// @system @ref LLP 0210 §4.5 / LLP 0381 P4 — tiny deterministic hydration
// capability primitive shared by the editable and generated runtimes without
// pulling the producer manifest implementation into the private P4 client.

/**
 * Deterministic request/root RNG shared by SSR capture and client adoption.
 */
export function createContractHydrationSeededRandom(
  seed: string,
): () => number {
  // FNV-1a string hash feeding mulberry32. Both stages use explicit uint32
  // arithmetic so server and hydration clients replay the same sequence.
  let state = 0x811c9dc5;
  for (let index = 0; index < seed.length; index += 1) {
    state ^= seed.charCodeAt(index);
    state = Math.imul(state, 0x01000193) >>> 0;
  }
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 0x1_0000_0000;
  };
}
