// @system @ref LLP 0157 §2, LLP 0195 §4.1, LLP 0373 phase 3c — the narrow
// global size-class projection. Contract `match size` consumes viewport plus
// app and agent token overrides; it must not resolve unrelated theme tokens.

import {
  getThemeOverride,
  subscribeThemeOverride,
} from '@exact/core/agent/experience-registry';

import {
  getAppThemeOverrides,
  subscribeFacetOverrides,
} from './facet-overrides.js';
import {
  getThemeViewportWidth,
  subscribeThemeViewportWidth,
} from './theme-host-inputs.js';
import {
  defaultSizeClasses,
  resolveSizeClassForWidth,
  type SizeClass,
  type SizeClassToken,
  type SizeClassTokens,
} from './size-class.js';

export type { SizeClass } from './size-class.js';

function mergeToken(
  base: SizeClassToken,
  override: unknown,
): SizeClassToken {
  return override && typeof override === 'object' && !Array.isArray(override)
    ? { ...base, ...(override as Partial<SizeClassToken>) }
    : base;
}

function applySizeClassOverride(
  base: SizeClassTokens,
  override: unknown,
): SizeClassTokens {
  if (!override || typeof override !== 'object' || Array.isArray(override)) return base;
  const sizeClasses = (override as { sizeClasses?: unknown }).sizeClasses;
  if (!sizeClasses || typeof sizeClasses !== 'object' || Array.isArray(sizeClasses)) return base;
  const values = sizeClasses as Partial<Record<SizeClass, unknown>>;
  return {
    compact: mergeToken(base.compact, values.compact),
    regular: mergeToken(base.regular, values.regular),
    expanded: mergeToken(base.expanded, values.expanded),
  };
}

export function resolveFacetSizeClass(viewportWidth = getThemeViewportWidth()): SizeClass {
  const appTokens = applySizeClassOverride(defaultSizeClasses, getAppThemeOverrides());
  const resolvedTokens = applySizeClassOverride(appTokens, getThemeOverride());
  return resolveSizeClassForWidth(viewportWidth, resolvedTokens);
}

export function subscribeFacetSizeClass(listener: () => void): () => void {
  const disposers = [
    subscribeThemeViewportWidth(listener),
    subscribeFacetOverrides(listener),
    subscribeThemeOverride(listener),
  ];
  return () => disposers.forEach((dispose) => dispose());
}
