// @system @ref LLP 0201 W1 / LLP 0202 H1, LLP 0373 phase 3c — direct-DOM
// canonical prop boundary. The DOM description consumes authored
// `originalProps` for semantics, accessibility, controls, events, and image
// materialization. Only image dynamic-range CSS and the LLP 0364 color-matrix
// filter still read `node.props`.

import type { CanonicalProps, CanonicalTagType } from '../types.js';
import { canonicalImageColorMatrixProp } from './image-color-matrix.js';
import { normalizeImageDynamicRange } from './image-dynamic-range.js';

export type ProductionWebPropsNormalizer = (
  tagType: CanonicalTagType,
  props: Record<string, unknown>,
  isRNStyle: boolean,
) => CanonicalProps;

const EMPTY_DIRECT_DOM_PROPS = Object.freeze({}) as CanonicalProps;

function normalizeDirectDomProps(
  tagType: CanonicalTagType,
  props: Record<string, unknown>,
): CanonicalProps {
  if (tagType !== 'image') return EMPTY_DIRECT_DOM_PROPS;
  const imageDynamicRange = normalizeImageDynamicRange(props.dynamicRange, props.hdr);
  const imageColorMatrix = canonicalImageColorMatrixProp(props.colorMatrix);
  if (imageDynamicRange === undefined && imageColorMatrix === undefined) {
    return EMPTY_DIRECT_DOM_PROPS;
  }
  return {
    ...(imageDynamicRange === undefined ? {} : { imageDynamicRange }),
    ...(imageColorMatrix === undefined ? {} : { imageColorMatrix }),
  };
}

let normalize: ProductionWebPropsNormalizer = normalizeDirectDomProps;

export function installProductionWebPropsNormalizer(
  next: ProductionWebPropsNormalizer,
): void {
  normalize = next;
}

export function normalizeProductionWebProps(
  tagType: CanonicalTagType,
  props: Record<string, unknown>,
  isRNStyle: boolean,
): CanonicalProps {
  return normalize(tagType, props, isRNStyle);
}

export function _resetProductionWebPropsNormalizerForTests(): void {
  normalize = normalizeDirectDomProps;
}
