// @system @ref LLP 0278 §2 item 3, §4 mode 1 — runtime contract monitor.
//
// Dev-only live verdicts for contract clauses the compiler can only check
// statically. The static analyzer proves what an action body's *source* can
// write (analyze.ts collectStateWrites); this monitor records what each
// invocation *actually* wrote (LLP 0231's action log) and fails the
// component's `action <name> writes <...>` clauses when an invocation's
// actual writes escape the declared set — the defense-in-depth layer for
// exactly the cases the static picture misses (opaque escapes, nested
// attribution, IR drift after hot-patching).
//
// Verdicts are queryable through the existing contract dataflow surface
// (getContractDataflowSnapshot include 'clauseVerdicts' → the
// exact_contract_dataflow agent op) and, per contract, through the
// `verdicts` hook toUiContract attaches when given a mounted instance.
// Production cost is zero: every entry point returns immediately outside
// dev mode (isContractDevMode, same gate as reactivity introspection).

import type { ElementNode, TextNode } from '@exact/renderer/host-ops';

import type {
  ContractAssertionClauseIR,
  ContractClauseIR,
  ContractSelectorIR,
} from '../compiler/ir.js';
import { printExpression } from '../compiler/expression-format.js';
import type { ComponentInstance } from './instance.js';
import type { ActionLogRecord } from './dataflow-inspector.js';
import { evalRuntimeExpr } from './execution.js';
import { isContractDevMode } from './provenance.js';
import { onFlush, untrack } from './signals.js';

export interface ContractActionWritesViolation {
  /** Action-log sequence number of the violating invocation. */
  seq: number;
  atMs: number;
  /** Every state the invocation actually wrote. */
  actualWrites: string[];
  /** The actual writes that escaped the clause's declared set. */
  undeclaredWrites: string[];
}

export interface ContractClauseVerdict {
  kind: 'action-writes';
  component: string;
  instanceId: string;
  action: string;
  /** The clause's declared writes list (the claim being checked). */
  declaredWrites: string[];
  invocations: number;
  violations: number;
  status: 'unchecked' | 'pass' | 'violated';
  lastViolation?: ContractActionWritesViolation;
}

// ---------------------------------------------------------------------------
// Cross-bundle state anchor (ENG-22560)
// ---------------------------------------------------------------------------
//
// The dev browser module graph can hold TWO copies of this module: the app
// graph (which mounts components and writes these registries) and the
// agent-relay bundle (which serves `POST /agent/contract-witness` and reads
// them) — vite dep-optimization duplicates @exact/contract between them.
// Module-local Maps split across the copies: the relay's copy stayed empty,
// so the witness op returned zero liveClauses on a fresh dev boot. Anchoring
// the state on `globalThis` (the same pattern as `__exactContractWitness`
// for the compile-time module witness) makes every copy read and write the
// same registries. The maps hold app-graph object identities; the reader
// only iterates them — the whole query path is duck-typed (no instanceof),
// so cross-copy objects are safe.

interface ContractMonitorSharedState {
  verdictsByInstance: Map<ComponentInstance, ContractClauseVerdict[]>;
  invariantWatchers: Set<InvariantWatcher>;
  clauseWitnessInstances: Map<ComponentInstance, ClauseWitnessRegistration>;
}

function contractMonitorSharedState(): ContractMonitorSharedState {
  const scope = globalThis as {
    __exactContractMonitorState?: ContractMonitorSharedState;
  };
  scope.__exactContractMonitorState ??= {
    verdictsByInstance: new Map(),
    invariantWatchers: new Set(),
    clauseWitnessInstances: new Map(),
  };
  return scope.__exactContractMonitorState;
}

const verdictsByInstance = contractMonitorSharedState().verdictsByInstance;

/**
 * Called by the dataflow inspector when an instance registers. Pre-creates
 * `unchecked` verdicts for the instance's action-writes clauses so they are
 * queryable before the first invocation. No-op for components without
 * monitor-checked clauses and outside dev mode.
 */
export function registerContractMonitorInstance(
  instance: ComponentInstance,
  instanceId: string,
): void {
  if (!isContractDevMode()) {
    return;
  }
  ensureVerdicts(instance, instanceId);
}

function ensureVerdicts(instance: ComponentInstance, instanceId: string): ContractClauseVerdict[] {
  let verdicts = verdictsByInstance.get(instance);
  if (verdicts) {
    return verdicts;
  }
  verdicts = [];
  for (const clause of instance.def.ir.contracts) {
    if (clause.kind === 'action-writes') {
      verdicts.push({
        kind: 'action-writes',
        component: instance.def.ir.name,
        instanceId,
        action: clause.action,
        declaredWrites: [...clause.writes],
        invocations: 0,
        violations: 0,
        status: 'unchecked',
      });
    }
  }
  if (verdicts.length === 0) {
    return verdicts;
  }
  verdictsByInstance.set(instance, verdicts);
  instance.owner.register(() => {
    verdictsByInstance.delete(instance);
  });
  return verdicts;
}

/**
 * Called by the dataflow inspector after every completed action invocation.
 * Checks the invocation's actual writes against every `action ... writes`
 * clause naming that action: the clause fails when actualWrites ⊄ declared.
 */
export function noteContractActionInvocation(
  instance: ComponentInstance,
  instanceId: string,
  log: ActionLogRecord,
): void {
  if (!isContractDevMode()) {
    return;
  }
  const verdicts = ensureVerdicts(instance, instanceId);
  for (const verdict of verdicts) {
    if (verdict.action !== log.action) {
      continue;
    }
    verdict.invocations += 1;
    const declared = new Set(verdict.declaredWrites);
    const actualWrites = log.actualWrites.map((write) => write.name);
    const undeclaredWrites = actualWrites.filter((name) => !declared.has(name));
    if (undeclaredWrites.length === 0) {
      if (verdict.status !== 'violated') {
        verdict.status = 'pass';
      }
      continue;
    }
    verdict.violations += 1;
    verdict.status = 'violated';
    verdict.lastViolation = {
      seq: log.seq,
      atMs: log.atMs,
      actualWrites,
      undeclaredWrites,
    };
    console.error('[contract] action-writes clause violated', {
      component: verdict.component,
      instanceId: verdict.instanceId,
      action: verdict.action,
      declaredWrites: verdict.declaredWrites,
      actualWrites,
      undeclaredWrites,
      seq: log.seq,
    });
  }
}

/** Clause verdicts for one mounted instance (the toUiContract verdict hook). */
export function getContractClauseVerdictsForInstance(
  instance: ComponentInstance,
): ContractClauseVerdict[] {
  return [...(verdictsByInstance.get(instance) ?? [])];
}

export interface ContractClauseVerdictQuery {
  component?: string;
}

/** All recorded clause verdicts, optionally filtered by component name. */
export function getContractClauseVerdicts(
  query: ContractClauseVerdictQuery = {},
): ContractClauseVerdict[] {
  const out: ContractClauseVerdict[] = [];
  for (const verdicts of verdictsByInstance.values()) {
    for (const verdict of verdicts) {
      if (query.component && verdict.component !== query.component) {
        continue;
      }
      out.push(verdict);
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// Passive invariants (LLP 0278 §4 mode 1)
// ---------------------------------------------------------------------------

export type ContractInvariantStatus = 'unchecked' | 'pass' | 'violated' | 'guard-false' | 'error';

export interface ContractInvariantRecord {
  component: string;
  /** Printed clause text — the invariant's identity for reporting. */
  clause: string;
  status: ContractInvariantStatus;
  checks: number;
  violations: number;
  lastViolation?: { atMs: number; detail: string };
  lastError?: string;
}

interface InvariantWatcher {
  component: string;
  records: ContractInvariantRecord[];
}

const invariantWatchers = contractMonitorSharedState().invariantWatchers;

type HostNode = ElementNode | TextNode;

function isTextNode(node: HostNode): node is TextNode {
  return 'text' in node && typeof (node as TextNode).text === 'string';
}

function nodeText(node: ElementNode): string {
  const out: string[] = [];
  const visit = (candidate: HostNode): void => {
    if (isTextNode(candidate)) {
      out.push(candidate.text);
      return;
    }
    candidate.children.forEach((child) => visit(child as HostNode));
  };
  node.children.forEach((child) => visit(child as HostNode));
  return out.join('');
}

function collectElements(roots: readonly HostNode[]): ElementNode[] {
  const out: ElementNode[] = [];
  const visit = (node: HostNode): void => {
    if (isTextNode(node)) {
      return;
    }
    out.push(node);
    node.children.forEach((child) => visit(child as HostNode));
  };
  roots.forEach(visit);
  return out;
}

function prop(node: ElementNode, name: string): unknown {
  return (node.originalProps as Record<string, unknown>)[name];
}

function nodeTestId(node: ElementNode): string | undefined {
  const value = prop(node, 'testId') ?? prop(node, 'testID');
  return typeof value === 'string' ? value : undefined;
}

function nodeLabel(node: ElementNode): string | undefined {
  const label = prop(node, 'label') ?? prop(node, 'accessibilityLabel') ?? prop(node, 'aria-label');
  return typeof label === 'string' ? label : undefined;
}

function nodeRole(node: ElementNode): string | undefined {
  // Contract lowering renames the authored `role` attr to `accessibilityRole`
  // and stamps lowered tags with static roles (`button` -> Pressable +
  // accessibilityRole 'button'), so the committed tree carries the role as
  // accessibilityRole, not the authored spelling (builtin-schema.ts).
  const role = prop(node, 'role') ?? prop(node, 'accessibilityRole');
  if (typeof role === 'string') {
    return role;
  }
  switch (node.originalTag) {
    case 'button':
      return 'button';
    case 'toggle':
    case 'Toggle':
      return 'switch';
    case 'section':
      return 'group';
    default:
      return undefined;
  }
}

/** Semantic tag stamped by the Contract lowering (`__exactSemanticTag`). */
function nodeSemanticTag(node: ElementNode): string | undefined {
  const value = prop(node, '__exactSemanticTag');
  return typeof value === 'string' ? value : undefined;
}

/**
 * In-process selector matcher over the committed host-ops tree — the
 * dev-runtime approximation of the agent find op's semantics (visibility is
 * presence in the committed tree; labels come from label/accessibilityLabel;
 * text matches the deepest element whose subtree text equals the value).
 */
function matchSelector(elements: readonly ElementNode[], selector: ContractSelectorIR): ElementNode[] {
  const { testId, testIdPrefix } = (() => {
    if (selector.testId === undefined) {
      return { testId: undefined, testIdPrefix: undefined };
    }
    return selector.testId.startsWith('^')
      ? { testId: undefined, testIdPrefix: selector.testId.slice(1) }
      : { testId: selector.testId, testIdPrefix: undefined };
  })();

  const base = elements.filter((node) => {
    if (testId !== undefined && nodeTestId(node) !== testId) return false;
    if (testIdPrefix !== undefined) {
      const id = nodeTestId(node);
      if (typeof id !== 'string' || !id.startsWith(testIdPrefix)) return false;
    }
    if (selector.label !== undefined && nodeLabel(node) !== selector.label) return false;
    return true;
  });

  switch (selector.kind) {
    case 'button': {
      const buttons = base.filter((node) => nodeRole(node) === 'button');
      if (selector.value === undefined) return buttons;
      return buttons.filter(
        (node) => nodeLabel(node) === selector.value || nodeText(node) === selector.value,
      );
    }
    case 'text': {
      if (selector.value === undefined) {
        return base.filter((node) => nodeText(node).length > 0);
      }
      const matching = base.filter((node) => nodeText(node) === selector.value);
      // Deepest-match only: drop elements with a matching descendant so a
      // wrapping column around one text node does not double-count.
      return matching.filter(
        (node) => !matching.some((other) => other !== node && isAncestor(node, other)),
      );
    }
    case 'section':
      return base.filter(
        (node) =>
          (nodeRole(node) === 'group' ||
            node.originalTag === 'section' ||
            nodeSemanticTag(node) === 'section') &&
          (selector.value === undefined || nodeLabel(node) === selector.value),
      );
    case 'spinner':
      // Contract lowering: spinner -> View + accessibilityRole 'progressbar'.
      return base.filter(
        (node) => node.originalTag === 'spinner' || nodeRole(node) === 'progressbar',
      );
    case 'input':
      // Contract lowering: input -> TextInput.
      return base.filter(
        (node) => node.originalTag === 'input' || node.originalTag === 'TextInput',
      );
    case 'toggle':
      // Contract lowering: toggle -> Toggle.
      return base.filter(
        (node) => node.originalTag === 'toggle' || node.originalTag === 'Toggle',
      );
    case 'node':
      return base.filter(
        (node) => selector.role === undefined || nodeRole(node) === selector.role,
      );
    case 'item':
    default:
      return base;
  }
}

function isAncestor(candidate: ElementNode, descendant: ElementNode): boolean {
  let parent = descendant.parent;
  while (parent) {
    if (parent === candidate) {
      return true;
    }
    parent = parent.parent;
  }
  return false;
}

function isDisabled(node: ElementNode): boolean {
  return prop(node, 'disabled') === true || prop(node, 'accessibilityDisabled') === true;
}

function isChecked(node: ElementNode): boolean {
  return (
    prop(node, 'checked') === true ||
    ((node.originalTag === 'toggle' || node.originalTag === 'Toggle') &&
      prop(node, 'value') === true)
  );
}

type InvariantOutcome =
  | { kind: 'pass' }
  | { kind: 'guard-false' }
  | { kind: 'violated'; detail: string };

function checkAssertionClause(
  clause: ContractAssertionClauseIR,
  elements: readonly ElementNode[],
  instance: ComponentInstance,
): InvariantOutcome {
  const matches = matchSelector(elements, clause.selector);
  switch (clause.kind) {
    case 'has':
      return matches.length > 0
        ? { kind: 'pass' }
        : { kind: 'violated', detail: 'expected at least one match, found none' };
    case 'missing':
      return matches.length === 0
        ? { kind: 'pass' }
        : { kind: 'violated', detail: `expected no matches, found ${matches.length}` };
    case 'count': {
      const expected =
        clause.expected.kind === 'number'
          ? clause.expected.value
          : untrack(() => evalRuntimeExpr(clause.expected, instance.scope));
      if (typeof expected !== 'number' || !Number.isFinite(expected)) {
        return {
          kind: 'violated',
          detail: `count expression evaluated to ${JSON.stringify(expected)}, not a finite number`,
        };
      }
      return matches.length === expected
        ? { kind: 'pass' }
        : { kind: 'violated', detail: `expected ${expected} match(es), found ${matches.length}` };
    }
    case 'state': {
      // `hidden` is an absence claim over the committed tree, aligned with
      // Phase A's missing-lowering (issues/20260722-contract-verification-
      // evidence-defects.md defect 2): zero matches PASS — the clause is
      // satisfiable — and it must be judged before the exactly-one-match
      // gate below, which would otherwise fail absence as "not found".
      if (clause.state === 'hidden') {
        return matches.length === 0
          ? { kind: 'pass' }
          : {
              kind: 'violated',
              detail: `expected hidden, found ${matches.length} present node(s)`,
            };
      }
      if (matches.length !== 1) {
        return {
          kind: 'violated',
          detail:
            matches.length === 0
              ? 'state target was not found'
              : `state target is ambiguous (${matches.length} matches)`,
        };
      }
      const node = matches[0]!;
      switch (clause.state) {
        case 'enabled':
          return isDisabled(node)
            ? { kind: 'violated', detail: 'expected enabled, node is disabled' }
            : { kind: 'pass' };
        case 'disabled':
          return isDisabled(node)
            ? { kind: 'pass' }
            : { kind: 'violated', detail: 'expected disabled, node is enabled' };
        case 'checked':
          return isChecked(node)
            ? { kind: 'pass' }
            : { kind: 'violated', detail: 'expected checked, node is unchecked' };
        case 'unchecked':
          return isChecked(node)
            ? { kind: 'violated', detail: 'expected unchecked, node is checked' }
            : { kind: 'pass' };
        case 'visible':
          // Present in the committed tree — the strongest visibility fact
          // this structural monitor can attest (geometry is Phase A's job).
          return { kind: 'pass' };
      }
    }
  }
}

function checkInvariantClause(
  clause: ContractClauseIR,
  elements: readonly ElementNode[],
  instance: ComponentInstance,
): InvariantOutcome {
  if (clause.kind === 'when') {
    const guard = untrack(() => evalRuntimeExpr(clause.test, instance.scope));
    if (!guard) {
      return { kind: 'guard-false' };
    }
    return checkInvariantClause(clause.clause, elements, instance);
  }
  if (
    clause.kind === 'has' ||
    clause.kind === 'missing' ||
    clause.kind === 'count' ||
    clause.kind === 'state'
  ) {
    return checkAssertionClause(clause, elements, instance);
  }
  return { kind: 'violated', detail: `invariant cannot check clause kind "${clause.kind}"` };
}

export interface WatchContractInvariantsOptions {
  instance: ComponentInstance;
  /** The mounted top-level host nodes the invariants are scoped to. */
  hostNodes: () => readonly unknown[];
}

/**
 * Watches a mounted instance's `invariant` clauses: checks them once
 * immediately and after every settled flush, records per-clause status, and
 * console.errors a structured payload on the transition into `violated`
 * (throttled — repeat violating flushes do not re-report). Returns a stop
 * function. No-op (returns a no-op stop) outside dev mode or for components
 * without invariant clauses — production cost is zero.
 */
export function watchContractInvariants(options: WatchContractInvariantsOptions): () => void {
  if (!isContractDevMode()) {
    return () => {};
  }
  const { instance } = options;
  const invariants = instance.def.ir.contracts.filter(
    (clause): clause is ContractClauseIR & { kind: 'invariant' } => clause.kind === 'invariant',
  );
  if (invariants.length === 0) {
    return () => {};
  }

  const component = instance.def.ir.name;
  const watcher: InvariantWatcher = {
    component,
    records: invariants.map((clause) => ({
      component,
      clause: printInvariantClause(clause.clause),
      status: 'unchecked',
      checks: 0,
      violations: 0,
    })),
  };
  invariantWatchers.add(watcher);

  const check = (): void => {
    const elements = collectElements(options.hostNodes() as HostNode[]);
    invariants.forEach((clause, index) => {
      const record = watcher.records[index]!;
      record.checks += 1;
      let outcome: InvariantOutcome;
      try {
        outcome = checkInvariantClause(clause.clause, elements, instance);
      } catch (error) {
        record.status = 'error';
        record.lastError = error instanceof Error ? error.message : String(error);
        return;
      }
      if (outcome.kind === 'guard-false') {
        if (record.status !== 'violated') {
          record.status = 'guard-false';
        }
        return;
      }
      if (outcome.kind === 'pass') {
        if (record.status !== 'violated') {
          record.status = 'pass';
        }
        return;
      }
      record.violations += 1;
      const firstViolation = record.status !== 'violated';
      record.status = 'violated';
      record.lastViolation = { atMs: Date.now(), detail: outcome.detail };
      if (firstViolation) {
        console.error('[contract] invariant violated', {
          component,
          invariant: record.clause,
          detail: outcome.detail,
          checks: record.checks,
        });
      }
    });
  };

  // Initial check against the first committed tree, then after every flush.
  check();
  const stopFlush = onFlush(check);
  const stop = (): void => {
    stopFlush();
    invariantWatchers.delete(watcher);
  };
  instance.owner.register(stop);
  return stop;
}

function printInvariantClause(clause: ContractClauseIR): string {
  switch (clause.kind) {
    case 'has':
      return `has ${printSelector(clause.selector)}`;
    case 'missing':
      return `missing ${printSelector(clause.selector)}`;
    case 'count':
      return `count ${printSelector(clause.selector)} = ${printExpression(clause.expected)}`;
    case 'state':
      return `state ${printSelector(clause.selector)} is ${clause.state}`;
    case 'when':
      return `when ${printExpression(clause.test)} then ${printInvariantClause(clause.clause)}`;
    default:
      return clause.kind;
  }
}

function printSelector(selector: ContractSelectorIR): string {
  let text = selector.kind;
  if (selector.value !== undefined) text += ` ${JSON.stringify(selector.value)}`;
  if (selector.label !== undefined) text += ` label=${JSON.stringify(selector.label)}`;
  if (selector.testId !== undefined) text += ` testId=${JSON.stringify(selector.testId)}`;
  if (selector.role !== undefined) text += ` role=${JSON.stringify(selector.role)}`;
  return text;
}

export interface ContractInvariantQuery {
  component?: string;
}

/** All live invariant records, optionally filtered by component name. */
export function getContractInvariantRecords(
  query: ContractInvariantQuery = {},
): ContractInvariantRecord[] {
  const out: ContractInvariantRecord[] = [];
  for (const watcher of invariantWatchers) {
    if (query.component && watcher.component !== query.component) {
      continue;
    }
    out.push(...watcher.records.map((record) => ({ ...record })));
  }
  return out;
}

// ---------------------------------------------------------------------------
// Live clause witness (LLP 0293 ledger row 8)
// ---------------------------------------------------------------------------
//
// On-demand clause results for a mounted component's whole `contract` block,
// checked in-process against the committed host-ops tree — the read-only
// twin of the Phase A verifier for the `exact_contract_witness` agent op.
// Assertion clauses (has/missing/count/state, `when`-guarded or not) run the
// same matcher the passive invariants use; press/change clauses witness that
// the target is present and the routed action resolves on the live instance
// (no interaction is performed — the op stays side-effect free);
// action-writes clauses report the monitor's recorded verdicts; clause kinds
// the compiler alone enforces report `static`.

export type ContractClauseWitnessStatus =
  | 'pass'
  | 'violated'
  | 'guard-false'
  | 'unchecked'
  | 'static'
  | 'error';

export interface ContractClauseWitnessResult {
  kind: ContractClauseIR['kind'];
  /** Printed clause text — the claim's identity for reporting. */
  clause: string;
  status: ContractClauseWitnessStatus;
  detail?: string;
}

export interface ContractComponentClauseWitness {
  component: string;
  sourcePath?: string;
  clauseCount: number;
  results: ContractClauseWitnessResult[];
}

export interface ContractClauseWitnessQuery {
  component?: string;
}

interface ClauseWitnessRegistration {
  instance: ComponentInstance;
  hostNodes: () => readonly unknown[];
}

const clauseWitnessInstances = contractMonitorSharedState().clauseWitnessInstances;

/**
 * Registers a mounted instance (and its committed subtree accessor) for
 * on-demand clause witnessing. Called by mount (root instances) and the view
 * runtime (component-call instances). No-op outside dev mode and for
 * components without a `contract` block — production cost is zero.
 */
export function registerContractClauseWitnessInstance(
  instance: ComponentInstance,
  hostNodes: () => readonly unknown[],
): void {
  if (!isContractDevMode()) {
    return;
  }
  if (instance.def.ir.contracts.length === 0 || clauseWitnessInstances.has(instance)) {
    return;
  }
  clauseWitnessInstances.set(instance, { instance, hostNodes });
  instance.owner.register(() => {
    clauseWitnessInstances.delete(instance);
  });
}

function witnessOutcome(outcome: InvariantOutcome): {
  status: ContractClauseWitnessStatus;
  detail?: string;
} {
  switch (outcome.kind) {
    case 'pass':
      return { status: 'pass' };
    case 'guard-false':
      return { status: 'guard-false', detail: 'guard evaluated false; inner clause not checked' };
    case 'violated':
      return { status: 'violated', detail: outcome.detail };
  }
}

function checkWitnessClause(
  clause: ContractClauseIR,
  elements: readonly ElementNode[],
  instance: ComponentInstance,
): { status: ContractClauseWitnessStatus; detail?: string } {
  switch (clause.kind) {
    case 'has':
    case 'missing':
    case 'count':
    case 'state':
      return witnessOutcome(checkAssertionClause(clause, elements, instance));
    case 'when': {
      const guard = untrack(() => evalRuntimeExpr(clause.test, instance.scope));
      if (!guard) {
        return { status: 'guard-false', detail: 'guard evaluated false; inner clause not checked' };
      }
      return checkWitnessClause(clause.clause, elements, instance);
    }
    case 'invariant':
      return checkWitnessClause(clause.clause, elements, instance);
    case 'press':
    case 'change': {
      const matches = matchSelector(elements, clause.selector);
      if (matches.length === 0) {
        return {
          status: 'violated',
          detail: 'target selector matched no elements in the committed tree',
        };
      }
      if (clause.action && !instance.scope.lookup(clause.action)) {
        return {
          status: 'violated',
          detail: `action "${clause.action}" does not resolve on the mounted instance`,
        };
      }
      return {
        status: 'pass',
        detail: clause.action
          ? `target present; action "${clause.action}" resolves (interaction not performed)`
          : 'target present (interaction not performed)',
      };
    }
    case 'action-writes': {
      const verdict = (verdictsByInstance.get(instance) ?? []).find(
        (candidate) => candidate.action === clause.action,
      );
      if (!verdict || verdict.status === 'unchecked') {
        return { status: 'unchecked', detail: 'no invocations recorded yet' };
      }
      if (verdict.status === 'violated') {
        return {
          status: 'violated',
          detail: `undeclared writes: ${verdict.lastViolation?.undeclaredWrites.join(', ') ?? 'unknown'}`,
        };
      }
      return { status: 'pass', detail: `${verdict.invocations} invocation(s) checked` };
    }
    case 'navigate':
    case 'exits':
    case 'derive-depends':
      return { status: 'static', detail: 'compiler-enforced clause; no live check' };
  }
}

function printWitnessClause(clause: ContractClauseIR): string {
  switch (clause.kind) {
    case 'has':
    case 'missing':
    case 'count':
    case 'state':
    case 'when':
      return printInvariantClause(clause);
    case 'press':
      return `press ${printSelector(clause.selector)}${
        clause.action ? ` -> ${clause.action}` : clause.navigate ? ` -> navigate` : ''
      }`;
    case 'change':
      return `change ${printSelector(clause.selector)} -> ${clause.action}`;
    case 'action-writes':
      return `action ${clause.action} writes ${clause.writes.join(', ')}`;
    case 'derive-depends':
      return `derive ${clause.derive} depends only on ${clause.deps.join(', ')}`;
    case 'navigate':
      return `navigate ${printExpression(clause.target)}`;
    case 'exits':
      return `exits${clause.only ? ' only' : ''} ${clause.targets.map(printExpression).join(', ')}`;
    case 'invariant':
      return `invariant ${printWitnessClause(clause.clause)}`;
    default:
      return (clause as { kind: string }).kind;
  }
}

/**
 * Runs every clause of every registered mounted instance (optionally
 * filtered by component name) against the live committed tree and returns
 * per-clause results. Read-only: no interaction is performed and nothing is
 * recorded. Returns [] outside dev mode.
 */
export function getContractClauseWitness(
  query: ContractClauseWitnessQuery = {},
): ContractComponentClauseWitness[] {
  if (!isContractDevMode()) {
    return [];
  }
  const out: ContractComponentClauseWitness[] = [];
  for (const registration of clauseWitnessInstances.values()) {
    const { instance } = registration;
    if (query.component && instance.def.ir.name !== query.component) {
      continue;
    }
    const elements = collectElements(registration.hostNodes() as HostNode[]);
    const results = instance.def.ir.contracts.map((clause): ContractClauseWitnessResult => {
      let checked: { status: ContractClauseWitnessStatus; detail?: string };
      try {
        checked = checkWitnessClause(clause, elements, instance);
      } catch (error) {
        checked = {
          status: 'error',
          detail: error instanceof Error ? error.message : String(error),
        };
      }
      return {
        kind: clause.kind,
        clause: printWitnessClause(clause),
        ...checked,
      };
    });
    out.push({
      component: instance.def.ir.name,
      sourcePath: instance.def.file.sourcePath,
      clauseCount: results.length,
      results,
    });
  }
  return out;
}

export function resetContractMonitorForTests(): void {
  verdictsByInstance.clear();
  invariantWatchers.clear();
  clauseWitnessInstances.clear();
}
