// @system @ref LLP 0373 P0; LLP 0179 §8 minimum logical-identity contract —
// logical query identity: the four-position key (opaque provider/authority
// partition, stable descriptor identity, compatibility token, canonicalized
// arguments) that keyed query scopes deduplicate and fence on.
//
// All four positions are load-bearing (LLP 0373 §4 P0):
// - the PARTITION isolates provider instance / store / tenant / root /
//   authority context without exposing raw identity — descriptor+args alone
//   would deduplicate identical arguments ACROSS providers or users;
// - the DESCRIPTOR IDENTITY keeps distinct queries with identical arguments
//   distinct (Partitime's eventDetails/eventWall/guestList all key by the
//   same `{eventId}`);
// - the COMPATIBILITY TOKEN versions the descriptor's meaning so an
//   incompatible descriptor change never aliases a live key (mint/bump rules
//   belong to the LLP 0179 §8 declaration home; default "1");
// - CANONICALIZED ARGUMENTS make equivalent encodings one key and
//   non-equivalent ones distinct (no type coercion).

import type { ContractDataProvider, DataQueryDescriptor } from './data-provider.js';

// ---------------------------------------------------------------------------
// Argument canonicalization
// ---------------------------------------------------------------------------

/**
 * Typed failure for arguments that cannot participate in logical query
 * identity. Callers surface it as a structured diagnostic through the query
 * cell error state (LLP 0373 P0: invalid arguments never throw uncaught
 * through the binding path — the dedup layer catches this and delivers a
 * `DataProviderDiagnostic`-shaped refusal).
 */
export class QueryArgsCanonicalizationError extends Error {
  readonly code = 'contract_query_args_invalid';
  /** JSON-pointer-ish path of the offending value (`$`, `$.filter`, `$.ids[2]`). */
  readonly path: string;

  constructor(message: string, path: string) {
    super(`invalid query arguments at ${path}: ${message}`);
    this.name = 'QueryArgsCanonicalizationError';
    this.path = path;
  }
}

function isPlainObject(value: object): boolean {
  const proto: unknown = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function canonicalize(value: unknown, path: string, seen: Set<object>): string {
  switch (typeof value) {
    case 'string':
    case 'boolean':
      return JSON.stringify(value);
    case 'number': {
      if (!Number.isFinite(value)) {
        throw new QueryArgsCanonicalizationError(
          `non-finite number ${String(value)} cannot be part of query identity`,
          path,
        );
      }
      // -0 normalizes to 0 (JSON has no -0; Object.is keeps the check exact).
      return JSON.stringify(Object.is(value, -0) ? 0 : value);
    }
    case 'undefined':
      throw new QueryArgsCanonicalizationError(
        'undefined is droppable only in object-property position (absent == undefined); it cannot appear here',
        path,
      );
    case 'object':
      break;
    default:
      // function / symbol / bigint: no coercion — refuse.
      throw new QueryArgsCanonicalizationError(
        `${typeof value} values cannot be part of query identity`,
        path,
      );
  }
  if (value === null) {
    return 'null';
  }
  const objectValue = value as object;
  if (seen.has(objectValue)) {
    throw new QueryArgsCanonicalizationError('circular reference', path);
  }
  seen.add(objectValue);
  try {
    if (Array.isArray(objectValue)) {
      const parts: string[] = [];
      for (let index = 0; index < objectValue.length; index += 1) {
        const element: unknown = objectValue[index];
        if (element === undefined) {
          // Positional: an undefined element cannot be dropped without
          // shifting its siblings, and null-coercion would alias `[null]`.
          throw new QueryArgsCanonicalizationError(
            'undefined array elements cannot be part of query identity',
            `${path}[${index}]`,
          );
        }
        parts.push(canonicalize(element, `${path}[${index}]`, seen));
      }
      return `[${parts.join(',')}]`;
    }
    if (!isPlainObject(objectValue)) {
      // Date/Map/class instances would all canonicalize to "{}" and alias
      // each other — refuse rather than coerce (deterministic, no surprises).
      throw new QueryArgsCanonicalizationError(
        'only plain objects, arrays, and JSON scalars can be part of query identity',
        path,
      );
    }
    const record = objectValue as Record<string, unknown>;
    const parts: string[] = [];
    for (const key of Object.keys(record).sort()) {
      const propertyValue = record[key];
      if (propertyValue === undefined) {
        // Absent == undefined: `{ a: 1 }` and `{ a: 1, b: undefined }` are
        // one identity.
        continue;
      }
      parts.push(`${JSON.stringify(key)}:${canonicalize(propertyValue, `${path}.${key}`, seen)}`);
    }
    return `{${parts.join(',')}}`;
  } finally {
    seen.delete(objectValue);
  }
}

/**
 * Deterministic canonical JSON for query arguments: object keys sorted
 * lexicographically, `undefined`-valued properties dropped (absent ==
 * undefined), arrays positional, numbers finite with -0 normalized to 0,
 * strings/booleans/null as-is, nested structures recursive. No type
 * coercion — `1` and `"1"` stay distinct. Throws
 * `QueryArgsCanonicalizationError` on values that cannot carry identity.
 */
export function canonicalizeQueryArgs(args: unknown): string {
  return canonicalize(args, '$', new Set());
}

// ---------------------------------------------------------------------------
// Logical query key
// ---------------------------------------------------------------------------

/** The four-position logical query identity (LLP 0373 §4 P0 layer 2). */
export interface LogicalQueryKey {
  /** Opaque provider/authority partition (minted per provider instance or declared via `partitionId()`). */
  partition: string;
  /** Stable descriptor identity at rest — the manifest query name (v1). */
  descriptorId: string;
  /** Descriptor compatibility version (LLP 0179 §8 mint/bump rules; default "1"). */
  compatibilityToken: string;
  /** `canonicalizeQueryArgs` output. */
  canonicalArgs: string;
}

/**
 * Stable joined encoding of a logical key. JSON-array framing so field
 * contents can never collide across positions (no separator injection).
 */
export function logicalQueryKeyString(key: LogicalQueryKey): string {
  return JSON.stringify([key.partition, key.descriptorId, key.compatibilityToken, key.canonicalArgs]);
}

/**
 * Descriptor identity v1 — the versioned pair (LLP 0373 P0): `descriptorId`
 * is the manifest query name (stable at rest in the generated manifest);
 * `compatibilityToken` comes from the descriptor's optional
 * `compatibilityToken` field (additive, manifest-v2-compatible) and defaults
 * to "1".
 */
export function descriptorQueryIdentity(
  queryName: string,
  descriptor: DataQueryDescriptor | undefined,
): { descriptorId: string; compatibilityToken: string } {
  return {
    descriptorId: queryName,
    compatibilityToken: descriptor?.compatibilityToken ?? '1',
  };
}

// ---------------------------------------------------------------------------
// Partition minting and rotation
// ---------------------------------------------------------------------------

const mintedPartitions = new WeakMap<ContractDataProvider, string>();
let partitionSeq = 0;

function mintPartition(): string {
  // Counter for uniqueness within the session; unguessable suffix so a
  // partition id never encodes (or lets callers forge) raw provider
  // identity across sessions.
  const suffix =
    Math.random().toString(36).slice(2, 10) + Math.random().toString(36).slice(2, 10);
  partitionSeq += 1;
  return `pk${partitionSeq}:${suffix}`;
}

/**
 * The opaque partition for a provider instance: the provider's declared
 * `partitionId()` when present (authorization/tenant-aware providers own
 * their partition), otherwise an instance-minted opaque id. Two provider
 * instances with the same descriptor+args never share a partition.
 */
export function providerPartitionId(provider: ContractDataProvider): string {
  const declared = provider.partitionId?.();
  if (typeof declared === 'string' && declared.length > 0) {
    // Namespaced so a declared id can never collide with a minted one.
    return `declared:${declared}`;
  }
  let minted = mintedPartitions.get(provider);
  if (minted === undefined) {
    minted = mintPartition();
    mintedPartitions.set(provider, minted);
  }
  return minted;
}

export type PartitionRotationListener = (provider: ContractDataProvider) => void;

const rotationListeners = new Set<PartitionRotationListener>();

/**
 * Observe partition rotations. The dedup layer (query-dedup.ts) registers
 * here so `rotatePartition` can atomically fence-and-resubscribe active
 * logical subscriptions without a circular import.
 */
export function onPartitionRotation(listener: PartitionRotationListener): () => void {
  rotationListeners.add(listener);
  return () => {
    rotationListeners.delete(listener);
  };
}

/**
 * Rotate a provider instance's partition (authorization or provider
 * reconfiguration change — LLP 0373 P0). Mints a fresh opaque partition for
 * minted-partition providers (declared `partitionId()` providers re-read
 * their declaration), then synchronously notifies rotation listeners so the
 * dedup layer fences old-partition delivery (fail-closed: retained rows
 * from a prior partition are never delivered after rotation) and
 * resubscribes under the new partition. Returns the new partition id.
 */
export function rotatePartition(provider: ContractDataProvider): string {
  mintedPartitions.set(provider, mintPartition());
  for (const listener of [...rotationListeners]) {
    listener(provider);
  }
  return providerPartitionId(provider);
}

/**
 * Assemble the full logical key for a provider query. Throws
 * `QueryArgsCanonicalizationError` when the arguments cannot carry identity
 * (callers on the binding path catch and surface a structured diagnostic).
 */
export function providerLogicalQueryKey(
  provider: ContractDataProvider,
  queryName: string,
  args: Record<string, unknown>,
): LogicalQueryKey {
  const identity = descriptorQueryIdentity(queryName, provider.manifest?.queries?.[queryName]);
  return {
    partition: providerPartitionId(provider),
    descriptorId: identity.descriptorId,
    compatibilityToken: identity.compatibilityToken,
    canonicalArgs: canonicalizeQueryArgs(args),
  };
}
