import {
  hostCallOperationId,
  type HostCallOperationId,
} from './host-call-operations.generated.js';

export type {
  HostCallOperationId,
  HostCallOperationName,
  HostCallRuntimeContext,
} from './host-call-operations.generated.js';
export {
  HOST_CALL_ENDOWMENTS,
  HOST_CALL_OPERATION_IDS,
  HOST_CALL_OPERATION_NAMES,
  hostCallOperationId,
} from './host-call-operations.generated.js';

/** The CapSec-admitted binary host ingress installed on an Exact runtime. */
export interface ExactTypedHostIngress {
  invokeHostAsync(
    operationId: HostCallOperationId,
    payload: Uint8Array,
  ): Promise<Uint8Array>;
}

export type ExactHostCallAsyncBridge = (
  operation: string,
  argsJson: string,
) => Promise<unknown>;

type TypedInvokeHostAsync = ExactTypedHostIngress['invokeHostAsync'];

let cachedTypedIngress: ExactTypedHostIngress | null = null;
let cachedTypedInvoke: TypedInvokeHostAsync | null = null;
let cachedTypedAdapter: ExactHostCallAsyncBridge | null = null;
let hostCallTextEncoder: TextEncoder | null = null;
let hostCallTextDecoder: TextDecoder | null = null;

function encodeHostCallPayload(json: string): Uint8Array {
  hostCallTextEncoder ??= new TextEncoder();
  return hostCallTextEncoder.encode(json);
}

function decodeHostCallResult(result: Uint8Array): unknown {
  if (!(result instanceof Uint8Array)) {
    throw new TypeError('exact.invokeHostAsync must resolve to Uint8Array');
  }
  hostCallTextDecoder ??= new TextDecoder();
  return JSON.parse(hostCallTextDecoder.decode(result)) as unknown;
}

/** Return the raw, numeric/binary CapSec ingress when the host installed it. */
export function typedHostIngress(): ExactTypedHostIngress | null {
  const exact = (
    globalThis as { exact?: Partial<ExactTypedHostIngress> }
  ).exact;
  return exact && typeof exact.invokeHostAsync === 'function'
    ? exact as ExactTypedHostIngress
    : null;
}

/**
 * Adapt the numeric/binary ingress to the existing string/JSON call shape.
 * The adapter is stable for the lifetime of one installed host function so
 * caches that key by bridge identity survive repeated lookups.
 */
export function typedHostCallAsyncBridge(): ExactHostCallAsyncBridge | null {
  const ingress = typedHostIngress();
  if (!ingress) return null;
  if (
    cachedTypedAdapter
    && cachedTypedIngress === ingress
    && cachedTypedInvoke === ingress.invokeHostAsync
  ) {
    return cachedTypedAdapter;
  }

  cachedTypedIngress = ingress;
  cachedTypedInvoke = ingress.invokeHostAsync;
  cachedTypedAdapter = (operation, argsJson) => {
    const operationId = hostCallOperationId(operation);
    if (typeof operationId === 'undefined') {
      return Promise.reject(
        new Error(
          `Unknown Exact host operation "${operation}"; add it to `
            + 'packages/exact-core/host-call-operations.json',
        ),
      );
    }
    try {
      return Promise.resolve(
        ingress.invokeHostAsync(operationId, encodeHostCallPayload(argsJson)),
      ).then(decodeHostCallResult);
    } catch (error) {
      return Promise.reject(error);
    }
  };
  return cachedTypedAdapter;
}

/**
 * Shared helper for looking up the legacy generic sync diagnostic bridge.
 */

export function hostCallBridge():
  | ((operation: string, argsJson: string) => unknown)
  | null {
  const hostCall = (
    globalThis as {
      __hostCall?: ((operation: string, argsJson: string) => unknown) | undefined;
    }
  ).__hostCall;

  return typeof hostCall === 'function' ? hostCall : null;
}

/**
 * Explicit access to the legacy generic promise bridge. Armed runtimes do not
 * receive this global; it remains available only to diagnostic/unarmed hosts
 * during migration and to test harnesses that intentionally install it.
 */
export function diagnosticHostCallAsyncBridge(): ExactHostCallAsyncBridge | null {
  const hostCallAsync = (
    globalThis as {
      __hostCallAsync?:
        | ((operation: string, argsJson: string) => Promise<unknown>)
        | undefined;
    }
  ).__hostCallAsync;

  return typeof hostCallAsync === 'function' ? hostCallAsync : null;
}

/**
 * Async host-call transport. Prefer the typed numeric/binary Exact ingress;
 * fall back to the explicitly diagnostic generic global only when no typed
 * ingress is installed.
 */
export function hostCallAsyncBridge(): ExactHostCallAsyncBridge | null {
  return typedHostCallAsyncBridge() ?? diagnosticHostCallAsyncBridge();
}

/**
 * Async-first host call: prefers `exact.invokeHostAsync`, then the explicit
 * diagnostic/unarmed `__hostCallAsync` fallback, and finally the legacy sync
 * bridge on old single-threaded hosts. Returns `null` when no bridge exists.
 */
export function hostCallAsync(
  operation: string,
  argsJson?: string,
): Promise<unknown> | null {
  const asyncBridge = hostCallAsyncBridge();
  if (asyncBridge) {
    return asyncBridge(operation, argsJson ?? '{}');
  }
  const syncBridge = hostCallBridge();
  if (!syncBridge) {
    return null;
  }
  try {
    return Promise.resolve(syncBridge(operation, argsJson ?? '{}'));
  } catch (error) {
    return Promise.reject(error);
  }
}

/**
 * Options for {@link hostCallOptional}.
 */
export interface HostCallOptionalOptions {
  /** Label used in the dev-only degradation warning (defaults to the op name). */
  label?: string;
  /** Suppress the dev-only warning entirely (for reads expected to be absent). */
  silent?: boolean;
}

const warnedDegradedHostCalls = new Set<string>();

function isProductionHostEnvironment(): boolean {
  // Mirror desktop-platform.ts's capability gate: only a build that explicitly
  // sets NODE_ENV=production is treated as production (release HBC bundles do).
  // Dev/undefined environments get the warning so a swallowed error is visible.
  const nodeEnv = (
    globalThis as { process?: { env?: Record<string, string | undefined> } }
  ).process?.env?.NODE_ENV;
  return nodeEnv === 'production';
}

function describeHostCallError(error: unknown): string {
  if (error instanceof Error && typeof error.message === 'string') {
    return error.message;
  }
  try {
    return String(error);
  } catch {
    return '<unstringifiable error>';
  }
}

/**
 * Passive/nullable variant of the host-call bridge for reads that may run at
 * module-init on a platform that does NOT implement the capability.
 *
 * Calling `__hostCall` directly THROWS when the host answers a
 * `desktop.*`/platform-specific op with an error (the native host encodes an
 * error as a `-`-prefixed string, which the engine raises as a `JSError`). If
 * that throw is unhandled during module evaluation it aborts the whole native
 * entry module graph before first render — the ENG-22813 failure mode that
 * silently broke every non-home iOS route for ~8 days and left the agent
 * server unbound. `hostCallOptional` CATCHES the throw and returns `undefined`,
 * so a missing platform capability degrades to "no value" instead of crashing
 * startup (ENG-22821).
 *
 * This is deliberately NOT a global "swallow every host-call error" switch.
 * `unimplemented` is not distinguishable from a genuine runtime error at this
 * boundary: both arrive as a thrown `Error` whose only differentiator is a
 * host-defined message string (e.g. iOS returns
 * `"Desktop window snapshots are only implemented on macOS"`). Message-sniffing
 * would be fragile — a host rewording that message would silently reintroduce
 * the crash, or wrongly swallow a real error. So this helper MUST only be used
 * at call sites where returning `undefined`/null is itself a correct degraded
 * result: passive, nullable READS. Required calls (opening a window, showing a
 * dialog, etc.) MUST keep using the throwing {@link hostCallBridge} path so
 * genuine failures still surface. `scripts/check-desktop-host-call-init-safety.mjs`
 * guards the module-init boundary so a new throwing `desktop.*` read cannot
 * reintroduce the hazard.
 *
 * The swallowed error is surfaced as a dev-only `console.warn` (once per
 * operation) so a real bug hiding behind a passive read is never fully silent.
 */
export function hostCallOptional(
  operation: string,
  argsJson?: string,
  options?: HostCallOptionalOptions,
): unknown {
  const hostCall = hostCallBridge();
  if (!hostCall) {
    return undefined;
  }

  try {
    return hostCall(operation, argsJson ?? '{}');
  } catch (error) {
    warnDegradedHostCall(operation, options, error);
    return undefined;
  }
}

/**
 * Async counterpart of {@link hostCallOptional} for passive, nullable reads
 * that ride the promise transport (ENG-22825). The same contract applies: a
 * host that answers the op with an error (unimplemented capability on
 * iOS/Android) degrades to a resolved `undefined` instead of a rejection,
 * with the same dev-only once-per-operation warning. Only for passive reads
 * whose call sites already coalesce `undefined` to a correct default;
 * required/side-effecting calls MUST stay on the rejecting
 * {@link hostCallAsync} path so genuine failures surface.
 */
export function hostCallOptionalAsync(
  operation: string,
  argsJson?: string,
  options?: HostCallOptionalOptions,
): Promise<unknown> {
  const result = hostCallAsync(operation, argsJson);
  if (!result) {
    return Promise.resolve(undefined);
  }
  return result.then(
    (value) => value,
    (error: unknown) => {
      warnDegradedHostCall(operation, options, error);
      return undefined;
    },
  );
}

function warnDegradedHostCall(
  operation: string,
  options: HostCallOptionalOptions | undefined,
  error: unknown,
): void {
  if (
    options?.silent
    || isProductionHostEnvironment()
    || warnedDegradedHostCalls.has(operation)
  ) {
    return;
  }
  warnedDegradedHostCalls.add(operation);
  // eslint-disable-next-line no-console
  console.warn(
    `[ExactHostCall] optional host call "${options?.label ?? operation}" `
      + `degraded to null after the host threw: ${describeHostCallError(error)}. `
      + 'This is expected when the capability is unimplemented on this platform, '
      + 'but if the op SHOULD work here it is a real error, not a missing capability.',
  );
}

/**
 * Test-only: clear the once-per-operation dedup set used by
 * {@link hostCallOptional} so warnings can be re-observed.
 */
export function __resetHostCallOptionalWarningsForTests(): void {
  warnedDegradedHostCalls.clear();
}
