// ---------------------------------------------------------------------------
// A6 write guard: unidirectional time.
// ---------------------------------------------------------------------------

let writeDepth = 0;

export function allowStateWrites<T>(fn: () => T): T {
  writeDepth += 1;
  try {
    return fn();
  } finally {
    writeDepth -= 1;
  }
}

function guardWrite(name: string): void {
  if (writeDepth === 0) {
    throw new Error(
      `[contract] state "${name}" written outside an action/task (LLP 0155 A6: no state writes during view evaluation)`,
    );
  }
}

function scopeValue(scope: Scope, name: string): unknown {
  const binding = scope.lookup(name);
  if (!binding) return undefined;
  if (binding.kind === 'value' || binding.kind === 'local') return binding.value;
  return untrack(() => binding.get());
}

/**
 * Materialize compiler-owned Contract worklet artifacts only after behavior
 * instances exist, so capture names resolve to their live SharedValue
 * objects. The executable source/capture order remains immutable compiler IR;
 * only the per-instance capture values and runOnJS callbacks are joined here.
 */
function attachContractMotionWorkletArtifacts(ir: ComponentIR, scope: Scope): void {
  for (const worklet of ir.motion?.worklets ?? []) {
    const callback = scopeValue(scope, worklet.action);
    if (typeof callback !== 'function') {
      throw new Error(`[motion] worklet action "${worklet.action}" did not resolve to a function`);
    }
    const artifact = worklet.artifact;
    const captures = artifact.captureNames.map((name) => {
      const value = scopeValue(scope, name);
      if (value === undefined) {
        throw new Error(`[motion] worklet capture "${name}" is missing from component scope`);
      }
      return value;
    });
    const callbacks = artifact.callbacks.map((entry) => {
      const value = scopeValue(scope, entry.action);
      if (typeof value !== 'function') {
        throw new Error(`[motion] runOnJS action "${entry.action}" did not resolve to a function`);
      }
      return Object.freeze({ ...entry, callback: value });
    });
    const runtimeArtifact = Object.freeze({
      ...artifact,
      captureNames: Object.freeze([...artifact.captureNames]),
      captureKinds: Object.freeze([...artifact.captureKinds]),
      captures: Object.freeze(captures),
      inputSlots: Object.freeze([...artifact.inputSlots]),
      outputSlots: Object.freeze([...artifact.outputSlots]),
      callbacks: Object.freeze(callbacks),
    });
    Object.defineProperties(callback, {
      __workletSource: {
        configurable: true,
        enumerable: false,
        value: artifact.source,
      },
      __exactMotionWorkletId: {
        configurable: true,
        enumerable: false,
        value: artifact.compilerId,
      },
      __exactMotionWorkletArtifact: {
        configurable: true,
        enumerable: false,
        value: runtimeArtifact,
      },
    });
  }
}

/**
 * Wrap an authored derive formula with its optional result-stabilization
 * policy. The comparator expression is sampled once per component/behavior
 * instance; the formula itself remains reactive through the surrounding
 * computed.
 */
function createDeriveEvaluator(
  derive: DeriveIR,
  def: CompiledComponent,
  scope: Scope,
  locus: ContractErrorLocus,
  evaluate: () => unknown,
): () => unknown {
  if (!derive.memo) {
    return () => runWithContractErrorLocus(locus, evaluate);
  }

  const memo = derive.memo;
  const createDeriveMemoStabilizer = def.runtime?.createDeriveMemoStabilizer;
  if (!createDeriveMemoStabilizer) {
    // `defineComponent` normally catches this before instantiation. Keep the
    // local guard so hand-constructed/stale component handles fail closed at
    // the authored derive instead of silently reverting to Object.is.
    throw new Error(
      `[contract] derive "${derive.name}" uses memoization without an injected memo runtime`,
    );
  }
  const label = `derive "${derive.name}" ${
    memo.kind === 'rows' ? `memoRows(${JSON.stringify(memo.key)})` : 'memo'
  }`;
  let policy: DeriveMemoRuntimePolicy;
  switch (memo.kind) {
    case 'shallow':
      policy = { kind: 'shallow', label };
      break;
    case 'rows':
      policy = { kind: 'rows', key: memo.key, label };
      break;
    case 'comparator': {
      // Resolve lazily on the first computed read, after the full component
      // or behavior scope has been installed. The value is still sampled
      // exactly once and never becomes a reactive dependency.
      let stabilize: DeriveMemoStabilizer | undefined;
      return () =>
        runWithContractErrorLocus(locus, () => {
          if (!stabilize) {
            const comparator = untrack(() => evalRuntimeExpr(memo.comparator, scope));
            if (typeof comparator !== 'function') {
              throw new TypeError(
                `[contract] ${label}: comparator expression must evaluate to a function`,
              );
            }
            stabilize = createDeriveMemoStabilizer({
              kind: 'comparator',
              label,
              comparator: comparator as (previous: unknown, next: unknown) => unknown,
            });
          }
          return stabilize(evaluate());
        });
    }
  }

  const stabilize = createDeriveMemoStabilizer(policy);
  return () => runWithContractErrorLocus(locus, () => stabilize(evaluate()));
}

// ---------------------------------------------------------------------------
// Runtime context (per mounted root)
// ---------------------------------------------------------------------------

export interface RuntimeContext {
  /** Stable identity for per-root capability caching. */
  rootKey: object;
  /** Host-ops root id used to scope DOM witnesses and one-root key dispatch. */
  rootId: number;
  rootOwner: Owner;
  /** App-runtime ownership object shared by every root explicitly mounted into it. */
  contractRuntime: ContractRuntime;
  runtimeRoot: ContractRuntimeRootRegistration;
  treeEffectScope: EffectScope;
  capabilityCache: Map<ContractCapability, unknown>;
  /** Mount tasks queued until after the next commit. */
  mountTaskQueue: Array<() => void>;
  /** Hydration-only builtin overrides waiting for the root's live release. */
  releaseHydrationCapabilities: Array<() => void>;
  /** Framework-owned activation work held until the candidate commits. */
  hydrationActivationQueue: Array<() => void>;
  /** Affine ownership state for a hydration candidate. */
  hydrationActivationState: 'preparing' | 'committed' | 'aborted';
  /** Register framework-owned publication against this root's commit token. */
  activateAfterHydrationCommit(
    activate: () => void,
    effectScope?: EffectScope,
  ): void;
  /** Request/root-scoped seeded RNG used only for the hydration replay window. */
  hydrationRandom?: () => number;
  /** Root-lifetime phase bit: late-mounted scopes release immediately once live. */
  hydrationCapabilitiesReleased: boolean;
  hydration?: ContractHydrationRuntimeOptions;
  /** Present only for an explicit build-time semantic payload capture. */
  routePayloadCapture?: ContractRoutePayloadCaptureState;
  quiescenceEpoch: number;
}

export interface RuntimeContextOptions {
  hydration?: ContractHydrationRuntimeOptions;
  rootId?: number;
  routePayloadCapture?: ContractRoutePayloadCaptureState;
  contractRuntime?: ContractRuntime;
}

export function createRuntimeContext(
  rootOwner: Owner,
  options: RuntimeContextOptions = {},
): RuntimeContext {
  const contractRuntime = options.contractRuntime ?? getDefaultContractRuntime();
  const runtimeRoot = contractRuntime.registerRoot(options.rootId ?? 0, {
    deferPublication: options.hydration?.deferActivation === true,
  });
  runtimeRoot.setCaptureReset(() => rootOwner.dispose());
  const treeEffectScope = contractRuntime.effectSupervisor.createScope({
    id: `${runtimeRoot.id}:generation`,
    kind: 'tree-generation',
    parentId: runtimeRoot.scope.id,
  });
  const ctx: RuntimeContext = {
    rootKey: {},
    rootId: options.rootId ?? 0,
    rootOwner,
    contractRuntime,
    runtimeRoot,
    treeEffectScope,
    capabilityCache: new Map(),
    mountTaskQueue: [],
    releaseHydrationCapabilities: [],
    hydrationActivationQueue: [],
    hydrationActivationState: options.hydration?.deferActivation
      ? 'preparing'
      : 'committed',
    activateAfterHydrationCommit: (activate, effectScope) => {
      registerHydrationActivation(ctx, activate, effectScope);
    },
    hydrationCapabilitiesReleased: options.hydration === undefined,
    quiescenceEpoch: 0,
  };
  if (options.routePayloadCapture) {
    ctx.routePayloadCapture = options.routePayloadCapture;
  }
  if (options.hydration) {
    ctx.hydration = options.hydration;
    const randomSeed = options.hydration.capabilities?.randomSeed;
    if (typeof randomSeed === 'string' && randomSeed.length > 0) {
      ctx.hydrationRandom = createContractHydrationSeededRandom(randomSeed);
    }
  }
  let unregisterQuiescence = (): void => {};
  registerHydrationActivation(ctx, () => {
    runtimeRoot.publish();
    unregisterQuiescence = contractRuntime.registerQuiescenceParticipant({
      id: `${runtimeRoot.id}:queues`,
      snapshot: () => ({
        deferredMountTasks: ctx.mountTaskQueue.length,
        hydrationReleases: ctx.releaseHydrationCapabilities.length,
        hydrationActivations: ctx.hydrationActivationQueue.length,
        // Deferred work blocked behind hydration is still actionable debt for
        // replay: the fixed-point barrier must fail NON_QUIESCENT rather than
        // silently checkpoint a pre-release root.
        actionable:
          ctx.mountTaskQueue.length +
          ctx.releaseHydrationCapabilities.length +
          ctx.hydrationActivationQueue.length,
        epoch: ctx.quiescenceEpoch,
      }),
      drain: () => ctx.hydrationCapabilitiesReleased ? drainMountTasks(ctx) : 0,
    });
  });
  rootOwner.register(() => {
    if (ctx.hydrationActivationState === 'preparing') {
      ctx.hydrationActivationState = 'aborted';
      ctx.hydrationActivationQueue.length = 0;
      ctx.releaseHydrationCapabilities.length = 0;
      ctx.mountTaskQueue.length = 0;
      ctx.quiescenceEpoch += 1;
    }
    unregisterQuiescence();
    treeEffectScope.close();
    runtimeRoot.close();
  });
  return ctx;
}

export function drainMountTasks(ctx: RuntimeContext): number {
  let drained = 0;
  while (ctx.mountTaskQueue.length > 0) {
    const task = ctx.mountTaskQueue.shift()!;
    task();
    drained += 1;
  }
  if (drained > 0) ctx.quiescenceEpoch += 1;
  return drained;
}

function queueMountTask(ctx: RuntimeContext, effectScope: EffectScope, task: () => void): void {
  ctx.mountTaskQueue.push(() => {
    if (effectScope.state === 'open') task();
  });
  ctx.quiescenceEpoch += 1;
}

export function releaseHydrationCapabilities(ctx: RuntimeContext): void {
  if (ctx.hydrationCapabilitiesReleased) {
    return;
  }
  batch(() => {
    // Release callbacks publish live capability values. Mark the root live
    // before invoking them so reactive consumers re-evaluate against the live
    // branch rather than observing one last captured turn.
    ctx.hydrationCapabilitiesReleased = true;
    while (ctx.releaseHydrationCapabilities.length > 0) {
      const release = ctx.releaseHydrationCapabilities.shift()!;
      release();
    }
    // Keep the phase on the root context rather than on the initially mounted
    // component set. A conditional/lazy child created after hydration release
    // must join live host/time state immediately instead of enqueueing a
    // callback into a drain that already happened.
    ctx.quiescenceEpoch += 1;
  });
}

// @ref LLP 0210 §4.9 — framework-owned activation is affine: work registered
// while a hydration candidate is preparing cannot publish until that same
// candidate commits, and an aborted candidate can never be revived.
export function registerHydrationActivation(
  ctx: RuntimeContext,
  activate: () => void,
  effectScope?: EffectScope,
): void {
  if (ctx.hydrationActivationState === 'aborted') return;
  const guarded = (): void => {
    if (!effectScope || effectScope.state === 'open') activate();
  };
  if (ctx.hydrationActivationState === 'committed') {
    guarded();
    return;
  }
  ctx.hydrationActivationQueue.push(guarded);
  ctx.quiescenceEpoch += 1;
}

export function commitHydrationActivation(ctx: RuntimeContext): void {
  if (ctx.hydrationActivationState === 'aborted') return;
  if (ctx.hydrationActivationState === 'preparing') {
    ctx.hydrationActivationState = 'committed';
  }
  releaseHydrationCapabilities(ctx);
  while (ctx.hydrationActivationQueue.length > 0) {
    ctx.hydrationActivationQueue.shift()!();
  }
  ctx.quiescenceEpoch += 1;
}

export function registerHydrationCapabilityRelease(
  ctx: RuntimeContext,
  release: () => void,
  effectScope?: EffectScope,
): void {
  if (ctx.hydrationCapabilitiesReleased) {
    batch(release);
    return;
  }
  ctx.releaseHydrationCapabilities.push(() => {
    if (!effectScope || effectScope.state === 'open') release();
  });
  ctx.quiescenceEpoch += 1;
}

// ---------------------------------------------------------------------------
// Built-ins
// ---------------------------------------------------------------------------

// Keep this set in sync with CONTRACT_RUNTIME_BUILTIN_NAMES
// (compiler/tokens.ts) — the analyzer's behavior-template closed-scope check
// reads that list, and behavior-templates.test.ts pins the two together via
// hasContractBuiltin below.
const builtinScope = new Scope(null);
// The Contract `Math` object forwards to the engine's, except `random`,
// which routes through the LLP 0087 determinism seam when a conformance
// host is installed (LLP 0328 D1: the scripted clock + seeded rng seam).
const contractMath: Record<string, unknown> = {};
for (const key of Object.getOwnPropertyNames(Math)) {
  contractMath[key] = (Math as unknown as Record<string, unknown>)[key];
}
contractMath.random = (): number =>
  getContractDeterminismHost()?.random() ?? Math.random();

function installHydrationMath(
  scope: Scope,
  ctx: RuntimeContext,
  liveMath: Record<string, unknown>,
  effectScope: EffectScope,
): void {
  if (!ctx.hydrationRandom) {
    scope.defineValue('Math', liveMath);
    return;
  }
  const scopedMath = Object.create(liveMath) as Record<string, unknown>;
  scopedMath.random = ctx.hydrationRandom;
  scope.defineValue('Math', scopedMath);
  registerHydrationCapabilityRelease(ctx, () => {
    scope.defineValue('Math', liveMath);
  }, effectScope);
}
builtinScope.defineValue('Math', contractMath);

function contractMathForInstance(
  runtime: ContractRuntime,
  logicalInstancePath: readonly string[],
): Record<string, unknown> {
  const value: Record<string, unknown> = {};
  for (const key of Object.getOwnPropertyNames(Math)) {
    value[key] = (Math as unknown as Record<string, unknown>)[key];
  }
  const random = (): number => runtime.random('<uncertified-rng>', logicalInstancePath);
  Object.defineProperty(random, '__exactContractRandomAtSite', {
    value: (siteId: string) => runtime.random(siteId, logicalInstancePath),
  });
  value.random = random;
  return value;
}
builtinScope.defineValue('JSON', JSON);
builtinScope.defineValue('String', String);
builtinScope.defineValue('Number', Number);
builtinScope.defineValue('Boolean', Boolean);
builtinScope.defineValue('console', console);
builtinScope.defineValue('form', createContractForm);
// Time enters through an explicit builtin rather than ambient Date (LLP 0087
// keeps time/randomness visible; `now()` is the v0 form).
// @ref LLP 0330 §10.3 — an unstamped/legacy alias must fail closed instead of
// silently degrading now(granularity) to exact, nonreactive now().
function exactNowWithoutTemporalExtension(read: () => number): (...args: unknown[]) => number {
  return (...args: unknown[]) => {
    if (args.length > 0) {
      throw new Error(
        '[contract] now(granularity) requires the temporal runtime extension; refusing to ignore the argument',
      );
    }
    return read();
  };
}
builtinScope.defineValue(
  'now',
  exactNowWithoutTemporalExtension(
    () => getContractDeterminismHost()?.now() ?? Date.now(),
  ),
);
// LLP 0281 §3.4 — `sample(<channel>)` seals an immutable copy of a value
// channel's current sample. The analyzer confines it to edge pointer-event
// arguments; here it is an ordinary builtin so the sealed value flows into
// the action as a plain, trace-visible argument.
builtinScope.defineValue('sample', sampleChannel);
// LLP 0281 §3.1 (ENG-22539) — `publish(<channel>)` requests one paced
// emission through the channel's declared rated publish line. The analyzer
// confines it to statement position in action/task bodies; the emission
// itself defers past the action's commit and re-evaluates the declared
// payload mapping (the caller never supplies a wire value).
builtinScope.defineValue('publish', publishChannel);

/** Names defined per component/behavior scope rather than on builtinScope. */
const PER_SCOPE_BUILTIN_NAMES: ReadonlySet<string> = new Set([
  'every',
  'after',
  'now',
  'invalidateAt',
  'timezoneGeneration',
  'temporal',
]);

/**
 * True when the runtime provides `name` to every component AND behavior
 * scope (builtinScope or the per-scope managed helpers). Test-facing pin for
 * CONTRACT_RUNTIME_BUILTIN_NAMES (compiler/tokens.ts).
 */
export function hasContractBuiltin(name: string): boolean {
  return PER_SCOPE_BUILTIN_NAMES.has(name) || builtinScope.lookup(name) !== null;
}

function querySnapshot(
  rows: readonly unknown[],
  status: 'pending' | 'ready' | 'error',
  error: unknown,
  connection?: DataConnection,
): readonly unknown[] {
  const snapshot = [...rows] as unknown[] & {
    status?: string;
    pending?: boolean;
    loading?: boolean;
    ready?: boolean;
    empty?: boolean;
    error?: unknown;
    value?: readonly unknown[];
    connection?: DataConnection;
  };
  Object.defineProperties(snapshot, {
    status: { value: status, enumerable: false },
    pending: { value: status === 'pending', enumerable: false },
    loading: { value: status === 'pending', enumerable: false },
    ready: { value: status === 'ready', enumerable: false },
    empty: { value: status === 'ready' && rows.length === 0, enumerable: false },
    error: { value: status === 'error' ? error ?? true : null, enumerable: false },
    value: { value: snapshot, enumerable: false },
    // LLP 0284 §2.2: the connection axis is readable as `<binding>.connection`;
    // undefined for non-provider-backed bindings — absence is itself a fact.
    connection: { value: connection, enumerable: false },
  });
  return snapshot;
}

/**
 * Managed timer helpers, shared by component and behavior scopes (A4:
 * acquisition returns a disposal the owner tracks, so reset-based HMR and
 * unmount stay leak-free by construction).
 */
function guardTuiGenerationCallback<TArgs extends unknown[], TResult>(
  callback: (...args: TArgs) => TResult,
): (...args: TArgs) => TResult | undefined {
  const guard = (
    globalThis as typeof globalThis & {
      __exactTuiGuardAsyncCallback?: (
        value: (...args: TArgs) => TResult,
      ) => (...args: TArgs) => TResult | undefined;
    }
  ).__exactTuiGuardAsyncCallback;
  return guard ? guard(callback) : callback;
}

function defineManagedTimers(
  scope: Scope,
  owner: Owner,
  ctx: RuntimeContext,
  effectScope: EffectScope,
): void {
  scope.defineValue('every', (ms: unknown, fn: unknown) => {
    if (typeof fn !== 'function') {
      throw new Error('[contract] every(ms, action) requires an action');
    }
    const delayMs = Number(ms);
    let active = true;
    let disposeTimer: (() => void) | null = null;
    let handle: unknown = Object.freeze({ kind: 'deferred-contract-interval' });
    registerHydrationActivation(ctx, () => {
      if (!active) return;
      const timerId = ctx.contractRuntime.allocateReplayTimerId();
      ctx.contractRuntime.recordReplayEvent({
        kind: 'timer-submission',
        timerId,
        timerKind: 'every',
        delayMs,
      });
      const tick = guardTuiGenerationCallback((): void => {
        if (!active || effectScope.state !== 'open') return;
        runWithContractReactiveQueueOwner(ctx.contractRuntime, () => {
          ctx.contractRuntime.recordReplayEvent({
            kind: 'timer-fire',
            timerId,
            timerKind: 'every',
            delayMs,
          });
          batch(() => allowStateWrites(() => (fn as () => void)()));
        });
      });
      // LLP 0328 D1: timers route through the determinism seam when a
      // conformance host is installed (scripted clock); ambient otherwise.
      const host = ctx.contractRuntime.determinism.get();
      if (host) {
        handle = host.setInterval(tick, delayMs);
        disposeTimer = () => host.clearInterval(handle);
      } else {
        handle = setInterval(tick, delayMs);
        disposeTimer = () => clearInterval(handle as ReturnType<typeof setInterval>);
      }
    }, effectScope);
    owner.register(() => {
      active = false;
      disposeTimer?.();
      disposeTimer = null;
    });
    return handle;
  });
  scope.defineValue('after', (ms: unknown, fn: unknown) => {
    if (typeof fn !== 'function') {
      throw new Error('[contract] after(ms, action) requires an action');
    }
    const delayMs = Number(ms);
    let active = true;
    let disposeTimer: (() => void) | null = null;
    let handle: unknown = Object.freeze({ kind: 'deferred-contract-timeout' });
    registerHydrationActivation(ctx, () => {
      if (!active) return;
      const timerId = ctx.contractRuntime.allocateReplayTimerId();
      ctx.contractRuntime.recordReplayEvent({
        kind: 'timer-submission',
        timerId,
        timerKind: 'after',
        delayMs,
      });
      const fire = guardTuiGenerationCallback((): void => {
        if (!active || effectScope.state !== 'open') return;
        runWithContractReactiveQueueOwner(ctx.contractRuntime, () => {
          ctx.contractRuntime.recordReplayEvent({
            kind: 'timer-fire',
            timerId,
            timerKind: 'after',
            delayMs,
          });
          batch(() => allowStateWrites(() => (fn as () => void)()));
        });
      });
      const host = ctx.contractRuntime.determinism.get();
      if (host) {
        handle = host.setTimeout(fire, delayMs);
        disposeTimer = () => host.clearTimeout(handle);
      } else {
        handle = setTimeout(fire, delayMs);
        disposeTimer = () => clearTimeout(handle as ReturnType<typeof setTimeout>);
      }
    }, effectScope);
    owner.register(() => {
      active = false;
      disposeTimer?.();
      disposeTimer = null;
    });
    return handle;
  });
}

function defineManagedTimeScope(
  scope: Scope,
  owner: Owner,
  ctx: RuntimeContext,
  runtime: CompiledComponent['runtime'],
  effectScope: EffectScope,
): void {
  const hydrationNowMs = ctx.hydration?.capabilities?.nowMs;
  if (runtime.temporal) {
    runtime.temporal.installScope({
      scope,
      owner,
      clockAuthority: ctx.contractRuntime.clockAuthority,
      ...(typeof hydrationNowMs === 'number' ? { hydrationNowMs } : {}),
      registerHydrationRelease: (release) => registerHydrationCapabilityRelease(ctx, release, effectScope),
    });
    return;
  }
  if (typeof hydrationNowMs === 'number' && Number.isFinite(hydrationNowMs)) {
    scope.defineValue('now', exactNowWithoutTemporalExtension(() => hydrationNowMs));
    registerHydrationCapabilityRelease(ctx, () => {
      scope.defineValue(
        'now',
        exactNowWithoutTemporalExtension(
          () => ctx.contractRuntime.now(),
        ),
      );
    }, effectScope);
    return;
  }
  scope.defineValue(
    'now',
    exactNowWithoutTemporalExtension(() => ctx.contractRuntime.now()),
  );
}

function invokeMutationTarget(name: string, target: unknown, args: unknown[]): unknown {
  if (typeof target === 'function') {
    return (target as (...mutationArgs: unknown[]) => unknown)(...args);
  }
  if (target && typeof target === 'object') {
    const mutate = (target as { mutate?: unknown }).mutate;
    if (typeof mutate === 'function') {
      return (mutate as (...mutationArgs: unknown[]) => unknown).call(target, ...args);
    }
  }
  throw new Error(`[contract] mutation "${name}" did not resolve to a callable mutation`);
}

function normalizeTypedMutationResult(
  value: unknown,
): { kind: 'ok'; value?: unknown } | { kind: 'error'; error: unknown; code?: string } {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return {
      kind: 'error',
      code: 'mutation-protocol-violation',
      error: new Error('[contract] typed mutation returned a malformed DataMutationResult'),
    };
  }
  const result = value as { ok?: unknown; value?: unknown; error?: unknown };
  if (result.ok === true) {
    return { kind: 'ok', ...(result.value === undefined ? {} : { value: result.value }) };
  }
  if (result.ok === false && Object.prototype.hasOwnProperty.call(result, 'error')) {
    return { kind: 'error', error: result.error, code: 'mutation-rejected' };
  }
  return {
    kind: 'error',
    code: 'mutation-protocol-violation',
    error: new Error('[contract] typed mutation returned a malformed DataMutationResult'),
  };
}

// ---------------------------------------------------------------------------
// Component instances
// ---------------------------------------------------------------------------

export type PropValue =
  | { kind: 'getter'; get: () => unknown }
  | { kind: 'value'; value: unknown };

export interface ComponentInstance {
  def: CompiledComponent;
  scope: Scope;
  owner: Owner;
  ctx: RuntimeContext;
  /** Mounted component boundary, populated after its single-root view mounts. */
  hostNodes?: () => Array<{ id: number }>;
  /** Dataflow/receipt identity for this mounted instance. */
  runtimeInstanceId?: string;
  /** Component-owned effect scope; runtime mutations intentionally use the sibling mutation scope. */
  effectScope: EffectScope;
  logicalInstancePath: readonly string[];
}

export interface InstantiateComponentOptions {
  hydrationNodeId?: string;
  hydrationStructuralId?: string;
  hydrationKeyChain?: string;
  logicalInstancePath?: readonly string[];
}

let nextComponentEffectScopeId = 1;

function effectAddress(
  instance: ComponentInstance,
  declarationKind: EffectAddressV1['declarationKind'],
  declarationName: string,
  operationSiteId?: string,
): EffectAddressV1 {
  return {
    version: 1,
    moduleId: instance.def.file.sourcePath ?? '<inline-contract>',
    templateKind: 'component',
    template: instance.def.ir.name,
    declarationKind,
    declarationId: `${declarationKind}:${declarationName}`,
    ...(operationSiteId ? { operationSiteId } : {}),
    logicalInstancePath: instance.logicalInstancePath,
  };
}

function recordRuntimeStateWrite(
  instance: ComponentInstance,
  slot: string,
  before: unknown,
  after: unknown,
): void {
  const invocationId = currentContractActionInvocationId(instance.ctx.contractRuntime);
  instance.ctx.contractRuntime.recordReplayEvent({
    kind: 'state-write',
    instancePath: instance.logicalInstancePath,
    slot,
    ...(invocationId ? { invocationId } : {}),
    before,
    after: instance.ctx.contractRuntime.captureReplayValue(after),
  });
}

export function instantiateComponent(
  def: CompiledComponent,
  props: Record<string, PropValue>,
  ctx: RuntimeContext,
  options: InstantiateComponentOptions = {},
): ComponentInstance {
  if (def.file.runtimeExtensions?.includes('temporal') && !def.runtime.temporal) {
    throw new Error('[contract] this module requires the temporal runtime extension');
  }
  registerHydrationActivation(ctx, () => {
    ctx.contractRuntime.registerReplayModule({
      moduleId: def.file.sourcePath ?? '<inline-contract>',
      sourceVersion: def.file.sourceVersion ?? '<missing-source-version>',
      irVersion: def.file.irVersion,
    });
  });
  const owner = createOwner();
  getOwner()?.register(() => owner.dispose());

  const scope = new Scope(builtinScope);
  const ir: ComponentIR = def.ir;

  // Prime the LLP 0284 §2.6 session key before any binding wiring: providers
  // emit `established` receipts during query/ephemeral subscribe below,
  // which runs before this instance registers with the dataflow inspector.
  registerHydrationActivation(ctx, primeContractDataflowSession);

  return runWithOwner(owner, () => {
    const logicalInstancePath = options.logicalInstancePath ?? [
      `${def.file.sourcePath ?? '<inline-contract>'}#${def.ir.name}`,
    ];
    const effectScope = ctx.contractRuntime.effectSupervisor.createScope({
      id: `${ctx.runtimeRoot.id}:component:${nextComponentEffectScopeId++}`,
      kind: 'component',
      parentId: ctx.treeEffectScope.id,
    });
    owner.register(() => effectScope.close());
    const instance: ComponentInstance = {
      def,
      scope,
      owner,
      ctx,
      effectScope,
      logicalInstancePath,
      // CommandRef identities are minted while behaviors instantiate below;
      // assign the lifetime id before action functions freeze their owner.
      runtimeInstanceId: allocateContractRuntimeInstanceId(),
    };
    const activateOwned = (setup: () => void): void => {
      registerHydrationActivation(
        ctx,
        () => runWithOwner(owner, setup),
        instance.effectScope,
      );
    };
    installHydrationMath(
      scope,
      ctx,
      contractMathForInstance(ctx.contractRuntime, instance.logicalInstancePath),
      instance.effectScope,
    );
    // ENG-22443: every declaration boundary tags escaping errors with its
    // authored locus (fill-only-missing; inner statement/expression spans
    // stay the most precise).
    const errorLocus = (region: string, span: Span | undefined): ContractErrorLocus => ({
      component: ir.name,
      sourcePath: def.file.sourcePath,
      region,
      span,
    });
    const reactiveOptions = (
      kind: 'state' | 'derive' | 'task',
      name: string,
      span: Span | undefined,
    ): ReactiveNodeOptions | undefined => {
      if (!isReactiveIntrospectionEnabled()) {
        return undefined;
      }
      return {
        label: `${ir.name}.${kind}.${name}`,
        source: {
          component: ir.name,
          sourcePath: def.file.sourcePath,
          region: `${kind} "${name}"`,
          ...(span ? { span } : {}),
        },
      };
    };
    // Managed timer helpers (A4: acquisition returns a disposal the owner
    // tracks, so reset-based HMR and unmount stay leak-free by construction).
    defineManagedTimeScope(scope, owner, ctx, def.runtime, instance.effectScope);
    defineManagedTimers(scope, owner, ctx, instance.effectScope);
    // Disposal channel for use-imported helpers (LLP 0293 ledger row 2):
    // `onCleanup(installThing(...))` in a task body registers the returned
    // disposal with the same owner every()/after() use, so reset-based HMR
    // and unmount stay leak-free without module-level idempotence hacks.
    scope.defineValue('onCleanup', (fn: unknown) => {
      if (typeof fn !== 'function') {
        throw new Error('[contract] onCleanup(dispose) requires a function');
      }
      owner.register(fn as () => void);
    });

    // use-imports: capabilities instantiate per root; everything else binds
    // as a value (compiled components, behavior factories, stores, helpers).
    // Editable/manual IR retains the authored inventory and its missing-link
    // diagnostic. Generated production modules omit that duplicate inventory;
    // their `__links` object is exhaustive by construction.
    if (!CONTRACT_INSTANCE_PRODUCTION) {
      for (const use of def.file.uses ?? []) {
        if (def.links[use.name] === undefined) {
          throw new Error(
            `[contract] component ${ir.name}: import "${use.name}" was not linked (missing in defineComponent links)`,
          );
        }
      }
    }
    for (const [importName, linked] of Object.entries(def.links)) {
      if (isCapability(linked)) {
        let value = ctx.capabilityCache.get(linked);
        if (value === undefined && !ctx.capabilityCache.has(linked)) {
          // ENG-23201: instantiate under the ROOT owner, not the ambient
          // component owner. The capability value is cached per root, but
          // signals created inside instantiate() register their teardown
          // (which clears the signal's observer set) with the ambient owner
          // — so the first-consuming component's unmount would silently
          // freeze every other component's bindings to this capability.
          value = runWithOwner(ctx.rootOwner, () =>
            linked.instantiate({
              rootKey: ctx.rootKey,
              rootId: ctx.rootId,
              owner: ctx.rootOwner,
              ...(ctx.hydration
                ? {
                    hydration: ctx.hydration,
                    onHydrationRelease: (release: () => void) => {
                      registerHydrationCapabilityRelease(ctx, release);
                    },
                  }
                : {}),
            }),
          );
          ctx.capabilityCache.set(linked, value);
        }
        scope.defineValue(importName, value);
      } else {
        const imported = def.file.imports?.[importName];
        const authoredUse = def.file.uses?.find((entry) =>
          entry.name === importName
        );
        const productionOpaqueImport =
          def.file.hydrationOpaqueImports?.[importName];
        const opaqueImportLocus = authoredUse ?? productionOpaqueImport;
        const opaqueFunction = ctx.hydration?.deferActivation === true &&
          typeof linked === 'function' &&
          (
            imported?.descriptor.kind === 'opaque' ||
            productionOpaqueImport !== undefined ||
            (!imported && authoredUse !== undefined)
          );
        if (opaqueFunction && opaqueImportLocus) {
          const target = linked as (...args: unknown[]) => unknown;
          scope.defineValue(importName, new Proxy(target, {
            apply(fn, thisArg, args) {
              if (ctx.hydrationActivationState === 'preparing') {
                // @ref LLP 0386 §3.8.1 — arbitrary opaque helpers cannot be
                // escrowed. Name their authored import locus when preparation
                // invokes one so a later fresh CSR reissue is observable.
                recordContractHydrationOpaquePrepareCall({
                  component: ir.name,
                  ...(def.file.sourcePath
                    ? { sourcePath: def.file.sourcePath }
                    : {}),
                  importName,
                  importSpec: opaqueImportLocus.spec,
                  span: opaqueImportLocus.span,
                });
              }
              return Reflect.apply(fn, thisArg, args);
            },
          }));
        } else {
          scope.defineValue(importName, linked);
        }
      }
    }

    // In-file components shadow nothing; they resolve from view nodes.
    for (const [name, fileComponent] of def.fileComponents) {
      if (!scope.lookup(name)) {
        scope.defineValue(name, fileComponent);
      }
    }

    // Per-item loops below use forEach, not for-of: their closures escape
    // the iteration (into scope bindings), and on Hermes `const` in for-of
    // is function-scoped — the module loader's for-of rewrite cannot save
    // bodies that contain `return`, so every binding would capture the last
    // item (all props resolving to the final prop's value, every action
    // running the last action's body).

    // Props.
    ir.props.forEach((prop) => {
      const provided = props[prop.name];
      const defaultLocus = prop.defaultValue
        ? errorLocus(`prop "${prop.name}" default`, prop.span)
        : null;
      const binding: Binding = {
        kind: 'getter',
        get: () => {
          if (provided) {
            const value = provided.kind === 'getter' ? provided.get() : provided.value;
            if (value !== undefined) {
              return value;
            }
          }
          return defaultLocus
            ? runWithContractErrorLocus(defaultLocus, () =>
                evalRuntimeExpr(prop.defaultValue!, scope),
              )
            : undefined;
        },
      };
      scope.define(prop.name, binding);
    });

    for (const shared of ir.motion?.sharedValues ?? []) {
      if (shared.external !== true) continue;
      const binding = scope.lookup(shared.name);
      const value = binding?.kind === 'value' || binding?.kind === 'local'
        ? binding.value
        : binding
          ? untrack(() => binding.get())
          : undefined;
      const candidate = value && typeof value === 'object'
        ? value as {
            __exactMotionKind?: unknown;
            current?: unknown;
            subscribe?: unknown;
            value?: unknown;
          }
        : null;
      if (
        candidate?.__exactMotionKind !== MOTION_SHARED_VALUE_KIND ||
        typeof candidate.current !== 'function' ||
        typeof candidate.subscribe !== 'function' ||
        !('value' in candidate)
      ) {
        throw new TypeError(
          `[motion] prop "${shared.name}" on ${ir.name} must be a live MotionSharedValue`,
        );
      }
    }

    if ((ir.hosts?.length ?? 0) > 0 && !def.runtime.hostBindings) {
      throw new Error(
        `[contract] component ${ir.name} declares host bindings, but its compiled module did not load the host-bindings runtime extension`,
      );
    }
    def.runtime.hostBindings?.setup(ir, scope, ctx, owner);

    // State slots.
    const stateSnapshot: Record<string, unknown> = {};
    ir.states.forEach((state) => {
      const slot = signal<unknown>(
        untrack(() =>
          runWithContractErrorLocus(errorLocus(`state "${state.name}" initial value`, state.span), () =>
            evalRuntimeExpr(state.initial, scope),
          ),
        ),
        reactiveOptions('state', state.name, state.span),
      );
      stateSnapshot[state.name] = slot.peek();
      scope.define(state.name, {
        kind: 'state',
        get: () => slot.get(),
        set: (value) => {
          guardWrite(state.name);
          const before = slot.peek();
          const replayBefore = ctx.contractRuntime.captureReplayValue(before);
          slot.set(value);
          recordContractStateWrite(instance, state.name, before, slot.peek());
          recordRuntimeStateWrite(instance, state.name, replayBefore, slot.peek());
        },
        mutate: (apply) => {
          guardWrite(state.name);
          const before = slot.peek();
          const replayBefore = ctx.contractRuntime.captureReplayValue(before);
          apply();
          slot.touch();
          recordContractStateWrite(instance, state.name, before, slot.peek());
          recordRuntimeStateWrite(instance, state.name, replayBefore, slot.peek());
        },
      });
    });
    if (ctx.hydration?.capture && options.hydrationNodeId) {
      ctx.hydration.capture.recordComponentState({
        nodeId: options.hydrationNodeId,
        structuralId: options.hydrationStructuralId,
        sourcePath: def.file.sourcePath,
        sourceVersion: def.file.sourceVersion,
        componentName: ir.name,
        state: stateSnapshot,
      });
    }

    // Derives (lazy computeds; may reference props/state/other derives).
    ir.derives.forEach((derive) => {
      const locus = errorLocus(`derive "${derive.name}"`, derive.span);
      const evaluate = createDeriveEvaluator(
        derive,
        def,
        scope,
        locus,
        () => evalRuntimeExpr(derive.expr, scope),
      );
      const memo = ownedComputed(
        evaluate,
        reactiveOptions('derive', derive.name, derive.span),
      );
      scope.define(derive.name, { kind: 'getter', get: () => memo.get() });
    });

    // Resources (A1 exhaustive states, generation-guarded settlement).
    ir.resources.forEach((resource) => {
      const status = signal<'pending' | 'ready' | 'error'>('pending');
      const value = signal<unknown>(undefined);
      const error = signal<unknown>(null);
      let generation = 0;
      let currentAttempt: EffectAttemptId | null = null;

      const run = (): void => {
        const gen = ++generation;
        if (currentAttempt) {
          ctx.contractRuntime.effectSupervisor.supersede(currentAttempt);
          currentAttempt = null;
        }
        batch(() =>
          allowStateWrites(() => {
            status.set('pending');
            error.set(null);
          }),
        );
        const attempt = ctx.contractRuntime.effectSupervisor.startOpaque({
          address: effectAddress(instance, 'resource', resource.name),
          scope: instance.effectScope,
          kind: 'contract-resource',
          params: null,
          thunk: () => evalRuntimeExpr(resource.expr, scope),
        });
        currentAttempt = attempt.attemptId;
        void attempt.completion.then(guardTuiGenerationCallback((receipt) => {
          if (currentAttempt === attempt.attemptId) currentAttempt = null;
          if (gen !== generation || instance.effectScope.state !== 'open') return;
          if (receipt.outcome.kind === 'cancelled') return;
          if (receipt.outcome.kind === 'error') {
            const thrown = receipt.outcome.error;
            decorateContractError(thrown, errorLocus(`resource "${resource.name}"`, resource.span));
            batch(() =>
              allowStateWrites(() => {
                status.set('error');
                error.set(thrown);
              }),
            );
            return;
          }
          const resolved = receipt.outcome.value;
          batch(() =>
            allowStateWrites(() => {
              value.set(resolved);
              status.set('ready');
            }),
          );
        }));
      };

      // The initializer's reactive reads are the resource's dependencies:
      // the effect re-runs (new generation) when any of them change.
      activateOwned(() => {
        ownedEffect(run);
      });

      const handle = {
        get status() {
          return status.get();
        },
        get pending() {
          return status.get() === 'pending';
        },
        get loading() {
          return status.get() === 'pending';
        },
        get ready() {
          return status.get() === 'ready';
        },
        get error() {
          return status.get() === 'error' ? error.get() ?? true : null;
        },
        get value() {
          return value.get();
        },
        refresh() {
          untrack(run);
        },
      };
      scope.defineValue(resource.name, handle);
    });

    // Queries (LLP 0193 S0-S1): a typed handle behind the LLP 0183 `query`
    // boundary becomes a signal-backed array-like value. Parameter reads in
    // the initializer are tracked by this effect, so a prop/state parameter
    // change re-subscribes the query.
    ir.queries.forEach((query) => {
      const status = signal<'pending' | 'ready' | 'error'>('pending');
      const rows = signal<readonly unknown[]>([]);
      const error = signal<unknown>(null);
      // LLP 0284 §2.2: connection axis, orthogonal to the data status above.
      // Only provider-backed deliveries (cells riding the rows) ever set it.
      const connection = signal<DataConnection | undefined>(undefined);
      let subscription: ContractQuerySubscription | null = null;
      // LLP 0373 P0: per-binding generation fence (the resource-path
      // precedent applied to queries) — a resubscription bumps the
      // generation, and every observer delivery from a superseded
      // subscription early-returns, so rapid A→B→A key changes can never
      // publish B's data after the final A.
      let generation = 0;

      const subscribe = (): void => {
        const gen = ++generation;
        subscription?.dispose();
        subscription = null;
        batch(() =>
          allowStateWrites(() => {
            status.set('pending');
            error.set(null);
            connection.set(undefined);
          }),
        );
        let queryHandle: ContractQueryHandle | null = null;
        try {
          const handle = evalRuntimeExpr(query.expr, scope);
          if (!isContractQueryHandle(handle)) {
            throw new Error(`[contract] query "${query.name}" initializer did not return a Contract query handle`);
          }
          queryHandle = handle;
        } catch (thrown) {
          decorateContractError(thrown, errorLocus(`query "${query.name}"`, query.span));
          batch(() =>
            allowStateWrites(() => {
              status.set('error');
              error.set(thrown);
            }),
          );
          return;
        }
        try {
          // LLP 0284 §2.3 `once`: take the snapshot-with-subscribe read,
          // then dispose once the binding holds its first AUTHORITATIVE
          // snapshot — a `ready` cell (or a bare-rows delivery from a plain
          // boundary handle, which is ready by construction). Through the
          // handle seam this is subscribe → first ready cell → dispose (on
          // an initial-snapshot provider that IS the one-shot read; on a
          // change-only provider it primes via the first delta and disposes
          // — the §2.3 pinned semantics). Transient `error` and
          // `refreshing` cells render their states but do NOT settle the
          // once-read: the cell contract carries no transient-vs-terminal
          // error distinction, so the subscription stays open and settles on
          // the provider's first eventual snapshot; a terminal error simply
          // never delivers again (equivalent outcome, review adjudication
          // ENG-22516). The provider's SubscriptionReceipt pair
          // (established → disposed) records which path actually ran. A
          // settled `once` binding is a non-subscription binding, so its
          // connection axis is absent (§2.2). The §2.3 descriptor-policy
          // compiler warning rides the LLP 0194 amendment with the other
          // §2.4 compile-time diagnostics.
          let settledOnce = false;
          let disposeAfterSubscribe = false;
          const settleOnce = (): void => {
            settledOnce = true;
            if (subscription) {
              subscription.dispose();
              subscription = null;
            } else {
              disposeAfterSubscribe = true;
            }
          };
          const established = queryHandle.subscribe((nextRows) => {
            if (gen !== generation) {
              // Straggler delivery from a superseded subscription (LLP 0373
              // P0 generation fence): never published.
              return;
            }
            if (query.once && settledOnce) {
              // A straggler delivery after the once-settlement (e.g. a
              // synchronous burst before dispose ran) must not reopen the
              // binding.
              return;
            }
            // Provider-backed handles tag each delivery with its data cell
            // (LLP 0284 §2.2); plain boundary handles deliver bare rows and
            // keep the pre-0284 ready-on-notify behavior exactly.
            const cell = readQueryDeliveryCell(nextRows);
            const settled = !cell || cell.status === 'ready';
            const once = query.once === true && settled;
            batch(() =>
              allowStateWrites(() => {
                rows.set([...nextRows]);
                if (cell) {
                  if (cell.status === 'error') {
                    status.set('error');
                    error.set(cell.error);
                  } else if (cell.status === 'pending') {
                    status.set('pending');
                    error.set(null);
                  } else {
                    // 'ready' and 'refreshing' both render the value axis.
                    status.set('ready');
                    error.set(null);
                  }
                  connection.set(once ? undefined : cell.connection);
                } else {
                  status.set('ready');
                  error.set(null);
                  connection.set(undefined);
                }
              }),
            );
            if (once) {
              settleOnce();
            }
          });
          if (disposeAfterSubscribe || gen !== generation) {
            // `gen !== generation`: a re-entrant resubscription superseded
            // this attempt while `subscribe()` ran — the newer generation
            // owns `subscription`, so this attempt disposes itself.
            established.dispose();
          } else {
            subscription = established;
          }
        } catch (thrown) {
          decorateContractError(thrown, errorLocus(`query "${query.name}"`, query.span));
          batch(() =>
            allowStateWrites(() => {
              status.set('error');
              error.set(thrown);
            }),
          );
        }
      };

      activateOwned(() => {
        ownedEffect(subscribe);
      });
      owner.register(() => {
        subscription?.dispose();
      });

      // ENG-23174: memoize the snapshot so repeated reads within the same
      // rows/status/error/connection version window return the SAME array
      // identity. Without this, every binding read (including collection
      // re-evaluation on unrelated signal writes, e.g. virtualList's
      // scrollOffset) rebuilt a fresh array via querySnapshot's `[...rows]`
      // spread, which permanently defeated the prepared-list identity cache
      // in computeVirtualRecords (view.ts).
      const snapshotMemo = ownedComputed(() =>
        querySnapshot(rows.get(), status.get(), error.get(), connection.get()),
      );
      scope.define(query.name, {
        kind: 'getter',
        get: () => snapshotMemo.get(),
      });
    });

    // Ephemeral maps (LLP 0284 §2.5) retain their exact delivered-cell and
    // generation-fence semantics, but only modules that declare them load the
    // provider-backed implementation (LLP 0373 P1).
    if ((ir.ephemerals?.length ?? 0) > 0) {
      const ephemeralsRuntime = def.runtime.ephemerals ??
        editableContractEphemeralsRuntime();
      if (!ephemeralsRuntime) {
        throw new Error(
          '[contract] this component requires the ephemeral-map runtime extension',
        );
      }
      ephemeralsRuntime.setup(instance);
    }

    // Mutations (LLP 0263 S2): a manifest-backed mutation declaration binds a
    // callable effect into scope. The analyzer owns mutates-clause validation;
    // runtime keeps the boundary small and invokes the linked callable/adapter.
    ir.mutations.forEach((mutation) => {
      const locus = errorLocus(`mutation "${mutation.name}"`, mutation.span);
      const target = ownedComputed(() =>
        runWithContractErrorLocus(locus, () => evalRuntimeExpr(mutation.expr, scope)),
      );
      scope.defineValue(mutation.name, (...args: unknown[]) => {
        const resolved = target.get();
        const typed = isContractDataMutationCallable(resolved);
        const parentInvocation = currentContractActionInvocationId(ctx.contractRuntime);
        const first = args[0];
        const mutationArgs = typed && first && typeof first === 'object' && !Array.isArray(first)
          ? first as Record<string, unknown>
          : typed ? {} : [...args];
        const attempt = ctx.contractRuntime.effectSupervisor.startOpaque({
          address: effectAddress(instance, 'mutation', mutation.name),
          scope: ctx.contractRuntime.effectSupervisor.mutationScope,
          kind: typed ? 'contract-data-mutation' : 'contract-legacy-mutation',
          params: { args: mutationArgs },
          redactionClass: 'vault',
          evidencePosture: typed ? 'promised' : 'none',
          propagateSynchronousThrow: true,
          causalParents: parentInvocation ? [parentInvocation] : [],
          thunk: (descriptor) => runWithContractErrorLocus(locus, () => {
            if (typed) {
              return resolved.invokeWithCorrelation(mutationArgs as Record<string, unknown>, {
                ...buildDataMutationCorrelation({ actionInvocationId: parentInvocation }),
                effectAttemptId: descriptor.attemptId,
              });
            }
            return invokeMutationTarget(mutation.name, resolved, args);
          }),
          ...(typed ? { normalizeResult: normalizeTypedMutationResult } : {}),
        });
        // Legacy callables retain raw sync/async return semantics. Typed
        // DataMutationResult promises likewise stay fulfilled/rejected exactly
        // as before; the supervisor's normalized terminal is journal truth.
        return attempt.rawResult;
      });
    });

    // Actions.
    ir.actions.forEach((action) => {
      const locus = errorLocus(`action "${action.name}"`, action.span);
      const fn = (...args: unknown[]): unknown => {
        const result = runWithContractErrorLocus(locus, () =>
          runContractActionWithLog(instance, action, args, (runAttributed) => {
            const actionScope = scope.child();
            action.params.forEach((param, index) => {
              actionScope.defineLocal(param, args[index]);
            });
            return executeContractStatements(action, action.body, actionScope, (segment) =>
              runAttributed(() => batch(() => allowStateWrites(segment))),
              instance.effectScope,
            );
          }),
        );
        if (result instanceof Promise) {
          // The async tail of an action has no caller left to catch it
          // (event handlers don't await); report here so the rejection
          // reaches the developer with its authored locus, then keep the
          // rejection observable for callers that do await.
          return result.then(undefined, (error) => {
            decorateContractError(error, locus);
            reportContractRuntimeError(error);
            throw error;
          });
        }
        return result;
      };
      // LLP 0099 M8: motion.command(action) receives the already-bound action
      // function. These non-enumerable annotations preserve the existing call
      // surface while letting the shared LLP 0336 command-instance registry
      // mint an action-symbol + component-generation identity.
      Object.defineProperties(fn, {
        __exactCommandAction: { value: action.name, enumerable: false },
        __exactCommandOwner: {
          value: instance.runtimeInstanceId ?? `${ir.name}_unmounted`,
          enumerable: false,
        },
      });
      registerMotionRunOnJSCallbackOwner(fn, owner);
      scope.defineValue(action.name, fn);
    });

    // LLP 0345 / ENG-24441: reconcile state-derived secondary windows only
    // after action bindings exist, so host closeRequested ingress can invoke
    // the declared close action through the same component scope.
    const windowDeclarations = ir.windows ?? [];
    if (windowDeclarations.length > 0) {
      const windowsRuntime = def.runtime.windows ?? editableContractWindowsRuntime();
      if (!windowsRuntime) {
        throw new Error(
          '[contract] this component requires the declarative-window runtime extension',
        );
      }
      activateOwned(() => {
        windowsRuntime.setup(instance);
      });
    }

    // Behaviors. A `use x = expr()` slot resolved to a same-file behavior
    // template instantiates the template's graph here (LLP 0280 §2.1); an
    // opaque JS factory (`use hover = interaction()`) evaluates exactly as
    // before — that path deliberately does not migrate.
    // ENG-25125: component-lifetime Motion artifacts (SharedValues, commands)
    // are created inside this loop; the root scope attributes them so the web
    // store can expose live/retired counts by root.
    withMotionRootScope(`root:${ctx.rootId}`, () => {
      for (const behavior of ir.behaviors) {
        if (behavior.template) {
          const template = (def.file.behaviorTemplates ?? []).find(
            (candidate) => candidate.name === behavior.template,
          );
          if (!template) {
            throw new Error(
              `[contract] component ${ir.name}: behavior template "${behavior.template}" is missing from the compiled file IR`,
            );
          }
          scope.defineValue(
            behavior.name,
            instantiateBehaviorTemplate({
              instance,
              use: behavior,
              template,
              componentScope: scope,
              owner,
              ctx,
            }),
          );
          continue;
        }
        const value = untrack(() =>
          runWithContractErrorLocus(errorLocus(`behavior "${behavior.name}"`, behavior.span), () =>
            instantiateChannelBehavior(behavior, scope) ?? evalRuntimeExpr(behavior.expr, scope),
          ),
        );
        scope.defineValue(behavior.name, value);
        // Reactive behavior options: a factory result that declares
        // `__exactUpdate` (motion sortable items, or any behavior instance
        // carrying the `__contractReactiveOptions` marker — LLP 0408 W-B)
        // gets its object-literal options argument re-evaluated in an owned
        // effect and pushed on change.
        if (
          value && typeof value === 'object' &&
          ((value as { __exactMotionKind?: unknown }).__exactMotionKind === MOTION_SORTABLE_ITEM_KIND ||
            (value as { __contractReactiveOptions?: unknown }).__contractReactiveOptions === true) &&
          typeof (value as { __exactUpdate?: unknown }).__exactUpdate === 'function' &&
          behavior.expr.kind === 'call' && behavior.expr.args[0]?.kind === 'object'
        ) {
          const item = value as { __exactUpdate(options: unknown): void };
          const optionsExpr = behavior.expr.args[0];
          let first = true;
          ownedEffect(() => {
            const options = evalRuntimeExpr(optionsExpr, scope);
            if (first) {
              first = false;
              return;
            }
            untrack(() => item.__exactUpdate(options));
          });
        }
      }
    });

    attachContractMotionWorkletArtifacts(ir, scope);

    // Tasks.
    ir.tasks.forEach((task) => {
      const locus = errorLocus(`task "${task.name}"`, task.span);
      const runTask = (): void => {
        const taskScope = scope.child();
        const result = runWithContractErrorLocus(locus, () =>
          executeContractStatements(task, task.body, taskScope, (segment) =>
            runWithContractReactiveQueueOwner(
              ctx.contractRuntime,
              () => batch(() => allowStateWrites(segment)),
            ),
            instance.effectScope,
          ),
        );
        if (result instanceof Promise) {
          // Fire-and-forget: report async task failures with their authored
          // locus, then rethrow so the rejection stays loud (unchanged
          // unhandled-rejection semantics, now decorated).
          void result.then(undefined, (error) => {
            decorateContractError(error, locus);
            reportContractRuntimeError(error);
            throw error;
          });
        }
      };

      if (task.trigger.kind === 'manual') {
        scope.defineValue(task.name, runTask);
      } else if (task.trigger.kind === 'mount') {
        queueMountTask(ctx, instance.effectScope, runTask);
      } else {
        const deps = task.trigger.deps;
        let first = true;
        activateOwned(() => {
          ownedEffect(
            () => {
              for (const dep of deps) {
                const binding = scope.lookup(dep);
                if (binding && (binding.kind === 'getter' || binding.kind === 'state')) {
                  binding.get();
                } else if (binding && (binding.kind === 'value' || binding.kind === 'local')) {
                  // Resources bind as stable handle objects; watching one means
                  // watching its status/value.
                  const handle = binding.value as { status?: unknown; value?: unknown } | null;
                  if (handle && typeof handle === 'object') {
                    void handle.status;
                    void handle.value;
                  }
                }
              }
              if (first) {
                first = false;
                return;
              }
              untrack(runTask);
            },
            reactiveOptions('task', task.name, task.span),
          );
        });
      }
    });

    activateOwned(() => {
      registerContractDataflowInstance(instance);
    });
    if ((instance.def.ir.keys ?? []).length > 0) {
      const interactionsRuntime = def.runtime.interactions ??
        editableContractInteractionsRuntime();
      if (!interactionsRuntime) {
        throw new Error(
          '[contract] this production module requires the key-interaction runtime extension',
        );
      }
      activateOwned(() => {
        interactionsRuntime.registerComponent(instance);
      });
    }
    return instance;
  });
}

// ---------------------------------------------------------------------------
// Behavior template instantiation (LLP 0280 §2.1)
// ---------------------------------------------------------------------------

interface BehaviorTemplateInstanceInput {
  instance: ComponentInstance;
  use: UseBehaviorIR;
  template: BehaviorTemplateIR;
  componentScope: Scope;
  owner: Owner;
  ctx: RuntimeContext;
}

/**
 * LLP 0281 stage 0 — instantiate a channel-capability behavior slot
 * (`use cursors = pointerChannel(...)`).
 *
 * Returns null when the slot is not a channel factory call (the caller
 * falls through to plain evaluation). Options cook as plain untracked
 * values; rated publish is NOT an option — it is the
 * `publish <channel> -> <descriptor> rate=<Hz>` view line, wired by
 * mountPublish through the set's __attachPublisher hook (ENG-22525
 * retired the interim ENG-22524 options spelling; the analyzer errors on
 * publish/rate/payload keys).
 */
function instantiateChannelBehavior(
  behavior: UseBehaviorIR,
  scope: Scope,
): unknown | null {
  const expr = behavior.expr;
  if (expr.kind !== 'call' || expr.callee.kind !== 'ident') {
    return null;
  }
  const factory = untrack(() => evalRuntimeExpr(expr.callee, scope));
  if (
    typeof factory !== 'function' ||
    typeof (factory as unknown as Record<string, unknown>).__contractChannelFactory !== 'string'
  ) {
    return null;
  }
  const optionsExpr = expr.args[0];
  if (expr.args.length > 1 || (optionsExpr && optionsExpr.kind !== 'object')) {
    throw new Error(
      `[contract] channel binding "${behavior.name}" takes a single object-literal options argument`,
    );
  }
  const cooked: Record<string, unknown> = {};
  if (optionsExpr && optionsExpr.kind === 'object') {
    for (const entry of optionsExpr.entries) {
      if (!('key' in entry)) {
        throw new Error(
          `[contract] channel binding "${behavior.name}" options do not support spread entries`,
        );
      }
      cooked[entry.key] = untrack(() => evalRuntimeExpr(entry.value, scope));
    }
  }
  const value = factory(cooked);
  if (isValueChannelSet(value)) {
    value.__attachBinding(behavior.name);
  }
  return value;
}

/**
 * Instantiates a behavior template for one `use <name> = <template>(args)`
 * slot. Slot identity is `componentIdentity × instanceName × slotName`
 * (LLP 0280 §2.1): two instances of one template get distinct signals for
 * free because the instance is named. The behavior scope chains to the
 * builtins only — component names are invisible by construction; component
 * values enter through the reactive parameters, which re-read their argument
 * expressions in the component scope on every access (a parameter change
 * never resets behavior state; identity comes from the instance name, not
 * the arguments). Dataflow writes and action invocations record under the
 * qualified `instance.slot` names so behavior-carried contract clauses
 * (joined with those names) verify per instance through the existing
 * contract monitor.
 */
function instantiateBehaviorTemplate(input: BehaviorTemplateInstanceInput): Record<string, unknown> {
  const { instance, use, template, componentScope, owner, ctx } = input;
  const qualified = (name: string): string => `${use.name}.${name}`;
  const locus = (region: string, span: Span | undefined): ContractErrorLocus => ({
    component: instance.def.ir.name,
    sourcePath: instance.def.file.sourcePath,
    region: `behavior ${use.name} (${template.name}): ${region}`,
    span,
  });
  const reactiveOptions = (
    kind: 'state' | 'derive' | 'task',
    name: string,
    span: Span | undefined,
  ): ReactiveNodeOptions | undefined => {
    if (!isReactiveIntrospectionEnabled()) {
      return undefined;
    }
    return {
      label: `${instance.def.ir.name}.behavior.${use.name}.${kind}.${name}`,
      source: {
        component: instance.def.ir.name,
        sourcePath: instance.def.file.sourcePath,
        region: `behavior ${use.name} (${template.name}): ${kind} "${name}"`,
        ...(span ? { span } : {}),
      },
    };
  };

  const behaviorScope = new Scope(builtinScope);
  installHydrationMath(
    behaviorScope,
    ctx,
    contractMathForInstance(ctx.contractRuntime, instance.logicalInstancePath),
    instance.effectScope,
  );

  // Managed helpers mirror the component's own (hydration-aware `now`,
  // owner-disposed timers) so behavior task bodies carry the same A4
  // disposal obligations.
  defineManagedTimeScope(behaviorScope, owner, ctx, instance.def.runtime, instance.effectScope);
  defineManagedTimers(behaviorScope, owner, ctx, instance.effectScope);

  // Reactive parameters.
  const args = use.expr.kind === 'call' ? use.expr.args : [];
  template.params.forEach((param, index) => {
    const argExpr = args[index];
    const argLocus = locus(`parameter "${param}"`, argExpr?.span ?? use.span);
    behaviorScope.define(param, {
      kind: 'getter',
      get: () =>
        argExpr === undefined
          ? undefined
          : runWithContractErrorLocus(argLocus, () => evalRuntimeExpr(argExpr, componentScope)),
    });
  });

  // State slots (dataflow-recorded under qualified names).
  template.states.forEach((state) => {
    const slot = signal<unknown>(
      untrack(() =>
        runWithContractErrorLocus(locus(`state "${state.name}" initial value`, state.span), () =>
          evalRuntimeExpr(state.initial, behaviorScope),
        ),
      ),
      reactiveOptions('state', state.name, state.span),
    );
    behaviorScope.define(state.name, {
      kind: 'state',
      get: () => slot.get(),
      set: (value) => {
        guardWrite(qualified(state.name));
        const before = slot.peek();
        const replayBefore = ctx.contractRuntime.captureReplayValue(before);
        slot.set(value);
        recordContractStateWrite(instance, qualified(state.name), before, slot.peek());
        recordRuntimeStateWrite(instance, qualified(state.name), replayBefore, slot.peek());
      },
      mutate: (apply) => {
        guardWrite(qualified(state.name));
        const before = slot.peek();
        const replayBefore = ctx.contractRuntime.captureReplayValue(before);
        apply();
        slot.touch();
        recordContractStateWrite(instance, qualified(state.name), before, slot.peek());
        recordRuntimeStateWrite(instance, qualified(state.name), replayBefore, slot.peek());
      },
    });
  });

  // Derives: lazy computeds threaded through the module's behavior revision
  // signal so a refresh-spliced formula recomputes in place (behavior-hmr.ts
  // — this is what lets derive-body edits PRESERVE state, LLP 0280 §2.1).
  const revision = behaviorDeriveRevision(instance.def.file.sourcePath ?? '');
  template.derives.forEach((derive) => {
    const deriveLocus = locus(`derive "${derive.name}"`, derive.span);
    const evaluate = createDeriveEvaluator(derive, instance.def, behaviorScope, deriveLocus, () => {
      revision.get();
      return evalRuntimeExpr(derive.expr, behaviorScope);
    });
    const memo = ownedComputed(
      evaluate,
      reactiveOptions('derive', derive.name, derive.span),
    );
    behaviorScope.define(derive.name, { kind: 'getter', get: () => memo.get() });
  });

  // Actions: bodies execute in a child of the behavior scope; invocations
  // log under the qualified name (the action-writes monitor matches joined
  // clauses by it). The runner reads `action.body` at invocation time so a
  // state-preserving refresh splice takes effect immediately.
  template.actions.forEach((action) => {
    const actionLocus = locus(`action "${action.name}"`, action.span);
    const logView: ActionIR = {
      ...action,
      name: qualified(action.name),
      writes: action.writes?.map(qualified),
    };
    const fn = (...actionArgs: unknown[]): unknown => {
      const result = runWithContractErrorLocus(actionLocus, () =>
        runContractActionWithLog(instance, logView, actionArgs, (runAttributed) => {
          const actionScope = behaviorScope.child();
          action.params.forEach((param, index) => {
            actionScope.defineLocal(param, actionArgs[index]);
          });
          return executeContractStatements(action, action.body, actionScope, (segment) =>
            runAttributed(() => batch(() => allowStateWrites(segment))),
            instance.effectScope,
          );
        }),
      );
      if (result instanceof Promise) {
        return result.then(undefined, (error) => {
          decorateContractError(error, actionLocus);
          reportContractRuntimeError(error);
          throw error;
        });
      }
      return result;
    };
    behaviorScope.defineValue(action.name, fn);
  });

  // Tasks: standard triggers and disposal; watching tasks re-arm on declared
  // dependency changes (a reactive parameter is a legal dependency).
  template.tasks.forEach((task) => {
    const taskLocus = locus(`task "${task.name}"`, task.span);
    const runTask = (): void => {
      const taskScope = behaviorScope.child();
      const result = runWithContractErrorLocus(taskLocus, () =>
        executeContractStatements(task, task.body, taskScope, (segment) =>
          runWithContractReactiveQueueOwner(
            ctx.contractRuntime,
            () => batch(() => allowStateWrites(segment)),
          ),
          instance.effectScope,
        ),
      );
      if (result instanceof Promise) {
        void result.then(undefined, (error) => {
          decorateContractError(error, taskLocus);
          reportContractRuntimeError(error);
          throw error;
        });
      }
    };
    if (task.trigger.kind === 'manual') {
      behaviorScope.defineValue(task.name, runTask);
    } else if (task.trigger.kind === 'mount') {
      queueMountTask(ctx, instance.effectScope, runTask);
    } else {
      const deps = task.trigger.deps;
      let first = true;
      ownedEffect(
        () => {
          for (const dep of deps) {
            const binding = behaviorScope.lookup(dep);
            if (binding && (binding.kind === 'getter' || binding.kind === 'state')) {
              binding.get();
            }
          }
          if (first) {
            first = false;
            return;
          }
          untrack(runTask);
        },
        reactiveOptions('task', task.name, task.span),
      );
    }
  });

  // The exposed surface (LLP 0280 OQ3 lean: values and actions only):
  // reactive getters for state/derive values, plain functions for actions.
  const exposed: Record<string, unknown> = {};
  for (const name of template.expose) {
    const binding = behaviorScope.lookup(name);
    if (!binding) {
      continue; // The analyzer rejects invalid exposure; degrade, never throw.
    }
    if (binding.kind === 'value' || binding.kind === 'local') {
      exposed[name] = binding.value;
    } else {
      const reactive = binding;
      Object.defineProperty(exposed, name, {
        enumerable: true,
        get: () => reactive.get(),
      });
    }
  }
  return exposed;
}
