/**
 * Structural namespace for renderer-owned nodes that are part of the
 * hydratable host tree but do not correspond to a distinct authored IR node.
 *
 * @ref LLP 0386 §3.8.3 — total correspondence includes every candidate host
 * node. `$` cannot occur in the authored structural-path grammar, so these
 * descendants cannot alias an authored node within the same source version.
 */
export function contractHydrationSyntheticStructuralId(
  ownerStructuralId: string,
  role: 'virtual-content' | 'collection-row',
): string {
  return `${ownerStructuralId}.$${role}`;
}
