// @system @ref LLP 0081 — compiled-component handle: IR + resolved links.
//
// The Vite plugin emits `defineComponent(fileIR, links)` per .contract
// module; `links` maps each `use Name from "spec"` to the imported value
// (another compiled component, a capability, a behavior factory, a store,
// or a plain helper — LLP 0087's import classes).

import type { ComponentIR, ContractFileIR, Expr } from '../compiler/ir.js';
import type { TextNode } from '@exact/renderer/host-ops';
import type { ContractErrorLocus } from './error-locus.js';
import type { RuntimeContext } from './instance.js';
import type { ContractClockAuthority } from './clock-authority.js';
import type { Scope } from './interpreter.js';
import type { Owner, ReactiveNodeOptions } from './signals.js';
import type { ContractInteractionsRuntime } from './interactions-runtime.js';
import type { ContractWindowsRuntime } from './windows-runtime.js';
import type { ContractEphemeralsRuntime } from './ephemerals-runtime.js';
import { CONTRACT_DEVELOPMENT } from './build-mode.js';
import { registerComponentDesignMeta } from './design-meta.js';

declare const __EXACT_CONTRACT_PRODUCTION__: boolean;
const CONTRACT_DEFINE_DEV =
  typeof __EXACT_CONTRACT_PRODUCTION__ !== 'undefined'
    ? !__EXACT_CONTRACT_PRODUCTION__
    : CONTRACT_DEVELOPMENT;

type ContractModuleRegistrar = (file: ContractFileIR) => void;
let contractModuleRegistrar: ContractModuleRegistrar | null = null;

/**
 * Installs the dev-only IR-of-record registrar used by Contract HMR.
 * Production modules never install one, so their always-loaded component
 * definition path has no reachability edge to hot-patch machinery.
 */
export function setContractModuleRegistrar(
  registrar: ContractModuleRegistrar | null,
): void {
  contractModuleRegistrar = registrar;
}

export interface ComponentLinks {
  [importName: string]: unknown;
}

export type DeriveMemoRuntimePolicy =
  | { kind: 'shallow'; label: string }
  | {
      kind: 'comparator';
      label: string;
      comparator: (previous: unknown, next: unknown) => unknown;
    }
  | { kind: 'rows'; label: string; key: string };

export type DeriveMemoStabilizer = (next: unknown) => unknown;

/**
 * Optional runtime extensions injected by generated `.contract` modules.
 * Keeping this on the component handle (rather than in process-global state)
 * means an ordinary Contract module has no dependency on opt-in runtimes.
 */
export interface ContractComponentRuntimeOptions {
  createDeriveMemoStabilizer?: (
    policy: DeriveMemoRuntimePolicy,
  ) => DeriveMemoStabilizer;
  temporal?: {
    installScope(options: {
      scope: Scope;
      owner: Owner;
      hydrationNowMs?: number;
      clockAuthority?: ContractClockAuthority;
      registerHydrationRelease(release: () => void): void;
    }): void;
    installText(options: {
      expr: Expr;
      scope: Scope;
      textNode: TextNode;
      locus: ContractErrorLocus;
      reactiveOptions?: ReactiveNodeOptions;
    }): boolean;
  };
  hostBindings?: {
    setup(component: ComponentIR, scope: Scope, context: RuntimeContext, owner: Owner): void;
  };
  interactions?: ContractInteractionsRuntime;
  windows?: ContractWindowsRuntime;
  ephemerals?: ContractEphemeralsRuntime;
}

export interface CompiledComponent {
  readonly kind: 'contract-component';
  readonly name: string;
  readonly ir: ComponentIR;
  readonly file: ContractFileIR;
  readonly links: ComponentLinks;
  readonly runtime: ContractComponentRuntimeOptions;
  /** In-file components (public + private), resolvable from view nodes. */
  readonly fileComponents: ReadonlyMap<string, CompiledComponent>;
}

export function isCompiledComponent(value: unknown): value is CompiledComponent {
  return (
    typeof value === 'object' &&
    value !== null &&
    (value as { kind?: unknown }).kind === 'contract-component'
  );
}

/**
 * Builds compiled-component handles for a file. Returns the public component
 * (first declared); private components are reachable through
 * `fileComponents` and by name via `getFileComponent`.
 */
export function defineComponent(
  file: ContractFileIR,
  links: ComponentLinks = {},
  runtime: ContractComponentRuntimeOptions = {},
): CompiledComponent {
  if (fileUsesDeriveMemo(file) && !runtime.createDeriveMemoStabilizer) {
    throw new Error(
      '[contract] defineComponent: this Contract IR uses derive memoization, but no memo ' +
        'runtime was provided; compile the .contract module or pass ' +
        '{ createDeriveMemoStabilizer } as the third argument',
    );
  }
  // IR-of-record + hot-patch global (LLP 0166 §4.8) — installed by the
  // dev-only generated module prologue, absent from production reachability.
  contractModuleRegistrar?.(file);
  const fileComponents = new Map<string, CompiledComponent>();

  for (const componentIR of file.components) {
    fileComponents.set(componentIR.name, {
      kind: 'contract-component',
      name: componentIR.name,
      ir: componentIR,
      file,
      links,
      runtime,
      fileComponents,
    });
    // Design Mode metadata (LLP 0163 §5.3a) — dev-only, no-op in prod.
    if (CONTRACT_DEFINE_DEV) {
      registerComponentDesignMeta(componentIR, file.sourcePath);
    }
  }

  const publicComponent = fileComponents.get(file.components[0].name);
  if (!publicComponent) {
    throw new Error('[contract] defineComponent: file has no components');
  }
  return publicComponent;
}

function fileUsesDeriveMemo(file: ContractFileIR): boolean {
  return file.components.some((component) =>
    component.derives.some((derive) => derive.memo !== undefined),
  ) || (file.behaviorTemplates ?? []).some((template) =>
    template.derives.some((derive) => derive.memo !== undefined),
  );
}

export function getFileComponent(
  component: CompiledComponent,
  name: string,
): CompiledComponent | undefined {
  return component.fileComponents.get(name);
}
