// @system @ref LLP 0231 LLP 0362 scoping amendment, LLP 0373 phase 3c —
// narrow execution seam between Contract instances and the optional rich
// dev/agent dataflow inspector. The production runtime must not retain the
// registry, argument summarizer, action log, monitor, or inspection graph.

import type { ActionIR } from '../compiler/ir.js';
import type { ComponentInstance } from './instance.js';
import { setCurrentDataRootId } from './receipts.js';
import { runWithContractReactiveQueueOwner } from './signals.js';

interface ContractDataflowRuntimeHooks {
  primeSession(): void;
  allocateInstanceId(): string;
  registerInstance(instance: ComponentInstance): void;
  recordStateWrite(
    instance: ComponentInstance,
    name: string,
    before: unknown,
    after: unknown,
  ): void;
  currentActionInvocationId(
    runtime: ComponentInstance['ctx']['contractRuntime'],
  ): string | undefined;
  runActionWithLog<T>(
    instance: ComponentInstance,
    action: ActionIR,
    args: unknown[],
    fn: (runAttributed: <R>(work: () => R) => R) => T,
  ): T;
}

let hooks: ContractDataflowRuntimeHooks | null = null;
let productionInstanceCounter = 1;

/** Installed by dataflow-inspector.ts only in the editable/agent graph. */
export function installContractDataflowRuntimeHooks(
  next: ContractDataflowRuntimeHooks | null,
): void {
  hooks = next;
}

export function primeContractDataflowSession(): void {
  if (hooks) {
    hooks.primeSession();
    return;
  }
  // Preserve the current non-inspector production identity. The rich
  // inspector owns mount-epoch rollover when that composition is installed.
  setCurrentDataRootId('mount_1');
}

export function allocateContractRuntimeInstanceId(): string {
  if (hooks) return hooks.allocateInstanceId();
  primeContractDataflowSession();
  return `mount_1/ci_${productionInstanceCounter++}`;
}

export function registerContractDataflowInstance(instance: ComponentInstance): void {
  hooks?.registerInstance(instance);
}

export function recordContractStateWrite(
  instance: ComponentInstance,
  name: string,
  before: unknown,
  after: unknown,
): void {
  hooks?.recordStateWrite(instance, name, before, after);
}

export function currentContractActionInvocationId(
  runtime: ComponentInstance['ctx']['contractRuntime'],
): string | undefined {
  return hooks?.currentActionInvocationId(runtime);
}

export function runContractActionWithLog<T>(
  instance: ComponentInstance,
  action: ActionIR,
  args: unknown[],
  fn: (runAttributed: <R>(work: () => R) => R) => T,
): T {
  if (hooks) return hooks.runActionWithLog(instance, action, args, fn);
  return fn((work) => runWithContractReactiveQueueOwner(instance.ctx.contractRuntime, work));
}

export function resetContractDataflowRuntimeForTests(): void {
  productionInstanceCounter = 1;
}
