// ---------------------------------------------------------------------------
// keyboard — app-level key bindings.
//
//   use keyboard from "@exact/contract/runtime"
//   ...
//   task keys mount
//     keyboard("ArrowRight", next)
//     keyboard("Escape", close)
//
// The capability value is callable so task bodies stay in the bare-call
// statement grammar. Bindings are per-root; the single document listener is
// installed lazily and removed by the root owner on unmount/reset. Modifier
// chords are skipped (they belong to the host/browser), as are events
// targeted at editable elements.
//
// Two backings share the binder surface (ENG-22579):
// - web: a `document` keydown listener (native defines a window shim, so
//   `document` is the honest gate);
// - native: the host keyboard module (`com.exact.host.keyboard`) — JS syncs
//   the union of bound keys over the module-action channel, the host's key
//   monitor consumes exactly those plain (unmodified) keydowns and emits
//   them back as module events with web `KeyboardEvent.key` names. Hosts
//   without the module (a prerender process, an older native build) leave
//   the binder a silent no-op, same as before.
// ---------------------------------------------------------------------------

export type ContractKeyBinder = (key: string, action: () => void) => void;

const EDITABLE_TAGS = /* @__PURE__ */ new Set(["INPUT", "TEXTAREA", "SELECT"]);

const NATIVE_KEYBOARD_MODULE = "com.exact.host.keyboard";
/** Action id 0 = setKeys — pinned in HostKeyboardModule (Swift). */
const NATIVE_KEYBOARD_SET_KEYS_ACTION_ID = 0;
// @ref LLP 0150 idea 1 — module opcodes come from the generated OpCode table
// (authority: tests/protocol/protocol-inventory.json), never re-literaled.
const MODULE_ACTION_OPCODE: number = OpCode.ModuleAction;

interface NativeRuntimeBridge {
  getModuleMetadata?: (
    name: string,
  ) => { moduleId?: number } | null | undefined;
  dispatchModule?: (bytes: Uint8Array) => void;
}

type ModuleEventHandler = (event: string, payload: unknown) => void;

interface ModuleEventGlobals {
  exact?: NativeRuntimeBridge;
  __exactModuleEvent?: (
    module: string,
    event: string,
    ...rest: unknown[]
  ) => void;
  __exactModuleEventHandlers?: Map<string, ModuleEventHandler>;
}

function contractModuleEventGlobals(): ModuleEventGlobals {
  return globalThis as ModuleEventGlobals;
}

export interface NativeContractKeyEvent {
  readonly key: string;
  readonly rootId: number | null;
  /** Active modal host-node identity, used to exclude obscured owners. */
  readonly focusScopeViewId: number | null;
}

type NativeKeyAction = (event?: NativeContractKeyEvent) => void;
type KeyBindings = Map<string, NativeKeyAction>;

interface NativeKeyboardRootBindings {
  rootId: number;
  bindings: KeyBindings;
  contractActionScope: boolean;
}

const nativeKeyboardRoots = /* @__PURE__ */ new Set<NativeKeyboardRootBindings>();
let nativeKeyboardHandlerInstalled = false;
let nativeKeyboardDispatcherInstalled = false;
let nativeKeyboardCorrelationId = 1;
let nativeSyncedKeys: string | null = null;
const warnedChordSpellings = /* @__PURE__ */ new Set<string>();

// LLP 0336 §4.2 interim interlock (r11, ENG-24308): chord spellings are
// withheld from host registration entirely — a host key monitor consumes
// registered matches ahead of menu key-equivalent dispatch, so a synced
// "cmd+q" would shadow the host's own reserved command. The reserved-set
// authority replaces this filter; until then chords are inert on native.
function isChordSpelling(key: string): boolean {
  return key.length > 1 && key.includes("+");
}

function warnChordWithheld(key: string): void {
  if (warnedChordSpellings.has(key)) return;
  warnedChordSpellings.add(key);
  console.warn(
    `[contract] key "${key}" is a modifier chord; chords are not registered with native hosts until reserved-chord enforcement lands (LLP 0336 §4.2, ENG-24308) — the binding is inert on this platform`,
  );
}

function lookupKeyBinding(
  bindings: KeyBindings,
  key: string,
): NativeKeyAction | undefined {
  // "Space" is accepted as an author-friendly alias for the space bar.
  return bindings.get(key) ?? (key === " " ? bindings.get("Space") : undefined);
}

function encodeNativeModuleAction(
  moduleId: number,
  actionId: number,
  payload: Uint8Array,
): Uint8Array {
  const bytes = new Uint8Array(13 + payload.length);
  const view = new DataView(bytes.buffer);
  view.setUint8(0, MODULE_ACTION_OPCODE);
  view.setUint16(1, moduleId, true);
  view.setUint16(3, actionId, true);
  view.setUint32(5, nativeKeyboardCorrelationId++, true);
  view.setUint32(9, payload.length, true);
  bytes.set(payload, 13);
  return bytes;
}

function syncNativeKeyBindings(): void {
  const moduleEventGlobals = contractModuleEventGlobals();
  const bridge = moduleEventGlobals.exact;
  if (
    !bridge?.dispatchModule ||
    typeof bridge.getModuleMetadata !== "function"
  ) {
    return;
  }
  const keys = new Set<string>();
  for (const root of nativeKeyboardRoots) {
    for (const key of root.bindings.keys()) {
      if (isChordSpelling(key)) {
        warnChordWithheld(key);
        continue;
      }
      keys.add(key);
    }
  }
  const list = [...keys].sort();
  const serialized = JSON.stringify(list);
  if (serialized === nativeSyncedKeys) {
    return;
  }
  const moduleId = bridge.getModuleMetadata(NATIVE_KEYBOARD_MODULE)?.moduleId;
  if (!moduleId) {
    // Module not present on this host (prerender, an older native build) —
    // stay a no-op. macOS and iOS both ship it (ENG-22579 / ENG-22596).
    return;
  }
  bridge.dispatchModule(
    encodeNativeModuleAction(
      moduleId,
      NATIVE_KEYBOARD_SET_KEYS_ACTION_ID,
      new TextEncoder().encode(JSON.stringify({ keys: list })),
    ),
  );
  nativeSyncedKeys = serialized;
}

function decodeNativeKeyEvent(payload: unknown): NativeContractKeyEvent | null {
  let text: string | null = null;
  if (typeof payload === "string") {
    text = payload;
  } else if (payload instanceof Uint8Array) {
    text = new TextDecoder().decode(payload);
  } else if (payload instanceof ArrayBuffer) {
    text = new TextDecoder().decode(new Uint8Array(payload));
  } else if (payload !== null && typeof payload === "object") {
    const event = payload as {
      key?: unknown;
      rootId?: unknown;
      focusScopeViewId?: unknown;
    };
    return typeof event.key === "string"
      ? {
          key: event.key,
          rootId: typeof event.rootId === "number" ? event.rootId : null,
          focusScopeViewId:
            typeof event.focusScopeViewId === "number"
              ? event.focusScopeViewId
              : null,
        }
      : null;
  }
  if (text === null) {
    return null;
  }
  try {
    const parsed = JSON.parse(text) as {
      key?: unknown;
      rootId?: unknown;
      focusScopeViewId?: unknown;
    };
    return typeof parsed.key === "string"
      ? {
          key: parsed.key,
          rootId: typeof parsed.rootId === "number" ? parsed.rootId : null,
          focusScopeViewId:
            typeof parsed.focusScopeViewId === "number"
              ? parsed.focusScopeViewId
              : null,
        }
      : null;
  } catch {
    return null;
  }
}

function ensureNativeKeyboardHandlerInstalled(): void {
  if (nativeKeyboardHandlerInstalled) {
    return;
  }
  const moduleEventGlobals = contractModuleEventGlobals();
  if (typeof moduleEventGlobals.__exactModuleEventHandlers === "undefined") {
    moduleEventGlobals.__exactModuleEventHandlers = new Map();
  }
  if (!nativeKeyboardDispatcherInstalled) {
    const baseDispatcher = moduleEventGlobals.__exactModuleEvent;
    moduleEventGlobals.__exactModuleEvent = (
      module: string,
      event: string,
      ...rest: unknown[]
    ) => {
      const payload = rest.length > 1 ? rest[rest.length - 1] : rest[0];
      const handler =
        moduleEventGlobals.__exactModuleEventHandlers?.get(module);
      if (handler) {
        handler(event, payload);
        return;
      }
      if (baseDispatcher) {
        if (rest.length > 1 && baseDispatcher.length >= 4) {
          baseDispatcher(module, event, rest[0], payload);
          return;
        }
        baseDispatcher(module, event, payload);
        return;
      }
    };
    nativeKeyboardDispatcherInstalled = true;
  }
  moduleEventGlobals.__exactModuleEventHandlers.set(
    NATIVE_KEYBOARD_MODULE,
    (event, payload) => {
      if (event !== "keydown") {
        return;
      }
      const decoded = decodeNativeKeyEvent(payload);
      if (decoded === null) {
        return;
      }
      const eligible =
        decoded.rootId === null
          ? [...nativeKeyboardRoots]
          : [...nativeKeyboardRoots].filter(
              (root) => root.rootId === decoded.rootId,
            );
      const fallbackRootIds = new Set(eligible.map((root) => root.rootId));
      if (decoded.rootId === null && fallbackRootIds.size !== 1) return;
      for (const root of eligible) {
        const bound = lookupKeyBinding(root.bindings, decoded.key);
        if (bound) {
          try {
            if (root.contractActionScope) {
              batch(() => allowStateWrites(() => bound(decoded)));
            } else {
              bound(decoded);
            }
          } catch (error) {
            console.error(
              "[contract] native key dispatch failed",
              error instanceof Error
                ? (error.stack ?? error.message)
                : String(error),
            );
          }
        }
      }
    },
  );
  nativeKeyboardHandlerInstalled = true;
}

function assertKeyBindingArgs(key: string, action: unknown): void {
  if (typeof key !== "string" || key.length === 0) {
    throw new Error("[contract] keyboard(key, action) requires a key name");
  }
  if (typeof action !== "function") {
    throw new Error("[contract] keyboard(key, action) requires an action");
  }
}

export const keyboard = /* @__PURE__ */ defineCapability<ContractKeyBinder>({
  id: "contract.keyboard",
  effects: ["host:keyboard"],
  instantiate({ owner, rootId }) {
    if (typeof document === "undefined") {
      const bindings: KeyBindings = new Map();
      const rootBindings: NativeKeyboardRootBindings = {
        rootId,
        bindings,
        contractActionScope: true,
      };
      let attached = false;
      const attach = () => {
        if (attached) {
          return;
        }
        attached = true;
        ensureNativeKeyboardHandlerInstalled();
        nativeKeyboardRoots.add(rootBindings);
        owner.register(() => {
          nativeKeyboardRoots.delete(rootBindings);
          bindings.clear();
          syncNativeKeyBindings();
        });
      };
      return (key: string, action: () => void) => {
        assertKeyBindingArgs(key, action);
        attach();
        bindings.set(key, () => action());
        syncNativeKeyBindings();
      };
    }
    const bindings = new Map<string, () => void>();
    let listener: ((event: KeyboardEvent) => void) | null = null;
    const ensureListener = () => {
      if (listener) {
        return;
      }
      listener = (event: KeyboardEvent) => {
        if (event.metaKey || event.ctrlKey || event.altKey) {
          return;
        }
        const target = event.target as HTMLElement | null;
        if (
          target &&
          (EDITABLE_TAGS.has(target.tagName) || target.isContentEditable)
        ) {
          return;
        }
        const bound = lookupKeyBinding(bindings, event.key);
        if (!bound) {
          return;
        }
        event.preventDefault();
        batch(() => allowStateWrites(() => bound()));
      };
      document.addEventListener("keydown", listener);
      owner.register(() => {
        if (listener) {
          document.removeEventListener("keydown", listener);
          listener = null;
        }
        bindings.clear();
      });
    };
    return (key: string, action: () => void) => {
      assertKeyBindingArgs(key, action);
      ensureListener();
      bindings.set(key, action);
    };
  },
});

/** Internal LLP 0336 native scope-engine registration. */
export function registerNativeContractKeyBinding(
  rootId: number,
  key: string,
  action: (event: NativeContractKeyEvent) => void,
  owner?: Owner,
): () => void {
  if (typeof document !== "undefined") return () => {};
  assertKeyBindingArgs(key, action);
  ensureNativeKeyboardHandlerInstalled();
  const root: NativeKeyboardRootBindings = {
    rootId,
    bindings: new Map([
      [
        key,
        (event) => {
          if (event) action(event);
        },
      ],
    ]),
    contractActionScope: false,
  };
  nativeKeyboardRoots.add(root);
  syncNativeKeyBindings();
  let disposed = false;
  const dispose = (): void => {
    if (disposed) return;
    disposed = true;
    nativeKeyboardRoots.delete(root);
    root.bindings.clear();
    syncNativeKeyBindings();
  };
  owner?.register(dispose);
  return dispose;
}

