// @system @ref LLP 0373 P0 — the logical-subscription registry: same-key
// deduplication with refcounted disposal, logical-layer generation fencing,
// and partition rotation (atomic fence-and-resubscribe).
//
// Layered per LLP 0373 §4 P0:
// - component binding instances (layer 1) subscribe here and dispose
//   independently; disposal is refcounted against the logical attempt;
// - one LOGICAL subscription (layer 2, keyed by `logicalQueryKeyString`)
//   holds at most one underlying provider subscription (layer 3) —
//   simultaneous same-key bindings share the attempt's data/error/connection
//   state; different-key or different-partition bindings are fully isolated;
// - a retired or rotated-away entry is FENCED: late/straggler deliveries
//   from its provider subscription are dropped, never published to bindings
//   (fail-closed — retained rows from a prior partition are never delivered
//   after rotation).
//
// Physical transport sharing below the provider seam remains a provider
// capability fact and is never assumed here (layer 4).

import type {
  ContractDataProvider,
  DataCellV2,
  DataObserver,
  DataProviderDiagnostic,
  DataSubscription,
  SerializedError,
} from './data-provider.js';
import {
  logicalQueryKeyString,
  onPartitionRotation,
  providerLogicalQueryKey,
  QueryArgsCanonicalizationError,
} from './query-identity.js';
import { getContractErrorLocus } from './error-locus-runtime.js';

// ---------------------------------------------------------------------------
// Structured refusal diagnostics (LLP 0373 P0 item: invalid arguments and
// provider refusal surface as source-attributed diagnostics, never uncaught)
// ---------------------------------------------------------------------------

/**
 * The error payload a refused subscription delivers through the query cell
 * error state: a `SerializedError` (so every existing consumer renders it)
 * carrying the full `DataProviderDiagnostic` for structured consumers.
 */
export interface DataQueryScopeDiagnosticError extends SerializedError {
  diagnostic: DataProviderDiagnostic;
}

export function isDataQueryScopeDiagnosticError(
  value: unknown,
): value is DataQueryScopeDiagnosticError {
  return Boolean(
    value &&
      typeof value === 'object' &&
      typeof (value as { message?: unknown }).message === 'string' &&
      typeof (value as { diagnostic?: unknown }).diagnostic === 'object' &&
      (value as { diagnostic?: unknown }).diagnostic !== null,
  );
}

function diagnosticErrorCell(diagnostic: DataProviderDiagnostic): DataCellV2 {
  const error: DataQueryScopeDiagnosticError = {
    message: diagnostic.message,
    name: 'ContractQueryScopeError',
    diagnostic,
  };
  return { status: 'error', error };
}

function providerName(provider: ContractDataProvider): string {
  return provider.manifest?.provider ?? 'unknown';
}

function sourceAttributionFor(thrown: unknown): DataProviderDiagnostic['source'] | undefined {
  // Provider-attached source wins (a provider may throw a diagnostic-shaped
  // refusal); the contract error locus is the fallback attribution.
  const attached = (thrown as { source?: unknown } | null)?.source;
  if (attached && typeof attached === 'object') {
    return attached as DataProviderDiagnostic['source'];
  }
  const locus = getContractErrorLocus(thrown);
  if (locus?.sourcePath !== undefined || locus?.span !== undefined) {
    return {
      ...(locus.sourcePath !== undefined ? { file: locus.sourcePath } : {}),
      ...(locus.span !== undefined ? { line: locus.span.line, column: locus.span.col } : {}),
    };
  }
  return undefined;
}

function invalidArgsDiagnostic(
  provider: ContractDataProvider,
  queryName: string,
  thrown: QueryArgsCanonicalizationError,
): DataProviderDiagnostic {
  return {
    code: thrown.code,
    severity: 'error',
    message: `query "${queryName}": ${thrown.message}`,
    provider: providerName(provider),
    owner: 'contract',
    queryName,
    suggestedFix:
      'Query arguments must be plain JSON-canonicalizable data (finite numbers, strings, booleans, null, plain objects/arrays); drop or serialize the offending value.',
  };
}

function subscribeRefusalDiagnostic(
  provider: ContractDataProvider,
  queryName: string,
  thrown: unknown,
): DataProviderDiagnostic {
  const source = sourceAttributionFor(thrown);
  return {
    code: 'contract_query_subscribe_refused',
    severity: 'error',
    message:
      thrown instanceof Error
        ? `query "${queryName}" subscription refused: ${thrown.message}`
        : `query "${queryName}" subscription refused: ${String(thrown)}`,
    provider: providerName(provider),
    owner: 'provider',
    queryName,
    ...(source ? { source } : {}),
  };
}

// ---------------------------------------------------------------------------
// The registry
// ---------------------------------------------------------------------------

interface LogicalBindingRecord {
  observer: DataObserver<unknown>;
  entry: LogicalEntry | null;
  disposed: boolean;
}

interface LogicalEntry {
  keyString: string;
  provider: ContractDataProvider;
  queryName: string;
  args: Record<string, unknown>;
  bindings: Set<LogicalBindingRecord>;
  upstream: DataSubscription | null;
  /** The attempt's shared state — replayed synchronously to late same-key joiners. */
  lastCell: DataCellV2 | undefined;
  /**
   * Fenced entries drop every further upstream delivery (retirement,
   * supersession, partition rotation — the logical-layer generation fence).
   */
  fenced: boolean;
  /**
   * Boot-settled latch state (LLP 0391 §4.4): set once, on the attempt's
   * first authoritative cell (`ready` or `error`), and replayed
   * synchronously to late listeners like `lastCell`. Disposed with the
   * entry.
   */
  bootSettled: BootSettledOutcome | undefined;
}

const registry = new Map<string, LogicalEntry>();

function deliverToBindings(entry: LogicalEntry, cell: DataCellV2): void {
  for (const binding of [...entry.bindings]) {
    if (!binding.disposed) {
      binding.observer(cell);
    }
  }
}

// ---------------------------------------------------------------------------
// Boot-settled first-snapshot latch (LLP 0391 §4.4)
// ---------------------------------------------------------------------------
//
// @system @ref LLP 0391 §4.4 — runtime-owned first-snapshot latch at the
// logical query delivery layer. Keyed by logical query identity, it settles
// on the FIRST authoritative cell (`ready` OR `error`) the attempt delivers,
// replays its settled state synchronously to late listeners (the `lastCell`
// replay pattern), and is disposed with its logical entry: listeners still
// pending when the entry retires get a deterministic disposal notification,
// never silence. Providers implement nothing for it — the latch derives
// entirely from deliveries the runtime already observes.
//
// This is a BOOT-SETTLED signal, not a hydration signal: it settles on local
// truth, so a provider serving an empty local store synchronously settles it
// on `ready` + `empty` even while the server has data (LLP 0392 F10 — the
// empty-state flash is a policy question above this latch, not something the
// latch reports).

/** The settled half of a boot-settled notification (LLP 0391 §4.4). */
export interface BootSettledOutcome {
  readonly kind: 'settled';
  /** The authoritative status the latch settled on. */
  readonly status: 'ready' | 'error';
  /** The settling cell (the attempt's first authoritative delivery). */
  readonly cell: DataCellV2;
}

/**
 * What a boot-settled listener receives, exactly once: the settled outcome,
 * or a disposal notification when the logical entry retired before settling
 * (LLP 0391 §4.4 — deterministic, never silence).
 */
export type BootSettledNotification = BootSettledOutcome | { readonly kind: 'disposed' };

interface BootSettledWaiter {
  notify: (notification: BootSettledNotification) => void;
  notified: boolean;
}

/** Listeners waiting for a key that has not settled yet (or has no entry yet). */
const bootWaiters = new Map<string, Set<BootSettledWaiter>>();

function notifyBootWaiters(keyString: string, notification: BootSettledNotification): void {
  const waiters = bootWaiters.get(keyString);
  if (!waiters) {
    return;
  }
  bootWaiters.delete(keyString);
  for (const waiter of [...waiters]) {
    if (!waiter.notified) {
      waiter.notified = true;
      waiter.notify(notification);
    }
  }
}

function settleBootLatch(entry: LogicalEntry, cell: DataCellV2): void {
  if (entry.bootSettled !== undefined || (cell.status !== 'ready' && cell.status !== 'error')) {
    return;
  }
  entry.bootSettled = { kind: 'settled', status: cell.status, cell };
  notifyBootWaiters(entry.keyString, entry.bootSettled);
}

function startUpstream(entry: LogicalEntry): void {
  try {
    entry.upstream = entry.provider.subscribe<unknown>(
      entry.queryName,
      entry.args,
      (cell) => {
        // Logical-layer fence: a retired/rotated entry (or one superseded in
        // the registry) never publishes a late delivery.
        if (entry.fenced || registry.get(entry.keyString) !== entry) {
          return;
        }
        entry.lastCell = cell;
        deliverToBindings(entry, cell);
        settleBootLatch(entry, cell);
      },
    );
    // The provider may have delivered synchronously AND disposed of the last
    // binding re-entrantly; if the entry retired during subscribe, drop the
    // upstream immediately.
    if (entry.fenced) {
      const upstream = entry.upstream;
      entry.upstream = null;
      upstream?.dispose();
    }
  } catch (thrown) {
    // Provider refused synchronously at subscribe: structured diagnostic
    // through the error state — shared by same-key siblings like any other
    // attempt state — never an uncaught throw.
    const cell = diagnosticErrorCell(subscribeRefusalDiagnostic(entry.provider, entry.queryName, thrown));
    entry.lastCell = cell;
    deliverToBindings(entry, cell);
    settleBootLatch(entry, cell);
  }
}

function retireEntry(entry: LogicalEntry): void {
  entry.fenced = true;
  if (registry.get(entry.keyString) === entry) {
    registry.delete(entry.keyString);
  }
  const upstream = entry.upstream;
  entry.upstream = null;
  upstream?.dispose();
  // LLP 0391 §4.4: the latch is disposed with its logical entry — listeners
  // still pending get the deterministic disposal notification. When the key
  // is already occupied by a successor entry (supersession/rotation races),
  // pending waiters ride the successor's latch instead.
  if (entry.bootSettled === undefined && registry.get(entry.keyString) === undefined) {
    notifyBootWaiters(entry.keyString, { kind: 'disposed' });
  }
}

function createEntry(
  keyString: string,
  provider: ContractDataProvider,
  queryName: string,
  args: Record<string, unknown>,
): LogicalEntry {
  const entry: LogicalEntry = {
    keyString,
    provider,
    queryName,
    args,
    bindings: new Set(),
    upstream: null,
    lastCell: undefined,
    fenced: false,
    bootSettled: undefined,
  };
  registry.set(keyString, entry);
  return entry;
}

function attachBinding(entry: LogicalEntry, binding: LogicalBindingRecord): void {
  binding.entry = entry;
  entry.bindings.add(binding);
}

function noopSubscription(): DataSubscription {
  return { dispose() {} };
}

/**
 * Subscribe a component binding instance to a provider query through the
 * logical-subscription registry (LLP 0373 P0). Same-key simultaneous
 * bindings share ONE underlying provider subscription with refcounted
 * disposal (the last unref disposes it); different-key/different-partition
 * bindings are fully isolated. Invalid arguments and synchronous provider
 * refusal surface as structured diagnostics through the cell error state.
 */
export function subscribeLogicalQuery<T>(
  provider: ContractDataProvider,
  queryName: string,
  args: Record<string, unknown>,
  observer: DataObserver<T>,
): DataSubscription {
  let keyString: string;
  try {
    keyString = logicalQueryKeyStringFor(provider, queryName, args);
  } catch (thrown) {
    if (thrown instanceof QueryArgsCanonicalizationError) {
      observer(diagnosticErrorCell(invalidArgsDiagnostic(provider, queryName, thrown)) as DataCellV2<T>);
      return noopSubscription();
    }
    throw thrown;
  }

  const binding: LogicalBindingRecord = {
    observer: observer as DataObserver<unknown>,
    entry: null,
    disposed: false,
  };

  const existing = registry.get(keyString);
  if (existing && !existing.fenced) {
    attachBinding(existing, binding);
    // Share the attempt's current state synchronously (data, error, and
    // connection all ride the cell).
    if (existing.lastCell !== undefined) {
      binding.observer(existing.lastCell);
    }
  } else {
    const entry = createEntry(keyString, provider, queryName, args);
    attachBinding(entry, binding);
    startUpstream(entry);
  }

  return {
    dispose() {
      if (binding.disposed) {
        return;
      }
      binding.disposed = true;
      const entry = binding.entry;
      binding.entry = null;
      if (!entry) {
        return;
      }
      entry.bindings.delete(binding);
      if (entry.bindings.size === 0) {
        retireEntry(entry);
      }
    },
  };
}

/**
 * The logical key string a provider query handle carries (`provider:<key>`
 * prefixed by the caller). Throws `QueryArgsCanonicalizationError` on
 * non-canonicalizable arguments.
 */
export function logicalQueryKeyStringFor(
  provider: ContractDataProvider,
  queryName: string,
  args: Record<string, unknown>,
): string {
  return logicalQueryKeyString(providerLogicalQueryKey(provider, queryName, args));
}

/**
 * Wait for one logical query to boot-settle (LLP 0391 §4.4). The listener is
 * invoked exactly once — synchronously when the attempt already settled
 * (the `lastCell` replay pattern), otherwise on the first authoritative cell
 * (`ready` or `error`), or with `{ kind: 'disposed' }` when the logical
 * entry retires before settling. A listener registered before any same-key
 * subscription exists waits for the first attempt that settles under that
 * key. Non-canonicalizable arguments settle synchronously on the same
 * structured error cell a binding would observe.
 *
 * Boot-settled is NOT a hydration signal: an empty local store settles it on
 * `ready` + `empty` (LLP 0392 F10). Providers implement nothing for this.
 *
 * The returned subscription cancels the wait; disposal after notification is
 * a no-op.
 */
export function onBootSettled(
  provider: ContractDataProvider,
  queryName: string,
  args: Record<string, unknown>,
  listener: (notification: BootSettledNotification) => void,
): DataSubscription {
  let keyString: string;
  try {
    keyString = logicalQueryKeyStringFor(provider, queryName, args);
  } catch (thrown) {
    if (thrown instanceof QueryArgsCanonicalizationError) {
      // Delivery-layer truth: the matching subscription would deliver this
      // structured error cell, so the latch settles on it deterministically.
      listener({
        kind: 'settled',
        status: 'error',
        cell: diagnosticErrorCell(invalidArgsDiagnostic(provider, queryName, thrown)),
      });
      return noopSubscription();
    }
    throw thrown;
  }

  const entry = registry.get(keyString);
  if (entry && !entry.fenced && entry.bootSettled !== undefined) {
    listener(entry.bootSettled);
    return noopSubscription();
  }

  const waiter: BootSettledWaiter = { notify: listener, notified: false };
  let waiters = bootWaiters.get(keyString);
  if (!waiters) {
    waiters = new Set();
    bootWaiters.set(keyString, waiters);
  }
  waiters.add(waiter);
  return {
    dispose() {
      if (waiter.notified) {
        return;
      }
      waiter.notified = true;
      const current = bootWaiters.get(keyString);
      current?.delete(waiter);
      if (current && current.size === 0) {
        bootWaiters.delete(keyString);
      }
    },
  };
}

/** One query of a boot-settled aggregate barrier (LLP 0391 §4.4). */
export interface BootSettledQueryRef {
  queryName: string;
  args?: Record<string, unknown>;
}

/**
 * Aggregate boot-settled barrier (LLP 0391 §4.4): resolves when every listed
 * logical query has boot-settled (or its entry was disposed unsettled), with
 * the per-query notifications in input order. Composes `onBootSettled` —
 * same keying, same settle-on-local-truth semantics (LLP 0392 F10) — and
 * never rejects: disposal is a notification, not an error.
 */
export function whenBootSettled(
  provider: ContractDataProvider,
  queries: readonly BootSettledQueryRef[],
): Promise<BootSettledNotification[]> {
  if (queries.length === 0) {
    return Promise.resolve([]);
  }
  return new Promise((resolveBarrier) => {
    const results = new Array<BootSettledNotification>(queries.length);
    let remaining = queries.length;
    queries.forEach((query, index) => {
      onBootSettled(provider, query.queryName, query.args ?? {}, (notification) => {
        results[index] = notification;
        remaining -= 1;
        if (remaining === 0) {
          resolveBarrier(results);
        }
      });
    });
  });
}

/** Test/introspection: the number of live logical subscriptions. */
export function activeLogicalQuerySubscriptionCount(): number {
  return registry.size;
}

// ---------------------------------------------------------------------------
// Read-only inspection (LLP 0231 Amendment A1 / LLP 0373 §4 P1)
// ---------------------------------------------------------------------------

/**
 * The shared attempt state of one logical subscription as plain data:
 * the data axis (`no-delivery` before the first cell, else the cell status),
 * the orthogonal LLP 0284 §2.2 connection axis, and — for error attempts —
 * the serialized error with its structured `DataProviderDiagnostic` when the
 * refusal carried one. Error stacks are deliberately dropped (message + name
 * only) so the inspection surface never leaks stack frames.
 */
export interface LogicalSubscriptionAttemptInspection {
  status: 'no-delivery' | 'pending' | 'ready' | 'refreshing' | 'error';
  connection?: DataCellV2['connection'];
  /** `ready` cells only. */
  empty?: boolean;
  /** True when a pending/error cell still carries retained previous rows. */
  hasPrevious?: boolean;
  error?: SerializedError;
  diagnostic?: DataProviderDiagnostic;
}

/** One live logical subscription (registry layer 2), as plain data. */
export interface LogicalSubscriptionInspection {
  /** The joined logical key encoding (JSON-array framing). */
  keyString: string;
  /** The four key positions as opaque display strings (LLP 0373 P0). */
  key: {
    partition: string;
    descriptorId: string;
    compatibilityToken: string;
    canonicalArgs: string;
  };
  /** `manifest.provider` of the owning provider. */
  provider: string;
  queryName: string;
  /** Live component binding instances sharing this attempt (layer 1). */
  refCount: number;
  fenced: boolean;
  /** Whether an underlying provider subscription (layer 3) is held. */
  hasUpstream: boolean;
  attempt: LogicalSubscriptionAttemptInspection;
}

function inspectAttempt(cell: DataCellV2 | undefined): LogicalSubscriptionAttemptInspection {
  if (cell === undefined) {
    return { status: 'no-delivery' };
  }
  const attempt: LogicalSubscriptionAttemptInspection = { status: cell.status };
  if (cell.connection !== undefined) {
    attempt.connection = cell.connection;
  }
  if (cell.status === 'ready') {
    attempt.empty = cell.empty;
  }
  if ((cell.status === 'pending' || cell.status === 'error') && cell.previous !== undefined) {
    attempt.hasPrevious = true;
  }
  if (cell.status === 'error') {
    attempt.error = {
      message: cell.error.message,
      ...(cell.error.name !== undefined ? { name: cell.error.name } : {}),
    };
    if (isDataQueryScopeDiagnosticError(cell.error)) {
      attempt.diagnostic = cell.error.diagnostic;
    }
  }
  return attempt;
}

/**
 * Read-only inspection export over the live logical-subscription registry
 * (LLP 0231 A1's query/provider binding graph; LLP 0373 §4 P1). Returns
 * plain data only — no live registry objects escape — and never mutates
 * registry state.
 */
export function inspectLogicalSubscriptions(): LogicalSubscriptionInspection[] {
  return [...registry.values()].map((entry) => {
    let key = {
      partition: '',
      descriptorId: '',
      compatibilityToken: '',
      canonicalArgs: '',
    };
    try {
      const parsed: unknown = JSON.parse(entry.keyString);
      if (
        Array.isArray(parsed) &&
        parsed.length === 4 &&
        parsed.every((part): part is string => typeof part === 'string')
      ) {
        key = {
          partition: parsed[0],
          descriptorId: parsed[1],
          compatibilityToken: parsed[2],
          canonicalArgs: parsed[3],
        };
      }
    } catch {
      // Key stays opaque-empty; keyString remains the truth.
    }
    return {
      keyString: entry.keyString,
      key,
      provider: providerName(entry.provider),
      queryName: entry.queryName,
      refCount: entry.bindings.size,
      fenced: entry.fenced,
      hasUpstream: entry.upstream !== null,
      attempt: inspectAttempt(entry.lastCell),
    };
  });
}

/** Test hygiene: drop every live logical subscription (disposes upstreams). */
export function resetLogicalQuerySubscriptionsForTests(): void {
  for (const entry of [...registry.values()]) {
    for (const binding of entry.bindings) {
      binding.disposed = true;
      binding.entry = null;
    }
    entry.bindings.clear();
    retireEntry(entry);
  }
  registry.clear();
  // Boot-settled waiters with no live entry (LLP 0391 §4.4): disposal
  // notification, never silence — then a clean slate.
  for (const keyString of [...bootWaiters.keys()]) {
    notifyBootWaiters(keyString, { kind: 'disposed' });
  }
  bootWaiters.clear();
}

// ---------------------------------------------------------------------------
// Partition rotation: atomic fence-and-resubscribe (LLP 0373 P0)
// ---------------------------------------------------------------------------
//
// Registered once at module load. For each of the provider's live entries:
// 1. FENCE — the old attempt stops delivering immediately and its upstream
//    is disposed (fail-closed: retained rows from the prior partition are
//    never delivered after rotation).
// 2. RESET — surviving bindings receive a pending cell with cleared previous
//    rows so prior-partition data cannot linger as current.
// 3. RESUBSCRIBE — the same bindings re-key under the new partition and one
//    fresh provider subscription starts (or they join an existing entry for
//    the new key).

onPartitionRotation((provider) => {
  const affected = [...registry.values()].filter((entry) => entry.provider === provider);
  for (const entry of affected) {
    // 1. Fence-and-dispose the prior-partition attempt.
    retireEntry(entry);
    const survivors = [...entry.bindings].filter((binding) => !binding.disposed);
    entry.bindings.clear();
    if (survivors.length === 0) {
      continue;
    }

    // 2. Fail-closed reset: `previous: []` clears retained rows at the
    // handle seam (rows-for-cell falls back to `previous`, never to the
    // prior partition's last rows).
    const resetCell: DataCellV2 = { status: 'pending', previous: [] };
    for (const binding of survivors) {
      binding.entry = null;
      binding.observer(resetCell);
    }

    // 3. Resubscribe under the new partition.
    let nextKeyString: string;
    try {
      nextKeyString = logicalQueryKeyStringFor(provider, entry.queryName, entry.args);
    } catch (thrown) {
      if (thrown instanceof QueryArgsCanonicalizationError) {
        const cell = diagnosticErrorCell(invalidArgsDiagnostic(provider, entry.queryName, thrown));
        for (const binding of survivors) {
          if (!binding.disposed) {
            binding.observer(cell);
          }
        }
        continue;
      }
      throw thrown;
    }
    let nextEntry = registry.get(nextKeyString);
    const fresh = !nextEntry || nextEntry.fenced;
    if (!nextEntry || nextEntry.fenced) {
      nextEntry = createEntry(nextKeyString, provider, entry.queryName, entry.args);
    }
    for (const binding of survivors) {
      if (!binding.disposed) {
        attachBinding(nextEntry, binding);
      }
    }
    if (fresh) {
      startUpstream(nextEntry);
    } else if (nextEntry.lastCell !== undefined) {
      for (const binding of survivors) {
        if (!binding.disposed) {
          binding.observer(nextEntry.lastCell);
        }
      }
    }
  }
});
