// @system @ref LLP 0157 §2 / LLP 0373 phase 3c — lightweight host-fed
// theme inputs. Full scope resolution subscribes from theme-store.ts, but a
// host can publish preferences without retaining the complete theme engine.

import type { Scheme } from './internals.js';
import { createHostInput } from './store-machinery.js';

const systemAppearanceInput = createHostInput<Scheme>('light');
const reducedMotionInput = createHostInput<boolean>(false);
const viewportWidthInput = createHostInput<number>(390);

export function setThemeSystemAppearance(scheme: Scheme): void {
  systemAppearanceInput.set(scheme);
}

export function getThemeSystemAppearance(): Scheme {
  return systemAppearanceInput.get();
}

export function setThemeReducedMotion(reducedMotion: boolean): void {
  reducedMotionInput.set(reducedMotion);
}

export function getThemeReducedMotion(): boolean {
  return reducedMotionInput.get();
}

export function setThemeViewportWidth(width: number): void {
  viewportWidthInput.set(Number.isFinite(width) ? Math.max(0, width) : 0);
}

export function getThemeViewportWidth(): number {
  return viewportWidthInput.get();
}

export function subscribeThemeSystemAppearance(listener: () => void): () => void {
  return systemAppearanceInput.subscribe(listener);
}

export function subscribeThemeReducedMotion(listener: () => void): () => void {
  return reducedMotionInput.subscribe(listener);
}

export function subscribeThemeViewportWidth(listener: () => void): () => void {
  return viewportWidthInput.subscribe(listener);
}

export function resetThemeHostInputsForTesting(): void {
  systemAppearanceInput.set('light');
  reducedMotionInput.set(false);
  viewportWidthInput.set(390);
}
