// @system @ref LLP 0393 — Contract video: the player-id registry.
//
// Live objects never travel through host props (the graphics-surface /
// pager-binding registry pattern): the mount path stamps the synthesized
// VideoView element with a `data-exact-video-player-id` string and registers
// the live engine player here; the web adoption hook in the renderer
// (dom-mirror / web-host-direct) resolves it back through the global getter.

export interface RegisteredContractVideoPlayer {
  /** Opaque engine player handle (an `ExactVideoPlayer` in production). */
  player: unknown;
  /** Serialized view config for the adopting web backend. */
  viewConfig: string;
}

const registeredPlayers = new Map<string, RegisteredContractVideoPlayer>();

export function registerContractVideoPlayer(
  playerKey: string,
  entry: RegisteredContractVideoPlayer,
): void {
  registeredPlayers.set(playerKey, entry);
  (globalThis as {
    __exactGetContractVideoPlayer?: (
      id: string,
    ) => RegisteredContractVideoPlayer | undefined;
  }).__exactGetContractVideoPlayer = (id) => registeredPlayers.get(id);
}

export function unregisterContractVideoPlayer(playerKey: string): void {
  registeredPlayers.delete(playerKey);
}
