// @system @ref LLP 0352 §6.1 / LLP 0373 P1 — graphics backends are
// compiler-selected production capabilities. Ordinary web hosts retain only
// this inert seam; a generated module that authors graphics installs the
// Canvas2D backend before mount.

export interface GraphicsCanvas2dBackend {
  ensure(el: HTMLElement): void;
  dispose(el: HTMLElement): void;
}

let registeredBackend: GraphicsCanvas2dBackend | null = null;

export function registerGraphicsCanvas2dBackend(
  backend: GraphicsCanvas2dBackend,
): void {
  registeredBackend = backend;
}

export function ensureGraphicsCanvas2dBackend(el: HTMLElement): void {
  registeredBackend?.ensure(el);
}

export function disposeGraphicsCanvas2dBackend(el: HTMLElement): void {
  registeredBackend?.dispose(el);
}
