// @system @ref LLP 0364 — web lowering for the image color matrix.
//
// CSS has no general color-matrix function, so the honest browser lowering is
// `filter: url(#id)` against an inline SVG `<feColorMatrix>`. The description
// half of this module is pure (no DOM reads or writes) so the live DOM host and
// the static serializer agree on the id and the CSS value; the `*Def` helpers
// below own the one document-level `<defs>` container the live host injects.

import {
  canonicalizeImageColorMatrix,
  normalizeImageColorMatrix,
} from './props/image-color-matrix.js';
import type { ImageColorMatrix } from './types.js';

export interface ImageColorMatrixFilter {
  /** Stable across hosts and reloads: derived only from the matrix values. */
  id: string;
  /** Canonical wire form (20 comma-separated numbers). */
  canonicalMatrix: string;
  /** The `values` attribute of the `<feColorMatrix>` (space separated). */
  filterValues: string;
  /** CSS `filter` value referencing the def. */
  cssValue: string;
}

const FILTER_ID_PREFIX = 'exact-color-matrix-';
const DEFS_CONTAINER_ATTR = 'data-exact-color-matrix-defs';
/** The authored intent, mirrored onto the element for inspection/hydration. */
export const IMAGE_COLOR_MATRIX_ATTR = 'data-exact-color-matrix';

/**
 * Two independent 32-bit hashes over the canonical matrix. The id must be a
 * pure function of the values (the static serializer and the live host mint it
 * separately), so it cannot come from a counter; 64 bits of digest keeps a
 * cross-matrix id collision out of practical reach.
 */
function matrixDigest(canonicalMatrix: string): string {
  let fnv = 0x811c9dc5;
  let djb = 5381;
  for (let index = 0; index < canonicalMatrix.length; index += 1) {
    const code = canonicalMatrix.charCodeAt(index);
    fnv = Math.imul(fnv ^ code, 0x01000193) >>> 0;
    djb = (Math.imul(djb, 33) ^ code) >>> 0;
  }
  return fnv.toString(16).padStart(8, '0') + djb.toString(16).padStart(8, '0');
}

export function imageColorMatrixFilterId(canonicalMatrix: string): string {
  return `${FILTER_ID_PREFIX}${matrixDigest(canonicalMatrix)}`;
}

/**
 * Describe the filter for an already-canonical prop value. Returns undefined
 * for absent or malformed values — the caller then emits no filter at all
 * rather than a dangling `url(#…)` reference, which browsers treat as
 * "do not render this element."
 */
export function lowerImageColorMatrixFilter(
  canonicalMatrix: unknown,
): ImageColorMatrixFilter | undefined {
  const matrix = normalizeImageColorMatrix(canonicalMatrix);
  if (matrix === undefined) return undefined;
  const canonical = canonicalizeImageColorMatrix(matrix);
  const id = imageColorMatrixFilterId(canonical);
  return {
    id,
    canonicalMatrix: canonical,
    filterValues: filterValuesFor(matrix),
    cssValue: `url(#${id})`,
  };
}

function filterValuesFor(matrix: ImageColorMatrix): string {
  return matrix.map((component) => String(component)).join(' ');
}

// --- Live DOM defs container -------------------------------------------------

const SVG_NS = 'http://www.w3.org/2000/svg';

/**
 * Id index for the live `<defs>` element: dedupe must stay O(1) per apply —
 * an animated matrix mints one distinct id per slider position, so a child
 * scan makes a drag O(n²). Keyed by the defs element itself so a reset or
 * host teardown drops the index with the container, and a container adopted
 * from server bytes is indexed lazily on first use.
 */
const defIdIndex = new WeakMap<Element, Set<string>>();

/**
 * Hook-held references (the React tier). A def a mounted hook instance still
 * references must survive the sweep even while no committed element carries
 * the intent attribute yet — `useInsertionEffect` runs before React's DOM
 * mutations. Counted, not a set: several images may share one matrix.
 */
const defRefCounts = new WeakMap<Document, Map<string, number>>();
const scheduledSweeps = new WeakSet<Document>();

function defsContainer(doc: Document): SVGSVGElement | null {
  return doc.querySelector<SVGSVGElement>(`svg[${DEFS_CONTAINER_ATTR}]`);
}

function ensureDefsContainer(doc: Document): SVGSVGElement | null {
  const existing = defsContainer(doc);
  if (existing) return existing;
  const host = doc.body ?? doc.documentElement;
  if (!host) return null;
  const svg = doc.createElementNS(SVG_NS, 'svg');
  svg.setAttribute(DEFS_CONTAINER_ATTR, '');
  svg.setAttribute('aria-hidden', 'true');
  svg.setAttribute('focusable', 'false');
  // A zero-size absolutely positioned container, not `display: none`: some
  // engines stop resolving paint servers inside a display:none subtree.
  svg.setAttribute(
    'style',
    'position:absolute;width:0;height:0;overflow:hidden;pointer-events:none',
  );
  svg.appendChild(doc.createElementNS(SVG_NS, 'defs'));
  host.appendChild(svg);
  return svg;
}

/**
 * Materialize the `<filter>` for a description, deduplicated by filter id.
 * Idempotent: re-applying the same matrix to another node is a no-op.
 */
export function ensureImageColorMatrixFilterDef(
  doc: Document,
  filter: ImageColorMatrixFilter,
): void {
  const container = ensureDefsContainer(doc);
  const defs = container?.firstElementChild;
  if (!defs) return;
  let ids = defIdIndex.get(defs);
  if (!ids) {
    ids = new Set();
    // Ids are always `exact-color-matrix-<hex>`; reading attributes avoids a
    // selector escape dependency on hosts without `CSS.escape`.
    for (const existing of Array.from(defs.children)) {
      const id = existing.getAttribute('id');
      if (id) ids.add(id);
    }
    defIdIndex.set(defs, ids);
  }
  if (ids.has(filter.id)) return;
  const element = doc.createElementNS(SVG_NS, 'filter');
  element.setAttribute('id', filter.id);
  // sRGB, not the SVG default linearRGB: this must match how the authoring
  // source (an SVG `feColorMatrix` on a photo) and the native Core Image /
  // Direct2D paths interpret the same 20 numbers.
  element.setAttribute('color-interpolation-filters', 'sRGB');
  const fe = doc.createElementNS(SVG_NS, 'feColorMatrix');
  fe.setAttribute('type', 'matrix');
  fe.setAttribute('values', filter.filterValues);
  element.appendChild(fe);
  defs.appendChild(element);
  ids.add(filter.id);
}

/**
 * Hook-lifecycle variant of `ensureImageColorMatrixFilterDef`: the def stays
 * alive while at least one retainer holds it, independent of whether an
 * element with the intent attribute has committed yet. Pair every retain
 * with exactly one release.
 */
export function retainImageColorMatrixFilterDef(
  doc: Document,
  filter: ImageColorMatrixFilter,
): void {
  ensureImageColorMatrixFilterDef(doc, filter);
  let counts = defRefCounts.get(doc);
  if (!counts) {
    counts = new Map();
    defRefCounts.set(doc, counts);
  }
  counts.set(filter.id, (counts.get(filter.id) ?? 0) + 1);
}

/**
 * Drop one retainer. The last release schedules the sweep on a microtask
 * rather than running it inline: `useInsertionEffect` cleanup fires before
 * React's DOM mutations, so an inline sweep would still count the departing
 * element's attribute as a live reference.
 */
export function releaseImageColorMatrixFilterDef(
  doc: Document,
  filter: ImageColorMatrixFilter,
): void {
  const counts = defRefCounts.get(doc);
  const current = counts?.get(filter.id);
  if (!counts || current === undefined) return;
  if (current > 1) {
    counts.set(filter.id, current - 1);
    return;
  }
  counts.delete(filter.id);
  if (scheduledSweeps.has(doc)) return;
  scheduledSweeps.add(doc);
  queueMicrotask(() => {
    scheduledSweeps.delete(doc);
    sweepImageColorMatrixFilterDefs(doc);
  });
}

/**
 * Drop `<filter>` defs no element references any more. Host tiers call this
 * after a commit rather than refcounting per node so a removed, replaced, or
 * re-parented image cannot leak a def, and so hydration-adopted elements are
 * counted too; hook-retained defs (the React tier) stay until released.
 */
export function sweepImageColorMatrixFilterDefs(doc: Document): void {
  const container = defsContainer(doc);
  const defs = container?.firstElementChild;
  if (!defs) return;
  const live = new Set<string>();
  for (const element of Array.from(doc.querySelectorAll(`[${IMAGE_COLOR_MATRIX_ATTR}]`))) {
    const canonical = element.getAttribute(IMAGE_COLOR_MATRIX_ATTR);
    if (canonical) live.add(imageColorMatrixFilterId(canonical));
  }
  const counts = defRefCounts.get(doc);
  if (counts) {
    for (const id of counts.keys()) live.add(id);
  }
  const ids = defIdIndex.get(defs);
  for (const def of Array.from(defs.children)) {
    const id = def.getAttribute('id');
    if (id && !live.has(id)) {
      defs.removeChild(def);
      ids?.delete(id);
    }
  }
  if (defs.children.length === 0) {
    container?.parentNode?.removeChild(container);
  }
}

/**
 * Apply the filter to prerendered images the host adopted verbatim. Static
 * HTML carries only the intent attribute (see `colorMatrixFilters: 'defer'`),
 * and a host that keeps server bytes authoritative for the adoption turn never
 * runs its ordinary presentation write for those elements. Idempotent.
 */
export function attachDeferredImageColorMatrixFilters(container: ParentNode): void {
  const doc = (container as Element).ownerDocument
    ?? (container as Document).defaultView?.document;
  if (!doc) return;
  for (const element of Array.from(
    container.querySelectorAll<HTMLElement>(`[${IMAGE_COLOR_MATRIX_ATTR}]`),
  )) {
    const filter = lowerImageColorMatrixFilter(element.getAttribute(IMAGE_COLOR_MATRIX_ATTR));
    if (!filter) continue;
    ensureImageColorMatrixFilterDef(doc, filter);
    if (element.style.filter !== filter.cssValue) {
      element.style.filter = filter.cssValue;
    }
  }
}

/**
 * Test-only full reset: removes the whole shared container and the hook
 * ledger unconditionally. Host teardown must NOT call this — the container is
 * document-global and shared across tiers, so a disposing host uses
 * `sweepImageColorMatrixFilterDefs` instead, which releases only references
 * that actually left the document and keeps defs other tiers still use.
 */
export function resetImageColorMatrixFilterDefs(doc: Document): void {
  const container = defsContainer(doc);
  container?.parentNode?.removeChild(container);
  // The refcount ledger describes the removed container's defs; releases that
  // arrive after teardown are no-ops against a fresh ledger.
  defRefCounts.delete(doc);
}
