// @system @ref LLP 0045, LLP 0307 — Route/list restoration state captured
// alongside a precomputed first frame.

export interface ContractListRestorationSeed {
  readonly listId: string;
  readonly scrollOffset: number;
  readonly anchor?: { readonly itemKey: string; readonly offsetInItem?: number };
  readonly measurements: {
    readonly entries: readonly {
      readonly key: string;
      readonly size: number;
      readonly type?: string | null;
    }[];
  };
}
const seeds = new Map<string, ContractListRestorationSeed>();
const precomputedSeeds = new Map<string, ContractListRestorationSeed>();
let precomputedSeedsLoaded = false;

type PrecomputedListSeedGlobal = typeof globalThis & {
  __exactPrecomputedFirstFrameListSeeds?: unknown;
};

function cloneSeed(seed: ContractListRestorationSeed): ContractListRestorationSeed {
  return {
    ...seed,
    anchor: seed.anchor ? { ...seed.anchor } : undefined,
    measurements: {
      entries: seed.measurements.entries.map((entry) => ({ ...entry })),
    },
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function parsePrecomputedSeed(value: unknown): ContractListRestorationSeed | null {
  if (!isRecord(value) ||
      typeof value.listId !== 'string' || value.listId.length === 0 ||
      typeof value.scrollOffset !== 'number' || !Number.isFinite(value.scrollOffset) ||
      value.scrollOffset < 0 ||
      !isRecord(value.measurements) || !Array.isArray(value.measurements.entries)) {
    return null;
  }
  let anchor: ContractListRestorationSeed['anchor'];
  const rawAnchor = value.anchor;
  if (rawAnchor !== undefined) {
    if (!isRecord(rawAnchor) ||
        typeof rawAnchor.itemKey !== 'string' || rawAnchor.itemKey.length === 0) {
      return null;
    }
    const offsetInItem = rawAnchor.offsetInItem;
    if (offsetInItem !== undefined &&
        (typeof offsetInItem !== 'number' ||
          !Number.isFinite(offsetInItem) || offsetInItem < 0)) {
      return null;
    }
    anchor = {
      itemKey: rawAnchor.itemKey,
      ...(typeof offsetInItem === 'number' ? { offsetInItem } : {}),
    };
  }
  const entries: Array<{ key: string; size: number; type?: string | null }> = [];
  for (const rawEntry of value.measurements.entries) {
    if (!isRecord(rawEntry) ||
        typeof rawEntry.key !== 'string' ||
        typeof rawEntry.size !== 'number' || !Number.isFinite(rawEntry.size) ||
        rawEntry.size < 0) {
      return null;
    }
    const entryType = rawEntry.type;
    if (entryType !== undefined && entryType !== null &&
        typeof entryType !== 'string') {
      return null;
    }
    const entry = {
      key: rawEntry.key,
      size: rawEntry.size,
    };
    if (typeof entryType === 'string') {
      entries.push({ ...entry, type: entryType });
    } else if (entryType === null) {
      entries.push({ ...entry, type: null });
    } else {
      entries.push(entry);
    }
  }
  return {
    listId: value.listId,
    scrollOffset: value.scrollOffset,
    ...(anchor ? { anchor } : {}),
    measurements: { entries },
  };
}

/**
 * Imports the one-shot host handoff written only after an EXFF artifact has
 * passed identity/font validation and replayed successfully. Malformed or
 * duplicate identities reject the whole handoff; partial adoption could
 * otherwise give the live tree a window different from the replayed pixels.
 */
function parsePrecomputedSeedsFromGlobal():
  | Map<string, ContractListRestorationSeed>
  | null {
  const host = globalThis as PrecomputedListSeedGlobal;
  const rawSeeds = host.__exactPrecomputedFirstFrameListSeeds;
  if (!Array.isArray(rawSeeds)) return new Map();

  const parsed = new Map<string, ContractListRestorationSeed>();
  for (const rawSeed of rawSeeds) {
    const seed = parsePrecomputedSeed(rawSeed);
    if (!seed || parsed.has(seed.listId)) return null;
    parsed.set(seed.listId, seed);
  }
  return parsed;
}

function loadPrecomputedSeeds(): void {
  if (precomputedSeedsLoaded) return;
  precomputedSeedsLoaded = true;
  const host = globalThis as PrecomputedListSeedGlobal;
  const parsed = parsePrecomputedSeedsFromGlobal();
  delete host.__exactPrecomputedFirstFrameListSeeds;
  if (!parsed) return;
  for (const [listId, seed] of parsed) {
    precomputedSeeds.set(listId, seed);
  }
}

export function consumePrecomputedContractListRestorationSeed(
  listId: string,
): ContractListRestorationSeed | undefined {
  loadPrecomputedSeeds();
  const seed = precomputedSeeds.get(listId);
  if (!seed) return undefined;
  precomputedSeeds.delete(listId);
  return cloneSeed(seed);
}

/**
 * Read the one-shot first-frame handoff without consuming it. An unpublished
 * hydration candidate consumes the seed only when its activation token commits.
 */
export function peekPrecomputedContractListRestorationSeed(
  listId: string,
): ContractListRestorationSeed | undefined {
  // @ref LLP 0386 §3.8.1 — speculative hydration preparation cannot consume
  // process-global one-shot state that a subsequent full CSR owner still needs.
  const seed = precomputedSeedsLoaded
    ? precomputedSeeds.get(listId)
    : parsePrecomputedSeedsFromGlobal()?.get(listId);
  return seed ? cloneSeed(seed) : undefined;
}

export function updateContractListRestorationSeed(
  identity: string,
  seed: ContractListRestorationSeed,
): void {
  seeds.set(identity, seed);
}

export function removeContractListRestorationSeed(identity: string): void {
  seeds.delete(identity);
}

export function takeContractListRestorationSnapshot(): ContractListRestorationSeed[] {
  return [...seeds.values()].map(cloneSeed);
}

export function resetContractListRestorationSeeds(): void {
  seeds.clear();
  precomputedSeeds.clear();
  precomputedSeedsLoaded = false;
  delete (globalThis as PrecomputedListSeedGlobal)
    .__exactPrecomputedFirstFrameListSeeds;
}
