// @system @ref LLP 0185 S2 — straight-line keyed each-region construction.

import {
  appendChild,
  insertBefore,
  type ElementNode,
  type TextNode,
} from '@exact/renderer/host-ops';

import type { Span, ViewNodeIR } from '../compiler/ir.js';
import {
  runWithContractErrorLocus,
  type ContractErrorLocus,
} from './error-locus-runtime.js';
import {
  createOwner,
  getOwner,
  isReactiveIntrospectionEnabled,
  ownedEffect,
  runWithOwner,
  signal,
  untrack,
  type ReactiveNodeOptions,
} from './signals.js';
import type { Scope } from './interpreter.js';
import { recordContractRoutePayloadEachExpansion } from './route-payload-capture-runtime.js';
import { mountContractAotViewNodes } from './aot-view-runtime.js';
import type { ContractMountViewNodes } from './aot-view-region.js';
import { logicalKeySegment } from './view-key-identity.js';
import type { AnchorFn, HostParent, Mounted, MountEnv } from './view.js';

type HostNode = ElementNode | TextNode;
const VIEW_EVAL = { identFallbackToString: true } as const;
type ContractEachEvaluator = (scope: Scope, options: typeof VIEW_EVAL) => unknown;

export type ContractAotEachPlan = readonly [
  iterable: ContractEachEvaluator,
  key: ContractEachEvaluator,
  item: string,
  index: string | null,
  line: number,
  col: number,
  len: number,
  offset: number,
];

interface EachRow {
  key: unknown;
  position: number;
  setItem(value: unknown): void;
  setIndex(value: number): void;
  mounted: Mounted;
  owner: ReturnType<typeof createOwner>;
}

export function mountContractEach(
  plan: ContractAotEachPlan,
  node: ViewNodeIR,
  body: readonly ViewNodeIR[],
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  mountNodes: ContractMountViewNodes = mountContractAotViewNodes,
): Mounted {
  const [iterable, evaluateKey, itemName, indexName, line, col, len, offset] = plan;
  const structuralId = env.ids.get(node) ?? null;
  const span: Span = { line, col, len, offset };
  let rows: EachRow[] = [];
  let disposed = false;
  let warnedDuplicateKeys = false;

  const createRow = (item: unknown, index: number, key: unknown): EachRow => {
    recordContractRoutePayloadEachExpansion(env.ctx.routePayloadCapture);
    const owner = createOwner();
    const self: { row: EachRow | null } = { row: null };
    const rowAnchor: AnchorFn = () => {
      const position = self.row?.position ?? -1;
      if (position >= 0) {
        for (let i = position + 1; i < rows.length; i += 1) {
          const nodesAfter = rows[i]!.mounted.hostNodes();
          if (nodesAfter.length > 0) return nodesAfter[0]!;
        }
      }
      return anchor();
    };
    let row: EachRow;
    try {
      row = runWithOwner(owner, () => {
        const itemSignal = signal<unknown>(item);
        const indexSignal = signal<number>(index);
        const rowScope = env.scope.child();
        rowScope.define(itemName, { kind: 'getter', get: () => itemSignal.get() });
        if (indexName) {
          rowScope.define(indexName, { kind: 'getter', get: () => indexSignal.get() });
        }
        const mounted = mountNodes(body, parent, rowAnchor, {
          ...env,
          scope: rowScope,
          isRootView: false,
          inRepetitionScope: true,
          repetitionIndex: index,
          keyChain: `${env.keyChain}#${String(key)}`,
          logicalKeyPath: [...env.logicalKeyPath, logicalKeySegment(key)],
          hydrationKeyChain: `${env.hydrationKeyChain}#${String(key)}`,
        });
        return {
          key,
          position: -1,
          setItem: (value: unknown) => itemSignal.set(value),
          setIndex: (value: number) => indexSignal.set(value),
          mounted,
          owner,
        };
      });
    } catch (error) {
      owner.dispose();
      throw error;
    }
    self.row = row;
    return row;
  };

  const locus: ContractErrorLocus = {
    component: env.component.name,
    sourcePath: env.component.file.sourcePath,
    region: 'each',
    span,
  };
  ownedEffect(
    () => runWithContractErrorLocus(locus, () => {
      const value = iterable(env.scope, VIEW_EVAL);
      const items = Array.isArray(value) ? value : [];
      untrack(() => {
        if (disposed) return;

        const oldByKey = new Map<unknown, EachRow[]>();
        const oldPositions = new Map<EachRow, number>();
        rows.forEach((row, index) => {
          oldPositions.set(row, index);
          const queue = oldByKey.get(row.key);
          if (queue) queue.push(row);
          else oldByKey.set(row.key, [row]);
        });

        const nextRows: EachRow[] = [];
        const createdRows: EachRow[] = [];
        const seen = new Set<unknown>();
        let createdAny = false;
        try {
          items.forEach((item, index) => {
            const keyScope = env.scope.child();
            keyScope.defineValue(itemName, item);
            if (indexName) keyScope.defineValue(indexName, index);
            const key = evaluateKey(keyScope, VIEW_EVAL);
            if (seen.has(key) && !warnedDuplicateKeys) {
              warnedDuplicateKeys = true;
              console.warn(
                `[contract] duplicate each key ${String(key)}; rows need unique keys`,
              );
            }
            seen.add(key);

            const queue = oldByKey.get(key);
            const existing = queue?.shift();
            if (existing) {
              if (queue!.length === 0) oldByKey.delete(key);
              existing.setItem(item);
              existing.setIndex(index);
              nextRows.push(existing);
            } else {
              createdAny = true;
              const created = createRow(item, index, key);
              createdRows.push(created);
              nextRows.push(created);
            }
          });
        } catch (error) {
          createdRows.forEach((row) => row.owner.dispose());
          throw error;
        }

        oldByKey.forEach((queue) => queue.forEach((row) => row.owner.dispose()));

        let previousPosition = -1;
        let orderChanged = false;
        for (const row of nextRows) {
          const oldPosition = oldPositions.get(row);
          if (oldPosition === undefined) continue;
          if (oldPosition < previousPosition) orderChanged = true;
          previousPosition = oldPosition;
        }
        rows = nextRows;
        rows.forEach((row, index) => { row.position = index; });

        if (createdAny || orderChanged) {
          let nextAnchor: HostNode | null = anchor();
          for (let i = rows.length - 1; i >= 0; i -= 1) {
            const nodes = rows[i]!.mounted.hostNodes();
            for (let n = nodes.length - 1; n >= 0; n -= 1) {
              const hostNode = nodes[n]!;
              if (nextAnchor) insertBefore(parent, hostNode, nextAnchor);
              else appendChild(parent, hostNode);
              nextAnchor = hostNode;
            }
          }
        }
      });
    }),
    eachReactiveOptions(env, structuralId, span),
  );

  const dispose = (): void => {
    if (disposed) return;
    disposed = true;
    rows.forEach((row) => row.owner.dispose());
    rows = [];
  };
  getOwner()?.register(dispose);
  return {
    hostNodes: () => rows.flatMap((row) => row.mounted.hostNodes()),
    dispose,
  };
}

function eachReactiveOptions(
  env: MountEnv,
  structuralId: string | null,
  span: Span,
): ReactiveNodeOptions | undefined {
  if (!isReactiveIntrospectionEnabled()) return undefined;
  const id = structuralId ?? `each:${span.line}:${span.col}`;
  return {
    label: `${env.component.name}.view.${id}.each`,
    source: {
      component: env.component.name,
      sourcePath: env.component.file.sourcePath,
      region: 'each',
      span,
    },
  };
}
