// @system @ref LLP 0007 §8.2.2 — one browser focusability contract shared by
// React behavior primitives and the Contract DOM mirror.

/**
 * Structural candidates only. Eligibility that depends on an ancestor
 * (`inert` / `aria-hidden`) deliberately lives in `isDomFocusable` so every
 * caller applies the same predicate after querying.
 */
export const DOM_FOCUSABLE_SELECTOR = [
  'a[href]',
  'button',
  'input:not([type="hidden"])',
  'select',
  'textarea',
  '[tabindex]',
  '[role="button"]',
  '[role="link"]',
  '[role="textbox"]',
  '[role="switch"]',
  '[role="checkbox"]',
  '[role="radio"]',
  '[role="slider"]',
  '[role="spinbutton"]',
  '[role="combobox"]',
  '[role="listbox"]',
  '[role="option"]',
  '[role="menuitem"]',
  '[role="tab"]',
  '[role="treeitem"]',
].join(',');

export function hasDomHiddenOrInertAncestor(element: HTMLElement): boolean {
  let current: HTMLElement | null = element;
  while (current) {
    if (
      current.hasAttribute('inert') ||
      current.getAttribute('aria-hidden') === 'true'
    ) {
      return true;
    }
    current = current.parentElement;
  }
  return false;
}

/** Browser-side projection of the kernel focusability contract. */
export function isDomFocusable(element: HTMLElement): boolean {
  if (!element.isConnected || hasDomHiddenOrInertAncestor(element)) {
    return false;
  }
  if (
    element.hasAttribute('disabled') ||
    element.getAttribute('aria-disabled') === 'true'
  ) {
    return false;
  }
  return element.tabIndex >= 0;
}

export function isDomInteractionBlocked(element: HTMLElement): boolean {
  return hasDomHiddenOrInertAncestor(element) ||
    element.hasAttribute('disabled') ||
    element.getAttribute('aria-disabled') === 'true';
}

export function domFocusableDescendants(scope: HTMLElement): HTMLElement[] {
  return Array.from(
    scope.querySelectorAll<HTMLElement>(DOM_FOCUSABLE_SELECTOR),
  ).filter(isDomFocusable);
}
