import type {
  EffectPressureSnapshot,
  EffectSupervisor,
} from './effect-supervisor.js';
import type { ContractDeterminismAuthority } from './determinism-host.js';
import type { ContractReactiveQueueSnapshot } from './signals.js';

export interface ContractRuntimeQuiescenceParticipant {
  id: string;
  snapshot(): {
    deferredMountTasks?: number;
    hydrationReleases?: number;
    actionable?: number;
    epoch?: number;
  };
  drain(): number;
}

export interface QuiescenceSnapshotV1 {
  version: 1;
  runtimeId: string;
  iteration: number;
  work: number;
  reactiveQueue: ContractReactiveQueueSnapshot;
  supervisor: EffectPressureSnapshot;
  ownedMicrotasks: number;
  dueTimers: number;
  deferredMountTasks: number;
  hydrationReleases: number;
  participantActionable: number;
  participantEpoch: number;
}

export interface QuiescenceResultV1 {
  status: 'quiescent';
  snapshot: QuiescenceSnapshotV1;
}

export interface NonQuiescentFailureV1 {
  status: 'NON_QUIESCENT';
  reason: 'iteration-bound' | 'work-bound';
  maxIterations: number;
  maxWork: number;
  snapshot: QuiescenceSnapshotV1;
}

export interface ContractQuiescenceRuntimeInput {
  runtimeId: string;
  reactiveQueueOwner: object;
  supervisor: EffectSupervisor;
  determinism: ContractDeterminismAuthority;
  ownedMicrotasks(): number;
  participants: ReadonlyMap<string, ContractRuntimeQuiescenceParticipant>;
}

export interface ContractQuiescenceRuntime {
  snapshot(
    input: ContractQuiescenceRuntimeInput,
    iteration: number,
    work: number,
  ): QuiescenceSnapshotV1;
  quiesce(
    input: ContractQuiescenceRuntimeInput,
    options: { maxIterations?: number; maxWork?: number },
  ): Promise<QuiescenceResultV1>;
}

const unavailable: ContractQuiescenceRuntime = {
  snapshot() {
    throw new Error('[contract] quiescence inspection requires the full replay runtime');
  },
  async quiesce() {
    throw new Error('[contract] quiescence requires the full replay runtime');
  },
};

let implementation = unavailable;

export function installContractQuiescenceRuntime(next: ContractQuiescenceRuntime): void {
  implementation = next;
}

export function contractQuiescenceSnapshot(
  input: ContractQuiescenceRuntimeInput,
  iteration = 0,
  work = 0,
): QuiescenceSnapshotV1 {
  return implementation.snapshot(input, iteration, work);
}

export function quiesceContractRuntime(
  input: ContractQuiescenceRuntimeInput,
  options: { maxIterations?: number; maxWork?: number } = {},
): Promise<QuiescenceResultV1> {
  return implementation.quiesce(input, options);
}
