import { BackdropMaterialId } from '../protocol/opcodes.generated.js';

/**
 * Semantic backdrop materials (LLP 0412).
 *
 * These names are the portable authoring and Facet-token surface. Hosts map
 * them to their native material vocabulary or to a documented tint/blur
 * approximation; platform-specific material names deliberately do not cross
 * this boundary.
 */
export const BACKDROP_MATERIAL_VALUES = [
  'thin',
  'regular',
  'thick',
  'chrome',
  'bar',
  'sidebar',
] as const;

export type BackdropMaterial = (typeof BACKDROP_MATERIAL_VALUES)[number];

const BACKDROP_MATERIAL_SET: ReadonlySet<string> = new Set(BACKDROP_MATERIAL_VALUES);

const BACKDROP_MATERIAL_PROTOCOL_VALUES: Readonly<Record<BackdropMaterial, number>> = {
  thin: BackdropMaterialId.Thin,
  regular: BackdropMaterialId.Regular,
  thick: BackdropMaterialId.Thick,
  chrome: BackdropMaterialId.Chrome,
  bar: BackdropMaterialId.Bar,
  sidebar: BackdropMaterialId.Sidebar,
};

export function normalizeBackdropMaterial(value: unknown): BackdropMaterial | undefined {
  return typeof value === 'string' && BACKDROP_MATERIAL_SET.has(value)
    ? value as BackdropMaterial
    : undefined;
}

/**
 * Protocol values intentionally reserve zero for no/unknown material so a
 * newer authoring token degrades safely on an older or defensive decoder.
 */
export function backdropMaterialProtocolValue(value: unknown): number {
  const material = normalizeBackdropMaterial(value);
  return material === undefined
    ? BackdropMaterialId.None
    : BACKDROP_MATERIAL_PROTOCOL_VALUES[material];
}
