// @system @ref LLP 0185 S1/S4 — build-time Contract expression closure emission.

import type { ContractFileIR, Expr, Span } from './ir.js';
import { isExprSpread } from './ir.js';

const EXPRESSION_KINDS = new Set<Expr['kind']>([
  'array',
  'arrow',
  'binary',
  'boolean',
  'call',
  'ident',
  'index',
  'member',
  'null',
  'number',
  'object',
  'relation',
  'string',
  'template',
  'ternary',
  'token',
  'unary',
]);

/**
 * Returns every expression object in deterministic pre-order. The runtime
 * uses the same order to bind generated closures back to the in-memory IR.
 */
export function collectContractExpressions(file: ContractFileIR): Expr[] {
  const expressions: Expr[] = [];
  const visit = (value: unknown): void => {
    if (!value || typeof value !== 'object') return;
    const record = value as Record<string, unknown>;
    if (isContractExpression(value)) {
      expressions.push(value as Expr);
    }
    for (const child of Object.values(record)) {
      if (Array.isArray(child)) child.forEach(visit);
      else visit(child);
    }
  };
  visit(file);
  return expressions;
}

/** The Contract IR has other tagged unions whose discriminator values overlap
 * expression kinds (`array` parsed types, `call` effect records, and literal
 * contract clauses). Inventory only structurally valid expressions. */
export function isContractExpression(value: unknown): value is Expr {
  if (!value || typeof value !== 'object') return false;
  const record = value as Record<string, unknown>;
  if (typeof record.kind !== 'string' || !EXPRESSION_KINDS.has(record.kind as Expr['kind'])) {
    return false;
  }
  switch (record.kind as Expr['kind']) {
    case 'null':
      return true;
    case 'string':
      return typeof record.value === 'string';
    case 'number':
      return typeof record.value === 'number';
    case 'boolean':
      return typeof record.value === 'boolean';
    case 'ident':
      return typeof record.name === 'string';
    case 'token':
      return typeof record.path === 'string';
    case 'array':
      return Array.isArray(record.items);
    case 'object':
      return Array.isArray(record.entries);
    case 'arrow':
      return Array.isArray(record.params) && Boolean(record.body);
    case 'call':
      return Boolean(record.callee) && Array.isArray(record.args);
    case 'member':
      return Boolean(record.object) && typeof record.property === 'string';
    case 'index':
      return Boolean(record.object) && Boolean(record.index);
    case 'unary':
      return typeof record.op === 'string' && Boolean(record.operand);
    case 'binary':
      return typeof record.op === 'string' && Boolean(record.left) && Boolean(record.right);
    case 'ternary':
      return Boolean(record.test) && Boolean(record.consequent) && Boolean(record.alternate);
    case 'template':
      return Array.isArray(record.parts);
    case 'relation':
      return typeof record.op === 'string' && Array.isArray(record.args);
  }
}

export interface ContractAotExpressionLine {
  text: string;
  anchor?: Span;
}

const AOT_RUNTIME_HELPERS = {
  readToken: '__contractAot.t',
  readIdent: '__contractAot.i',
  readMember: '__contractAot.m',
  readIndex: '__contractAot.x',
  call: '__contractAot.c',
  templateValue: '__contractAot.v',
  buildArray: '__contractAot.a',
  buildObject: '__contractAot.o',
  arrowScope: '__contractAot.s',
  createRelation: '__contractAot.r',
} as const;

/**
 * Emits one generated line per closure so the Vite source map can attribute
 * runtime failures to the corresponding authored expression span.
 */
export function emitContractAotExpressionLines(
  file: ContractFileIR,
  runtimeExpressionIndices?: readonly number[],
  emittedExpressionIndices?: readonly number[],
  expressionIndexRemap?: ReadonlyMap<number, number>,
): ContractAotExpressionLine[] {
  const table = emitContractAotExpressionTableLines(
    file,
    emittedExpressionIndices,
    expressionIndexRemap,
  );
  return [
    ...table,
    {
      text: runtimeExpressionIndices
        ? `__registerContractAotExpressions(__contractFile, __contractAotExpressions, ${JSON.stringify(runtimeExpressionIndices)});`
        : '__registerContractAotExpressions(__contractFile, __contractAotExpressions);',
    },
  ];
}

/**
 * Emits only the IR-free evaluator table. The legacy adapter appends an
 * IR-keyed registration call; LLP 0381 P3 generated programs consume this
 * table directly and therefore never retain an AST identity map.
 */
export function emitContractAotExpressionTableLines(
  file: ContractFileIR,
  emittedExpressionIndices?: readonly number[],
  expressionIndexRemap?: ReadonlyMap<number, number>,
): ContractAotExpressionLine[] {
  const expressions = collectContractExpressions(file);
  const indices = new Map(expressions.map((expr, index) => [expr, index]));
  const emitted = emittedExpressionIndices
    ? new Set(emittedExpressionIndices)
    : null;
  const render = (
    expr: Expr,
    scope: string,
    options: string,
    allowReference: boolean,
  ): string => {
    const index = indices.get(expr);
    if (index === undefined) {
      throw new Error('[contract] AOT expression inventory omitted a child expression');
    }
    if (allowReference && (!emitted || emitted.has(index))) {
      return `__contractAotExpressions[${expressionIndexRemap?.get(index) ?? index}](${scope}, ${options})`;
    }
    return emitExprBody(
      expr,
      (child, childScope = scope, childOptions = options) =>
        render(child, childScope, childOptions, true),
      scope,
      options,
    );
  };
  const emit = (expr: Expr): string => {
    const body = render(expr, '__scope', '__options', false);
    return `(__scope, __options) => ${body}`;
  };
  const expressionLines = expressionIndexRemap
    ? [...expressionIndexRemap.entries()]
        .sort((left, right) => left[1] - right[1])
        .map(([index]) => ({
          text: `  ${emit(expressions[index]!)},`,
          anchor: expressions[index]!.span,
        }))
    : expressions.map((expr, index) => emitted && !emitted.has(index)
      ? { text: '  ,' }
      : { text: `  ${emit(expr)},`, anchor: expr.span });
  return [
    { text: 'const __contractAotExpressions = [' },
    ...expressionLines,
    { text: '];' },
  ];
}

/** String form used by isolated compiler tests and non-Vite consumers. */
export function emitContractAotExpressions(file: ContractFileIR): string {
  return emitContractAotExpressionLines(file).map(({ text }) => text).join('\n');
}

function emitExprBody(
  expr: Expr,
  child: (expr: Expr, scope?: string, options?: string) => string,
  scope = '__scope',
  options = '__options',
): string {
  switch (expr.kind) {
    case 'string':
    case 'number':
    case 'boolean':
      return JSON.stringify(expr.value);
    case 'null':
      return 'null';
    case 'token':
      return `${AOT_RUNTIME_HELPERS.readToken}(${scope}, ${JSON.stringify(expr.path)})`;
    case 'relation':
      return `${AOT_RUNTIME_HELPERS.createRelation}(${JSON.stringify(expr.op)}, [${expr.args.map((arg) => child(arg)).join(',')}], ${expr.fallback ? child(expr.fallback) : 'undefined'})`;
    case 'ident':
      return `${AOT_RUNTIME_HELPERS.readIdent}(${scope}, ${JSON.stringify(expr.name)}, ${options})`;
    case 'member':
      return `${AOT_RUNTIME_HELPERS.readMember}(${child(expr.object)}, ${JSON.stringify(expr.property)}, ${expr.optional === true})`;
    case 'index':
      return `${AOT_RUNTIME_HELPERS.readIndex}(${child(expr.object)}, ${child(expr.index)})`;
    case 'call':
      return `${AOT_RUNTIME_HELPERS.call}(${child(expr.callee)}, ${JSON.stringify(describeCallee(expr.callee))}, [${expr.args.map((arg) => child(arg)).join(',')}], ${JSON.stringify(expr.oracleReadSiteId ?? null)})`;
    case 'unary':
      return expr.op === '!' ? `!(${child(expr.operand)})` : `-(${child(expr.operand)})`;
    case 'binary':
      return `(${child(expr.left)} ${binaryOperator(expr.op)} ${child(expr.right)})`;
    case 'ternary':
      return `(${child(expr.test)} ? ${child(expr.consequent)} : ${child(expr.alternate)})`;
    case 'template':
      return `[${expr.parts.map((part) => part.kind === 'text'
        ? JSON.stringify(part.text)
        : `${AOT_RUNTIME_HELPERS.templateValue}(${child(part.expr)})`).join(',')}].join("")`;
    case 'array':
      return `${AOT_RUNTIME_HELPERS.buildArray}([${expr.items.map((item) => child(isExprSpread(item) ? item.value : item)).join(',')}], [${expr.items.map((item) => isExprSpread(item)).join(',')}])`;
    case 'object':
      return `${AOT_RUNTIME_HELPERS.buildObject}([${expr.entries.map((entry) => isExprSpread(entry) ? 'null' : JSON.stringify(entry.key)).join(',')}], [${expr.entries.map((entry) => child(entry.value)).join(',')}])`;
    case 'arrow':
      return `(...__args) => ${child(
        expr.body,
        `${AOT_RUNTIME_HELPERS.arrowScope}(${scope}, ${JSON.stringify(expr.params)}, __args)`,
        options,
      )}`;
  }
}

function binaryOperator(op: Extract<Expr, { kind: 'binary' }>['op']): string {
  if (op === '==') return '===';
  if (op === '!=') return '!==';
  return op;
}

function describeCallee(expr: Expr): string {
  if (expr.kind === 'ident') return expr.name;
  if (expr.kind === 'member') return expr.property;
  return expr.kind;
}
