// @system @ref LLP 0317 §§8.1-8.2 — runtime capture of the fully expanded
// Contract semantic tree. The wire schema remains compiler-owned; this module
// only records the mounted output before host-specific lowering becomes the
// sole representation.

import type { ElementNode, TextNode } from '@exact/renderer/host-ops';

import { CONTRACT_ROUTE_PAYLOAD_HARD_QUOTAS } from '../compiler/route-payload-quotas.js';
import type {
  ContractRoutePayloadElementNode,
  ContractRoutePayloadKey,
  ContractRoutePayloadNode,
  ContractRoutePayloadProvenance,
  ContractRoutePayloadTag,
  ContractRoutePayloadTextNode,
  ContractRoutePayloadValue,
} from '../compiler/route-payload.js';
import type { Expr } from '../compiler/ir.js';
import { isExprSpread } from '../compiler/ir.js';

type PayloadHostNode = ElementNode | TextNode;

interface ElementCaptureMetadata {
  readonly kind: 'element';
  readonly id: string;
  readonly key?: ContractRoutePayloadKey;
  readonly tag: ContractRoutePayloadTag;
  readonly provenance?: ContractRoutePayloadProvenance;
  readonly readProps: () => Record<string, ContractRoutePayloadValue>;
}

interface TextCaptureMetadata {
  readonly kind: 'text';
  readonly id: string;
  readonly key?: ContractRoutePayloadKey;
  readonly provenance?: ContractRoutePayloadProvenance;
  readonly readValue: () => string | { $token: string };
}

type CaptureMetadata = ElementCaptureMetadata | TextCaptureMetadata;

const captureMetadata = new WeakMap<object, CaptureMetadata>();

export interface ContractRoutePayloadTreeCapture {
  readonly tree: ContractRoutePayloadNode;
  readonly eachExpansionCount: number;
}

export interface ContractRoutePayloadCaptureState {
  eachExpansionCount: number;
  nodeCount: number;
  valueNodeCount: number;
  valueStringBytes: number;
  readonly maxEachExpansions: number;
}

export function createContractRoutePayloadCaptureState(
  maxEachExpansions: number = CONTRACT_ROUTE_PAYLOAD_HARD_QUOTAS.eachExpansions,
): ContractRoutePayloadCaptureState {
  if (!Number.isSafeInteger(maxEachExpansions)
    || maxEachExpansions < 0
    || maxEachExpansions > CONTRACT_ROUTE_PAYLOAD_HARD_QUOTAS.eachExpansions) {
    throw new Error('[contract] route payload each-expansion limit is invalid');
  }
  return {
    eachExpansionCount: 0,
    nodeCount: 0,
    valueNodeCount: 0,
    valueStringBytes: 0,
    maxEachExpansions,
  };
}

export function recordContractRoutePayloadEachExpansion(
  state: ContractRoutePayloadCaptureState | undefined,
): void {
  if (state === undefined) return;
  if (state.eachExpansionCount >= state.maxEachExpansions) {
    throw new Error('[contract] route payload each-expansion quota exceeded during generation');
  }
  state.eachExpansionCount += 1;
}

export function registerContractRoutePayloadElementCapture(
  state: ContractRoutePayloadCaptureState,
  host: ElementNode,
  metadata: ElementCaptureMetadata,
): void {
  recordCapturedNode(state);
  captureMetadata.set(host, metadata);
}

export function registerContractRoutePayloadTextCapture(
  state: ContractRoutePayloadCaptureState,
  host: TextNode,
  metadata: TextCaptureMetadata,
): void {
  recordCapturedNode(state);
  captureMetadata.set(host, metadata);
}

function recordCapturedNode(state: ContractRoutePayloadCaptureState): void {
  if (state.nodeCount >= CONTRACT_ROUTE_PAYLOAD_HARD_QUOTAS.nodes) {
    throw new Error('[contract] route payload node quota exceeded during generation');
  }
  state.nodeCount += 1;
}

export function captureMountedContractRoutePayloadTree(
  roots: readonly PayloadHostNode[],
  state: ContractRoutePayloadCaptureState,
): ContractRoutePayloadTreeCapture {
  if (roots.length !== 1) {
    throw new Error(
      `[contract] route payload requires exactly one mounted root; received ${roots.length}`,
    );
  }
  // A handle may be inspected more than once. Recompute the per-capture value
  // budget from zero while retaining the mount-time node/row counters.
  state.valueNodeCount = 0;
  state.valueStringBytes = 0;
  return Object.freeze({
    tree: captureHostNode(roots[0]!, state),
    eachExpansionCount: state.eachExpansionCount,
  });
}

function captureHostNode(
  host: PayloadHostNode,
  state: ContractRoutePayloadCaptureState,
): ContractRoutePayloadNode {
  const metadata = captureMetadata.get(host);
  if (metadata === undefined) {
    throw new Error(
      '[contract] mounted route contains a host node without semantic payload metadata',
    );
  }
  if (metadata.kind === 'text') {
    const value = metadata.readValue();
    recordCapturedValue(state, value);
    const node: ContractRoutePayloadTextNode = {
      kind: 'text',
      id: metadata.id,
      value,
    };
    if (metadata.key !== undefined) node.key = metadata.key;
    if (metadata.provenance !== undefined) node.provenance = metadata.provenance;
    return node;
  }
  const node: ContractRoutePayloadElementNode = {
    kind: 'element',
    id: metadata.id,
    tag: metadata.tag,
    props: metadata.readProps(),
    children: (host as ElementNode).children.map((child) => captureHostNode(child, state)),
  };
  if (metadata.key !== undefined) node.key = metadata.key;
  if (metadata.provenance !== undefined) node.provenance = metadata.provenance;
  return node;
}

/**
 * Preserve first-class token references while resolving every other pure
 * expression through the ordinary Contract evaluator. Object/array literals
 * are walked so nested token references remain symbolic too.
 */
export function readContractRoutePayloadExpression(
  expr: Expr,
  evaluate: (expr: Expr) => unknown,
  state?: ContractRoutePayloadCaptureState,
): ContractRoutePayloadValue {
  if (expr.kind === 'token') {
    const token = Object.freeze({ $token: expr.path });
    if (state) recordCapturedValue(state, token);
    return token;
  }
  if (expr.kind === 'array') {
    const values: ContractRoutePayloadValue[] = [];
    if (state) recordCapturedValueNode(state);
    for (const item of expr.items) {
      if (isExprSpread(item)) {
        const spread = snapshotPayloadValue(evaluate(item.value), 'array spread', state);
        if (!Array.isArray(spread)) {
          throw new Error('[contract] route payload array spread did not resolve to an array');
        }
        // Avoid the engine's variadic-argument ceiling at the allowed graph
        // boundary; the snapshotter has already enforced the shared quota.
        for (const entry of spread) values.push(entry);
      } else {
        values.push(readContractRoutePayloadExpression(item, evaluate, state));
      }
    }
    return values;
  }
  if (expr.kind === 'object') {
    const value: Record<string, ContractRoutePayloadValue> = Object.create(null);
    if (state) recordCapturedValueNode(state);
    for (const entry of expr.entries) {
      if (isExprSpread(entry)) {
        const spread = snapshotPayloadValue(evaluate(entry.value), 'object spread', state);
        if (spread === null || Array.isArray(spread) || typeof spread !== 'object') {
          throw new Error('[contract] route payload object spread did not resolve to an object');
        }
        Object.assign(value, spread);
      } else {
        value[entry.key] = readContractRoutePayloadExpression(entry.value, evaluate, state);
      }
    }
    return value;
  }
  return snapshotPayloadValue(evaluate(expr), 'expression', state);
}

function snapshotPayloadValue(
  value: unknown,
  label: string,
  state?: ContractRoutePayloadCaptureState,
  ancestors: Set<object> = new Set(),
  localUsage: { nodes: number } = { nodes: 0 },
  depth = 0,
): ContractRoutePayloadValue {
  localUsage.nodes += 1;
  if (localUsage.nodes > 100_000 || depth > 64) {
    throw new Error(`[contract] route payload ${label} exceeds the JSON graph quota`);
  }
  if (state) recordCapturedValueNode(state);
  if (value === null) return null;
  if (typeof value === 'string') {
    if (state) recordCapturedString(state, value);
    return value;
  }
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number' && Number.isFinite(value) && !Object.is(value, -0)) {
    return value;
  }
  if (Array.isArray(value)) {
    if (ancestors.has(value)) throw new Error(`[contract] route payload ${label} is cyclic`);
    const prototype = Object.getPrototypeOf(value);
    if (prototype !== Array.prototype && prototype !== null) {
      throw new Error(`[contract] route payload ${label} resolved to a non-plain array`);
    }
    ancestors.add(value);
    try {
      const output: ContractRoutePayloadValue[] = [];
      for (let index = 0; index < value.length; index += 1) {
        const descriptor = Object.getOwnPropertyDescriptor(value, String(index));
        if (!descriptor?.enumerable || !Object.prototype.hasOwnProperty.call(descriptor, 'value')) {
          throw new Error(`[contract] route payload ${label} has a sparse/accessor array entry`);
        }
        output.push(snapshotPayloadValue(
          descriptor.value,
          label,
          state,
          ancestors,
          localUsage,
          depth + 1,
        ));
      }
      if (Reflect.ownKeys(value).some((key) => (
        key !== 'length'
        && (typeof key !== 'string' || !/^(?:0|[1-9][0-9]*)$/.test(key))
      ))) {
        throw new Error(`[contract] route payload ${label} has an extended array`);
      }
      return output;
    } finally {
      ancestors.delete(value);
    }
  }
  if (typeof value === 'object' && value !== null) {
    const prototype = Object.getPrototypeOf(value);
    if (prototype !== Object.prototype && prototype !== null) {
      throw new Error(`[contract] route payload ${label} resolved to a non-plain object`);
    }
    if (ancestors.has(value)) throw new Error(`[contract] route payload ${label} is cyclic`);
    ancestors.add(value);
    const output: Record<string, ContractRoutePayloadValue> = Object.create(null);
    try {
      for (const key of Reflect.ownKeys(value)) {
        if (typeof key !== 'string') {
          throw new Error(`[contract] route payload ${label} has a symbol field`);
        }
        const descriptor = Object.getOwnPropertyDescriptor(value, key);
        if (!descriptor?.enumerable || !Object.prototype.hasOwnProperty.call(descriptor, 'value')) {
          throw new Error(`[contract] route payload ${label} has an accessor/non-data field`);
        }
        output[key] = snapshotPayloadValue(
          descriptor.value,
          label,
          state,
          ancestors,
          localUsage,
          depth + 1,
        );
      }
    } finally {
      ancestors.delete(value);
    }
    return output;
  }
  throw new Error(`[contract] route payload ${label} is not JSON-serializable`);
}

function recordCapturedValue(
  state: ContractRoutePayloadCaptureState,
  value: string | { $token: string },
): void {
  recordCapturedValueNode(state);
  recordCapturedString(state, typeof value === 'string' ? value : value.$token);
}

function recordCapturedValueNode(state: ContractRoutePayloadCaptureState): void {
  state.valueNodeCount += 1;
  if (state.valueNodeCount > 100_000) {
    throw new Error('[contract] route payload cumulative value-node quota exceeded during generation');
  }
}

function recordCapturedString(state: ContractRoutePayloadCaptureState, value: string): void {
  state.valueStringBytes += new TextEncoder().encode(value).byteLength;
  if (state.valueStringBytes > CONTRACT_ROUTE_PAYLOAD_HARD_QUOTAS.payloadBytes) {
    throw new Error('[contract] route payload cumulative value-string quota exceeded during generation');
  }
}
