// @system @ref LLP 0336#4-contract-authoring-surface — mounted interaction
// registry, scoped key engine, pager command registry, and dispatch context.

import type {
  Expr,
  InteractionWitnessIR,
  PagerCenterAnimationIR,
  PagerNodeIR,
} from "../compiler/ir.js";
import { contractDevelopmentFeaturesEnabled } from "./build-mode.js";
import { evalRuntimeExpr } from "./execution.js";
import {
  ensureInputInventoryObserver,
  getCharacterShortcutsEnabled,
  readInputKeyboardPresence,
  registerNativeContractKeyBinding,
  type NativeContractKeyEvent,
} from "./host-capabilities.js";
import type { ComponentInstance } from "./instance.js";
import type { Scope } from "./interpreter.js";
import type { ContractInteractionsRuntime } from './interactions-runtime.js';
import { batch, untrack } from "./signals.js";

export interface InteractionEqualityToken {
  kind: "primitive" | "json" | "unverifiable";
  value?: string | number | boolean | null;
  fingerprint?: string;
}

export interface InteractionDispatchContext {
  inputCorrelationId: string;
  commandInstanceId: string;
  bindingGeneration: number;
  action: string;
  ownerInstance: string;
  invocationId?: string;
  arguments: InteractionEqualityToken[];
  binding: "press" | "key" | "pager-prev" | "pager-next" | "pager-arrows";
}

let currentDispatch: InteractionDispatchContext | null = null;
let lastDispatch: InteractionDispatchContext | null = null;
let nextCorrelation = 1;
let nextInstance = 1;
let nextPager = 1;

export function currentInteractionDispatchContext(): InteractionDispatchContext | null {
  return currentDispatch;
}

export function lastInteractionDispatchContext(): InteractionDispatchContext | null {
  return lastDispatch;
}

export function attachInteractionInvocation(invocationId: string): void {
  if (currentDispatch) currentDispatch.invocationId = invocationId;
}

function canonicalJson(value: unknown): string | null {
  const seen = new Set<object>();
  const normalize = (candidate: unknown): unknown => {
    if (
      candidate === null ||
      typeof candidate === "string" ||
      typeof candidate === "number" ||
      typeof candidate === "boolean"
    ) {
      return candidate;
    }
    if (Array.isArray(candidate)) return candidate.map(normalize);
    if (typeof candidate === "object") {
      const prototype = Object.getPrototypeOf(candidate);
      if (prototype !== Object.prototype && prototype !== null)
        throw new Error("opaque");
      if (seen.has(candidate as object)) throw new Error("cycle");
      seen.add(candidate as object);
      const out: Record<string, unknown> = {};
      Object.keys(candidate as Record<string, unknown>)
        .sort()
        .forEach((key) => {
          out[key] = normalize((candidate as Record<string, unknown>)[key]);
        });
      seen.delete(candidate as object);
      return out;
    }
    throw new Error("opaque");
  };
  try {
    return JSON.stringify(normalize(value));
  } catch {
    return null;
  }
}

function fnv1a(value: string): string {
  return `fnv1a32:${fnv1aU32(value).toString(16).padStart(8, "0")}`;
}

function fnv1aU32(value: string): number {
  let hash = 0x811c9dc5;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

export function interactionEqualityToken(
  value: unknown,
): InteractionEqualityToken {
  if (
    value === null ||
    typeof value === "string" ||
    typeof value === "boolean" ||
    (typeof value === "number" && Number.isFinite(value))
  ) {
    return {
      kind: "primitive",
      value: value as string | number | boolean | null,
    };
  }
  const json = canonicalJson(value);
  return json === null
    ? { kind: "unverifiable" }
    : { kind: "json", fingerprint: fnv1a(json) };
}

function commandRef(expr: Expr): { action: string; args: Expr[] } | null {
  if (expr.kind === "ident") return { action: expr.name, args: [] };
  if (expr.kind === "call" && expr.callee.kind === "ident") {
    return { action: expr.callee.name, args: expr.args };
  }
  return null;
}

export function runWithInteractionDispatchForExpr<T>(
  instance: ComponentInstance,
  expr: Expr,
  binding: InteractionDispatchContext["binding"],
  commandInstanceId: string,
  generation: number,
  fn: () => T,
  evaluationScope: Scope = instance.scope,
): T {
  const ref = commandRef(expr);
  if (!ref) return fn();
  if (!contractDevelopmentFeaturesEnabled()) return fn();
  const args = untrack(() =>
    ref.args.map((arg) => evalRuntimeExpr(arg, evaluationScope)),
  );
  const previous = currentDispatch;
  const context: InteractionDispatchContext = {
    inputCorrelationId: `interaction_${nextCorrelation++}`,
    commandInstanceId,
    bindingGeneration: generation,
    action: ref.action,
    ownerInstance:
      instance.runtimeInstanceId ?? commandInstanceId.split("/")[0]!,
    arguments: args.map(interactionEqualityToken),
    binding,
  };
  currentDispatch = context;
  try {
    return fn();
  } finally {
    lastDispatch = context;
    currentDispatch = previous;
  }
}

export function runWithCompiledInteractionDispatch<T>(
  ownerInstance: string,
  action: string,
  args: readonly unknown[],
  binding: InteractionDispatchContext['binding'],
  commandInstanceId: string,
  generation: number,
  fn: () => T,
): T {
  if (!contractDevelopmentFeaturesEnabled()) return fn();
  const previous = currentDispatch;
  const context: InteractionDispatchContext = {
    inputCorrelationId: `interaction_${nextCorrelation++}`,
    commandInstanceId,
    bindingGeneration: generation,
    action,
    ownerInstance,
    arguments: args.map(interactionEqualityToken),
    binding,
  };
  currentDispatch = context;
  try {
    return fn();
  } finally {
    lastDispatch = context;
    currentDispatch = previous;
  }
}

function dispatchCommand(
  instance: ComponentInstance,
  expr: Expr,
  binding: InteractionDispatchContext["binding"],
  commandInstanceId: string,
  generation: number,
): void {
  const ref = commandRef(expr);
  if (!ref) return;
  const args = untrack(() =>
    ref.args.map((arg) => evalRuntimeExpr(arg, instance.scope)),
  );
  const fn = untrack(() =>
    evalRuntimeExpr({ kind: "ident", name: ref.action }, instance.scope),
  );
  if (typeof fn !== "function") return;
  runWithInteractionDispatchForExpr(
    instance,
    expr,
    binding,
    commandInstanceId,
    generation,
    () => {
      batch(() => (fn as (...values: unknown[]) => unknown)(...args));
    },
  );
}

function evaluatedCommand(
  instance: ComponentInstance,
  expr: Expr,
): Record<string, unknown> | null {
  const ref = commandRef(expr);
  if (!ref) return null;
  return {
    action: ref.action,
    arguments: untrack(() =>
      ref.args.map((arg) =>
        interactionEqualityToken(evalRuntimeExpr(arg, instance.scope)),
      ),
    ),
  };
}

interface MountedKeyBinding {
  id: string;
  owner: PagerInteractionOwner;
  key: string;
  witness?: InteractionWitnessIR;
  command: PagerInteractionCommand;
  generation: number;
}

export interface MountedPagerBinding {
  id: string;
  owner: PagerInteractionOwner;
  definition: PagerInteractionDefinition;
  commands: Readonly<Record<'prev' | 'next', PagerInteractionCommand>>;
  generation(): string;
  bindingGeneration(): number;
  centerRevision(): number;
  centerValid(): boolean;
  /** Wire code for `animateCenter=` (0 never, 1 external, 2 always). */
  centerAnimation(): 0 | 1 | 2;
  /**
   * Direction the center moved to reach the current `centerRevision`
   * (0 none/unknown, 1 prev, 2 next). Resolved from the turn the runtime itself
   * commanded, else from an adjacent `order=` ordinal step.
   */
  centerDirection(): 0 | 1 | 2;
  updateCenterIdentity(value: unknown, order?: unknown): void;
  witnessAvailable(direction: "prev" | "next"): boolean;
  turnToken(): number;
  acceptTurnToken(token: number): void;
  commitTurn(
    direction: "prev" | "next",
    token: number,
    gestureStartBindingGeneration: number,
    binding?: "pager-prev" | "pager-next" | "pager-arrows",
  ): "dispatched" | "stale-generation" | "invalid-center";
  commit(
    direction: "prev" | "next",
    binding?: "pager-prev" | "pager-next" | "pager-arrows",
  ): void;
}

export interface PagerInteractionOwner {
  readonly rootId: number;
  readonly ownerInstanceId: string;
  readonly hostNodes?: () => Array<{ id: number }>;
  activate(callback: () => void): void;
  registerCleanup(dispose: () => void): void;
}

export interface PagerInteractionDefinition {
  readonly axis: PagerNodeIR['axis'];
  readonly keys?: PagerNodeIR['keys'];
  readonly claim?: string;
  readonly animateCenter?: PagerNodeIR['animateCenter'];
  readonly prevWitness?: InteractionWitnessIR;
  readonly nextWitness?: InteractionWitnessIR;
  readonly hasOrder: boolean;
}

export interface PagerInteractionCommand {
  /** Stable command/argument identity used by the lease generation. */
  identity(): Record<string, unknown> | null;
  /** Inspector-facing equality-token projection. */
  evaluated(): Record<string, unknown> | null;
  dispatch(
    binding: InteractionDispatchContext['binding'],
    commandInstanceId: string,
    generation: number,
  ): void;
}

export interface PagerInteractionRegistrationOptions {
  /** Publish a turn token into the pager render so hosts can observe the ack. */
  onTurnToken?(token: number): void;
}

type PagerCenterIdentity = string | number | boolean | null;
const UNSET_PAGER_CENTER = Symbol("unset-pager-center");

/**
 * Wire encoding for the presentation hint a host needs to animate a center
 * change it did not originate. `centerRevision` is a monotonic counter, so the
 * direction has to travel beside it.
 */
export const PAGER_CENTER_ANIMATION = { never: 0, external: 1, always: 2 } as const;
export const PAGER_CENTER_DIRECTION = { none: 0, prev: 1, next: 2 } as const;

function pagerCenterAnimationCode(
  mode: PagerCenterAnimationIR | undefined,
): 0 | 1 | 2 {
  return mode ? PAGER_CENTER_ANIMATION[mode] : PAGER_CENTER_ANIMATION.never;
}

/** An ordinal is only usable when it is a finite integer within i32 range. */
function pagerOrdinal(value: unknown): number | null {
  if (typeof value !== "number" || !Number.isInteger(value)) return null;
  if (value < -0x8000_0000 || value > 0x7fff_ffff) return null;
  return value;
}

function isPagerCenterIdentity(value: unknown): value is PagerCenterIdentity {
  return (
    value === null ||
    typeof value === "string" ||
    typeof value === "boolean" ||
    typeof value === "number"
  );
}

function sameValueZero(
  left: PagerCenterIdentity,
  right: PagerCenterIdentity,
): boolean {
  return (
    left === right ||
    (typeof left === "number" &&
      typeof right === "number" &&
      Number.isNaN(left) &&
      Number.isNaN(right))
  );
}

function pagerCenterKey(value: PagerCenterIdentity): string {
  if (value === null) return "null";
  if (typeof value === "string") return `string:${JSON.stringify(value)}`;
  if (typeof value === "number")
    return `number:${Object.is(value, -0) ? "0" : String(value)}`;
  return `boolean:${String(value)}`;
}

function nextPagerRevision(value: number, label: string): number {
  if (value >= 0xffff_ffff)
    throw new Error(`[contract] ${label} exhausted its u32 revision space`);
  return value + 1;
}

interface InteractionState {
  keys: Set<MountedKeyBinding>;
  pagers: Map<string, MountedPagerBinding>;
  diagnostics: Array<{ code: string; message: string; atMs: number }>;
  keyListenerInstalled: boolean;
  nativeKeyDisposers: Map<string, () => void>;
}

function state(): InteractionState {
  const scope = globalThis as {
    __exactContractInteractionState?: InteractionState;
  };
  return (scope.__exactContractInteractionState ??= {
    keys: new Set(),
    pagers: new Map(),
    diagnostics: [],
    keyListenerInstalled: false,
    nativeKeyDisposers: new Map(),
  });
}

function witnessSelector(witness: InteractionWitnessIR): string {
  const escaped =
    typeof CSS !== "undefined" && typeof CSS.escape === "function"
      ? CSS.escape(witness.value)
      : witness.value.replace(/["\\]/g, "\\$&");
  return witness.kind === "testId"
    ? `[data-testid="${escaped}"]`
    : `[aria-label="${escaped}"]`;
}

function domRoot(rootId: number): HTMLElement | null {
  if (typeof document === "undefined") return null;
  return document.querySelector<HTMLElement>(
    `[data-exact-mirror-root="${rootId}"], [data-exact-contract-host-root="${rootId}"]`,
  );
}

function rootForTarget(target: EventTarget | null): HTMLElement | null {
  return target instanceof Element
    ? target.closest<HTMLElement>(
        "[data-exact-mirror-root], [data-exact-contract-host-root]",
      )
    : null;
}

interface InteractionHostOwner {
  readonly hostNodes?: () => Array<{ id: number }>;
}

function witnessElements(
  witness: InteractionWitnessIR | undefined,
  instance: InteractionHostOwner,
): HTMLElement[] {
  if (!witness || typeof document === "undefined") return [];
  const selector = witnessSelector(witness);
  const roots = (instance.hostNodes?.() ?? [])
    .map(
      (node) =>
        (
          globalThis as {
            __exactDomIdentity?: {
              elementForViewId(viewId: number): HTMLElement | null;
            };
          }
        ).__exactDomIdentity?.elementForViewId(node.id) ?? null,
    )
    .filter(
      (element): element is HTMLElement =>
        element !== null && element.isConnected,
    );
  return roots
    .flatMap((root) => [
      ...(root.matches(selector) ? [root] : []),
      ...Array.from(root.querySelectorAll<HTMLElement>(selector)),
    ])
    .filter(
      (element) =>
        element.isConnected &&
        !element.hidden &&
        element.getAttribute("aria-disabled") !== "true" &&
        !(element as HTMLButtonElement).disabled &&
        getComputedStyle(element).display !== "none" &&
        getComputedStyle(element).visibility !== "hidden",
    );
}

function nativeWitnessCount(
  witness: InteractionWitnessIR | undefined,
  instance: InteractionHostOwner,
): number {
  if (!witness || typeof document !== "undefined") return 0;
  let count = 0;
  const visit = (node: unknown): void => {
    if (!node || typeof node !== "object") return;
    const candidate = node as {
      kind?: number;
      originalProps?: Record<string, unknown>;
      style?: Record<string, unknown>;
      children?: unknown[];
    };
    const props = candidate.originalProps ?? {};
    const value =
      witness.kind === "testId"
        ? (props.testId ?? props.testID ?? props["data-testid"])
        : (props.accessibilityLabel ?? props.label);
    const hidden = props.hidden === true || candidate.style?.display === "none";
    const disabled =
      props.disabled === true || props.accessibilityDisabled === true;
    if (value === witness.value && !hidden && !disabled) count += 1;
    candidate.children?.forEach(visit);
  };
  (instance.hostNodes?.() ?? []).forEach(visit);
  return count;
}

function witnessCount(
  witness: InteractionWitnessIR | undefined,
  instance: InteractionHostOwner,
): number {
  return typeof document === "undefined"
    ? nativeWitnessCount(witness, instance)
    : witnessElements(witness, instance).length;
}

interface PagerHostNodeShape {
  id?: number;
  kind?: number;
  parent?: unknown;
  originalProps?: Record<string, unknown>;
  children?: unknown[];
}

/**
 * Resolve the renderer-owned facts that participate in a pager lease. Keeping
 * this projection beside the monotonic generation makes web and native sample
 * the same identity rather than independently hashing partial topology.
 */
function pagerHostTopology(
  id: string,
  claim: string,
  instance: InteractionHostOwner,
): Record<string, unknown> {
  const roots = instance.hostNodes?.() ?? [];
  const matches: PagerHostNodeShape[] = [];
  const visit = (candidate: unknown): void => {
    if (!candidate || typeof candidate !== "object") return;
    const node = candidate as PagerHostNodeShape;
    if (node.originalProps?.__exactPagerId === id) matches.push(node);
    node.children?.forEach(visit);
  };
  roots.forEach(visit);
  if (matches.length !== 1) {
    return {
      pager: {
        status: matches.length === 0 ? "missing" : "ambiguous",
        id: null,
      },
      claim: { status: "unresolved", id: null },
      cells: { prev: 0, current: 0, next: 0 },
    };
  }

  const pager = matches[0]!;
  const cells = { prev: 0, current: 0, next: 0 };
  const countCells = (candidate: unknown): void => {
    if (!candidate || typeof candidate !== "object") return;
    const node = candidate as PagerHostNodeShape;
    const side = node.originalProps?.__exactPagerCell;
    if (side === "prev" || side === "current" || side === "next")
      cells[side] += 1;
    node.children?.forEach(countCells);
  };
  countCells(pager);

  if (claim.length === 0) {
    return {
      pager: { status: "resolved", id: pager.id ?? null },
      claim: { status: "self", id: pager.id ?? null },
      cells,
    };
  }
  const claimMatches: number[] = [];
  for (let current = pager.parent; current && typeof current === "object";) {
    const ancestor = current as PagerHostNodeShape;
    if (ancestor.kind === 0) break;
    const props = ancestor.originalProps ?? {};
    const testId = props.testId ?? props.testID ?? props["data-testid"];
    if (testId === claim && typeof ancestor.id === "number")
      claimMatches.push(ancestor.id);
    current = ancestor.parent;
  }
  return {
    pager: { status: "resolved", id: pager.id ?? null },
    claim:
      claimMatches.length > 1
        ? { status: "ambiguous", id: null }
        : claimMatches.length === 1
          ? { status: "resolved", id: claimMatches[0] }
          : { status: "missing-fallback", id: pager.id ?? null },
    cells,
  };
}

function activeModal(): HTMLElement | null {
  if (typeof document === "undefined") return null;
  const modals = Array.from(
    document.querySelectorAll<HTMLElement>('[aria-modal="true"]'),
  ).filter(
    (element) =>
      element.isConnected && getComputedStyle(element).display !== "none",
  );
  return modals.at(-1) ?? null;
}

function domDepth(element: Element): number {
  let depth = 0;
  for (
    let current: Element | null = element;
    current;
    current = current.parentElement
  )
    depth += 1;
  return depth;
}

function isFocusedControlActivation(event: KeyboardEvent): boolean {
  if (event.key !== "Enter" && event.key !== " " && event.key !== "Space")
    return false;
  const target = event.target as HTMLElement | null;
  if (!target) return false;
  return target.matches(
    'button, a[href], input, textarea, select, [role="button"], [role="link"]',
  );
}

function editableTarget(target: EventTarget | null): boolean {
  const element = target as HTMLElement | null;
  return Boolean(
    element &&
    (element.isContentEditable || element.matches("input, textarea, select")),
  );
}

function noteDiagnostic(code: string, message: string): void {
  const diagnostics = state().diagnostics;
  diagnostics.push({ code, message, atMs: Date.now() });
  while (diagnostics.length > 100) diagnostics.shift();
}

function handleKeyEvent(event: KeyboardEvent): void {
  if (
    event.defaultPrevented ||
    event.metaKey ||
    event.ctrlKey ||
    event.altKey ||
    event.isComposing ||
    event.key === "Unidentified" ||
    editableTarget(event.target) ||
    isFocusedControlActivation(event)
  )
    return;
  const normalized = /^[\x20-\x7e]$/.test(event.key)
    ? event.key.toLowerCase()
    : event.key;
  const singleCharacter = normalized.length === 1;
  if (
    singleCharacter &&
    (readInputKeyboardPresence() !== "present" ||
      !getCharacterShortcutsEnabled())
  )
    return;
  const modal = activeModal();
  const targetedRoot =
    rootForTarget(event.target) ?? rootForTarget(document.activeElement);
  let entries = [...state().keys];
  if (targetedRoot) {
    entries = entries.filter(
      (entry) => domRoot(entry.owner.rootId) === targetedRoot,
    );
  } else {
    const rootIds = new Set(entries.map((entry) => entry.owner.rootId));
    if (rootIds.size > 1) {
      noteDiagnostic(
        "key_root_ambiguous",
        `key "${normalized}" reached ${rootIds.size} roots without a focused owner; dispatch dropped`,
      );
      return;
    }
  }
  const candidates = entries.flatMap((entry) =>
    entry.key === normalized
      ? witnessElements(entry.witness, entry.owner)
          .filter((element) => !modal || modal.contains(element))
          .map((element) => ({ entry, element, depth: domDepth(element) }))
      : [],
  );
  if (candidates.length === 0) return;
  const maxDepth = Math.max(...candidates.map((candidate) => candidate.depth));
  const winners = candidates.filter(
    (candidate) => candidate.depth === maxDepth,
  );
  if (winners.length !== 1) {
    noteDiagnostic(
      "key_equal_depth_conflict",
      `key "${normalized}" has ${winners.length} equal-depth owners; dispatch dropped`,
    );
    return;
  }
  event.preventDefault();
  const winner = winners[0]!.entry;
  winner.command.dispatch(
    "key",
    winner.id,
    winner.generation,
  );
}

function ensureKeyListener(): void {
  const registry = state();
  if (registry.keyListenerInstalled || typeof document === "undefined") return;
  ensureInputInventoryObserver();
  document.addEventListener("keydown", handleKeyEvent);
  registry.keyListenerInstalled = true;
}

function nativeOwnerDepth(instance: InteractionHostOwner): number {
  let maxDepth = 0;
  for (const hostNode of instance.hostNodes?.() ?? []) {
    let depth = 0;
    for (
      let current: { parent?: unknown } | null = hostNode as {
        parent?: unknown;
      };
      current;
      current =
        current.parent && typeof current.parent === "object"
          ? (current.parent as { parent?: unknown })
          : null
    ) {
      depth += 1;
    }
    maxDepth = Math.max(maxDepth, depth);
  }
  return maxDepth;
}

function nativeOwnerIsWithinFocusScope(
  instance: InteractionHostOwner,
  focusScopeViewId: number | null,
): boolean {
  if (focusScopeViewId === null) return true;
  return (instance.hostNodes?.() ?? []).some((hostNode) => {
    for (
      let current: { id?: unknown; parent?: unknown } | null = hostNode as {
        id?: unknown;
        parent?: unknown;
      };
      current;
      current =
        current.parent && typeof current.parent === "object"
          ? (current.parent as { id?: unknown; parent?: unknown })
          : null
    ) {
      if (current.id === focusScopeViewId) return true;
    }
    return false;
  });
}

function pagerArrowDirection(
  pager: MountedPagerBinding,
  key: string,
): "prev" | "next" | null {
  const axis = pager.definition.keys ?? pager.definition.axis;
  if (axis === "none") return null;
  if (axis === "vertical") {
    return key === "ArrowUp" ? "prev" : key === "ArrowDown" ? "next" : null;
  }
  return key === "ArrowLeft" ? "prev" : key === "ArrowRight" ? "next" : null;
}

function dispatchNativeKey(
  rootId: number,
  key: string,
  focusScopeViewId: number | null,
): void {
  if (key.length === 1 && !getCharacterShortcutsEnabled()) return;
  const candidates: Array<{
    depth: number;
    run: () => void;
    id: string;
  }> = [];
  for (const entry of state().keys) {
    if (
      entry.owner.rootId !== rootId ||
      entry.key !== key ||
      !nativeOwnerIsWithinFocusScope(entry.owner, focusScopeViewId) ||
      witnessCount(entry.witness, entry.owner) !== 1
    )
      continue;
    candidates.push({
      depth: nativeOwnerDepth(entry.owner),
      id: entry.id,
      run: () => entry.command.dispatch(
        "key",
        entry.id,
        entry.generation,
      ),
    });
  }
  for (const pager of state().pagers.values()) {
    if (
      pager.owner.rootId !== rootId ||
      !nativeOwnerIsWithinFocusScope(pager.owner, focusScopeViewId)
    )
      continue;
    const direction = pagerArrowDirection(pager, key);
    if (!direction || !pager.witnessAvailable(direction)) continue;
    candidates.push({
      depth: nativeOwnerDepth(pager.owner),
      id: pager.id,
      run: () => pager.commit(direction, "pager-arrows"),
    });
  }
  if (candidates.length === 0) return;
  const depth = Math.max(...candidates.map((candidate) => candidate.depth));
  const winners = candidates.filter((candidate) => candidate.depth === depth);
  if (winners.length !== 1) {
    noteDiagnostic(
      "native_key_equal_depth_conflict",
      `key "${key}" has ${winners.length} equal-depth owners in root ${rootId}; dispatch dropped`,
    );
    return;
  }
  winners[0]!.run();
}

function refreshNativeKeyRegistrations(): void {
  if (typeof document !== "undefined") return;
  const desired = new Set<string>();
  for (const entry of state().keys)
    desired.add(`${entry.owner.rootId}\0${entry.key}`);
  for (const pager of state().pagers.values()) {
    const axis = pager.definition.keys ?? pager.definition.axis;
    if (axis === "none") continue;
    const keys =
      axis === "vertical"
        ? ["ArrowUp", "ArrowDown"]
        : ["ArrowLeft", "ArrowRight"];
    keys.forEach((key) => desired.add(`${pager.owner.rootId}\0${key}`));
  }
  for (const [key, dispose] of state().nativeKeyDisposers) {
    if (!desired.has(key)) {
      dispose();
      state().nativeKeyDisposers.delete(key);
    }
  }
  for (const composite of desired) {
    if (state().nativeKeyDisposers.has(composite)) continue;
    const separator = composite.indexOf("\0");
    const rootId = Number(composite.slice(0, separator));
    const key = composite.slice(separator + 1);
    state().nativeKeyDisposers.set(
      composite,
      registerNativeContractKeyBinding(
        rootId,
        key,
        (event: NativeContractKeyEvent) =>
          dispatchNativeKey(rootId, key, event.focusScopeViewId),
      ),
    );
  }
}

export function registerComponentInteractions(
  instance: ComponentInstance,
): void {
  if ((instance.def.ir.keys ?? []).length === 0) return;
  const owner: PagerInteractionOwner = {
    rootId: instance.ctx.rootId,
    ownerInstanceId:
      instance.runtimeInstanceId ?? `${instance.def.ir.name}_${nextInstance++}`,
    hostNodes: () => instance.hostNodes?.() ?? [],
    activate: (callback) =>
      instance.ctx.activateAfterHydrationCommit(callback),
    registerCleanup: (dispose) => instance.owner.register(dispose),
  };
  registerCompiledKeyInteractions({
    owner,
    bindings: (instance.def.ir.keys ?? []).map((binding) => ({
      key: binding.key,
      ...(binding.witness ? { witness: binding.witness } : {}),
      command: {
        identity: () => evaluatedCommand(instance, binding.command),
        evaluated: () => evaluatedCommand(instance, binding.command),
        dispatch(bindingKind, commandInstanceId, generation) {
          dispatchCommand(
            instance,
            binding.command,
            bindingKind,
            commandInstanceId,
            generation,
          );
        },
      },
    })),
  });
}

export interface CompiledKeyInteraction {
  readonly key: string;
  readonly witness?: InteractionWitnessIR;
  readonly command: PagerInteractionCommand;
}

export function registerCompiledKeyInteractions(input: {
  readonly owner: PagerInteractionOwner;
  readonly bindings: readonly CompiledKeyInteraction[];
}): void {
  const entries = input.bindings.map((binding, index): MountedKeyBinding => ({
    id: `${input.owner.ownerInstanceId}/key_${index}`,
    owner: input.owner,
    key: binding.key,
    ...(binding.witness ? { witness: binding.witness } : {}),
    command: binding.command,
    generation: 1,
  }));
  let registered = false;
  let disposed = false;
  input.owner.activate(() => {
    if (disposed || registered) return;
    registered = true;
    ensureKeyListener();
    entries.forEach((entry) => state().keys.add(entry));
    refreshNativeKeyRegistrations();
  });
  input.owner.registerCleanup(() => {
    disposed = true;
    if (!registered) return;
    registered = false;
    entries.forEach((entry) => state().keys.delete(entry));
    refreshNativeKeyRegistrations();
  });
}

export const contractInteractionsRuntime: ContractInteractionsRuntime = {
  registerComponent: registerComponentInteractions,
};

export function registerPagerInteraction(
  instance: ComponentInstance,
  node: PagerNodeIR,
  options: PagerInteractionRegistrationOptions = {},
): MountedPagerBinding {
  let nextOpaqueArgumentIdentity = 1;
  const opaqueArgumentIdentities = new Map<unknown, number>();
  const argumentIdentity = (value: unknown): string => {
    if (value === null) return "null";
    if (typeof value === "string" || typeof value === "boolean") {
      return `${typeof value}:${JSON.stringify(value)}`;
    }
    if (typeof value === "number") {
      return `number:${Object.is(value, -0) ? "-0" : String(value)}`;
    }
    const json = canonicalJson(value);
    if (json !== null) return `json:${json}`;
    let identity = opaqueArgumentIdentities.get(value);
    if (identity === undefined) {
      identity = nextOpaqueArgumentIdentity++;
      opaqueArgumentIdentities.set(value, identity);
    }
    return `opaque:${identity}`;
  };
  const command = (expr: Expr): PagerInteractionCommand => ({
    identity() {
      const ref = commandRef(expr);
      if (!ref) return null;
      return {
        action: ref.action,
        arguments: untrack(() =>
          ref.args.map((arg) =>
            argumentIdentity(evalRuntimeExpr(arg, instance.scope)),
          ),
        ),
      };
    },
    evaluated: () => evaluatedCommand(instance, expr),
    dispatch(binding, commandInstanceId, generation) {
      dispatchCommand(instance, expr, binding, commandInstanceId, generation);
    },
  });
  return registerCompiledPagerInteraction({
    owner: {
      rootId: instance.ctx.rootId,
      ownerInstanceId:
        instance.runtimeInstanceId ?? `${instance.def.ir.name}_${nextInstance++}`,
      hostNodes: () => instance.hostNodes?.() ?? [],
      activate: (callback) =>
        instance.ctx.activateAfterHydrationCommit(callback),
      registerCleanup: (dispose) => instance.owner.register(dispose),
    },
    definition: {
      axis: node.axis,
      ...(node.keys !== undefined ? { keys: node.keys } : {}),
      ...(node.claim !== undefined ? { claim: node.claim } : {}),
      ...(node.animateCenter !== undefined
        ? { animateCenter: node.animateCenter }
        : {}),
      ...(node.prevWitness ? { prevWitness: node.prevWitness } : {}),
      ...(node.nextWitness ? { nextWitness: node.nextWitness } : {}),
      hasOrder: node.order !== undefined,
    },
    commands: {
      prev: command(node.prev),
      next: command(node.next),
    },
  }, options);
}

export function registerCompiledPagerInteraction(
  input: {
    readonly owner: PagerInteractionOwner;
    readonly definition: PagerInteractionDefinition;
    readonly commands: Readonly<Record<'prev' | 'next', PagerInteractionCommand>>;
  },
  options: PagerInteractionRegistrationOptions = {},
): MountedPagerBinding {
  const { owner, definition, commands } = input;
  const id = `pager_${nextPager++}`;
  let centerIdentity: PagerCenterIdentity | typeof UNSET_PAGER_CENTER =
    UNSET_PAGER_CENTER;
  let centerIdentityValid = false;
  let currentCenterRevision = 0;
  let currentBindingGeneration = 0;
  let lastBindingKey: string | null = null;
  let invalidCenterDiagnostic = false;
  let currentTurnToken = 0;
  const centerAnimationCode = pagerCenterAnimationCode(
    definition.animateCenter,
  );
  let centerOrdinal: number | null = null;
  let currentCenterDirection: 0 | 1 | 2 = PAGER_CENTER_DIRECTION.none;
  // A turn the runtime commanded knows its own direction. It is consumed by the
  // next center change so that arrow keys and command-bound buttons resolve a
  // direction even when the surface declares no `order=`.
  let commandedDirection: "prev" | "next" | null = null;
  let invalidOrderDiagnostic = false;
  const bindingKey = (): string => {
    const center =
      centerIdentityValid && centerIdentity !== UNSET_PAGER_CENTER
        ? pagerCenterKey(centerIdentity)
        : "invalid-center";
    const witnesses = {
      prev: {
        selector: definition.prevWitness ?? null,
        available: witnessCount(definition.prevWitness, owner),
      },
      next: {
        selector: definition.nextWitness ?? null,
        available: witnessCount(definition.nextWitness, owner),
      },
    };
    return JSON.stringify({
      center,
      axis: definition.axis,
      claim: definition.claim ?? "",
      topology: pagerHostTopology(id, definition.claim ?? "", owner),
      commands: {
        prev: commands.prev.identity(),
        next: commands.next.identity(),
      },
      witnesses,
    });
  };
  /**
   * The ordinal pair is authoritative because both halves are read in the same
   * commit that bumped the revision: an adjacent step is a slide, an explicit
   * multi-step jump has no neighbor cell to slide from and stays a snap. Only
   * when no usable ordinal pair exists does a turn the runtime commanded
   * (arrow keys, command-bound buttons, agent turns) supply the direction.
   */
  const resolveCenterDirection = (
    previousOrdinal: number | null,
    nextOrdinal: number | null,
  ): 0 | 1 | 2 => {
    if (previousOrdinal !== null && nextOrdinal !== null) {
      const delta = nextOrdinal - previousOrdinal;
      if (delta === 1) return PAGER_CENTER_DIRECTION.next;
      if (delta === -1) return PAGER_CENTER_DIRECTION.prev;
      return PAGER_CENTER_DIRECTION.none;
    }
    if (commandedDirection === "prev") return PAGER_CENTER_DIRECTION.prev;
    if (commandedDirection === "next") return PAGER_CENTER_DIRECTION.next;
    return PAGER_CENTER_DIRECTION.none;
  };
  const refreshBindingGeneration = (): number => {
    const nextKey = bindingKey();
    if (lastBindingKey !== nextKey) {
      currentBindingGeneration = nextPagerRevision(
        currentBindingGeneration,
        `${id} binding generation`,
      );
      lastBindingKey = nextKey;
    }
    return currentBindingGeneration;
  };
  const descriptor: MountedPagerBinding = {
    id,
    owner,
    definition,
    commands,
    generation() {
      return String(refreshBindingGeneration());
    },
    bindingGeneration() {
      return refreshBindingGeneration();
    },
    centerRevision() {
      return currentCenterRevision;
    },
    centerValid() {
      return centerIdentityValid;
    },
    centerAnimation() {
      return centerAnimationCode;
    },
    centerDirection() {
      return currentCenterDirection;
    },
    updateCenterIdentity(value, order) {
      // Center identity and ordinal are read in one pass so the ordinal diff is
      // always taken across the same commit that bumped the revision.
      const nextOrdinal = definition.hasOrder ? pagerOrdinal(order) : null;
      if (definition.hasOrder && nextOrdinal === null) {
        if (!invalidOrderDiagnostic) {
          noteDiagnostic(
            "pager-order-invalid",
            `pager ${id} order= must evaluate to a finite integer ordinal; received ${typeof order}`,
          );
          invalidOrderDiagnostic = true;
        }
      } else if (nextOrdinal !== null) {
        invalidOrderDiagnostic = false;
      }
      if (!isPagerCenterIdentity(value)) {
        centerIdentityValid = false;
        centerIdentity = UNSET_PAGER_CENTER;
        centerOrdinal = nextOrdinal;
        currentCenterDirection = PAGER_CENTER_DIRECTION.none;
        commandedDirection = null;
        if (!invalidCenterDiagnostic) {
          noteDiagnostic(
            "pager-center-invalid",
            `pager ${id} value= must evaluate to a stable scalar identity; received ${typeof value}`,
          );
          invalidCenterDiagnostic = true;
        }
        return;
      }
      invalidCenterDiagnostic = false;
      centerIdentityValid = true;
      if (
        centerIdentity === UNSET_PAGER_CENTER ||
        !sameValueZero(centerIdentity, value)
      ) {
        const previousOrdinal = centerOrdinal;
        const first = centerIdentity === UNSET_PAGER_CENTER;
        centerIdentity = value;
        currentCenterRevision = nextPagerRevision(
          currentCenterRevision,
          `${id} center revision`,
        );
        // The first center a pager ever publishes has no predecessor to slide
        // from, so it stays a snap regardless of mode.
        currentCenterDirection = first
          ? PAGER_CENTER_DIRECTION.none
          : resolveCenterDirection(previousOrdinal, nextOrdinal);
      }
      centerOrdinal = nextOrdinal;
      commandedDirection = null;
    },
    witnessAvailable(direction) {
      if (!centerIdentityValid) return false;
      const witness =
        direction === "prev"
          ? definition.prevWitness
          : definition.nextWitness;
      return witnessCount(witness, owner) === 1;
    },
    turnToken() {
      return currentTurnToken;
    },
    acceptTurnToken(token) {
      currentTurnToken = token >>> 0;
    },
    commitTurn(direction, token, gestureStartBindingGeneration, binding) {
      const normalizedToken = token >>> 0;
      const normalizedGeneration = gestureStartBindingGeneration >>> 0;
      if (normalizedToken === 0 || normalizedGeneration === 0)
        return "stale-generation";
      let result: "dispatched" | "stale-generation" | "invalid-center" =
        "dispatched";
      batch(() => {
        const currentGeneration = refreshBindingGeneration();
        if (!centerIdentityValid) {
          result = "invalid-center";
          noteDiagnostic(
            "pager-center-invalid",
            `pager ${id} rejected a turn with an invalid center identity`,
          );
        } else if (normalizedGeneration !== currentGeneration) {
          result = "stale-generation";
          noteDiagnostic(
            "pager-generation-mismatch",
            `pager ${id} dropped turn ${normalizedToken}: began at generation ${normalizedGeneration}, current ${currentGeneration}`,
          );
        } else {
          commandedDirection = direction;
          commands[direction].dispatch(
            binding ?? (direction === "prev" ? "pager-prev" : "pager-next"),
            `${id}/${direction}`,
            normalizedGeneration,
          );
        }
        // The token is published even for a stale/mis-bound turn. Its
        // post-flush descriptor answer carries an unchanged centerRevision,
        // allowing the host to spring back immediately instead of timing out.
        currentTurnToken = normalizedToken;
        options.onTurnToken?.(normalizedToken);
      });
      return result;
    },
    commit(direction, binding) {
      const generation = refreshBindingGeneration();
      if (!centerIdentityValid) return;
      commandedDirection = direction;
      commands[direction].dispatch(
        binding ?? (direction === "prev" ? "pager-prev" : "pager-next"),
        `${id}/${direction}`,
        generation,
      );
    },
  };
  owner.activate(() => {
    ensureKeyListener();
    state().pagers.set(id, descriptor);
    refreshNativeKeyRegistrations();
    owner.registerCleanup(() => {
      state().pagers.delete(id);
      refreshNativeKeyRegistrations();
    });
  });
  return descriptor;
}

export function getMountedPagerBinding(
  id: string,
): MountedPagerBinding | undefined {
  return state().pagers.get(id);
}

export function getMountedInteractionSnapshot(
  rootId?: number,
): Record<string, unknown> {
  const keyEntries = [...state().keys].filter(
    (entry) => rootId === undefined || entry.owner.rootId === rootId,
  );
  const pagerEntries = [...state().pagers.values()].filter(
    (pager) => rootId === undefined || pager.owner.rootId === rootId,
  );
  return {
    schemaVersion: 1,
    rootId: rootId ?? null,
    characterShortcutsEnabled: getCharacterShortcutsEnabled(),
    keyboard: readInputKeyboardPresence(),
    keys: keyEntries.map((entry) => {
      const mountedWitnessCount = witnessCount(
        entry.witness,
        entry.owner,
      );
      return {
        id: entry.id,
        key: entry.key,
        witness: entry.witness,
        command:
          mountedWitnessCount === 1
            ? entry.command.evaluated()
            : null,
        enabled: mountedWitnessCount === 1,
        disableReason: mountedWitnessCount === 1 ? null : "witness-unavailable",
      };
    }),
    pagers: pagerEntries.map((pager) => {
      const element =
        typeof document === "undefined"
          ? null
          : document.querySelector<HTMLElement>(
              `[data-exact-pager-id="${pager.id}"]`,
            );
      const cellCount = (side: string): number =>
        element?.querySelectorAll(`[data-exact-pager-cell="${side}"]`).length ??
        0;
      const claimMatches: HTMLElement[] = [];
      if (element && pager.definition.claim) {
        for (
          let current = element.parentElement;
          current;
          current = current.parentElement
        ) {
          if (current.dataset.testid === pager.definition.claim)
            claimMatches.push(current);
        }
      }
      const currentCount = cellCount("current");
      const prevWitnessCount = witnessCount(
        pager.definition.prevWitness,
        pager.owner,
      );
      const nextWitnessCount = witnessCount(
        pager.definition.nextWitness,
        pager.owner,
      );
      const claimStatus =
        !pager.definition.claim || claimMatches.length === 1
          ? "resolved"
          : claimMatches.length === 0
            ? "missing-degraded"
            : "ambiguous-disabled";
      return {
        id: pager.id,
        axis: pager.definition.axis,
        keys: pager.definition.keys ?? null,
        claim: pager.definition.claim ?? null,
        claimStatus,
        generation: pager.generation(),
        bindingGeneration: pager.bindingGeneration(),
        centerRevision: pager.centerRevision(),
        centerValid: pager.centerValid(),
        animateCenter: pager.definition.animateCenter ?? "never",
        centerDirection:
          pager.centerDirection() === PAGER_CENTER_DIRECTION.prev
            ? "prev"
            : pager.centerDirection() === PAGER_CENTER_DIRECTION.next
              ? "next"
              : null,
        cells: {
          prev: cellCount("prev"),
          current: currentCount,
          next: cellCount("next"),
        },
        enabled:
          pager.centerValid() &&
          currentCount === 1 &&
          claimStatus !== "ambiguous-disabled",
        disableReason:
          currentCount !== 1
            ? "current-cell-cardinality"
            : claimStatus === "ambiguous-disabled"
              ? "claim-ambiguous"
              : !pager.centerValid()
                ? "center-invalid"
                : null,
        prevWitness: pager.definition.prevWitness,
        nextWitness: pager.definition.nextWitness,
        prevCommand:
          prevWitnessCount === 1
            ? pager.commands.prev.evaluated()
            : null,
        nextCommand:
          nextWitnessCount === 1
            ? pager.commands.next.evaluated()
            : null,
        prevEnabled: cellCount("prev") === 1 && prevWitnessCount === 1,
        nextEnabled: cellCount("next") === 1 && nextWitnessCount === 1,
        prevDisableReason:
          cellCount("prev") !== 1
            ? "neighbor-unavailable"
            : prevWitnessCount !== 1
              ? "witness-unavailable"
              : null,
        nextDisableReason:
          cellCount("next") !== 1
            ? "neighbor-unavailable"
            : nextWitnessCount !== 1
              ? "witness-unavailable"
              : null,
      };
    }),
    diagnostics: [...state().diagnostics],
  };
}

export function _resetInteractionsForTests(): void {
  const registry = state();
  if (registry.keyListenerInstalled && typeof document !== "undefined") {
    document.removeEventListener("keydown", handleKeyEvent);
  }
  registry.keys.clear();
  registry.pagers.clear();
  registry.nativeKeyDisposers.forEach((dispose) => dispose());
  registry.nativeKeyDisposers.clear();
  registry.diagnostics.length = 0;
  registry.keyListenerInstalled = false;
  currentDispatch = null;
  lastDispatch = null;
  nextCorrelation = 1;
  nextInstance = 1;
  nextPager = 1;
}

(
  globalThis as typeof globalThis & {
    __exactGetContractPagerBinding?: (
      id: string,
    ) => MountedPagerBinding | undefined;
  }
).__exactGetContractPagerBinding = getMountedPagerBinding;
(
  globalThis as typeof globalThis & {
    __exactGetContractPagerNativeDescriptor?: (
      id: string,
    ) => Record<string, unknown> | null;
  }
).__exactGetContractPagerNativeDescriptor = (id) => {
  const pager = getMountedPagerBinding(id);
  if (!pager || !pager.centerValid() || pager.centerRevision() === 0)
    return null;
  return {
    bindingGeneration: pager.bindingGeneration(),
    centerRevision: pager.centerRevision(),
    turnToken: pager.turnToken(),
    prevEnabled: pager.witnessAvailable("prev"),
    nextEnabled: pager.witnessAvailable("next"),
    centerAnimation: pager.centerAnimation(),
    centerDirection: pager.centerDirection(),
  };
};
(
  globalThis as typeof globalThis & {
    __exactMountedInteractionSnapshot?: (
      rootId?: number,
    ) => Record<string, unknown>;
  }
).__exactMountedInteractionSnapshot = getMountedInteractionSnapshot;
