import type {
  EffectEvidenceDiagnostics,
  EffectEvidenceLink,
  EffectJournalSink,
  EffectSupervisor,
} from './effect-supervisor.js';

export interface ContractEffectEvidenceBroker {
  attach(input: Omit<EffectEvidenceLink, 'version' | 'observedAtEpoch'>): EffectEvidenceLink;
  snapshot(): readonly EffectEvidenceLink[];
  diagnostics(): EffectEvidenceDiagnostics;
}

export interface ContractEffectEvidenceBinding {
  broker: ContractEffectEvidenceBroker;
  dispose(): void;
}

export type ContractEffectEvidenceFactory = (input: {
  supervisor: EffectSupervisor;
  journal: EffectJournalSink;
  runtimeId: string;
}) => ContractEffectEvidenceBinding;

const EMPTY_REJECTIONS = Object.freeze({
  'unknown-attempt': 0,
  'wrong-attempt': 0,
  duplicate: 0,
  contradictory: 0,
  'posture-mismatch': 0,
  'evidence-not-allowed': 0,
});

const unavailableBroker: ContractEffectEvidenceBroker = Object.freeze({
  attach(): EffectEvidenceLink {
    throw new Error(
      '[contract] effect-evidence capture is unavailable in the slim production runtime',
    );
  },
  snapshot: () => Object.freeze([]),
  diagnostics: () => Object.freeze({
    version: 1 as const,
    accepted: 0,
    rejected: EMPTY_REJECTIONS,
    promisedMissing: Object.freeze([]),
    journalObserverFailures: 0,
  }),
});

let factory: ContractEffectEvidenceFactory = () => ({
  broker: unavailableBroker,
  dispose() {},
});

export function installContractEffectEvidenceFactory(
  next: ContractEffectEvidenceFactory,
): void {
  factory = next;
}

export function createContractEffectEvidenceBinding(input: {
  supervisor: EffectSupervisor;
  journal: EffectJournalSink;
  runtimeId: string;
}): ContractEffectEvidenceBinding {
  return factory(input);
}
