// @system @ref LLP 0386 §3.8.1 — bounded diagnostics for authored opaque
// helpers invoked during escrowed hydration preparation. This tiny module is
// separate from the manifest/adoption implementation so generated P4
// programs do not retain the full hydration validator merely to report an
// allowed opaque-call exception.

import type { Span } from '../compiler/ir.js';

export interface ContractHydrationOpaquePrepareDiagnostic {
  code: 'CONTRACT_HYDRATION_OPAQUE_PREPARE_CALL';
  component: string;
  sourcePath?: string;
  importName: string;
  importSpec: string;
  span: Span;
}

declare global {
  // eslint-disable-next-line no-var
  var __exactContractHydrationOpaquePrepareDiagnostics:
    | ContractHydrationOpaquePrepareDiagnostic[]
    | undefined;
}

export function recordContractHydrationOpaquePrepareCall(
  diagnostic: Omit<
    ContractHydrationOpaquePrepareDiagnostic,
    'code'
  >,
): void {
  const rows =
    globalThis.__exactContractHydrationOpaquePrepareDiagnostics ??= [];
  rows.push({
    code: 'CONTRACT_HYDRATION_OPAQUE_PREPARE_CALL',
    ...diagnostic,
  });
  if (rows.length > 32) rows.shift();
}

export function contractHydrationOpaquePrepareDiagnostics(): readonly ContractHydrationOpaquePrepareDiagnostic[] {
  return (
    globalThis.__exactContractHydrationOpaquePrepareDiagnostics ?? []
  ).map((row) => ({
    ...row,
    span: { ...row.span },
  }));
}
