// @system @ref LLP 0291 / LLP 0373 phase 3c — lightweight browser image
// scheme lookup. Source selection and ThumbHash decoding remain opt-in.

import type { ImageColorScheme } from './types.js';

export function getRuntimeImageColorScheme(): ImageColorScheme {
  const documentValue = readDocumentColorScheme();
  if (documentValue) return documentValue;
  const themeValue = readExactThemeColorScheme();
  return themeValue ?? 'light';
}

function readDocumentColorScheme(): ImageColorScheme | undefined {
  const doc = (globalThis as {
    document?: {
      documentElement?: {
        getAttribute?: (name: string) => string | null;
      };
    };
  }).document;
  const root = doc?.documentElement;
  if (!root || typeof root.getAttribute !== 'function') return undefined;

  // Keep the first attribute in sync with EXACT_SCHEME_ATTRIBUTE without
  // making the renderer depend on Facet.
  for (const attr of ['data-scheme', 'data-exact-color-scheme']) {
    const value = root.getAttribute(attr);
    if (value === 'light' || value === 'dark') return value;
  }
  return undefined;
}

function readExactThemeColorScheme(): ImageColorScheme | undefined {
  const state = (globalThis as {
    __exactExperienceRegistryState?: {
      theme?: { scheme?: unknown } | null;
    };
  }).__exactExperienceRegistryState;
  const scheme = state?.theme?.scheme;
  return scheme === 'light' || scheme === 'dark' ? scheme : undefined;
}
