const SYSTEM_SYMBOL_PREFIX = 'system-symbol:';

/**
 * Apple hosts interpret this source namespace as an SF Symbol. Other hosts
 * must treat it as an unsupported platform source, not as a fetchable URL.
 */
export function isSystemSymbolImageSource(source: unknown): boolean {
  if (typeof source === 'string') {
    return source.trim().startsWith(SYSTEM_SYMBOL_PREFIX);
  }
  if (
    source !== null &&
    typeof source === 'object' &&
    'uri' in source &&
    typeof source.uri === 'string'
  ) {
    return source.uri.trim().startsWith(SYSTEM_SYMBOL_PREFIX);
  }
  return false;
}
