// @system @ref LLP 0362, LLP 0373 phase 3c — optional replay-capture runtime.
// Ordinary production sessions publish through this inert seam; importing the
// replay capture installs the ownership, lease, and recording implementation.

export type ContractRuntimeReplayEvent =
  | {
      kind: 'module-evaluated';
      moduleId: string;
      sourceVersion: string;
      irVersion: number;
    }
  | {
      kind: 'oracle-rng';
      siteId: string;
      logicalInstancePath: readonly string[];
      value: number;
    }
  | { kind: 'clock-read'; value: number }
  | {
      kind: 'timer-submission';
      timerId: string;
      timerKind: 'every' | 'after';
      delayMs: number;
    }
  | {
      kind: 'timer-fire';
      timerId: string;
      timerKind: 'every' | 'after';
      delayMs: number;
    }
  | {
      kind: 'invocation-entry';
      invocationId: string;
      action: string;
      args: unknown[];
    }
  | { kind: 'invocation-thenable'; invocationId: string }
  | {
      kind: 'invocation-exit';
      invocationId: string;
      status: 'ok' | 'error';
      error?: string;
    }
  | {
      kind: 'state-write';
      instancePath: readonly string[];
      slot: string;
      invocationId?: string;
      before: unknown;
      after: unknown;
    };

export interface ContractRuntimeReplayObserver {
  record(event: ContractRuntimeReplayEvent): void;
  captureValue?(value: unknown): unknown;
}

export type ReplayCaptureRevocationReason =
  'released' | 'expired' | 'runtime-disposed' | 'process-death';

export interface ContractReplayRuntimeTarget {
  readonly id: string;
  readonly isDisposed: boolean;
  resetRootsForReplayCapture(): void;
}

export interface ContractReplayCaptureLeaseInput {
  owner: object;
  leaseId: string;
  token: string;
  expiresAtMs: number;
  revoke(reason: Exclude<ReplayCaptureRevocationReason, 'released'>): void;
}

interface ContractReplayRuntimeImplementation {
  setObserver(
    runtime: ContractReplayRuntimeTarget,
    observer: ContractRuntimeReplayObserver | null,
  ): () => void;
  acquire(
    runtime: ContractReplayRuntimeTarget,
    input: ContractReplayCaptureLeaseInput,
  ): void;
  renew(
    runtime: ContractReplayRuntimeTarget,
    owner: object,
    token: string,
    expiresAtMs: number,
  ): void;
  assert(
    runtime: ContractReplayRuntimeTarget,
    owner: object,
    token: string,
  ): void;
  release(
    runtime: ContractReplayRuntimeTarget,
    owner: object,
    token: string,
  ): void;
  processDeath(runtime: ContractReplayRuntimeTarget): void;
  record(
    runtime: ContractReplayRuntimeTarget,
    event: ContractRuntimeReplayEvent,
  ): void;
  registerModule(
    runtime: ContractReplayRuntimeTarget,
    module: { moduleId: string; sourceVersion: string; irVersion: number },
  ): void;
  captureValue(runtime: ContractReplayRuntimeTarget, value: unknown): unknown;
  dispose(runtime: ContractReplayRuntimeTarget): void;
}

let implementation: ContractReplayRuntimeImplementation | null = null;

export function installContractReplayRuntime(
  next: ContractReplayRuntimeImplementation,
): void {
  implementation = next;
}

function requireImplementation(): ContractReplayRuntimeImplementation {
  if (!implementation) {
    throw new Error(
      '[contract-replay] replay capture is unavailable in the slim production runtime; import the full Contract runtime or replay-capture entry',
    );
  }
  return implementation;
}

export const setContractReplayObserver = (
  runtime: ContractReplayRuntimeTarget,
  observer: ContractRuntimeReplayObserver | null,
): (() => void) => requireImplementation().setObserver(runtime, observer);

export const acquireContractReplayCaptureLease = (
  runtime: ContractReplayRuntimeTarget,
  input: ContractReplayCaptureLeaseInput,
): void => requireImplementation().acquire(runtime, input);

export const renewContractReplayCaptureLease = (
  runtime: ContractReplayRuntimeTarget,
  owner: object,
  token: string,
  expiresAtMs: number,
): void => requireImplementation().renew(runtime, owner, token, expiresAtMs);

export const assertContractReplayCaptureLease = (
  runtime: ContractReplayRuntimeTarget,
  owner: object,
  token: string,
): void => requireImplementation().assert(runtime, owner, token);

export const releaseContractReplayCaptureLease = (
  runtime: ContractReplayRuntimeTarget,
  owner: object,
  token: string,
): void => requireImplementation().release(runtime, owner, token);

export function notifyContractReplayCaptureProcessDeath(
  runtime: ContractReplayRuntimeTarget,
): void {
  implementation?.processDeath(runtime);
}

export function recordContractReplayEvent(
  runtime: ContractReplayRuntimeTarget,
  event: ContractRuntimeReplayEvent,
): void {
  implementation?.record(runtime, event);
}

export function registerContractReplayModule(
  runtime: ContractReplayRuntimeTarget,
  module: { moduleId: string; sourceVersion: string; irVersion: number },
): void {
  implementation?.registerModule(runtime, module);
}

export function captureContractReplayValue(
  runtime: ContractReplayRuntimeTarget,
  value: unknown,
): unknown {
  return implementation?.captureValue(runtime, value) ?? value;
}

export function disposeContractReplayRuntime(
  runtime: ContractReplayRuntimeTarget,
): void {
  implementation?.dispose(runtime);
}
