import type * as CaptureImplementation from './route-payload-capture.js';

export interface ContractRoutePayloadCaptureRuntime {
  create: typeof CaptureImplementation.createContractRoutePayloadCaptureState;
  recordEach: typeof CaptureImplementation.recordContractRoutePayloadEachExpansion;
  registerElement: typeof CaptureImplementation.registerContractRoutePayloadElementCapture;
  registerText: typeof CaptureImplementation.registerContractRoutePayloadTextCapture;
  captureTree: typeof CaptureImplementation.captureMountedContractRoutePayloadTree;
  readExpression: typeof CaptureImplementation.readContractRoutePayloadExpression;
}

let installedRuntime: ContractRoutePayloadCaptureRuntime | undefined;

export function installContractRoutePayloadCaptureRuntime(
  runtime: ContractRoutePayloadCaptureRuntime,
): void {
  installedRuntime = runtime;
}

function runtime(): ContractRoutePayloadCaptureRuntime {
  if (!installedRuntime) {
    throw new Error(
      '[contract] route-payload capture requires the build-time capture runtime.',
    );
  }
  return installedRuntime;
}

export function createContractRoutePayloadCaptureState(
  ...args: Parameters<ContractRoutePayloadCaptureRuntime['create']>
): ReturnType<ContractRoutePayloadCaptureRuntime['create']> {
  return runtime().create(...args);
}

export function recordContractRoutePayloadEachExpansion(
  ...args: Parameters<ContractRoutePayloadCaptureRuntime['recordEach']>
): void {
  if (args[0] === undefined) return;
  runtime().recordEach(...args);
}

export function registerContractRoutePayloadElementCapture(
  ...args: Parameters<ContractRoutePayloadCaptureRuntime['registerElement']>
): void {
  runtime().registerElement(...args);
}

export function registerContractRoutePayloadTextCapture(
  ...args: Parameters<ContractRoutePayloadCaptureRuntime['registerText']>
): void {
  runtime().registerText(...args);
}

export function captureMountedContractRoutePayloadTree(
  ...args: Parameters<ContractRoutePayloadCaptureRuntime['captureTree']>
): ReturnType<ContractRoutePayloadCaptureRuntime['captureTree']> {
  return runtime().captureTree(...args);
}

export function readContractRoutePayloadExpression(
  ...args: Parameters<ContractRoutePayloadCaptureRuntime['readExpression']>
): ReturnType<ContractRoutePayloadCaptureRuntime['readExpression']> {
  return runtime().readExpression(...args);
}

export function _resetContractRoutePayloadCaptureRuntimeForTests(): void {
  installedRuntime = undefined;
}
