// @system @ref LLP 0185 S2 — straight-line text view construction.

import {
  appendChild,
  createTextInstance,
  insertBefore,
  removeChild,
  updateTextContent,
  type ElementNode,
  type RootNode,
  type TextNode,
} from '@exact/renderer/host-ops';

import type { Span, ViewNodeIR } from '../compiler/ir.js';
import {
  attachContractHydrationTextId,
  contractHydrationNodeId,
} from './hydration.js';
import {
  runWithContractErrorLocus,
  type ContractErrorLocus,
} from './error-locus-runtime.js';
import {
  getOwner,
  isReactiveIntrospectionEnabled,
  ownedEffect,
  type ReactiveNodeOptions,
} from './signals.js';
import { registerContractRoutePayloadTextCapture } from './route-payload-capture-runtime.js';
import type { Scope } from './interpreter.js';
import type { AnchorFn, Mounted, MountEnv } from './view.js';

type HostParent = ElementNode | RootNode;
const VIEW_EVAL = { identFallbackToString: true } as const;

type ContractAotTextEvaluator = (
  scope: Scope,
  options: typeof VIEW_EVAL,
) => unknown;

/** Compact generated ABI: retain the full authored locus without repeating
 * object keys in every production text closure. */
export type ContractAotTextPlan = readonly [
  valueOrEvaluate: unknown,
  line: number,
  col: number,
  len: number,
  offset: number,
  tokenPath?: string,
];

type ContractAotTextInstallBinding = (
  textNode: TextNode,
  locus: ContractErrorLocus,
  reactiveOptions: ReactiveNodeOptions | undefined,
) => boolean;

export function mountContractText(
  plan: ContractAotTextPlan,
  node: ViewNodeIR,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  onCreate?: (textNode: TextNode) => void,
  installBinding?: ContractAotTextInstallBinding,
): Mounted {
  const [valueOrEvaluate, line, col, len, offset, tokenPath] = plan;
  const literal = typeof valueOrEvaluate !== 'function';
  const structuralIdValue = env.ids.get(node) ?? null;
  const readValue = (): unknown => literal
    ? valueOrEvaluate
    : (valueOrEvaluate as ContractAotTextEvaluator)(env.scope, VIEW_EVAL);
  const span: Span = { line, col, len, offset };
  const textNode = createTextInstance('');
  const structuralId = structuralIdValue ?? undefined;
  const hydrationNodeId = structuralId && env.ctx.hydration?.capture
    ? hydrationNodeIdFor(env, structuralId)
    : undefined;
  if (structuralId && hydrationNodeId && env.ctx.hydration?.capture) {
    attachContractHydrationTextId(textNode, hydrationNodeId);
    env.ctx.hydration.capture.recordNode({
      host: textNode,
      nodeId: hydrationNodeId,
      structuralId,
      sourcePath: env.component.file.sourcePath,
      sourceVersion: env.component.file.sourceVersion,
      componentName: env.component.name,
      kind: 'text',
    });
  }
  if (env.ctx.routePayloadCapture && structuralId) {
    registerContractRoutePayloadTextCapture(env.ctx.routePayloadCapture, textNode, {
      kind: 'text',
      id: hydrationNodeIdFor(env, structuralId),
      ...(routePayloadKeyFor(env) === undefined
        ? {}
        : { key: routePayloadKeyFor(env) }),
      provenance: Object.freeze({
        component: env.component.name,
        ...(env.component.file.sourcePath
          ? { source: env.component.file.sourcePath }
          : {}),
        span: Object.freeze({ ...span }),
      }),
      readValue: () => tokenPath !== undefined
        ? Object.freeze({ $token: tokenPath })
        : String(readValue() ?? ''),
    });
  }
  onCreate?.(textNode);
  insertNode(parent, textNode, anchor());

  let disposed = false;
  const dispose = (): void => {
    if (disposed) return;
    disposed = true;
    removeChild(parent, textNode);
  };
  getOwner()?.register(dispose);

  const locus: ContractErrorLocus = {
    component: env.component.name,
    sourcePath: env.component.file.sourcePath,
    region: 'text binding',
    span,
  };
  const reactiveOptions = textReactiveOptions(env, structuralIdValue, span);
  const installed = installBinding?.(textNode, locus, reactiveOptions) ?? false;
  const update = (): void => {
    const value = readValue();
    updateTextContent(textNode, value == null ? '' : String(value));
  };
  if (!installed) {
    if (literal) update();
    else ownedEffect(() => runWithContractErrorLocus(locus, update), reactiveOptions);
  }
  return { hostNodes: () => (disposed ? [] : [textNode]), dispose };
}

function textReactiveOptions(
  env: MountEnv,
  structuralIdValue: string | null,
  span: Span,
): ReactiveNodeOptions | undefined {
  if (!isReactiveIntrospectionEnabled()) return undefined;
  const structuralId = structuralIdValue ?? `text:${span.line}:${span.col}`;
  return {
    label: `${env.component.name}.view.${structuralId}.text binding`,
    source: {
      component: env.component.name,
      sourcePath: env.component.file.sourcePath,
      region: 'text binding',
      span,
    },
  };
}

function hydrationNodeIdFor(env: MountEnv, structuralId: string): string {
  return contractHydrationNodeId({
    prefix: env.hydrationPrefix,
    structuralId,
    keyChain: env.hydrationKeyChain,
  });
}

function routePayloadKeyFor(env: MountEnv): string | undefined {
  return env.ctx.routePayloadCapture && env.keyChain.length > 0
    ? env.keyChain.slice(1)
    : undefined;
}

function insertNode(
  parent: HostParent,
  node: TextNode,
  anchor: ElementNode | TextNode | null,
): void {
  if (anchor) insertBefore(parent, node, anchor);
  else appendChild(parent, node);
}
