// @system @ref LLP 0166 §4.7, LLP 0185 S2 — shared view identity seam.

import type { ComponentIR, ViewNodeIR } from '../compiler/ir.js';
import { assignStructuralIds } from '../compiler/identity.js';

const structuralIdCache = new WeakMap<ComponentIR, Map<ViewNodeIR, string>>();

/** Cached per-IR structural-id assignment (the IR is shared per module). */
export function structuralIdsFor(ir: ComponentIR): Map<ViewNodeIR, string> {
  let ids = structuralIdCache.get(ir);
  if (!ids) {
    ids = assignStructuralIds(ir);
    structuralIdCache.set(ir, ids);
  }
  return ids;
}
