// @system @ref ENG-23244 — browser consumption for the shared scrollCommand
// host prop. Native presenters and both DOM hosts accept the same monotonic,
// producer-generation-stamped payload.

interface DomScrollCommandWatermark {
  generation: number;
  seq: number;
}

interface DomScrollCommand {
  producerGeneration: number;
  seq: number;
  interactionEpoch: number;
  x?: number;
  y?: number;
  animated: boolean;
}

const watermarks = new WeakMap<HTMLElement, DomScrollCommandWatermark>();
const UINT32_MAX = 0xffff_ffff;

function uint32(value: unknown): number | null {
  return typeof value === 'number' &&
    Number.isInteger(value) &&
    value >= 0 &&
    value <= UINT32_MAX
    ? value
    : null;
}

function finiteCoordinate(value: unknown): number | undefined | null {
  if (value === undefined) return undefined;
  return typeof value === 'number' && Number.isFinite(value) ? value : null;
}

function decode(raw: unknown): DomScrollCommand | null {
  if (typeof raw !== 'string' || raw.length === 0) return null;
  let payload: unknown;
  try {
    payload = JSON.parse(raw);
  } catch {
    return null;
  }
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return null;
  const record = payload as Record<string, unknown>;
  const producerGeneration = uint32(record.producerGeneration);
  const seq = uint32(record.seq);
  const interactionEpoch = uint32(record.interactionEpoch);
  const x = finiteCoordinate(record.x);
  const y = finiteCoordinate(record.y);
  if (
    producerGeneration === null || producerGeneration === 0 ||
    seq === null || seq === 0 ||
    interactionEpoch === null ||
    x === null || y === null
  ) {
    return null;
  }
  return {
    producerGeneration,
    seq,
    interactionEpoch,
    ...(x === undefined ? {} : { x }),
    ...(y === undefined ? {} : { y }),
    animated: record.animated === true,
  };
}

function clamp(value: number, upper: number): number {
  return Math.min(Math.max(value, 0), Math.max(upper, 0));
}

/** Apply one fresh command and reject malformed, replayed, or stale payloads. */
export function applyDomScrollCommandIfNeeded(
  element: HTMLElement,
  raw: unknown,
): boolean {
  const command = decode(raw);
  if (!command) return false;
  const previous = watermarks.get(element);
  if (
    previous &&
    (
      command.producerGeneration < previous.generation ||
      (command.producerGeneration === previous.generation && command.seq <= previous.seq)
    )
  ) {
    return false;
  }
  watermarks.set(element, {
    generation: command.producerGeneration,
    seq: command.seq,
  });

  const left = clamp(command.x ?? element.scrollLeft, element.scrollWidth - element.clientWidth);
  const top = clamp(command.y ?? element.scrollTop, element.scrollHeight - element.clientHeight);
  if (left === element.scrollLeft && top === element.scrollTop) return true;

  try {
    element.scrollTo({
      left,
      top,
      behavior: command.animated ? 'smooth' : 'auto',
    });
  } catch {
    // Embedded/minimal DOM implementations may expose scroll offsets without
    // the options overload. Direct assignment preserves the command endpoint.
    element.scrollLeft = left;
    element.scrollTop = top;
  }
  return true;
}
