// @system @ref LLP 0099#agent-api — bounded web parity for Motion registry
// ownership/lifetime diagnostics (ENG-25151).

export const WEB_MOTION_ARTIFACT_KINDS = [
  'sharedValues',
  'commands',
  'witnesses',
  'gestureOwners',
] as const;

export type WebMotionArtifactKind = (typeof WEB_MOTION_ARTIFACT_KINDS)[number];

export interface WebMotionArtifactCounts {
  readonly live: number;
  readonly retired: number;
}

export type WebMotionArtifactAccounting = Readonly<
  Record<WebMotionArtifactKind, WebMotionArtifactCounts>
>;

export interface WebMotionRetiredGeneration {
  readonly generation: number;
  readonly artifacts: WebMotionArtifactAccounting;
}

export interface WebMotionRootDiagnostics {
  /** Compatibility projection: SharedValue counts exposed by ENG-25125. */
  readonly live: number;
  readonly retired: number;
  /** Latest incarnation allocated for this root label. */
  readonly generation: number;
  /** Null while the root has no live Motion artifacts. */
  readonly activeGeneration: number | null;
  readonly artifacts: WebMotionArtifactAccounting;
  /** Oldest-first, bounded summaries for fully retired incarnations. */
  readonly retiredGenerations: readonly WebMotionRetiredGeneration[];
}

interface MutableArtifactCounts {
  live: number;
  retired: number;
}

interface MutableGeneration {
  generation: number;
  artifacts: Record<WebMotionArtifactKind, MutableArtifactCounts>;
}

interface MutableRootDiagnostics {
  nextGeneration: number;
  active: MutableGeneration | null;
  totals: Record<WebMotionArtifactKind, MutableArtifactCounts>;
  retiredGenerations: WebMotionRetiredGeneration[];
}

interface WebMotionDiagnosticsRegistry {
  roots: Map<string, MutableRootDiagnostics>;
}

const ROOT_CAPACITY = 64;
const RETIRED_GENERATION_CAPACITY = 16;

function emptyCounts(): Record<WebMotionArtifactKind, MutableArtifactCounts> {
  return {
    sharedValues: { live: 0, retired: 0 },
    commands: { live: 0, retired: 0 },
    witnesses: { live: 0, retired: 0 },
    gestureOwners: { live: 0, retired: 0 },
  };
}

function registry(): WebMotionDiagnosticsRegistry {
  const scope = globalThis as typeof globalThis & {
    __exactWebMotionArtifactDiagnostics?: WebMotionDiagnosticsRegistry;
  };
  return scope.__exactWebMotionArtifactDiagnostics ??= { roots: new Map() };
}

function freezeAccounting(
  counts: Record<WebMotionArtifactKind, MutableArtifactCounts>,
): WebMotionArtifactAccounting {
  return Object.freeze({
    sharedValues: Object.freeze({ ...counts.sharedValues }),
    commands: Object.freeze({ ...counts.commands }),
    witnesses: Object.freeze({ ...counts.witnesses }),
    gestureOwners: Object.freeze({ ...counts.gestureOwners }),
  });
}

function totalLive(generation: MutableGeneration): number {
  return WEB_MOTION_ARTIFACT_KINDS.reduce(
    (total, kind) => total + generation.artifacts[kind].live,
    0,
  );
}

function pruneRoots(state: WebMotionDiagnosticsRegistry): void {
  if (state.roots.size <= ROOT_CAPACITY) return;
  for (const [rootLabel, root] of state.roots) {
    if (state.roots.size <= ROOT_CAPACITY) return;
    if (root.active === null) state.roots.delete(rootLabel);
  }
}

/**
 * Normalize host/root spellings into the same labels used by Contract's
 * `withMotionRootScope`. `document` is not a logical Exact root.
 */
export function webMotionRootLabel(rootId?: string | number | null): string {
  if (rootId === null || rootId === undefined || rootId === '' || rootId === 'document') {
    return 'unattributed';
  }
  const value = String(rootId);
  return value.startsWith('root:') ? value : `root:${value}`;
}

/** Register one live artifact and return its idempotent retirement handle. */
export function registerWebMotionArtifact(
  kind: WebMotionArtifactKind,
  rootId?: string | number | null,
): () => void {
  const state = registry();
  const rootLabel = webMotionRootLabel(rootId);
  let root = state.roots.get(rootLabel);
  if (!root) {
    root = {
      nextGeneration: 1,
      active: null,
      totals: emptyCounts(),
      retiredGenerations: [],
    };
    state.roots.set(rootLabel, root);
  }
  if (!root.active) {
    root.active = {
      generation: root.nextGeneration,
      artifacts: emptyCounts(),
    };
    root.nextGeneration += 1;
  }
  const generation = root.active;
  generation.artifacts[kind].live += 1;
  root.totals[kind].live += 1;

  let live = true;
  return () => {
    if (!live) return;
    live = false;
    generation.artifacts[kind].live = Math.max(0, generation.artifacts[kind].live - 1);
    generation.artifacts[kind].retired += 1;
    root!.totals[kind].live = Math.max(0, root!.totals[kind].live - 1);
    root!.totals[kind].retired += 1;
    if (root!.active === generation && totalLive(generation) === 0) {
      root!.retiredGenerations.push(Object.freeze({
        generation: generation.generation,
        artifacts: freezeAccounting(generation.artifacts),
      }));
      while (root!.retiredGenerations.length > RETIRED_GENERATION_CAPACITY) {
        root!.retiredGenerations.shift();
      }
      root!.active = null;
      pruneRoots(state);
    }
  };
}

export function getWebMotionArtifactDiagnostics(): Readonly<
  Record<string, WebMotionRootDiagnostics>
> {
  const roots: Record<string, WebMotionRootDiagnostics> = {};
  for (const [rootLabel, root] of registry().roots) {
    roots[rootLabel] = Object.freeze({
      live: root.totals.sharedValues.live,
      retired: root.totals.sharedValues.retired,
      generation: root.nextGeneration - 1,
      activeGeneration: root.active?.generation ?? null,
      artifacts: freezeAccounting(root.totals),
      retiredGenerations: Object.freeze([...root.retiredGenerations]),
    });
  }
  return Object.freeze(roots);
}

/** @internal Test isolation for the global HMR-preserved registry. */
export function resetWebMotionArtifactDiagnosticsForTests(): void {
  delete (globalThis as typeof globalThis & {
    __exactWebMotionArtifactDiagnostics?: WebMotionDiagnosticsRegistry;
  }).__exactWebMotionArtifactDiagnostics;
}
