// @system @ref LLP 0101#phase-0 — projection of tests/graphics/scene-model-v1.schema.json.
export const GRAPHICS_SCHEMA_VERSION = 1 as const;
export const GRAPHICS_NODE_TYPES = ['group', 'clip', 'transform', 'rect', 'roundedRect', 'circle', 'ellipse', 'line', 'path', 'image', 'text', 'paragraph', 'batch'] as const;
export const GRAPHICS_OPERATION_TYPES = ['create', 'update', 'delete', 'reorder', 'batchUpload'] as const;
export const GRAPHICS_HANDLER_KINDS = ['press', 'longpress', 'pointerdown', 'pointermove', 'pointerup', 'pointercancel', 'pointerenter', 'pointerleave', 'focus', 'blur', 'keydown'] as const;
export const GRAPHICS_LIMITS = Object.freeze({ maxNodesPerScene: 100_000, maxDepth: 256, maxOperationsPerCommit: 100_000, maxStringBytes: 65_536, maxBatchItems: 1_000_000 });

export type GraphicsNodeType = typeof GRAPHICS_NODE_TYPES[number];
export type GraphicsOperationType = typeof GRAPHICS_OPERATION_TYPES[number];
export type GraphicsHandlerKind = typeof GRAPHICS_HANDLER_KINDS[number];
export type InternalNodeId = `n${number}`;
export type SceneEpoch = string;
export type CommitGeneration = string;

export interface GraphicsSemantics {
  role?: string; label?: string; hint?: string; focusable?: boolean;
  selected?: boolean; checked?: boolean | 'mixed'; disabled?: boolean;
  expanded?: boolean; busy?: boolean; valueText?: string;
  labelledBy?: string; describedBy?: string; headingLevel?: number;
}

export interface GraphicsNodeProps {
  graphicsId?: string; testId?: string; agentId?: string;
  opacity?: number; visible?: boolean; pointerEvents?: 'auto' | 'none';
  hitTest?: 'shape' | 'bounds' | 'none';
  transform?: { a: number; b: number; c: number; d: number; tx: number; ty: number };
  semantics?: GraphicsSemantics;
  semanticLod?: 'summary' | 'visible' | 'full';
  handlers?: Partial<Record<GraphicsHandlerKind, string>>;
  [key: string]: unknown;
}

export interface GraphicsNodeRecord {
  internalNodeId: InternalNodeId; type: GraphicsNodeType;
  parentId: InternalNodeId | null; children: InternalNodeId[];
  graphicsId?: string; testId?: string; agentId?: string;
  props: Record<string, unknown>;
  handlers: Partial<Record<GraphicsHandlerKind, string>>;
  semantics?: GraphicsSemantics; semanticLod?: 'summary' | 'visible' | 'full';
}

export type GraphicsOperation =
  | { type: 'create'; nodeId: InternalNodeId; node: GraphicsNodeRecord }
  | { type: 'update'; nodeId: InternalNodeId; patch: Record<string, unknown> }
  | { type: 'delete'; nodeId: InternalNodeId }
  | { type: 'reorder'; nodeId: InternalNodeId; parentId: InternalNodeId | null; beforeId: InternalNodeId | null }
  | { type: 'batchUpload'; nodeId: InternalNodeId; batchDataGeneration: string; itemCount: number };

export interface GraphicsDiagnostic { code: string; message: string; nodeIds?: InternalNodeId[] }
export interface GraphicsSceneSnapshot { kind: 'snapshot'; schemaVersion: 1; sceneEpoch: SceneEpoch; commitGeneration: CommitGeneration; roots: InternalNodeId[]; nodes: GraphicsNodeRecord[] }
export interface GraphicsCommit { kind: 'commit'; schemaVersion: 1; sceneEpoch: SceneEpoch; commitGeneration: CommitGeneration; mode: 'full' | 'diff'; operations: GraphicsOperation[]; accepted: boolean; diagnostics: GraphicsDiagnostic[]; snapshot?: GraphicsSceneSnapshot }
