// @system @ref LLP 0335 §4.1 — shared pure DOM element lowering.
//
// This module is deliberately free of DOM reads and writes. The live DOM host
// consumes its descriptions today; the direct HTML serializer can consume the
// same descriptions later without growing a second tag/attribute/style truth.

import { colorToRgba, parseColor } from '@exact/core/style/color';
import { isGradientValue, normalizeGradientCssValue } from '@exact/core/style/gradient';

import {
  isSafeHostDomAttr,
  lowerHostAttrs,
  type DomTagName,
  type HostSemanticAttrs,
} from './attrs.js';
import type { ElementNode } from './nodes/node.js';
import { NodeKind } from './nodes/node.js';
import { cssTransform, cssTransition } from './style/css-motion.js';
import { lowerBackdropMaterialWebStyle } from './style/backdrop-material-web.js';
import { lowerLiquidGlassWebStyle } from './style/liquid-glass-web.js';
import type { ImageColorScheme } from './types.js';
import { lowerImageDynamicRangeCss, type CssSupports } from './image-dynamic-range.js';
import {
  IMAGE_COLOR_MATRIX_ATTR,
  lowerImageColorMatrixFilter,
  type ImageColorMatrixFilter,
} from './image-color-matrix-filter.js';
import { isSystemSymbolImageSource } from './image-system-symbol.js';
import {
  GRAPHICS_GESTURE_CLAIM_ATTR,
  touchActionForGraphicsGestureClaim,
} from './graphics/gesture-claim.js';
import { describeLottieDomProps } from './lottie/backend-scope.js';
import { describeRiveDomProps } from './rive/backend-scope.js';
import {
  normalizeImageFetchPriority,
  resolveImageLoadingForWeb,
} from './image-loading-web.js';

export type DomElementAttributeValue = string | true;
export type DomElementAttribute = readonly [name: string, value: DomElementAttributeValue];

export interface DomElementProperties {
  disabled?: boolean;
  checked?: boolean;
  readOnly?: boolean;
  value?: string;
}

export interface DomInlineSvgDescription {
  markup: string;
  objectFit?: unknown;
  objectPosition?: unknown;
  tintColor?: unknown;
  decorative: boolean;
  label?: string;
}

export interface DomElementDescription {
  tag: DomTagName;
  /** Ordered to preserve the DOM writer's observable attribute order. */
  attributes: readonly DomElementAttribute[];
  /** CSSOM property names and values, in application order. */
  styles: Readonly<Record<string, string>>;
  /** Live DOM properties whose state is not fully represented by attributes. */
  properties: Readonly<DomElementProperties>;
  /** DOM parsing/sanitization remains a narrow writer-owned operation. */
  inlineSvg?: Readonly<DomInlineSvgDescription>;
  /**
   * LLP 0364: the `<filter>` def this element's `filter` style references. The
   * writer materializes it — a live host into a document-level `<defs>`, a
   * static serializer not at all (see `colorMatrixFilters`).
   */
  colorMatrixFilter?: Readonly<ImageColorMatrixFilter>;
}

/**
 * Project live DOM properties into the attributes emitted by static HTML.
 * Keeping this next to the pure description prevents the server writer and
 * hydration adoption checks from drifting on reflected control state.
 */
export function materializeDomElementAttributes(
  description: DomElementDescription,
): readonly DomElementAttribute[] {
  const attributes = new Map<string, DomElementAttribute>();
  const set = (name: string, value: DomElementAttributeValue): void => {
    const key = name.toLowerCase();
    const existing = attributes.get(key);
    attributes.set(key, [existing?.[0] ?? name, value]);
  };
  const setBoolean = (name: string, value: boolean | undefined): void => {
    if (value === true) set(name, true);
    else if (value === false) attributes.delete(name);
  };

  for (const [name, value] of description.attributes) set(name, value);
  setBoolean('disabled', description.properties.disabled);
  setBoolean('checked', description.properties.checked);
  setBoolean('readonly', description.properties.readOnly);
  if (description.properties.value !== undefined) {
    set('value', description.properties.value);
  }
  return [...attributes.values()];
}

export interface DescribeDomElementOptions {
  imageColorScheme: ImageColorScheme;
  supportsDynamicRangeCss?: CssSupports;
  /**
   * LLP 0364 color-matrix strategy. `document-defs` (the default) emits the
   * `filter: url(#id)` style for a live host that can inject the `<filter>`
   * into the document. `defer` emits only the intent attribute: a static
   * serializer has nowhere to put the def inside a void `<img>`, and a
   * `filter` referencing a missing def makes browsers drop the element
   * entirely, so the prerendered frame paints the unfiltered photo and the
   * hydrating host applies the filter.
   */
  colorMatrixFilters?: 'document-defs' | 'defer';
}

/**
 * Inline HTML serializes all styles into one declaration list, while the live
 * DOM writer assigns one CSSOM property at a time. A raw declaration boundary
 * in a value is harmless to CSSOM but could create a sibling property in the
 * serialized style attribute. Drop that value in this shared pure lowering so
 * both writers have the same fail-closed semantics.
 */
export function isSafeInlineStyleValue(value: string): boolean {
  const closing: string[] = [];
  let quote: '"' | "'" | null = null;
  let inComment = false;
  for (let index = 0; index < value.length; index += 1) {
    const char = value[index]!;
    const next = value[index + 1];
    if (char === '\0' || char === '\r' || char === '\n' || char === '\f') return false;
    if (inComment) {
      if (char === '*' && next === '/') {
        inComment = false;
        index += 1;
      }
      continue;
    }
    if (quote) {
      if (char === '\\') {
        index += 1;
      } else if (char === quote) {
        quote = null;
      }
      continue;
    }
    if (char === '/' && next === '*') {
      inComment = true;
      index += 1;
      continue;
    }
    if (char === '\\') {
      index += 1;
      continue;
    }
    if (char === '"' || char === "'") {
      quote = char;
      continue;
    }
    if (char === '(') closing.push(')');
    else if (char === '[') closing.push(']');
    else if (char === '{') closing.push('}');
    else if (char === ')' || char === ']' || char === '}') {
      if (closing.pop() !== char) return false;
    } else if (char === ';' && closing.length === 0) {
      return false;
    }
  }
  return quote === null && !inComment && closing.length === 0;
}

const UNITLESS = new Set([
  'flex',
  'flexGrow',
  'flexShrink',
  'opacity',
  'zIndex',
  'fontWeight',
  'aspectRatio',
  'order',
]);

const RN_CONTAINER_TAGS = new Set(['View', 'ScrollView', 'Pressable', 'List']);
const WEB_CONTAINER_TAGS = new Set([
  'a',
  'div',
  'section',
  'figure',
  'main',
  'article',
  'blockquote',
  'pre',
  'hr',
  'nav',
  'aside',
  'header',
  'footer',
  'form',
  'label',
]);
const TEXT_TAGS = new Set([
  'Text',
  'text',
  'span',
  'p',
  'code',
  'figcaption',
  'cite',
  'h1',
  'h2',
  'h3',
  'h4',
  'h5',
  'h6',
]);
const UA_MARGIN_RESET_TAGS = new Set([
  'blockquote',
  'figure',
  'pre',
  'hr',
  'h1',
  'h2',
  'h3',
  'h4',
  'h5',
  'h6',
]);
const NATIVELY_FOCUSABLE_TAGS = new Set(['button', 'input', 'textarea', 'select', 'a']);

function cssValue(name: string, value: unknown): string {
  if (typeof value === 'number') {
    return UNITLESS.has(name) ? String(value) : `${value}px`;
  }
  if (Array.isArray(value)) {
    return value.join(', ');
  }
  return String(value);
}

/** Expands RN-only shorthand/composite props into CSS-compatible entries. */
export function lowerDomStyle(
  style: Record<string, unknown> | undefined,
): Record<string, string> {
  const out: Record<string, string> = {};
  if (!style) {
    return out;
  }

  let shadow: {
    x?: number;
    y?: number;
    blur?: number;
    color?: string;
    opacity?: number;
  } | null = null;

  for (const [name, value] of Object.entries(style)) {
    if (value === undefined || value === null) {
      continue;
    }
    switch (name) {
      case 'transition': {
        const converted = cssTransition(value);
        if (converted) {
          out.transition = converted;
        }
        break;
      }
      case 'transform': {
        const converted = cssTransform(value);
        if (converted) {
          out.transform = converted;
        }
        break;
      }
      case 'paddingHorizontal':
        out.paddingLeft = cssValue('paddingLeft', value);
        out.paddingRight = cssValue('paddingRight', value);
        break;
      case 'paddingVertical':
        out.paddingTop = cssValue('paddingTop', value);
        out.paddingBottom = cssValue('paddingBottom', value);
        break;
      case 'marginHorizontal':
        out.marginLeft = cssValue('marginLeft', value);
        out.marginRight = cssValue('marginRight', value);
        break;
      case 'marginVertical':
        out.marginTop = cssValue('marginTop', value);
        out.marginBottom = cssValue('marginBottom', value);
        break;
      case 'shadowColor':
        shadow = { ...(shadow ?? {}), color: String(value) };
        break;
      case 'shadowOffset': {
        const offset = value as { width?: number; height?: number };
        shadow = {
          ...(shadow ?? {}),
          x: offset?.width ?? 0,
          y: offset?.height ?? 0,
        };
        break;
      }
      case 'shadowRadius':
        shadow = { ...(shadow ?? {}), blur: Number(value) };
        break;
      case 'shadowOpacity':
        shadow = { ...(shadow ?? {}), opacity: Number(value) };
        break;
      case 'backdropBlur':
      case 'backdropMaterial':
        // Lowered as one semantic unit after iteration.
        break;
      case 'textAlignVertical':
      case 'numberOfLines':
      case 'fontVariant':
        break;
      case 'backgroundColor': {
        if (isGradientValue(value)) {
          const css = normalizeGradientCssValue(value);
          if (css) {
            out.backgroundImage = css;
          }
        } else {
          out[name] = cssValue(name, value);
        }
        break;
      }
      case 'backgroundImage': {
        const raw = String(value).trim();
        if (isGradientValue(raw)) {
          const css = normalizeGradientCssValue(raw);
          if (css) {
            out.backgroundImage = css;
          }
        } else {
          out.backgroundImage = raw;
        }
        break;
      }
      case 'borderWidth':
        out.borderWidth = cssValue(name, value);
        out.borderStyle = 'solid';
        break;
      case 'borderBottomWidth':
        out.borderBottomWidth = cssValue(name, value);
        out.borderBottomStyle = 'solid';
        break;
      case 'borderLeftWidth':
        out.borderLeftWidth = cssValue(name, value);
        out.borderLeftStyle = 'solid';
        break;
      default:
        out[name] = cssValue(name, value);
        break;
    }
  }

  if (!out.boxShadow && shadow && (shadow.blur ?? 0) > 0 && shadow.color) {
    const opacity = Math.max(0, Math.min(shadow.opacity ?? 1, 1));
    const parsed = parseColor(shadow.color);
    const cssColor = parsed
      ? colorToRgba({ ...parsed, a: Math.round(parsed.a * opacity) })
      : shadow.color;
    out.boxShadow = `${shadow.x ?? 0}px ${shadow.y ?? 0}px ${shadow.blur}px ${cssColor}`;
  }

  const glass = lowerLiquidGlassWebStyle(style);
  if (glass) {
    // Liquid Glass wins over backdropMaterial/backdropBlur (LLP 0412 §1)
    // and replaces the authored fill, matching the native hosts, which
    // clear the node's background so glass samples the true backdrop.
    out.backdropFilter = glass.backdropFilter;
    out.WebkitBackdropFilter = glass.WebkitBackdropFilter;
    out.backgroundColor = glass.backgroundColor;
    return out;
  }

  const backdrop = lowerBackdropMaterialWebStyle(style);
  if (backdrop) {
    out.backdropFilter = backdrop.backdropFilter;
    out.WebkitBackdropFilter = backdrop.WebkitBackdropFilter;
    if (out.backgroundColor === undefined && backdrop.backgroundColor !== undefined) {
      out.backgroundColor = backdrop.backgroundColor;
    }
  }

  return out;
}

function readPositiveLineCount(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value) && value > 0
    ? Math.trunc(value)
    : undefined;
}

/**
 * Lottie sources feed a fetch inside the dotlottie backend, never
 * navigation or script execution, so beyond the general URL-attr gate they
 * also accept same-origin `blob:` object URLs (the /lottie-lab upload
 * path) and `data:` payloads (LLP 0394 §9).
 */
function isSafeLottieSourceUrl(value: string): boolean {
  const trimmed = value.trim();
  if (trimmed.startsWith('blob:') || trimmed.startsWith('data:')) {
    return true;
  }
  return isSafeHostDomAttr('src', trimmed);
}

/**
 * Rive bytes are fetched by the Exact backend rather than assigned to a
 * browser navigation attribute. The versioned envelope is data, while plain
 * sources use the same URL gate and local blob/data allowance as Lottie.
 */
function isSafeRiveSourceUrl(value: string): boolean {
  const trimmed = value.trim();
  if (trimmed.startsWith('exact:rive:')) return true;
  if (trimmed.startsWith('blob:') || trimmed.startsWith('data:')) return true;
  return isSafeHostDomAttr('src', trimmed);
}

function defaultDomTagFor(node: ElementNode): DomTagName {
  const tag = node.originalTag;
  const props = (node.originalProps ?? {}) as Record<string, unknown>;
  if (tag === 'Pressable' || tag === 'button' || tag === 'a') {
    return 'button';
  }
  if (tag === 'TextInput' || tag === 'input' || tag === 'textarea') {
    return props.multiline ? 'textarea' : 'input';
  }
  if (tag === 'Toggle' || tag === 'Switch' || tag === 'toggle') {
    return 'input';
  }
  if (tag === 'Image' || tag === 'img') {
    return typeof props.svgSource === 'string' && props.svgSource.trim().length > 0
      ? 'span'
      : 'img';
  }
  if (TEXT_TAGS.has(tag)) {
    return tag === 'Text' || tag === 'text' || tag === 'p'
      ? 'span'
      : (tag as DomTagName);
  }
  if (WEB_CONTAINER_TAGS.has(tag)) {
    return tag as DomTagName;
  }
  return 'div';
}

function semanticAttrsFromProps(
  props: Record<string, unknown>,
): HostSemanticAttrs | undefined {
  const tag = props.__exactSemanticTag;
  return typeof tag === 'string' && tag.length > 0 ? { tag } : undefined;
}

function isInlineTextFlowChild(node: ElementNode): boolean {
  const parent = node.parent;
  return parent?.kind === NodeKind.Element &&
    TEXT_TAGS.has((parent as ElementNode).originalTag);
}

function pushAttribute(
  attributes: DomElementAttribute[],
  name: string,
  value: unknown,
): void {
  if (name === 'style' || name === 'children' || name === 'ref' || name === 'key') {
    return;
  }
  if (value === undefined || value === null || typeof value === 'function' || typeof value === 'object') {
    return;
  }
  if (!isSafeHostDomAttr(name, value)) {
    return;
  }

  const normalizedName = name === 'className'
    ? 'class'
    : name === 'htmlFor'
      ? 'for'
      : name === 'tabIndex'
        ? 'tabindex'
        : name;
  if (typeof value === 'boolean') {
    if (name.startsWith('aria-')) {
      attributes.push([normalizedName, String(value)]);
    } else if (value) {
      attributes.push([normalizedName, true]);
    }
    return;
  }
  attributes.push([normalizedName, String(value)]);
}

function lastAttributeValue(
  attributes: readonly DomElementAttribute[],
  name: string,
): DomElementAttributeValue | undefined {
  for (let index = attributes.length - 1; index >= 0; index -= 1) {
    if (attributes[index]?.[0] === name) {
      return attributes[index]?.[1];
    }
  }
  return undefined;
}

function stringProp(value: unknown): string | undefined {
  return typeof value === 'string' && value.length > 0 ? value : undefined;
}

function resolvedThemeImageSrc(
  props: Record<string, unknown>,
  scheme: ImageColorScheme,
): string | undefined {
  const src = stringProp(props.src);
  const lightSrc = stringProp(props.lightSrc);
  const darkSrc = stringProp(props.darkSrc);
  if (!lightSrc && !darkSrc) {
    return src;
  }
  return scheme === 'dark'
    ? darkSrc ?? src ?? lightSrc
    : lightSrc ?? src ?? darkSrc;
}

export function describeDomElement(
  node: ElementNode,
  options: DescribeDomElementOptions,
): DomElementDescription {
  const props = (node.originalProps ?? {}) as Record<string, unknown>;
  const lowered = lowerHostAttrs(
    { tag: node.originalTag, props },
    semanticAttrsFromProps(props),
    { defaultTag: defaultDomTagFor(node) },
  );
  const tag = lowered.tag;
  const styles: Record<string, string> = { boxSizing: 'border-box' };
  const attributes: DomElementAttribute[] = [];

  if (RN_CONTAINER_TAGS.has(node.originalTag)) {
    Object.assign(styles, {
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'stretch',
      position: 'relative',
      minWidth: '0',
      minHeight: '0',
      flexShrink: '0',
    });
  }
  if (node.originalTag === 'ScrollView') {
    Object.assign(styles, {
      overflowY: 'auto',
      flex: '1 1 0%',
      width: '100%',
      minHeight: '0',
    });
  }
  if (WEB_CONTAINER_TAGS.has(node.originalTag)) {
    Object.assign(styles, {
      display: 'flex',
      flexDirection: 'row',
      position: 'relative',
    });
  }
  if (UA_MARGIN_RESET_TAGS.has(tag)) {
    styles.margin = '0';
  }
  if (tag === 'pre') {
    styles.whiteSpace = 'pre-wrap';
    styles.font = 'inherit';
  }
  if (tag === 'hr') {
    styles.border = 'none';
    styles.display = 'block';
  }
  if (TEXT_TAGS.has(node.originalTag)) {
    styles.whiteSpace = 'pre-wrap';
  }
  if (tag === 'button') {
    pushAttribute(attributes, 'type', 'button');
    Object.assign(styles, {
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'stretch',
      position: 'relative',
      background: 'transparent',
      // Longhands avoid HappyDOM serializing a later authored borderWidth as
      // the invalid shorthand `border: 0px solid none` in static output.
      borderWidth: '0px',
      borderStyle: 'solid',
      margin: '0',
      padding: '0',
      font: 'inherit',
      color: 'inherit',
      textAlign: 'inherit',
      cursor: 'pointer',
    });
  }
  if (tag === 'a') {
    Object.assign(styles, {
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'stretch',
      position: 'relative',
      color: 'inherit',
      textDecoration: 'none',
      cursor: 'pointer',
    });
  }
  if (node.originalTag === 'Toggle' || node.originalTag === 'Switch' || node.originalTag === 'toggle') {
    pushAttribute(attributes, 'type', 'checkbox');
  }
  if ((tag === 'input' && lastAttributeValue(attributes, 'type') !== 'checkbox') || tag === 'textarea') {
    styles.font = 'inherit';
    styles.color = 'inherit';
  }
  if ((tag === 'a' || tag === 'button') && isInlineTextFlowChild(node)) {
    styles.display = 'inline';
    styles.flexDirection = '';
    styles.alignItems = '';
    styles.minWidth = '';
    styles.minHeight = '';
    styles.flexShrink = '';
  }

  Object.assign(
    styles,
    lowerDomStyle(props.style as Record<string, unknown> | undefined),
  );

  // RFC 0101 SG2 / LLP 0353 §2 — a graphics surface's gesture claim owns the
  // element's `touch-action`. It is applied AFTER the authored style because
  // the claim is a framework declaration, not a decoration: an app cannot own
  // this property anyway (applyDescription rewrites the whole style attribute
  // on the next commit), so the framework has to be the one writing it.
  const graphicsTouchAction = touchActionForGraphicsGestureClaim(
    props[GRAPHICS_GESTURE_CLAIM_ATTR],
  );
  if (graphicsTouchAction !== undefined) {
    styles.touchAction = graphicsTouchAction;
  }

  // Liquid Glass rides as top-level host props (the Contract `glass*` attr
  // lowering), not inside `style`; the style-carried case is handled inside
  // lowerDomStyle. Applied after the authored style so the glass wash
  // replaces the authored fill, matching the native hosts, which clear the
  // node's background so glass samples the true backdrop.
  const liquidGlass = lowerLiquidGlassWebStyle(props);
  if (liquidGlass) {
    styles.backdropFilter = liquidGlass.backdropFilter;
    styles['-webkit-backdrop-filter'] = liquidGlass.WebkitBackdropFilter;
    styles.backgroundColor = liquidGlass.backgroundColor;
  }

  // Modal/sheet portal overlays: the web host does not relocate portals to a
  // full-screen overlay root (as native does via portalPresentation), so an
  // `absolute; inset:0` scrim is trapped inside its inline (position:relative)
  // parent and only covers a band. Pin these presentations to the viewport
  // with `position: fixed` so the scrim and centered content fill the screen —
  // matching the native presentation. Anchored (non-modal) overlays set an
  // `anchor`/placement instead of a modal/sheet presentation and are untouched.
  //
  // Known limitation: `position: fixed` resolves against the viewport only
  // while no ancestor establishes a containing block. A transformed ancestor
  // — or one with `will-change: transform`, `filter`, `perspective`, or
  // `contain: paint/layout` — captures the fixed descendant, and the "pinned"
  // scrim then only covers that ancestor. Pager cells are the concrete
  // in-repo case: the pager track animates `transform`, so a modal/sheet
  // opened from inside a pager cell pins to the cell, not the screen. This
  // pure lowering cannot see ancestors; escaping a transformed subtree needs
  // real portal relocation to a root outside it (as native does).
  const portalPresentation = props.__exactPortalPresentation ?? props.portalPresentation;
  if (portalPresentation === 'modal' || portalPresentation === 'sheet') {
    styles.position = 'fixed';
    styles.left = '0';
    styles.top = '0';
    styles.right = '0';
    styles.bottom = '0';
  }

  if (TEXT_TAGS.has(node.originalTag)) {
    const styleObject = typeof props.style === 'object' && props.style !== null
      ? (props.style as Record<string, unknown>)
      : undefined;
    const numberOfLines = readPositiveLineCount(props.numberOfLines) ??
      readPositiveLineCount(styleObject?.numberOfLines) ??
      readPositiveLineCount(node.style.numberOfLines);
    if (numberOfLines === 1) {
      Object.assign(styles, {
        display: 'block',
        overflow: 'hidden',
        textOverflow: 'ellipsis',
        whiteSpace: 'nowrap',
      });
    } else if (numberOfLines != null) {
      Object.assign(styles, {
        display: '-webkit-box',
        '-webkit-line-clamp': String(numberOfLines),
        '-webkit-box-orient': 'vertical',
        overflow: 'hidden',
      });
    }
  }

  for (const [name, value] of Object.entries(lowered.attrs)) {
    pushAttribute(attributes, name, value);
  }

  if (props.focusScope === 'trapped') {
    pushAttribute(attributes, 'data-exact-focus-scope', 'trapped');
    if (props.__exactFocusRestore === true) {
      pushAttribute(attributes, 'data-exact-focus-restore', 'true');
    }
    if (lastAttributeValue(attributes, 'tabindex') === undefined) {
      pushAttribute(attributes, 'tabIndex', -1);
    }
  }

  if (
    typeof props.onKeyDown === 'function' &&
    !NATIVELY_FOCUSABLE_TAGS.has(tag) &&
    lastAttributeValue(attributes, 'tabindex') === undefined
  ) {
    pushAttribute(attributes, 'tabIndex', -1);
  }

  const properties: DomElementProperties = {};
  if (tag === 'button' || tag === 'input' || tag === 'textarea') {
    properties.disabled = props.disabled === true;
  }

  const isCheckbox = tag === 'input' && lastAttributeValue(attributes, 'type') === 'checkbox';
  if (isCheckbox) {
    properties.checked = props.value === true || props.checked === true;
  } else if (tag === 'input' || tag === 'textarea') {
    if (props.placeholder != null) {
      pushAttribute(attributes, 'placeholder', String(props.placeholder));
    }
    if (props.secureTextEntry === true) {
      pushAttribute(attributes, 'type', 'password');
    }
    properties.readOnly = props.editable === false;
    if (props.value !== undefined) {
      properties.value = String(props.value ?? '');
    }
  }

  let colorMatrixFilter: ImageColorMatrixFilter | undefined;
  if (tag === 'img') {
    const dynamicRangeCss = lowerImageDynamicRangeCss(
      node.props.imageDynamicRange,
      options.supportsDynamicRangeCss,
    );
    if (dynamicRangeCss) {
      styles[dynamicRangeCss.property] = dynamicRangeCss.value;
    }
    // LLP 0364: the canonical prop, not the authored one — malformed matrices
    // are already rejected at the canonical boundary, so the DOM and the
    // native wire always filter with the same 20 numbers.
    const colorMatrix = lowerImageColorMatrixFilter(node.props.imageColorMatrix);
    if (colorMatrix) {
      pushAttribute(attributes, IMAGE_COLOR_MATRIX_ATTR, colorMatrix.canonicalMatrix);
      if (options.colorMatrixFilters !== 'defer') {
        styles.filter = colorMatrix.cssValue;
        colorMatrixFilter = colorMatrix;
      }
    }
    const authoredLightSrc = stringProp(props.lightSrc);
    const authoredDarkSrc = stringProp(props.darkSrc);
    const lightSrc = isSystemSymbolImageSource(authoredLightSrc)
      ? undefined
      : authoredLightSrc;
    const darkSrc = isSystemSymbolImageSource(authoredDarkSrc)
      ? undefined
      : authoredDarkSrc;
    const rawTreatment = stringProp(props.themeTreatment);
    const treatment = rawTreatment === 'none' ? undefined : rawTreatment;
    if (lightSrc) pushAttribute(attributes, 'data-light-src', lightSrc);
    if (darkSrc) pushAttribute(attributes, 'data-dark-src', darkSrc);
    if (treatment) pushAttribute(attributes, 'data-exact-theme-treatment', treatment);
    if (lightSrc || darkSrc || treatment) {
      pushAttribute(attributes, 'data-exact-theme-image', 'color-scheme');
    }

    const resolvedSrc = resolvedThemeImageSrc(props, options.imageColorScheme);
    if (
      resolvedSrc != null &&
      !isSystemSymbolImageSource(resolvedSrc) &&
      isSafeHostDomAttr('src', resolvedSrc)
    ) {
      pushAttribute(attributes, 'src', resolvedSrc);
    } else if (
      props.src != null &&
      !isSystemSymbolImageSource(props.src) &&
      isSafeHostDomAttr('src', props.src)
    ) {
      pushAttribute(attributes, 'src', String(props.src));
    }
    if (props.decorative === true) {
      pushAttribute(attributes, 'alt', '');
    } else if (props.alt != null) {
      pushAttribute(attributes, 'alt', String(props.alt));
    } else if (props.accessibilityLabel != null) {
      pushAttribute(attributes, 'alt', String(props.accessibilityLabel));
    }

    const loading = resolveImageLoadingForWeb(
      props.loading === 'auto' || props.loading === 'eager' || props.loading === 'lazy'
        ? props.loading
        : undefined,
      false,
    );
    if (loading) {
      pushAttribute(attributes, 'loading', loading);
      pushAttribute(attributes, 'decoding', 'async');
    }
    const fetchPriority = normalizeImageFetchPriority(
      props.priority === 'auto' || props.priority === 'high' ||
      props.priority === 'normal' || props.priority === 'low'
        ? props.priority
        : undefined,
    );
    if (fetchPriority) pushAttribute(attributes, 'fetchpriority', fetchPriority);
  }

  if (node.originalTag === 'lottie') {
    // LLP 0394 §9: the web host paints Lottie through the dotlottie-web
    // (ThorVG WASM) backend adopted off these attrs; the same derivation
    // feeds the native lottieSource/lottieConfig props (props/normalize.ts).
    pushAttribute(attributes, 'data-exact-lottie-backend', 'dotlottie');
    const lottie = describeLottieDomProps(props);
    const lottieSrc = lottie?.source;
    if (lottieSrc != null && isSafeLottieSourceUrl(lottieSrc)) {
      pushAttribute(attributes, 'data-exact-lottie-src', lottieSrc);
    }
    const lottieConfig = lottie?.config;
    if (lottieConfig) {
      pushAttribute(attributes, 'data-exact-lottie-config', lottieConfig);
    }
    const lottiePlayerId = lottie?.playerId;
    if (lottiePlayerId) {
      pushAttribute(attributes, 'data-exact-lottie-player', lottiePlayerId);
    }
  }

  if (node.originalTag === 'rive') {
    // LLP 0395 §4: attrs are the adoption boundary for the lazy WebGL2
    // backend. Live controller objects never enter the DOM or protocol.
    pushAttribute(attributes, 'data-exact-rive-backend', 'webgl2');
    const rive = describeRiveDomProps(props);
    const riveSrc = rive?.source;
    if (riveSrc != null && isSafeRiveSourceUrl(riveSrc)) {
      pushAttribute(attributes, 'data-exact-rive-src', riveSrc);
    }
    const riveConfig = rive?.config;
    if (riveConfig) {
      pushAttribute(attributes, 'data-exact-rive-config', riveConfig);
    }
    const riveBindings = rive?.bindings;
    if (riveBindings) {
      pushAttribute(attributes, 'data-exact-rive-bindings', riveBindings);
    }
    const riveControllerId = rive?.controllerId;
    if (riveControllerId) {
      pushAttribute(attributes, 'data-exact-rive-controller', riveControllerId);
    }
  }

  const svgSource = tag === 'span' && typeof props.svgSource === 'string'
    ? props.svgSource
    : undefined;
  const inlineSvg = svgSource !== undefined
    ? {
        markup: svgSource,
        objectFit: props.objectFit,
        objectPosition: props.objectPosition,
        tintColor: props.tintColor,
        decorative: props.decorative === true,
        label: stringProp(props.alt) ?? stringProp(props.accessibilityLabel),
      }
    : undefined;

  for (const [name, value] of Object.entries(styles)) {
    if (!isSafeInlineStyleValue(value)) {
      delete styles[name];
    }
  }

  return {
    tag,
    attributes,
    styles,
    properties,
    ...(inlineSvg ? { inlineSvg } : {}),
    ...(colorMatrixFilter ? { colorMatrixFilter } : {}),
  };
}
