// @system @ref LLP 0336 / LLP 0373 phase 3c — optional key-interaction
// runtime seam. Generated production modules inject the implementation only
// when their component IR declares key bindings; editable mount preserves the
// historical default.

import type { ComponentInstance } from './instance.js';

export interface ContractInteractionsRuntime {
  registerComponent(instance: ComponentInstance): void;
}

let editableDefault: ContractInteractionsRuntime | null = null;

export function setEditableContractInteractionsRuntime(
  runtime: ContractInteractionsRuntime | null,
): void {
  editableDefault = runtime;
}

export function editableContractInteractionsRuntime(): ContractInteractionsRuntime | null {
  return editableDefault;
}
