// @system @ref LLP 0007#motion-amendment — framework-neutral, per-root
// component-local dismiss-layer authority. Gesture arbitration remains the
// one LLP 0099/0336 Motion arena; React and Contract project into this schema.

import type { MotionCommandIdentity } from './motion-command.js';

export interface DismissLayerRegistration {
  readonly id: string;
  readonly rootId: string;
  readonly parentId?: string;
  /** Host node identity when this layer belongs to an Exact renderer tree. */
  readonly viewId?: number;
  readonly modal: boolean;
  readonly portalOrder: number;
  readonly visualOrder: number;
  /** Stable for the lifetime of one mounted keyed layer. */
  readonly mountSequence?: number;
  readonly command?: MotionCommandIdentity | undefined;
  readonly triggers?: readonly ('escape' | 'outside-press' | 'swipe-down')[];
}

export interface MountedDismissLayer extends DismissLayerRegistration {
  readonly generation: number;
  readonly mountSequence: number;
}

export interface DismissLayerReceipt {
  readonly sequence: number;
  readonly rootId: string;
  readonly layerId: string;
  readonly generation: number;
  readonly kind: 'topmost-claim' | 'structural-cancel' | 'dismiss';
  readonly decision: string;
  readonly gestureId?: string;
  readonly command?: MotionCommandIdentity;
  readonly timestampMs: number;
}

export interface DismissLayerHandle {
  readonly id: string;
  readonly generation: number;
  isTopmost(): boolean;
  claim(gestureId: string): boolean;
  release(gestureId: string, decision: 'commit' | 'cancel'): void;
  update(next: Partial<Omit<DismissLayerRegistration, 'id' | 'rootId' | 'mountSequence'>>): void;
  dispose(): void;
}

interface DismissLayerState {
  layers: Map<string, MountedDismissLayer>;
  activeClaims: Map<string, { layerId: string; generation: number; gestureId: string }>;
  receipts: DismissLayerReceipt[];
  nextGeneration: number;
  nextMount: number;
  nextReceipt: number;
}

export interface DismissLayerAgentProjection {
  readonly rootId: number;
  readonly layers: ReadonlyArray<{
    readonly rootId: number;
    readonly layerId: string;
    readonly parentId?: string;
    readonly viewId?: number;
    readonly generation: number;
    readonly modal: boolean;
    readonly portalOrder: number;
    readonly visualOrder: number;
    readonly mountSequence: number;
    readonly topmost: boolean;
    readonly triggers: readonly ('escape' | 'outside-press' | 'swipe-down')[];
    readonly activeClaimGestureId?: string;
    readonly command?: MotionCommandIdentity;
  }>;
  readonly receipts: ReadonlyArray<{
    readonly rootId: number;
    readonly sequence: number;
    readonly layerId: string;
    readonly generation: number;
    readonly kind: DismissLayerReceipt['kind'];
    readonly decision: string;
    readonly gestureId?: string;
    readonly command?: MotionCommandIdentity;
    readonly timestampMs: number;
  }>;
  readonly updatedAt?: number;
}

type DismissLayerAgentProjectionPublisher = (
  projection: DismissLayerAgentProjection,
) => void;

let agentProjectionPublisher: DismissLayerAgentProjectionPublisher | null = null;

/** Install the optional agent/inspection mirror without coupling production behavior to it. */
export function setDismissLayerAgentProjectionPublisher(
  publisher: DismissLayerAgentProjectionPublisher | null,
): void {
  agentProjectionPublisher = publisher;
}

const RECEIPT_CAPACITY = 100;

function state(): DismissLayerState {
  const scope = globalThis as typeof globalThis & { __exactDismissLayerState?: DismissLayerState };
  return scope.__exactDismissLayerState ??= {
    layers: new Map(),
    activeClaims: new Map(),
    receipts: [],
    nextGeneration: 1,
    nextMount: 1,
    nextReceipt: 1,
  };
}

function key(rootId: string, id: string): string {
  return `${rootId}\0${id}`;
}

/** Reserve the sibling-order identity shared by all framework adapters. */
export function reserveDismissLayerMountSequence(): number {
  return state().nextMount++;
}

function isDescendant(
  candidate: MountedDismissLayer,
  ancestor: MountedDismissLayer,
  layers: ReadonlyMap<string, MountedDismissLayer>,
): boolean {
  const visited = new Set<string>();
  let parentId = candidate.parentId;
  while (parentId && !visited.has(parentId)) {
    if (parentId === ancestor.id) return true;
    visited.add(parentId);
    parentId = layers.get(key(candidate.rootId, parentId))?.parentId;
  }
  return false;
}

function compareLayers(
  left: MountedDismissLayer,
  right: MountedDismissLayer,
  layers: ReadonlyMap<string, MountedDismissLayer>,
): number {
  if (isDescendant(left, right, layers)) return 1;
  if (isDescendant(right, left, layers)) return -1;
  if (left.modal !== right.modal) return left.modal ? 1 : -1;
  if (left.portalOrder !== right.portalOrder) return left.portalOrder - right.portalOrder;
  if (left.visualOrder !== right.visualOrder) return left.visualOrder - right.visualOrder;
  return left.mountSequence - right.mountSequence;
}

function topmost(rootId: string): MountedDismissLayer | null {
  const registry = state();
  const candidates = [...registry.layers.values()].filter((layer) => layer.rootId === rootId);
  if (candidates.length === 0) return null;
  return candidates.sort((left, right) => compareLayers(left, right, registry.layers)).at(-1) ?? null;
}

function receipt(
  layer: MountedDismissLayer,
  kind: DismissLayerReceipt['kind'],
  decision: string,
  gestureId?: string,
): void {
  const registry = state();
  registry.receipts.push(Object.freeze({
    sequence: registry.nextReceipt++,
    rootId: layer.rootId,
    layerId: layer.id,
    generation: layer.generation,
    kind,
    decision,
    ...(gestureId ? { gestureId } : {}),
    ...(layer.command ? { command: layer.command } : {}),
    timestampMs: Date.now(),
  }));
  while (registry.receipts.length > RECEIPT_CAPACITY) registry.receipts.shift();
}

function agentRootId(rootId: string): number | null {
  // Plain React DOM has one document-scoped fallback stack and the Acto DOM
  // fallback exposes it as logical root 0.
  if (rootId === 'document') return 0;
  if (!/^(0|[1-9][0-9]*)$/.test(rootId)) return null;
  const value = Number(rootId);
  return Number.isSafeInteger(value) && value >= 0 ? value : null;
}

/** Publish a loss-tolerant mirror; the maps above remain the sole authority. */
function syncAgentProjection(rootId: string): void {
  const publish = agentProjectionPublisher;
  if (!publish) return;
  const projectedRootId = agentRootId(rootId);
  if (projectedRootId === null) return;
  const registry = state();
  const winner = topmost(rootId);
  const claim = registry.activeClaims.get(rootId);
  try {
    publish({
      rootId: projectedRootId,
      layers: [...registry.layers.values()]
        .filter((layer) => layer.rootId === rootId)
        .map((layer) => ({
          rootId: projectedRootId,
          layerId: layer.id,
          ...(layer.parentId ? { parentId: layer.parentId } : {}),
          ...(layer.viewId === undefined ? {} : { viewId: layer.viewId }),
          generation: layer.generation,
          modal: layer.modal,
          portalOrder: layer.portalOrder,
          visualOrder: layer.visualOrder,
          mountSequence: layer.mountSequence,
          topmost: winner?.generation === layer.generation,
          triggers: [...(layer.triggers ?? [])],
          ...(claim?.generation === layer.generation
            ? { activeClaimGestureId: claim.gestureId }
            : {}),
          ...(layer.command ? { command: { ...layer.command } } : {}),
        })),
      receipts: registry.receipts
        .filter((entry) => entry.rootId === rootId)
        .map((entry) => ({
          rootId: projectedRootId,
          sequence: entry.sequence,
          layerId: entry.layerId,
          generation: entry.generation,
          kind: entry.kind,
          decision: entry.decision,
          ...(entry.gestureId ? { gestureId: entry.gestureId } : {}),
          ...(entry.command ? { command: { ...entry.command } } : {}),
          timestampMs: entry.timestampMs,
        })),
      updatedAt: Date.now(),
    });
  } catch {
    // The stack is correctness-bearing; its lossy agent mirror is not.
  }
}

export function registerDismissLayer(input: DismissLayerRegistration): DismissLayerHandle {
  if (!input.id || !input.rootId) {
    throw new TypeError('[behavior] dismiss layer requires stable id and root');
  }
  if (
    input.viewId !== undefined &&
    (!Number.isSafeInteger(input.viewId) || input.viewId < 0)
  ) {
    throw new TypeError('[behavior] dismiss layer view id must be a non-negative safe integer');
  }
  if (input.triggers?.some((trigger) =>
    trigger !== 'escape' && trigger !== 'outside-press' && trigger !== 'swipe-down')) {
    throw new TypeError('[behavior] dismiss layer has an unsupported trigger');
  }
  const registry = state();
  const layerKey = key(input.rootId, input.id);
  const mountSequence = input.mountSequence ?? reserveDismissLayerMountSequence();
  if (!Number.isSafeInteger(mountSequence) || mountSequence <= 0) {
    throw new TypeError('[behavior] dismiss layer mount sequence must be a positive safe integer');
  }
  registry.nextMount = Math.max(registry.nextMount, mountSequence + 1);
  const mounted: MountedDismissLayer = {
    ...input,
    ...(input.triggers ? { triggers: [...new Set(input.triggers)] } : {}),
    generation: registry.nextGeneration++,
    mountSequence,
  };
  registry.layers.set(layerKey, mounted);
  syncAgentProjection(mounted.rootId);
  let current = mounted;
  let active = true;
  const handle: DismissLayerHandle = {
    id: mounted.id,
    generation: mounted.generation,
    isTopmost: () => active && topmost(current.rootId)?.generation === current.generation,
    claim(gestureId) {
      if (!active) return false;
      const winner = topmost(current.rootId);
      const existing = registry.activeClaims.get(current.rootId);
      if (
        existing?.generation === current.generation &&
        existing.gestureId === gestureId
      ) {
        // Web acquisition and the native lifecycle-start hook can observe the
        // same arena lease. Treat that duplicate edge as idempotent.
        return true;
      }
      const accepted = winner?.generation === current.generation && existing === undefined;
      receipt(
        current,
        'topmost-claim',
        accepted
          ? 'projected-to-motion-arena'
          : existing
            ? 'rejected-active-claim'
            : 'rejected-not-topmost',
        gestureId,
      );
      if (accepted) {
        registry.activeClaims.set(current.rootId, {
          layerId: current.id,
          generation: current.generation,
          gestureId,
        });
      }
      syncAgentProjection(current.rootId);
      return accepted;
    },
    release(gestureId, decision) {
      if (!active) return;
      const claim = registry.activeClaims.get(current.rootId);
      if (claim?.generation !== current.generation || claim.gestureId !== gestureId) return;
      registry.activeClaims.delete(current.rootId);
      receipt(current, 'dismiss', decision, claim.gestureId);
      syncAgentProjection(current.rootId);
    },
    update(next) {
      if (!active) return;
      const replacement: MountedDismissLayer = { ...current, ...next };
      current = replacement;
      if (registry.layers.get(layerKey)?.generation === replacement.generation) {
        registry.layers.set(layerKey, replacement);
      }
      syncAgentProjection(current.rootId);
    },
    dispose() {
      if (!active) return;
      active = false;
      const claim = registry.activeClaims.get(current.rootId);
      if (claim?.generation === current.generation) {
        registry.activeClaims.delete(current.rootId);
        receipt(current, 'structural-cancel', 'early-unmount', claim.gestureId);
      }
      // Generation fence: obsolete cleanup cannot unregister a remount that
      // intentionally reused this stable identity.
      if (registry.layers.get(layerKey)?.generation === current.generation) {
        registry.layers.delete(layerKey);
      }
      syncAgentProjection(current.rootId);
    },
  };
  return handle;
}

export function getDismissLayerSnapshot(rootId?: string): {
  layers: readonly MountedDismissLayer[];
  topmost: string | null;
  receipts: readonly DismissLayerReceipt[];
} {
  const registry = state();
  const layers = [...registry.layers.values()]
    .filter((layer) => rootId === undefined || layer.rootId === rootId);
  return {
    layers,
    topmost: rootId === undefined ? null : topmost(rootId)?.id ?? null,
    receipts: registry.receipts.filter(
      (entry) => rootId === undefined || entry.rootId === rootId,
    ),
  };
}

export function resetDismissLayerStackForTests(): void {
  const scope = globalThis as typeof globalThis & { __exactDismissLayerState?: DismissLayerState };
  const registry = scope.__exactDismissLayerState;
  if (registry) {
    const roots = new Set([...registry.layers.values()].map((layer) => layer.rootId));
    registry.receipts.forEach((entry) => roots.add(entry.rootId));
    for (const rootId of roots) {
      const projectedRootId = agentRootId(rootId);
      if (projectedRootId === null) continue;
      agentProjectionPublisher?.({
        rootId: projectedRootId,
        layers: [],
        receipts: [],
      });
    }
  }
  delete scope.__exactDismissLayerState;
}
