// @system @ref LLP 0363 §4–5 / LLP 0373 phase 3c — pure web image
// attribute normalization. Native cache and prefetch operations live in
// image-loading.ts so a direct DOM renderer does not retain host-call tables.

import type { ImageFetchPriority, ImageLoading } from './types.js';

export function resolveImageLoadingForWeb(
  loading: ImageLoading | undefined,
  inRepetitionScope: boolean,
): 'lazy' | undefined {
  if (loading === 'lazy' || ((loading === undefined || loading === 'auto') && inRepetitionScope)) {
    return 'lazy';
  }
  return undefined;
}

export function normalizeImageFetchPriority(
  priority: ImageFetchPriority | undefined,
): 'high' | 'low' | undefined {
  return priority === 'high' || priority === 'low' ? priority : undefined;
}
