import type { CanonicalTransitionMap, StyleTransition } from '../types.js';

export type ProductionTransitionNormalizer = (
  transition: StyleTransition | undefined,
) => CanonicalTransitionMap;

const EMPTY_DIRECT_DOM_TRANSITIONS = Object.freeze({}) as CanonicalTransitionMap;

let normalizeProductionTransitionImpl: ProductionTransitionNormalizer =
  () => EMPTY_DIRECT_DOM_TRANSITIONS;

/**
 * Production Contract web builds install transition parsing only when an
 * authored module uses transition=. The ordinary/full host installs it
 * unconditionally through its compatibility entry.
 */
export function installProductionTransitionNormalizer(
  normalizer: ProductionTransitionNormalizer,
): void {
  normalizeProductionTransitionImpl = normalizer;
}

export function normalizeProductionTransition(
  transition: StyleTransition | undefined,
): CanonicalTransitionMap {
  return normalizeProductionTransitionImpl(transition);
}
