// @system @ref LLP 0207 S0 / LLP 0193 G0-G1 — explicit mock reactive-query boundary.
//
// This is the Contract-side mock of the Snapback four-operation
// subscription seam: open a store, subscribe a query handle, apply a write,
// and notify affected subscriptions. It is intentionally coarse:
// table-level writes over-notify every subscription on that table and never
// under-notify. It is not a database engine and carries no sync semantics.

/**
 * INTERNAL PROTOCOL (`@ref LLP 0391 §4.5`): the `__exactContractQuery`
 * handle convention is not a supported author API and may break without
 * notice. Constructing raw handles outside `@exact/contract` is unsupported;
 * backends integrate through `ContractDataProvider` (LLP 0391 §4.1), and the
 * runtime projects providers into handles itself.
 */
export interface ContractQueryHandle<Row = unknown> {
  readonly __exactContractQuery: true;
  readonly table: string;
  readonly key?: string;
  read(): readonly Row[];
  subscribe(notify: (rows: readonly Row[]) => void): ContractQuerySubscription<Row>;
}

export interface ContractQuerySubscription<Row = unknown> {
  readonly current: readonly Row[];
  dispose(): void;
}

export interface ContractQueryBoundary {
  openStore(): object;
  query<Row>(
    table: string,
    read: (rows: readonly unknown[]) => readonly Row[],
    options?: { key?: string },
  ): ContractQueryHandle<Row>;
  subscribe<Row>(
    handle: ContractQueryHandle<Row>,
    notify: (rows: readonly Row[]) => void,
  ): ContractQuerySubscription<Row>;
  write<Row>(
    table: string,
    apply: (rows: readonly Row[]) => readonly Row[],
  ): void;
  snapshot(table: string): readonly unknown[];
  notificationCount(table?: string): number;
}

interface Subscription {
  table: string;
  notify(): void;
  disposed: boolean;
}

export function isContractQueryHandle(value: unknown): value is ContractQueryHandle {
  return Boolean(
    value &&
      typeof value === 'object' &&
      (value as { __exactContractQuery?: unknown }).__exactContractQuery === true &&
      typeof (value as { table?: unknown }).table === 'string' &&
      typeof (value as { read?: unknown }).read === 'function' &&
      typeof (value as { subscribe?: unknown }).subscribe === 'function',
  );
}

export function createContractMockQueryBoundary(
  initialTables: Record<string, readonly unknown[]> = {},
): ContractQueryBoundary {
  const tables = new Map<string, readonly unknown[]>();
  const subscriptions = new Set<Subscription>();
  const notifications = new Map<string, number>();

  Object.entries(initialTables).forEach(([table, rows]) => {
    tables.set(table, [...rows]);
    notifications.set(table, 0);
  });

  const readTable = (table: string): readonly unknown[] => tables.get(table) ?? [];
  const bumpNotification = (table: string): void => {
    notifications.set(table, (notifications.get(table) ?? 0) + 1);
  };

  function subscribeHandle<Row>(
    handle: ContractQueryHandle<Row>,
    notify: (rows: readonly Row[]) => void,
  ): ContractQuerySubscription<Row> {
    let current = handle.read();
    const subscription: Subscription = {
      table: handle.table,
      disposed: false,
      notify: () => {
        if (subscription.disposed) {
          return;
        }
        current = handle.read();
        bumpNotification(handle.table);
        notify(current);
      },
    };
    subscriptions.add(subscription);
    notify(current);
    return {
      get current() {
        return current;
      },
      dispose() {
        subscription.disposed = true;
        subscriptions.delete(subscription);
      },
    };
  }

  return {
    openStore() {
      return { kind: 'contract-query-mock-store' };
    },
    query<Row>(
      table: string,
      read: (rows: readonly unknown[]) => readonly Row[],
      options?: { key?: string },
    ): ContractQueryHandle<Row> {
      const handle: ContractQueryHandle<Row> = {
        __exactContractQuery: true,
        table,
        key: options?.key,
        read: () => [...read(readTable(table))],
        subscribe(notify) {
          return subscribeHandle(handle, notify);
        },
      };
      return handle;
    },
    subscribe<Row>(
      handle: ContractQueryHandle<Row>,
      notify: (rows: readonly Row[]) => void,
    ): ContractQuerySubscription<Row> {
      return subscribeHandle(handle, notify);
    },
    write<Row>(table: string, apply: (rows: readonly Row[]) => readonly Row[]): void {
      tables.set(table, [...apply(readTable(table) as readonly Row[])]);
      // 0207 S0 invariant: coarse is valid when it may over-notify and never
      // under-notifies. Table-level writes notify every subscription on that
      // table, regardless of whether a precise result changed.
      for (const subscription of subscriptions) {
        if (subscription.table === table) {
          subscription.notify();
        }
      }
    },
    snapshot(table: string): readonly unknown[] {
      return [...readTable(table)];
    },
    notificationCount(table?: string): number {
      if (table) {
        return notifications.get(table) ?? 0;
      }
      let total = 0;
      for (const count of notifications.values()) {
        total += count;
      }
      return total;
    },
  };
}
