/**
 * Web emulation for Liquid Glass surfaces on the DOM path.
 *
 * Accepts either carrier shape:
 *  - the raw authoring attrs as the host props carry them
 *    (`glassEffect`/`glass` enable plus `glassVariant`, `glassTint`,
 *    `glassInteractive`), or
 *  - the composed spec value from props/normalize.ts `composeGlassSpec`
 *    (`true` | `"regular"` | `"clear"` | `"<variant>;tint=<color>;interactive"`),
 *    which also appears style-carried on some paths (the LLP 0412
 *    glass-wins guard in backdrop-material-web.ts keys off it).
 *
 * Native hosts parse the same spec onto real material; the web
 * approximation is a frosted backdrop blur with a translucent wash — the
 * same recipe as the React renderer's `glassStyleFromProps`
 * (web-primitives.ts), so the two web paths keep one visual story.
 *
 * Precedence (LLP 0412 §1): Liquid Glass wins outright over
 * `backdropMaterial`/`backdropBlur` (no second backdrop effect), and the
 * glass wash replaces an authored background — native hosts clear the
 * node's fill so glass samples the true backdrop, and the emulation follows.
 */

export interface LiquidGlassWebStyle {
  readonly backdropFilter: string;
  readonly WebkitBackdropFilter: string;
  readonly backgroundColor: string;
}

export function lowerLiquidGlassWebStyle(
  source: Readonly<Record<string, unknown>>,
): LiquidGlassWebStyle | undefined {
  const enable = source.glassEffect ?? source.glass;
  // An explicit off wins even when a variant/tint is present.
  if (enable === false || enable === 'false') {
    return undefined;
  }
  const enabled =
    enable === true ||
    (typeof enable === 'string' && enable.length > 0) ||
    typeof source.glassVariant === 'string' ||
    (typeof source.glassTint === 'string' && source.glassTint.length > 0) ||
    source.glassInteractive === true;
  if (!enabled) {
    return undefined;
  }

  let variant: 'regular' | 'clear' = 'regular';
  let tint: string | undefined;
  if (typeof enable === 'string') {
    const segments = enable.split(';');
    if (segments[0]?.trim().toLowerCase() === 'clear') {
      variant = 'clear';
    }
    for (const segment of segments.slice(1)) {
      const part = segment.trim();
      if (part.startsWith('tint=') && part.length > 5) {
        tint = part.slice(5);
      }
    }
  }
  if (source.glassVariant === 'clear') {
    variant = 'clear';
  }
  if (typeof source.glassTint === 'string' && source.glassTint.length > 0) {
    tint = source.glassTint;
  }

  const blur = variant === 'clear' ? 10 : 18;
  const base = variant === 'clear' ? 'rgba(255,255,255,0.08)' : 'rgba(255,255,255,0.16)';
  const filter = `blur(${blur}px) saturate(180%)`;
  return {
    backdropFilter: filter,
    WebkitBackdropFilter: filter,
    backgroundColor: tint ?? base,
  };
}
