// @system @ref LLP 0353 §2 / LLP 0381 P4 —
// Renderer-facing graphics registry shared by editable and generated mounts.

import type { GraphicsScene } from '@exact/graphics';
import type {
  GraphicsPointerEvent,
  GraphicsSurfaceSize,
} from '@exact/graphics/contract';
import { loadGraphicsSceneText } from '@exact/renderer/graphics-lazy';

/**
 * LLP 0420 §9: scene text measurement needs a platform text-geometry backend.
 * The load is requested from surface registration and is idempotent inside the
 * wiring module, so the wiring module — and, transitively, whichever
 * `@exact/text` backend the platform picks — never joins the eager startup
 * graph of a Contract app that has no graphics surface (LLP 0128 module/byte
 * budgets).
 *
 * It goes through `@exact/renderer/graphics-lazy` rather than a literal
 * `import()` here because a literal one did NOT keep the promise on native: the
 * startup-artifact walker links literal `import()` edges into the served module
 * table, so `graphics-scene-text.ts`, both `@exact/text` backends and the five
 * `@chenglou/pretext` modules behind the web one all sat in the blog reference
 * lane's measured first-frame graph. See that seam for the three variants.
 */
function requestGraphicsSceneTextGeometry(): void {
  void loadGraphicsSceneText()
    .then((module) => {
      module.ensureGraphicsSceneTextGeometry();
    })
    .catch(() => {
      // A bundle without the chunk: @exact/graphics reports the missing
      // backend once and falls back to its advance estimate. A later surface
      // registration retries this load; the scene-text module itself guards
      // concurrent and already-completed backend installation.
    });
}

/**
 * Where the WEB host republishes the LLP 0420 §8 streams. The renderer's DOM
 * listeners know only the surface's string id (live objects never travel
 * through host props), so the mount publishes this sink into the same registry
 * record the canvas backend already resolves the scene through.
 */
export interface RegisteredGraphicsSurfaceEvents {
  emitPointer(event: GraphicsPointerEvent): void;
  emitSize(size: GraphicsSurfaceSize): void;
}

export interface RegisteredGraphicsSurface {
  scene: GraphicsScene;
  viewBox?: string;
  events?: RegisteredGraphicsSurfaceEvents;
}

/**
 * The §8 sink for one surface behavior, or undefined for an anonymous scene
 * (`graphics` with no `surface=`, which nothing can subscribe to anyway).
 *
 * Bound methods rather than the behavior itself: the registry record is read
 * by the renderer, which must not be handed an authoring surface it could
 * write the scene through.
 */
export function graphicsSurfaceEventSink(
  behavior:
    | {
        __emitPointer(event: GraphicsPointerEvent): void;
        __emitSize(size: GraphicsSurfaceSize): void;
      }
    | undefined,
): RegisteredGraphicsSurfaceEvents | undefined {
  if (!behavior) return undefined;
  return {
    emitPointer: (event) => behavior.__emitPointer(event),
    emitSize: (size) => behavior.__emitSize(size),
  };
}

const registeredSurfaceScenes = new Map<string, RegisteredGraphicsSurface>();

export function registerGraphicsSurfaceScene(
  surfaceId: string,
  entry: RegisteredGraphicsSurface,
): void {
  // This is the one call site both mount paths (interpreter and generated P4,
  // web and native) already pass through. Idempotent.
  requestGraphicsSceneTextGeometry();
  registeredSurfaceScenes.set(surfaceId, entry);
  (
    globalThis as {
      __exactGetContractGraphicsScene?: (
        id: string,
      ) => RegisteredGraphicsSurface | undefined;
    }
  ).__exactGetContractGraphicsScene = (id) =>
    registeredSurfaceScenes.get(id);
}

export function unregisterGraphicsSurfaceScene(surfaceId: string): void {
  registeredSurfaceScenes.delete(surfaceId);
}
