import {
  GRAPHICS_LIMITS,
  GRAPHICS_NODE_TYPES,
  GRAPHICS_SCHEMA_VERSION,
  type GraphicsCommit,
  type GraphicsDiagnostic,
  type GraphicsNodeProps,
  type GraphicsNodeRecord,
  type GraphicsNodeType,
  type GraphicsOperation,
  type GraphicsSceneSnapshot,
  type InternalNodeId,
  type SceneEpoch,
} from './types.js';

export interface GraphicsSceneOptions {
  mode?: 'development' | 'production';
  sceneEpoch?: SceneEpoch;
}

export interface GraphicsNodeHandle {
  readonly id: InternalNodeId;
  readonly type: GraphicsNodeType;
  update(patch: GraphicsNodeProps): void;
  appendChild(child: GraphicsNodeHandle): void;
  insertBefore(child: GraphicsNodeHandle, before: GraphicsNodeHandle | null): void;
  remove(): void;
}

export interface GraphicsScene {
  readonly sceneEpoch: SceneEpoch;
  createNode(type: GraphicsNodeType, props?: GraphicsNodeProps): GraphicsNodeHandle;
  createGroup(props?: GraphicsNodeProps): GraphicsNodeHandle;
  createClip(props?: GraphicsNodeProps): GraphicsNodeHandle;
  createTransform(props?: GraphicsNodeProps): GraphicsNodeHandle;
  createRect(props?: GraphicsNodeProps): GraphicsNodeHandle;
  createRoundedRect(props?: GraphicsNodeProps): GraphicsNodeHandle;
  createCircle(props?: GraphicsNodeProps): GraphicsNodeHandle;
  createEllipse(props?: GraphicsNodeProps): GraphicsNodeHandle;
  createLine(props?: GraphicsNodeProps): GraphicsNodeHandle;
  createPath(props?: GraphicsNodeProps): GraphicsNodeHandle;
  createImage(props?: GraphicsNodeProps): GraphicsNodeHandle;
  createText(props?: GraphicsNodeProps): GraphicsNodeHandle;
  createParagraph(props?: GraphicsNodeProps): GraphicsNodeHandle;
  createBatch(props?: GraphicsNodeProps): GraphicsNodeHandle;
  commit(): GraphicsCommit;
  snapshot(): GraphicsSceneSnapshot;
  authoringSnapshot(): GraphicsSceneSnapshot;
  subscribe(listener: (commit: GraphicsCommit) => void): () => void;
  attach(surfaceKey: string): void;
  detach(surfaceKey: string): void;
  dispose(): void;
}

let nextEpoch = 1;
const textEncoder = new TextEncoder();

/**
 * Deep clone for scene props and operations.
 *
 * NOT `structuredClone`. That global is absent on the Apple native runtime
 * (Hermes/Ibex), and its absence made the FIRST `createNode` on that host throw
 * `TypeError: undefined is not a function` — a scene that never committed, a
 * surface that painted white, and no diagnostic anywhere, because the throw
 * escaped through a host event callback. The scene model is the producer for
 * the LLP 0420 native transport, so it cannot depend on a web-only global.
 *
 * A JSON round trip is not a substitute either: it destroys the typed arrays
 * that carry batch columns (`positions`, `radii`, `colors`, `glyphs`,
 * `itemIds`), which is exactly the data a batch node exists for. So this walks
 * the value and copies typed arrays as typed arrays.
 *
 * Scope is deliberate: props are schema-constrained to JSON scalars, arrays,
 * plain objects, and typed arrays (plus `Date`, cloned here rather than shared
 * so a caller cannot mutate a committed record through it). Cyclic values are
 * not supported — they are already illegal, since a publication's operations
 * section is UTF-8 JSON (LLP 0420 §4).
 */
function deepClone<T>(value: T): T {
  if (value === null || typeof value !== 'object') return value;
  if (ArrayBuffer.isView(value)) {
    // `slice()` on a typed array returns a copy of the SAME type; DataView has
    // no `slice`, and nothing in the schema declares one.
    const view = value as unknown as { slice?: () => unknown };
    return (typeof view.slice === 'function' ? view.slice() : value) as T;
  }
  if (Array.isArray(value)) {
    return value.map((entry) => deepClone(entry)) as unknown as T;
  }
  if (value instanceof Date) return new Date(value.getTime()) as unknown as T;
  const result: Record<string, unknown> = {};
  for (const [key, entry] of Object.entries(value as Record<string, unknown>)) {
    result[key] = deepClone(entry);
  }
  return result as T;
}

function cloneRecord(record: GraphicsNodeRecord): GraphicsNodeRecord {
  return {
    ...record,
    children: [...record.children],
    props: deepClone(record.props),
    handlers: { ...record.handlers },
    ...(record.semantics ? { semantics: deepClone(record.semantics) } : {}),
  };
}

/**
 * Plain snapshot values can be deeply frozen and safely shared by later COW
 * receipts. Typed-array elements and Date internal slots stay mutable even
 * when their wrapper object is frozen (and freezing a non-empty typed array
 * throws on current engines), so records containing either must be refreshed
 * from protected internal state for every public receipt.
 */
function containsMutableLeaf(value: unknown): boolean {
  if (value === null || typeof value !== 'object') return false;
  if (ArrayBuffer.isView(value) || value instanceof Date) return true;
  if (Array.isArray(value)) return value.some(containsMutableLeaf);
  return Object.values(value).some(containsMutableLeaf);
}

function deepFreezePublic<T>(value: T): T {
  if (value === null || typeof value !== 'object') return value;
  if (ArrayBuffer.isView(value) || value instanceof Date) return value;
  for (const entry of Object.values(value)) deepFreezePublic(entry);
  return Object.freeze(value) as T;
}

function splitProps(props: GraphicsNodeProps): Omit<GraphicsNodeRecord, 'internalNodeId' | 'type' | 'parentId' | 'children'> {
  const { graphicsId, testId, agentId, handlers, semantics, semanticLod, ...paint } = props;
  return {
    ...(graphicsId === undefined ? {} : { graphicsId }),
    ...(testId === undefined ? {} : { testId }),
    ...(agentId === undefined ? {} : { agentId }),
    props: deepClone(paint),
    handlers: { ...(handlers ?? {}) },
    ...(semantics ? { semantics: deepClone(semantics) } : {}),
    ...(semanticLod === undefined ? {} : { semanticLod }),
  };
}

function finiteClone(value: unknown, path: string, diagnostics: GraphicsDiagnostic[]): unknown {
  if (typeof value === 'number' && !Number.isFinite(value)) {
    diagnostics.push({ code: 'NON_FINITE_VALUE_DEGRADED', message: `${path} was non-finite and degraded to 0` });
    return 0;
  }
  // Columnar batch data (positions/radii/colors/glyphs/itemIds) arrives as
  // typed arrays. The generic object walk below would flatten them into
  // `{"0": …}` plain objects, which survives the deep clone in the diff
  // operations but silently destroys every column in the applied snapshot —
  // and the snapshot is what a full publication is built from (LLP 0420 §4).
  // Degrade in place instead: the caller already handed us a clone.
  if (ArrayBuffer.isView(value) && !(value instanceof DataView)) {
    if (value instanceof Float32Array || value instanceof Float64Array) {
      for (let index = 0; index < value.length; index += 1) {
        if (Number.isFinite(value[index])) continue;
        diagnostics.push({ code: 'NON_FINITE_VALUE_DEGRADED', message: `${path}[${index}] was non-finite and degraded to 0` });
        value[index] = 0;
      }
    }
    return value;
  }
  if (Array.isArray(value)) return value.map((entry, index) => finiteClone(entry, `${path}[${index}]`, diagnostics));
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, entry]) => [key, finiteClone(entry, `${path}.${key}`, diagnostics)]));
  }
  return value;
}

function visitStrings(value: unknown, visit: (value: string) => void): void {
  if (typeof value === 'string') { visit(value); return; }
  if (Array.isArray(value)) { for (const entry of value) visitStrings(entry, visit); return; }
  if (value && typeof value === 'object') for (const entry of Object.values(value)) visitStrings(entry, visit);
}

const TRANSFORM_KEYS = ['a', 'b', 'c', 'd', 'tx', 'ty'] as const;

/**
 * The incremental commit path is intentionally narrower than the public
 * `GraphicsNodeProps` type. A canonical matrix can only affect paint-space
 * placement, so none of the scene-wide identity, size, string, batch, or
 * topology invariants need to be rechecked. Anything else takes the ordinary
 * validator path.
 */
function isCanonicalTransform(value: unknown): value is Record<typeof TRANSFORM_KEYS[number], number> {
  if (!value || typeof value !== 'object' || Array.isArray(value) || ArrayBuffer.isView(value)) return false;
  const keys = Object.keys(value);
  return keys.length === TRANSFORM_KEYS.length
    && TRANSFORM_KEYS.every((key) => Object.hasOwn(value, key) && typeof (value as Record<string, unknown>)[key] === 'number');
}

function isTransformOnlyUpdate(operation: GraphicsOperation): operation is Extract<GraphicsOperation, { type: 'update' }> {
  if (operation.type !== 'update') return false;
  const keys = Object.keys(operation.patch);
  return keys.length === 1 && keys[0] === 'transform' && isCanonicalTransform(operation.patch.transform);
}

export function createGraphicsScene(options: GraphicsSceneOptions = {}): GraphicsScene {
  const mode = options.mode ?? 'development';
  const sceneEpoch = options.sceneEpoch ?? String(nextEpoch++);
  if (!/^(0|[1-9][0-9]*)$/.test(sceneEpoch)) throw new TypeError('[graphics] sceneEpoch must be a canonical decimal u64 string');

  const authoring = new Map<InternalNodeId, GraphicsNodeRecord>();
  let applied = new Map<InternalNodeId, GraphicsNodeRecord>();
  let roots: InternalNodeId[] = [];
  let appliedRoots: InternalNodeId[] = [];
  let nextNodeId = 1;
  let generation = 0;
  let appliedGeneration = 0;
  // Accepted commit snapshots are copy-on-write, but public receipts never
  // own this protected state. Ordinary public records are deeply frozen and
  // may be reused; records with typed views / Dates are freshly cloned for
  // every receipt because those mutable leaves cannot be frozen reliably.
  // Updated records are replaced rather than mutated, preserving earlier
  // receipts without deep-cloning every calendar-like node per gesture frame.
  let publishedNodes: GraphicsNodeRecord[] = [];
  let publishedNodeIndexes = new Map<InternalNodeId, number>();
  let publishedPublicNodeCache: Array<GraphicsNodeRecord | null> = [];
  let publishedRefreshIndexes = new Set<number>();
  let disposed = false;
  let attachedSurface: string | null = null;
  let pending: GraphicsOperation[] = [];
  let forceFull = true;
  let scheduled = false;
  const listeners = new Set<(commit: GraphicsCommit) => void>();

  const stale = (message: string): false => {
    if (mode === 'development') throw new Error(`[graphics] ${message}`);
    return false;
  };

  const schedule = () => {
    if (scheduled || disposed) return;
    scheduled = true;
    queueMicrotask(() => {
      scheduled = false;
      if (pending.length === 0 || disposed) return;
      commit();
    });
  };

  const requireRecord = (id: InternalNodeId): GraphicsNodeRecord | null => {
    if (disposed) {
      stale('scene is disposed');
      return null;
    }
    const record = authoring.get(id);
    if (!record) {
      stale(`node handle ${id} is stale`);
      return null;
    }
    return record;
  };

  const depth = (id: InternalNodeId): number => {
    let current = authoring.get(id);
    let value = 1;
    const visited = new Set<InternalNodeId>();
    while (current?.parentId) {
      if (visited.has(current.parentId)) return GRAPHICS_LIMITS.maxDepth + 1;
      visited.add(current.parentId);
      current = authoring.get(current.parentId);
      value += 1;
    }
    return value;
  };

  const validate = (): { diagnostics: GraphicsDiagnostic[]; normalized: Map<InternalNodeId, GraphicsNodeRecord> } => {
    const diagnostics: GraphicsDiagnostic[] = [];
    const graphicsIds = new Map<string, InternalNodeId>();
    const agentIds = new Map<string, InternalNodeId>();
    if (authoring.size > GRAPHICS_LIMITS.maxNodesPerScene) diagnostics.push({ code: 'SCENE_NODE_LIMIT', message: `scene has ${authoring.size} nodes; limit is ${GRAPHICS_LIMITS.maxNodesPerScene}` });
    if (pending.length > GRAPHICS_LIMITS.maxOperationsPerCommit) diagnostics.push({ code: 'COMMIT_OPERATION_LIMIT', message: `commit has ${pending.length} operations; limit is ${GRAPHICS_LIMITS.maxOperationsPerCommit}` });
    const normalized = new Map<InternalNodeId, GraphicsNodeRecord>();
    for (const record of authoring.values()) {
      if (record.graphicsId) {
        const duplicate = graphicsIds.get(record.graphicsId);
        if (duplicate) diagnostics.push({ code: 'DUPLICATE_GRAPHICS_ID', message: `graphicsId ${JSON.stringify(record.graphicsId)} is duplicated`, nodeIds: [duplicate, record.internalNodeId] });
        else graphicsIds.set(record.graphicsId, record.internalNodeId);
      }
      if (record.agentId) {
        const duplicate = agentIds.get(record.agentId);
        if (duplicate) diagnostics.push({ code: 'DUPLICATE_AGENT_ID', message: `agentId ${JSON.stringify(record.agentId)} is duplicated`, nodeIds: [duplicate, record.internalNodeId] });
        else agentIds.set(record.agentId, record.internalNodeId);
      }
      if ((Object.keys(record.handlers).length > 0 || record.semantics) && !record.graphicsId) diagnostics.push({ code: 'MISSING_GRAPHICS_ID', message: 'interactive and semantic nodes require graphicsId', nodeIds: [record.internalNodeId] });
      visitStrings(record, (value) => {
        if (textEncoder.encode(value).byteLength > GRAPHICS_LIMITS.maxStringBytes) diagnostics.push({ code: 'STRING_LIMIT', message: `node contains a string larger than ${GRAPHICS_LIMITS.maxStringBytes} bytes`, nodeIds: [record.internalNodeId] });
      });
      if (record.type === 'batch') {
        const itemIds = record.props.itemIds;
        if (Array.isArray(itemIds)) {
          if (itemIds.length > GRAPHICS_LIMITS.maxBatchItems) diagnostics.push({ code: 'BATCH_ITEM_LIMIT', message: `batch has ${itemIds.length} items; limit is ${GRAPHICS_LIMITS.maxBatchItems}`, nodeIds: [record.internalNodeId] });
          const identities = itemIds.map((item) => String(item));
          if (new Set(identities).size !== identities.length) diagnostics.push({ code: 'DUPLICATE_BATCH_ITEM_ID', message: 'interactive batch itemIds must be unique', nodeIds: [record.internalNodeId] });
        }
      }
      if (depth(record.internalNodeId) > GRAPHICS_LIMITS.maxDepth) diagnostics.push({ code: 'SCENE_DEPTH_LIMIT', message: `node exceeds depth ${GRAPHICS_LIMITS.maxDepth}`, nodeIds: [record.internalNodeId] });
      const copy = cloneRecord(record);
      copy.props = finiteClone(copy.props, `node(${record.internalNodeId}).props`, diagnostics) as Record<string, unknown>;
      normalized.set(copy.internalNodeId, copy);
    }
    return { diagnostics, normalized };
  };

  const snapshotFrom = (records: Map<InternalNodeId, GraphicsNodeRecord>, snapshotRoots: InternalNodeId[], atGeneration: number): GraphicsSceneSnapshot => ({
    kind: 'snapshot', schemaVersion: GRAPHICS_SCHEMA_VERSION, sceneEpoch,
    commitGeneration: String(atGeneration), roots: [...snapshotRoots],
    nodes: [...records.values()].map(cloneRecord),
  });

  const resetPublishedPublicState = (): void => {
    publishedPublicNodeCache = publishedNodes.map(() => null);
    publishedRefreshIndexes = new Set<number>();
    for (let index = 0; index < publishedNodes.length; index += 1) {
      if (containsMutableLeaf(publishedNodes[index])) publishedRefreshIndexes.add(index);
    }
  };

  const invalidatePublishedPublicRecord = (
    index: number,
    record: GraphicsNodeRecord,
  ): void => {
    publishedPublicNodeCache[index] = null;
    if (containsMutableLeaf(record)) publishedRefreshIndexes.add(index);
    else publishedRefreshIndexes.delete(index);
  };

  const publishedSnapshot = (): GraphicsSceneSnapshot => {
    const publicNodes = publishedNodes.map((record, index) => {
      if (publishedRefreshIndexes.has(index)) {
        // Never retain an exposed mutable view/Date record as the source for
        // a later receipt. Its fresh clone comes from protected state.
        return deepFreezePublic(cloneRecord(record));
      }
      let cached = publishedPublicNodeCache[index];
      if (!cached) {
        cached = deepFreezePublic(cloneRecord(record));
        publishedPublicNodeCache[index] = cached;
      }
      return cached;
    });
    const snapshot: GraphicsSceneSnapshot = {
      kind: 'snapshot', schemaVersion: GRAPHICS_SCHEMA_VERSION, sceneEpoch,
      commitGeneration: String(appliedGeneration),
      roots: Object.freeze([...appliedRoots]) as unknown as InternalNodeId[],
      nodes: Object.freeze(publicNodes) as unknown as GraphicsNodeRecord[],
    };
    return Object.freeze(snapshot);
  };

  const fullOperations = (): GraphicsOperation[] => [...authoring.values()].map((node) => ({ type: 'create', nodeId: node.internalNodeId, node: cloneRecord(node) }));

  const normalizeTransformOnlyDiff = (): {
    diagnostics: GraphicsDiagnostic[];
    records: Map<InternalNodeId, GraphicsNodeRecord>;
  } | null => {
    if (
      forceFull
      || pending.length === 0
      || pending.length > GRAPHICS_LIMITS.maxOperationsPerCommit
      || !pending.every(isTransformOnlyUpdate)
    ) return null;

    const affected = new Set(pending.map((operation) => operation.nodeId));
    const diagnostics: GraphicsDiagnostic[] = [];
    const records = new Map<InternalNodeId, GraphicsNodeRecord>();

    // Authoring-map order matches the full validator's diagnostic order. The
    // final authored value is normalized once even when input coalescing put
    // several updates for the same node in this commit.
    for (const record of authoring.values()) {
      if (!affected.has(record.internalNodeId)) continue;
      const previous = applied.get(record.internalNodeId);
      const transform = record.props.transform;
      if (!previous || !isCanonicalTransform(transform)) return null;
      const normalizedTransform = finiteClone(
        deepClone(transform),
        `node(${record.internalNodeId}).props.transform`,
        diagnostics,
      );
      records.set(record.internalNodeId, {
        ...previous,
        props: { ...previous.props, transform: normalizedTransform },
      });
    }

    // This should be impossible through a live handle, but keeping the guard
    // makes the fast path fail closed if operation production changes.
    return records.size === affected.size ? { diagnostics, records } : null;
  };

  function commit(): GraphicsCommit {
    if (disposed) {
      stale('scene is disposed');
      return { kind: 'commit', schemaVersion: 1, sceneEpoch, commitGeneration: String(generation), mode: 'full', operations: [], accepted: false, diagnostics: [{ code: 'SCENE_DISPOSED', message: 'scene is disposed' }] };
    }
    generation += 1;
    const modeForCommit = forceFull ? 'full' : 'diff';
    const operations = modeForCommit === 'full' ? fullOperations() : pending.map((operation) => deepClone(operation));
    const transformOnlyDiff = modeForCommit === 'diff' ? normalizeTransformOnlyDiff() : null;

    if (transformOnlyDiff && [...transformOnlyDiff.records.keys()].every((nodeId) => publishedNodeIndexes.has(nodeId))) {
      pending = [];
      const nextPublishedNodes = publishedNodes.slice();
      for (const [nodeId, record] of transformOnlyDiff.records) {
        // The all-record guard above proves the index exists; keeping the
        // lookup local avoids another scene-wide map construction.
        const index = publishedNodeIndexes.get(nodeId)!;
        applied.set(nodeId, record);
        nextPublishedNodes[index] = record;
        invalidatePublishedPublicRecord(index, record);
      }
      publishedNodes = nextPublishedNodes;
      appliedGeneration = generation;
      // Diff operations are the native consumer's source of truth. Normalize
      // their matrices too, otherwise JSON transport would turn NaN/Infinity
      // into `null` while the retained snapshot correctly contains zero.
      const normalizedOperations = operations.map((operation) => {
        if (!isTransformOnlyUpdate(operation)) return operation;
        return {
          ...operation,
          patch: {
            transform: finiteClone(
              operation.patch.transform,
              `node(${operation.nodeId}).props.transform`,
              [],
            ),
          },
        } satisfies GraphicsOperation;
      });
      const snapshot = publishedSnapshot();
      const receipt: GraphicsCommit = {
        kind: 'commit', schemaVersion: 1, sceneEpoch,
        commitGeneration: String(generation), mode: modeForCommit, operations: normalizedOperations,
        accepted: true, diagnostics: transformOnlyDiff.diagnostics, snapshot,
      };
      for (const listener of listeners) listener(receipt);
      return receipt;
    }

    const { diagnostics, normalized } = validate();
    const refusal = diagnostics.some((diagnostic) => diagnostic.code !== 'NON_FINITE_VALUE_DEGRADED');
    pending = [];
    if (refusal) {
      forceFull = true;
      const receipt: GraphicsCommit = { kind: 'commit', schemaVersion: 1, sceneEpoch, commitGeneration: String(generation), mode: modeForCommit, operations, accepted: false, diagnostics };
      for (const listener of listeners) listener(receipt);
      return receipt;
    }
    applied = normalized;
    appliedRoots = [...roots];
    appliedGeneration = generation;
    forceFull = false;
    publishedNodes = [...applied.values()];
    publishedNodeIndexes = new Map(publishedNodes.map((record, index) => [record.internalNodeId, index]));
    resetPublishedPublicState();
    const snapshot = publishedSnapshot();
    const receipt: GraphicsCommit = { kind: 'commit', schemaVersion: 1, sceneEpoch, commitGeneration: String(generation), mode: modeForCommit, operations, accepted: true, diagnostics, snapshot };
    for (const listener of listeners) listener(receipt);
    return receipt;
  }

  const makeHandle = (id: InternalNodeId, type: GraphicsNodeType): GraphicsNodeHandle => ({
    id, type,
    update(patch) {
      const record = requireRecord(id); if (!record) return;
      if (Object.hasOwn(patch, 'graphicsId') && patch.graphicsId !== record.graphicsId) return void stale('graphicsId is immutable; delete and recreate the node');
      const next = { ...record, ...splitProps({ ...record.props, ...patch, graphicsId: record.graphicsId, testId: patch.testId ?? record.testId, agentId: patch.agentId ?? record.agentId, handlers: patch.handlers ?? record.handlers, semantics: patch.semantics ?? record.semantics, semanticLod: patch.semanticLod ?? record.semanticLod }) };
      authoring.set(id, next);
      pending.push({ type: 'update', nodeId: id, patch: deepClone(patch) });
      schedule();
    },
    appendChild(child) { this.insertBefore(child, null); },
    insertBefore(child, before) {
      const parent = requireRecord(id); const childRecord = requireRecord(child.id); if (!parent || !childRecord) return;
      if (child.id === id || contains(child.id, id)) return void stale('reparenting would create a cycle');
      if (before && !parent.children.includes(before.id)) return void stale(`before handle ${before.id} is not a child of ${id}`);
      detachFromParent(childRecord);
      const index = before ? parent.children.indexOf(before.id) : parent.children.length;
      parent.children.splice(index, 0, child.id);
      childRecord.parentId = id;
      pending.push({ type: 'reorder', nodeId: child.id, parentId: id, beforeId: before?.id ?? null });
      schedule();
    },
    remove() { removeSubtree(id); schedule(); },
  });

  const contains = (ancestorId: InternalNodeId, candidateId: InternalNodeId): boolean => {
    const ancestor = authoring.get(ancestorId);
    return ancestor?.children.some((child) => child === candidateId || contains(child, candidateId)) ?? false;
  };
  const detachFromParent = (record: GraphicsNodeRecord) => {
    if (record.parentId) {
      const parent = authoring.get(record.parentId);
      if (parent) parent.children = parent.children.filter((child) => child !== record.internalNodeId);
    } else roots = roots.filter((root) => root !== record.internalNodeId);
  };
  const removeSubtree = (id: InternalNodeId) => {
    const record = requireRecord(id); if (!record) return;
    for (const child of [...record.children]) removeSubtree(child);
    detachFromParent(record);
    authoring.delete(id);
    pending.push({ type: 'delete', nodeId: id });
  };

  const createNode = (type: GraphicsNodeType, props: GraphicsNodeProps = {}): GraphicsNodeHandle => {
    if (disposed) { stale('scene is disposed'); return makeHandle(`n${nextNodeId}` as InternalNodeId, type); }
    if (!(GRAPHICS_NODE_TYPES as readonly string[]).includes(type)) throw new TypeError(`[graphics] unsupported node type ${type}`);
    const id = `n${nextNodeId++}` as InternalNodeId;
    const record: GraphicsNodeRecord = { internalNodeId: id, type, parentId: null, children: [], ...splitProps(props) };
    authoring.set(id, record); roots.push(id);
    pending.push({ type: 'create', nodeId: id, node: cloneRecord(record) });
    schedule();
    return makeHandle(id, type);
  };

  return {
    sceneEpoch, createNode,
    createGroup: (props) => createNode('group', props), createClip: (props) => createNode('clip', props),
    createTransform: (props) => createNode('transform', props), createRect: (props) => createNode('rect', props),
    createRoundedRect: (props) => createNode('roundedRect', props), createCircle: (props) => createNode('circle', props),
    createEllipse: (props) => createNode('ellipse', props), createLine: (props) => createNode('line', props),
    createPath: (props) => createNode('path', props), createImage: (props) => createNode('image', props),
    createText: (props) => createNode('text', props), createParagraph: (props) => createNode('paragraph', props),
    createBatch: (props) => createNode('batch', props), commit,
    snapshot: () => snapshotFrom(applied, appliedRoots, appliedGeneration),
    authoringSnapshot: () => snapshotFrom(authoring, roots, generation),
    subscribe(listener) { listeners.add(listener); return () => listeners.delete(listener); },
    attach(surfaceKey) {
      if (disposed) return void stale('scene is disposed');
      if (!surfaceKey) throw new TypeError('[graphics] surface key is required');
      if (attachedSurface && attachedSurface !== surfaceKey) return void stale(`scene is already attached to ${attachedSurface}`);
      attachedSurface = surfaceKey;
    },
    detach(surfaceKey) { if (attachedSurface === surfaceKey) attachedSurface = null; },
    dispose() { disposed = true; authoring.clear(); applied.clear(); roots = []; appliedRoots = []; publishedNodes = []; publishedNodeIndexes.clear(); publishedPublicNodeCache = []; publishedRefreshIndexes.clear(); pending = []; listeners.clear(); attachedSurface = null; },
  };
}
