/**
 * Gradient Parsing (LLP 0296, ENG-22750)
 *
 * Parses the authored CSS-subset gradient grammar into the kernel's
 * four-field gradient model (`gradientType`/`gradientAngle`/start/end —
 * StyleMask bits 61-63, see `kernel/src/protocol/style_decoder.rs`), and
 * re-serializes the normalized form as CSS for the web renderers so web and
 * native stay pixel-converging (the LLP 0171 parity baseline).
 *
 * Supported grammar (v0 — honest about the kernel's two-stop, stop-less
 * model):
 * - `linear-gradient([<angle>deg | to <side-or-corner>,] <color>, <color>)`
 * - `radial-gradient([circle | <shape/position prefix>,] <color>, <color>)`
 *
 * Graceful degradation, never failure: more than two stops clamp to
 * first + last; per-stop positions and unsupported shape/position prefixes
 * are ignored; all such lossy normalizations set `clamped` so callers can
 * dev-warn. A value that cannot yield two colors parses to `null` (callers
 * drop the gradient and keep any solid background).
 *
 * Framework-neutral per the LLP 0157 styling charter: shared by the
 * renderer's native normalize path, both web style paths, and (through
 * them) Contract's `background=` attr.
 */

import { parseColor, colorToRgba } from './color.js';
import type { RGBAColor } from './color.js';

/** Protocol gradient type values (match `kernel/src/style.rs` GradientType). */
export const GRADIENT_TYPE_NONE = 0;
export const GRADIENT_TYPE_LINEAR = 1;
export const GRADIENT_TYPE_RADIAL = 2;

export type GradientTypeValue =
  | typeof GRADIENT_TYPE_NONE
  | typeof GRADIENT_TYPE_LINEAR
  | typeof GRADIENT_TYPE_RADIAL;

/** A gradient normalized to the kernel's four-field model. */
export interface ParsedGradient {
  type: typeof GRADIENT_TYPE_LINEAR | typeof GRADIENT_TYPE_RADIAL;
  /**
   * Degrees, CSS semantics (0deg = to top, clockwise) — the native
   * presenters use the same mapping. Only meaningful for linear gradients.
   */
  angle: number;
  start: RGBAColor;
  end: RGBAColor;
  /**
   * True when the authored value carried features the kernel model cannot
   * represent (extra stops, stop positions, unsupported prefixes) that were
   * clamped or ignored. Callers should surface a dev warning.
   */
  clamped: boolean;
}

const GRADIENT_PREFIX = /^(linear|radial)-gradient\(/i;

/** Quick shape test: is this string a gradient function value? */
export function isGradientValue(value: unknown): value is string {
  return typeof value === 'string' && GRADIENT_PREFIX.test(value.trim());
}

/** `to <side-or-corner>` keywords mapped to CSS angles (degrees). */
const DIRECTION_KEYWORDS: Record<string, number> = {
  'to top': 0,
  'to top right': 45,
  'to right top': 45,
  'to right': 90,
  'to bottom right': 135,
  'to right bottom': 135,
  'to bottom': 180,
  'to bottom left': 225,
  'to left bottom': 225,
  'to left': 270,
  'to top left': 315,
  'to left top': 315,
};

/** Default linear direction: CSS's `to bottom` (also the native default). */
export const DEFAULT_GRADIENT_ANGLE = 180;

/** Split on top-level commas (commas inside `rgb(...)` etc. don't split). */
function splitTopLevel(input: string, separator: string): string[] {
  const parts: string[] = [];
  let depth = 0;
  let current = '';
  for (let i = 0; i < input.length; i++) {
    const char = input[i];
    if (char === '(') depth++;
    else if (char === ')') depth--;
    if (char === separator && depth === 0) {
      parts.push(current);
      current = '';
    } else {
      current += char;
    }
  }
  parts.push(current);
  return parts;
}

/** Split a stop like `#fff 20%` into whitespace tokens outside parens. */
function splitStopTokens(stop: string): string[] {
  const tokens: string[] = [];
  let depth = 0;
  let current = '';
  for (let i = 0; i < stop.length; i++) {
    const char = stop[i];
    if (char === '(') depth++;
    else if (char === ')') depth--;
    if ((char === ' ' || char === '\t' || char === '\n') && depth === 0) {
      if (current) tokens.push(current);
      current = '';
    } else {
      current += char;
    }
  }
  if (current) tokens.push(current);
  return tokens;
}

interface DirectionParse {
  angle: number;
  clamped: boolean;
}

/** Parse a linear direction argument (`<angle>deg` or `to <side>`). */
function parseDirection(arg: string): DirectionParse {
  const normalized = arg.trim().toLowerCase().replace(/\s+/g, ' ');
  const keyword = DIRECTION_KEYWORDS[normalized];
  if (keyword !== undefined) {
    return { angle: keyword, clamped: false };
  }
  const angleMatch = normalized.match(/^(-?\d*\.?\d+)deg$/);
  if (angleMatch) {
    return { angle: Number(angleMatch[1]), clamped: false };
  }
  if (normalized === '0') {
    return { angle: 0, clamped: false };
  }
  // Unsupported direction syntax (rad/turn/`at ...`): degrade to the
  // default direction rather than failing the whole gradient.
  return { angle: DEFAULT_GRADIENT_ANGLE, clamped: true };
}

/**
 * Parse a CSS-subset gradient string into the kernel's four-field model.
 * Returns `null` when the value is not a gradient or cannot yield two
 * colors (callers keep any solid background — degrade, never fail).
 */
export function parseGradient(input: string): ParsedGradient | null {
  if (typeof input !== 'string') return null;
  const trimmed = input.trim();
  const prefixMatch = trimmed.match(GRADIENT_PREFIX);
  if (!prefixMatch || !trimmed.endsWith(')')) return null;

  const type =
    prefixMatch[1].toLowerCase() === 'linear' ? GRADIENT_TYPE_LINEAR : GRADIENT_TYPE_RADIAL;
  const inner = trimmed.slice(trimmed.indexOf('(') + 1, trimmed.length - 1);
  const args = splitTopLevel(inner, ',').map((arg) => arg.trim()).filter((arg) => arg !== '');
  if (args.length === 0) return null;

  let angle = type === GRADIENT_TYPE_LINEAR ? DEFAULT_GRADIENT_ANGLE : 0;
  let clamped = false;
  let stopArgs = args;

  const firstArgTokens = splitStopTokens(args[0]);
  const firstArgIsColorStop = firstArgTokens.length > 0 && parseColor(firstArgTokens[0]) !== null;
  if (!firstArgIsColorStop) {
    // Leading direction (linear) or shape/size/position prefix (radial).
    stopArgs = args.slice(1);
    if (type === GRADIENT_TYPE_LINEAR) {
      const direction = parseDirection(args[0]);
      angle = direction.angle;
      clamped = clamped || direction.clamped;
    } else {
      // Native radial rendering is center-anchored `circle farthest-side`
      // (endRadius = max(w,h)/2); any other prefix is ignored lossily.
      const normalizedPrefix = args[0].toLowerCase().replace(/\s+/g, ' ');
      if (normalizedPrefix !== 'circle' && normalizedPrefix !== 'circle farthest-side') {
        clamped = true;
      }
    }
  }

  const colors: RGBAColor[] = [];
  for (const stop of stopArgs) {
    const tokens = splitStopTokens(stop);
    if (tokens.length === 0) continue;
    const color = parseColor(tokens[0]);
    if (!color) {
      // Not a color stop we understand — ignored lossily.
      clamped = true;
      continue;
    }
    if (tokens.length > 1) {
      // Stop positions (`#fff 20%`) are not representable — ignored.
      clamped = true;
    }
    colors.push(color);
  }

  if (colors.length < 2) return null;
  if (colors.length > 2) {
    // The kernel model is two-stop: clamp to first + last.
    clamped = true;
  }

  return {
    type,
    angle,
    start: colors[0],
    end: colors[colors.length - 1],
    clamped,
  };
}

/**
 * Serialize a parsed gradient back to CSS. Web renderers emit this
 * normalized form (not the raw authored string) so web output matches what
 * native renders from the same four fields. Radial uses
 * `circle farthest-side` to match the native `endRadius = max(w,h)/2`
 * anchor.
 */
export function gradientToCss(gradient: ParsedGradient): string {
  const start = colorToRgba(gradient.start);
  const end = colorToRgba(gradient.end);
  if (gradient.type === GRADIENT_TYPE_RADIAL) {
    return `radial-gradient(circle farthest-side, ${start}, ${end})`;
  }
  return `linear-gradient(${gradient.angle}deg, ${start}, ${end})`;
}

/**
 * One-step helper for the web style paths: parse an authored gradient
 * string and return the normalized CSS, or `null` when unparseable.
 */
export function normalizeGradientCssValue(value: string): string | null {
  const gradient = parseGradient(value);
  return gradient ? gradientToCss(gradient) : null;
}
