// @system @ref LLP 0201#1 / LLP 0202#2.1 — browser host-ops implementation.
//
// Ordinary Contract web production does not need the native protocol encoder,
// Taffy viewport negotiation, or native Motion sidecars.  This module keeps
// the shared host-node ABI while committing that tree directly to the
// Contract Web Host.  The Contract Vite preset selects it at build time;
// native and compatibility adapters continue to use host-ops.ts.

import type { AgentSemantics, CanonicalProps, FullStyle } from './types.js';
import {
  DirtyFlags,
  NodeKind,
  appendChild as appendNodeChild,
  clearChildren,
  clearDirtyFlags,
  createDirectDomElementNode,
  createRootNode,
  createTextNode,
  insertBefore as insertNodeBefore,
  removeChild as removeNodeChild,
  type ElementNode,
  type RootNode,
  type TextNode,
} from './nodes/node.js';
import { resolveMotionLayoutIslandRootNode } from './motion-layout-island-shared.js';
import { getTagConfig, defaultTagConfig } from './tags/index.js';
import { normalizeProductionWebProps } from './props/web-props-runtime.js';
import { normalizeProductionWebStyle } from './style/web-style-runtime.js';
import { normalizeProductionTransition } from './style/transition-runtime.js';

export type { ElementNode, RootNode, TextNode } from './nodes/node.js';
export { NodeKind } from './nodes/node.js';

export interface ContractWebHostRegistry {
  sync(root: RootNode): void;
  remove(rootId: number): void;
  applyStyle?(node: ElementNode, property: string, value: unknown): boolean;
}

declare global {
  // eslint-disable-next-line no-var
  var __exactContractWebHost: ContractWebHostRegistry | undefined;
}

const liveRoots = new Map<number, RootNode>();

export interface CollectionAgentMetadata {
  readonly logicalItemCount: number;
  readonly mountedItemCount: number;
  readonly virtualized: boolean;
  readonly nativeHost: boolean;
}

export function collectionAgentSemantics(
  metadata: CollectionAgentMetadata,
  caller?: Readonly<Record<string, unknown>>,
): AgentSemantics {
  return {
    ...(caller ?? {}),
    kind: 'list',
    value: [
      metadata.logicalItemCount,
      metadata.mountedItemCount,
      metadata.virtualized ? 1 : 0,
      metadata.nativeHost ? 1 : 0,
    ],
    hint: 'logicalItems, mountedItems, virtualized, nativeHost',
  } as AgentSemantics;
}

function resolveNode(node: ElementNode, props: Record<string, unknown>): void {
  const config = getTagConfig(node.originalTag) ?? defaultTagConfig;
  node.originalProps = props;
  node.props = normalizeProductionWebProps(config.canonicalType, props, config.isRNStyle);
  node.style = normalizeProductionWebStyle(
    props.style as FullStyle | undefined,
    config.defaultFlexDirection,
  );
  node.transitions = normalizeProductionTransition(
    (props.style as FullStyle | undefined)?.transition,
  );
  node.dirtyFlags |= DirtyFlags.Props | DirtyFlags.Style | DirtyFlags.Events;
}

export function createInstance(
  type: string,
  props: Record<string, unknown>,
): ElementNode {
  const config = getTagConfig(type) ?? defaultTagConfig;
  const node = createDirectDomElementNode(
    config.canonicalType,
    type,
    config.isRNStyle,
    props,
  );
  resolveNode(node, props);
  return node;
}

export function createTextInstance(text: string): TextNode {
  return createTextNode(text);
}

export function appendChild(
  parent: ElementNode | RootNode,
  child: ElementNode | TextNode,
): void {
  appendNodeChild(parent, child);
}

export function insertBefore(
  parent: ElementNode | RootNode,
  child: ElementNode | TextNode,
  beforeChild: ElementNode | TextNode,
): void {
  insertNodeBefore(parent, child, beforeChild);
}

export function removeChild(
  parent: ElementNode | RootNode,
  child: ElementNode | TextNode,
): void {
  removeNodeChild(parent, child);
}

export const detachChild = removeChild;

export function updateInstanceProps(
  instance: ElementNode,
  _oldProps: Record<string, unknown>,
  newProps: Record<string, unknown>,
): void {
  resolveNode(instance, newProps);
}

export function updateTextContent(instance: TextNode, text: string): void {
  if (instance.text === text) return;
  instance.text = text;
  instance.dirtyFlags |= DirtyFlags.Props;
}

export function createRoot(rootId = 0, _owner?: string): RootNode {
  if (liveRoots.has(rootId)) {
    throw new Error(`Root ${rootId} is already initialized.`);
  }
  const root = createRootNode(rootId);
  liveRoots.set(rootId, root);
  return root;
}

export function clearContainer(root: RootNode): void {
  clearChildren(root);
}

export function destroyRoot(rootId: number): void {
  const root = liveRoots.get(rootId);
  if (!root) return;
  clearContainer(root);
  globalThis.__exactContractWebHost?.remove(rootId);
  liveRoots.delete(rootId);
}

export function commitBatch(root: RootNode): void {
  const host = globalThis.__exactContractWebHost;
  if (!host) {
    throw new Error(
      '[ExactRenderer] Contract web host is not installed before mount(); ' +
        'call installContractWebHost({ container }) first.',
    );
  }
  host.sync(root);
  const clear = (node: RootNode | ElementNode | TextNode): void => {
    clearDirtyFlags(node);
    if (node.kind !== NodeKind.Text) node.children.forEach(clear);
  };
  clear(root);
}

export function getRootContainerForNode(
  node: ElementNode | TextNode | RootNode,
): RootNode | null {
  let cursor: ElementNode | TextNode | RootNode = node;
  while (cursor.kind !== NodeKind.Root) {
    if (!cursor.parent) return null;
    cursor = cursor.parent as ElementNode | RootNode;
  }
  return cursor;
}

// Browser layout owns viewport resolution. These native transport controls are
// intentionally no-ops on the admitted web host.
export function setRootProtocolDispatchSuppressed(_rootId: number, _value: boolean): void {}
export function syncRootWindowState(root: RootNode): void {
  if (liveRoots.get(root.rootId) === root) commitBatch(root);
}

export type HostMotionBindingProperty =
  | 'translateX'
  | 'translateY'
  | 'scale'
  | 'scaleX'
  | 'scaleY'
  | 'rotation'
  | 'opacity'
  | 'borderRadius'
  | 'shadowOpacity'
  | 'shadowRadius';

export type HostMotionLayoutIslandProperty =
  | 'width'
  | 'height'
  | 'minWidth'
  | 'minHeight'
  | 'maxWidth'
  | 'maxHeight'
  | 'flexGrow'
  | 'flexShrink'
  | 'flexBasis'
  | 'rowGap'
  | 'columnGap'
  | 'aspectRatio';

export type HostMotionLayoutIslandClosureClass = 'fixedEnvelope' | 'closedAncestor';

export interface HostMotionSharedValue {
  readonly id: string;
  readonly generation: number;
  current(): number;
}

export interface HostMotionWritableSharedValue extends HostMotionSharedValue {
  value: number;
}

export interface HostMotionRuntimeWorkletArtifact {
  readonly [key: string]: unknown;
}

export interface HostMotionDerivedNodeMetadata {
  readonly identity: string;
  readonly generation: number;
  readonly role: 'derive' | 'sink';
  readonly artifact: HostMotionRuntimeWorkletArtifact;
}

export function createHostMotionDerivedNode(
  metadata: HostMotionDerivedNodeMetadata,
  current: () => number,
): HostMotionSharedValue {
  return Object.freeze({ id: metadata.identity, generation: metadata.generation, current });
}

export function hasNativeMotionProtocolEnvironment(): boolean {
  return false;
}

export function registerHostMotionBinding(): () => void {
  throw new Error('[ExactRenderer] native Motion bindings are not admitted by the lightweight web host');
}

export const registerHostMotionDerivedBinding = registerHostMotionBinding;
export const registerHostMotionScrollBinding = registerHostMotionBinding;

export { HOST_MOTION_LAYOUT_ISLAND_ROOT_PROP } from './motion-layout-island-shared.js';

/**
 * On the lightweight web host the "island" is advisory: there is no arena, and
 * the browser relayouts the subtree same-frame from the ordinary per-frame
 * channel style write (`applyHostChannelStyle` below). Registration therefore
 * succeeds and does nothing rather than throwing — the authoring tier must be
 * able to call one registration API on every target. The reference host-ops
 * implementation is where the LLP 0313 descriptor is lowered.
 */
export function registerHostMotionLayoutIslandBinding(
  _node: unknown,
  _islandRoot: unknown,
  _property: HostMotionLayoutIslandProperty,
  _source: HostMotionSharedValue,
  _closureClass?: HostMotionLayoutIslandClosureClass,
): () => void {
  return () => {};
}

// Interior properties (gap) may resolve to the marked node itself; extent
// properties need an island above. The rule itself lives in the leaf module
// `motion-layout-island-shared.ts`, shared with host-ops.ts: one implementation
// without this host importing the native reference host.
export function resolveHostMotionLayoutIslandRoot(
  node: unknown,
  property?: string,
): ElementNode | null {
  return resolveMotionLayoutIslandRootNode(node, property);
}

export function resolveHostMotionSortableScrollHost(): null {
  return null;
}

export function applyHostChannelStyle(
  node: unknown,
  property: string,
  value: unknown,
): boolean {
  if (!node || typeof node !== 'object' || (node as ElementNode).kind !== NodeKind.Element) {
    return false;
  }
  const element = node as ElementNode;
  const props = element.originalProps ?? {};
  const style = {
    ...((props.style as Record<string, unknown> | undefined) ?? {}),
    [property]: value,
  };
  resolveNode(element, { ...props, style });
  return globalThis.__exactContractWebHost?.applyStyle?.(element, property, value) ?? false;
}

// Handler IDs belong to the native protocol registry. The direct DOM host
// reads the current functions from originalProps at dispatch time.
export function registerHandler(_fn: Function): number { return 0; }
export function unregisterHandler(): void {}

export { getTagConfig } from './tags/index.js';
