// @system @ref LLP 0088, LLP 0139 — Collection geometry is a bounded,
// latest-wins structural input. It is intentionally separate from LLP 0281's
// presentation channels.

export type CollectionGeometrySource = 'user' | 'command' | 'restore';

export interface CollectionGeometrySample {
  readonly listId: string;
  readonly geometrySeq: number;
  readonly offset: number;
  readonly viewport: number;
  readonly velocity: number;
  readonly interactionEpoch: number;
  readonly source: CollectionGeometrySource;
}
export type CollectionGeometryInput = Omit<
  CollectionGeometrySample,
  'geometrySeq' | 'velocity' | 'interactionEpoch'
> & {
  readonly geometrySeq?: number;
  readonly velocity?: number;
  readonly interactionEpoch?: number;
  readonly timestamp?: number;
};

type ScheduleFrame = (commit: () => void) => () => void;

const scheduleNextFrame: ScheduleFrame = (commit) => {
  if (typeof requestAnimationFrame === 'function') {
    const id = requestAnimationFrame(commit);
    return () => cancelAnimationFrame(id);
  }
  let active = true;
  queueMicrotask(() => {
    if (active) commit();
  });
  return () => {
    active = false;
  };
};

/**
 * One pending sample per list. A burst of native/web scroll callbacks costs
 * one structural commit per frame, and sub-half-pixel repeats do not churn.
 */
export class CollectionGeometryMailbox {
  private latest: CollectionGeometrySample | null = null;
  private committed: CollectionGeometrySample | null = null;
  private cancelFrame: (() => void) | null = null;
  private nextSeq = 1;
  private interactionEpoch = 0;
  private lastPublishedAt = 0;
  private lastPublishedOffset = 0;

  constructor(
    private readonly commit: (sample: CollectionGeometrySample) => void,
    private readonly schedule: ScheduleFrame = scheduleNextFrame,
  ) {}

  publish(input: CollectionGeometryInput): void {
    const timestamp = input.timestamp ?? Date.now();
    if (input.source === 'user' && timestamp - this.lastPublishedAt > 120) {
      this.interactionEpoch += 1;
    }
    const elapsed = Math.max(1, timestamp - this.lastPublishedAt);
    const sample: CollectionGeometrySample = {
      listId: input.listId,
      geometrySeq: input.geometrySeq ?? this.nextSeq++,
      offset: Math.max(0, input.offset),
      viewport: Math.max(0, input.viewport),
      velocity: input.velocity ?? ((input.offset - this.lastPublishedOffset) / elapsed) * 1_000,
      interactionEpoch: input.interactionEpoch ?? this.interactionEpoch,
      source: input.source,
    };
    this.lastPublishedAt = timestamp;
    this.lastPublishedOffset = input.offset;
    this.latest = sample;
    if (!this.cancelFrame) {
      this.cancelFrame = this.schedule(() => this.flush());
    }
  }

  dispose(): void {
    this.cancelFrame?.();
    this.cancelFrame = null;
    this.latest = null;
  }

  private flush(): void {
    this.cancelFrame = null;
    const sample = this.latest;
    this.latest = null;
    if (!sample) return;
    const previous = this.committed;
    if (
      previous &&
      Math.abs(previous.offset - sample.offset) < 0.5 &&
      Math.abs(previous.viewport - sample.viewport) < 0.5 &&
      previous.source === sample.source
    ) {
      return;
    }
    this.committed = sample;
    this.commit(sample);
  }
}

export interface CollectionReachSnapshot {
  readonly totalSize: number;
  readonly offset: number;
  readonly viewport: number;
  readonly visibleStartIndex: number;
  readonly visibleEndIndex: number;
  readonly itemCount: number;
}

export interface CollectionReachCallbacks {
  readonly onStart?: (distanceFromEdge: number) => void;
  readonly onEnd?: (distanceFromEdge: number) => void;
}

/**
 * Thresholds in [0,1] are viewport fractions; larger values are pixels.
 * A short list chooses the end edge only, avoiding two callbacks for the same
 * first user sample. Edges re-arm only after the geometry leaves the zone.
 */
export class CollectionReachState {
  private startInside = false;
  private endInside = false;

  update(
    snapshot: CollectionReachSnapshot,
    startThreshold: number,
    endThreshold: number,
    callbacks: CollectionReachCallbacks,
  ): void {
    const startDistance = Math.max(0, snapshot.offset);
    const endDistance = Math.max(0, snapshot.totalSize - snapshot.viewport - snapshot.offset);
    const startLimit = resolveReachThreshold(startThreshold, snapshot.viewport);
    const endLimit = resolveReachThreshold(endThreshold, snapshot.viewport);
    const short = snapshot.totalSize <= snapshot.viewport;
    const nextStartInside = !short && startDistance <= startLimit;
    const nextEndInside = endDistance <= endLimit;
    if (nextStartInside && !this.startInside) callbacks.onStart?.(startDistance);
    if (nextEndInside && !this.endInside) callbacks.onEnd?.(endDistance);
    this.startInside = nextStartInside;
    this.endInside = nextEndInside;
  }
}

export function resolveReachThreshold(value: number, viewport: number): number {
  const finite = Number.isFinite(value) ? Math.max(0, value) : 0.5;
  return finite <= 1 ? finite * viewport : finite;
}

export type CollectionRefreshStatus = 'idle' | 'refreshing' | 'error';

export interface CollectionRefreshSnapshot {
  readonly status: CollectionRefreshStatus;
  readonly refreshId: number;
  readonly error?: unknown;
}

export interface CollectionRefreshContext {
  readonly refreshId: number;
  readonly signal: AbortSignal;
}

export type CollectionRefreshOutcome =
  | { readonly kind: 'completed'; readonly refreshId: number }
  | { readonly kind: 'cancelled'; readonly refreshId: number; readonly reason?: unknown }
  | { readonly kind: 'error'; readonly refreshId: number; readonly error: unknown };

interface ActiveCollectionRefresh {
  readonly refreshId: number;
  readonly controller: AbortController;
  readonly completion: Promise<CollectionRefreshOutcome>;
  readonly resolve: (outcome: CollectionRefreshOutcome) => void;
}

/**
 * One refresh attempt per collection. Concurrent host edges coalesce onto the
 * active completion; unmount cancellation settles immediately and fences late
 * async results; failures remain observable until the next explicit retry.
 */
export class CollectionRefreshState {
  private nextRefreshId = 1;
  private active: ActiveCollectionRefresh | null = null;
  private current: CollectionRefreshSnapshot = { status: 'idle', refreshId: 0 };

  constructor(
    private readonly onChange: (snapshot: CollectionRefreshSnapshot) => void = () => {},
  ) {}

  snapshot(): CollectionRefreshSnapshot {
    return { ...this.current };
  }

  begin(
    run: (context: CollectionRefreshContext) => unknown | PromiseLike<unknown>,
  ): Promise<CollectionRefreshOutcome> {
    if (this.active) {
      return this.active.completion;
    }

    const refreshId = this.nextRefreshId++;
    const controller = new AbortController();
    let resolve!: (outcome: CollectionRefreshOutcome) => void;
    const completion = new Promise<CollectionRefreshOutcome>((settle) => {
      resolve = settle;
    });
    this.active = { refreshId, controller, completion, resolve };
    this.publish({ status: 'refreshing', refreshId });

    let result: unknown | PromiseLike<unknown>;
    try {
      result = run({ refreshId, signal: controller.signal });
    } catch (error) {
      this.settleError(refreshId, error);
      return completion;
    }
    void Promise.resolve(result).then(
      () => this.settleCompleted(refreshId),
      (error: unknown) => this.settleError(refreshId, error),
    );
    return completion;
  }

  cancel(reason?: unknown): boolean {
    const active = this.active;
    if (!active) {
      return false;
    }
    // Clear first: abort listeners may synchronously reject the underlying
    // operation, and that late rejection must not turn cancellation to error.
    this.active = null;
    active.controller.abort(reason);
    this.publish({ status: 'idle', refreshId: active.refreshId });
    active.resolve({ kind: 'cancelled', refreshId: active.refreshId, reason });
    return true;
  }

  dispose(): void {
    this.cancel(new Error('collection refresh disposed'));
  }

  private settleCompleted(refreshId: number): void {
    const active = this.takeActive(refreshId);
    if (!active) return;
    this.publish({ status: 'idle', refreshId });
    active.resolve({ kind: 'completed', refreshId });
  }

  private settleError(refreshId: number, error: unknown): void {
    const active = this.takeActive(refreshId);
    if (!active) return;
    this.publish({ status: 'error', refreshId, error });
    active.resolve({ kind: 'error', refreshId, error });
  }

  private takeActive(refreshId: number): ActiveCollectionRefresh | null {
    if (this.active?.refreshId !== refreshId) {
      return null;
    }
    const active = this.active;
    this.active = null;
    return active;
  }

  private publish(snapshot: CollectionRefreshSnapshot): void {
    this.current = snapshot;
    this.onChange(this.snapshot());
  }
}
