const MOTION_SHARED_VALUE_KIND = Symbol.for("exact.motion.shared-value");
const MOTION_DERIVED_VALUE_KIND = Symbol.for("exact.motion.derived-value");
const MOTION_GESTURE_KIND = Symbol.for("exact.motion.gesture");
const MOTION_SORTABLE_LIST_KIND = Symbol.for("exact.motion.sortable-list");
const MOTION_SORTABLE_ITEM_KIND = Symbol.for("exact.motion.sortable-item");

