function sortableController(
  value: unknown,
): ContractSortableListController | null {
  return value &&
    typeof value === "object" &&
    (value as ContractSortableListController).__exactMotionKind ===
      MOTION_SORTABLE_LIST_KIND
    ? (value as ContractSortableListController)
    : null;
}

function sortableItemBinding(
  value: unknown,
): ContractSortableItemBinding | null {
  return value &&
    typeof value === "object" &&
    (value as ContractSortableItemBinding).__exactMotionKind ===
      MOTION_SORTABLE_ITEM_KIND
    ? (value as ContractSortableItemBinding)
    : null;
}

function sortableDerivedBinding(
  controller: ContractSortableListController,
  index: number,
  kind: "gap" | "drag" | "dragCross",
  identity: string,
): HostMotionSharedValue {
  const captures =
    kind === "gap"
      ? [controller.activeIndex, controller.gap, controller.slot, index, index]
      : kind === "drag"
        ? [controller.activeIndex, controller.translation, index]
        : [controller.activeIndex, controller.crossTranslation, index];
  const source =
    kind === "gap"
      ? "(function(){var active=worklet.captureGet(0),gap=worklet.captureGet(1),slot=worklet.captureGet(2),row=worklet.captureGet(4);worklet.output(0,(active===row||gap===0)?0:(active<0?(gap*worklet.clamp(((row-slot)+1),0,1)):(gap<0?(row>active?gap:0):(slot>active?((row>active&&row<=slot)?-gap:0):(slot<active?((row>=slot&&row<active)?gap:0):0)))));})"
      : "(function(){worklet.output(0,((worklet.captureGet(0)===worklet.captureGet(2))?worklet.captureGet(1):0));})";
  const artifact: HostMotionRuntimeWorkletArtifact = Object.freeze({
    schemaVersion: 1,
    installFormat: "source-utf8",
    compilerId: `motion:sortable:${kind}`,
    source,
    captureNames: Object.freeze(
      kind === "gap"
        ? ["activeIndex", "gap", "slot", "sourceIndex", "rowIndex"]
        : kind === "drag"
          ? ["activeIndex", "translation", "rowIndex"]
          : ["activeIndex", "crossTranslation", "rowIndex"],
    ),
    captureKinds: Object.freeze(
      kind === "gap"
        ? ["sharedValue", "sharedValue", "sharedValue", "scalar", "scalar"]
        : ["sharedValue", "sharedValue", "scalar"],
    ),
    captures: Object.freeze(captures),
    inputSlots: Object.freeze([]),
    outputSlots: Object.freeze(["return.value"]),
    callbacks: Object.freeze([]),
  });
  return createHostMotionDerivedNode(
    {
      identity: `contract:sortable:${identity}:${kind}:${index}`,
      generation: controller.generation,
      role: "sink",
      artifact,
    },
    () =>
      kind === "drag"
        ? controller.activeIndex.current() === index
          ? controller.translation.current()
          : 0
        : kind === "dragCross"
          ? controller.activeIndex.current() === index
            ? controller.crossTranslation.current()
            : 0
          : sortableGapOffset(
              controller.activeIndex.current(),
              controller.gap.current(),
              controller.slot.current(),
              index,
            ),
  );
}

function sortableGapOffset(
  active: number,
  gap: number,
  slot: number,
  row: number,
): number {
  if (active === row || gap === 0) return 0;
  if (active < 0) return gap * Math.min(Math.max(row - slot + 1, 0), 1);
  if (gap < 0) return row > active ? gap : 0;
  if (slot > active) return row > active && row <= slot ? -gap : 0;
  if (slot < active) return row >= slot && row < active ? gap : 0;
  return 0;
}

function sortableDragPresentation(
  sortableItem: ContractSortableItemBinding,
  claim: string,
): Readonly<Record<string, unknown>> {
  const controller = sortableItem.controller;
  return Object.freeze({
    schemaVersion: 1,
    claim,
    placeholder: sortableItem.placeholder,
    dropGhost: Object.freeze({
      translateX:
        controller.axis === "x"
          ? controller.ghostTranslation
          : controller.ghostCrossTranslation,
      translateY:
        controller.axis === "y"
          ? controller.ghostTranslation
          : controller.ghostCrossTranslation,
      visible: controller.ghostVisible,
      target: Object.freeze({
        x: controller.ghostTargetX,
        y: controller.ghostTargetY,
        enabled: controller.ghostTargetEnabled,
      }),
      autoScrolling: controller.ghostAutoScrolling,
      clip: Object.freeze({
        x: controller.ghostViewportX,
        y: controller.ghostViewportY,
        width: controller.ghostViewportWidth,
        height: controller.ghostViewportHeight,
        enabled: controller.ghostViewportEnabled,
      }),
    }),
  });
}

function sortableTransform(
  axis: "x" | "y",
  value: number,
  cross: number = 0,
): string {
  const main =
    axis === "x" ? `translateX(${value}px)` : `translateY(${value}px)`;
  if (cross === 0) return main;
  return axis === "x"
    ? `${main} translateY(${cross}px)`
    : `translateX(${cross}px) ${main}`;
}

function registerSortablePresentationBinding(
  element: ElementNode,
  controller: ContractSortableListController,
  index: number,
  kind: "gap" | "drag",
  identity: string,
  apply: (value: number, cross: number) => void,
): () => void {
  const source = sortableDerivedBinding(controller, index, kind, identity);
  // Grouped drags follow the pointer into sibling lists, so the dragged
  // row's presentation needs the cross-axis channel as well.
  const crossSource =
    kind === "drag" && controller.group !== null
      ? sortableDerivedBinding(controller, index, "dragCross", identity)
      : null;
  const mainChannel = controller.axis === "x" ? "translateX" : "translateY";
  const crossChannel = controller.axis === "x" ? "translateY" : "translateX";
  const disposeGraph = registerHostMotionDerivedBinding(
    element,
    mainChannel,
    source,
  );
  const disposeCrossGraph =
    crossSource !== null
      ? registerHostMotionDerivedBinding(element, crossChannel, crossSource)
      : null;
  const applyCurrent = (): void =>
    apply(source.current(), crossSource?.current() ?? 0);
  applyCurrent();
  if (hasNativeMotionProtocolEnvironment()) {
    return () => {
      disposeCrossGraph?.();
      disposeGraph();
    };
  }
  const dependencies =
    kind === "drag"
      ? crossSource !== null
        ? [
            controller.activeIndex,
            controller.translation,
            controller.crossTranslation,
          ]
        : [controller.activeIndex, controller.translation]
      : [controller.activeIndex, controller.gap, controller.slot];
  const disposers = dependencies.map((dependency) =>
    dependency.subscribe(() => applyCurrent()),
  );
  return () => {
    disposers.forEach((dispose) => dispose());
    disposeCrossGraph?.();
    disposeGraph();
  };
}

/**
 * Direct SharedValue -> property edges usable without a compiler graph
 * binding. Keyed on the LOWERED style prop, so the paint family arrives as
 * `borderRadius`/`shadowOpacity`/`shadowRadius` (LLP 0417 §4).
 */
const DIRECT_PAINT_MOTION_PROPERTIES: Partial<
  Record<string, HostMotionBindingProperty>
> = {
  borderRadius: "borderRadius",
  shadowOpacity: "shadowOpacity",
  shadowRadius: "shadowRadius",
};

function directHostMotionProperty(
  styleProp: string,
  expr: Expr,
): HostMotionBindingProperty | null {
  const isSharedRead = (candidate: Expr): boolean =>
    candidate.kind === "member" &&
    candidate.property === "value" &&
    candidate.object.kind === "ident";
  if (styleProp === "opacity") return isSharedRead(expr) ? "opacity" : null;
  const paint = DIRECT_PAINT_MOTION_PROPERTIES[styleProp];
  if (paint) return isSharedRead(expr) ? paint : null;
  if (
    styleProp !== "transform" ||
    expr.kind !== "call" ||
    expr.args.length !== 1 ||
    !isSharedRead(expr.args[0]!) ||
    expr.callee.kind !== "member"
  ) {
    return null;
  }
  const properties: Partial<Record<string, HostMotionBindingProperty>> = {
    translateX: "translateX",
    translateY: "translateY",
    scale: "scale",
    scaleX: "scaleX",
    scaleY: "scaleY",
    rotate: "rotation",
  };
  return properties[expr.callee.property] ?? null;
}

const VIEW_EVAL = { identFallbackToString: true } as const;

function isCompiledComponentValue(value: unknown): value is CompiledComponent {
  return (
    typeof value === "object" &&
    value !== null &&
    (value as { kind?: unknown }).kind === "contract-component"
  );
}

