const TAG_LOWERING: Record<string, ContractTagLowering> = CONTRACT_TAG_LOWERING;
/**
 * Lowerings the RUNTIME contributes for synthetic elements the grammar has no
 * tag for — today only the LLP 0420 native graphics surface, whose host tag is
 * a module-backed `nativeView` registered at first use.
 *
 * Kept separate from {@link TAG_LOWERING} on purpose: `CONTRACT_TAG_LOWERING`
 * is the built-in grammar authority, and a runtime that mutated it would put a
 * tag no `.contract` file can author into the authoring inventory.
 */
const RUNTIME_TAG_LOWERING: Record<string, ContractTagLowering> = Object.create(
  null,
) as Record<string, ContractTagLowering>;
const STYLE_PROP_MAP: Record<string, string> = CONTRACT_STYLE_PROP_MAP;
const TEXT_STYLE_PROP_MAP: Record<string, string> =
  CONTRACT_TEXT_STYLE_PROP_MAP;
const PROP_RENAMES: Record<string, string> = CONTRACT_PROP_RENAMES;

interface OverlayPropLowering {
  hostProp: string;
  map?: (value: unknown) => unknown;
}

function lowerOverlayProp(name: string): OverlayPropLowering | undefined {
  const hostProp = (CONTRACT_OVERLAY_PROP_MAP as Record<string, string>)[name];
  if (!hostProp) {
    return undefined;
  }
  return {
    hostProp,
    map: name === "focusTrap" ? mapFocusTrapValue : undefined,
  };
}

function mapFocusTrapValue(value: unknown): unknown {
  return value === true ? "trapped" : undefined;
}

function mapHeadingLevelValue(value: unknown): unknown {
  return typeof value === "number" &&
    Number.isInteger(value) &&
    value >= 1 &&
    value <= 6
    ? value
    : undefined;
}

function actionNameFromExpr(expr: Expr): string | undefined {
  if (expr.kind === "ident") {
    return expr.name;
  }
  if (expr.kind === "call" && expr.callee.kind === "ident") {
    return expr.callee.name;
  }
  return undefined;
}

// `submit`, `keydown`, and `dismiss` all lower to onKeyDown, so onKeyDown
// consumers compose instead of clobbering (authoring order preserved).
// Module-scope: mountElement runs per element and must not re-allocate it.
function chainEventHandler(
  existing: unknown,
  next: (payload: unknown) => void,
) {
  if (typeof existing !== "function") {
    return next;
  }
  return (payload: unknown) => {
    (existing as (p: unknown) => void)(payload);
    next(payload);
  };
}

function lowerEventName(event: string, tag: string): string | null {
  switch (event) {
    case "press":
      return "onPress";
    case "longpress":
      return "onLongPress";
    case "keydown":
      return "onKeyDown";
    case "accessibilityaction":
      return "onAccessibilityAction";
    case "change":
      if (tag === "input") {
        return "onChangeText";
      }
      if (tag === "toggle") {
        return "onValueChange";
      }
      return "onChange";
    case "focus":
      return "onFocus";
    case "blur":
      return "onBlur";
    case "load":
      return tag === "image" || tag === "lottie" || tag === "rive" ? "onLoad" : null;
    case "error":
      return tag === "image" || tag === "lottie" || tag === "rive" ? "onError" : null;
    // LLP 0394 Lottie lifecycle. `complete` fires at the final end (never
    // while loop=true); `looped` fires per iteration.
    case "complete":
      return tag === "lottie" ? "onComplete" : null;
    case "looped":
      return tag === "lottie" ? "onLooped" : null;
    // LLP 0395 Rive lifecycle, state-machine, data-binding, and editor events.
    case "statechange":
      return tag === "rive" ? "onStateChange" : null;
    case "datachange":
      return tag === "rive" ? "onDataChange" : null;
    case "riveevent":
      return tag === "rive" ? "onRiveEvent" : null;
    case "submit":
      return "onKeyDown";
    case "scrollend":
      return "onScrollEnd";
    case "refresh":
      return "onRefresh";
    // LLP 0281 stage 0 pointer vocabulary (LLP 0275 A1). The web host
    // (dom-mirror) delivers element-local envelopes; native delivery
    // arrives with LLP 0099's intake substrate.
    case "pointerdown":
      return "onPointerDown";
    case "pointermove":
      return "onPointerMove";
    case "pointerup":
      return "onPointerUp";
    case "pointercancel":
      return "onPointerCancel";
    case "pointerenter":
      return "onPointerEnter";
    case "pointerleave":
      return "onPointerLeave";
    // Framework-internal semantic event emitted by the native Motion domain.
    case "pagercommit":
      return "onPagerCommit";
    default:
      return null;
  }
}

// ---------------------------------------------------------------------------
// LLP 0281 stage 0 — channel event targets and the §3.4 sampled crossing
// ---------------------------------------------------------------------------

/** Resolve a channel handle (or a channel-set's `.self`) to its channel. */
function toValueChannel(value: unknown): ContractValueChannel | null {
  if (isValueChannel(value)) {
    return value;
  }
  if (isValueChannelSet(value)) {
    return value.self;
  }
  return null;
}

/**
 * A pointer event attr whose expression is an ident/member chain resolving
 * to a value channel binds as a channel write (the §3.1 rule: the
 * affordable path is the only path). Resolution happens once, untracked —
 * channel handles are stable per component instance.
 */
function resolveChannelEventTarget(
  handlerExpr: Expr,
  scope: Scope,
): ContractValueChannel | null {
  if (handlerExpr.kind !== "ident" && handlerExpr.kind !== "member") {
    return null;
  }
  const value = untrack(() => {
    try {
      return evalRuntimeExpr(handlerExpr, scope);
    } catch {
      return null;
    }
  });
  return toValueChannel(value);
}

/** Channels named by `sample(<channel>)` arguments of an edge action call. */
function sampledChannelsInCall(
  handlerExpr: Expr,
  scope: Scope,
): ContractValueChannel[] {
  if (handlerExpr.kind !== "call") {
    return [];
  }
  const channels: ContractValueChannel[] = [];
  const visit = (expr: Expr): void => {
    if (
      expr.kind === "call" &&
      expr.callee.kind === "ident" &&
      expr.callee.name === "sample"
    ) {
      const target = expr.args[0];
      if (target) {
        const channel = resolveChannelEventTarget(target, scope);
        if (channel) {
          channels.push(channel);
        }
      }
      return;
    }
    switch (expr.kind) {
      case "call":
        visit(expr.callee);
        expr.args.forEach(visit);
        break;
      case "member":
        visit(expr.object);
        break;
      case "ternary":
        visit(expr.test);
        visit(expr.consequent);
        visit(expr.alternate);
        break;
      case "binary":
        visit(expr.left);
        visit(expr.right);
        break;
      case "unary":
        visit(expr.operand);
        break;
      default:
        break;
    }
  };
  handlerExpr.args.forEach(visit);
  return channels;
}

/**
 * Find the value channel a sink expression reads (LLP 0281 §3.3). Runs
 * once at element mount, untracked: channel handles are stable bindings
 * (behavior slots or pass-through props), so resolution never needs to be
 * reactive. Returns the first channel found — the analyzer restricts sink
 * expressions to one channel plus literals.
 */
function findChannelReadInExpr(
  expr: Expr,
  scope: Scope,
): ContractValueChannel | null {
  let found: ContractValueChannel | null = null;
  const lookupChannel = (name: string): ContractValueChannel | null => {
    const binding = scope.lookup(name);
    if (!binding) {
      return null;
    }
    const value =
      binding.kind === "value" || binding.kind === "local"
        ? binding.value
        : untrack(() => {
            try {
              return binding.get();
            } catch {
              return null;
            }
          });
    return toValueChannel(value);
  };
  const visit = (node: Expr): void => {
    if (found) {
      return;
    }
    switch (node.kind) {
      case "ident":
        found = lookupChannel(node.name);
        return;
      case "member":
        visit(node.object);
        return;
      case "index":
        visit(node.object);
        visit(node.index);
        return;
      case "call":
        visit(node.callee);
        node.args.forEach(visit);
        return;
      case "unary":
        visit(node.operand);
        return;
      case "binary":
        visit(node.left);
        visit(node.right);
        return;
      case "ternary":
        visit(node.test);
        visit(node.consequent);
        visit(node.alternate);
        return;
      case "template":
        node.parts.forEach((part) => {
          if (part.kind === "expr") {
            visit(part.expr);
          }
        });
        return;
      case "array":
        node.items.forEach((item) =>
          visit(isExprSpread(item) ? item.value : item),
        );
        return;
      case "object":
        node.entries.forEach((entry) =>
          visit(isExprSpread(entry) ? entry.value : entry.value),
        );
        return;
      default:
        return;
    }
  };
  visit(expr);
  return found;
}

function toMotionReadable(value: unknown): ContractMotionReadable | null {
  if (!value || typeof value !== "object") return null;
  const candidate = value as Partial<ContractMotionReadable>;
  return (candidate.__exactMotionKind === MOTION_SHARED_VALUE_KIND ||
    candidate.__exactMotionKind === MOTION_DERIVED_VALUE_KIND) &&
    typeof candidate.current === "function" &&
    typeof candidate.subscribe === "function"
    ? (candidate as ContractMotionReadable)
    : null;
}

function registerElementMotionScrollBinding(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  element: ElementNode,
  scope: Scope,
  component: ComponentIR,
  ctx: RuntimeContext,
): void {
  const targetExpr = node.props.testId;
  if (!targetExpr || targetExpr.kind !== "string") return;
  const bindings = component.motion?.scrollBindings ?? [];
  for (const binding of bindings) {
    if (binding.target !== targetExpr.value) continue;
    const slot = scope.lookup(binding.name);
    let raw: unknown = null;
    if (slot) {
      if (slot.kind === "value" || slot.kind === "local") raw = slot.value;
      else raw = untrack(() => slot.get());
    }
    const readable = toMotionReadable(raw);
    if (
      !readable ||
      readable.__exactMotionKind !== MOTION_SHARED_VALUE_KIND ||
      !("value" in (raw as object))
    ) {
      throw new Error(
        `[motion] scroll binding "${binding.name}" did not resolve to a live SharedValue`,
      );
    }
    const owner = getOwner();
    registerHydrationActivation(ctx, () => {
      owner?.register(
        registerHostMotionScrollBinding(
          element,
          raw as HostMotionWritableSharedValue,
          binding.axis,
        ),
      );
    });
  }
}

function registerElementMotionCommandWitness(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  element: ElementNode,
  scope: Scope,
  ctx: RuntimeContext,
): void {
  const press = node.events.press;
  if (!press || press.kind !== "ident") return;
  const slot = scope.lookup(press.name);
  const candidate =
    slot?.kind === "value" || slot?.kind === "local"
      ? slot.value
      : slot
        ? untrack(() => slot.get())
        : null;
  if (!isMotionCommandRef(candidate)) return;
  const owner = getOwner();
  registerHydrationActivation(ctx, () => {
    owner?.register(
      registerMotionCommandWitness(candidate, {
        id: `contract-view-${element.id}`,
        readState: () => {
          const props = element.originalProps ?? {};
          if (props.disabled === true || props.accessibilityDisabled === true)
            return "disabled";
          if (
            props.hidden === true ||
            props.accessibilityElementsHidden === true ||
            element.style.display === "none" ||
            element.style.opacity === 0
          )
            return "conditionally-hidden";
          return "visible";
        },
      }),
    );
  });
}

function scopeIdentifierValue(expr: Expr, scope: Scope): unknown {
  if (expr.kind !== "ident") return undefined;
  const slot = scope.lookup(expr.name);
  if (!slot) return undefined;
  return slot.kind === "value" || slot.kind === "local"
    ? slot.value
    : untrack(() => slot.get());
}

function dismissLayerVisualOrder(
  props: Readonly<Record<string, unknown>>,
): number {
  let zIndex: number | undefined;
  let elevation: number | undefined;
  const visit = (candidate: unknown): void => {
    if (Array.isArray(candidate)) {
      candidate.forEach(visit);
      return;
    }
    if (!candidate || typeof candidate !== "object") return;
    const style = candidate as Record<string, unknown>;
    if (typeof style.zIndex === "number" && Number.isFinite(style.zIndex)) {
      zIndex = style.zIndex;
    }
    if (
      typeof style.elevation === "number" &&
      Number.isFinite(style.elevation)
    ) {
      elevation = style.elevation;
    }
  };
  visit(props.style);
  return zIndex ?? elevation ?? 0;
}

function dismissLayerPortalOrder(
  props: Readonly<Record<string, unknown>>,
): number {
  if (
    props.__exactPortalLevel === "root" ||
    (typeof props.portalTarget === "string" && props.portalTarget.length > 0)
  ) {
    return 1_000;
  }
  return props.__exactPortalLevel === "tree" ? 1 : 0;
}

function elementMotionGestureDescriptor(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  scope: Scope,
  component: ComponentIR,
): ContractMotionGestureDescriptor | null {
  const targetExpr = node.props.testId;
  if (!targetExpr || targetExpr.kind !== "string" || !component.motion)
    return null;
  const compositions = component.motion.compositions ?? [];
  const referenced = new Set(
    compositions.flatMap((composition) => composition.children),
  );
  const roots = [
    ...component.motion.gestures.map((gesture) => ({
      name: gesture.name,
      claim: gesture.claim,
    })),
    ...compositions.map((composition) => ({
      name: composition.name,
      claim: composition.claim,
    })),
  ].filter(
    (gesture) =>
      !referenced.has(gesture.name) && gesture.claim === targetExpr.value,
  );
  if (roots.length === 0) return null;
  if (roots.length > 1) {
    throw new Error(
      `[motion] gesture owner "${targetExpr.value}" has multiple uncomposed roots`,
    );
  }
  const binding = scope.lookup(roots[0]!.name);
  const raw =
    binding?.kind === "value" || binding?.kind === "local"
      ? binding.value
      : binding
        ? untrack(() => binding.get())
        : null;
  if (!raw || typeof raw !== "object") {
    throw new Error(
      `[motion] gesture "${roots[0]!.name}" did not resolve to a descriptor`,
    );
  }
  const descriptor = raw as Partial<ContractMotionGestureDescriptor>;
  if (
    descriptor.__exactMotionKind !== MOTION_GESTURE_KIND ||
    (descriptor.descriptorType !== "gesture" &&
      descriptor.descriptorType !== "composition")
  ) {
    throw new Error(
      `[motion] gesture "${roots[0]!.name}" resolved to an invalid descriptor`,
    );
  }
  return descriptor as ContractMotionGestureDescriptor;
}

const MOTION_DRAG_PRESENTATION_KIND = Symbol.for(
  "exact.motion.drag-presentation",
);

interface ContractMotionDragPresentationProp {
  readonly schemaVersion: 1;
  readonly claim: string;
  readonly placeholder: "hidden" | "ghost" | "none";
}

/**
 * Resolve the RFC 0368 drag presentation declaration claiming this element,
 * if any, to the serializable host prop the presenters consume
 * (`__exactMotionDragPresentation`). Mirrors the gesture-descriptor
 * attachment: claims resolve against the literal testId.
 */
function elementMotionDragPresentationProp(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  scope: Scope,
  component: ComponentIR,
): ContractMotionDragPresentationProp | null {
  const targetExpr = node.props.testId;
  const presentations = component.motion?.dragPresentations;
  if (!targetExpr || targetExpr.kind !== "string" || !presentations?.length)
    return null;
  const record = presentations.find(
    (candidate) => candidate.claim === targetExpr.value,
  );
  if (!record) return null;
  const binding = scope.lookup(record.name);
  const raw =
    binding?.kind === "value" || binding?.kind === "local"
      ? binding.value
      : binding
        ? untrack(() => binding.get())
        : null;
  const descriptor = raw as {
    __exactMotionKind?: unknown;
    placeholder?: unknown;
  } | null;
  if (
    !descriptor ||
    descriptor.__exactMotionKind !== MOTION_DRAG_PRESENTATION_KIND
  ) {
    throw new Error(
      `[motion] dragPresentation "${record.name}" did not resolve to a descriptor`,
    );
  }
  return Object.freeze({
    schemaVersion: 1,
    claim: record.claim,
    placeholder: record.placeholder,
  });
}

/**
 * Resolve the stable SharedValue handles feeding a presentation expression.
 * The compiler-emitted graph expands a bare derived name (opacity=fade) back
 * to its SharedValue roots, so the runtime does not need a reactive tree
 * effect or a per-frame component render to discover dependencies.
 */
function findMotionReadsInExpr(
  expr: Expr,
  scope: Scope,
  component: ComponentIR,
): ContractMotionReadable[] {
  const motion = component.motion;
  if (!motion) return [];
  const sharedNames = new Set(motion.sharedValues.map((value) => value.name));
  const deriveByName = new Map(
    motion.derives.map((derive) => [derive.name, derive]),
  );
  const roots = new Set<string>();
  const expandedDerives = new Set<string>();
  const expandDerive = (name: string): void => {
    if (expandedDerives.has(name)) return;
    expandedDerives.add(name);
    const derive = deriveByName.get(name);
    derive?.dependencies.forEach((dependency) => {
      if (sharedNames.has(dependency)) roots.add(dependency);
      else if (deriveByName.has(dependency)) expandDerive(dependency);
    });
  };
  const visit = (node: Expr): void => {
    if (
      node.kind === "member" &&
      node.property === "value" &&
      node.object.kind === "ident" &&
      sharedNames.has(node.object.name)
    ) {
      roots.add(node.object.name);
    }
    if (node.kind === "ident" && deriveByName.has(node.name))
      expandDerive(node.name);
    visitExprChildrenForMotion(node, visit);
  };
  visit(expr);

  const values: ContractMotionReadable[] = [];
  for (const name of roots) {
    const binding = scope.lookup(name);
    if (!binding) continue;
    const raw =
      binding.kind === "value" || binding.kind === "local"
        ? binding.value
        : untrack(() => binding.get());
    const readable = toMotionReadable(raw);
    if (readable && !values.includes(readable)) values.push(readable);
  }
  return values;
}

function visitExprChildrenForMotion(
  expr: Expr,
  visit: (expr: Expr) => void,
): void {
  switch (expr.kind) {
    case "relation":
      expr.args.forEach(visit);
      if (expr.fallback) visit(expr.fallback);
      return;
    case "member":
      visit(expr.object);
      return;
    case "index":
      visit(expr.object);
      visit(expr.index);
      return;
    case "call":
      visit(expr.callee);
      expr.args.forEach(visit);
      return;
    case "unary":
      visit(expr.operand);
      return;
    case "binary":
      visit(expr.left);
      visit(expr.right);
      return;
    case "ternary":
      visit(expr.test);
      visit(expr.consequent);
      visit(expr.alternate);
      return;
    case "template":
      expr.parts.forEach((part) => {
        if (part.kind === "expr") visit(part.expr);
      });
      return;
    case "array":
      expr.items.forEach((item) =>
        visit(isExprSpread(item) ? item.value : item),
      );
      return;
    case "object":
      expr.entries.forEach((entry) =>
        visit(isExprSpread(entry) ? entry.value : entry.value),
      );
      return;
    case "arrow":
      visit(expr.body);
      return;
    default:
      return;
  }
}

function composeMotionPresentationValue(
  styleProp: string,
  staticValue: unknown,
  motionValue: unknown,
): unknown {
  if (styleProp !== "transform" || staticValue == null || staticValue === "")
    return motionValue;
  if (typeof staticValue === "string" && typeof motionValue === "string") {
    return `${staticValue} ${motionValue}`;
  }
  if (Array.isArray(staticValue) && Array.isArray(motionValue)) {
    return [...staticValue, ...motionValue];
  }
  // Mixed representations cannot be safely guessed. The authored Motion
  // value remains the presentation override; native M2 will carry the two
  // typed channels separately and compose them in the presenter.
  return motionValue;
}

function sameMotionSpan(
  left: Span | undefined,
  right: Span | undefined,
): boolean {
  return Boolean(
    left &&
    right &&
    left.line === right.line &&
    left.col === right.col &&
    left.offset === right.offset &&
    left.len === right.len,
  );
}

function scopeMotionReadable(
  scope: Scope,
  name: string,
): ContractMotionReadable {
  const binding = scope.lookup(name);
  const raw =
    binding?.kind === "value" || binding?.kind === "local"
      ? binding.value
      : binding
        ? untrack(() => binding.get())
        : undefined;
  const readable = toMotionReadable(raw);
  if (!readable)
    throw new Error(
      `[motion] graph capture "${name}" is not a live Motion value`,
    );
  return readable;
}

/**
 * The compiler binding for one sink site. Matched on the AUTHORED attr
 * (`radius`, `grow`), not the lowered style prop (`borderRadius`,
 * `flexGrow`) — those coincide only for transform/opacity.
 */
function contractMotionBindingForSink(
  component: ComponentIR,
  expr: Expr,
  attr: string,
): ContractMotionBindingIR | null {
  if (!CONTRACT_MOTION_SINK_ATTRS.has(attr)) return null;
  const matches = (component.motion?.bindings ?? []).filter(
    (binding) =>
      binding.attr === attr && sameMotionSpan(binding.span, expr.span),
  );
  if (matches.length > 1) {
    throw new Error(
      `[motion] ${attr} sink has ambiguous compiler graph metadata`,
    );
  }
  return matches[0] ?? null;
}

function createContractMotionSinkNode(
  binding: ContractMotionBindingIR,
  expr: Expr,
  scope: Scope,
  component: CompiledComponent,
  instance: ComponentInstance,
  paramValues?: ReadonlyMap<string, number>,
): HostMotionSharedValue | null {
  const motionGraph = component.ir.motion;
  if (!motionGraph || !binding.artifact) return null;
  const deriveByName = new Map(
    motionGraph.derives.map((derive) => [derive.name, derive]),
  );
  const nodes = new Map<string, HostMotionSharedValue>();
  const capture = (name: string): HostMotionSharedValue | number => {
    // Commit-frozen scalar parameters (RFC 0368) ride the artifact as plain
    // finite numbers; the host lowers them as `scalar` captures.
    const paramValue = paramValues?.get(name);
    if (paramValue !== undefined) return paramValue;
    if (deriveByName.has(name)) return derive(name);
    return scopeMotionReadable(scope, name) as HostMotionSharedValue;
  };
  const ownerIdentity = [
    component.file.sourcePath ?? "<inline-contract>",
    component.ir.name,
    ...instance.logicalInstancePath,
  ].join("/");
  const paramIdentity =
    paramValues && paramValues.size > 0
      ? `:params:${[...paramValues.entries()].map(([name, value]) => `${name}=${value}`).join(",")}`
      : "";
  const derive = (name: string): HostMotionSharedValue => {
    const existing = nodes.get(name);
    if (existing) return existing;
    const record = deriveByName.get(name);
    if (!record?.artifact) {
      throw new Error(
        `[motion] derive "${name}" has no executable compiler artifact`,
      );
    }
    const runtimeArtifact: HostMotionRuntimeWorkletArtifact = Object.freeze({
      ...record.artifact,
      captures: Object.freeze(record.artifact.captureNames.map(capture)),
    });
    const node = createHostMotionDerivedNode(
      {
        identity: `contract:${ownerIdentity}:derive:${name}:${record.workletId}`,
        generation: 1,
        role: "derive",
        artifact: runtimeArtifact,
      },
      () => {
        const slot = scope.lookup(name);
        const value =
          slot?.kind === "value" || slot?.kind === "local"
            ? slot.value
            : slot
              ? untrack(() => slot.get())
              : undefined;
        if (typeof value !== "number" || !Number.isFinite(value)) {
          throw new TypeError(
            `[motion] derive "${name}" produced a non-finite scalar`,
          );
        }
        return value;
      },
    );
    nodes.set(name, node);
    return node;
  };
  const scalarExpr =
    binding.attr === "transform" && expr.kind === "call"
      ? (expr.args[0] ?? expr)
      : expr;
  const runtimeArtifact: HostMotionRuntimeWorkletArtifact = Object.freeze({
    ...binding.artifact,
    captures: Object.freeze(binding.artifact.captureNames.map(capture)),
  });
  return createHostMotionDerivedNode(
    {
      identity: `contract:${ownerIdentity}:sink:${binding.path}:${binding.property}:${binding.workletId}${paramIdentity}`,
      generation: 1,
      role: "sink",
      artifact: runtimeArtifact,
    },
    () => {
      const value = untrack(() =>
        evalRuntimeExpr(scalarExpr, scope, VIEW_EVAL),
      );
      if (typeof value !== "number" || !Number.isFinite(value)) {
        throw new TypeError(
          `[motion] ${binding.property} sink produced a non-finite scalar`,
        );
      }
      return value;
    },
  );
}

/**
 * Narrow a compiler binding's property to the whole-root presentation
 * transport. Layout-island bindings never reach these call sites (they return
 * early), so an unexpected one is a compiler/runtime mismatch, not an author
 * error.
 */
function presentationBindingProperty(
  binding: ContractMotionBindingIR,
): HostMotionBindingProperty {
  if (binding.sinkClass === "layoutIsland") {
    throw new Error(
      `[motion] layout sink ${binding.attr}= reached the presentation binding transport`,
    );
  }
  return binding.property as HostMotionBindingProperty;
}

/**
 * Register one `layoutIsland`-class sink (LLP 0313 descriptor kind 14,
 * LLP 0417 §5) for the interpreter. The shared resolve/register/degrade flow
 * lives in `motion-layout-island-install.ts` so this path and the AOT
 * production program cannot drift (LLP 0417 §5 requires identical behavior).
 * Returns null when the edge was not admitted; the sink then degrades to the
 * ordinary reactive style write instead of taking the component down.
 */
function registerContractLayoutIslandSink(
  element: ElementNode,
  binding: ContractMotionBindingIR,
  dependencies: readonly ContractMotionReadable[],
): (() => void) | null {
  const source = dependencies[0];
  if (dependencies.length !== 1 || !source) return null;
  return installContractLayoutIslandEdge(
    element,
    binding.attr,
    binding.property as HostMotionLayoutIslandProperty,
    () => source,
    binding.island?.closure ?? 'fixedEnvelope',
  );
}

function wireMotionStyleSinks(
  sinks: Array<{
    attr: string;
    styleProp: string;
    expr: Expr;
    dependencies: ContractMotionReadable[];
    staticValue: unknown;
  }>,
  element: ElementNode,
  scope: Scope,
  component: CompiledComponent,
  instance: ComponentInstance,
  ctx: RuntimeContext,
  locus: ContractErrorLocus | null,
  applyFallbackStyle: (styleProp: string, value: unknown) => void,
): void {
  const owner = getOwner();
  sinks.forEach((sink) => {
    const graphBinding = contractMotionBindingForSink(
      component.ir,
      sink.expr,
      sink.attr,
    );
    const isLayoutIslandSink = graphBinding?.sinkClass === "layoutIsland";
    const applySink = (): void => {
      const evaluated = untrack(() =>
        locus
          ? runWithContractErrorLocus(locus, () =>
              evalRuntimeExpr(sink.expr, scope, VIEW_EVAL),
            )
          : evalRuntimeExpr(sink.expr, scope, VIEW_EVAL),
      );
      const value = composeMotionPresentationValue(
        sink.styleProp,
        sink.staticValue,
        evaluated,
      );
      if (!applyHostChannelStyle(element, sink.styleProp, value)) {
        applyFallbackStyle(sink.styleProp, value);
      }
    };
    // LLP 0089 requires the compiler-authored finite value in the unpublished
    // candidate. Host motion bindings and subscriptions publish only after
    // hydration commit.
    applySink();
    registerHydrationActivation(ctx, () => runWithOwner(owner, () => {
      if (isLayoutIslandSink && graphBinding) {
        // A layout sink has one bare SharedValue dependency by construction
        // (the compiler enforces it), so there is no derived graph node and no
        // motion.param path here — just the island edge, re-established on
        // every activation and disposed with the owner.
        const disposeIsland = registerContractLayoutIslandSink(
          element,
          graphBinding,
          sink.dependencies,
        );
        if (disposeIsland) owner?.register(disposeIsland);
        if (contractLayoutIslandArenaOwnsLayout(disposeIsland)) {
          // The island arena owns this node's layout per frame; an app-JS
          // style write would fight it and re-enter the transactional lane.
          return;
        }
        // Web (and any host without an arena) relayouts same-frame from the
        // ordinary per-frame channel style write.
        sink.dependencies.forEach((dependency) =>
          owner?.register(dependency.subscribe(applySink)),
        );
        return;
      }
      if (graphBinding?.params?.length) {
      // Commit-frozen per-instance parameters (RFC 0368): evaluate each
      // param in transactional scope inside a tracked effect, freeze the
      // values into a fresh graph node, and re-freeze whenever they change
      // (keyed reorder updates the each-row index signal in place). This is
      // transactional-lane work — it runs per commit, never per frame.
      const params = graphBinding.params;
      let disposeRegistration: (() => void) | null = null;
      ownedEffect(() => {
        const paramValues = new Map<string, number>();
        for (const param of params) {
          const raw = locus
            ? runWithContractErrorLocus(locus, () =>
                evalRuntimeExpr(param.expr, scope, VIEW_EVAL),
              )
            : evalRuntimeExpr(param.expr, scope, VIEW_EVAL);
          const numeric =
            typeof raw === "number" && Number.isFinite(raw)
              ? raw
              : typeof raw === "boolean"
                ? raw
                  ? 1
                  : 0
                : null;
          if (numeric === null) {
            console.warn(
              `[motion] param "${param.name}" on ${sink.styleProp} produced a non-finite scalar; freezing 0`,
            );
          }
          paramValues.set(param.name, numeric ?? 0);
        }
        untrack(() => {
          disposeRegistration?.();
          disposeRegistration = null;
          const source = createContractMotionSinkNode(
            graphBinding,
            sink.expr,
            scope,
            component,
            instance,
            paramValues,
          );
          if (source) {
            disposeRegistration = registerHostMotionDerivedBinding(
              element,
              presentationBindingProperty(graphBinding),
              source,
            );
          }
          applySink();
        });
      });
      owner?.register(() => {
        disposeRegistration?.();
        disposeRegistration = null;
      });
      if (hasNativeMotionProtocolEnvironment()) {
        // Native reads graph slots during MotionClock worklet/binding
        // phases; app JS must not subscribe or evaluate this sink per frame.
        return;
      }
      sink.dependencies.forEach((dependency) =>
        owner?.register(dependency.subscribe(applySink)),
      );
        return;
      }
      const graphSource = graphBinding
        ? createContractMotionSinkNode(
            graphBinding,
            sink.expr,
            scope,
            component,
            instance,
          )
        : null;
      if (graphBinding && graphSource) {
        owner?.register(
          registerHostMotionDerivedBinding(
            element,
            presentationBindingProperty(graphBinding),
            graphSource,
          ),
        );
      } else {
        const directProperty = directHostMotionProperty(
          sink.styleProp,
          sink.expr,
        );
        if (directProperty && sink.dependencies.length === 1) {
          owner?.register(
            registerHostMotionBinding(
              element,
              directProperty,
              sink.dependencies[0]!,
            ),
          );
        }
      }
      if (graphSource && hasNativeMotionProtocolEnvironment()) {
        // Native reads graph slots during MotionClock worklet/binding phases;
        // app JS must not subscribe or evaluate this sink per frame.
        return;
      }
      sink.dependencies.forEach((dependency) =>
        owner?.register(dependency.subscribe(applySink)),
      );
    }), instance.effectScope);
  });
}

/**
 * Wire channel style sinks for one element: per coalesced channel frame,
 * evaluate the sink expression (channel getters + literals — cheap by
 * analyzer rule) and write it through the host channel-apply seam. When no
 * host applier exists (native pre-0099, bare tests), fall back to an
 * ordinary coalesced host-ops prop update — correct semantics, slower
 * path, still at most once per frame.
 */
function wireChannelStyleSinks(
  sinks: Array<{
    styleProp: string;
    expr: Expr;
    channel: ContractValueChannel;
  }>,
  element: ElementNode,
  scope: Scope,
  ctx: RuntimeContext,
  locus: ContractErrorLocus | null,
  applyFallbackStyle: (styleProp: string, value: unknown) => void,
): void {
  const owner = getOwner();
  sinks.forEach((sink) => {
    const applySink = (): void => {
      const value = untrack(() =>
        locus
          ? runWithContractErrorLocus(locus, () =>
              evalRuntimeExpr(sink.expr, scope, VIEW_EVAL),
            )
          : evalRuntimeExpr(sink.expr, scope, VIEW_EVAL),
      );
      if (!applyHostChannelStyle(element, sink.styleProp, value)) {
        applyFallbackStyle(sink.styleProp, value);
      }
    };
    if (sink.channel.hasSample) {
      applySink();
    }
    registerHydrationActivation(ctx, () => {
      const unsubscribe = sink.channel.subscribe(() => applySink());
      owner?.register(unsubscribe);
    });
  });
}

/** Normalize whatever the host delivered into a channel envelope. */
function toChannelEnvelope(
  payload: unknown,
  phase: string,
): ChannelHostEnvelope | null {
  if (payload && typeof payload === "object") {
    const record = payload as Record<string, unknown>;
    if (record.sample && typeof record.sample === "object") {
      return record as unknown as ChannelHostEnvelope;
    }
    // Degraded delivery (a synthetic caller passing bare coordinates).
    if (typeof record.x === "number" && typeof record.y === "number") {
      return {
        sample: {
          x: record.x,
          y: record.y,
          pointerId:
            typeof record.pointerId === "number" ? record.pointerId : -1,
          pointerType:
            typeof record.pointerType === "string"
              ? record.pointerType
              : "synthetic",
          buttons: typeof record.buttons === "number" ? record.buttons : 0,
          pressure: typeof record.pressure === "number" ? record.pressure : 0,
        },
        phase,
      };
    }
  }
  return null;
}

/**
 * Wire one pointer event attr. Channel targets write into the channel
 * (frame-coalesced for continuous events, immediate for edges — §3.4);
 * edge action calls carrying `sample(...)` first apply the edge payload to
 * the sampled channels non-coalesced, then invoke the action, so the seal
 * observes the final sample (§3.4 atomic sampling).
 */
function makePointerEventHandler(
  event: string,
  handlerExpr: Expr,
  scope: Scope,
  locus: ContractErrorLocus | null,
): ((payload?: unknown) => void) | null {
  const channel = resolveChannelEventTarget(handlerExpr, scope);
  if (channel) {
    const immediate = CONTRACT_POINTER_EDGE_EVENTS.has(event);
    return (payload?: unknown) => {
      const envelope = toChannelEnvelope(payload, event);
      if (envelope) {
        channel.writeFromHost(envelope, { immediate });
      }
    };
  }
  if (CONTRACT_POINTER_CONTINUOUS_EVENTS.has(event)) {
    // Continuous events bind only to channels (analyzer-enforced; runtime
    // degrades to a no-op with a warning rather than running an action at
    // input cadence).
    console.warn(
      `[contract] ${event}= must bind a value channel; transactional handlers are not run at pointer cadence (LLP 0281 §3.1)`,
    );
    return () => {};
  }
  const sampled = sampledChannelsInCall(handlerExpr, scope);
  const invoke = makeHandler(handlerExpr, scope, locus ?? undefined, undefined);
  if (sampled.length === 0) {
    return invoke;
  }
  return (payload?: unknown) => {
    const envelope = toChannelEnvelope(payload, event);
    if (envelope) {
      for (const sampledChannel of sampled) {
        sampledChannel.writeFromHost(envelope, { immediate: true });
      }
    }
    invoke(payload);
  };
}

/**
 * LLP 0281 §3.1 (ENG-22525) — mount a rated publish line:
 * `publish <channel> -> <descriptor> rate=<Hz> [payload={...}]`.
 *
 * Renders nothing. Resolves the channel-set handle from the line's channel
 * expression root (the analyzer restricts the shape to `cursors` /
 * `cursors.self`), the descriptor callable from scope, and the provider
 * budget facts from the resolved import descriptor, then attaches a rated
 * publisher through the set's protocol hook (`__attachPublisher` — the
 * implementation lives behind `@exact/contract/channels`; a set without
 * the hook degrades to a warning). The publisher is disposed by the owner
 * (unmount / reset-based HMR) and by the set's own dispose — both paths
 * are idempotent.
 */
function mountPublish(
  node: Extract<ViewNodeIR, { kind: "publish" }>,
  env: MountEnv,
): Mounted {
  let rootExpr: Expr = node.channel;
  while (rootExpr.kind === "member") rootExpr = rootExpr.object;
  const imported = env.component.file.imports?.[node.descriptor]?.descriptor;
  const budget = imported?.kind === "publish"
    ? imported.budget
    : imported?.kind === "mutation"
      ? imported.publishBudget
      : null;
  return mountContractPublish([
    (scope, options) => evalRuntimeExpr(rootExpr, scope, options),
    node.descriptor,
    node.rate ?? null,
    node.heartbeat ?? null,
    budget ?? null,
    node.payload
      ? (scope) => evalRuntimeExpr(node.payload!, scope)
      : null,
    node.payload ? printExpression(node.payload) : null,
  ], env);
}

function keyFromPayload(payload: unknown): string | undefined {
  if (!payload || typeof payload !== "object") {
    return undefined;
  }
  const record = payload as { key?: unknown; nativeEvent?: { key?: unknown } };
  if (typeof record.key === "string") {
    return record.key;
  }
  return typeof record.nativeEvent?.key === "string"
    ? record.nativeEvent.key
    : undefined;
}

function accessibilityActionNameFromPayload(payload: unknown): string | undefined {
  if (!payload || typeof payload !== "object") {
    return undefined;
  }
  const record = payload as {
    actionName?: unknown;
    nativeEvent?: { actionName?: unknown };
  };
  if (typeof record.actionName === "string") {
    return record.actionName;
  }
  return typeof record.nativeEvent?.actionName === "string"
    ? record.nativeEvent.actionName
    : undefined;
}

// @ref LLP 0292 §Per-node keydown on native — the element-scoped keydown attr
// is only reliably delivered by the web dom-mirror (focus-scoped DOM listener
// + granted tabindex="-1"). Native hosts have no per-node focus model: the
// presenters capture hardware keys app-wide and heuristically dispatch to the
// deepest mounted node with a keydown handler, only while the presenter's own
// capture view is first responder (other responders routinely preempt it),
// and native text inputs forward only Enter. Warn once (ENG-22597) so a
// keydown= consumer that appears dead on native is a diagnosis, not a
// mystery. `submit`/`dismiss` also lower to onKeyDown but have working native
// paths, so only the explicit keydown attr warns.
let warnedNativeKeydownAttr = false;
function warnNativeKeydownAttrOnce(tag: string): void {
  if (warnedNativeKeydownAttr || typeof document !== "undefined") {
    return;
  }
  warnedNativeKeydownAttr = true;
  console.warn(
    `[contract] keydown= (here on <${tag}>) has no reliable per-node backing on native hosts: ` +
      "there is no native focus model yet, so hardware keys are captured app-wide and " +
      "heuristically delivered to the deepest mounted keydown consumer, and native text " +
      "inputs deliver only Enter. For app-level keys, bind through the keyboard capability " +
      '(use keyboard from "@exact/contract/runtime"), which has native macOS/iOS backing. ' +
      "See LLP 0292 (ENG-22597).",
  );
}

function makeLinkPressHandler(
  hrefExpr: Expr | undefined,
  scope: Scope,
): ((payload?: unknown) => void) | undefined {
  if (!hrefExpr) {
    return undefined;
  }
  const nativeLinkHandlerAtRender = (
    globalThis as typeof globalThis & {
      __exactHandleLinkHref?: (href: string) => void | Promise<void>;
    }
  ).__exactHandleLinkHref;
  const initialValue = evalRuntimeExpr(hrefExpr, scope, VIEW_EVAL);
  const initialHref =
    typeof initialValue === "string"
      ? initialValue
      : initialValue == null
        ? ""
        : String(initialValue);
  if (
    initialHref.startsWith("#") &&
    typeof nativeLinkHandlerAtRender !== "function"
  ) {
    return undefined;
  }

  return () => {
    const value = evalRuntimeExpr(hrefExpr, scope, VIEW_EVAL);
    const href =
      typeof value === "string" ? value : value == null ? "" : String(value);
    if (href.length === 0) {
      return;
    }

    const nativeLinkHandler = (
      globalThis as typeof globalThis & {
        __exactHandleLinkHref?: (href: string) => void | Promise<void>;
      }
    ).__exactHandleLinkHref;

    if (href.startsWith("#") && typeof nativeLinkHandler !== "function") {
      return;
    }

    if (typeof nativeLinkHandler === "function") {
      Promise.resolve(nativeLinkHandler(href)).catch((error: unknown) => {
        console.error("[contract] link press failed", error);
      });
    }
  };
}

// ---------------------------------------------------------------------------
// Mounted units
// ---------------------------------------------------------------------------

export interface Mounted {
  /** Current top-level host nodes, in document order. */
  hostNodes(): HostNode[];
  /** Disposes effects and removes host nodes from the tree. */
  dispose(): void;
}

export type AnchorFn = () => HostNode | null;

/**
 * Renders the caller's children template into the host position where the
 * child component's view places its `children` slot.
 */
type ChildrenSlot = (parent: HostParent, anchor: AnchorFn | null) => Mounted;

export interface MountEnv {
  instance: ComponentInstance;
  scope: Scope;
  component: CompiledComponent;
  ctx: RuntimeContext;
  childrenSlot: ChildrenSlot | null;
  /** True only while mounting the component root view node. */
  isRootView: boolean;
  /** Item-subtree context for LLP 0363's web `loading=auto` default. */
  inRepetitionScope: boolean;
  /** Nearest repeated-item ordinal for LLP 0363's first-viewport eager refinement. */
  repetitionIndex: number | null;
  /** Structural ids for this component's view nodes (LLP 0166 §4.7). */
  ids: Map<ViewNodeIR, string>;
  /** `each`-key chain for runtimeNodeKey derivation ('' outside regions). */
  keyChain: string;
  /** Collision-free typed key segments for replay/effect logical identity. */
  logicalKeyPath: readonly string[];
  /** Component-call prefix for unique W3 hydration node identities. */
  hydrationPrefix: string;
  /** Keyed-region chain used only for W3 hydration identities. */
  hydrationKeyChain: string;
  /** Logical component-local dismiss ancestor across elements/components/portals. */
  dismissLayerParentId?: string;
}

function liveNodeRegistrationIdentity(env: MountEnv): {
  runtimeId: string;
  rootRegistrationId: string;
  componentInstanceId: string;
  keyChain: string;
  occurrencePath: readonly string[];
} {
  return {
    runtimeId: env.ctx.contractRuntime.id,
    rootRegistrationId: env.ctx.runtimeRoot.id,
    componentInstanceId:
      env.instance.runtimeInstanceId ?? `${env.component.name}:unmounted`,
    keyChain: env.keyChain,
    occurrencePath: env.logicalKeyPath,
  };
}

// LLP 0398 P1 — the merge-seed subject: the element's structural id plus
// the runtime-instance tuple (both available in the mount env), so a merge
// record is addressable per live occurrence.
function mergeCaptureSubjectFor(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  env: MountEnv,
  mergePath: "element" | "collection",
): MergeCaptureSubjectInit {
  const identity = liveNodeRegistrationIdentity(env);
  return {
    runtimeId: identity.runtimeId,
    rootRegistrationId: identity.rootRegistrationId,
    componentInstanceId: identity.componentInstanceId,
    occurrencePath: identity.occurrencePath,
    rootId: env.ctx.rootId,
    structuralId: env.ids.get(node) ?? null,
    componentName: env.component.name,
    ...(env.component.file.sourcePath !== undefined
      ? { sourcePath: env.component.file.sourcePath }
      : {}),
    tag: node.tag,
    mergePath,
  };
}

const CONTRACT_AUTO_EAGER_REPETITION_COUNT = 12;

function lowerContractImageLoading(
  value: unknown,
  inRepetitionScope: boolean,
  repetitionIndex: number | null,
): "eager" | "lazy" | undefined {
  if (value === "lazy") return "lazy";
  if (value === "eager") return "eager";
  if (value === undefined || value === "auto") {
    if (!inRepetitionScope) return undefined;
    return repetitionIndex !== null &&
      repetitionIndex < CONTRACT_AUTO_EAGER_REPETITION_COUNT
      ? undefined
      : "lazy";
  }
  return undefined;
}

function routePayloadKeyFor(env: MountEnv): string | undefined {
  return env.ctx.routePayloadCapture && env.keyChain.length > 0
    ? env.keyChain.slice(1)
    : undefined;
}

function routePayloadProvenanceFor(env: MountEnv, node: ViewNodeIR) {
  if (!env.ctx.routePayloadCapture) return undefined;
  return Object.freeze({
    component: env.component.name,
    ...(env.component.file.sourcePath
      ? { source: env.component.file.sourcePath }
      : {}),
    span: Object.freeze({
      line: node.span.line,
      col: node.span.col,
      offset: node.span.offset,
      len: node.span.len,
    }),
  });
}

function logicalPathSegment(kind: "call" | "key", value: string): string {
  return `${kind}:${value.length}:${value}`;
}

/**
 * Authored locus for a view node (ENG-22443): every view-node span is
 * required IR, so mount- and update-time errors report the authored line of
 * the node whose binding failed.
 */
function viewNodeLocus(
  env: MountEnv,
  node: ViewNodeIR,
  region?: string,
): ContractErrorLocus {
  return {
    component: env.component.name,
    sourcePath: env.component.file.sourcePath,
    region:
      region ??
      `view <${node.kind === "element" ? node.tag : node.kind === "component" ? node.name : node.kind}>`,
    span: node.span,
  };
}

function viewReactiveOptions(
  env: MountEnv,
  node: ViewNodeIR,
  region: string,
  expression?: string,
): ReactiveNodeOptions | undefined {
  if (!isReactiveIntrospectionEnabled()) {
    return undefined;
  }
  const structuralId =
    env.ids.get(node) ?? `${node.kind}:${node.span.line}:${node.span.col}`;
  return {
    label: `${env.component.name}.view.${structuralId}.${region}`,
    source: {
      component: env.component.name,
      sourcePath: env.component.file.sourcePath,
      region,
      ...(expression ? { expression } : {}),
      span: node.span,
    },
  };
}

function hydrationNodeIdFor(env: MountEnv, structuralId: string): string {
  return contractHydrationNodeId({
    prefix: env.hydrationPrefix,
    structuralId,
    keyChain: env.hydrationKeyChain,
  });
}

function applyHydrationElementProps(
  env: MountEnv,
  structuralId: string | undefined,
  props: Record<string, unknown>,
): string | undefined {
  if (!env.ctx.hydration?.capture || !structuralId) {
    return undefined;
  }
  const nodeId = hydrationNodeIdFor(env, structuralId);
  props["data-exact-hydration-id"] = nodeId;
  props["data-exact-structural-id"] = structuralId;
  if (env.component.file.sourceVersion) {
    props["data-exact-source-version"] = env.component.file.sourceVersion;
  }
  return nodeId;
}

function recordHydrationElement(
  env: MountEnv,
  element: ElementNode,
  structuralId: string | undefined,
  nodeId: string | undefined,
): void {
  if (!env.ctx.hydration?.capture || !structuralId || !nodeId) {
    return;
  }
  env.ctx.hydration.capture.recordNode({
    host: element,
    nodeId,
    structuralId,
    sourcePath: env.component.file.sourcePath,
    sourceVersion: env.component.file.sourceVersion,
    componentName: env.component.name,
    kind: "element",
  });
}

function recordHydrationHandlers(
  env: MountEnv,
  element: ElementNode,
  events: Record<string, Expr>,
  structuralId: string | undefined,
  nodeId: string | undefined,
): void {
  if (!structuralId || !nodeId) {
    return;
  }
  const handlers = Object.entries(events).flatMap(([event, handlerExpr]) => {
    const actionId = actionNameFromExpr(handlerExpr);
    return actionId ? [{ event, actionId }] : [];
  });
  if (handlers.length > 0) {
    (
      element as ElementNode & {
        __exactHydrationHandlers?: readonly {
          readonly event: string;
          readonly actionId: string;
        }[];
      }
    ).__exactHydrationHandlers = Object.freeze(
      handlers.map((handler) => Object.freeze({ ...handler })),
    );
  }
  const capture = env.ctx.hydration?.capture;
  handlers.forEach(({ event, actionId }) =>
    capture?.recordHandler({
      nodeId,
      structuralId,
      event: event as ContractHydrationEvent,
      actionId,
    }));
}

function insertNode(
  parent: HostParent,
  node: HostNode,
  anchor: HostNode | null,
): void {
  if (anchor) {
    insertBefore(parent, node, anchor);
  } else {
    appendChild(parent, node);
  }
}

/**
 * Mounts sibling view nodes into `parent`. `anchor` resolves the host node
 * the whole list must stay in front of (null appends at the end) — this is
 * how regions insert into the middle of a static parent.
 */
export function mountViewNodes(
  nodes: readonly ViewNodeIR[],
  parent: HostParent,
  anchor: AnchorFn | null,
  env: MountEnv,
): Mounted {
  const slots: Mounted[] = [];
  const descendantEnv = env.isRootView && nodes.length !== 1
    ? { ...env, isRootView: false }
    : env;

  const anchorFor =
    (index: number): AnchorFn =>
    () => {
      for (let i = index + 1; i < slots.length; i += 1) {
        const nodesAfter = slots[i].hostNodes();
        if (nodesAfter.length > 0) {
          return nodesAfter[0];
        }
      }
      return anchor ? anchor() : null;
    };

  nodes.forEach((node, index) => {
    const nodeEnv =
      env.isRootView && nodes.length === 1 && index === 0
        ? env
        : descendantEnv;
    // ENG-22443: mount-time failures carry the failing node's authored span
    // even when no inner expression span was attached.
    slots.push(
      runWithContractErrorLocus(viewNodeLocus(nodeEnv, node), () =>
        mountViewNode(node, parent, anchorFor(index), nodeEnv),
      ),
    );
  });

  return {
    hostNodes(): HostNode[] {
      return slots.flatMap((slot) => slot.hostNodes());
    },
    dispose(): void {
      for (const slot of slots) {
        slot.dispose();
      }
      slots.length = 0;
    },
  };
}

function mountViewNode(
  node: ViewNodeIR,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  const compiled = getContractAotViewClosure(node);
  if (compiled) return compiled(node, parent, anchor, env);
  if (CONTRACT_VIEW_PRODUCTION) {
    throw new Error(
      `[contract] production artifact omitted the AOT view closure for node kind "${node.kind}"`,
    );
  }
  switch (node.kind) {
    case "element":
      return mountElement(node, parent, anchor, env);
    case "pager":
      return mountPager(node, parent, anchor, env);
    case "graphics":
      return mountGraphics(node, parent, anchor, env);
    case "text":
      return mountText(node, parent, anchor, env);
    case "nothing":
      return mountContractNothing();
    case "hole":
      return mountContractHole(node.label, parent, anchor);
    case "when":
      return mountWhen(node, parent, anchor, env);
    case "match":
      return mountMatch(node, parent, anchor, env);
    case "match-size":
      return mountMatchSize(node, parent, anchor, env);
    case "each":
      return mountEach(node, parent, anchor, env);
    case "resource":
    case "async":
      return mountResourceRegion(node, parent, anchor, env);
    case "boundary":
      return mountBoundary(node, parent, anchor, env);
    case "component":
      return mountComponent(node, parent, anchor, env);
    case "publish":
      return mountPublish(node, env);
    case "children":
      return mountContractChildren(parent, anchor, env);
    case "snippet-call":
      return mountSnippetCall(node, parent, anchor, env);
  }
}

function mountSnippetCall(
  node: Extract<ViewNodeIR, { kind: "snippet-call" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  const snippet = env.component.ir.snippets.find(
    (candidate) => candidate.name === node.name,
  );
  if (!snippet) throw new Error(`[contract] unknown snippet "${node.name}"`);
  return mountContractSnippet([
    node.name,
    snippet.params,
    node.args.map((arg) =>
      (scope, options) => evalRuntimeExpr(arg, scope, options)),
  ], snippet.body, parent, anchor, env, mountViewNodes);
}

export const contractAotViewRuntime = Object.freeze({
  element: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountElement(node as Extract<ViewNodeIR, { kind: "element" }>, parent, anchor, env),
  pager: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountPager(node as Extract<ViewNodeIR, { kind: "pager" }>, parent, anchor, env),
  graphics: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountGraphics(node as Extract<ViewNodeIR, { kind: "graphics" }>, parent, anchor, env),
  when: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountWhen(node as Extract<ViewNodeIR, { kind: "when" }>, parent, anchor, env),
  match: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountMatch(node as Extract<ViewNodeIR, { kind: "match" }>, parent, anchor, env),
  "match-size": (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountMatchSize(node as Extract<ViewNodeIR, { kind: "match-size" }>, parent, anchor, env),
  each: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountEach(node as Extract<ViewNodeIR, { kind: "each" }>, parent, anchor, env),
  resource: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountResourceRegion(node as Extract<ViewNodeIR, { kind: "resource" | "async" }>, parent, anchor, env),
  boundary: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountBoundary(node as Extract<ViewNodeIR, { kind: "boundary" }>, parent, anchor, env),
  component: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountComponent(node as Extract<ViewNodeIR, { kind: "component" }>, parent, anchor, env),
  publish: (node: ViewNodeIR, _parent: HostParent, _anchor: AnchorFn, env: MountEnv) =>
    mountPublish(node as Extract<ViewNodeIR, { kind: "publish" }>, env),
  "snippet-call": (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountSnippetCall(node as Extract<ViewNodeIR, { kind: "snippet-call" }>, parent, anchor, env),
});

/** Exhaustive generic oracle used only while materializing synthetic
 * server-prerender artifacts. It is absent from the narrow production entry. */
export const contractBuildTimeViewRuntime = /* @__PURE__ */ Object.freeze({
  element: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountElement(node as Extract<ViewNodeIR, { kind: "element" }>, parent, anchor, env),
  pager: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountPager(node as Extract<ViewNodeIR, { kind: "pager" }>, parent, anchor, env),
  graphics: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountGraphics(node as Extract<ViewNodeIR, { kind: "graphics" }>, parent, anchor, env),
  text: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountText(node as Extract<ViewNodeIR, { kind: "text" }>, parent, anchor, env),
  nothing: () => mountContractNothing(),
  hole: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn) =>
    mountContractHole((node as Extract<ViewNodeIR, { kind: "hole" }>).label, parent, anchor),
  children: (_node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountContractChildren(parent, anchor, env),
  when: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountWhen(node as Extract<ViewNodeIR, { kind: "when" }>, parent, anchor, env),
  match: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountMatch(node as Extract<ViewNodeIR, { kind: "match" }>, parent, anchor, env),
  "match-size": (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountMatchSize(node as Extract<ViewNodeIR, { kind: "match-size" }>, parent, anchor, env),
  each: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountEach(node as Extract<ViewNodeIR, { kind: "each" }>, parent, anchor, env),
  resource: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountResourceRegion(node as Extract<ViewNodeIR, { kind: "resource" }>, parent, anchor, env),
  async: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountResourceRegion(node as Extract<ViewNodeIR, { kind: "async" }>, parent, anchor, env),
  boundary: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountBoundary(node as Extract<ViewNodeIR, { kind: "boundary" }>, parent, anchor, env),
  "snippet-call": (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountSnippetCall(node as Extract<ViewNodeIR, { kind: "snippet-call" }>, parent, anchor, env),
  publish: (node: ViewNodeIR, _parent: HostParent, _anchor: AnchorFn, env: MountEnv) =>
    mountPublish(node as Extract<ViewNodeIR, { kind: "publish" }>, env),
  component: (node: ViewNodeIR, parent: HostParent, anchor: AnchorFn, env: MountEnv) =>
    mountComponent(node as Extract<ViewNodeIR, { kind: "component" }>, parent, anchor, env),
});

function stringExpr(value: string): Expr {
  return { kind: "string", value };
}

function numberExpr(value: number): Expr {
  return { kind: "number", value };
}

/** Web P1 lowering: a framework-owned strip with explicit cell markers.
 * The DOM recognizer owns transforms and command commits; the ordinary
 * Contract action path remains the only state-changing path. */
function mountPager(
  node: Extract<ViewNodeIR, { kind: "pager" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  const turnToken = signal(0);
  const binding = registerPagerInteraction(env.instance, node, {
    onTurnToken: (token) => turnToken.set(token),
  });
  ownedEffect(
    () => {
      // Identity and ordinal are read in one effect so the ordinal diff always
      // spans the same commit that bumped the center revision (LLP 0336).
      binding.updateCenterIdentity(
        evalRuntimeExpr(node.value, env.scope, VIEW_EVAL),
        node.order
          ? evalRuntimeExpr(node.order, env.scope, VIEW_EVAL)
          : undefined,
      );
    },
    viewReactiveOptions(env, node, "pager center identity"),
  );
  const pagerScope = env.scope.child();
  pagerScope.define("__exactPagerTurnToken", {
    kind: "getter",
    get: () => turnToken.get(),
  });
  pagerScope.defineValue("__exactPagerCommit", (payload: unknown) => {
    const nativeEvent = (
      payload as {
        nativeEvent?: {
          direction?: unknown;
          turnToken?: unknown;
          bindingGeneration?: unknown;
        };
      } | null
    )?.nativeEvent;
    const direction = nativeEvent?.direction === "prev" ? "prev" : "next";
    const token =
      typeof nativeEvent?.turnToken === "number"
        ? nativeEvent.turnToken >>> 0
        : 0;
    const bindingGeneration =
      typeof nativeEvent?.bindingGeneration === "number"
        ? nativeEvent.bindingGeneration >>> 0
        : 0;
    if (token === 0 || bindingGeneration === 0) return;
    binding.commitTurn(
      direction,
      token,
      bindingGeneration,
      direction === "prev" ? "pager-prev" : "pager-next",
    );
  });
  const children: ViewNodeIR[] = node.cells.map((cell) => {
    const offset =
      cell.side === "prev" ? "-100%" : cell.side === "next" ? "100%" : "0%";
    const placement: Record<string, Expr> =
      node.axis === "horizontal"
        ? {
            left: stringExpr(offset),
            top: numberExpr(0),
            width: stringExpr("100%"),
          }
        : {
            top: stringExpr(offset),
            left: numberExpr(0),
            height: stringExpr("100%"),
          };
    const wrapper: ViewNodeIR = {
      kind: "element",
      tag: "column",
      props: {
        __exactPagerCell: stringExpr(cell.side),
        "data-exact-pager-cell": stringExpr(cell.side),
        position: stringExpr(cell.side === "current" ? "relative" : "absolute"),
        ...placement,
      },
      events: {},
      children: cell.body,
      span: cell.span,
    };
    return cell.when
      ? { kind: "when", test: cell.when, then: [wrapper], span: cell.span }
      : wrapper;
  });
  const synthetic: Extract<ViewNodeIR, { kind: "element" }> = {
    kind: "element",
    tag: node.axis === "horizontal" ? "row" : "column",
    props: {
      overflow: stringExpr("hidden"),
      position: stringExpr("relative"),
      width: stringExpr("100%"),
      ...node.props,
      __exactPagerId: stringExpr(binding.id),
      "data-exact-pager-id": stringExpr(binding.id),
      __exactPagerAxis: stringExpr(node.axis),
      "data-exact-pager-axis": stringExpr(node.axis),
      __exactPagerKeys: stringExpr(node.keys ?? ""),
      __exactPagerClaim: stringExpr(node.claim ?? ""),
      "data-exact-pager-claim": stringExpr(node.claim ?? ""),
      __exactPagerPrevWitness: stringExpr(node.prevWitness?.value ?? ""),
      __exactPagerNextWitness: stringExpr(node.nextWitness?.value ?? ""),
      __exactPagerTurnToken: { kind: "ident", name: "__exactPagerTurnToken" },
    },
    events: {
      pagercommit: { kind: "ident", name: "__exactPagerCommit" },
    },
    children,
    span: node.span,
    propSources: node.propSources,
  };
  return mountElement(synthetic, parent, anchor, { ...env, scope: pagerScope });
}

function emptyMounted(): Mounted {
  return { hostNodes: () => [], dispose: () => {} };
}

// ---------------------------------------------------------------------------
// Graphics surface (RFC 0101 SG2 / LLP 0353 §2)
// ---------------------------------------------------------------------------

/** Surface attrs consumed by the scene/backend seam, never by the host
 * element (the rest — layout, style, testId, role/label — flow through the
 * ordinary element machinery). */
const GRAPHICS_SEAM_PROPS = new Set([
  'viewBox',
  'backend',
  'gestureClaim',
  'focusPolicy',
  'agentSummary',
]);

function isWebCanvasHost(): boolean {
  return (
    typeof document !== 'undefined' &&
    typeof document.createElement === 'function' &&
    typeof (globalThis as { HTMLCanvasElement?: unknown }).HTMLCanvasElement === 'function'
  );
}

let nextGraphicsSurfaceKey = 1;
const reportedGraphicsPlaceholders = new Set<string>();
/** Private scope binding carrying the native surface's module event seam. */
const GRAPHICS_NATIVE_EVENT_BINDING = '__exactGraphicsNativeViewEvent';
/** Synthetic Contract tag for the native surface leaf, lowered to the
 * module-backed `nativeView` host tag through {@link RUNTIME_TAG_LOWERING}. */
const GRAPHICS_NATIVE_SURFACE_TAG = '__graphicsNativeSurface';

function graphicsNativeSurfaceTag(): string {
  RUNTIME_TAG_LOWERING[GRAPHICS_NATIVE_SURFACE_TAG] ??= {
    tag: graphicsSceneNativeViewTag(),
  };
  return GRAPHICS_NATIVE_SURFACE_TAG;
}

function mountGraphics(
  node: Extract<ViewNodeIR, { kind: "graphics" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  const surfaceValue = node.surface
    ? untrack(() => evalRuntimeExpr(node.surface!, env.scope, VIEW_EVAL))
    : undefined;
  const behavior = hasContractGraphicsSurfaceBrand(surfaceValue)
    ? (surfaceValue as GraphicsSurfaceBehavior)
    : undefined;
  // Fail closed on any authored surface= that does not resolve to a behavior
  // instance — including undefined, which would otherwise silently create an
  // anonymous orphan scene whose behavior.batch() returns null forever.
  // Omitting the surface attr entirely stays legal (anonymous scene).
  if (node.surface && !behavior) {
    throw new Error(
      surfaceValue === undefined
        ? `[contract] ${env.component.name}: graphics surface= evaluated to undefined — bind a graphicsSurface() behavior instance (LLP 0353 SG1 D)`
        : `[contract] ${env.component.name}: graphics surface= must bind a graphicsSurface() behavior instance (LLP 0353 SG1 D)`,
    );
  }
  const scene = behavior ? behavior.scene : createGraphicsScene();

  // backend is a mount-time platform selection (it decides which renderer
  // seam exists at all), so it is deliberately mount-frozen.
  const backendHint =
    node.props.backend !== undefined
      ? String(untrack(() => evalRuntimeExpr(node.props.backend, env.scope, VIEW_EVAL)))
      : undefined;
  const viewBoxExpr = node.props.viewBox;
  const viewBox =
    viewBoxExpr !== undefined
      ? String(untrack(() => evalRuntimeExpr(viewBoxExpr, env.scope, VIEW_EVAL)))
      : undefined;
  // LLP 0353 §2 / RFC 0101 SG2: the gesture claim is surface POLICY, so it is
  // mount-frozen exactly like the backend hint. It reaches the web host as an
  // element attr (below) that the shared element description lowers to
  // `touch-action` — the framework owns that property on a surface, because an
  // inline style written by an app is erased by the next presentation commit.
  const gestureClaim =
    node.props.gestureClaim !== undefined
      ? String(
          untrack(() => evalRuntimeExpr(node.props.gestureClaim, env.scope, VIEW_EVAL)),
        )
      : undefined;

  // LLP 0352 backend selection: platform-determined with the surface-level
  // hint. The hint's v1 value set names a WEB backend (`backend="canvas"`), so
  // it decides among web backends; a native protocol host takes the platform's
  // own scene backend (LLP 0420 §1's Apple leg). Web wins when both are
  // available — a host that owns real DOM already owns the pixels. Neither
  // available still renders the visible missing-backend placeholder with a
  // structured diagnostic (never a silent blank).
  const webBackendAvailable = backendHint === 'canvas' && isWebCanvasHost();
  const nativeBackendAvailable = !webBackendAvailable && hasGraphicsProtocolHost();
  const backendAvailable = webBackendAvailable || nativeBackendAvailable;

  const elementProps: Record<string, Expr> = {};
  for (const [name, expr] of Object.entries(node.props)) {
    if (!GRAPHICS_SEAM_PROPS.has(name)) {
      elementProps[name] = expr;
    }
  }

  const surfaceKey = `graphics:${env.component.name}:${node.span.line}:${nextGraphicsSurfaceKey++}`;
  const graphicsScope = env.scope.child();

  if (!backendAvailable) {
    const placeholderKey = `${env.component.name}:${node.span.line}`;
    if (!reportedGraphicsPlaceholders.has(placeholderKey)) {
      reportedGraphicsPlaceholders.add(placeholderKey);
      console.warn(
        `[graphics] ${placeholderKey}: no scene backend for this surface — rendering the LLP 0352 missing-backend placeholder`,
        {
          code: 'graphics_backend_missing',
          backendHint: backendHint ?? null,
          webHost: isWebCanvasHost(),
          detail:
            backendHint === undefined
              ? 'the web SVG default backend is not implemented yet; author backend="canvas" for the SG2 canvas2d path'
              : 'this platform has no scene backend yet (Apple lands with RFC 0101 Phase 2)',
        },
      );
    }
    const placeholder: Extract<ViewNodeIR, { kind: "element" }> = {
      kind: 'element',
      tag: 'column',
      props: {
        ...elementProps,
        'data-exact-graphics-placeholder': stringExpr('true'),
        borderWidth: elementProps.borderWidth ?? numberExpr(1),
        borderColor: elementProps.borderColor ?? stringExpr('rgba(127,127,127,0.35)'),
        radius: elementProps.radius ?? numberExpr(6),
        padding: elementProps.padding ?? numberExpr(12),
        justify: stringExpr('center'),
        align: stringExpr('center'),
      },
      events: node.events,
      children: [
        {
          kind: 'element',
          tag: 'text',
          props: { size: numberExpr(12), opacity: numberExpr(0.6) },
          events: {},
          children: [
            {
              kind: 'text',
              expr: {
                kind: 'string',
                value: 'graphics scene (no backend on this platform yet)',
              },
              span: node.span,
            },
          ],
          span: node.span,
        },
      ],
      span: node.span,
      propSources: node.propSources,
    };
    return mountElement(placeholder, parent, anchor, { ...env, scope: graphicsScope });
  }

  behavior?.__attachSurface(surfaceKey);
  // Mount-path exception safety (the mirror of the dispose path below): if
  // scene mounting, the viewBox effect's first eval, or the host element
  // mount throws, unwind everything acquired so far — a leaked attachment
  // makes remounting the same behavior throw "scene is already attached",
  // and leaked scene nodes turn a retry into DUPLICATE_GRAPHICS_ID refusals.
  let mountedSceneForUnwind: MountedScene | null = null;
  let viewBoxEffect: EffectHandle | null = null;
  let mountedElementForUnwind: Mounted | null = null;
  let nativeMount: ContractNativeGraphicsMount | null = null;
  try {
    const sceneContext = createSceneMountContext(scene, behavior, surfaceKey);
    const mountedScene = mountGraphicsSceneNodes(node.scene, null, env.scope, sceneContext);
    mountedSceneForUnwind = mountedScene;
    // Live objects never travel through host props: the renderer backend
    // resolves the scene by string id (the pager-binding registry pattern).
    // LLP 0420 §8's pointer/size sink rides the same record, because the web
    // leg's DOM listeners know only that id.
    const sink = graphicsSurfaceEventSink(behavior);
    const registeredEntry: RegisteredGraphicsSurface = {
      scene,
      ...(viewBox !== undefined ? { viewBox } : {}),
      ...(sink ? { events: sink } : {}),
    };
    registerGraphicsSurfaceScene(surfaceKey, registeredEntry);
    if (nativeBackendAvailable) {
      nativeMount = createContractNativeGraphicsMount({
        scene,
        sink,
        surfaceKey,
        gestureClaim,
        viewBox,
      });
    }
    // A reactive viewBox updates the registered record; the backend re-reads
    // it on every paint, so the change lands with the next scene commit (no
    // dedicated repaint trigger in SG2).
    if (viewBoxExpr !== undefined) {
      viewBoxEffect = ownedEffect(() => {
        registeredEntry.viewBox = String(evalRuntimeExpr(viewBoxExpr, env.scope, VIEW_EVAL));
      });
    }

    if (nativeMount) {
      // A function cannot be written as an IR literal, so the module event
      // seam is defined into the surface's own scope and referenced by ident —
      // the same shape the pager lowering uses for `__exactPagerCommit`. The
      // identity is stable for the surface's whole life, which is what keeps
      // an ordinary prop update from re-registering the module bridge.
      graphicsScope.defineValue(
        GRAPHICS_NATIVE_EVENT_BINDING,
        nativeMount.baseProps.onNativeViewEvent,
      );
    }
    const synthetic: Extract<ViewNodeIR, { kind: "element" }> = nativeMount
      ? {
          kind: 'element',
          tag: graphicsNativeSurfaceTag(),
          props: {
            ...elementProps,
            surfaceId: stringExpr(surfaceKey),
            backendId: stringExpr(String(nativeMount.baseProps.backendId)),
            // The authored EXPRESSION, so a state-bound viewBox reaches the
            // painter and the pointer mapping instead of freezing at mount.
            ...(viewBoxExpr !== undefined ? { viewBox: viewBoxExpr } : {}),
            ...(gestureClaim !== undefined
              ? { gestureClaim: stringExpr(gestureClaim) }
              : {}),
            onNativeViewEvent: {
              kind: 'ident',
              name: GRAPHICS_NATIVE_EVENT_BINDING,
            },
          },
          events: node.events,
          children: [],
          span: node.span,
          propSources: node.propSources,
        }
      : {
          kind: 'element',
          tag: 'stack',
          props: {
            overflow: stringExpr('hidden'),
            ...elementProps,
            'data-exact-graphics-backend': stringExpr('canvas2d'),
            'data-exact-graphics-surface-id': stringExpr(surfaceKey),
            // The authored EXPRESSION, not a mount-time snapshot of it: a
            // state-bound viewBox otherwise froze this attr at its first value
            // and the DOM advertised a viewBox the surface had stopped using.
            ...(viewBoxExpr !== undefined
              ? { 'data-exact-graphics-viewbox': viewBoxExpr }
              : {}),
            ...(gestureClaim !== undefined
              ? { 'data-exact-graphics-gesture-claim': stringExpr(gestureClaim) }
              : {}),
          },
          events: node.events,
          children: [],
          span: node.span,
          propSources: node.propSources,
        };
    const mountedElement = mountElement(synthetic, parent, anchor, { ...env, scope: graphicsScope });
    mountedElementForUnwind = mountedElement;
    // The mounted host node's protocol view id IS the publication envelope's
    // `surfaceViewId` (LLP 0420 §2) — no surface string goes on the wire.
    nativeMount?.bind(mountedElement.hostNodes()[0]);
    let disposed = false;
    const dispose = (): void => {
      if (disposed) {
        return;
      }
      disposed = true;
      // Exception-safe teardown: if scene disposal throws, the registry
      // entry, the behavior attachment, and the host element must still be
      // released — a leaked attachment makes remounting the same behavior
      // throw "scene is already attached".
      try {
        mountedScene.dispose();
      } finally {
        // The opcode-41 teardown goes out BEFORE the host element is
        // destroyed: it names the (surface, epoch) pair whose retained scene
        // it retires, and the surface id is that node's id.
        nativeMount?.dispose();
        viewBoxEffect?.dispose();
        unregisterGraphicsSurfaceScene(surfaceKey);
        behavior?.__detachSurface(surfaceKey);
        mountedElement.dispose();
      }
    };
    // Owner registration (the mountElement pattern): control-flow regions
    // (`when`/`each` branches) tear children down by disposing the owner, not
    // by calling Mounted.dispose() — without this, an unmounted surface leaks
    // its scene nodes, registry entry, and behavior attachment.
    getOwner()?.register(dispose);
    return {
      hostNodes: () => mountedElement.hostNodes(),
      dispose,
    };
  } catch (error) {
    try {
      mountedSceneForUnwind?.dispose();
    } catch {
      // Best-effort unwind: the original mount failure is the error to
      // surface, never a secondary disposal throw.
    }
    (nativeMount as ContractNativeGraphicsMount | null)?.dispose();
    viewBoxEffect?.dispose();
    unregisterGraphicsSurfaceScene(surfaceKey);
    behavior?.__detachSurface(surfaceKey);
    try {
      mountedElementForUnwind?.dispose();
    } catch {
      // Best-effort unwind: the original mount failure is the error to
      // surface, never a secondary disposal throw.
    }
    throw error;
  }
}

// ---------------------------------------------------------------------------
// Video elements (LLP 0393)
// ---------------------------------------------------------------------------

let nextContractVideoKey = 0;
const loweredVideoNodes = new WeakSet<ViewNodeIR>();
const reportedVideoPlaceholders = new Set<string>();

function readVideoProp(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  name: string,
  scope: Scope,
): unknown {
  const expr = node.props[name];
  if (expr === undefined) {
    return undefined;
  }
  return untrack(() => evalRuntimeExpr(expr, scope, VIEW_EVAL));
}

function currentVideoViewConfig(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  scope: Scope,
): ContractVideoViewConfig {
  const poster = node.props.poster
    ? evalRuntimeExpr(node.props.poster, scope, VIEW_EVAL)
    : undefined;
  const objectFit = node.props.objectFit
    ? evalRuntimeExpr(node.props.objectFit, scope, VIEW_EVAL)
    : undefined;
  const controls = node.props.controls
    ? evalRuntimeExpr(node.props.controls, scope, VIEW_EVAL)
    : undefined;
  return {
    ...(poster !== undefined ? { poster: String(poster) } : {}),
    ...(objectFit !== undefined ? { objectFit: String(objectFit) } : {}),
    ...(controls !== undefined ? { controls: controls !== false } : {}),
  };
}

/**
 * Mounts a `video` element (LLP 0393): resolves the self-owned vs bound
 * player mode, synthesizes an ordinary `VideoView`-lowered element carrying
 * only string props (live players travel through the video-surface registry,
 * never host props), wires lifecycle events through the engine's subscribe
 * seam, and applies reactive playback/view props behind change gates so an
 * unrelated signal flush produces zero host calls (the ENG-23172 lesson).
 *
 * Exported for the AOT element path (`aot-view-element.ts`), which
 * reconstructs an Expr-shaped node and delegates here — the video semantics
 * exist exactly once.
 */
export function mountContractVideoElement(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  mountNodes: (
    nodes: readonly ViewNodeIR[],
    parent: HostParent,
    anchor: AnchorFn | null,
    env: MountEnv,
  ) => Mounted,
): Mounted {
  const { scope } = env;
  const engine = getContractVideoEngine();

  // Bound-player resolution is mount-frozen and fails closed (the graphics
  // `surface=` pattern): a `player=` that does not resolve to a video player
  // behavior would otherwise silently present a dead surface.
  const playerExpr = node.props.player;
  const boundValue = playerExpr
    ? untrack(() => evalRuntimeExpr(playerExpr, scope, VIEW_EVAL))
    : undefined;
  const boundBehavior = isVideoPlayerBehavior(boundValue) ? boundValue : undefined;
  if (playerExpr && !boundBehavior) {
    throw new Error(
      `[contract] ${env.component.name}: video player= must bind a videoPlayer() behavior from @exact/contract/video (LLP 0393)`,
    );
  }

  const elementProps: Record<string, Expr> = {};
  for (const [name, expr] of Object.entries(node.props)) {
    if (!CONTRACT_VIDEO_SEAM_PROP_SET.has(name)) {
      elementProps[name] = expr;
    }
  }
  const elementEvents: Record<string, Expr> = {};
  const videoEvents: Record<string, Expr> = {};
  for (const [name, expr] of Object.entries(node.events)) {
    if (CONTRACT_VIDEO_EVENT_SET.has(name)) {
      videoEvents[name] = expr;
    } else {
      elementEvents[name] = expr;
    }
  }

  if (!engine) {
    // Degraded platforms fail visible, never blank (the LLP 0352 graphics
    // placeholder behavior).
    const placeholderKey = `${env.component.name}:${node.span.line}`;
    if (!reportedVideoPlaceholders.has(placeholderKey)) {
      reportedVideoPlaceholders.add(placeholderKey);
      console.warn(
        `[video] ${placeholderKey}: no video engine on this platform — rendering the LLP 0393 missing-backend placeholder`,
        { code: "video_backend_missing" },
      );
    }
    const placeholder: Extract<ViewNodeIR, { kind: "element" }> = {
      kind: "element",
      tag: "column",
      props: {
        ...elementProps,
        "data-exact-video-placeholder": stringExpr("true"),
        borderWidth: elementProps.borderWidth ?? numberExpr(1),
        borderColor: elementProps.borderColor ?? stringExpr("rgba(127,127,127,0.35)"),
        radius: elementProps.radius ?? numberExpr(6),
        padding: elementProps.padding ?? numberExpr(12),
        justify: stringExpr("center"),
        align: stringExpr("center"),
      },
      events: elementEvents,
      children: [
        {
          kind: "element",
          tag: "text",
          props: { size: numberExpr(12), opacity: numberExpr(0.6) },
          events: {},
          children: [
            {
              kind: "text",
              expr: { kind: "string", value: "video (no playback backend on this platform yet)" },
              span: node.span,
            },
          ],
          span: node.span,
        },
      ],
      span: node.span,
      propSources: node.propSources,
    };
    return mountElement(placeholder, parent, anchor, env);
  }

  const selfOwned = boundBehavior === undefined;
  let player: unknown;
  if (selfOwned) {
    const autoplay = readVideoProp(node, "autoplay", scope);
    const pausedProp = readVideoProp(node, "paused", scope);
    player = engine.createPlayer({
      source: readVideoProp(node, "src", scope),
      ...(autoplay !== undefined ? { autoplay: autoplay === true } : {}),
      // The <Video> convenience semantics: an explicit paused= wins,
      // otherwise autoplay decides the initial state.
      paused: pausedProp !== undefined ? pausedProp === true : !(autoplay === true),
      ...(node.props.muted !== undefined
        ? { muted: readVideoProp(node, "muted", scope) === true }
        : {}),
      ...(node.props.loop !== undefined
        ? { loop: readVideoProp(node, "loop", scope) === true }
        : {}),
      ...(node.props.volume !== undefined
        ? { volume: Number(readVideoProp(node, "volume", scope)) }
        : {}),
      ...(node.props.rate !== undefined
        ? { rate: Number(readVideoProp(node, "rate", scope)) }
        : {}),
    });
  } else {
    player = boundBehavior.__player;
  }

  const playerKey = `video:${env.component.name}:${node.span.line}:${nextContractVideoKey++}`;

  // Mount-path exception safety (the graphics unwind pattern): anything
  // acquired before a throw must be released, or a retry leaks a native
  // player / registry entry.
  let unsubscribeForUnwind: (() => void) | null = null;
  let registeredForUnwind = false;
  let mountedElementForUnwind: Mounted | null = null;
  const effectsForUnwind: EffectHandle[] = [];
  try {
    const initialViewConfig = untrack(() => currentVideoViewConfig(node, scope));
    const registeredEntry: RegisteredContractVideoPlayer = {
      player,
      viewConfig: engine.serializeViewConfig(initialViewConfig),
    };
    registerContractVideoPlayer(playerKey, registeredEntry);
    registeredForUnwind = true;

    // Lifecycle events arrive through the engine's subscribe seam on every
    // backend (web DOM listeners and the native module bridge converge on
    // it) — they are not host-prop events.
    const handlers: ContractVideoEventHandlers = {};
    for (const [name, expr] of Object.entries(videoEvents)) {
      const invoke = makeHandler(
        expr,
        scope,
        viewNodeLocus(env, node, `event "${name}"`),
      );
      (handlers as Record<string, (payload?: unknown) => void>)[name] = (
        payload?: unknown,
      ) => invoke(payload);
    }
    const unsubscribe =
      Object.keys(handlers).length > 0 ? engine.subscribe(player, handlers) : null;
    unsubscribeForUnwind = unsubscribe;

    const synthetic: Extract<ViewNodeIR, { kind: "element" }> = {
      kind: "element",
      tag: "video",
      props: {
        ...elementProps,
        videoPlayerId: stringExpr(engine.playerId(player)),
        videoViewConfig: stringExpr(registeredEntry.viewConfig),
        "data-exact-video-player-id": stringExpr(playerKey),
        "data-exact-video-view-config": stringExpr(registeredEntry.viewConfig),
      },
      events: elementEvents,
      children: [],
      span: node.span,
      propSources: node.propSources,
    };
    loweredVideoNodes.add(synthetic);
    const mountedElement = mountContractElement(synthetic, parent, anchor, env, mountNodes);
    mountedElementForUnwind = mountedElement;

    const hostNode = mountedElement.hostNodes()[0] as { id?: unknown } | undefined;
    const hostNodeId = typeof hostNode?.id === "number" ? hostNode.id : null;
    if (hostNodeId !== null) {
      engine.setBoundNativeView(player, hostNodeId, true);
    }

    // Reactive appliers, all signature/value-gated: re-running an effect with
    // an unchanged value must produce zero engine calls (replaceSource
    // restarts playback; view-config chatter is ENG-23172).
    if (selfOwned && node.props.src !== undefined) {
      const srcExpr = node.props.src;
      let lastSourceSignature = JSON.stringify(
        untrack(() => evalRuntimeExpr(srcExpr, scope, VIEW_EVAL)) ?? null,
      );
      effectsForUnwind.push(
        ownedEffect(() => {
          const source = evalRuntimeExpr(srcExpr, scope, VIEW_EVAL);
          const signature = JSON.stringify(source ?? null);
          if (signature !== lastSourceSignature) {
            lastSourceSignature = signature;
            engine.replaceSource(player, source);
          }
        }),
      );
    }
    if (selfOwned) {
      const scalarAppliers: ReadonlyArray<
        [prop: string, apply: (value: unknown) => void]
      > = [
        ["muted", (value) => engine.setMuted(player, value === true)],
        ["loop", (value) => engine.setLoop(player, value === true)],
        ["volume", (value) => engine.setVolume(player, Number(value))],
        ["rate", (value) => engine.setRate(player, Number(value))],
        ["paused", (value) => engine.setPaused(player, value === true)],
      ];
      for (const [prop, apply] of scalarAppliers) {
        const expr = node.props[prop];
        if (expr === undefined) {
          continue;
        }
        let last = untrack(() => evalRuntimeExpr(expr, scope, VIEW_EVAL));
        effectsForUnwind.push(
          ownedEffect(() => {
            const value = evalRuntimeExpr(expr, scope, VIEW_EVAL);
            if (value !== last) {
              last = value;
              apply(value);
            }
          }),
        );
      }
    }
    const hasReactiveViewConfig =
      node.props.poster !== undefined ||
      node.props.objectFit !== undefined ||
      node.props.controls !== undefined;
    if (hasReactiveViewConfig) {
      effectsForUnwind.push(
        ownedEffect(() => {
          const config = currentVideoViewConfig(node, scope);
          const serialized = engine.serializeViewConfig(config);
          if (serialized !== registeredEntry.viewConfig) {
            registeredEntry.viewConfig = serialized;
            engine.updateViewConfig(player, config);
          }
        }),
      );
    }

    let disposed = false;
    const dispose = (): void => {
      if (disposed) {
        return;
      }
      disposed = true;
      try {
        unsubscribe?.();
      } finally {
        for (const effect of effectsForUnwind) {
          effect.dispose();
        }
        if (hostNodeId !== null) {
          engine.setBoundNativeView(player, hostNodeId, false);
        }
        unregisterContractVideoPlayer(playerKey);
        // Ownership (LLP 0393 D3): a self-owned player dies with its tag; a
        // bound player only detaches — the declaring behavior destroys it
        // with its component owner.
        if (selfOwned) {
          engine.destroyPlayer(player);
        }
        mountedElement.dispose();
      }
    };
    getOwner()?.register(dispose);
    return {
      hostNodes: () => mountedElement.hostNodes(),
      dispose,
    };
  } catch (error) {
    try {
      unsubscribeForUnwind?.();
    } catch {
      // Best-effort unwind: surface the original mount failure.
    }
    for (const effect of effectsForUnwind) {
      effect.dispose();
    }
    if (registeredForUnwind) {
      unregisterContractVideoPlayer(playerKey);
    }
    if (selfOwned) {
      try {
        engine.destroyPlayer(player);
      } catch {
        // Best-effort unwind: surface the original mount failure.
      }
    }
    try {
      mountedElementForUnwind?.dispose();
    } catch {
      // Best-effort unwind: surface the original mount failure.
    }
    throw error;
  }
}

// ---------------------------------------------------------------------------
// Elements + text
// ---------------------------------------------------------------------------

function hasProp(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  name: string,
): boolean {
  return Object.prototype.hasOwnProperty.call(node.props, name);
}

function hasStyleKey(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  names: Set<string>,
): boolean {
  const styleExpr = node.props.style;
  if (!styleExpr) {
    return false;
  }
  if (styleExpr.kind !== "object") {
    return true;
  }
  return styleExpr.entries.some(
    (entry) => isExprSpread(entry) || names.has(entry.key),
  );
}

function applyRootScrollDefaults(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  style: Record<string, unknown>,
): void {
  if (!hasProp(node, "width") && !hasStyleKey(node, new Set(["width"]))) {
    style.width = "100%";
  }
  if (
    !hasProp(node, "minHeight") &&
    !hasStyleKey(node, new Set(["minHeight"]))
  ) {
    style.minHeight = 0;
  }
  if (
    !hasProp(node, "height") &&
    !hasProp(node, "minHeight") &&
    !hasProp(node, "maxHeight") &&
    !hasProp(node, "flex") &&
    !hasProp(node, "grow") &&
    !hasProp(node, "basis") &&
    !hasStyleKey(
      node,
      new Set([
        "height",
        "minHeight",
        "maxHeight",
        "flex",
        "flexGrow",
        "grow",
        "flexBasis",
        "basis",
      ]),
    )
  ) {
    style.flex = 1;
  }
}

function mountElement(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  return mountContractElement(node, parent, anchor, env, mountViewNodes);
}

type ContractAotElementPropPlan = readonly [
  name: string,
  value: unknown | CompiledExpr,
  tokenPath?: string,
];

type ContractAotElementEventPlan = readonly [
  name: string,
  evaluate: CompiledExpr,
  mode: 0 | 1 | 2,
  action: string | null,
];

export type ContractAotElementPlan = readonly [
  props: readonly ContractAotElementPropPlan[],
  events: readonly ContractAotElementEventPlan[],
  tag: string,
  line: number,
  col: number,
  len: number,
  offset: number,
];

/** Reconstructs only the tiny expression shells the shared element semantics
 * key on, binding each shell to its generated evaluator. Authored production
 * prop/event AST is therefore absent from the client IR. */
export function mountContractElementPlan(
  plan: ContractAotElementPlan,
  runtimeNode: Extract<ViewNodeIR, { kind: "element" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  mountNodes: (
    nodes: readonly ViewNodeIR[],
    parent: HostParent,
    anchor: AnchorFn | null,
    env: MountEnv,
  ) => Mounted,
): Mounted {
  const [propPlans, eventPlans, tag, line, col, len, offset] = plan;
  const props: Record<string, Expr> = Object.create(null);
  for (const [name, value, tokenPath] of propPlans) {
    if (typeof value !== "function") {
      const literal = value === null
        ? ({ kind: "null" } as const)
        : typeof value === "string"
          ? ({ kind: "string", value } as const)
          : typeof value === "number"
            ? ({ kind: "number", value } as const)
            : ({ kind: "boolean", value: value as boolean } as const);
      props[name] = literal;
      continue;
    }
    const expression: Expr = tokenPath === undefined
      ? { kind: "ident", name: "__contractAotValue" }
      : { kind: "token", path: tokenPath };
    bindContractAotExpression(expression, value as CompiledExpr);
    props[name] = expression;
  }
  const events: Record<string, Expr> = Object.create(null);
  for (const [name, evaluate, mode, action] of eventPlans) {
    const expression: Expr = mode === 1
      ? {
          kind: "call",
          callee: { kind: "ident", name: action ?? "__contractAotAction" },
          args: [],
        }
      : { kind: "ident", name: action ?? "__contractAotAction" };
    bindContractAotExpression(expression, evaluate);
    events[name] = expression;
  }
  runtimeNode.tag = tag;
  runtimeNode.props = props;
  runtimeNode.events = events;
  runtimeNode.span = { line, col, len, offset };
  return mountContractElement(runtimeNode, parent, anchor, env, mountNodes);
}

export function mountContractElement(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  mountNodes: (
    nodes: readonly ViewNodeIR[],
    parent: HostParent,
    anchor: AnchorFn | null,
    env: MountEnv,
  ) => Mounted,
): Mounted {
  const { scope } = env;
  const lowering = TAG_LOWERING[node.tag] ?? RUNTIME_TAG_LOWERING[node.tag];
  if (!lowering) {
    throw new Error(`[contract] no host lowering for "${node.tag}"`);
  }
  if ((node.tag === "list" || node.tag === "virtualList") && node.props.items) {
    return mountCollectionElement(node, parent, anchor, env, lowering, mountNodes);
  }
  if (node.tag === "video" && !loweredVideoNodes.has(node)) {
    return mountContractVideoElement(node, parent, anchor, env, mountNodes);
  }

  const staticProps: Record<string, unknown> = {
    ...(lowering.staticProps ?? {}),
  };
  if (lowering.semanticTag) {
    staticProps.__exactSemanticTag = lowering.semanticTag;
  }
  const staticStyle: Record<string, unknown> = {
    ...(lowering.staticStyle ?? {}),
  };
  // Literal authored style attrs live in their own layer so they override
  // `style=` sources (style recipes / style objects) deterministically:
  // lowering defaults < style= output < authored attrs (LLP 0254 §4.4,
  // pinned by contract-style-recipes.test.ts).
  const staticAttrStyle: Record<string, unknown> = {};
  if (env.isRootView && node.tag === "scroll") {
    applyRootScrollDefaults(node, staticStyle);
  }
  const dynamicProps: Array<{
    hostProp: string;
    expr: Expr;
    map?: (value: unknown) => unknown;
  }> = [];
  const dynamicStyle: Array<{ styleProp: string; expr: Expr }> = [];
  // LLP 0281 §3.3 — channel-driven sink attrs (transform/opacity). Applied
  // per coalesced channel frame through the host seam, never through the
  // reactive patch effect below.
  const channelStyleSinks: Array<{
    styleProp: string;
    expr: Expr;
    channel: ContractValueChannel;
  }> = [];
  // LLP 0089 rev 2 / LLP 0099 M6 — direct SharedValue/DAG presentation
  // bindings. These subscribe to the Motion value plane, never the Contract
  // tree's reactive patch effect.
  const motionStyleSinks: Array<{
    /** Authored sink attr (`radius`, `grow`) — the compiler binding key. */
    attr: string;
    styleProp: string;
    expr: Expr;
    dependencies: ContractMotionReadable[];
    staticValue: unknown;
  }> = [];
  // Authored attr -> lowered host target, for the S4 hot-patch pipeline.
  const attrTargets: Record<
    string,
    { target: "prop" | "style"; name: string }
  > = {};
  let dynamicStyleObject: Expr | null = null;
  let interactionExpr: Expr | null = null;
  let dismissExpr: Expr | null = null;
  let sortableItemExpr: Expr | null = null;
  let dismissLayerHandle: DismissLayerHandle | null = null;
  // Design Mode D0 (LLP 0158): null in production, no per-attr cost there.
  const provenance = CONTRACT_VIEW_DEV
    ? beginElementProvenance(node, env)
    : null;
  // LLP 0398 P1 — render-time merge seed (dev-only; null in production).
  // `staticStyle` mixes lowering defaults with literal `style=` output, so
  // the lowering layer is snapshotted here (before the attr loop) and the
  // literal style= contribution is mirrored separately as it is applied.
  const mergeCapture = CONTRACT_VIEW_DEV
    ? beginMergeCapture(mergeCaptureSubjectFor(node, env, "element"))
    : null;
  const mergeLoweringLayer = mergeCapture ? { ...staticStyle } : null;
  const mergeStaticStyleSource: Record<string, unknown> | null = mergeCapture
    ? {}
    : null;
  let mergeHasStyleSource = false;

  for (const [name, expr] of Object.entries(node.props)) {
    if (name === "sortableItem") {
      sortableItemExpr = expr;
      continue;
    }
    if (name === "interaction") {
      interactionExpr = expr;
      continue;
    }
    if (node.tag === "lottie" && name === "player") {
      // LLP 0394 §5.2: player= binds a lottiePlayer() behavior instance.
      // Mount-frozen (the graphics surface= discipline) and lowered to the
      // lottiePlayerId host prop — live objects never ride host props. A
      // non-behavior value fails closed: the binding is dropped with a dev
      // diagnostic instead of leaking an object into host props.
      const playerValue = untrack(() => evalRuntimeExpr(expr, scope, VIEW_EVAL));
      if (hasContractLottiePlayerBrand(playerValue)) {
        const player = playerValue as LottiePlayerBehavior;
        staticProps.lottiePlayerId = player.playerId;
        attrTargets[name] = { target: "prop", name: "lottiePlayerId" };
        provenance?.record("lottiePlayerId", name, expr);
        player.__attachNode();
        getOwner()?.register(() => player.__detachNode());
      } else {
        console.warn(
          `[contract] ${env.component.name}: lottie player= must bind a lottiePlayer() behavior instance (LLP 0394 §5.2) — binding dropped`,
        );
      }
      continue;
    }
    if (node.tag === "rive" && name === "controller") {
      // LLP 0395 §2.3: mount-frozen behavior link. Only the string id crosses
      // the host boundary; invalid values fail closed.
      const controllerValue = untrack(() => evalRuntimeExpr(expr, scope, VIEW_EVAL));
      if (hasContractRiveControllerBrand(controllerValue)) {
        const controller = controllerValue as RiveControllerBehavior;
        staticProps.riveControllerId = controller.controllerId;
        attrTargets[name] = { target: "prop", name: "riveControllerId" };
        provenance?.record("riveControllerId", name, expr);
        controller.__attachNode();
        getOwner()?.register(() => controller.__detachNode());
      } else {
        console.warn(
          `[contract] ${env.component.name}: rive controller= must bind a riveController() behavior instance (LLP 0395 §2.3) — binding dropped`,
        );
      }
      continue;
    }
    if (name === "dismiss") {
      dismissExpr = expr;
      staticProps.__exactDismissableLayer = true;
      const actionName = actionNameFromExpr(expr);
      if (actionName) {
        staticProps.__exactDismissAction = actionName;
      }
      attrTargets[name] = { target: "prop", name: "__exactDismissableLayer" };
      provenance?.record("__exactDismissableLayer", name, expr);
      continue;
    }
    if (name === "style") {
      if (isLiteral(expr)) {
        const literalStyleValue = evalRuntimeExpr(expr, scope, VIEW_EVAL);
        applyStyleObject(staticStyle, literalStyleValue);
        if (mergeStaticStyleSource) {
          applyStyleObject(mergeStaticStyleSource, literalStyleValue);
          mergeHasStyleSource = true;
        }
        provenance?.recordStyleObject(expr);
      } else if (expr.kind === "object") {
        dynamicStyleObject = expr;
        provenance?.recordStyleObject(expr);
      } else {
        dynamicStyleObject = expr;
        provenance?.recordStyleSource(expr);
      }
      mergeCapture?.describeStyleSource(describeStyleSourceExpr(expr));
      continue;
    }
    const stylePropName =
      STYLE_PROP_MAP[name] ??
      (CONTRACT_TEXT_BEARING_TAG_SET.has(node.tag)
        ? TEXT_STYLE_PROP_MAP[name]
        : undefined);
    if (stylePropName) {
      attrTargets[name] = { target: "style", name: stylePropName };
      provenance?.record(stylePropName, name, expr);
      if (isLiteral(expr)) {
        applyStyleValue(
          staticAttrStyle,
          stylePropName,
          transformLoweredStyleValue(
            stylePropName,
            evalRuntimeExpr(expr, scope, VIEW_EVAL),
          ),
        );
      } else {
        // Motion may drive the layout-island family as well; a CHANNEL may
        // not (LLP 0417 §3 — a channel frame carries no island registration).
        const motionReads = CONTRACT_MOTION_SINK_ATTRS.has(name)
          ? findMotionReadsInExpr(expr, scope, env.component.ir)
          : [];
        const sinkChannel =
          motionReads.length === 0 && CONTRACT_CHANNEL_SINK_ATTRS.has(name)
            ? findChannelReadInExpr(expr, scope)
            : null;
        if (motionReads.length > 0) {
          motionStyleSinks.push({
            attr: name,
            styleProp: stylePropName,
            expr,
            dependencies: motionReads,
            // Filled after every authored prop has been classified so
            // `transform=... style={ transform: ... }` composes exactly like
            // the opposite source order.
            staticValue: undefined,
          });
        } else if (sinkChannel) {
          channelStyleSinks.push({
            styleProp: stylePropName,
            expr,
            channel: sinkChannel,
          });
        } else {
          dynamicStyle.push({ styleProp: stylePropName, expr });
        }
      }
      continue;
    }
    const mappedOverlay = lowerOverlayProp(name);
    const hostProp = mappedOverlay?.hostProp ?? PROP_RENAMES[name] ?? name;
    const mapProp =
      mappedOverlay?.map ??
      (node.tag === "image" && name === "loading"
        ? (value: unknown) =>
            lowerContractImageLoading(
              value,
              env.inRepetitionScope,
              env.repetitionIndex,
            )
        : name === "headingLevel"
          ? mapHeadingLevelValue
          : undefined);
    attrTargets[name] = { target: "prop", name: hostProp };
    provenance?.record(hostProp, name, expr);
    if (isLiteral(expr)) {
      const rawValue = evalRuntimeExpr(expr, scope, VIEW_EVAL);
      staticProps[hostProp] = mapProp ? mapProp(rawValue) : rawValue;
    } else {
      dynamicProps.push({ hostProp, expr, map: mapProp });
    }
  }

  if (
    node.tag === "image" &&
    node.props.loading === undefined &&
    env.inRepetitionScope
  ) {
    staticProps.loading = lowerContractImageLoading(
      undefined,
      env.inRepetitionScope,
      env.repetitionIndex,
    );
  }

  for (const sink of motionStyleSinks) {
    sink.staticValue =
      literalStyleObjectValue(node.props.style, sink.styleProp, scope) ??
      staticStyle[sink.styleProp];
  }

  if (
    node.tag === "text" &&
    node.props.headingLevel &&
    !node.props.role &&
    !node.props.accessibilityRole
  ) {
    staticProps.accessibilityRole = "heading";
  }

  // Event handlers wire once. forEach, not for-of: the submit wrapper
  // closure escapes the iteration, and Hermes scopes for-of `const` to the
  // function (the module loader's rewrite skips bodies with `continue`).
  const eventProps: Record<string, unknown> = {};
  Object.entries(node.events).forEach(([event, handlerExpr]) => {
    const hostEvent = lowerEventName(event, node.tag);
    if (!hostEvent) {
      console.warn(
        `[contract] event "${event}" has no host lowering on <${node.tag}>`,
      );
      return;
    }
    if (CONTRACT_POINTER_EVENT_SET.has(event)) {
      const pointerHandler = makePointerEventHandler(
        event,
        handlerExpr,
        scope,
        viewNodeLocus(env, node, `event "${event}"`),
      );
      if (pointerHandler) {
        eventProps[hostEvent] = pointerHandler;
      }
      return;
    }
    const invoke = makeHandler(
      handlerExpr,
      scope,
      viewNodeLocus(env, node, `event "${event}"`),
      event === "press"
        ? {
            instance: env.instance,
            id: `${env.instance.runtimeInstanceId ?? env.component.name}/${env.ids.get(node) ?? node.span.line}`,
          }
        : undefined,
    );
    if (event === "submit") {
      staticProps.__exactSubmitHandler = true;
      eventProps[hostEvent] = chainEventHandler(
        eventProps[hostEvent],
        (payload: unknown) => {
          if (!payload || keyFromPayload(payload) === "Enter") {
            invoke(payload);
          }
        },
      );
    } else if (event === "keydown") {
      staticProps.__exactKeydownObserver = true;
      // The action receives the key string (`action onKey(key)`), matching
      // how `change` delivers the input value (LLP 0293 ledger row 1).
      warnNativeKeydownAttrOnce(node.tag);
      eventProps[hostEvent] = chainEventHandler(
        eventProps[hostEvent],
        (payload: unknown) => {
          invoke(keyFromPayload(payload) ?? payload);
        },
      );
    } else if (event === "accessibilityaction") {
      eventProps[hostEvent] = (payload: unknown) => {
        invoke(accessibilityActionNameFromPayload(payload) ?? payload);
      };
    } else {
      eventProps[hostEvent] = invoke;
    }
  });
  if (node.tag === "link" && typeof eventProps.onPress !== "function") {
    const linkPress = makeLinkPressHandler(node.props.href, scope);
    if (linkPress) {
      eventProps.onPress = linkPress;
    }
  }
  if (dismissExpr) {
    // Dismiss is implemented as an Escape-filtered keydown handler. Mark it
    // for native/TUI handler registration just like an authored keydown;
    // otherwise the JS closure exists but no host handler id reaches the
    // presented frame for keyboard or click-outside dismissal.
    staticProps.__exactKeydownObserver = true;
    const dismiss = makeHandler(
      dismissExpr,
      scope,
      viewNodeLocus(env, node, 'event "dismiss"'),
    );
    eventProps.onKeyDown = chainEventHandler(
      eventProps.onKeyDown,
      (payload: unknown) => {
        if (
          (!payload || keyFromPayload(payload) === "Escape") &&
          dismissLayerHandle?.isTopmost() === true
        ) {
          dismiss(payload);
        }
      },
    );
  }

  // Behavior attachment (the interaction-state primitive, LLP 0157 §5/F2a-i).
  let attachedBehavior: unknown = null;
  if (interactionExpr) {
    const behavior = untrack(() => evalRuntimeExpr(interactionExpr!, scope));
    attachedBehavior = behavior;
    if (isBehaviorInstance(behavior) && behavior.attachProps) {
      Object.entries(behavior.attachProps()).forEach(([propName, handler]) => {
        const existing = eventProps[propName];
        if (typeof existing === "function" && typeof handler === "function") {
          eventProps[propName] = (...args: unknown[]) => {
            (handler as (...a: unknown[]) => void)(...args);
            (existing as (...a: unknown[]) => void)(...args);
          };
        } else {
          eventProps[propName] = handler;
        }
      });
    } else if (behavior != null) {
      console.warn("[contract] interaction= expects a behavior instance");
    }
  }

  const hasDynamic =
    dynamicProps.length > 0 ||
    dynamicStyle.length > 0 ||
    dynamicStyleObject !== null;
  const structuralId = env.ids.get(node);
  const hydrationNodeId = applyHydrationElementProps(
    env,
    structuralId,
    staticProps,
  );
  const dismissLayerId = dismissExpr
    ? `contract-dismiss:${env.instance.runtimeInstanceId ?? env.component.name}:${structuralId ?? node.span.offset}`
    : null;
  const dismissLayerRootId = String(env.ctx.rootId);
  const dismissLayerMountSequence = dismissExpr
    ? reserveDismissLayerMountSequence()
    : null;
  const dismissLayerCommand = dismissExpr
    ? scopeIdentifierValue(dismissExpr, scope)
    : undefined;
  const decorateDismissLayerProps = (
    props: Record<string, unknown>,
  ): Record<string, unknown> => {
    if (!dismissLayerId || dismissLayerMountSequence === null) return props;
    const modal = props.accessibilityModal === true;
    const portalOrder = dismissLayerPortalOrder(props);
    const visualOrder = dismissLayerVisualOrder(props);
    dismissLayerHandle?.update({
      modal,
      portalOrder,
      visualOrder,
      command: isMotionCommandRef(dismissLayerCommand)
        ? dismissLayerCommand.identity
        : undefined,
      triggers: ["escape"],
    });
    return {
      ...props,
      __exactMotionDismissLayerClaim: Object.freeze({
        schemaVersion: 1,
        layerId: dismissLayerId,
        rootId: dismissLayerRootId,
        parentId: env.dismissLayerParentId ?? null,
        modal,
        portalOrder,
        visualOrder,
        mountSequence: dismissLayerMountSequence,
      }),
    };
  };
  let initialProps: Record<string, unknown> = { ...staticProps, ...eventProps };
  let sortableTransformValue: string | null = null;
  const sortableItem = sortableItemExpr
    ? sortableItemBinding(
        untrack(() => evalRuntimeExpr(sortableItemExpr!, scope)),
      )
    : null;
  if (sortableItemExpr && !sortableItem) {
    throw new TypeError(
      "[motion] sortableItem= expects a MotionSortableItem binding",
    );
  }
  const sortableTestId =
    sortableItem && node.props.testId
      ? String(
          untrack(() => evalRuntimeExpr(node.props.testId, scope, VIEW_EVAL)) ??
            "",
        )
      : "";
  if (sortableItem && sortableTestId.length === 0) {
    throw new Error(
      "[motion] sortableItem owner requires a unique evaluated testId",
    );
  }
  if (sortableItem) {
    const gesture = sortableItem.__exactGesture(sortableTestId);
    const presentation = sortableDragPresentation(sortableItem, sortableTestId);
    staticProps.__exactMotionGesture = gesture;
    staticProps.__exactMotionDragPresentation = presentation;
    initialProps.__exactMotionGesture = gesture;
    initialProps.__exactMotionDragPresentation = presentation;
  }
  const motionGesture = elementMotionGestureDescriptor(
    node,
    scope,
    env.component.ir,
  );
  if (motionGesture) {
    staticProps.__exactMotionGesture = motionGesture;
    initialProps.__exactMotionGesture = motionGesture;
  }
  const motionDragPresentation = elementMotionDragPresentationProp(
    node,
    scope,
    env.component.ir,
  );
  if (motionDragPresentation) {
    staticProps.__exactMotionDragPresentation = motionDragPresentation;
    initialProps.__exactMotionDragPresentation = motionDragPresentation;
  }
  if (
    !hasDynamic &&
    (Object.keys(staticStyle).length > 0 ||
      Object.keys(staticAttrStyle).length > 0)
  ) {
    initialProps.style = { ...staticStyle, ...staticAttrStyle };
  }
  if (sortableItem) {
    sortableTransformValue = sortableTransform(sortableItem.controller.axis, 0);
    initialProps.style = {
      ...((initialProps.style as Record<string, unknown> | undefined) ?? {}),
      transform: sortableTransformValue,
    };
  }
  if (mergeCapture) {
    // LLP 0398 P1 — post-merge style writers are temporal writers, never
    // merge candidates (D1/D9): declare them so the explanation stays
    // honest even when a sink writes through the host seam invisibly.
    for (const sink of channelStyleSinks) {
      mergeCapture.declareTemporalWriter(sink.styleProp, "channel");
    }
    for (const sink of motionStyleSinks) {
      mergeCapture.declareTemporalWriter(sink.styleProp, "motion");
    }
    if (sortableItem) {
      mergeCapture.declareTemporalWriter("transform", "sortable");
    }
    if (!hasDynamic) {
      const mergedInitial: Record<string, unknown> = {
        ...staticStyle,
        ...staticAttrStyle,
      };
      if (sortableTransformValue !== null) {
        mergedInitial.transform = sortableTransformValue;
      }
      mergeCapture.commit({
        loweringDefault: mergeLoweringLayer ?? {},
        styleSource: mergeHasStyleSource ? (mergeStaticStyleSource ?? {}) : null,
        authoredAttr: { ...staticAttrStyle },
        merged: mergedInitial,
      });
    }
  }
  initialProps = decorateDismissLayerProps(initialProps);

  const element = createInstance(lowering.tag, initialProps);
  registerElementMotionScrollBinding(
    node,
    element,
    scope,
    env.component.ir,
    env.ctx,
  );
  registerElementMotionCommandWitness(node, element, scope, env.ctx);
  if (env.ctx.routePayloadCapture && structuralId) {
    registerContractRoutePayloadElementCapture(
      env.ctx.routePayloadCapture,
      element,
      {
        kind: "element",
        id: hydrationNodeIdFor(env, structuralId),
        ...(routePayloadKeyFor(env) === undefined
          ? {}
          : { key: routePayloadKeyFor(env) }),
        tag: node.tag as ContractRoutePayloadTag,
        provenance: routePayloadProvenanceFor(env, node),
        readProps: () => {
          const props: Record<
            string,
            ReturnType<typeof readContractRoutePayloadExpression>
          > = Object.create(null);
          for (const [name, expr] of Object.entries(node.props)) {
            const value = readContractRoutePayloadExpression(
              expr,
              (candidate) => evalRuntimeExpr(candidate, scope, VIEW_EVAL),
              env.ctx.routePayloadCapture,
            );
            if (node.tag === "image" && name === "loading") {
              const lowered = lowerContractImageLoading(
                value,
                env.inRepetitionScope,
                env.repetitionIndex,
              );
              if (lowered !== undefined) props[name] = lowered;
            } else {
              props[name] = value;
            }
          }
          if (
            node.tag === "image" &&
            node.props.loading === undefined &&
            env.inRepetitionScope
          ) {
            const lowered = lowerContractImageLoading(
              undefined,
              env.inRepetitionScope,
              env.repetitionIndex,
            );
            if (lowered !== undefined) props.loading = lowered;
          }
          return props;
        },
      },
    );
  }
  recordHydrationElement(env, element, structuralId, hydrationNodeId);
  recordHydrationHandlers(
    env,
    element,
    node.events,
    structuralId,
    hydrationNodeId,
  );
  provenance?.finish(element);
  if (mergeCapture) {
    getOwner()?.register(mergeCapture.attach(element));
  }
  let lastProps = initialProps;
  let disposeSortableDrag: (() => void) | null = null;
  let disposeSortableSubscription: (() => void) | null = null;
  const refreshSortableItem = (): void => {
    if (!sortableItem) return;
    disposeSortableDrag?.();
    disposeSortableDrag = registerSortablePresentationBinding(
      element,
      sortableItem.controller,
      sortableItem.index,
      "drag",
      `${env.instance.runtimeInstanceId ?? env.component.name}:${structuralId ?? node.span.offset}`,
      (value, cross) => {
        sortableTransformValue = sortableTransform(
          sortableItem.controller.axis,
          value,
          cross,
        );
        mergeCapture?.recordTemporalWrite(
          "transform",
          "sortable",
          sortableTransformValue,
        );
        if (applyHostChannelStyle(element, "transform", sortableTransformValue))
          return;
        const next = {
          ...lastProps,
          style: {
            ...((lastProps.style as Record<string, unknown> | undefined) ?? {}),
            transform: sortableTransformValue,
          },
        };
        updateInstanceProps(element, lastProps, next);
        lastProps = next;
      },
    );
    const next = {
      ...lastProps,
      __exactMotionGesture: sortableItem.__exactGesture(sortableTestId),
      __exactMotionDragPresentation: sortableDragPresentation(
        sortableItem,
        sortableTestId,
      ),
    };
    staticProps.__exactMotionGesture = next.__exactMotionGesture;
    staticProps.__exactMotionDragPresentation =
      next.__exactMotionDragPresentation;
    updateInstanceProps(element, lastProps, next);
    lastProps = next;
  };
  if (sortableItem) {
    registerHydrationActivation(env.ctx, () => {
      refreshSortableItem();
      disposeSortableSubscription = sortableItem.subscribe(refreshSortableItem);
    }, env.instance.effectScope);
    getOwner()?.register(() => {
      disposeSortableSubscription?.();
      disposeSortableDrag?.();
    });
  }

  if (CONTRACT_VIEW_DEV) {
    if (isBehaviorInstance(attachedBehavior)) {
      // State forcing (LLP 0163 E1d): the panel pins hover/pressed/focus
      // through the behavior instance attached to this element.
      registerHydrationActivation(env.ctx, () => {
        registerInteractionTarget(
          element,
          attachedBehavior as {
            force?: (state: Record<string, boolean>) => void;
          },
        );
      });
    }
    if (structuralId) {
      const owner = getOwner();
      registerHydrationActivation(env.ctx, () => {
        const unregister = registerLiveNode({
          ...liveNodeRegistrationIdentity(env),
          structuralId,
          sourcePath: env.component.file.sourcePath,
          sourceVersion: env.component.file.sourceVersion,
          host: element,
          patch: {
            kind: "element",
            attrTargets,
            applyStatic(mutation) {
            // Mutate the closed-over static objects so future effect runs
            // rebuild from the patched values (no revert on the next flush),
            // then push through the normal update path. Style patches land in
            // the authored-attr layer so an edit keeps winning over `style=`
            // recipe output (LLP 0254 §4.4).
            if (mutation.props) {
              Object.assign(staticProps, mutation.props);
            }
            if (mutation.style) {
              Object.assign(staticAttrStyle, mutation.style);
              // LLP 0398 D9 — a hot patch is an authored-attr-layer
              // mutation plus an authorship event, never a temporal
              // writer: bump the authored candidates + append receipts.
              mergeCapture?.recordHotPatch(mutation.style);
            }
            const baseStyle = (lastProps.style ?? {}) as Record<
              string,
              unknown
            >;
            const nextStyle = { ...baseStyle, ...(mutation.style ?? {}) };
            const next: Record<string, unknown> = {
              ...lastProps,
              ...(mutation.props ?? {}),
            };
            if (Object.keys(nextStyle).length > 0) {
              next.style = nextStyle;
            }
            const decorated = decorateDismissLayerProps(next);
            updateInstanceProps(element, lastProps, decorated);
            lastProps = decorated;
            },
          },
        });
        owner?.register(unregister);
      });
    }
  }

  insertNode(parent, element, anchor());

  if (dismissLayerId && dismissLayerMountSequence !== null) {
    registerHydrationActivation(env.ctx, () => {
      dismissLayerHandle = registerDismissLayer({
        id: dismissLayerId,
        rootId: dismissLayerRootId,
        viewId: element.id,
        ...(env.dismissLayerParentId
          ? { parentId: env.dismissLayerParentId }
          : {}),
        modal: lastProps.accessibilityModal === true,
        portalOrder: dismissLayerPortalOrder(lastProps),
        visualOrder: dismissLayerVisualOrder(lastProps),
        mountSequence: dismissLayerMountSequence,
        triggers: ["escape"],
        ...(isMotionCommandRef(dismissLayerCommand)
          ? { command: dismissLayerCommand.identity }
          : {}),
      });
    });
  }

  // Registered BEFORE the attr effect and child mounts: a throw while
  // evaluating either must not leak the inserted element into the committed
  // tree — the owner's disposal removes it (keep-last-good, ENG-22443).
  let disposed = false;
  let childMount: Mounted | null = null;
  const dispose = (): void => {
    if (disposed) {
      return;
    }
    disposed = true;
    childMount?.dispose();
    dismissLayerHandle?.dispose();
    dismissLayerHandle = null;
    removeChild(parent, element);
  };
  getOwner()?.register(dispose);

  if (hasDynamic) {
    // One patch effect per element: still fine-grained relative to the
    // component (no tree re-render), without per-prop bookkeeping.
    // Merge order: lowering defaults, then `style=` output (recipe/object),
    // then authored attrs — literal and dynamic — so tag attrs win
    // deterministically over recipe output (LLP 0254 §4.4).
    const attrLocus = viewNodeLocus(env, node);
    ownedEffect(
      () =>
        runWithContractErrorLocus(attrLocus, () => {
          const style: Record<string, unknown> = { ...staticStyle };
          let dynamicStyleObjectValue: unknown;
          if (dynamicStyleObject) {
            dynamicStyleObjectValue = evalRuntimeExpr(
              dynamicStyleObject,
              scope,
              VIEW_EVAL,
            );
            applyStyleObject(style, dynamicStyleObjectValue);
          }
          Object.assign(style, staticAttrStyle);
          const mergeAuthoredLayer = mergeCapture
            ? { ...staticAttrStyle }
            : null;
          for (const entry of dynamicStyle) {
            const entryValue = transformLoweredStyleValue(
              entry.styleProp,
              evalRuntimeExpr(entry.expr, scope, VIEW_EVAL),
            );
            applyStyleValue(style, entry.styleProp, entryValue);
            if (mergeAuthoredLayer) {
              applyStyleValue(mergeAuthoredLayer, entry.styleProp, entryValue);
            }
          }
          if (sortableTransformValue !== null)
            style.transform = sortableTransformValue;
          if (mergeCapture) {
            const mergeStyleSourceLayer = {
              ...(mergeStaticStyleSource ?? {}),
            };
            if (dynamicStyleObject) {
              applyStyleObject(mergeStyleSourceLayer, dynamicStyleObjectValue);
            }
            mergeCapture.commit({
              loweringDefault: mergeLoweringLayer ?? {},
              styleSource:
                mergeHasStyleSource || dynamicStyleObject !== null
                  ? mergeStyleSourceLayer
                  : null,
              authoredAttr: mergeAuthoredLayer ?? {},
              merged: style,
              // LLP 0398 P3 — raw expression value, identity preserved: the
              // causal handle joining this merge to its recipe invocation.
              ...(dynamicStyleObject !== null
                ? { styleSourceValue: dynamicStyleObjectValue }
                : {}),
            });
          }
          const next: Record<string, unknown> = {
            ...staticProps,
            ...eventProps,
            style,
          };
          for (const entry of dynamicProps) {
            const rawValue = evalRuntimeExpr(entry.expr, scope, VIEW_EVAL);
            next[entry.hostProp] = entry.map ? entry.map(rawValue) : rawValue;
          }
          const decorated = decorateDismissLayerProps(next);
          updateInstanceProps(element, lastProps, decorated);
          lastProps = decorated;
        }),
      viewReactiveOptions(env, node, "element props"),
    );
  }

  if (channelStyleSinks.length > 0) {
    wireChannelStyleSinks(
      channelStyleSinks,
      element,
      scope,
      env.ctx,
      viewNodeLocus(env, node),
      (styleProp, value) => {
        // Fallback keeps the reactive patch effect coherent: recording the
        // value in the authored-attr layer means the next reactive flush
        // re-emits it instead of reverting the sink.
        staticAttrStyle[styleProp] = value;
        mergeCapture?.recordTemporalWrite(styleProp, "channel", value);
        const style = {
          ...((lastProps.style as Record<string, unknown> | undefined) ?? {}),
          [styleProp]: value,
        };
        const next: Record<string, unknown> = { ...lastProps, style };
        updateInstanceProps(element, lastProps, next);
        lastProps = next;
      },
    );
  }

  if (motionStyleSinks.length > 0) {
    wireMotionStyleSinks(
      motionStyleSinks,
      element,
      scope,
      env.component,
      env.instance,
      env.ctx,
      viewNodeLocus(env, node),
      (styleProp, value) => {
        staticAttrStyle[styleProp] = value;
        mergeCapture?.recordTemporalWrite(styleProp, "motion", value);
        const style = {
          ...((lastProps.style as Record<string, unknown> | undefined) ?? {}),
          [styleProp]: value,
        };
        const next: Record<string, unknown> = { ...lastProps, style };
        updateInstanceProps(element, lastProps, next);
        lastProps = next;
      },
    );
  }

  const crossesPortalBoundary =
    node.props.portalTarget !== undefined ||
    node.props.portalLevel !== undefined ||
    node.props.portalPresentation !== undefined;
  childMount = mountNodes(node.children, element, null, {
    ...env,
    isRootView: false,
    inRepetitionScope: crossesPortalBoundary ? false : env.inRepetitionScope,
    repetitionIndex: crossesPortalBoundary ? null : env.repetitionIndex,
    dismissLayerParentId: dismissLayerId ?? env.dismissLayerParentId,
  });

  return {
    hostNodes: () => (disposed ? [] : [element]),
    dispose,
  };
}

const COLLECTION_CONTROL_PROPS = new Set([
  "items",
  "as",
  "index",
  "key",
  "estimateSize",
  "estimatedItemSize",
  "viewportSize",
  "scrollOffset",
  "initialScrollOffset",
  "initialScrollKey",
  "initialMeasurements",
  "overscan",
  "drawDistance",
  "startReachedThreshold",
  "endReachedThreshold",
  "stickToBottom",
  "stickToBottomThreshold",
  "sortable",
]);

let nextContractListProducerGeneration = 1;

function allocateContractListProducerGeneration(): number {
  const generation = nextContractListProducerGeneration;
  nextContractListProducerGeneration = generation >= 0xffff_ffff ? 1 : generation + 1;
  return generation;
}

interface CollectionMountedRow {
  key: unknown;
  wrapper: ElementNode;
  owner: Owner;
  setItem(value: unknown): void;
  setIndex(value: number): void;
  updateFrame(frame: VirtualListItem | null, itemCount: number): void;
}

interface VirtualListPreparedCache {
  items: readonly unknown[];
  estimate: number;
  prepared: PreparedListState;
}

function mountCollectionElement(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  lowering: ContractTagLowering,
  mountNodes: (
    nodes: readonly ViewNodeIR[],
    parent: HostParent,
    anchor: AnchorFn | null,
    env: MountEnv,
  ) => Mounted,
): Mounted {
  const { scope } = env;
  const staticProps: Record<string, unknown> = {
    ...(lowering.staticProps ?? {}),
  };
  if (lowering.semanticTag) {
    staticProps.__exactSemanticTag = lowering.semanticTag;
  }
  const staticStyle: Record<string, unknown> = {
    ...(lowering.staticStyle ?? {}),
  };
  // Same authored-attr layering as mountElement (LLP 0254 §4.4): lowering
  // defaults < `style=` output < authored attrs.
  const staticAttrStyle: Record<string, unknown> = {};
  // LLP 0398 P1 — the separate collection merge path carries the same
  // render-time merge seed as mountElement (dev-only; null in production).
  const mergeCapture = CONTRACT_VIEW_DEV
    ? beginMergeCapture(mergeCaptureSubjectFor(node, env, "collection"))
    : null;
  const mergeLoweringLayer = mergeCapture ? { ...staticStyle } : null;
  const mergeStaticStyleSource: Record<string, unknown> | null = mergeCapture
    ? {}
    : null;
  let mergeHasStyleSource = false;
  const dynamicProps: Array<{
    hostProp: string;
    expr: Expr;
    map?: (value: unknown) => unknown;
  }> = [];
  const dynamicStyle: Array<{ styleProp: string; expr: Expr }> = [];
  // LLP 0281 §3.3 — channel-driven sink attrs (transform/opacity). Applied
  // per coalesced channel frame through the host seam, never through the
  // reactive patch effect below.
  const channelStyleSinks: Array<{
    styleProp: string;
    expr: Expr;
    channel: ContractValueChannel;
  }> = [];
  const motionStyleSinks: Array<{
    /** Authored sink attr (`radius`, `grow`) — the compiler binding key. */
    attr: string;
    styleProp: string;
    expr: Expr;
    dependencies: ContractMotionReadable[];
    staticValue: unknown;
  }> = [];
  let dynamicStyleObject: Expr | null = null;
  const structuralId = env.ids.get(node);
  const controlledScrollOffset = node.props.scrollOffset !== undefined;
  // Collection windowing is one-dimensional. `horizontal` selects which
  // native scroll axis feeds that geometry and which axis receives the
  // absolute row frames; the virtualizer math itself stays axis-agnostic.
  const horizontal = booleanProp(node.props.horizontal, scope, false);
  const listId =
    literalStringProp(node.props.testId ?? node.props.testID) ??
    `contract-list:${structuralId ?? "unknown"}`;
  const restorationIdentity = `${env.ctx.rootId}:${listId}`;
  const sortable = node.props.sortable
    ? sortableController(
        untrack(() => evalRuntimeExpr(node.props.sortable!, scope, VIEW_EVAL)),
      )
    : null;
  if (node.props.sortable && !sortable) {
    throw new TypeError(
      "[motion] sortable= expects a MotionSortableList controller",
    );
  }
  const sortableOwner = `${env.ctx.rootId}:${env.instance.runtimeInstanceId ?? env.component.name}:${listId}`;
  const precomputedRestorationSeed =
    peekPrecomputedContractListRestorationSeed(listId);
  const geometry = signal({
    offset:
      node.props.scrollOffset !== undefined ||
      node.props.initialScrollOffset !== undefined
        ? numberProp(
            node.props.scrollOffset ?? node.props.initialScrollOffset,
            scope,
            0,
          )
        : (precomputedRestorationSeed?.scrollOffset ?? 0),
    viewport: numberProp(node.props.viewportSize, scope, 0),
    interacted: false,
  });
  let tailFollowing = node.props.stickToBottom !== undefined;
  let latestReachSnapshot: {
    totalSize: number;
    visibleStartIndex: number;
    visibleEndIndex: number;
    itemCount: number;
  } | null = null;
  const reachState = new CollectionReachState();
  const refreshState = new CollectionRefreshState();
  let startReached: ((payload: unknown) => void) | undefined;
  let endReached: ((payload: unknown) => void) | undefined;

  for (const [name, expr] of Object.entries(node.props)) {
    if (COLLECTION_CONTROL_PROPS.has(name)) {
      continue;
    }
    if (name === "style") {
      if (isLiteral(expr)) {
        const literalStyleValue = evalRuntimeExpr(expr, scope, VIEW_EVAL);
        applyStyleObject(staticStyle, literalStyleValue);
        if (mergeStaticStyleSource) {
          applyStyleObject(mergeStaticStyleSource, literalStyleValue);
          mergeHasStyleSource = true;
        }
      } else {
        dynamicStyleObject = expr;
      }
      mergeCapture?.describeStyleSource(describeStyleSourceExpr(expr));
      continue;
    }
    const stylePropName =
      STYLE_PROP_MAP[name] ??
      (CONTRACT_TEXT_BEARING_TAG_SET.has(node.tag)
        ? TEXT_STYLE_PROP_MAP[name]
        : undefined);
    if (stylePropName) {
      if (isLiteral(expr)) {
        applyStyleValue(
          staticAttrStyle,
          stylePropName,
          transformLoweredStyleValue(
            stylePropName,
            evalRuntimeExpr(expr, scope, VIEW_EVAL),
          ),
        );
      } else {
        // Motion may drive the layout-island family as well; a CHANNEL may
        // not (LLP 0417 §3 — a channel frame carries no island registration).
        const motionReads = CONTRACT_MOTION_SINK_ATTRS.has(name)
          ? findMotionReadsInExpr(expr, scope, env.component.ir)
          : [];
        const sinkChannel =
          motionReads.length === 0 && CONTRACT_CHANNEL_SINK_ATTRS.has(name)
            ? findChannelReadInExpr(expr, scope)
            : null;
        if (motionReads.length > 0) {
          motionStyleSinks.push({
            attr: name,
            styleProp: stylePropName,
            expr,
            dependencies: motionReads,
            staticValue: undefined,
          });
        } else if (sinkChannel) {
          channelStyleSinks.push({
            styleProp: stylePropName,
            expr,
            channel: sinkChannel,
          });
        } else {
          dynamicStyle.push({ styleProp: stylePropName, expr });
        }
      }
      continue;
    }
    const mappedOverlay = lowerOverlayProp(name);
    const hostProp = mappedOverlay?.hostProp ?? PROP_RENAMES[name] ?? name;
    const mapProp =
      mappedOverlay?.map ??
      (name === "headingLevel" ? mapHeadingLevelValue : undefined);
    if (isLiteral(expr)) {
      const rawValue = evalRuntimeExpr(expr, scope, VIEW_EVAL);
      staticProps[hostProp] = mapProp ? mapProp(rawValue) : rawValue;
    } else {
      dynamicProps.push({ hostProp, expr, map: mapProp });
    }
  }

  for (const sink of motionStyleSinks) {
    sink.staticValue =
      literalStyleObjectValue(node.props.style, sink.styleProp, scope) ??
      staticStyle[sink.styleProp];
  }

  if (
    node.tag === "text" &&
    node.props.headingLevel &&
    !node.props.role &&
    !node.props.accessibilityRole
  ) {
    staticProps.accessibilityRole = "heading";
  }

  const eventProps: Record<string, unknown> = {};
  Object.entries(node.events).forEach(([event, handlerExpr]) => {
    if (event === "startreached" || event === "endreached") {
      const invoke = makeHandler(
        handlerExpr,
        scope,
        viewNodeLocus(env, node, `event "${event}"`),
      );
      if (event === "startreached") startReached = invoke;
      else endReached = invoke;
      return;
    }
    const hostEvent = lowerEventName(event, node.tag);
    if (!hostEvent) {
      console.warn(
        `[contract] event "${event}" has no host lowering on <${node.tag}>`,
      );
      return;
    }
    if (CONTRACT_POINTER_EVENT_SET.has(event)) {
      const pointerHandler = makePointerEventHandler(
        event,
        handlerExpr,
        scope,
        viewNodeLocus(env, node, `event "${event}"`),
      );
      if (pointerHandler) {
        eventProps[hostEvent] = pointerHandler;
      }
      return;
    }
    if (event === "refresh") {
      const invoke = makeCompletionHandler(
        handlerExpr,
        scope,
        viewNodeLocus(env, node, `event "${event}"`),
      );
      eventProps[hostEvent] = (payload: unknown) =>
        refreshState.begin((context) =>
          invoke(collectionRefreshPayload(payload, context)),
        );
      return;
    }
    const invoke = makeHandler(
      handlerExpr,
      scope,
      viewNodeLocus(env, node, `event "${event}"`),
      undefined,
    );
    if (event === "submit") {
      eventProps[hostEvent] = chainEventHandler(
        eventProps[hostEvent],
        (payload: unknown) => {
          if (!payload || keyFromPayload(payload) === "Enter") {
            invoke(payload);
          }
        },
      );
    } else if (event === "keydown") {
      warnNativeKeydownAttrOnce(node.tag);
      eventProps[hostEvent] = chainEventHandler(
        eventProps[hostEvent],
        (payload: unknown) => {
          invoke(keyFromPayload(payload) ?? payload);
        },
      );
    } else {
      eventProps[hostEvent] = invoke;
    }
  });

  const geometryMailbox = new CollectionGeometryMailbox(
    (sample: CollectionGeometrySample) => {
      const current = geometry.get();
      const viewport = sample.viewport > 0 ? sample.viewport : current.viewport;
      if (latestReachSnapshot) {
        reachState.update(
          { ...latestReachSnapshot, offset: sample.offset, viewport },
          numberProp(node.props.startReachedThreshold, scope, 0.5),
          numberProp(node.props.endReachedThreshold, scope, 0.5),
          {
            onStart: startReached
              ? (distanceFromEdge) =>
                  startReached?.({ distanceFromEdge, ...latestReachSnapshot })
              : undefined,
            onEnd: endReached
              ? (distanceFromEdge) =>
                  endReached?.({ distanceFromEdge, ...latestReachSnapshot })
              : undefined,
          },
        );
      }
      if (!controlledScrollOffset && node.tag === "virtualList") {
        if (sample.source === "user" && node.props.stickToBottom !== undefined) {
          const threshold = numberProp(
            node.props.stickToBottomThreshold,
            scope,
            24,
          );
          const totalSize = latestReachSnapshot?.totalSize ?? 0;
          tailFollowing =
            Math.max(0, totalSize - viewport - sample.offset) <= threshold;
        }
        geometry.set({ offset: sample.offset, viewport, interacted: true });
      }
    },
  );
  eventProps.onScroll = chainEventHandler(
    eventProps.onScroll,
    (payload: unknown) => {
      geometryMailbox.publish(
        collectionGeometryFromPayload(
          payload,
          listId,
          geometry.get(),
          horizontal,
        ),
      );
    },
  );
  staticProps.scrollEventThrottle = 50;

  const hasDynamic =
    dynamicProps.length > 0 ||
    dynamicStyle.length > 0 ||
    dynamicStyleObject !== null;
  const hydrationNodeId = applyHydrationElementProps(
    env,
    structuralId,
    staticProps,
  );
  const initialProps: Record<string, unknown> = {
    ...staticProps,
    ...eventProps,
  };
  const motionGesture = elementMotionGestureDescriptor(
    node,
    scope,
    env.component.ir,
  );
  if (motionGesture) {
    staticProps.__exactMotionGesture = motionGesture;
    initialProps.__exactMotionGesture = motionGesture;
  }
  const motionDragPresentation = elementMotionDragPresentationProp(
    node,
    scope,
    env.component.ir,
  );
  if (motionDragPresentation) {
    staticProps.__exactMotionDragPresentation = motionDragPresentation;
    initialProps.__exactMotionDragPresentation = motionDragPresentation;
  }
  if (
    !hasDynamic &&
    (Object.keys(staticStyle).length > 0 ||
      Object.keys(staticAttrStyle).length > 0)
  ) {
    initialProps.style = { ...staticStyle, ...staticAttrStyle };
  }
  if (mergeCapture) {
    for (const sink of channelStyleSinks) {
      mergeCapture.declareTemporalWriter(sink.styleProp, "channel");
    }
    for (const sink of motionStyleSinks) {
      mergeCapture.declareTemporalWriter(sink.styleProp, "motion");
    }
    if (!hasDynamic) {
      mergeCapture.commit({
        loweringDefault: mergeLoweringLayer ?? {},
        styleSource: mergeHasStyleSource ? (mergeStaticStyleSource ?? {}) : null,
        authoredAttr: { ...staticAttrStyle },
        merged: { ...staticStyle, ...staticAttrStyle },
      });
    }
  }

  const element = createInstance(lowering.tag, initialProps);
  registerElementMotionScrollBinding(
    node,
    element,
    scope,
    env.component.ir,
    env.ctx,
  );
  registerElementMotionCommandWitness(node, element, scope, env.ctx);
  if (mergeCapture) {
    getOwner()?.register(mergeCapture.attach(element));
  }
  // The sortable drag session (auto-scroll, cross-list hit testing) reads
  // and writes the owning scroller through the active host's adapter.
  // Resolution is lazy: web registers adapters as elements materialize;
  // hosts without one degrade to the translation-only session math.
  let disposed = false;
  let sortableCollectionPublished = false;
  let pendingSortableRows:
    | Array<{ key: string | number; index: number; itemCount: number }>
    | null = null;
  let restorationPublished = false;
  let pendingRestorationSeed: ContractListRestorationSeed | null = null;
  registerHydrationActivation(env.ctx, () => {
    if (!disposed) {
      if (sortable) {
        sortable.__exactClaimCollection(sortableOwner);
        sortableCollectionPublished = true;
        if (pendingSortableRows) {
          sortable.__exactUpdateCollection(pendingSortableRows);
          pendingSortableRows = null;
        }
      }
      if (precomputedRestorationSeed) {
        consumePrecomputedContractListRestorationSeed(listId);
      }
      restorationPublished = true;
      if (pendingRestorationSeed) {
        updateContractListRestorationSeed(
          restorationIdentity,
          pendingRestorationSeed,
        );
        pendingRestorationSeed = null;
      }
      sortable?.__exactAttachScrollHost(() =>
        resolveHostMotionSortableScrollHost(element),
      );
    }
  }, env.instance.effectScope);
  recordHydrationElement(env, element, structuralId, hydrationNodeId);
  recordHydrationHandlers(
    env,
    element,
    node.events,
    structuralId,
    hydrationNodeId,
  );
  insertNode(parent, element, anchor());
  let lastProps = initialProps;
  const patchElement = (next: Record<string, unknown>): void => {
    updateInstanceProps(element, lastProps, next);
    lastProps = next;
  };

  // Registered BEFORE the attr effect and row mounts: a throw while
  // evaluating either must not leak the inserted element into the committed
  // tree — the owner's disposal removes it (keep-last-good, ENG-22443).
  let content: ElementNode | null = null;
  let rowsMounted: Mounted | null = null;
  const dispose = (): void => {
    if (disposed) {
      return;
    }
    disposed = true;
    rowsMounted?.dispose();
    geometryMailbox.dispose();
    refreshState.dispose();
    if (restorationPublished) {
      removeContractListRestorationSeed(restorationIdentity);
    }
    sortable?.__exactAttachScrollHost(null);
    if (sortableCollectionPublished) {
      sortable?.__exactReleaseCollection(sortableOwner);
    }
    if (content) {
      removeChild(element, content);
    }
    removeChild(parent, element);
  };
  getOwner()?.register(dispose);

  if (hasDynamic) {
    const attrLocus = viewNodeLocus(env, node);
    ownedEffect(
      () =>
        runWithContractErrorLocus(attrLocus, () => {
          const style: Record<string, unknown> = { ...staticStyle };
          let dynamicStyleObjectValue: unknown;
          if (dynamicStyleObject) {
            dynamicStyleObjectValue = evalRuntimeExpr(
              dynamicStyleObject,
              scope,
              VIEW_EVAL,
            );
            applyStyleObject(style, dynamicStyleObjectValue);
          }
          Object.assign(style, staticAttrStyle);
          const mergeAuthoredLayer = mergeCapture
            ? { ...staticAttrStyle }
            : null;
          for (const entry of dynamicStyle) {
            const entryValue = transformLoweredStyleValue(
              entry.styleProp,
              evalRuntimeExpr(entry.expr, scope, VIEW_EVAL),
            );
            applyStyleValue(style, entry.styleProp, entryValue);
            if (mergeAuthoredLayer) {
              applyStyleValue(mergeAuthoredLayer, entry.styleProp, entryValue);
            }
          }
          if (mergeCapture) {
            const mergeStyleSourceLayer = {
              ...(mergeStaticStyleSource ?? {}),
            };
            if (dynamicStyleObject) {
              applyStyleObject(mergeStyleSourceLayer, dynamicStyleObjectValue);
            }
            mergeCapture.commit({
              loweringDefault: mergeLoweringLayer ?? {},
              styleSource:
                mergeHasStyleSource || dynamicStyleObject !== null
                  ? mergeStyleSourceLayer
                  : null,
              authoredAttr: mergeAuthoredLayer ?? {},
              merged: style,
              // LLP 0398 P3 — raw expression value, identity preserved (the
              // collection merge path joins exactly like the element path).
              ...(dynamicStyleObject !== null
                ? { styleSourceValue: dynamicStyleObjectValue }
                : {}),
            });
          }
          const next: Record<string, unknown> = {
            ...lastProps,
            ...staticProps,
            ...eventProps,
            style,
          };
          for (const entry of dynamicProps) {
            const rawValue = evalRuntimeExpr(entry.expr, scope, VIEW_EVAL);
            next[entry.hostProp] = entry.map ? entry.map(rawValue) : rawValue;
          }
          patchElement(next);
        }),
      viewReactiveOptions(env, node, "collection props"),
    );
  }

  if (channelStyleSinks.length > 0) {
    wireChannelStyleSinks(
      channelStyleSinks,
      element,
      scope,
      env.ctx,
      viewNodeLocus(env, node),
      (styleProp, value) => {
        staticAttrStyle[styleProp] = value;
        mergeCapture?.recordTemporalWrite(styleProp, "channel", value);
        const style = {
          ...((lastProps.style as Record<string, unknown> | undefined) ?? {}),
          [styleProp]: value,
        };
        patchElement({ ...lastProps, style });
      },
    );
  }

  if (motionStyleSinks.length > 0) {
    wireMotionStyleSinks(
      motionStyleSinks,
      element,
      scope,
      env.component,
      env.instance,
      env.ctx,
      viewNodeLocus(env, node),
      (styleProp, value) => {
        staticAttrStyle[styleProp] = value;
        mergeCapture?.recordTemporalWrite(styleProp, "motion", value);
        const style = {
          ...((lastProps.style as Record<string, unknown> | undefined) ?? {}),
          [styleProp]: value,
        };
        patchElement({ ...lastProps, style });
      },
    );
  }

  let collectionParent: HostParent = element;
  let contentLastProps: Record<string, unknown> | null = null;
  if (node.tag === "virtualList") {
    // @ref LLP 0088#host-mapping — the virtualizer's geometry wrapper is not
    // an authored collection item.
    // Keep it transparent to ARIA so list/listbox ownership reaches the
    // generated row wrappers (or their authored option descendants).
    contentLastProps = {
      accessibilityRole: "presentation",
      style: horizontal
        ? { position: "relative", width: 0, height: "100%" }
        : { position: "relative", height: 0 },
    };
    const contentStructuralId = structuralId
      ? contractHydrationSyntheticStructuralId(
          structuralId,
          "virtual-content",
        )
      : undefined;
    const contentHydrationNodeId = applyHydrationElementProps(
      env,
      contentStructuralId,
      contentLastProps,
    );
    content = createInstance("View", contentLastProps);
    appendChild(element, content);
    recordHydrationElement(
      env,
      content,
      contentStructuralId,
      contentHydrationNodeId,
    );
    collectionParent = content;
  }

  rowsMounted = mountCollectionRows(node, collectionParent, null, env, mountNodes, {
    patchElement,
    lastElementProps: () => lastProps,
    patchContentStyle(totalSize) {
      if (!content || !contentLastProps) {
        return;
      }
      const next = {
        ...contentLastProps,
        style: horizontal
          ? { position: "relative", width: totalSize, height: "100%" }
          : { position: "relative", height: totalSize },
      };
      updateInstanceProps(content, contentLastProps, next);
      contentLastProps = next;
    },
    readGeometry: () => geometry.get(),
    onRecords(records) {
      latestReachSnapshot = records;
    },
    restorationIdentity,
    listId,
    precomputedRestorationSeed,
    sortable,
    publishSortableRows(rows) {
      if (!sortable) return;
      if (sortableCollectionPublished) {
        sortable.__exactUpdateCollection(rows);
      } else {
        pendingSortableRows = rows;
      }
    },
    publishRestorationSeed(seed) {
      if (restorationPublished) {
        updateContractListRestorationSeed(restorationIdentity, seed);
      } else {
        pendingRestorationSeed = seed;
      }
    },
    isTailFollowing: () => tailFollowing,
    setTailFollowing(value) {
      tailFollowing = value;
    },
    horizontal,
  });

  return {
    hostNodes: () => (disposed ? [] : [element]),
    dispose,
  };
}

function mountCollectionRows(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  parent: HostParent,
  anchor: AnchorFn | null,
  env: MountEnv,
  mountNodes: (
    nodes: readonly ViewNodeIR[],
    parent: HostParent,
    anchor: AnchorFn | null,
    env: MountEnv,
  ) => Mounted,
  patches: {
    patchElement(next: Record<string, unknown>): void;
    lastElementProps(): Record<string, unknown>;
    patchContentStyle(totalSize: number): void;
    readGeometry(): { offset: number; viewport: number; interacted: boolean };
    onRecords(records: {
      totalSize: number;
      visibleStartIndex: number;
      visibleEndIndex: number;
      itemCount: number;
    }): void;
    restorationIdentity: string;
    listId: string;
    precomputedRestorationSeed: ContractListRestorationSeed | undefined;
    sortable: ContractSortableListController | null;
    publishSortableRows(
      rows: Array<{ key: string | number; index: number; itemCount: number }>,
    ): void;
    publishRestorationSeed(seed: ContractListRestorationSeed): void;
    isTailFollowing(): boolean;
    setTailFollowing(value: boolean): void;
    horizontal: boolean;
  },
): Mounted {
  const itemName = collectionBindingName(node.props.as, env.scope, "item");
  const indexName = node.props.index
    ? collectionBindingName(node.props.index, env.scope, "index")
    : null;
  const keyExpr = node.props.key ?? null;
  const virtualized = node.tag === "virtualList";
  const rowWrapperRole = literalStringProp(node.props.role) === "listbox"
    ? "presentation"
    : "listitem";
  const sortable = patches.sortable;
  let rows: CollectionMountedRow[] = [];
  let preparedCache: VirtualListPreparedCache | null = null;
  let disposed = false;
  let warnedDuplicateKeys = false;
  let initialScrollCommandIssued = false;
  let tailFollowWasEnabled = false;
  let lastObservedTotalSize = -1;
  const producerGeneration = allocateContractListProducerGeneration();
  let scrollCommandSeq = 0;

  const keyFor = (item: unknown, index: number): unknown => {
    if (!keyExpr) {
      return index;
    }
    const keyScope = env.scope.child();
    keyScope.defineValue(itemName, item);
    if (indexName) {
      keyScope.defineValue(indexName, index);
    }
    return evalRuntimeExpr(keyExpr, keyScope, VIEW_EVAL);
  };

  const createRow = (
    item: unknown,
    index: number,
    key: unknown,
    frame: VirtualListItem | null,
    itemCount: number,
  ): CollectionMountedRow => {
    const owner = createOwner();
    const ownerStructuralId = env.ids.get(node);
    const rowStructuralId = ownerStructuralId
      ? contractHydrationSyntheticStructuralId(
          ownerStructuralId,
          "collection-row",
        )
      : undefined;
    const rowEnv = {
      ...env,
      hydrationKeyChain: `${env.hydrationKeyChain}#${String(key)}`,
    };
    const wrapperInitial = collectionRowProps(
      key,
      index,
      frame,
      itemCount,
      sortable !== null,
      rowWrapperRole,
      patches.horizontal,
    );
    const rowHydrationNodeId = applyHydrationElementProps(
      rowEnv,
      rowStructuralId,
      wrapperInitial,
    );
    const wrapper = createInstance("View", wrapperInitial);
    let lastWrapperProps = wrapperInitial;
    insertNode(parent, wrapper, anchor ? anchor() : null);
    recordHydrationElement(
      rowEnv,
      wrapper,
      rowStructuralId,
      rowHydrationNodeId,
    );
    // Registered BEFORE mounting children so a mid-mount throw still removes
    // the wrapper when the owner disposes (keep-last-good, ENG-22443).
    owner.register(() => {
      removeChild(parent, wrapper);
    });
    let disposeSortableGap: (() => void) | null = null;
    let sortableRowTransform: string | null = null;
    const updateSortable = (logicalIndex: number): void => {
      if (!sortable) return;
      disposeSortableGap?.();
      disposeSortableGap = registerSortablePresentationBinding(
        wrapper,
        sortable,
        logicalIndex,
        "gap",
        `${env.instance.runtimeInstanceId ?? env.component.name}:${String(key)}`,
        (value) => {
          const transform = sortableTransform(sortable.axis, value);
          sortableRowTransform = transform;
          if (applyHostChannelStyle(wrapper, "transform", transform)) return;
          const next = {
            ...lastWrapperProps,
            style: {
              ...((lastWrapperProps.style as
                Record<string, unknown> | undefined) ?? {}),
              transform,
            },
          };
          updateInstanceProps(wrapper, lastWrapperProps, next);
          lastWrapperProps = next;
        },
      );
    };
    let sortableActivationLive = false;
    let pendingSortableIndex = index;
    registerHydrationActivation(env.ctx, () => {
      sortableActivationLive = true;
      updateSortable(pendingSortableIndex);
    }, env.instance.effectScope);
    owner.register(() => {
      sortableActivationLive = false;
      disposeSortableGap?.();
    });

    let row: CollectionMountedRow;
    try {
      row = runWithOwner(owner, () => {
        const itemSignal = signal<unknown>(item);
        const indexSignal = signal<number>(index);
        const rowScope = env.scope.child();
        rowScope.define(itemName, {
          kind: "getter",
          get: () => itemSignal.get(),
        });
        if (indexName) {
          rowScope.define(indexName, {
            kind: "getter",
            get: () => indexSignal.get(),
          });
        }
        const mounted = mountNodes(node.children, wrapper, null, {
          ...env,
          scope: rowScope,
          isRootView: false,
          inRepetitionScope: true,
          repetitionIndex: index,
          keyChain: `${env.keyChain}#${String(key)}`,
          logicalKeyPath: [...env.logicalKeyPath, logicalKeySegment(key)],
          hydrationKeyChain: `${env.hydrationKeyChain}#${String(key)}`,
        });
        owner.register(() => {
          mounted.dispose();
        });
        return {
          key,
          wrapper,
          owner,
          setItem(value: unknown) {
            itemSignal.set(value);
          },
          setIndex(value: number) {
            indexSignal.set(value);
            pendingSortableIndex = value;
            if (sortableActivationLive) updateSortable(value);
          },
          updateFrame(
            nextFrame: VirtualListItem | null,
            nextItemCount: number,
          ) {
            const next = collectionRowProps(
              key,
              indexSignal.get(),
              nextFrame,
              nextItemCount,
              sortable !== null,
              rowWrapperRole,
              patches.horizontal,
            );
            applyHydrationElementProps(rowEnv, rowStructuralId, next);
            if (sortableRowTransform !== null) {
              next.style = {
                ...((next.style as Record<string, unknown> | undefined) ?? {}),
                transform: sortableRowTransform,
              };
            }
            updateInstanceProps(wrapper, lastWrapperProps, next);
            lastWrapperProps = next;
            if (sortableRowTransform !== null) {
              applyHostChannelStyle(wrapper, "transform", sortableRowTransform);
            }
          },
        };
      });
    } catch (error) {
      owner.dispose();
      throw error;
    }
    return row;
  };

  const collectionLocus = viewNodeLocus(env, node, `${node.tag} items`);
  ownedEffect(
    () =>
      runWithContractErrorLocus(collectionLocus, () => {
        const rawItems = evalRuntimeExpr(
          node.props.items,
          env.scope,
          VIEW_EVAL,
        );
        const allItems = Array.isArray(rawItems) ? rawItems : [];
        const tailFollowEnabled = booleanProp(
          node.props.stickToBottom,
          env.scope,
          false,
        );
        if (tailFollowEnabled && !tailFollowWasEnabled) {
          patches.setTailFollowing(true);
        } else if (!tailFollowEnabled) {
          patches.setTailFollowing(false);
        }
        tailFollowWasEnabled = tailFollowEnabled;
        const records = virtualized
          ? computeVirtualRecords(
              node,
              env,
              allItems,
              keyFor,
              preparedCache,
              (next) => {
                preparedCache = next;
              },
              patches.readGeometry(),
              patches.precomputedRestorationSeed,
              tailFollowEnabled && patches.isTailFollowing(),
            )
          : {
              totalSize: allItems.length,
              items: allItems.map((item, index) => ({
                item,
                index,
                key: keyFor(item, index),
                frame: null,
              })),
              diagnostics: {
                itemCount: allItems.length,
                mountedItemCount: allItems.length,
                visibleStartIndex: allItems.length > 0 ? 0 : -1,
                visibleEndIndex: allItems.length > 0 ? allItems.length - 1 : -1,
                overscanStartIndex: allItems.length > 0 ? 0 : -1,
                overscanEndIndex:
                  allItems.length > 0 ? allItems.length - 1 : -1,
              },
              restorationSeed: undefined,
            };

        if (sortable) {
          const nextSortableRows = allItems.map((item, index) => ({
            key: keyFor(item, index) as string | number,
            index,
            itemCount: allItems.length,
          }));
          untrack(() => {
            patches.publishSortableRows(nextSortableRows);
          });
        }

        untrack(() => {
          if (disposed) {
            return;
          }

          patches.patchContentStyle(records.totalSize);
          patches.onRecords({
            totalSize: records.totalSize,
            visibleStartIndex: records.diagnostics.visibleStartIndex,
            visibleEndIndex: records.diagnostics.visibleEndIndex,
            itemCount: records.diagnostics.itemCount,
          });
          if (records.restorationSeed) {
            const nextRestorationSeed = {
              listId: patches.listId,
              ...records.restorationSeed,
            };
            patches.publishRestorationSeed(nextRestorationSeed);
          }
          const needsInitialScrollCommand =
            !initialScrollCommandIssued &&
            (node.props.initialScrollOffset !== undefined ||
              node.props.initialScrollKey !== undefined ||
              patches.precomputedRestorationSeed !== undefined) &&
            records.restorationSeed;
          const needsTailFollowCommand =
            tailFollowEnabled &&
            patches.isTailFollowing() &&
            records.restorationSeed !== undefined &&
            records.totalSize !== lastObservedTotalSize;
          let scrollCommand: string | undefined;
          if (needsInitialScrollCommand || needsTailFollowCommand) {
            scrollCommandSeq += 1;
            scrollCommand = JSON.stringify({
              producerGeneration,
              seq: scrollCommandSeq,
              interactionEpoch: scrollCommandSeq,
              ...(patches.horizontal
                ? { x: records.restorationSeed!.scrollOffset }
                : { y: records.restorationSeed!.scrollOffset }),
              animated: false,
            });
          }
          initialScrollCommandIssued = true;
          lastObservedTotalSize = records.totalSize;
          patches.patchElement({
            ...patches.lastElementProps(),
            virtualized,
            itemCount: records.diagnostics.itemCount,
            mountedItemCount: records.diagnostics.mountedItemCount,
            visibleStartIndex: records.diagnostics.visibleStartIndex,
            visibleEndIndex: records.diagnostics.visibleEndIndex,
            overscanStartIndex: records.diagnostics.overscanStartIndex,
            overscanEndIndex: records.diagnostics.overscanEndIndex,
            totalSize: records.totalSize,
            agentSemantics: collectionAgentSemantics({
              logicalItemCount: records.diagnostics.itemCount,
              mountedItemCount: records.diagnostics.mountedItemCount,
              virtualized,
              nativeHost: false,
            }),
            ...(scrollCommand
              ? { scrollCommand }
              : {}),
          });

          // Queue per key (ENG-23170): same duplicate-key round-trip as mountEach
          // — a plain Map drops all but the last duplicate, leaking live rows.
          const oldByKey = new Map<unknown, CollectionMountedRow[]>();
          for (const row of rows) {
            const queue = oldByKey.get(row.key);
            if (queue) {
              queue.push(row);
            } else {
              oldByKey.set(row.key, [row]);
            }
          }

          const nextRows: CollectionMountedRow[] = [];
          const createdRows: CollectionMountedRow[] = [];
          const seen = new Set<unknown>();
          let orderChanged = records.items.length !== rows.length;
          try {
            for (const record of records.items) {
              if (seen.has(record.key) && !warnedDuplicateKeys) {
                warnedDuplicateKeys = true;
                console.warn(
                  `[contract] duplicate ${node.tag} key ${String(record.key)}; rows need unique keys`,
                );
              }
              seen.add(record.key);
              const queue = oldByKey.get(record.key);
              const existing = queue?.shift();
              if (existing) {
                if (queue!.length === 0) {
                  oldByKey.delete(record.key);
                }
                existing.setItem(record.item);
                existing.setIndex(record.index);
                existing.updateFrame(
                  record.frame,
                  records.diagnostics.itemCount,
                );
                orderChanged ||= existing !== rows[nextRows.length];
                nextRows.push(existing);
              } else {
                orderChanged = true;
                const created = createRow(
                  record.item,
                  record.index,
                  record.key,
                  record.frame,
                  records.diagnostics.itemCount,
                );
                createdRows.push(created);
                nextRows.push(created);
              }
            }
          } catch (error) {
            // Keep-last-good (ENG-22443): see mountEach — drop only the rows
            // created this pass, keep the committed ones.
            for (const created of createdRows) {
              created.owner.dispose();
            }
            throw error;
          }

          for (const queue of oldByKey.values()) {
            for (const removed of queue) {
              removed.owner.dispose();
            }
          }

          rows = nextRows;
          if (orderChanged) {
            let nextAnchor: HostNode | null = anchor ? anchor() : null;
            for (let i = rows.length - 1; i >= 0; i -= 1) {
              const row = rows[i];
              if (nextAnchor) {
                insertBefore(parent, row.wrapper, nextAnchor);
              } else {
                appendChild(parent, row.wrapper);
              }
              nextAnchor = row.wrapper;
            }
          }
        });
      }),
    viewReactiveOptions(env, node, `${node.tag} items`),
  );

  const dispose = (): void => {
    if (disposed) {
      return;
    }
    disposed = true;
    for (const row of rows) {
      row.owner.dispose();
    }
    rows = [];
  };

  return { hostNodes: () => rows.map((row) => row.wrapper), dispose };
}

function collectionBindingName(
  expr: Expr | undefined,
  scope: Scope,
  fallback: string,
): string {
  if (!expr) {
    return fallback;
  }
  const value = evalRuntimeExpr(expr, scope, VIEW_EVAL);
  return typeof value === "string" && value.length > 0 ? value : fallback;
}

function computeVirtualRecords(
  node: Extract<ViewNodeIR, { kind: "element" }>,
  env: MountEnv,
  allItems: unknown[],
  keyFor: (item: unknown, index: number) => unknown,
  cache: VirtualListPreparedCache | null,
  setCache: (next: VirtualListPreparedCache) => void,
  geometry: { offset: number; viewport: number; interacted: boolean },
  precomputedRestorationSeed: ContractListRestorationSeed | undefined,
  tailFollowing: boolean,
): {
  totalSize: number;
  items: Array<{
    item: unknown;
    index: number;
    key: unknown;
    frame: VirtualListItem | null;
  }>;
  diagnostics: {
    itemCount: number;
    mountedItemCount: number;
    visibleStartIndex: number;
    visibleEndIndex: number;
    overscanStartIndex: number;
    overscanEndIndex: number;
  };
  restorationSeed?: {
    scrollOffset: number;
    anchor?: { itemKey: string; offsetInItem?: number };
    measurements: {
      entries: Array<{ key: string; size: number; type?: string | null }>;
    };
  };
} {
  const estimate = numberProp(
    node.props.estimateSize ?? node.props.estimatedItemSize,
    env.scope,
    64,
  );
  const viewportSize = numberProp(
    node.props.viewportSize,
    env.scope,
    geometry.viewport > 0 ? geometry.viewport : estimate * 8,
  );
  const scrollOffset = node.props.scrollOffset
    ? numberProp(node.props.scrollOffset, env.scope, 0)
    : geometry.offset;
  const drawDistance = numberProp(
    node.props.overscan ?? node.props.drawDistance,
    env.scope,
    estimate * 2,
  );
  let prepared =
    cache?.items === allItems && cache.estimate === estimate
      ? cache.prepared
      : null;
  if (!prepared) {
    const keys = allItems.map((item, index) => String(keyFor(item, index)));
    const rawMeasurements = node.props.initialMeasurements
      ? evalRuntimeExpr(node.props.initialMeasurements, env.scope, VIEW_EVAL)
      : precomputedRestorationSeed?.measurements;
    prepared = prepareVirtualList({
      count: allItems.length,
      estimatedItemSize: estimate,
      measurements: measurementsFromSnapshot(
        rawMeasurements && typeof rawMeasurements === "object"
          ? (rawMeasurements as ListMeasurementSnapshot)
          : undefined,
      ),
      getKey: (index) => keys[index] ?? String(index),
    });
    setCache({ items: allItems, estimate, prepared });
  }
  let resolvedScrollOffset = scrollOffset;
  if (tailFollowing && node.props.scrollOffset === undefined) {
    resolvedScrollOffset = Math.max(0, prepared.totalSize - viewportSize);
  } else if (
    !geometry.interacted &&
    node.props.scrollOffset === undefined &&
    node.props.initialScrollKey
  ) {
    const rawInitialKey = evalRuntimeExpr(
      node.props.initialScrollKey,
      env.scope,
      VIEW_EVAL,
    );
    const initialIndex = prepared.keyIndex.get(String(rawInitialKey));
    if (initialIndex !== undefined) {
      resolvedScrollOffset =
        prepared.records[initialIndex]?.start ?? resolvedScrollOffset;
    }
  } else if (
    !geometry.interacted &&
    node.props.scrollOffset === undefined &&
    precomputedRestorationSeed?.anchor
  ) {
    const initialIndex = prepared.keyIndex.get(
      precomputedRestorationSeed.anchor.itemKey,
    );
    if (initialIndex !== undefined) {
      resolvedScrollOffset =
        (prepared.records[initialIndex]?.start ?? resolvedScrollOffset) +
        (precomputedRestorationSeed.anchor.offsetInItem ?? 0);
    }
  }
  const output = computeVirtualItemsFromPrepared(prepared, {
    scrollOffset: resolvedScrollOffset,
    viewportSize,
    drawDistance,
  });
  return {
    totalSize: output.totalSize,
    items: output.items.map((frame) => ({
      item: allItems[frame.index],
      index: frame.index,
      key: frame.key,
      frame,
    })),
    diagnostics: output.diagnostics,
    restorationSeed: {
      scrollOffset: resolvedScrollOffset,
      anchor:
        output.visibleRange.startIndex >= 0
          ? {
              itemKey:
                prepared.records[output.visibleRange.startIndex]?.key ?? "",
              offsetInItem: Math.max(
                0,
                resolvedScrollOffset -
                  (prepared.records[output.visibleRange.startIndex]?.start ??
                    resolvedScrollOffset),
              ),
            }
          : undefined,
      measurements: {
        entries: output.items.map((item) => ({
          key: item.key,
          size: item.size,
          type: item.type,
        })),
      },
    },
  };
}

function numberProp(
  expr: Expr | undefined,
  scope: Scope,
  fallback: number,
): number {
  if (!expr) {
    return fallback;
  }
  const value = evalRuntimeExpr(expr, scope, VIEW_EVAL);
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}

function booleanProp(
  expr: Expr | undefined,
  scope: Scope,
  fallback: boolean,
): boolean {
  if (!expr) {
    return fallback;
  }
  const value = evalRuntimeExpr(expr, scope, VIEW_EVAL);
  return typeof value === "boolean" ? value : fallback;
}

function literalStringProp(expr: Expr | undefined): string | undefined {
  return expr?.kind === "string" && expr.value.length > 0
    ? expr.value
    : undefined;
}

function collectionGeometryFromPayload(
  payload: unknown,
  listId: string,
  fallback: { offset: number; viewport: number },
  horizontal = false,
) {
  const envelope =
    payload && typeof payload === "object"
      ? (payload as Record<string, unknown>)
      : {};
  const nativeEvent =
    envelope.nativeEvent && typeof envelope.nativeEvent === "object"
      ? (envelope.nativeEvent as Record<string, unknown>)
      : envelope;
  const offsetValue =
    nativeEvent.contentOffset && typeof nativeEvent.contentOffset === "object"
      ? (nativeEvent.contentOffset as Record<string, unknown>)[
          horizontal ? "x" : "y"
        ]
      : nativeEvent.offset;
  const viewportValue =
      nativeEvent.layoutMeasurement &&
      typeof nativeEvent.layoutMeasurement === "object"
      ? (nativeEvent.layoutMeasurement as Record<string, unknown>)[
          horizontal ? "width" : "height"
        ]
      : nativeEvent.viewport;
  const source =
    nativeEvent.source === "command" || nativeEvent.source === "restore"
      ? nativeEvent.source
      : "user";
  return {
    listId,
    offset:
      typeof offsetValue === "number" && Number.isFinite(offsetValue)
        ? offsetValue
        : fallback.offset,
    viewport:
      typeof viewportValue === "number" && Number.isFinite(viewportValue)
        ? viewportValue
        : fallback.viewport,
    source,
    geometrySeq:
      typeof nativeEvent.geometrySeq === "number"
        ? nativeEvent.geometrySeq
        : undefined,
    velocity:
      typeof nativeEvent.velocity === "number"
        ? nativeEvent.velocity
        : undefined,
    interactionEpoch:
      typeof nativeEvent.interactionEpoch === "number"
        ? nativeEvent.interactionEpoch
        : undefined,
    timestamp:
      typeof nativeEvent.timestamp === "number"
        ? nativeEvent.timestamp
        : undefined,
  } as const;
}

function collectionRefreshPayload(
  payload: unknown,
  context: CollectionRefreshContext,
): Record<string, unknown> {
  const envelope =
    payload !== null && typeof payload === "object" && !Array.isArray(payload)
      ? (payload as Record<string, unknown>)
      : { nativeEvent: payload };
  return {
    ...envelope,
    refreshId: context.refreshId,
    signal: context.signal,
  };
}

function collectionRowProps(
  key: unknown,
  index: number,
  frame: VirtualListItem | null,
  itemCount: number,
  animateSortable: boolean,
  accessibilityRole: "listitem" | "presentation",
  horizontal = false,
): Record<string, unknown> {
  const props: Record<string, unknown> = {
    rowKey: String(key),
    rowIndex: index,
    accessibilityRole,
    accessibilityPosInSet: index + 1,
    accessibilitySetSize: itemCount,
  };
  if (frame) {
    props.style = horizontal
      ? {
          position: "absolute",
          top: 0,
          bottom: 0,
          left: frame.start,
          width: frame.size,
        }
      : {
          position: "absolute",
          top: frame.start,
          left: 0,
          right: 0,
          height: frame.size,
        };
  }
  if (animateSortable) {
    props.style = {
      ...((props.style as Record<string, unknown> | undefined) ?? {}),
      transition: {
        transform: { type: "timing", duration: 200, easing: "easeInOut" },
      },
    };
  }
  return props;
}

function isLiteral(
  expr: Expr,
): expr is Extract<Expr, { kind: "string" | "number" | "boolean" | "null" }> {
  return (
    expr.kind === "string" ||
    expr.kind === "number" ||
    expr.kind === "boolean" ||
    expr.kind === "null"
  );
}

function literalStyleObjectValue(
  expr: Expr | undefined,
  styleProp: string,
  scope: Scope,
): unknown {
  if (
    !expr ||
    expr.kind !== "object" ||
    expr.entries.some((entry) => isExprSpread(entry) || !isLiteral(entry.value))
  ) {
    return undefined;
  }
  const style: Record<string, unknown> = {};
  applyStyleObject(style, evalRuntimeExpr(expr, scope, VIEW_EVAL));
  return style[styleProp];
}

function makeHandler(
  handlerExpr: Expr,
  scope: Scope,
  locus?: ContractErrorLocus,
  interaction?: { instance: ComponentInstance; id: string },
): (...args: unknown[]) => void {
  return (...args: unknown[]) => {
    try {
      const invoke = (): void => {
        if (handlerExpr.kind === "call") {
          // press=remove(item.id): evaluate the call at event time (args bound
          // from the view scope); the event payload is not forwarded.
          untrack(() => evalRuntimeExpr(handlerExpr, scope));
          return;
        }
        const handler = untrack(() => evalRuntimeExpr(handlerExpr, scope));
        if (typeof handler === "function") handler(...args);
      };
      if (interaction) {
        runWithInteractionDispatchForExpr(
          interaction.instance,
          handlerExpr,
          "press",
          interaction.id,
          1,
          invoke,
          scope,
        );
      } else {
        invoke();
      }
    } catch (error) {
      // ENG-22443: the event dispatch boundary is where a sync action error
      // leaves the runtime (nothing above will catch it) — report it with
      // its authored locus (deduped), then stay loud.
      if (locus) {
        decorateContractError(error, locus);
      }
      reportContractRuntimeError(error);
      throw error;
    }
  };
}

function makeCompletionHandler(
  handlerExpr: Expr,
  scope: Scope,
  locus?: ContractErrorLocus,
): (...args: unknown[]) => unknown {
  return (...args: unknown[]) => {
    try {
      if (handlerExpr.kind === "call") {
        return untrack(() => evalRuntimeExpr(handlerExpr, scope));
      }
      const handler = untrack(() => evalRuntimeExpr(handlerExpr, scope));
      return typeof handler === "function" ? handler(...args) : undefined;
    } catch (error) {
      if (locus) {
        decorateContractError(error, locus);
      }
      reportContractRuntimeError(error);
      throw error;
    }
  };
}

function mountText(
  node: Extract<ViewNodeIR, { kind: "text" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  const { scope } = env;
  const expr = node.expr;
  const structuralId = env.ids.get(node) ?? null;
  const valueOrEvaluate = isLiteral(expr)
    ? expr.kind === "null" ? null : expr.value
    : (activeScope: Scope, options: typeof VIEW_EVAL) =>
        evalRuntimeExpr(expr, activeScope, options);
  const plan: ContractAotTextPlan = expr.kind === "token"
    ? [
        valueOrEvaluate,
        node.span.line,
        node.span.col,
        node.span.len,
        node.span.offset,
        expr.path,
      ]
    : [
        valueOrEvaluate,
        node.span.line,
        node.span.col,
        node.span.len,
        node.span.offset,
      ];
  return mountContractText(
    plan,
    node,
    parent,
    anchor,
    env,
    CONTRACT_VIEW_DEV
      ? (textNode: TextNode) => {
            attachTextProvenance(textNode, expr, scope, env, node.span?.line);
            if (structuralId) {
              const owner = getOwner();
              registerHydrationActivation(env.ctx, () => {
                const unregister = registerLiveNode({
                  ...liveNodeRegistrationIdentity(env),
                  structuralId,
                  sourcePath: env.component.file.sourcePath,
                  sourceVersion: env.component.file.sourceVersion,
                  host: textNode,
                  patch: {
                    kind: "text" as const,
                    setText(value: string) {
                      updateTextContent(textNode, value);
                    },
                  },
                });
                owner?.register(unregister);
              });
            }
          }
      : undefined,
    env.instance.def.runtime.temporal
      ? (textNode: TextNode) => {
            return env.instance.def.runtime.temporal!.installText({
              expr,
              scope,
              textNode,
              locus: viewNodeLocus(env, node, "temporal text binding"),
              reactiveOptions: viewReactiveOptions(env, node, "temporal text binding"),
            });
          }
      : undefined,
  );
}

// ---------------------------------------------------------------------------
// Regions: when / each / resource / boundary
// ---------------------------------------------------------------------------

function mountWhen(
  node: Extract<ViewNodeIR, { kind: "when" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  return mountContractWhen(
    [
      (scope, options) => evalRuntimeExpr(node.test, scope, options),
      node.span.line,
      node.span.col,
      node.span.len,
      node.span.offset,
    ],
    node,
    node.then,
    node.else,
    parent,
    anchor,
    env,
    mountViewNodes,
  );
}

function mountMatch(
  node: Extract<ViewNodeIR, { kind: "match" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  return mountContractMatch(
    [
      (scope, options) => evalRuntimeExpr(node.expr, scope, options),
      node.cases.map((entry) =>
        (scope, options) => evalRuntimeExpr(entry.test, scope, options)
      ),
      node.span.line,
      node.span.col,
      node.span.len,
      node.span.offset,
    ],
    node,
    node.cases,
    node.else,
    parent,
    anchor,
    env,
    mountViewNodes,
  );
}

function mountMatchSize(
  node: Extract<ViewNodeIR, { kind: "match-size" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  return mountContractMatchSize(
    [
      node.cases.map((entry) => entry.value),
      node.span.line,
      node.span.col,
      node.span.len,
      node.span.offset,
    ],
    node,
    node.cases,
    node.else,
    parent,
    anchor,
    env,
    mountViewNodes,
  );
}

function mountEach(
  node: Extract<ViewNodeIR, { kind: "each" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  return mountContractEach(
    [
      (scope, options) => evalRuntimeExpr(node.iterable, scope, options),
      (scope, options) => evalRuntimeExpr(node.key, scope, options),
      node.item,
      node.index ?? null,
      node.span.line,
      node.span.col,
      node.span.len,
      node.span.offset,
    ],
    node,
    node.body,
    parent,
    anchor,
    env,
    mountViewNodes,
  );
}

function mountResourceRegion(
  node: Extract<ViewNodeIR, { kind: "resource" | "async" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  return mountContractResource(
    [
      node.kind,
      node.name,
      node.slots.map((slot) => [slot.kind, slot.binding ?? null]),
      node.span.line,
      node.span.col,
      node.span.len,
      node.span.offset,
    ],
    node,
    node.slots,
    parent,
    anchor,
    env,
    mountViewNodes,
  );
}

function mountBoundary(
  node: Extract<ViewNodeIR, { kind: "boundary" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  return mountContractBoundary(
    [
      node.fallback.binding ?? null,
      node.span.line,
      node.span.col,
      node.span.len,
      node.span.offset,
    ],
    node.body,
    node.fallback.body,
    parent,
    anchor,
    env,
    mountViewNodes,
  );
}

// ---------------------------------------------------------------------------
// Components
// ---------------------------------------------------------------------------

function mountComponent(
  node: Extract<ViewNodeIR, { kind: "component" }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  const resolved = untrack(() => {
    const binding = env.scope.lookup(node.name);
    if (!binding) {
      return undefined;
    }
    return binding.kind === "value" || binding.kind === "local"
      ? binding.value
      : binding.get();
  });

  if (!isCompiledComponentValue(resolved)) {
    throw new Error(
      `[contract] "${node.name}" did not resolve to a Contract component`,
    );
  }

  // Props are reactive getters into the caller's scope; events are callback
  // props (functions) under their event names. forEach: the getter closure
  // escapes the iteration (see the Hermes for-of note in instance.ts).
  // Action-typed props (LLP 0280 §2.3) take the event wiring regardless of
  // their name, so a curried application (`confirm=save(item.id)`) is a
  // deferred thunk rather than an eager getter evaluation.
  const actionTypedPropNames = new Set(
    resolved.ir.props
      .filter((prop) => prop.parsedType?.ir.kind === "action")
      .map((prop) => prop.name),
  );
  const relayComponentHandler = (
    expr: Expr,
    locus: ContractErrorLocus,
  ): unknown => {
    // A direct CommandRef must retain its identity while crossing a Contract
    // component boundary so the child's concrete host control can register
    // as its semantic witness. This helper is deliberately scoped to
    // component callback props: host-element events still use makeHandler and
    // keep authored loci plus interaction attribution.
    if (expr.kind === "ident") {
      const candidate = untrack(() => evalRuntimeExpr(expr, env.scope));
      if (isMotionCommandRef(candidate)) return candidate;
    }
    return makeHandler(expr, env.scope, locus);
  };
  const props: Record<string, PropValue> = {};
  Object.entries(node.props).forEach(([name, expr]) => {
    if (actionTypedPropNames.has(name)) {
      props[name] = {
        kind: "value",
        value: relayComponentHandler(
          expr,
          viewNodeLocus(env, node, `action prop "${name}"`),
        ),
      };
    } else if (isLiteral(expr)) {
      props[name] = {
        kind: "value",
        value: evalRuntimeExpr(expr, env.scope, VIEW_EVAL),
      };
    } else {
      const propLocus = viewNodeLocus(env, node, `prop "${name}"`);
      props[name] = {
        kind: "getter",
        get: () =>
          runWithContractErrorLocus(propLocus, () =>
            evalRuntimeExpr(expr, env.scope, VIEW_EVAL),
          ),
      };
    }
  });
  Object.entries(node.events).forEach(([event, handlerExpr]) => {
    props[event] = {
      kind: "value",
      value: relayComponentHandler(
        handlerExpr,
        viewNodeLocus(env, node, `event "${event}"`),
      ),
    };
  });

  const callStructuralId = env.ids.get(node);
  const callHydrationNodeId =
    callStructuralId &&
    (env.ctx.hydration?.capture || env.ctx.routePayloadCapture)
      ? hydrationNodeIdFor(env, callStructuralId)
      : undefined;
  const childInstance = instantiateComponent(resolved, props, env.ctx, {
    hydrationNodeId:
      callHydrationNodeId ?? `${env.hydrationPrefix}${resolved.ir.name}/v`,
    hydrationStructuralId: callStructuralId,
    hydrationKeyChain: env.hydrationKeyChain,
    logicalInstancePath: [
      ...env.instance.logicalInstancePath,
      logicalPathSegment("call", callStructuralId ?? node.name),
      ...env.logicalKeyPath.map((key) => logicalPathSegment("key", key)),
    ],
  });

  // Caller children mount wherever the child's view places its `children`
  // slot, with the caller's scope (closure semantics).
  const childrenSlot: ChildrenSlot | null =
    node.children.length > 0
      ? (slotParent, slotAnchor) =>
          mountViewNodes(node.children, slotParent, slotAnchor, {
            ...env,
            isRootView: false,
          })
      : null;

  const mounted = runWithOwner(childInstance.owner, () =>
    mountViewNodes([resolved.ir.view], parent, anchor, {
      instance: childInstance,
      scope: childInstance.scope,
      component: resolved,
      ctx: env.ctx,
      childrenSlot,
      isRootView: env.isRootView,
      inRepetitionScope: env.inRepetitionScope,
      repetitionIndex: env.repetitionIndex,
      ids: structuralIdsFor(resolved.ir),
      keyChain: env.keyChain,
      logicalKeyPath: [],
      hydrationPrefix: callHydrationNodeId
        ? `${callHydrationNodeId}>`
        : env.hydrationPrefix,
      hydrationKeyChain: "",
      dismissLayerParentId: env.dismissLayerParentId,
    }),
  );
  childInstance.hostNodes = () => mounted.hostNodes();

  // Design Mode D0 (LLP 0158): mark the component call boundary on the
  // component's root host node (selection targets this, §7.1).
  if (CONTRACT_VIEW_DEV) {
    // On-demand clause witnessing for the exact_contract_witness agent op
    // (LLP 0293 ledger row 8): dev-only, no-op for components without a
    // `contract` block. Inside the dev gate so production list mounts pay
    // no per-instance closure or registry work.
    registerContractClauseWitnessInstance(childInstance, () =>
      mounted.hostNodes(),
    );
    const rootHost = mounted.hostNodes()[0];
    if (rootHost) {
      const propOrigins: Record<string, AttrOrigin> = {};
      for (const [name, expr] of Object.entries(node.props)) {
        const origin = classifyExpr(expr, env.scope, name);
        const rawSource = node.propSources?.[name];
        if (origin.kind === "literal" && typeof rawSource === "string") {
          origin.rawSource = rawSource;
        }
        propOrigins[name] = origin;
      }
      attachComponentBoundary(rootHost, {
        componentName: node.name,
        callSourcePath: env.component.file.sourcePath,
        callLine: node.span.line,
        definitionSourcePath: resolved.file.sourcePath,
        props: propOrigins,
      });
    }
  }

  return mounted;
}
