// @system @ref LLP 0185#432-proposed-statement-backend-decision-packet —
// Production-safe runner registry. The editable runtime installs its
// interpreter fallback separately; ordinary production has no interpreter
// import edge and fails closed when a generated runner is missing.

import type {
  ActionIR,
  ContractFileIR,
  Stmt,
  TaskIR,
} from '../compiler/ir.js';
import { CONTRACT_PRODUCTION } from './build-mode.js';
import type {
  ExecutionContinuationFence,
  Scope,
} from './execution-scope.js';

declare const __EXACT_CONTRACT_PRODUCTION__: boolean;
const CONTRACT_STATEMENTS_PRODUCTION =
  typeof __EXACT_CONTRACT_PRODUCTION__ !== 'undefined'
    ? __EXACT_CONTRACT_PRODUCTION__
    : CONTRACT_PRODUCTION;

type StatementOwner = ActionIR | TaskIR;

export type ContractAotStatementRunner = (
  scope: Scope,
  runSegment: <T>(fn: () => T) => T,
  continuationFence?: ExecutionContinuationFence,
) => unknown | Promise<unknown>;

type ContractStatementFallbackExecutor = (
  body: Stmt[],
  scope: Scope,
  runSegment: <T>(fn: () => T) => T,
  continuationFence?: ExecutionContinuationFence,
) => unknown | Promise<unknown>;

let runnersByOwner = new WeakMap<StatementOwner, ContractAotStatementRunner>();
let fallbackExecutor: ContractStatementFallbackExecutor | null = null;

export function registerContractAotStatements(
  file: ContractFileIR,
  runners: readonly ContractAotStatementRunner[],
): void {
  const owners = collectStatementOwners(file);
  if (owners.length !== runners.length) {
    throw new Error(
      `[contract] AOT statement table has ${runners.length} runners ` +
        `for ${owners.length} declarations`,
    );
  }
  owners.forEach((owner, index) => {
    runnersByOwner.set(owner, runners[index]!);
  });
}

export function executeContractStatements(
  owner: StatementOwner,
  fallbackBody: Stmt[] | undefined,
  scope: Scope,
  runSegment: <T>(fn: () => T) => T,
  continuationFence?: ExecutionContinuationFence,
): unknown | Promise<unknown> {
  const runner = runnersByOwner.get(owner);
  if (runner) return runner(scope, runSegment, continuationFence);
  if (CONTRACT_STATEMENTS_PRODUCTION) {
    throw new Error(
      `[contract] production artifact omitted the AOT statement runner ` +
        `for "${owner.name}"`,
    );
  }
  if (!fallbackExecutor) {
    throw new Error(
      '[contract] editable statement interpreter fallback is not installed',
    );
  }
  return fallbackExecutor(
    fallbackBody ?? [],
    scope,
    runSegment,
    continuationFence,
  );
}

export function installContractStatementFallbackExecutor(
  executor: ContractStatementFallbackExecutor,
): void {
  fallbackExecutor = executor;
}

export function resetContractAotStatementsForTests(): void {
  runnersByOwner = new WeakMap();
}

function collectStatementOwners(file: ContractFileIR): StatementOwner[] {
  const owners: StatementOwner[] = [];
  file.components.forEach((component) => {
    owners.push(...component.actions, ...component.tasks);
  });
  (file.behaviorTemplates ?? []).forEach((template) => {
    owners.push(...template.actions, ...template.tasks);
  });
  return owners;
}
