// @system @ref LLP 0185 S2 — node-free terminal view construction.

import {
  appendChild,
  createInstance,
  insertBefore,
  removeChild,
  type ElementNode,
  type RootNode,
  type TextNode,
} from '@exact/renderer/host-ops';

import { getOwner } from './signals.js';
import type { AnchorFn, Mounted, MountEnv } from './view.js';

type HostNode = ElementNode | TextNode;
type HostParent = ElementNode | RootNode;

export function mountContractNothing(): Mounted {
  return { hostNodes: () => [], dispose: () => {} };
}

export function mountContractChildren(
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  return env.childrenSlot
    ? env.childrenSlot(parent, anchor)
    : mountContractNothing();
}

export function mountContractHole(
  label: string | undefined,
  parent: HostParent,
  anchor: AnchorFn,
): Mounted {
  const element = createInstance('View', {
    accessibilityRole: 'none',
    dataHole: true,
    label: label ?? 'Contract hole',
  });
  insertNode(parent, element, anchor());

  let disposed = false;
  const dispose = (): void => {
    if (disposed) return;
    disposed = true;
    removeChild(parent, element);
  };
  getOwner()?.register(dispose);
  return { hostNodes: () => (disposed ? [] : [element]), dispose };
}

function insertNode(
  parent: HostParent,
  node: HostNode,
  anchor: HostNode | null,
): void {
  if (anchor) insertBefore(parent, node, anchor);
  else appendChild(parent, node);
}
