// @system @ref LLP 0345 / LLP 0373 phase 3c — optional declarative-window
// runtime seam. Production modules inject the implementation only when their
// compiled IR declares windows; editable mount keeps the historical default.

import type { ComponentInstance } from './instance.js';

export interface ContractWindowsRuntime {
  setup(instance: ComponentInstance): void;
}

let editableDefault: ContractWindowsRuntime | null = null;

export function setEditableContractWindowsRuntime(
  runtime: ContractWindowsRuntime | null,
): void {
  editableDefault = runtime;
}

export function editableContractWindowsRuntime(): ContractWindowsRuntime | null {
  return editableDefault;
}
