import type {
  CanonicalStyle,
  FlexDirection,
  FullStyle,
} from '../types.js';
import type { NormalizeStyleOptions } from './normalize.js';

export type ProductionWebStyleNormalizer = (
  style: FullStyle | undefined,
  defaultFlexDirection?: FlexDirection,
  options?: NormalizeStyleOptions,
) => CanonicalStyle;

const EMPTY_DIRECT_DOM_STYLE = Object.freeze({}) as CanonicalStyle;

function normalizeDirectDomBookkeeping(
  style: FullStyle | undefined,
): CanonicalStyle {
  const numberOfLines = style?.numberOfLines;
  if (typeof numberOfLines !== 'number' || !Number.isFinite(numberOfLines) || numberOfLines <= 0) {
    return EMPTY_DIRECT_DOM_STYLE;
  }
  return { numberOfLines: Math.floor(numberOfLines) };
}

let normalizeProductionWebStyleImpl: ProductionWebStyleNormalizer =
  normalizeDirectDomBookkeeping;

export function installProductionWebStyleNormalizer(
  normalizer: ProductionWebStyleNormalizer,
): void {
  normalizeProductionWebStyleImpl = normalizer;
}

export function normalizeProductionWebStyle(
  style: FullStyle | undefined,
  defaultFlexDirection: FlexDirection = 'row',
  options: NormalizeStyleOptions = {},
): CanonicalStyle {
  return normalizeProductionWebStyleImpl(style, defaultFlexDirection, options);
}
