// @system @ref LLP 0185 S2 — production AOT view closure registry.
//
// Keep generated-closure identity and lookup independent from the editable IR
// walker in view.ts. Production root mounting can depend on this small module
// while the interpreter remains an on-demand dev/editability path.

import type { ContractFileIR, ViewNodeIR } from '../compiler/ir.js';
import { runWithContractErrorLocus } from './error-locus-runtime.js';
import type { AnchorFn, HostParent, Mounted, MountEnv } from './view.js';

export type ContractAotViewClosure = (
  node: ViewNodeIR,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
) => Mounted;

export type ContractAotViewPlanMount = (
  plan: unknown,
  node: ViewNodeIR,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
) => Mounted;

/**
 * Compact generated registration. The first position indexes the module's
 * one-per-kind mount table; the second is the node-specific positional plan.
 * Editable/advanced nodes may still register an exhaustive closure directly.
 */
export type ContractAotViewRegistration =
  | ContractAotViewClosure
  | readonly [mountIndex: number, plan?: unknown];

type RegisteredContractAotView = ContractAotViewClosure | readonly [
  mount: ContractAotViewPlanMount,
  plan: unknown,
];

/** Production compiler registration whose plan is allocated on first mount. */
export type ContractAotViewRegistrationFactory = () => RegisteredContractAotView;

let viewsByNode = new WeakMap<ViewNodeIR, RegisteredContractAotView>();
let viewFactoriesByNode = new WeakMap<ViewNodeIR, ContractAotViewRegistrationFactory>();

function resolveRegisteredContractAotView(
  node: ViewNodeIR,
): RegisteredContractAotView | undefined {
  const registered = viewsByNode.get(node);
  if (registered) return registered;
  const factory = viewFactoriesByNode.get(node);
  if (!factory) return undefined;
  const resolved = factory();
  viewFactoriesByNode.delete(node);
  viewsByNode.set(node, resolved);
  return resolved;
}

const mountRegisteredContractAotView: ContractAotViewClosure = (
  node,
  parent,
  anchor,
  env,
) => {
  const registered = resolveRegisteredContractAotView(node);
  if (!registered) {
    throw new Error(
      `[contract] production artifact omitted the AOT view closure for node kind "${node.kind}"`,
    );
  }
  return typeof registered === 'function'
    ? registered(node, parent, anchor, env)
    : registered[0](registered[1], node, parent, anchor, env);
};

export function getContractAotViewClosure(
  node: ViewNodeIR,
): ContractAotViewClosure | undefined {
  const registered = viewsByNode.get(node);
  return registered === undefined
    ? viewFactoriesByNode.has(node) ? mountRegisteredContractAotView : undefined
    : typeof registered === 'function'
      ? registered
      : mountRegisteredContractAotView;
}

export function registerContractAotViews(
  file: ContractFileIR,
  registrations: readonly ContractAotViewRegistration[],
  planMounts: readonly ContractAotViewPlanMount[] = [],
): void {
  const nodes = collectRuntimeViewNodes(file);
  if (nodes.length !== registrations.length) {
    throw new Error(
      `[contract] AOT view table has ${registrations.length} entries for ${nodes.length} IR nodes`,
    );
  }
  nodes.forEach((node, index) => {
    const registration = registrations[index]!;
    if (typeof registration === 'function') {
      viewFactoriesByNode.delete(node);
      viewsByNode.set(node, registration);
      return;
    }
    const mountIndex = registration[0];
    const mount = planMounts[mountIndex];
    if (!mount) {
      throw new Error(
        `[contract] missing AOT view mount ${mountIndex}:${index}`,
      );
    }
    viewFactoriesByNode.delete(node);
    viewsByNode.set(node, [mount, registration[1]]);
  });
}

/**
 * Production registration path. Generated plan arrays and generic closures
 * remain inside one factory per authored node until that node first mounts;
 * unopened regions therefore retain code identity but no materialized plan.
 */
export function registerContractAotViewFactories(
  file: ContractFileIR,
  factories: readonly ContractAotViewRegistrationFactory[],
): void {
  const nodes = collectRuntimeViewNodes(file);
  if (nodes.length !== factories.length) {
    throw new Error(
      `[contract] AOT view factory table has ${factories.length} entries for ${nodes.length} IR nodes`,
    );
  }
  nodes.forEach((node, index) => {
    viewsByNode.delete(node);
    viewFactoriesByNode.set(node, factories[index]!);
  });
}

export function resetContractAotViewsForTests(): void {
  viewsByNode = new WeakMap();
  viewFactoriesByNode = new WeakMap();
}

/** Mounts a compiled sibling list without importing the editable IR walker. */
export function mountContractAotViewNodes(
  nodes: readonly ViewNodeIR[],
  parent: HostParent,
  anchor: AnchorFn | null,
  env: MountEnv,
): Mounted {
  const slots: Mounted[] = [];
  // The environment is immutable during mounting. Once a walk leaves the
  // component root, every ordinary sibling/descendant can share the same
  // false-root projection instead of cloning all identity/context fields per
  // node. Region/component/repetition boundaries still create their authored
  // projections explicitly.
  const descendantEnv = env.isRootView && nodes.length !== 1
    ? { ...env, isRootView: false }
    : env;
  const anchorFor = (index: number): AnchorFn => () => {
    for (let i = index + 1; i < slots.length; i += 1) {
      const nodesAfter = slots[i]!.hostNodes();
      if (nodesAfter.length > 0) return nodesAfter[0]!;
    }
    return anchor ? anchor() : null;
  };

  nodes.forEach((node, index) => {
    const compiled = getContractAotViewClosure(node);
    if (!compiled) {
      throw new Error(
        `[contract] production artifact omitted the AOT view closure for node kind "${node.kind}"`,
      );
    }
    const nodeEnv = env.isRootView && nodes.length === 1 && index === 0
      ? env
      : descendantEnv;
    const mount = () => compiled(node, parent, anchorFor(index), nodeEnv);
    slots.push(node.span
      ? runWithContractErrorLocus({
          component: env.component.name,
          sourcePath: env.component.file.sourcePath,
          region: `view <${node.kind === 'element'
            ? node.tag
            : node.kind === 'component'
              ? node.name
              : node.kind}>`,
          span: node.span,
        }, mount)
      : mount());
  });

  return {
    hostNodes: () => slots.flatMap((slot) => slot.hostNodes()),
    dispose(): void {
      slots.forEach((slot) => slot.dispose());
      slots.length = 0;
    },
  };
}

function collectRuntimeViewNodes(file: ContractFileIR): ViewNodeIR[] {
  const nodes: ViewNodeIR[] = [];
  const many = (values: readonly ViewNodeIR[]): void => values.forEach(visit);
  const visit = (node: ViewNodeIR): void => {
    nodes.push(node);
    switch (node.kind) {
      case 'element':
      case 'component':
        many(node.children);
        return;
      case 'pager':
        node.cells.forEach((cell) => many(cell.body));
        return;
      case 'when':
        many(node.then);
        many(node.else ?? []);
        return;
      case 'match':
      case 'match-size':
        node.cases.forEach((entry) => many(entry.body));
        many(node.else ?? []);
        return;
      case 'each':
        many(node.body);
        return;
      case 'boundary':
        many(node.body);
        many(node.fallback.body);
        return;
      case 'resource':
      case 'async':
        node.slots.forEach((slot) => many(slot.body));
        return;
      default:
        return;
    }
  };
  file.components.forEach((component) => {
    visit(component.view);
    component.snippets.forEach((snippet) => many(snippet.body));
  });
  return nodes;
}
