// @system @ref LLP 0202 §2.3 / LLP 0205 S1 — shared semantic DOM attr lowering.

export type DomTagName =
  | 'div'
  | 'span'
  | 'a'
  | 'button'
  | 'input'
  | 'textarea'
  | 'img'
  | 'main'
  | 'nav'
  | 'header'
  | 'footer'
  | 'aside'
  | 'article'
  | 'section'
  | 'figure'
  | 'figcaption'
  | 'cite'
  | 'blockquote'
  | 'pre'
  | 'code'
  | 'hr'
  | 'ul'
  | 'li'
  | 'label'
  | `h${1 | 2 | 3 | 4 | 5 | 6}`;

export interface HostAttrNode {
  tag: string;
  props?: Record<string, unknown>;
}

export interface HostSemanticAttrs {
  tag?: string;
  role?: string;
  label?: string;
  hint?: string;
  headingLevel?: number;
  live?: string;
  labelledBy?: string;
  describedBy?: string;
  for?: string;
  nativeID?: string;
  testID?: string;
  testId?: string;
  focusable?: boolean;
  inert?: boolean;
}

export interface LowerHostAttrsOptions {
  defaultTag?: DomTagName;
  defaultRole?: string;
  inferTag?: boolean;
}

export interface LoweredHostAttrs {
  tag: DomTagName;
  attrs: Record<string, unknown>;
  aria: Record<string, unknown>;
  tabIndex?: number;
  inert?: boolean;
  role?: string;
  labelAssociation: {
    for?: string;
    labelledBy?: string;
    describedBy?: string;
  };
}

