export type JsonValue =
  | null
  | boolean
  | number
  | string
  | JsonValue[]
  | { [key: string]: JsonValue };

export interface ContractHydrationComponentState {
  nodeId: string;
  structuralId?: string;
  sourcePath?: string;
  sourceVersion?: string;
  componentName: string;
  state: Record<string, JsonValue>;
}

export interface ContractHydrationStateSnapshotRef {
  ref?: string;
  componentState: ContractHydrationComponentState[];
}

export interface ContractHydrationResourceSnapshot {
  nodeId: string;
  key: string;
  generation: number;
  status: 'ready' | 'error' | 'loading';
  value?: JsonValue;
  error?: { message: string; code?: string };
}

export interface ContractHydrationQuerySnapshot {
  nodeId: string;
  key: string;
  generation: number;
  status: 'ready' | 'error' | 'loading';
  value?: JsonValue;
  error?: { message: string; code?: string };
}

export interface ContractHydrationNodeAnchor {
  nodeId: string;
  structuralId?: string;
  sourcePath?: string;
  sourceVersion?: string;
  componentName?: string;
  domPath: number[];
  kind: 'element' | 'text' | 'component' | 'resource' | 'async' | 'boundary';
  tag?: string;
  textGuard?: string;
}

export type ContractHydrationEvent =
  | 'press'
  | 'change'
  | 'submit'
  | 'longpress'
  | 'focus'
  | 'blur'
  | 'scrollend'
  | 'refresh';

export interface ContractHydrationHandlerSlot {
  nodeId: string;
  structuralId?: string;
  event: ContractHydrationEvent;
  actionId: string;
}

export interface ContractHydrationCapabilityBag {
  nowMs: number;
  randomSeed?: string;
  locale?: string;
  timeZone?: string;
  /** Request/prerender-scoped appearance input. Never read process globals while set. */
  colorScheme?: 'light' | 'dark';
  /** Request/prerender-scoped authored appearance preference. */
  schemePreference?: 'system' | 'light' | 'dark';
  /** Request/prerender-scoped motion preference. */
  reducedMotion?: boolean;
  /** Prerender viewport replayed by the `viewport` capability (ENG-22563). */
  viewport?: { width: number; height: number };
  /**
   * Reactive host-binding snapshot (LLP 0292). Keys are capability names
   * (`colorScheme`, `safeAreaInsets`, `geolocation`) or `appGlue:<name>`.
   * Hydration replays these values through adoption, then releases to the
   * live host subscription in one ordinary reactive publication.
   */
  hostState?: Record<string, JsonValue>;
  resourceGenerations?: Record<string, number>;
  scroll?: Array<{ nodeId: string; x: number; y: number }>;
  focus?: { nodeId: string };
}

export interface ContractHydrationVerification {
  adoptedNodeCount: number;
  recreatedNodeCount: number;
  hydrationMismatchCount: number;
  adoptionFallbacks: string[];
  serverHtmlHash?: string;
  firstPaintHtmlHash?: string;
  firstPaintByteIdentical?: boolean;
  deferredMountTasks: number;
  tasksReleasedBeforeAdoption: boolean;
}

export interface ContractHydrationManifest {
  version: 1;
  rootId: number;
  routeId: string;
  buildId: string;
  sourceVersion: string;
  state: ContractHydrationStateSnapshotRef;
  resources: ContractHydrationResourceSnapshot[];
  queries: ContractHydrationQuerySnapshot[];
  nodes: ContractHydrationNodeAnchor[];
  handlers: ContractHydrationHandlerSlot[];
  capabilities: ContractHydrationCapabilityBag;
  verification?: ContractHydrationVerification;
}

export interface HydrationBuildDescriptorV1 {
  version: 1;
  schemaVersion: 1;
  routeId: string;
  routeGraphDigest: `sha256:${string}`;
  sourceVersion: string;
  buildFingerprint: `sha256:${string}`;
  generatedAdapterVersion: string;
}

// @ref LLP 0210 §4.9 — released-v1 readers bound untrusted manifest data
// before semantic lookup or component instantiation.
export const CONTRACT_HYDRATION_V1_LIMITS = Object.freeze({
  manifestBytes: 1024 * 1024,
  descriptorBytes: 16 * 1024,
  jsonDepth: 64,
  stringBytes: 64 * 1024,
  identityStringBytes: 1024,
  nodes: 16_384,
  handlers: 32_768,
  componentState: 8_192,
  resourceAndQueryRecords: 8_192,
  domPathDepth: 128,
  domPathIndex: 1_000_000,
  scrollRows: 4_096,
});
const hydrationUtf8 = new TextEncoder();

export type ContractHydrationManifestReadFailure =
  | 'manifest-too-large'
  | 'manifest-invalid-json'
  | 'manifest-invalid-schema';

export type ContractHydrationManifestReadResult =
  | {
      ok: true;
      manifest: ContractHydrationManifest;
      bytes: number;
    }
  | {
      ok: false;
      reason: ContractHydrationManifestReadFailure;
      errors: string[];
      bytes: number;
    };

export type HydrationBuildDescriptorReadResult =
  | {
      ok: true;
      descriptor: HydrationBuildDescriptorV1;
      bytes: number;
    }
  | {
      ok: false;
      reason:
        | 'descriptor-too-large'
        | 'descriptor-invalid-json'
        | 'descriptor-invalid-schema';
      errors: string[];
      bytes: number;
    };

export type ContractHydrationIdentityPreflight =
  | { ok: true }
  | {
      ok: false;
      outcome: 'development-unstamped' | 'stale-deploy';
      reason: string;
    };

export type ContractHydrationOutcome =
  | 'adopted'
  | 'genuine-mismatch'
  | 'expected-forced-csr'
  | 'development-unstamped'
  | 'stale-deploy'
  | 'internal-error';

export type ContractHydrationEntryPath =
  | 'per-route'
  | 'router-adapter'
  | 'router-document';

export interface ContractHydrationDiagnosticSnapshot {
  version: 1;
  attempts: number;
  outcomes: Record<ContractHydrationOutcome, number>;
  recent: Array<{
    outcome: ContractHydrationOutcome;
    entryPath: ContractHydrationEntryPath;
    reason?: string;
  }>;
}

declare global {
  // eslint-disable-next-line no-var
  var __exactContractHydrationDiagnostics:
    | ContractHydrationDiagnosticSnapshot
    | undefined;
  // eslint-disable-next-line no-var
  var __EXACT_CONTRACT_FORCE_CSR__: boolean | undefined;
}

export interface ContractHydrationRuntimeOptions {
  capabilities?: Partial<ContractHydrationCapabilityBag>;
  capture?: ContractHydrationCaptureSink;
  /**
   * Hold framework-owned effects, subscriptions, registries, and host
   * listeners behind the hydration commit fence. Client adoption paths set
   * this together with `deferMountTasks`; isolated server renders do not.
   */
  deferActivation?: boolean;
  deferMountTasks?: boolean;
  /** Server/headless render: never publish request state to process defaults. */
  isolatedRender?: boolean;
}

interface CapturedNode {
  hostId: number;
  nodeId: string;
  structuralId: string;
  sourcePath?: string;
  sourceVersion?: string;
  componentName?: string;
  kind: 'element' | 'text';
  tag?: string;
}

export interface ContractHydrationNodeInput {
  host: ElementNode | TextNode;
  nodeId: string;
  structuralId: string;
  sourcePath?: string;
  sourceVersion?: string;
  componentName?: string;
  kind: 'element' | 'text';
  tag?: string;
}

export interface ContractHydrationComponentStateInput {
  nodeId: string;
  structuralId?: string;
  sourcePath?: string;
  sourceVersion?: string;
  componentName: string;
  state: Record<string, unknown>;
}

export interface ContractHydrationCaptureSink {
  recordHostState(name: string, value: unknown): void;
  recordNode(input: ContractHydrationNodeInput): void;
  recordComponentState(input: ContractHydrationComponentStateInput): void;
  recordHandler(slot: ContractHydrationHandlerSlot): void;
  noteDeferredMountTasks(count: number): void;
  noteMountTasksReleasedBeforeAdoption(): void;
}

export interface ContractHydrationCaptureOptions {
  nowMs?: number;
  locale?: string;
  timeZone?: string;
  randomSeed?: string;
  colorScheme?: 'light' | 'dark';
  schemePreference?: 'system' | 'light' | 'dark';
  reducedMotion?: boolean;
  /**
   * The prerender window's viewport (ENG-22563). Recorded into the
   * capability bag so the client's first hydration render replays the size
   * the SSG baked into viewport-bound styles, then flips to the live window
   * when adoption releases.
   */
  viewport?: { width: number; height: number };
  hostState?: Record<string, JsonValue>;
}

export type ContractHydrationProducerValidationMode =
  | 'diagnostic'
  | 'strict';

export interface ContractHydrationProducerValidation {
  ok: boolean;
  errors: readonly string[];
}

export class ContractHydrationProducerValidationError extends Error {
  readonly errors: readonly string[];

  constructor(errors: readonly string[]) {
    super(
      `[contract] hydration producer validation failed: ${errors.join('; ')}`,
    );
    this.name = 'ContractHydrationProducerValidationError';
    this.errors = [...errors];
  }
}

export class ContractHydrationCapture implements ContractHydrationCaptureSink {
  readonly capabilities: ContractHydrationCapabilityBag;
  private readonly nodesByHostId = new Map<number, CapturedNode>();
  private readonly componentState = new Map<string, ContractHydrationComponentState>();
  private readonly handlers: ContractHydrationHandlerSlot[] = [];
  private readonly producerErrors: string[] = [];
  private deferredMountTasks = 0;
  private tasksReleasedBeforeAdoption = false;

  constructor(options: ContractHydrationCaptureOptions = {}) {
    this.capabilities = {
      nowMs: options.nowMs ?? Date.now(),
      ...(options.randomSeed ? { randomSeed: options.randomSeed } : {}),
      ...(options.locale ? { locale: options.locale } : {}),
      ...(options.timeZone ? { timeZone: options.timeZone } : {}),
      ...(options.colorScheme ? { colorScheme: options.colorScheme } : {}),
      ...(options.schemePreference
        ? { schemePreference: options.schemePreference }
        : {}),
      ...(options.reducedMotion !== undefined
        ? { reducedMotion: options.reducedMotion }
        : {}),
      ...(options.viewport ? { viewport: { ...options.viewport } } : {}),
      ...(options.hostState ? { hostState: { ...options.hostState } } : {}),
    };
  }

  recordHostState(name: string, value: unknown): void {
    const encoded = toJsonValue(value);
    if (encoded === undefined) {
      throw new Error(`[contract] hydration host state "${name}" is not JSON-serializable`);
    }
    (this.capabilities.hostState ??= {})[name] = encoded;
  }

  recordNode(input: ContractHydrationNodeInput): void {
    this.nodesByHostId.set(input.host.id, {
      hostId: input.host.id,
      nodeId: input.nodeId,
      structuralId: input.structuralId,
      sourcePath: input.sourcePath,
      sourceVersion: input.sourceVersion,
      componentName: input.componentName,
      kind: input.kind,
      tag: input.tag,
    });
  }

  recordComponentState(input: ContractHydrationComponentStateInput): void {
    const state = jsonRecord(input.state);
    const existing = this.componentState.get(input.nodeId);
    if (existing) {
      this.producerErrors.push(
        `duplicate component-state nodeId ${input.nodeId} ` +
          `(${existing.componentName ?? '<unknown>'} at ` +
          `${existing.sourcePath ?? '<unknown>'} vs ` +
          `${input.componentName ?? '<unknown>'} at ` +
          `${input.sourcePath ?? '<unknown>'})`,
      );
      return;
    }
    this.componentState.set(input.nodeId, {
      nodeId: input.nodeId,
      ...(input.structuralId ? { structuralId: input.structuralId } : {}),
      ...(input.sourcePath ? { sourcePath: input.sourcePath } : {}),
      ...(input.sourceVersion ? { sourceVersion: input.sourceVersion } : {}),
      componentName: input.componentName,
      state,
    });
  }

  recordHandler(slot: ContractHydrationHandlerSlot): void {
    if (this.handlers.some((candidate) =>
      candidate.nodeId === slot.nodeId &&
      candidate.event === slot.event &&
      candidate.actionId === slot.actionId
    )) {
      return;
    }
    this.handlers.push(slot);
  }

  noteDeferredMountTasks(count: number): void {
    this.deferredMountTasks = Math.max(this.deferredMountTasks, count);
  }

  noteMountTasksReleasedBeforeAdoption(): void {
    this.tasksReleasedBeforeAdoption = true;
  }

  snapshot(): {
    nodesByHostId: ReadonlyMap<number, CapturedNode>;
    componentState: ContractHydrationComponentState[];
    handlers: ContractHydrationHandlerSlot[];
    producerErrors: string[];
    deferredMountTasks: number;
    tasksReleasedBeforeAdoption: boolean;
  } {
    return {
      nodesByHostId: this.nodesByHostId,
      componentState: [...this.componentState.values()],
      handlers: [...this.handlers],
      producerErrors: [...this.producerErrors],
      deferredMountTasks: this.deferredMountTasks,
      tasksReleasedBeforeAdoption: this.tasksReleasedBeforeAdoption,
    };
  }
}

export function createContractHydrationCapture(
  options: ContractHydrationCaptureOptions = {},
): ContractHydrationCapture {
  return new ContractHydrationCapture(options);
}

const contractHydrationAdoptionCapture: ContractHydrationCaptureSink =
  Object.freeze({
    recordHostState() {},
    recordNode() {},
    recordComponentState() {},
    recordHandler() {},
    noteDeferredMountTasks() {},
    noteMountTasksReleasedBeforeAdoption() {},
  });

/**
 * Marks an adoption candidate with released-v1 node identities without
 * retaining the producer-only manifest transcript in a browser bundle.
 */
export function createContractHydrationAdoptionCapture(): ContractHydrationCaptureSink {
  return contractHydrationAdoptionCapture;
}

// @ref LLP 0210 §4.9 — every adoption attempt has one bounded, disjoint
// outcome. The workload harness reads the same diagnostic global as local
// conformance tests, so rates always retain their attempt denominator.
export function recordContractHydrationOutcome(input: {
  outcome: ContractHydrationOutcome;
  entryPath: ContractHydrationEntryPath;
  reason?: string;
}): ContractHydrationDiagnosticSnapshot {
  const diagnostics = globalThis.__exactContractHydrationDiagnostics ?? {
    version: 1 as const,
    attempts: 0,
    outcomes: {
      adopted: 0,
      'genuine-mismatch': 0,
      'expected-forced-csr': 0,
      'development-unstamped': 0,
      'stale-deploy': 0,
      'internal-error': 0,
    },
    recent: [],
  };
  diagnostics.attempts += 1;
  diagnostics.outcomes[input.outcome] += 1;
  diagnostics.recent.push({
    outcome: input.outcome,
    entryPath: input.entryPath,
    ...(input.reason
      ? { reason: input.reason.slice(0, 256) }
      : {}),
  });
  if (diagnostics.recent.length > 32) diagnostics.recent.shift();
  globalThis.__exactContractHydrationDiagnostics = diagnostics;
  return contractHydrationDiagnosticSnapshot();
}

export function contractHydrationDiagnosticSnapshot(): ContractHydrationDiagnosticSnapshot {
  const diagnostics = globalThis.__exactContractHydrationDiagnostics;
  if (!diagnostics) {
    return {
      version: 1,
      attempts: 0,
      outcomes: {
        adopted: 0,
        'genuine-mismatch': 0,
        'expected-forced-csr': 0,
        'development-unstamped': 0,
        'stale-deploy': 0,
        'internal-error': 0,
      },
      recent: [],
    };
  }
  return {
    version: 1,
    attempts: diagnostics.attempts,
    outcomes: { ...diagnostics.outcomes },
    recent: diagnostics.recent.map((entry) => ({ ...entry })),
  };
}

export function resetContractHydrationDiagnosticsForTests(): void {
  delete globalThis.__exactContractHydrationDiagnostics;
  delete globalThis.__exactContractHydrationOpaquePrepareDiagnostics;
}

export function contractHydrationForceCsr(): boolean {
  return globalThis.__EXACT_CONTRACT_FORCE_CSR__ === true;
}

export function contractHydrationNodeId(input: {
  prefix: string;
  structuralId: string;
  keyChain: string;
}): string {
  return `${input.prefix}${input.structuralId}${input.keyChain}`;
}

