export function attachContractHydrationTextId(text: TextNode, nodeId: string): void {
  (text as TextNode & { __exactHydrationId?: string }).__exactHydrationId = nodeId;
}

export function getContractHydrationIdForHostNode(
  node: ElementNode | TextNode,
): string | undefined {
  if (node.kind === NodeKind.Text) {
    return (node as TextNode & { __exactHydrationId?: string }).__exactHydrationId;
  }
  const value = (node.originalProps as Record<string, unknown>)['data-exact-hydration-id'];
  return typeof value === 'string' ? value : undefined;
}

export function buildContractHydrationManifest(input: {
  capture: ContractHydrationCapture;
  root: RootNode;
  domRoot?: ParentNode;
  /** DOM-free serializers provide the exact lowered tag for element guards. */
  resolveElementTag?: (host: ElementNode) => string;
  rootId: number;
  routeId: string;
  buildId: string;
  sourceVersion: string;
  serverHtml?: string;
  firstPaintHtml?: string;
  /**
   * Static producers fail the build on any malformed or self-inconsistent
   * output. Request-time producers remain diagnostic-only until the
   * separately ratified degraded-serving contract can omit the manifest.
   */
  producerValidation?: ContractHydrationProducerValidationMode;
  /**
   * Out-of-band because accepted v1 manifest bytes are frozen through H3a.
   * Request-time producers use this result for diagnostics until manifest
   * omission is separately ratified.
   */
  onProducerValidation?: (
    result: ContractHydrationProducerValidation,
  ) => void;
}): ContractHydrationManifest {
  const snapshot = input.capture.snapshot();
  const anchors: ContractHydrationNodeAnchor[] = [];
  const mismatches: string[] = [];
  const seenHostIds = new Set<number>();

  walkHostTree(input.root, input.domRoot, [], (host, domPath, domNode) => {
    const captured = snapshot.nodesByHostId.get(host.id);
    if (!captured) {
      return;
    }
    seenHostIds.add(host.id);
    const anchor: ContractHydrationNodeAnchor = {
      nodeId: captured.nodeId,
      structuralId: captured.structuralId,
      ...(captured.sourcePath ? { sourcePath: captured.sourcePath } : {}),
      ...(captured.sourceVersion ? { sourceVersion: captured.sourceVersion } : {}),
      ...(captured.componentName ? { componentName: captured.componentName } : {}),
      domPath,
      kind: captured.kind,
      ...(captured.tag ? { tag: captured.tag } : {}),
    };
    if (host.kind === NodeKind.Text) {
      anchor.textGuard = host.text;
    } else if (domNode?.nodeType === 1) {
      anchor.tag = (domNode as Element).localName;
    } else if (input.resolveElementTag) {
      anchor.tag = input.resolveElementTag(host);
    }
    if (domNode) {
      const mismatch = domMismatchFor(anchor, domNode);
      if (mismatch) {
        mismatches.push(mismatch);
      }
    }
    anchors.push(anchor);
  });

  for (const captured of snapshot.nodesByHostId.values()) {
    if (!seenHostIds.has(captured.hostId)) {
      mismatches.push(`host node ${captured.hostId} (${captured.nodeId}) was not reachable from the root`);
    }
  }

  const serverHash = input.serverHtml ? sha256(input.serverHtml) : undefined;
  const firstPaintHash = input.firstPaintHtml ? sha256(input.firstPaintHtml) : undefined;

  const manifest: ContractHydrationManifest = {
    version: 1,
    rootId: input.rootId,
    routeId: input.routeId,
    buildId: input.buildId,
    sourceVersion: input.sourceVersion,
    state: {
      componentState: snapshot.componentState,
    },
    resources: [],
    queries: [],
    nodes: anchors,
    handlers: snapshot.handlers,
    capabilities: input.capture.capabilities,
    verification: {
      adoptedNodeCount: anchors.length - mismatches.length,
      recreatedNodeCount: mismatches.length,
      hydrationMismatchCount: mismatches.length,
      adoptionFallbacks: mismatches,
      ...(serverHash ? { serverHtmlHash: serverHash } : {}),
      ...(firstPaintHash ? { firstPaintHtmlHash: firstPaintHash } : {}),
      ...(serverHash && firstPaintHash ? { firstPaintByteIdentical: serverHash === firstPaintHash } : {}),
      deferredMountTasks: snapshot.deferredMountTasks,
      tasksReleasedBeforeAdoption: snapshot.tasksReleasedBeforeAdoption,
    },
  };
  const producerErrors = validateContractHydrationProducerManifest(manifest, {
    captureErrors: snapshot.producerErrors,
  });
  input.onProducerValidation?.({
    ok: producerErrors.length === 0,
    errors: producerErrors,
  });
  if (
    input.producerValidation === 'strict' &&
    producerErrors.length > 0
  ) {
    throw new ContractHydrationProducerValidationError(producerErrors);
  }
  return manifest;
}

// @ref LLP 0386 §H2 — producer validation is stricter than the untrusted
// reader: production stamps and the producer's own correspondence transcript
// must be clean before an SSG manifest can be emitted.
export function validateContractHydrationProducerManifest(
  manifest: ContractHydrationManifest,
  options: { captureErrors?: readonly string[] } = {},
): string[] {
  const validation = validateContractHydrationManifest(manifest);
  const errors = validation.ok === true ? [] : [...validation.errors];
  for (const field of ['routeId', 'buildId', 'sourceVersion'] as const) {
    const identity = manifest[field];
    if (
      identity === `sha256:${'0'.repeat(64)}` ||
      /(?:^|[-_:/.<])(unknown|missing|placeholder|unstamped)(?:$|[-_:/.>])/i
        .test(identity)
    ) {
      errors.push(`${field} is not production-stamped`);
    }
  }
  for (const error of options.captureErrors ?? []) errors.push(error);
  for (const error of manifest.verification?.adoptionFallbacks ?? []) {
    errors.push(error);
  }
  if (
    manifest.verification &&
    (
      manifest.verification.hydrationMismatchCount !== 0 ||
      manifest.verification.recreatedNodeCount !== 0 ||
      manifest.verification.tasksReleasedBeforeAdoption
    )
  ) {
    if (manifest.verification.hydrationMismatchCount !== 0) {
      errors.push(
        `producer simulated adoption recorded ` +
          `${manifest.verification.hydrationMismatchCount} mismatches`,
      );
    }
    if (manifest.verification.recreatedNodeCount !== 0) {
      errors.push(
        `producer simulated adoption recorded ` +
          `${manifest.verification.recreatedNodeCount} recreated nodes`,
      );
    }
    if (manifest.verification.tasksReleasedBeforeAdoption) {
      errors.push('producer released deferred tasks before adoption');
    }
  }
  return [...new Set(errors)].slice(0, 64);
}

export function validateContractHydrationManifest(
  manifest: unknown,
): { ok: true; manifest: ContractHydrationManifest } | { ok: false; errors: string[] } {
  const errors: string[] = [];
  const addError = (message: string): void => {
    if (errors.length < 64) errors.push(message);
  };
  if (!manifest || typeof manifest !== 'object') {
    return { ok: false, errors: ['manifest must be an object'] };
  }
  inspectJsonBounds(manifest, addError);
  const candidate = manifest as Partial<ContractHydrationManifest>;
  if (candidate.version !== 1) addError('version must be 1');
  if (typeof candidate.rootId !== 'number' || !Number.isInteger(candidate.rootId)) {
    addError('rootId must be an integer');
  }
  for (const field of ['routeId', 'buildId', 'sourceVersion'] as const) {
    if (typeof candidate[field] !== 'string' || candidate[field]!.length === 0) {
      addError(`${field} must be a non-empty string`);
    } else if (utf8ByteLength(candidate[field]!) > CONTRACT_HYDRATION_V1_LIMITS.identityStringBytes) {
      addError(`${field} exceeds ${CONTRACT_HYDRATION_V1_LIMITS.identityStringBytes} UTF-8 bytes`);
    }
  }
  if (!candidate.capabilities || typeof candidate.capabilities.nowMs !== 'number') {
    addError('capabilities.nowMs must be a number');
  }
  if (!candidate.state || !Array.isArray(candidate.state.componentState)) {
    addError('state.componentState must be an array');
  } else if (candidate.state.componentState.length > CONTRACT_HYDRATION_V1_LIMITS.componentState) {
    addError(`state.componentState exceeds ${CONTRACT_HYDRATION_V1_LIMITS.componentState} records`);
  }
  if (!Array.isArray(candidate.resources)) addError('resources must be an array');
  if (!Array.isArray(candidate.queries)) addError('queries must be an array');
  if (
    Array.isArray(candidate.resources) &&
    Array.isArray(candidate.queries) &&
    candidate.resources.length + candidate.queries.length >
      CONTRACT_HYDRATION_V1_LIMITS.resourceAndQueryRecords
  ) {
    addError(
      `resources + queries exceed ${CONTRACT_HYDRATION_V1_LIMITS.resourceAndQueryRecords} records`,
    );
  }
  const nodeIds = new Set<string>();
  if (!Array.isArray(candidate.nodes)) {
    addError('nodes must be an array');
  } else {
    if (candidate.nodes.length > CONTRACT_HYDRATION_V1_LIMITS.nodes) {
      addError(`nodes exceeds ${CONTRACT_HYDRATION_V1_LIMITS.nodes} records`);
    }
    const domPaths = new Set<string>();
    for (const [index, node] of candidate.nodes.entries()) {
      if (!node || typeof node !== 'object') {
        addError(`nodes[${index}] must be an object`);
        continue;
      }
      const anchor = node as Partial<ContractHydrationNodeAnchor>;
      if (typeof anchor.nodeId !== 'string' || anchor.nodeId.length === 0) {
        addError(`nodes[${index}].nodeId must be a non-empty string`);
      } else if (utf8ByteLength(anchor.nodeId) > CONTRACT_HYDRATION_V1_LIMITS.identityStringBytes) {
        addError(`nodes[${index}].nodeId exceeds ${CONTRACT_HYDRATION_V1_LIMITS.identityStringBytes} UTF-8 bytes`);
      } else if (nodeIds.has(anchor.nodeId)) {
        addError(`duplicate nodeId ${anchor.nodeId}`);
      } else {
        nodeIds.add(anchor.nodeId);
      }
      if (!Array.isArray(anchor.domPath)) {
        addError(`nodes[${index}].domPath must be a non-negative integer array`);
      } else {
        if (anchor.domPath.length > CONTRACT_HYDRATION_V1_LIMITS.domPathDepth) {
          addError(`nodes[${index}].domPath exceeds depth ${CONTRACT_HYDRATION_V1_LIMITS.domPathDepth}`);
        }
        if (anchor.domPath.some((part) =>
          !Number.isSafeInteger(part) ||
          part < 0 ||
          part > CONTRACT_HYDRATION_V1_LIMITS.domPathIndex
        )) {
          addError(
            `nodes[${index}].domPath must contain safe integers from 0 through ` +
              `${CONTRACT_HYDRATION_V1_LIMITS.domPathIndex}`,
          );
        } else {
          const pathKey = anchor.domPath.join('.');
          if (domPaths.has(pathKey)) addError(`duplicate domPath ${pathKey}`);
          else domPaths.add(pathKey);
        }
      }
      if (anchor.kind !== 'element' && anchor.kind !== 'text' && anchor.kind !== 'component' &&
        anchor.kind !== 'resource' && anchor.kind !== 'async' && anchor.kind !== 'boundary') {
        addError(`nodes[${index}].kind is invalid`);
      }
    }
  }
  if (!Array.isArray(candidate.handlers)) {
    addError('handlers must be an array');
  } else {
    if (candidate.handlers.length > CONTRACT_HYDRATION_V1_LIMITS.handlers) {
      addError(`handlers exceeds ${CONTRACT_HYDRATION_V1_LIMITS.handlers} records`);
    }
    const handlerKeys = new Set<string>();
    for (const [index, handler] of candidate.handlers.entries()) {
      if (!handler || typeof handler !== 'object') {
        addError(`handlers[${index}] must be an object`);
        continue;
      }
      const nodeId = typeof handler.nodeId === 'string' ? handler.nodeId : '';
      if (!nodeId) addError(`handlers[${index}].nodeId must be a non-empty string`);
      else if (!nodeIds.has(nodeId)) addError(`handlers[${index}].nodeId must reference a manifest node`);
      const event = typeof handler.event === 'string' ? handler.event : '';
      const actionId = typeof handler.actionId === 'string' ? handler.actionId : '';
      if (!event) addError(`handlers[${index}].event must be a non-empty string`);
      if (!actionId) addError(`handlers[${index}].actionId must be a non-empty string`);
      const key = `${nodeId}\u0000${event}`;
      if (handlerKeys.has(key)) addError(`duplicate handler (${nodeId}, ${event})`);
      else handlerKeys.add(key);
    }
  }
  validateManifestRecordReferences(candidate, nodeIds, addError);
  return errors.length === 0
    ? { ok: true, manifest: candidate as ContractHydrationManifest }
    : { ok: false, errors };
}

/**
 * Validate an already-parsed v1 manifest for a production adoption path
 * without retaining the diagnostic validator's message inventory.
 *
 * @ref LLP 0386 §3.8.3 — the compact reader enforces the same released-v1
 * bounds and correspondence preconditions before component instantiation.
 */
export function readContractHydrationManifestValue(
  value: unknown,
): ContractHydrationManifest | null {
  if (!value || typeof value !== 'object' || !isBoundedHydrationJson(value)) {
    return null;
  }
  const candidate = value as Partial<ContractHydrationManifest>;
  const validIdentity = (identity: unknown): identity is string =>
    typeof identity === 'string' &&
    identity.length > 0 &&
    utf8ByteLength(identity) <= CONTRACT_HYDRATION_V1_LIMITS.identityStringBytes;
  if (
    candidate.version !== 1 ||
    typeof candidate.rootId !== 'number' ||
    !Number.isInteger(candidate.rootId) ||
    !validIdentity(candidate.routeId) ||
    !validIdentity(candidate.buildId) ||
    !validIdentity(candidate.sourceVersion) ||
    !candidate.capabilities ||
    typeof candidate.capabilities.nowMs !== 'number' ||
    !candidate.state ||
    !Array.isArray(candidate.state.componentState) ||
    candidate.state.componentState.length > CONTRACT_HYDRATION_V1_LIMITS.componentState ||
    !Array.isArray(candidate.resources) ||
    !Array.isArray(candidate.queries) ||
    candidate.resources.length + candidate.queries.length >
      CONTRACT_HYDRATION_V1_LIMITS.resourceAndQueryRecords ||
    !Array.isArray(candidate.nodes) ||
    candidate.nodes.length > CONTRACT_HYDRATION_V1_LIMITS.nodes ||
    !Array.isArray(candidate.handlers) ||
    candidate.handlers.length > CONTRACT_HYDRATION_V1_LIMITS.handlers
  ) {
    return null;
  }

  const nodeIds = new Set<string>();
  const domPaths = new Set<string>();
  for (const node of candidate.nodes) {
    if (!node || typeof node !== 'object') return null;
    const anchor = node as Partial<ContractHydrationNodeAnchor>;
    if (
      !validIdentity(anchor.nodeId) ||
      nodeIds.has(anchor.nodeId) ||
      !Array.isArray(anchor.domPath) ||
      anchor.domPath.length > CONTRACT_HYDRATION_V1_LIMITS.domPathDepth ||
      anchor.domPath.some((part) =>
        !Number.isSafeInteger(part) ||
        part < 0 ||
        part > CONTRACT_HYDRATION_V1_LIMITS.domPathIndex
      ) ||
      typeof anchor.kind !== 'string' ||
      !' element text component resource async boundary '.includes(` ${anchor.kind} `)
    ) {
      return null;
    }
    const path = anchor.domPath.join('.');
    if (domPaths.has(path)) return null;
    nodeIds.add(anchor.nodeId);
    domPaths.add(path);
  }

  const handlerKeys = new Set<string>();
  for (const handler of candidate.handlers) {
    if (
      !handler ||
      typeof handler !== 'object' ||
      typeof handler.nodeId !== 'string' ||
      !nodeIds.has(handler.nodeId) ||
      typeof handler.event !== 'string' ||
      handler.event.length === 0 ||
      typeof handler.actionId !== 'string' ||
      handler.actionId.length === 0
    ) {
      return null;
    }
    const key = `${handler.nodeId}\u0000${handler.event}`;
    if (handlerKeys.has(key)) return null;
    handlerKeys.add(key);
  }

  const uniqueRecordIdentities = (
    records: readonly unknown[],
    requireKey: boolean,
  ): boolean => {
    const identities = new Set<string>();
    for (const record of records) {
      if (!record || typeof record !== 'object') return false;
      const item = record as { nodeId?: unknown; key?: unknown };
      if (typeof item.nodeId !== 'string' || item.nodeId.length === 0) return false;
      const key = requireKey && typeof item.key === 'string' ? item.key : '';
      if (requireKey && !key) return false;
      const identity = `${item.nodeId}\u0000${key}`;
      if (identities.has(identity)) return false;
      identities.add(identity);
    }
    return true;
  };
  if (
    !uniqueRecordIdentities(candidate.state.componentState, false) ||
    !uniqueRecordIdentities(candidate.resources, true) ||
    !uniqueRecordIdentities(candidate.queries, true)
  ) {
    return null;
  }

  const scroll = candidate.capabilities.scroll;
  if (
    Array.isArray(scroll) &&
    (
      scroll.length > CONTRACT_HYDRATION_V1_LIMITS.scrollRows ||
      scroll.some((record) =>
        !record ||
        typeof record.nodeId !== 'string' ||
        !nodeIds.has(record.nodeId)
      )
    )
  ) {
    return null;
  }
  const focus = candidate.capabilities.focus;
  if (
    focus &&
    (typeof focus.nodeId !== 'string' || !nodeIds.has(focus.nodeId))
  ) {
    return null;
  }
  return candidate as ContractHydrationManifest;
}

export function parseContractHydrationManifestText(
  text: string,
): ContractHydrationManifestReadResult {
  const bytes = utf8ByteLength(text);
  if (bytes > CONTRACT_HYDRATION_V1_LIMITS.manifestBytes) {
    return {
      ok: false,
      reason: 'manifest-too-large',
      errors: [`manifest exceeds ${CONTRACT_HYDRATION_V1_LIMITS.manifestBytes} UTF-8 bytes`],
      bytes,
    };
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text) as unknown;
  } catch {
    return {
      ok: false,
      reason: 'manifest-invalid-json',
      errors: ['manifest is not valid JSON'],
      bytes,
    };
  }
  const validation = validateContractHydrationManifest(parsed);
  if (validation.ok === true) {
    return { ok: true, manifest: validation.manifest, bytes };
  }
  return {
    ok: false,
    reason: 'manifest-invalid-schema',
    errors: validation.errors,
    bytes,
  };
}

export function validateHydrationBuildDescriptor(
  value: unknown,
): { ok: true; descriptor: HydrationBuildDescriptorV1 } | {
  ok: false;
  errors: string[];
} {
  const errors: string[] = [];
  const addError = (message: string): void => {
    if (errors.length < 32) errors.push(message);
  };
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return { ok: false, errors: ['descriptor must be an object'] };
  }
  inspectJsonBounds(value, addError, 'descriptor');
  const descriptor = value as Partial<HydrationBuildDescriptorV1>;
  if (descriptor.version !== 1) addError('version must be 1');
  if (descriptor.schemaVersion !== 1) addError('schemaVersion must be 1');
  for (const field of [
    'routeId',
    'sourceVersion',
    'generatedAdapterVersion',
  ] as const) {
    const fieldValue = descriptor[field];
    if (typeof fieldValue !== 'string' || fieldValue.length === 0) {
      addError(`${field} must be a non-empty string`);
    } else if (
      utf8ByteLength(fieldValue) >
        CONTRACT_HYDRATION_V1_LIMITS.identityStringBytes
    ) {
      addError(
        `${field} exceeds ` +
          `${CONTRACT_HYDRATION_V1_LIMITS.identityStringBytes} UTF-8 bytes`,
      );
    }
  }
  for (const field of ['routeGraphDigest', 'buildFingerprint'] as const) {
    const fieldValue = descriptor[field];
    if (
      typeof fieldValue !== 'string' ||
      !/^sha256:[0-9a-f]{64}$/.test(fieldValue)
    ) {
      addError(`${field} must be sha256:<64 lowercase hex>`);
    }
  }
  return errors.length === 0
    ? { ok: true, descriptor: descriptor as HydrationBuildDescriptorV1 }
    : { ok: false, errors };
}

export function parseHydrationBuildDescriptorText(
  text: string,
): HydrationBuildDescriptorReadResult {
  const bytes = utf8ByteLength(text);
  if (bytes > CONTRACT_HYDRATION_V1_LIMITS.descriptorBytes) {
    return {
      ok: false,
      reason: 'descriptor-too-large',
      errors: [
        `descriptor exceeds ` +
          `${CONTRACT_HYDRATION_V1_LIMITS.descriptorBytes} UTF-8 bytes`,
      ],
      bytes,
    };
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text) as unknown;
  } catch {
    return {
      ok: false,
      reason: 'descriptor-invalid-json',
      errors: ['descriptor is not valid JSON'],
      bytes,
    };
  }
  const validation = validateHydrationBuildDescriptor(parsed);
  return validation.ok === true
    ? { ok: true, descriptor: validation.descriptor, bytes }
    : {
        ok: false,
        reason: 'descriptor-invalid-schema',
        errors: validation.errors,
        bytes,
      };
}

/**
 * Compare independently generated client identity with the released-v1
 * document fields before a route module is evaluated.
 *
 * V1 has no build-fingerprint field, so H1 checks the zero-wire-byte subset:
 * schema, route, composed source, and deterministic build id. The descriptor
 * fingerprint is still validated and becomes the enclosing artifact join
 * when the ratified v2 wire field lands.
 */
export function preflightContractHydrationIdentity(
  manifest: ContractHydrationManifest,
  descriptor: HydrationBuildDescriptorV1,
): ContractHydrationIdentityPreflight {
  const placeholder = hydrationIdentityPlaceholderReason(manifest, descriptor);
  if (placeholder) {
    return {
      ok: false,
      outcome: 'development-unstamped',
      reason: placeholder,
    };
  }
  if (descriptor.schemaVersion !== manifest.version) {
    return {
      ok: false,
      outcome: 'stale-deploy',
      reason: 'hydration schema does not match the client descriptor',
    };
  }
  if (descriptor.routeId !== manifest.routeId) {
    return {
      ok: false,
      outcome: 'stale-deploy',
      reason: 'hydration route does not match the client descriptor',
    };
  }
  if (descriptor.sourceVersion !== manifest.sourceVersion) {
    return {
      ok: false,
      outcome: 'stale-deploy',
      reason: 'hydration source does not match the client descriptor',
    };
  }
  const expectedBuildId = `${descriptor.routeId}:${descriptor.sourceVersion}`;
  if (manifest.buildId !== expectedBuildId) {
    return {
      ok: false,
      outcome: 'stale-deploy',
      reason: 'hydration build does not match the deterministic client identity',
    };
  }
  return { ok: true };
}

export function preflightContractHydrationIdentityFromDescriptors(
  manifest: ContractHydrationManifest,
  descriptors: readonly HydrationBuildDescriptorV1[],
): ContractHydrationIdentityPreflight {
  const routeDescriptors = descriptors.filter(
    (descriptor) => descriptor.routeId === manifest.routeId,
  );
  const descriptor = routeDescriptors.find(
    (candidate) => candidate.sourceVersion === manifest.sourceVersion,
  ) ?? routeDescriptors[0];
  if (!descriptor) {
    return {
      ok: false,
      outcome: 'stale-deploy',
      reason: 'hydration route is absent from the client descriptor registry',
    };
  }
  return preflightContractHydrationIdentity(manifest, descriptor);
}

function hydrationIdentityPlaceholderReason(
  manifest: ContractHydrationManifest,
  descriptor: HydrationBuildDescriptorV1,
): string | null {
  const identities = [
    ['manifest route', manifest.routeId],
    ['manifest build', manifest.buildId],
    ['manifest source', manifest.sourceVersion],
    ['descriptor route', descriptor.routeId],
    ['descriptor source', descriptor.sourceVersion],
    ['descriptor adapter', descriptor.generatedAdapterVersion],
    ['descriptor build', descriptor.buildFingerprint],
  ] as const;
  for (const [label, identity] of identities) {
    if (
      identity.trim().length === 0 ||
      identity === `sha256:${'0'.repeat(64)}` ||
      /(?:^|[-_:/.<])(unknown|missing|placeholder|unstamped)(?:$|[-_:/.>])/i
        .test(identity)
    ) {
      return `${label} identity is unstamped`;
    }
  }
  return null;
}

function inspectJsonBounds(
  value: unknown,
  addError: (message: string) => void,
  label = 'manifest',
): void {
  const seen = new Set<object>();
  const visit = (current: unknown, depth: number): void => {
    if (depth > CONTRACT_HYDRATION_V1_LIMITS.jsonDepth) {
      addError(`${label}:too-deep`);
      return;
    }
    if (typeof current === 'string') {
      if (utf8ByteLength(current) > CONTRACT_HYDRATION_V1_LIMITS.stringBytes) {
        addError(`${label}:string-too-large`);
      }
      return;
    }
    if (!current || typeof current !== 'object') return;
    if (seen.has(current)) {
      addError(`${label}:cycle`);
      return;
    }
    seen.add(current);
    if (Array.isArray(current)) {
      for (const child of current) visit(child, depth + 1);
      return;
    }
    for (const [key, child] of Object.entries(current)) {
      visit(key, depth + 1);
      visit(child, depth + 1);
    }
  };
  visit(value, 1);
}

function isBoundedHydrationJson(value: unknown): boolean {
  const seen = new Set<object>();
  const visit = (current: unknown, depth: number): boolean => {
    if (depth > CONTRACT_HYDRATION_V1_LIMITS.jsonDepth) return false;
    if (typeof current === 'string') {
      return utf8ByteLength(current) <= CONTRACT_HYDRATION_V1_LIMITS.stringBytes;
    }
    if (!current || typeof current !== 'object') return true;
    if (seen.has(current)) return false;
    seen.add(current);
    if (Array.isArray(current)) {
      return current.every((child) => visit(child, depth + 1));
    }
    return Object.entries(current).every(
      ([key, child]) => visit(key, depth + 1) && visit(child, depth + 1),
    );
  };
  return visit(value, 1);
}

function validateManifestRecordReferences(
  candidate: Partial<ContractHydrationManifest>,
  nodeIds: ReadonlySet<string>,
  addError: (message: string) => void,
): void {
  const componentState = candidate.state?.componentState;
  if (Array.isArray(componentState)) {
    const seen = new Set<string>();
    for (const [index, record] of componentState.entries()) {
      const nodeId = record && typeof record.nodeId === 'string' ? record.nodeId : '';
      if (!nodeId) addError(`state.componentState[${index}].nodeId:string`);
      // Released v1 records component-instance ids that do not necessarily
      // have their own host-node anchor. H2 may add producer-side component
      // anchor relations; H1 must not reinterpret accepted v1 bytes.
      if (seen.has(nodeId)) addError(`duplicate component state nodeId ${nodeId}`);
      else seen.add(nodeId);
    }
  }

  for (const [field, records] of [
    ['resources', candidate.resources],
    ['queries', candidate.queries],
  ] as const) {
    if (!Array.isArray(records)) continue;
    const seen = new Set<string>();
    for (const [index, record] of records.entries()) {
      const nodeId = record && typeof record.nodeId === 'string' ? record.nodeId : '';
      const key = record && typeof record.key === 'string' ? record.key : '';
      if (!nodeId) addError(`${field}[${index}].nodeId:string`);
      // Resource/query owner ids share the released component-occurrence
      // domain rather than the host-anchor-only `nodes` array.
      if (!key) addError(`${field}[${index}].key:string`);
      const identity = `${nodeId}\u0000${key}`;
      if (seen.has(identity)) addError(`duplicate ${field} identity (${nodeId}, ${key})`);
      else seen.add(identity);
    }
  }

  const scroll = candidate.capabilities?.scroll;
  if (Array.isArray(scroll)) {
    if (scroll.length > CONTRACT_HYDRATION_V1_LIMITS.scrollRows) {
      addError('capabilities.scroll:too-many');
    }
    for (const [index, record] of scroll.entries()) {
      if (!record || typeof record.nodeId !== 'string' || !nodeIds.has(record.nodeId)) {
        addError(`capabilities.scroll[${index}].nodeId must reference a manifest node`);
      }
    }
  }
  const focus = candidate.capabilities?.focus;
  if (focus && (typeof focus.nodeId !== 'string' || !nodeIds.has(focus.nodeId))) {
    addError('capabilities.focus.nodeId must reference a manifest node');
  }
}

function utf8ByteLength(value: string): number {
  return hydrationUtf8.encode(value).byteLength;
}

export function simulateContractHydrationAdoption(
  manifest: ContractHydrationManifest,
  domRoot: ParentNode,
): ContractHydrationVerification {
  const mismatches: string[] = [];
  let adopted = 0;
  for (const anchor of manifest.nodes) {
    const domNode = resolveDomPath(domRoot, anchor.domPath);
    if (!domNode) {
      mismatches.push(`${anchor.nodeId}: domPath ${anchor.domPath.join('.')} did not resolve`);
      continue;
    }
    const mismatch = domMismatchFor(anchor, domNode);
    if (mismatch) {
      mismatches.push(mismatch);
      continue;
    }
    adopted += 1;
  }
  return {
    adoptedNodeCount: adopted,
    recreatedNodeCount: mismatches.length,
    hydrationMismatchCount: mismatches.length,
    adoptionFallbacks: mismatches,
    deferredMountTasks: manifest.verification?.deferredMountTasks ?? 0,
    tasksReleasedBeforeAdoption: manifest.verification?.tasksReleasedBeforeAdoption ?? false,
  };
}

function walkHostTree(
  root: RootNode,
  domRoot: ParentNode | undefined,
  path: number[],
  visit: (node: ElementNode | TextNode, domPath: number[], domNode: Node | null) => void,
): void {
  const walkChildren = (
    children: Array<ElementNode | TextNode>,
    domParent: ParentNode | undefined,
    parentPath: number[],
  ): void => {
    children.forEach((child, index) => {
      const domPath = [...parentPath, index];
      const domNode = domParent?.childNodes.item(index) ?? null;
      visit(child, domPath, domNode);
      if (child.kind === NodeKind.Element) {
        const nextDomParent = domNode && 'childNodes' in domNode
          ? (domNode as unknown as ParentNode)
          : undefined;
        walkChildren(child.children as Array<ElementNode | TextNode>, nextDomParent, domPath);
      }
    });
  };
  walkChildren(root.children as Array<ElementNode | TextNode>, domRoot, path);
}

function resolveDomPath(root: ParentNode, domPath: readonly number[]): Node | null {
  let current: ParentNode | Node = root;
  for (const index of domPath) {
    if (!('childNodes' in current)) {
      return null;
    }
    const next = current.childNodes.item(index);
    if (!next) {
      return null;
    }
    current = next;
  }
  return current as Node;
}

function domMismatchFor(anchor: ContractHydrationNodeAnchor, domNode: Node): string | null {
  if (anchor.kind === 'element') {
    if (domNode.nodeType !== 1) {
      return `${anchor.nodeId}: expected element, got nodeType ${domNode.nodeType}`;
    }
    const element = domNode as Element;
    if (anchor.tag && element.localName !== anchor.tag) {
      return `${anchor.nodeId}: expected <${anchor.tag}>, got <${element.localName}>`;
    }
    const hydrationId = element.getAttribute('data-exact-hydration-id');
    if (hydrationId !== anchor.nodeId) {
      return `${anchor.nodeId}: data-exact-hydration-id mismatch (${hydrationId ?? 'missing'})`;
    }
  }
  if (anchor.kind === 'text') {
    if (domNode.nodeType !== 3) {
      return `${anchor.nodeId}: expected text, got nodeType ${domNode.nodeType}`;
    }
    if (anchor.textGuard !== undefined && domNode.nodeValue !== anchor.textGuard) {
      return `${anchor.nodeId}: textGuard mismatch`;
    }
  }
  return null;
}

function jsonRecord(input: Record<string, unknown>): Record<string, JsonValue> {
  const out: Record<string, JsonValue> = {};
  for (const [key, value] of Object.entries(input)) {
    const json = toJsonValue(value);
    if (json !== undefined) {
      out[key] = json;
    }
  }
  return out;
}

function toJsonValue(value: unknown): JsonValue | undefined {
  if (value === null || typeof value === 'boolean' || typeof value === 'string') {
    return value as JsonValue;
  }
  if (typeof value === 'number') {
    return Number.isFinite(value) ? value : null;
  }
  if (Array.isArray(value)) {
    return value.map((item) => toJsonValue(item) ?? null);
  }
  if (typeof value === 'object' && value !== null) {
    const out: Record<string, JsonValue> = {};
    for (const [key, nested] of Object.entries(value as Record<string, unknown>)) {
      const json = toJsonValue(nested);
      if (json !== undefined) {
        out[key] = json;
      }
    }
    return out;
  }
  return undefined;
}

function sha256(value: string): string {
  // Browser-safe stable hash. The verifier compares equality, not
  // cryptographic strength, and @exact/contract/runtime is client-loaded.
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `fnv1a32:${(hash >>> 0).toString(16).padStart(8, '0')}`;
}
