// @system @ref LLP 0185#432-proposed-statement-backend-decision-packet —
// Small semantic helpers for backend A. Authored statement order and control
// flow stay in emitted owner functions; this module supplies only shared
// assignment, locus, continuation, loop, and return mechanics.

import type { Span } from '../compiler/ir.js';
import { decorateContractError } from './error-locus-runtime.js';
import {
  isExecutionDisposedOutcome,
} from './effect-supervisor.js';
import type {
  ExecutionContinuationFence,
  Scope,
} from './execution-scope.js';

type SpanPlan = readonly [line: number, col: number, len: number, offset: number];
type RunSegment = <T>(fn: () => T) => T;

class DirectReturnSignal {
  constructor(readonly value: unknown) {}
}

function withLocus<T>(span: SpanPlan, run: () => T): T {
  try {
    return run();
  } catch (error) {
    decorateContractError(error, { span: spanFrom(span) });
    throw error;
  }
}

function assignName(scope: Scope, name: string, value: unknown): void {
  const binding = scope.lookup(name);
  if (!binding) {
    throw new Error(`[contract] cannot assign to undeclared "${name}"`);
  }
  if (binding.kind === 'state') {
    binding.set(value);
    return;
  }
  if (binding.kind === 'local') {
    binding.value = value;
    return;
  }
  throw new Error(
    `[contract] "${name}" is read-only ` +
      '(only state slots and local lets are assignable)',
  );
}

function assignMember(
  scope: Scope,
  object: () => unknown,
  property: string,
  stateRoot: string | null,
  value: unknown,
): void {
  const write = () => {
    const target = object();
    if (target == null || typeof target !== 'object') {
      throw new Error(
        '[contract] cannot assign to a property of a non-object',
      );
    }
    (target as Record<string, unknown>)[property] = value;
  };
  mutateStateRoot(scope, stateRoot, write);
}

function assignIndex(
  scope: Scope,
  object: () => unknown,
  index: () => unknown,
  stateRoot: string | null,
  value: unknown,
): void {
  const write = () => {
    const target = object();
    const key = index();
    if (target == null) {
      throw new Error('[contract] cannot assign into null/undefined');
    }
    (target as Record<string | number, unknown>)[
      key as string | number
    ] = value;
  };
  mutateStateRoot(scope, stateRoot, write);
}

function mutateStateRoot(
  scope: Scope,
  stateRoot: string | null,
  write: () => void,
): void {
  const root = stateRoot ? scope.lookup(stateRoot) : null;
  if (root?.kind === 'state') root.mutate(write);
  else write();
}

function resume(
  pending: Promise<unknown>,
  continuationFence: ExecutionContinuationFence | undefined,
  next: () => unknown | Promise<unknown>,
): Promise<unknown> {
  const fenced = continuationFence
    ? continuationFence.raceContinuation(pending)
    : pending;
  return fenced.then((settled) =>
    isExecutionDisposedOutcome(settled) ? settled : next(),
  );
}

function resumeAwait(
  pending: Promise<unknown>,
  continuationFence: ExecutionContinuationFence | undefined,
  span: SpanPlan,
  next: (resolved: unknown) => unknown | Promise<unknown>,
): Promise<unknown> {
  const fenced = continuationFence
    ? continuationFence.raceContinuation(pending)
    : pending;
  return fenced.then(
    (resolved) =>
      isExecutionDisposedOutcome(resolved) ? resolved : next(resolved),
    (error) => {
      decorateContractError(error, { span: spanFrom(span) });
      throw error;
    },
  );
}

function runLoop(
  iterable: unknown,
  item: string,
  scope: Scope,
  runSegment: RunSegment,
  continuationFence: ExecutionContinuationFence | undefined,
  body: (
    loopScope: Scope,
    runSegment: RunSegment,
    continuationFence?: ExecutionContinuationFence,
  ) => unknown | Promise<unknown>,
): unknown | Promise<unknown> {
  if (!Array.isArray(iterable)) {
    throw new Error('[contract] for ... in expects an array');
  }
  const runIteration = (index: number): unknown | Promise<unknown> => {
    if (index >= iterable.length) return undefined;
    const loopScope = scope.child();
    loopScope.defineLocal(item, iterable[index]);
    const result = body(loopScope, runSegment, continuationFence);
    if (result instanceof Promise) {
      const fenced = continuationFence
        ? continuationFence.raceContinuation(result)
        : result;
      return fenced.then((settled) =>
        isExecutionDisposedOutcome(settled)
          ? settled
          : runIteration(index + 1),
      );
    }
    return runIteration(index + 1);
  };
  return runIteration(0);
}

function returnValue(value: unknown): never {
  throw new DirectReturnSignal(value);
}

function finish(
  run: () => unknown | Promise<unknown>,
): unknown | Promise<unknown> {
  try {
    const result = run();
    if (result instanceof Promise) {
      return result.catch((error) => {
        if (error instanceof DirectReturnSignal) return error.value;
        throw error;
      });
    }
    return result;
  } catch (error) {
    if (error instanceof DirectReturnSignal) return error.value;
    throw error;
  }
}

function spanFrom(span: SpanPlan): Span {
  return {
    line: span[0],
    col: span[1],
    len: span[2],
    offset: span[3],
  };
}

export const contractDirectStatementRuntime = {
  l: withLocus,
  n: assignName,
  m: assignMember,
  x: assignIndex,
  c: resume,
  a: resumeAwait,
  f: runLoop,
  r: returnValue,
  h: finish,
} as const;
