// @system @ref LLP 0292 / LLP 0373 P1 runtime budgets — tiny shared
// viewport host ingress. This module intentionally has no component-runtime
// dependency so generated host declarations do not retain instance.ts.

export interface ContractViewportSize {
  width: number;
  height: number;
}

function hasViewportDom(): boolean {
  return typeof document !== 'undefined' && typeof window !== 'undefined';
}

interface ExactViewportHostBridge {
  viewport?: unknown;
  screenWidth?: unknown;
  screenHeight?: unknown;
}

function finitePositiveViewportDimension(value: unknown): number | null {
  return typeof value === 'number' && Number.isFinite(value) && value > 0
    ? value
    : null;
}

function readViewportHostBridge(): ContractViewportSize | null {
  const exact = (globalThis as { exact?: ExactViewportHostBridge }).exact;
  if (!exact || typeof exact !== 'object') return null;
  if (exact.viewport && typeof exact.viewport === 'object') {
    const nested = exact.viewport as Record<string, unknown>;
    const width = finitePositiveViewportDimension(nested.width);
    const height = finitePositiveViewportDimension(nested.height);
    if (width !== null && height !== null) return { width, height };
  }
  const width = finitePositiveViewportDimension(exact.screenWidth);
  const height = finitePositiveViewportDimension(exact.screenHeight);
  return width !== null && height !== null ? { width, height } : null;
}

/** Current viewport size; native bridge fallback or `{0, 0}` without a DOM. */
export function readViewportHostSize(): ContractViewportSize {
  if (!hasViewportDom()) {
    return readViewportHostBridge() ?? { width: 0, height: 0 };
  }
  return {
    width: typeof window.innerWidth === 'number' ? window.innerWidth : 0,
    height: typeof window.innerHeight === 'number' ? window.innerHeight : 0,
  };
}

type ViewportHostInputListener = (size: ContractViewportSize) => void;

const viewportHostInputListeners =
  /* @__PURE__ */ new Set<ViewportHostInputListener>();
let removeViewportWindowListener: (() => void) | null = null;

/** Tiny host-transaction ingress shared by the conditional D1 extension. */
export function publishViewportHostInput(size: ContractViewportSize): void {
  for (const subscriber of [...viewportHostInputListeners]) subscriber(size);
}

export function subscribeViewportHostInput(
  listener: ViewportHostInputListener,
): () => void {
  viewportHostInputListeners.add(listener);
  if (
    hasViewportDom() &&
    typeof window.addEventListener === 'function' &&
    !removeViewportWindowListener
  ) {
    const onResize = (): void => {
      const size = readViewportHostSize();
      viewportHostInputListeners.forEach((subscriber) => subscriber(size));
    };
    window.addEventListener('resize', onResize);
    removeViewportWindowListener = () =>
      window.removeEventListener('resize', onResize);
  }
  return () => {
    viewportHostInputListeners.delete(listener);
    if (
      viewportHostInputListeners.size === 0 &&
      removeViewportWindowListener
    ) {
      removeViewportWindowListener();
      removeViewportWindowListener = null;
    }
  };
}
