// @system @ref RFC 0101 SG2 / LLP 0353 §2 — the Contract→scene binding.
//
// Mounts a `graphics` surface's scene IR into a GraphicsScene: static attrs
// apply at node creation, dynamic attrs re-apply through ownedEffect (the
// transactional lane — RFC 0101 §12 "framework-driven updates"), and
// `when`/`each` control flow anchors inside dedicated group nodes so
// structural changes never disturb sibling paint order. Per-frame batch
// columns do NOT travel through here — the graphicsSurface() behavior's
// `.batch()` writer mutates node props directly on the rAF clock
// (RFC 0101 §12 "imperative"), one commit op per frame.
//
// §12 single-writer commit model: on the single-threaded web host every
// mutation lane (effects here, rAF writers, HMR disposal) runs on one
// thread, so atomicity is trivial; the scene's microtask-coalesced commit
// is the one commit point every later backend inherits.

import type {
  GraphicsNodeProps,
  GraphicsNodeHandle,
  GraphicsNodeType,
  GraphicsScene,
} from '@exact/graphics';
import type { GraphicsSurfaceBehavior } from '@exact/graphics/contract';

import type { Expr, GraphicsSceneNodeIR } from '../compiler/ir.js';
import { evalRuntimeExpr } from './execution.js';
import { Scope } from './interpreter.js';
import { ownedEffect, signal, untrack, type Signal } from './signals.js';
export {
  graphicsSurfaceEventSink,
  registerGraphicsSurfaceScene,
  unregisterGraphicsSurfaceScene,
  type RegisteredGraphicsSurface,
} from './graphics-surface-registry.js';

const SCENE_EVAL = { identFallbackToString: true } as const;

export interface MountedScene {
  dispose(): void;
}

interface SceneMountContext {
  scene: GraphicsScene;
  behavior: GraphicsSurfaceBehavior | undefined;
  /** One loud structured diagnostic per surface per gap class (LLP 0382). */
  reportedGaps: Set<string>;
  surfaceLabel: string;
}

/** Literal expression kinds whose value can never change reactively. */
function staticExprValue(expr: Expr): { value: unknown } | null {
  switch (expr.kind) {
    case 'string':
    case 'number':
    case 'boolean':
      return { value: expr.value };
    case 'null':
      return { value: null };
    default:
      return null;
  }
}

function reportGapOnce(context: SceneMountContext, code: string, message: string): void {
  if (context.reportedGaps.has(code)) {
    return;
  }
  context.reportedGaps.add(code);
  console.warn(`[graphics] ${context.surfaceLabel}: ${message}`, { code });
}

export function mountGraphicsSceneNodes(
  nodes: readonly GraphicsSceneNodeIR[],
  parent: GraphicsNodeHandle | null,
  scope: Scope,
  context: SceneMountContext,
): MountedScene {
  const disposers: Array<() => void> = [];
  const disposeAll = (): void => {
    for (const dispose of [...disposers].reverse()) {
      dispose();
    }
  };

  const appendToParent = (handle: GraphicsNodeHandle): void => {
    if (parent) {
      parent.appendChild(handle);
    }
  };

  try {
    for (const node of nodes) {
      switch (node.kind) {
        case 'scene-element': {
          // Unknown/view/component tags were rejected by the analyzer; if an
          // artifact reaches here anyway, fail closed and loudly.
          const type = node.tag as GraphicsNodeType;
          const initial: GraphicsNodeProps = {};
          const dynamic: Array<[string, Expr]> = [];
          for (const [name, expr] of Object.entries(node.props)) {
            const literal = staticExprValue(expr);
            if (literal) {
              initial[name] = literal.value;
            } else {
              // Dynamic attrs (including graphicsId templates) evaluate once
              // for identity-bearing attrs and reactively for the rest —
              // graphicsId is immutable after creation (LLP 0353 §3).
              if (name === 'graphicsId') {
                const identity = untrack(() => evalRuntimeExpr(expr, scope, SCENE_EVAL));
                // Fail closed at mount: coercing undefined/null/'' through
                // String(...) would register the literal "undefined"/"null"
                // and only surface later as a confusing DUPLICATE_GRAPHICS_ID
                // refusal when a second node makes the same mistake.
                if (
                  (typeof identity !== 'string' || identity.length === 0) &&
                  typeof identity !== 'number'
                ) {
                  throw new Error(
                    `[graphics] ${context.surfaceLabel}: graphicsId at ${node.span.line}:${node.span.col} evaluated to ${
                      identity === undefined ? 'undefined' : JSON.stringify(identity)
                    } — graphicsId must be a non-empty string or a number (LLP 0353 §3)`,
                  );
                }
                initial[name] = String(identity);
              } else {
                dynamic.push([name, expr]);
              }
            }
          }
          if (Object.keys(node.events).length > 0) {
            reportGapOnce(
              context,
              'graphics_scene_handlers_undispatched',
              'scene-node event handlers are declared but SG2 has no scene hit-testing — handlers never fire on this surface (RFC 0101 Phase 1 item 8 gap)',
            );
          }
          const handle = context.scene.createNode(type, initial);
          const graphicsId = typeof initial.graphicsId === 'string' ? initial.graphicsId : undefined;
          const attrEffects: Array<() => void> = [];
          let childMount: MountedScene;
          // Mount-path exception safety: a throw from an attr effect's first
          // eval or a child mount must not leak this node — a leaked scene
          // node turns a retry mount into a DUPLICATE_GRAPHICS_ID refusal.
          try {
            appendToParent(handle);
            if (graphicsId && context.behavior) {
              context.behavior.__registerSceneNode(graphicsId, handle);
            }
            for (const [name, expr] of dynamic) {
              const effectHandle = ownedEffect(() => {
                handle.update({ [name]: evalRuntimeExpr(expr, scope, SCENE_EVAL) });
              });
              attrEffects.push(() => effectHandle.dispose());
            }
            childMount = mountGraphicsSceneNodes(node.children, handle, scope, context);
          } catch (error) {
            for (const dispose of attrEffects) {
              dispose();
            }
            if (graphicsId && context.behavior) {
              context.behavior.__unregisterSceneNode(graphicsId);
            }
            handle.remove();
            throw error;
          }
          // One composite disposer so the internal order is fixed: attr
          // effects, then child mounts, then this node's removal —
          // handle.remove() deletes the whole subtree from the authoring map,
          // so any child disposer running after it would hit a stale record
          // and throw in development mode.
          disposers.push(() => {
            for (const dispose of attrEffects) {
              dispose();
            }
            childMount.dispose();
            if (graphicsId && context.behavior) {
              context.behavior.__unregisterSceneNode(graphicsId);
            }
            handle.remove();
          });
          break;
        }
        case 'scene-when': {
          // Anchor group keeps sibling paint order stable across toggles.
          const anchor = context.scene.createGroup();
          let active: MountedScene | null = null;
          let activeBranch: 'then' | 'else' | 'none' = 'none';
          // Mount-path exception safety (the scene-element pattern): the
          // disposer below is only pushed after ownedEffect returns, but the
          // effect body runs synchronously and rethrows — a branch mount that
          // fails on the first run would otherwise leak the anchor group in
          // the authoring scene, beyond the outer disposeAll's reach.
          try {
            appendToParent(anchor);
            const effectHandle = ownedEffect(() => {
              const test = Boolean(evalRuntimeExpr(node.test, scope, SCENE_EVAL));
              const nextBranch = test ? 'then' : node.else ? 'else' : 'none';
              if (nextBranch === activeBranch) {
                return;
              }
              active?.dispose();
              active = null;
              activeBranch = nextBranch;
              if (nextBranch === 'then') {
                active = mountGraphicsSceneNodes(node.then, anchor, scope, context);
              } else if (nextBranch === 'else' && node.else) {
                active = mountGraphicsSceneNodes(node.else, anchor, scope, context);
              }
            });
            disposers.push(() => {
              effectHandle.dispose();
              active?.dispose();
              anchor.remove();
            });
          } catch (error) {
            // First-run failure only (re-runs flush through the scheduler and
            // never pass here): the branch mount unwound its own subtree, so
            // `active` was never assigned — only the anchor needs removal.
            // Rethrow so the outer disposeAll unwinds earlier siblings.
            anchor.remove();
            throw error;
          }
          break;
        }
        case 'scene-each': {
          const anchor = context.scene.createGroup();
          interface EachSlot {
            group: GraphicsNodeHandle;
            item: Signal<unknown>;
            index: Signal<number>;
            mounted: MountedScene;
          }
          const slots = new Map<unknown, EachSlot>();
          let order: unknown[] = [];
          // The slot group of the item currently mounting — visible to the
          // first-run unwind below so a mid-list mount failure cannot leak
          // it (its body unwinds itself, but the group is created here).
          let mountingGroup: GraphicsNodeHandle | null = null;
          // Mount-path exception safety (the scene-element pattern): the
          // disposer below is only pushed after ownedEffect returns, but the
          // effect body runs synchronously and rethrows — an item body that
          // fails on the first run would otherwise leak the anchor group and
          // every earlier fully-mounted slot (including graphicsId-bearing
          // nodes, turning a retry into a DUPLICATE_GRAPHICS_ID refusal).
          try {
            appendToParent(anchor);
            const effectHandle = ownedEffect(() => {
              const iterable = evalRuntimeExpr(node.iterable, scope, SCENE_EVAL);
              const items: unknown[] = Array.isArray(iterable) ? iterable : [];
              const seen = new Set<unknown>();
              const appended: unknown[] = [];
              items.forEach((item, index) => {
                const key = untrack(() => {
                  const itemScope = scope.child();
                  itemScope.defineValue(node.item, item);
                  if (node.index) itemScope.defineValue(node.index, index);
                  return evalRuntimeExpr(node.key, itemScope, SCENE_EVAL);
                });
                if (seen.has(key)) {
                  // Deterministic duplicate handling: first occurrence wins,
                  // later duplicates are skipped (never slot hijacking).
                  reportGapOnce(
                    context,
                    'graphics_each_duplicate_key',
                    `each key ${JSON.stringify(key)} is duplicated — the first occurrence wins and later duplicates are skipped`,
                  );
                  return;
                }
                seen.add(key);
                const existing = slots.get(key);
                if (existing) {
                  existing.item.set(item);
                  existing.index.set(index);
                  return;
                }
                const itemSignal = signal(item);
                const indexSignal = signal(index);
                const slotScope = scope.child();
                slotScope.define(node.item, { kind: 'getter', get: () => itemSignal.get() });
                if (node.index) {
                  slotScope.define(node.index, { kind: 'getter', get: () => indexSignal.get() });
                }
                const group = context.scene.createGroup();
                anchor.appendChild(group);
                mountingGroup = group;
                const mounted = mountGraphicsSceneNodes(node.body, group, slotScope, context);
                mountingGroup = null;
                slots.set(key, { group, item: itemSignal, index: indexSignal, mounted });
                appended.push(key);
              });
              for (const [key, slot] of [...slots]) {
                if (!seen.has(key)) {
                  slot.mounted.dispose();
                  slot.group.remove();
                  slots.delete(key);
                }
              }
              // Order maintenance: after removals the anchor holds survivors in
              // their previous order with new groups appended at the end. Only
              // when that differs from the item order do we issue reorder ops —
              // unconditional re-appends emit N no-op operations per data update
              // and can trip maxOperationsPerCommit.
              const current = [...order.filter((key) => slots.has(key)), ...appended];
              const desired = [...seen];
              if (
                current.length !== desired.length ||
                current.some((key, position) => key !== desired[position])
              ) {
                for (const key of desired) {
                  const slot = slots.get(key);
                  if (slot) anchor.appendChild(slot.group);
                }
              }
              order = desired;
            });
            disposers.push(() => {
              effectHandle.dispose();
              for (const slot of slots.values()) {
                slot.mounted.dispose();
                slot.group.remove();
              }
              slots.clear();
              anchor.remove();
            });
          } catch (error) {
            // First-run failure only (re-runs flush through the scheduler and
            // never pass here): dispose the earlier fully-mounted slots,
            // remove the failing item's group (its body already unwound its
            // own children), then the anchor. Rethrow so the outer disposeAll
            // unwinds earlier siblings.
            for (const slot of slots.values()) {
              slot.mounted.dispose();
              slot.group.remove();
            }
            slots.clear();
            (mountingGroup as GraphicsNodeHandle | null)?.remove();
            anchor.remove();
            throw error;
          }
          break;
        }
        case 'scene-semantics': {
          // Mode B projections have no runtime projection target in SG2 —
          // the semantics tree integration is RFC 0101 Phase 1 item 8 /
          // Phase 2 work. Parsed, validated, and loudly inert.
          reportGapOnce(
            context,
            'graphics_semantics_unprojected',
            'the semantics block is not projected in SG2 — scene content is exposed only through the surface\'s own role/label (RFC 0101 Phase 1 item 8 gap)',
          );
          break;
        }
        case 'scene-projection':
          // Covered by the scene-semantics gap report (projections are only
          // legal inside the block; stray ones were analyzer errors).
          break;
        default: {
          const exhaustive: never = node;
          throw new Error(`unhandled graphics scene node ${(exhaustive as { kind?: string }).kind}`);
        }
      }
    }
  } catch (error) {
    // Sibling unwind: nodes mounted earlier in this list must not survive a
    // failed mount — the view layer only disposes a MountedScene it received,
    // so anything left behind here would leak until the next full reset.
    disposeAll();
    throw error;
  }

  return { dispose: disposeAll };
}

export function createSceneMountContext(
  scene: GraphicsScene,
  behavior: GraphicsSurfaceBehavior | undefined,
  surfaceLabel: string,
): SceneMountContext {
  return { scene, behavior, reportedGaps: new Set(), surfaceLabel };
}
