// @system @ref LLP 0185 §§3,4.3 / LLP 0373 P1 runtime budgets — keep the
// always-loaded component runtime independent of the opt-in Motion engine.
// This module owns only the tiny lifetime context shared across that seam;
// importing Contract runtime without `@exact/contract/motion` must not make
// the complete Motion implementation reachable in a production bundle.

import type { Owner } from './signals.js';

export interface MotionRunOnJSOwnerFence {
  active: boolean;
  generation: number;
}

const runOnJsOwnerFences = new WeakMap<Owner, MotionRunOnJSOwnerFence>();
const runOnJsCallbackOwners = new WeakMap<Function, MotionRunOnJSOwnerFence>();

let currentRootLabel: string | null = null;

function runOnJsOwnerFence(owner: Owner): MotionRunOnJSOwnerFence {
  const existing = runOnJsOwnerFences.get(owner);
  if (existing) return existing;

  const fence = { active: true, generation: 1 };
  runOnJsOwnerFences.set(owner, fence);
  owner.register(() => {
    fence.active = false;
    fence.generation += 1;
  });
  return fence;
}

/** @internal Attribute Motion artifacts created by `fn` to a Contract root. */
export function withMotionRootScope<T>(rootLabel: string, fn: () => T): T {
  const previous = currentRootLabel;
  currentRootLabel = rootLabel;
  try {
    return fn();
  } finally {
    currentRootLabel = previous;
  }
}

/** @internal Current Contract-root attribution for an opt-in Motion artifact. */
export function currentMotionRootLabel(): string | null {
  return currentRootLabel;
}

/** @internal Bind an interpreted Contract action to its component lifetime. */
export function registerMotionRunOnJSCallbackOwner(
  callback: Function,
  owner: Owner,
): void {
  runOnJsCallbackOwners.set(callback, runOnJsOwnerFence(owner));
}

/** @internal Resolve the lifetime fence captured by a queued runOnJS call. */
export function motionRunOnJSOwnerFence(
  callback: Function,
  ambientOwner: Owner | null,
): MotionRunOnJSOwnerFence | null {
  return runOnJsCallbackOwners.get(callback) ??
    (ambientOwner ? runOnJsOwnerFence(ambientOwner) : null);
}
