// @system @ref LLP 0185 S2 — straight-line Contract component calls.

import { hasMotionCommandRefBrand } from '@exact/renderer/motion-command-ref';

import type { Span, ViewNodeIR } from '../compiler/ir.js';
import { isCompiledComponent } from './define.js';
import {
  decorateContractError,
  reportContractRuntimeError,
  runWithContractErrorLocus,
  type ContractErrorLocus,
} from './error-locus-runtime.js';
import { contractHydrationNodeId } from './hydration.js';
import { instantiateComponent, type PropValue } from './instance.js';
import type { Scope } from './interpreter.js';
import { runWithOwner, untrack } from './signals.js';
import { mountContractAotViewNodes } from './aot-view-runtime.js';
import type { ContractMountViewNodes } from './aot-view-region.js';
import { structuralIdsFor } from './view-identity.js';
import type { AnchorFn, HostParent, Mounted, MountEnv } from './view.js';

const VIEW_EVAL = { identFallbackToString: true } as const;
type ContractComponentEvaluator = (
  scope: Scope,
  options?: typeof VIEW_EVAL,
) => unknown;

type ContractComponentPropPlan = readonly [
  name: string,
  valueOrEvaluate: unknown,
  relayMode?: 1 | 2,
];

type ContractComponentEventPlan = readonly [
  name: string,
  evaluate: ContractComponentEvaluator,
  relayMode?: 1 | 2,
];

export type ContractAotComponentPlan = readonly [
  name: string,
  props: readonly ContractComponentPropPlan[],
  events: readonly ContractComponentEventPlan[],
  line: number,
  col: number,
  len: number,
  offset: number,
];

export function mountContractComponent(
  plan: ContractAotComponentPlan,
  node: ViewNodeIR,
  children: readonly ViewNodeIR[],
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  mountNodes: ContractMountViewNodes = mountContractAotViewNodes,
): Mounted {
  const [name, propPlans, eventPlans, line, col, len, offset] = plan;
  const structuralId = env.ids.get(node) ?? null;
  const span: Span = { line, col, len, offset };
  const binding = env.scope.lookup(name);
  const resolved = untrack(() => binding
    ? binding.kind === 'value' || binding.kind === 'local'
      ? binding.value
      : binding.get()
    : undefined);
  if (!isCompiledComponent(resolved)) {
    throw new Error(`[contract] "${name}" did not resolve to a Contract component`);
  }

  const locus = (region: string): ContractErrorLocus => ({
    component: env.component.name,
    sourcePath: env.component.file.sourcePath,
    region,
    span,
  });
  const relay = (
    evaluate: ContractComponentEvaluator,
    mode: 1 | 2 | undefined,
    errorLocus: ContractErrorLocus,
  ): unknown => {
    if (mode === 2) {
      const candidate = untrack(() => evaluate(env.scope, VIEW_EVAL));
      if (hasMotionCommandRefBrand(candidate)) return candidate;
    }
    return (...args: unknown[]): unknown => {
      try {
        if (mode === 1) return untrack(() => evaluate(env.scope, VIEW_EVAL));
        const handler = untrack(() => evaluate(env.scope, VIEW_EVAL));
        return typeof handler === 'function' ? handler(...args) : undefined;
      } catch (error) {
        decorateContractError(error, errorLocus);
        reportContractRuntimeError(error);
        throw error;
      }
    };
  };

  const actionTyped = new Set(
    resolved.ir.props
      .filter((prop) => prop.parsedType?.ir.kind === 'action')
      .map((prop) => prop.name),
  );
  const props: Record<string, PropValue> = {};
  propPlans.forEach(([propName, valueOrEvaluate, relayMode]) => {
    const literal = typeof valueOrEvaluate !== 'function';
    if (actionTyped.has(propName)) {
      props[propName] = {
        kind: 'value',
        value: literal
          ? () => undefined
          : relay(
              valueOrEvaluate as ContractComponentEvaluator,
              relayMode,
              locus(`action prop "${propName}"`),
            ),
      };
    } else if (literal) {
      props[propName] = { kind: 'value', value: valueOrEvaluate };
    } else {
      const propLocus = locus(`prop "${propName}"`);
      const evaluate = valueOrEvaluate as ContractComponentEvaluator;
      props[propName] = {
        kind: 'getter',
        get: () => runWithContractErrorLocus(
          propLocus,
          () => evaluate(env.scope, VIEW_EVAL),
        ),
      };
    }
  });
  eventPlans.forEach(([event, evaluate, relayMode]) => {
    props[event] = {
      kind: 'value',
      value: relay(evaluate, relayMode, locus(`event "${event}"`)),
    };
  });

  const hydrationNodeId = structuralId &&
      (env.ctx.hydration?.capture || env.ctx.routePayloadCapture)
    ? contractHydrationNodeId({
        prefix: env.hydrationPrefix,
        structuralId,
        keyChain: env.hydrationKeyChain,
      })
    : undefined;
  const childInstance = instantiateComponent(resolved, props, env.ctx, {
    hydrationNodeId: hydrationNodeId ?? `${env.hydrationPrefix}${resolved.ir.name}/v`,
    hydrationStructuralId: structuralId ?? undefined,
    hydrationKeyChain: env.hydrationKeyChain,
    logicalInstancePath: [
      ...env.instance.logicalInstancePath,
      logicalPathSegment('call', structuralId ?? name),
      ...env.logicalKeyPath.map((key) => logicalPathSegment('key', key)),
    ],
  });
  const childrenSlot = children.length > 0
    ? (slotParent: HostParent, slotAnchor: AnchorFn | null) =>
        mountNodes(children, slotParent, slotAnchor, { ...env, isRootView: false })
    : null;
  const mounted = runWithOwner(childInstance.owner, () => mountNodes(
    [resolved.ir.view],
    parent,
    anchor,
    {
      instance: childInstance,
      scope: childInstance.scope,
      component: resolved,
      ctx: env.ctx,
      childrenSlot,
      isRootView: env.isRootView,
      inRepetitionScope: env.inRepetitionScope,
      repetitionIndex: env.repetitionIndex,
      ids: structuralIdsFor(resolved.ir),
      keyChain: env.keyChain,
      logicalKeyPath: [],
      hydrationPrefix: hydrationNodeId ? `${hydrationNodeId}>` : env.hydrationPrefix,
      hydrationKeyChain: '',
      dismissLayerParentId: env.dismissLayerParentId,
    },
  ));
  childInstance.hostNodes = () => mounted.hostNodes();
  return mounted;
}

function logicalPathSegment(kind: 'call' | 'key', value: string): string {
  return `${kind}:${value.length}:${value}`;
}
