// @system @ref LLP 0099#M8 — lightweight command-reference identity boundary.

export const MOTION_COMMAND_REF_KIND = Symbol.for('exact.motion.command-ref');

interface MotionCommandRefShape {
  readonly __exactMotionCommandKind: typeof MOTION_COMMAND_REF_KIND;
  readonly identity?: {
    readonly commandInstanceId?: unknown;
  };
}

/**
 * Recognize the stable cross-module CommandRef brand without retaining the
 * command registry, diagnostics, native dispatch, and receipt implementation.
 */
export function hasMotionCommandRefBrand(value: unknown): boolean {
  return typeof value === 'function' &&
    (value as Partial<MotionCommandRefShape>).__exactMotionCommandKind === MOTION_COMMAND_REF_KIND &&
    typeof (value as Partial<MotionCommandRefShape>).identity?.commandInstanceId === 'string';
}
