// @system @ref LLP 0166 §4.6 (S0b) — the minimal non-lossy value printer.
//
// Non-lossy printing for the editable subset: string literals with real
// escaping, numbers, booleans, null, and (with S1) token references. This is
// what lets the edit authority lift the commit plane's quoting bans without
// re-creating a tiny second printer outside the compiler — the S2 whole-file
// formatter EXTENDS this module; a sibling implementation is the failure
// mode (LLP 0166 §8). `printExpr` in runtime/provenance.ts remains the
// lossy display printer; this is its non-lossy sibling.
//
// Law (verified by fixture): for every printable value,
// parseExpressionSource(printValue(expr)) is Expr-identical modulo spans.

import type { Expr } from './ir.js';

/** Escapes per the Contract lexer's string grammar (double-quoted form). */
function printString(value: string): string {
  let out = '"';
  for (let i = 0; i < value.length; i += 1) {
    const ch = value[i];
    switch (ch) {
      case '\\':
        out += '\\\\';
        break;
      case '"':
        out += '\\"';
        break;
      case '\n':
        out += '\\n';
        break;
      case '\t':
        out += '\\t';
        break;
      case '\r':
        out += '\\r';
        break;
      default:
        out += ch;
    }
  }
  return out + '"';
}

function printNumber(value: number): string {
  if (!Number.isFinite(value)) {
    throw new TypeError(`cannot print non-finite number ${value} as Contract source`);
  }
  return String(value);
}

/**
 * Prints a literal JS value as Contract source text. The non-lossy
 * replacement for the devtools `renderAttrLiteral` (which it absorbs —
 * LLP 0166 S0b): strings of any content print with real escaping instead
 * of being banned.
 */
export function printLiteral(value: string | number | boolean | null): string {
  if (value === null) {
    return 'null';
  }
  switch (typeof value) {
    case 'string':
      return printString(value);
    case 'number':
      return printNumber(value);
    case 'boolean':
      return value ? 'true' : 'false';
    default:
      throw new TypeError(`cannot print ${typeof value} as a Contract literal`);
  }
}

/**
 * Prints an editable-subset Expr as Contract source text. Throws TypeError
 * on expressions outside the subset (computed expressions are locked slots;
 * nothing should ask to print them).
 */
export function printValue(expr: Expr): string {
  switch (expr.kind) {
    case 'token':
      return `$${expr.path}`;
    case 'string':
      return printString(expr.value);
    case 'number':
      return printNumber(expr.value);
    case 'boolean':
      return expr.value ? 'true' : 'false';
    case 'null':
      return 'null';
    case 'unary':
      if (expr.op === '-' && expr.operand.kind === 'number') {
        return `-${printNumber(expr.operand.value)}`;
      }
      throw new TypeError(`cannot print unary "${expr.op}" expression as a Contract value`);
    default:
      throw new TypeError(`cannot print ${expr.kind} expression as a Contract value`);
  }
}
