// @system @ref LLP 0094 Phase B, LLP 0082, LLP 0373 phase 3c — shared
// Contract root lifecycle. Editable mount.ts installs the generic view
// fallback; the production barrel imports this core directly.
//
// Modeled on the Solid adapter (packages/exact-renderer/src/solid.ts): the
// Contract runtime is a fifth framework adapter over the shared host-ops
// layer. One commit closes each reactive flush; reset() supports v0's
// reset-based HMR (LLP 0086).

import {
  commitBatch,
  createRoot,
  destroyRoot,
  getRootContainerForNode,
  setRootProtocolDispatchSuppressed,
  syncRootWindowState,
  type ElementNode,
  type RootNode,
} from '@exact/renderer/host-ops';
import { subscribeToRootWindowState } from '@exact/core/window-state';

import type { Mounted, mountViewNodes as GenericMountViewNodes } from './view.js';
import { CONTRACT_DEVELOPMENT, CONTRACT_PRODUCTION } from './build-mode.js';
import { structuralIdsFor } from './view-identity.js';
import { getContractAotViewClosure } from './aot-view-runtime.js';
import {
  reportContractRuntimeError,
  runWithContractErrorLocus,
} from './error-locus-runtime.js';
import {
  registerContractClauseWitnessInstance,
  watchContractInvariants,
} from './contract-monitor.js';
import {
  commitHydrationActivation,
  createRuntimeContext,
  drainMountTasks,
  instantiateComponent,
  registerHydrationActivation,
  type PropValue,
} from './instance.js';
import type { CompiledComponent } from './define.js';
import {
  batch,
  createOwner,
  onFlush,
  runWithContractReactiveQueueOwner,
  runWithOwner,
} from './signals.js';
import type { ContractHydrationRuntimeOptions } from './hydration.js';
import { ensureInputInventoryObserver } from './input-inventory.js';
import {
  captureMountedContractRoutePayloadTree,
  createContractRoutePayloadCaptureState,
} from './route-payload-capture-runtime.js';
import type { ContractRoutePayloadTreeCapture } from './route-payload-capture.js';
import { getDefaultContractRuntime, type ContractRuntime } from './contract-runtime.js';
import { resetContractListRestorationSeeds } from './list-restoration-seeds.js';

declare const __EXACT_CONTRACT_PRODUCTION__: boolean;
const CONTRACT_MOUNT_PRODUCTION =
  typeof __EXACT_CONTRACT_PRODUCTION__ !== 'undefined'
    ? __EXACT_CONTRACT_PRODUCTION__
    : CONTRACT_PRODUCTION;
const CONTRACT_MOUNT_DEV =
  typeof __EXACT_CONTRACT_PRODUCTION__ !== 'undefined'
    ? !__EXACT_CONTRACT_PRODUCTION__
    : CONTRACT_DEVELOPMENT;

// The editable runtime installs the exhaustive view interpreter through
// `mount-generic-view.ts`. Keeping that import out of this shared lifecycle
// file prevents compiler-closed production artifacts from retaining the
// generic interpreter solely for an unreachable development fallback.
let genericMountViewNodes: typeof GenericMountViewNodes | null = null;

export function registerContractGenericViewMount(
  mountViewNodes: typeof GenericMountViewNodes,
): void {
  genericMountViewNodes = mountViewNodes;
}

export interface MountOptions {
  rootId?: number;
  props?: Record<string, unknown>;
  /** `headless` mounts for tests/agents/server serialization suppress this root's protocol flush. */
  host?: 'default' | 'headless';
  /**
   * Mount into an existing host-ops parent owned by another adapter instead
   * of claiming a root. The Contract tree joins that node's root and commits
   * against it, so the host (native or web) renders it as ordinary children
   * of the surrounding tree — this is how `.contract` route modules embed
   * inside the React-rendered app shell on native (LLP 0160 §6 row 9).
   * `rootId` is ignored when `container` is set.
   */
  container?: ElementNode | RootNode;
  hydration?: ContractHydrationRuntimeOptions;
  /** Build-time only: retain the fully expanded semantic output tree. */
  captureRoutePayload?: boolean | {
    /** Compiler-derived cumulative row bound, enforced during mounting. */
    maxEachExpansions: number;
  };
  /** Explicit app-runtime owner; roots sharing it share effects/time/replay. */
  runtime?: ContractRuntime;
}

const CONTRACT_REACTIVE_MOUNT_PROP = Symbol.for('exact.contract.reactive-mount-prop');

interface ReactiveMountProp {
  readonly [CONTRACT_REACTIVE_MOUNT_PROP]: true;
  readonly read: () => unknown;
}

/**
 * Internal adapter seam for one Contract root to pass a live prop into
 * another root. Ordinary mount callers still pass values; declarative
 * windows use this wrapper so their child root observes parent signals
 * without teaching the public mount surface about framework internals.
 */
export function contractReactiveMountProp(read: () => unknown): unknown {
  return Object.freeze({
    [CONTRACT_REACTIVE_MOUNT_PROP]: true as const,
    read,
  });
}

function isReactiveMountProp(value: unknown): value is ReactiveMountProp {
  return Boolean(
    value &&
      typeof value === 'object' &&
      (value as Partial<ReactiveMountProp>)[CONTRACT_REACTIVE_MOUNT_PROP] === true &&
      typeof (value as Partial<ReactiveMountProp>).read === 'function',
  );
}

export interface MountHandle {
  /** The mounted host root container (useful for tests and tooling). */
  container: RootNode;
  /** Releases mount-triggered tasks that were deferred for DOM adoption. */
  releaseHydrationTasks?(): void;
  /** Available only when `captureRoutePayload` was requested. */
  captureRoutePayloadTree?(): ContractRoutePayloadTreeCapture;
  dispose(): void;
}

interface RootState {
  container: RootNode;
  unsubscribeWindowState: (() => void) | null;
  dispose: (() => void) | null;
  headless: boolean;
  /** Mounted component + props, retained for HMR remounts (ENG-22501). */
  component: CompiledComponent | null;
  props: Record<string, unknown> | undefined;
  /**
   * Identity of the logical mount chain occupying this root. An HMR remount
   * keeps the chain; a fresh `mount()` call starts a new one, so a stale
   * MountHandle from a replaced mount cannot dispose the replacement.
   */
  chain: symbol | null;
  runtime: ContractRuntime | null;
}

const rootStates = new Map<number, RootState>();

interface EmbeddedMountState {
  rootContainer: RootNode;
  dispose: () => void;
  /** Mount inputs retained for HMR remounts (ENG-22501). */
  component: CompiledComponent;
  props: Record<string, unknown> | undefined;
  parent: ElementNode | RootNode;
  headless: boolean;
  runtime: ContractRuntime;
}

// Embedded mounts (MountOptions.container) join a root another adapter owns,
// so they live outside rootStates: reset() must dispose them without
// destroying the foreign root, and hot-patch flushes must commit their roots.
const embeddedMounts = new Set<EmbeddedMountState>();

const headlessRootRefs = new Map<number, number>();

function installHeadlessProtocolDispatch(rootId: number): () => void {
  const refs = headlessRootRefs.get(rootId) ?? 0;
  // Reassert on every acquisition. destroyRoot deliberately clears renderer
  // state; if a root ID is reused while a stale embedded handle still holds a
  // ref, a new headless mount must restore suppression for the new root.
  setRootProtocolDispatchSuppressed(rootId, true);
  headlessRootRefs.set(rootId, refs + 1);
  return () => {
    const remaining = (headlessRootRefs.get(rootId) ?? 1) - 1;
    if (remaining <= 0) {
      headlessRootRefs.delete(rootId);
      setRootProtocolDispatchSuppressed(rootId, false);
    } else {
      headlessRootRefs.set(rootId, remaining);
    }
  };
}

/**
 * Commits every mounted root — the S4 hot-patch pipeline's single atomic
 * flush after applying host-ops updates outside the reactive system.
 */
export function commitMountedRoots(): void {
  rootStates.forEach((state) => {
    commitBatch(state.container);
  });
  embeddedMounts.forEach((state) => {
    commitBatch(state.rootContainer);
  });
}

function getOrCreateRootState(rootId: number): RootState {
  let state = rootStates.get(rootId);
  if (!state) {
    state = {
      container: createRoot(rootId, 'contract'),
      unsubscribeWindowState: null,
      dispose: null,
      headless: false,
      component: null,
      props: undefined,
      chain: null,
      runtime: null,
    };
    // Contract is a first-party host-ops adapter just like React/Solid/Vue:
    // a native window-state change must re-resolve the mounted root and
    // commit even when no Contract signal changed. This is the production
    // path that turns `__exactViewportChanged` into a re-encoded root
    // viewport; teardown owns the subscription with the root.
    const mountedState = state;
    state.unsubscribeWindowState = subscribeToRootWindowState(rootId, () => {
      syncRootWindowState(mountedState.container);
    });
    rootStates.set(rootId, state);
  }
  return state;
}

interface TreeMount {
  dispose: () => void;
  releaseHydrationTasks: () => void;
  captureRoutePayloadTree?: () => ContractRoutePayloadTreeCapture;
}

function runCleanupSteps(
  label: string,
  steps: ReadonlyArray<() => void>,
): void {
  // @ref LLP 0210 §4.9 — an aborted hydration owner must attempt every affine
  // cleanup before reporting the aggregate, rather than leak later owners.
  const errors: unknown[] = [];
  for (const step of steps) {
    try {
      step();
    } catch (error) {
      errors.push(error);
    }
  }
  if (errors.length === 1) throw errors[0];
  if (errors.length > 1) throw new AggregateError(errors, label);
}

/**
 * Shared mount body: instantiates the component, mounts its view under
 * `parent`, and keeps committing `rootContainer` on every reactive flush.
 */
function mountTree(
  component: CompiledComponent,
  parent: ElementNode | RootNode,
  rootContainer: RootNode,
  propsIn: Record<string, unknown> | undefined,
  hydration: ContractHydrationRuntimeOptions | undefined,
  captureRoutePayload: MountOptions['captureRoutePayload'],
  runtime: ContractRuntime,
): TreeMount {
  const rootOwner = createOwner();
  const routePayloadCapture = captureRoutePayload
    ? createContractRoutePayloadCaptureState(
        typeof captureRoutePayload === 'object'
          ? captureRoutePayload.maxEachExpansions
          : undefined,
      )
    : undefined;
  const ctx = createRuntimeContext(rootOwner, {
    hydration,
    rootId: rootContainer.rootId,
    routePayloadCapture,
    contractRuntime: runtime,
  });
  registerHydrationActivation(ctx, ensureInputInventoryObserver);

  const props: Record<string, PropValue> = {};
  for (const [name, value] of Object.entries(propsIn ?? {})) {
    props[name] = isReactiveMountProp(value)
      ? { kind: 'getter', get: value.read }
      : { kind: 'value', value };
  }

  let mounted: Mounted | null = null;
  let rootInstance: ReturnType<typeof instantiateComponent> | null = null;
  try {
    runWithContractReactiveQueueOwner(runtime, () => batch(() => {
      runWithOwner(rootOwner, () => {
        // @ref LLP 0386 §H2 — v1 gives the root component boundary and a
        // component-valued root view the same `<Component>/v` state key.
        // Historically the child's record overwrote an empty parent record.
        // Preserve the released bytes without last-write-wins by omitting only
        // that provably empty parent record; a stateful parent remains a
        // producer collision and therefore fails strict emission.
        const rootHydrationNodeId =
          component.ir.view.kind === 'component' &&
            component.ir.states.length === 0
            ? undefined
            : `${component.ir.name}/v`;
        const instance = instantiateComponent(component, props, ctx, {
          hydrationNodeId: rootHydrationNodeId,
          hydrationStructuralId: `${component.ir.name}/v`,
          hydrationKeyChain: '',
        });
        rootInstance = instance;
        const rootEnv = {
            instance,
            scope: instance.scope,
            component,
            ctx,
            childrenSlot: null,
            isRootView: true,
            inRepetitionScope: false,
            repetitionIndex: null,
            ids: structuralIdsFor(component.ir),
            keyChain: '',
            logicalKeyPath: [],
            hydrationPrefix: '',
            hydrationKeyChain: '',
          };
        const compiledRoot = getContractAotViewClosure(component.ir.view);
        mounted = runWithOwner(instance.owner, () => {
          if (compiledRoot) {
            const root = component.ir.view;
            return runWithContractErrorLocus({
              component: component.name,
              sourcePath: component.file.sourcePath,
              region: `view <${root.kind === 'element'
                ? root.tag
                : root.kind === 'component'
                  ? root.name
                  : root.kind}>`,
              span: root.span,
            }, () => compiledRoot(root, parent, () => null, rootEnv));
          }
          if (CONTRACT_MOUNT_PRODUCTION) {
            throw new Error(
              `[contract] production artifact omitted the AOT root view closure for component "${component.name}"`,
            );
          }
          if (!genericMountViewNodes) {
            throw new Error(
              `[contract] editable runtime did not install the generic view mount for component "${component.name}"`,
            );
          }
          return genericMountViewNodes([component.ir.view], parent, null, rootEnv);
        });
        instance.hostNodes = () => mounted?.hostNodes() ?? [];
      });
    }));
  } catch (error) {
    // Keep-last-good (ENG-22501): a mount that dies mid-way must not leak
    // partial host nodes into the committed tree. mountElement/mountText and
    // the collection wrappers register host-node removal with the owner
    // before evaluating bindings (ENG-22443), so disposing the root owner
    // rolls the partial mount back; the commit publishes the rollback.
    const errors: unknown[] = [error];
    try {
      rootOwner.dispose();
    } catch (cleanupError) {
      errors.push(cleanupError);
    } finally {
      // Rollback publication is independent from user/framework disposer
      // success: a throwing cleanup cannot strand a partially prepared tree.
      commitBatch(rootContainer);
    }
    if (errors.length > 1) {
      throw new AggregateError(errors, 'Contract mount preparation and cleanup failed');
    }
    throw error;
  }

  commitBatch(rootContainer);

  // Commit once after every reactive flush while this root is live.
  const stopCommitting = onFlush(() => {
    commitBatch(rootContainer);
  }, runtime);

  // Passive invariant clauses (LLP 0278 §4 mode 1): dev-only, checked
  // against the mounted subtree after the initial commit and after every
  // settled flush (registered after the commit hook so each check sees the
  // committed tree). No-op — and free — in production and for components
  // without invariant clauses.
  const stopInvariants = CONTRACT_MOUNT_DEV && rootInstance
    ? watchContractInvariants({
        instance: rootInstance,
        hostNodes: () => mounted?.hostNodes() ?? [],
      })
    : () => {};

  // On-demand clause witnessing for the exact_contract_witness agent op
  // (LLP 0293 ledger row 8): dev-only, no-op for components without a
  // `contract` block.
  if (CONTRACT_MOUNT_DEV && rootInstance) {
    registerContractClauseWitnessInstance(rootInstance, () => mounted?.hostNodes() ?? []);
  }

  // Mount tasks run after the first committed render (LLP 0082). Hydration
  // defers them until the DOM adoption scope releases, so server-rendered
  // `now()` text is not invalidated before the host has claimed nodes.
  let hydrationTasksReleased = !ctx.hydration?.deferMountTasks;
  const releaseHydrationTasks = (): void => {
    if (!hydrationTasksReleased && ctx.hydration?.capture) {
      ctx.hydration.capture.noteMountTasksReleasedBeforeAdoption();
    }
    hydrationTasksReleased = true;
    commitHydrationActivation(ctx);
    drainMountTasks(ctx);
    commitBatch(rootContainer);
  };
  if (hydrationTasksReleased) {
    releaseHydrationTasks();
  } else {
    ctx.hydration?.capture?.noteDeferredMountTasks(ctx.mountTaskQueue.length);
  }
  const stopDrainingMountTasks = onFlush(() => {
    if (hydrationTasksReleased) {
      drainMountTasks(ctx);
    } else {
      ctx.hydration?.capture?.noteDeferredMountTasks(ctx.mountTaskQueue.length);
    }
  }, runtime);

  return {
    releaseHydrationTasks,
    ...(routePayloadCapture === undefined ? {} : {
      captureRoutePayloadTree: () => captureMountedContractRoutePayloadTree(
        mounted?.hostNodes() ?? [],
        routePayloadCapture,
      ),
    }),
    dispose(): void {
      try {
        runCleanupSteps('multiple Contract mount disposers failed', [
          stopInvariants,
          stopCommitting,
          stopDrainingMountTasks,
          () => mounted?.dispose(),
          () => rootOwner.dispose(),
        ]);
      } finally {
        // DOM clear/replace custody is independent of cleanup success.
        commitBatch(rootContainer);
      }
    },
  };
}

/**
 * Mounts a compiled Contract component as a root. Subsequent mounts on the
 * same rootId replace the previous tree (reset semantics). With
 * `options.container`, mounts inside an existing host-ops parent instead —
 * the embedded form used by contract route modules inside the React shell.
 */
export function mount(component: CompiledComponent, options: MountOptions = {}): MountHandle {
  // Input inventory belongs to the mounted runtime, not to whichever
  // interaction binding happens to register first. This ordering also lets
  // the observer flip keyboard unknown→present before the same key event is
  // offered to a key line.
  if (!options.hydration?.deferActivation) {
    ensureInputInventoryObserver();
  }
  const runtime = options.runtime ?? getDefaultContractRuntime();
  if (options.container) {
    const rootContainer = getRootContainerForNode(options.container);
    if (!rootContainer) {
      throw new Error(
        '[contract] mount container is not attached to a host root; ' +
          'mount after the host has committed the container node',
      );
    }
    const restoreHeadlessDispatch = options.host === 'headless'
      ? installHeadlessProtocolDispatch(rootContainer.rootId)
      : () => {};
    let tree: TreeMount;
    try {
      tree = mountTree(
        component,
        options.container,
        rootContainer,
        options.props,
        options.hydration,
        options.captureRoutePayload,
        runtime,
      );
    } catch (error) {
      // ENG-22443: a first render has no last-good UI to keep — at least
      // report the authored locus + code frame and raise the dev overlay
      // instead of failing into a silently blank surface.
      reportContractRuntimeError(error, {
        component: component.ir.name,
        sourcePath: component.file.sourcePath,
        region: 'mount',
      });
      restoreHeadlessDispatch();
      throw error;
    }
    const state: EmbeddedMountState = {
      rootContainer,
      component,
      props: options.props,
      parent: options.container,
      headless: options.host === 'headless',
      runtime,
      dispose: (): void => {
        embeddedMounts.delete(state);
        runCleanupSteps('multiple embedded Contract disposers failed', [
          () => tree.dispose(),
          restoreHeadlessDispatch,
        ]);
      },
    };
    embeddedMounts.add(state);
    notifyContractMountObserver(component);
    return {
      container: rootContainer,
      releaseHydrationTasks: tree.releaseHydrationTasks,
      ...(tree.captureRoutePayloadTree === undefined
        ? {} : { captureRoutePayloadTree: tree.captureRoutePayloadTree }),
      // Delegate so the handle disposes whatever tree currently occupies
      // this embedded mount — an HMR remount replaces `state.dispose`.
      dispose: (): void => {
        state.dispose();
      },
    };
  }

  const rootId = options.rootId ?? 0;
  const state = getOrCreateRootState(rootId);
  const restoreHeadlessDispatch = options.host === 'headless'
    ? installHeadlessProtocolDispatch(rootId)
    : () => {};

  if (state.dispose) {
    state.dispose();
    state.dispose = null;
  }

  let tree: TreeMount;
  try {
    tree = mountTree(
      component,
      state.container,
      state.container,
      options.props,
      options.hydration,
      options.captureRoutePayload,
      runtime,
    );
  } catch (error) {
    // ENG-22443: see the embedded-mount catch above — report + overlay
    // before rethrowing so a failed first render is never a silent blank.
    reportContractRuntimeError(error, {
      component: component.ir.name,
      sourcePath: component.file.sourcePath,
      region: 'mount',
    });
    restoreHeadlessDispatch();
    throw error;
  }
  const chain = Symbol('contract-mount-chain');
  installRootTree(state, {
    component,
    props: options.props,
    headless: options.host === 'headless',
    chain,
    tree,
    runtime,
    release: restoreHeadlessDispatch,
  });
  notifyContractMountObserver(component);

  return {
    container: state.container,
    releaseHydrationTasks: tree.releaseHydrationTasks,
    ...(tree.captureRoutePayloadTree === undefined
      ? {} : { captureRoutePayloadTree: tree.captureRoutePayloadTree }),
    // Dispose the tree currently occupying this root as long as it belongs
    // to this mount chain (the initial mount or an HMR remount of it). A
    // later, unrelated mount() on the same rootId starts a new chain and is
    // not affected by stale handles.
    dispose: (): void => {
      if (state.chain === chain) {
        state.dispose?.();
      }
    },
  };
}

interface RootTreeInstall {
  component: CompiledComponent;
  props: Record<string, unknown> | undefined;
  headless: boolean;
  chain: symbol;
  tree: TreeMount;
  release: () => void;
  runtime: ContractRuntime;
}

function installRootTree(state: RootState, install: RootTreeInstall): void {
  const dispose = (): void => {
    runCleanupSteps('multiple Contract root disposers failed', [
      () => install.tree.dispose(),
      () => {
        if (state.dispose === dispose) {
          state.dispose = null;
          state.headless = false;
          state.component = null;
          state.props = undefined;
          state.chain = null;
          state.runtime = null;
        }
      },
      install.release,
    ]);
  };
  state.dispose = dispose;
  state.headless = install.headless;
  state.component = install.component;
  state.props = install.props;
  state.chain = install.chain;
  state.runtime = install.runtime;
}

// ---------------------------------------------------------------------------
// HMR remounts (ENG-22501)
// ---------------------------------------------------------------------------

export interface ContractRemountTarget {
  /** The compiled component currently mounted on this surface. */
  component: CompiledComponent;
  /**
   * Replaces the mounted tree with `next`, keep-last-good: the incoming tree
   * mounts before the previous one is disposed (both exist only inside one
   * synchronous swap — no paint in between), and a throwing mount leaves the
   * previous tree committed with the partial mount rolled back.
   */
  remount(next: CompiledComponent): void;
}

/**
 * Live mount surfaces whose component was defined by `sourcePath` — the
 * hot-update pipeline remounts these in place instead of asking Vite to
 * invalidate (which, with no accepting parent, means a full page reload
 * that destroys the last-good UI; ENG-22501).
 */
export function getContractRemountTargets(sourcePath: string): ContractRemountTarget[] {
  const targets: ContractRemountTarget[] = [];
  rootStates.forEach((state) => {
    const component = state.component;
    if (component && component.file.sourcePath === sourcePath && state.dispose) {
      targets.push({
        component,
        remount: (next) => {
          remountRootState(state, next);
        },
      });
    }
  });
  embeddedMounts.forEach((state) => {
    if (state.component.file.sourcePath === sourcePath) {
      targets.push({
        component: state.component,
        remount: (next) => {
          remountEmbeddedMount(state, next);
        },
      });
    }
  });
  return targets;
}

function remountRootState(state: RootState, next: CompiledComponent): void {
  const props = state.props;
  const headless = state.headless;
  const chain = state.chain ?? Symbol('contract-mount-chain');
  const release = headless
    ? installHeadlessProtocolDispatch(state.container.rootId)
    : () => {};
  const runtime = state.runtime ?? getDefaultContractRuntime();
  let tree: TreeMount;
  try {
    tree = mountTree(
      next,
      state.container,
      state.container,
      props,
      undefined,
      false,
      runtime,
    );
  } catch (error) {
    release();
    throw error;
  }
  // Keep-last-good ordering: dispose the previous tree only after the
  // incoming one mounted successfully.
  state.dispose?.();
  installRootTree(state, { component: next, props, headless, chain, tree, release, runtime });
  notifyContractMountObserver(next);
}

function remountEmbeddedMount(state: EmbeddedMountState, next: CompiledComponent): void {
  const rootContainer = getRootContainerForNode(state.parent);
  if (!rootContainer) {
    throw new Error(
      '[contract] hot update: embedded mount parent is no longer attached to a host root',
    );
  }
  const release = state.headless
    ? installHeadlessProtocolDispatch(rootContainer.rootId)
    : () => {};
  let tree: TreeMount;
  try {
    tree = mountTree(
      next,
      state.parent,
      rootContainer,
      state.props,
      undefined,
      false,
      state.runtime,
    );
  } catch (error) {
    release();
    throw error;
  }
  // Disposes the previous tree and removes `state` from the registry; the
  // entry is then re-added with the replacement tree on the same object so
  // outstanding MountHandles keep delegating to the current dispose.
  state.dispose();
  state.rootContainer = rootContainer;
  state.component = next;
  state.dispose = (): void => {
    embeddedMounts.delete(state);
    runCleanupSteps('multiple embedded Contract HMR disposers failed', [
      () => tree.dispose(),
      release,
    ]);
  };
  embeddedMounts.add(state);
  notifyContractMountObserver(next);
}

// The hot-update module observes successful mounts to reconcile any pending
// dev-server version sync (registered via setContractMountObserver; kept as
// an injected callback so mount.ts does not import hot-update.ts).
let contractMountObserver: ((component: CompiledComponent) => void) | null = null;

export function setContractMountObserver(
  observer: ((component: CompiledComponent) => void) | null,
): void {
  contractMountObserver = observer;
}

function notifyContractMountObserver(component: CompiledComponent): void {
  contractMountObserver?.(component);
}

/** Unmounts a root and destroys its host root (full reset, used by HMR). */
export function unmount(rootId = 0): void {
  const state = rootStates.get(rootId);
  if (!state) {
    return;
  }
  const destroyHeadless = state.headless;
  state.unsubscribeWindowState?.();
  state.unsubscribeWindowState = null;
  state.dispose?.();
  state.dispose = null;
  rootStates.delete(rootId);
  const restoreHeadlessDestroy = destroyHeadless
    ? installHeadlessProtocolDispatch(rootId)
    : () => {};
  try {
    destroyRoot(rootId);
  } finally {
    restoreHeadlessDestroy();
  }
}

/** Resets every Contract root (frameworks-lab style teardown). */
export function reset(): void {
  for (const rootId of [...rootStates.keys()]) {
    unmount(rootId);
  }
  // Embedded mounts dispose their subtree only — the surrounding adapter
  // owns the root and its lifecycle.
  for (const state of [...embeddedMounts]) {
    state.dispose();
  }
  resetContractListRestorationSeeds();
}
