// @system @ref LLP 0185 S2 — shared owner-safe compiled region switching.

import type { ViewNodeIR } from '../compiler/ir.js';
import { createOwner, getOwner, runWithOwner } from './signals.js';
import type { AnchorFn, HostParent, Mounted, MountEnv } from './view.js';

export type ContractMountViewNodes = (
  nodes: readonly ViewNodeIR[],
  parent: HostParent,
  anchor: AnchorFn | null,
  env: MountEnv,
) => Mounted;

export interface ContractBranchRegion extends Mounted {
  swap(branch: string, nodes: readonly ViewNodeIR[]): void;
}

export function createContractBranchRegion(
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  mountNodes: ContractMountViewNodes,
): ContractBranchRegion {
  let current: { mounted: Mounted; owner: ReturnType<typeof createOwner> } | null = null;
  let lastBranch = '__initial__';
  let disposed = false;

  const swap = (branch: string, nodes: readonly ViewNodeIR[]): void => {
    if (branch === lastBranch || disposed) return;
    const previousBranch = lastBranch;
    lastBranch = branch;
    if (nodes.length === 0) {
      current?.owner.dispose();
      current = null;
      return;
    }
    const owner = createOwner();
    let mounted: Mounted;
    try {
      mounted = runWithOwner(owner, () => mountNodes(nodes, parent, anchor, env));
    } catch (error) {
      owner.dispose();
      lastBranch = previousBranch;
      throw error;
    }
    current?.owner.dispose();
    current = { mounted, owner };
  };

  const dispose = (): void => {
    if (disposed) return;
    disposed = true;
    current?.owner.dispose();
    current = null;
  };
  getOwner()?.register(dispose);
  return {
    swap,
    hostNodes: () => current ? current.mounted.hostNodes() : [],
    dispose,
  };
}
