// @system @ref LLP 0292 / LLP 0373 P1 runtime budgets — the shared viewport
// host input remains a first-class Contract capability, while its production
// implementation is independently tree-shakeable from keyboard/native input.

import { defineCapability } from './capabilities.js';
import { allowStateWrites } from './instance.js';
import { batch, signal, type Signal } from './signals.js';
import {
  readViewportHostSize,
  subscribeViewportHostInput,
  type ContractViewportSize,
} from './viewport-host-input.js';
export {
  publishViewportHostInput,
  readViewportHostSize,
  subscribeViewportHostInput,
  type ContractViewportSize,
} from './viewport-host-input.js';

// ---------------------------------------------------------------------------
// Shared viewport host input (ENG-22563).
//
// ONE window resize listener feeds every consumer: the `viewport` capability
// below and the facet theme store's size-class width (facet-contract
// `installHostInputs`) both subscribe here instead of maintaining parallel
// listeners. The window listener installs lazily with the first subscriber
// and uninstalls with the last. `document` is part of the gate because
// native defines a window shim.
// ---------------------------------------------------------------------------

function hasViewportDom(): boolean {
  return typeof document !== 'undefined' && typeof window !== 'undefined';
}

// ---------------------------------------------------------------------------
// viewport — reactive viewport dimensions.
//
//   use viewport from "@exact/contract/runtime"
//
// Width/height are signal-backed, so bindings re-evaluate on resize. During
// hydration the first render replays the captured viewport and flips back to
// the live host input only after adoption releases deferred work.
// ---------------------------------------------------------------------------

export interface ContractViewport {
  readonly width: number;
  readonly height: number;
}

export const viewport = /* @__PURE__ */ defineCapability<ContractViewport>({
  id: 'contract.viewport',
  effects: ['host:viewport'],
  instantiate({ owner, hydration, onHydrationRelease }) {
    const hasDom = hasViewportDom();
    const liveInitial = readViewportHostSize();
    if (!hasDom && (liveInitial.width === 0 || liveInitial.height === 0)) {
      console.warn(
        '[contract] viewport capability has no DOM backing on this host; width/height start at 0 until a native host transaction arrives — bind a fallback for older hosts',
      );
    }
    const captured = hydration?.capabilities?.viewport;
    const initial = captured ?? liveInitial;
    const width: Signal<number> = signal(initial.width);
    const height: Signal<number> = signal(initial.height);
    const applySize = (size: ContractViewportSize): void => {
      batch(() => {
        allowStateWrites(() => {
          width.set(size.width);
          height.set(size.height);
        });
      });
    };
    let disposed = false;
    let disposeViewport: (() => void) | null = null;
    const subscribeLiveViewport = (): void => {
      if (disposed || disposeViewport) return;
      disposeViewport = subscribeViewportHostInput(applySize);
    };
    if (hydration?.deferActivation && onHydrationRelease) {
      onHydrationRelease(subscribeLiveViewport);
    } else {
      subscribeLiveViewport();
    }
    owner.register(() => {
      disposed = true;
      disposeViewport?.();
      disposeViewport = null;
    });
    if (captured) {
      onHydrationRelease?.(() => applySize(readViewportHostSize()));
    }
    return {
      get width() {
        return width.get();
      },
      get height() {
        return height.get();
      },
    };
  },
});
