export interface DirectDomHydrationManifestLike {
  version?: number;
  rootId?: number;
  nodes?: Array<{
    nodeId?: string;
    domPath?: number[];
    kind?: string;
    tag?: string;
    textGuard?: string;
  }>;
  handlers?: Array<{
    nodeId?: string;
    event?: string;
    actionId?: string;
  }>;
}

export interface DirectDomHydrationResult {
  rootId: number;
  adoptedNodes: number;
  recreatedNodes: number;
  mismatches: string[];
}

export interface DirectContractWebHostOptions {
  container?: HTMLElement;
  correlationHandles?: boolean;
  hydrate?: {
    rootId: number;
    manifest: DirectDomHydrationManifestLike;
    onResult?: (result: DirectDomHydrationResult) => void;
  };
}

export interface DirectContractWebHostHandle {
  dispose(): void;
}

type HostChild = ElementNode | TextNode;
type DirectHydrationHandlerOwner = ElementNode & {
  __exactHydrationHandlers?: readonly {
    readonly event: string;
    readonly actionId: string;
  }[];
};

const DIRECT_EVENT_NODE = Symbol('exact.direct-event-node');
const DIRECT_COMPOSITION_ACTIVE = Symbol('exact.direct-composition-active');
const DIRECT_COMPOSITION_COMMIT = Symbol('exact.direct-composition-commit');

const directElementEvents = [
  'click',
  'focus',
  'blur',
  'keydown',
  'pointerdown',
  'pointerup',
  'pointermove',
  'pointercancel',
  'scrollend',
] as const;

type DirectEventElement = HTMLElement & {
  [DIRECT_EVENT_NODE]?: ElementNode;
  [DIRECT_COMPOSITION_ACTIVE]?: boolean;
  [DIRECT_COMPOSITION_COMMIT]?: string;
};

function directActiveElement(scope: HTMLElement): HTMLElement | null {
  const active = scope.ownerDocument.activeElement;
  return active && typeof (active as HTMLElement).focus === 'function'
    ? active as HTMLElement
    : null;
}

function directFocusTarget(scope: HTMLElement): HTMLElement {
  return domFocusableDescendants(scope)[0] ?? scope;
}

function trapDirectTabKey(scope: HTMLElement, event: KeyboardEvent): void {
  const focusables = domFocusableDescendants(scope);
  if (focusables.length === 0) {
    event.preventDefault();
    scope.focus();
    return;
  }
  const active = directActiveElement(scope);
  const index = active ? focusables.indexOf(active) : -1;
  if (event.shiftKey) {
    if (index <= 0) {
      event.preventDefault();
      focusables[focusables.length - 1]?.focus();
    }
  } else if (index === -1 || index === focusables.length - 1) {
    event.preventDefault();
    focusables[0]?.focus();
  }
}

function currentHandler(node: ElementNode, name: string): ((value: unknown) => void) | undefined {
  const candidate = node.originalProps?.[name];
  return typeof candidate === 'function' ? candidate as (value: unknown) => void : undefined;
}

function publishDirectTextChange(
  element: HTMLInputElement | HTMLTextAreaElement,
  node: ElementNode,
): void {
  currentHandler(node, 'onChangeText')?.(element.value);
  currentHandler(node, 'onChange')?.({
    value: element.value,
    nativeEvent: { text: element.value },
  });
  const controlled = node.originalProps?.value;
  if (controlled !== undefined && element.value !== String(controlled ?? '')) {
    element.value = String(controlled ?? '');
  }
}

function dispatchDirectEvent(this: DirectEventElement, event: Event): void {
  const node = this[DIRECT_EVENT_NODE];
  if (!node) return;
  switch (event.type) {
    case 'click':
      if ((node.originalProps?.disabled ?? false) !== true) {
        currentHandler(node, 'onPress')?.({ type: 'press', nativeEvent: event });
      }
      return;
    case 'focus':
      currentHandler(node, 'onFocus')?.(createDomFocusEventPayload(event as FocusEvent));
      return;
    case 'blur':
      currentHandler(node, 'onBlur')?.(createDomFocusEventPayload(event as FocusEvent));
      return;
    case 'keydown':
      // @ref LLP 0202#5-event--focus-model / LLP 0202#7-overlays-portals-layering —
      // the lightweight production host must preserve the same browser focus
      // scope semantics as the full host while remaining outside the bundle.
      if (node.originalProps?.focusScope === 'trapped' && (event as KeyboardEvent).key === 'Tab') {
        trapDirectTabKey(this, event as KeyboardEvent);
      }
      currentHandler(node, 'onKeyDown')?.(createDomKeyEventPayload(event as KeyboardEvent));
      return;
    case 'pointerdown':
      currentHandler(node, 'onPressIn')?.({ type: 'pressin', nativeEvent: event });
      currentHandler(node, 'onPointerDown')?.({ type: 'pointerdown', nativeEvent: event });
      return;
    case 'pointerup':
      currentHandler(node, 'onPressOut')?.({ type: 'pressout', nativeEvent: event });
      currentHandler(node, 'onPointerUp')?.({ type: 'pointerup', nativeEvent: event });
      return;
    case 'pointermove':
      currentHandler(node, 'onPointerMove')?.({ type: 'pointermove', nativeEvent: event });
      return;
    case 'pointercancel':
      currentHandler(node, 'onPressOut')?.({ type: 'pressout', nativeEvent: event });
      currentHandler(node, 'onPointerCancel')?.({ type: 'pointercancel', nativeEvent: event });
      return;
    case 'scrollend':
      currentHandler(node, 'onScrollEnd')?.({ type: 'scrollend', nativeEvent: event });
      return;
    case 'compositionstart':
      // @ref LLP 0202#5-event--focus-model / LLP 0202#6-forms-renders-llp-0197-f2b —
      // marked text belongs to the browser IME until compositionend. In
      // particular, controlled-value snapback must not erase that native
      // candidate buffer or publish it as Contract form state.
      this[DIRECT_COMPOSITION_ACTIVE] = true;
      this[DIRECT_COMPOSITION_COMMIT] = undefined;
      return;
    case 'compositionend': {
      const element = this as HTMLInputElement | HTMLTextAreaElement;
      this[DIRECT_COMPOSITION_ACTIVE] = false;
      this[DIRECT_COMPOSITION_COMMIT] = element.value;
      publishDirectTextChange(element, node);
      const committed = element.value;
      queueMicrotask(() => {
        if (this[DIRECT_COMPOSITION_COMMIT] === committed) {
          this[DIRECT_COMPOSITION_COMMIT] = undefined;
        }
      });
      return;
    }
    case 'input': {
      const element = this as HTMLInputElement | HTMLTextAreaElement;
      if (element instanceof HTMLInputElement && element.type === 'checkbox') return;
      if (
        this[DIRECT_COMPOSITION_ACTIVE] === true ||
        (event as InputEvent).isComposing === true
      ) {
        return;
      }
      if (this[DIRECT_COMPOSITION_COMMIT] === element.value) {
        this[DIRECT_COMPOSITION_COMMIT] = undefined;
        return;
      }
      this[DIRECT_COMPOSITION_COMMIT] = undefined;
      publishDirectTextChange(element, node);
      return;
    }
    case 'change': {
      const element = this as HTMLInputElement;
      if (element.type !== 'checkbox') return;
      currentHandler(node, 'onChange')?.({
        value: element.checked,
        nativeEvent: { value: element.checked },
      });
      currentHandler(node, 'onValueChange')?.(element.checked);
      const controlled = node.originalProps?.value ?? node.originalProps?.checked;
      if (controlled !== undefined) element.checked = controlled === true;
    }
  }
}

/** Share dispatch functions across host elements while keeping the direct
 * listener/currentTarget semantics of the admitted browser host.
 *
 * @ref LLP 0202#2.1 — the admitted direct host owns browser event attachment;
 * native listeners read the current authored handlers from their host node.
 */
function installEvents(element: HTMLElement, node: ElementNode): void {
  const target = element as DirectEventElement;
  target[DIRECT_EVENT_NODE] = node;
  for (const eventName of directElementEvents) {
    element.addEventListener(eventName, dispatchDirectEvent);
  }
  if (element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement) {
    element.addEventListener('compositionstart', dispatchDirectEvent);
    element.addEventListener('compositionend', dispatchDirectEvent);
    element.addEventListener('input', dispatchDirectEvent);
    element.addEventListener('change', dispatchDirectEvent);
  }
  if (node.originalTag === 'lottie') {
    // LLP 0394 §5.1: the dotlottie backend re-dispatches player events as
    // CustomEvents on the host element; route them to the current handlers.
    const lottieEvents: ReadonlyArray<readonly [string, string]> = [
      ['exact-lottie-load', 'onLoad'],
      ['exact-lottie-error', 'onError'],
      ['exact-lottie-complete', 'onComplete'],
      ['exact-lottie-looped', 'onLooped'],
    ];
    for (const [domEvent, handlerName] of lottieEvents) {
      element.addEventListener(domEvent, (event) => {
        const liveNode = target[DIRECT_EVENT_NODE] ?? node;
        currentHandler(liveNode, handlerName)?.((event as CustomEvent).detail ?? {});
      });
    }
  }
  if (node.originalTag === 'rive') {
    const riveEvents: ReadonlyArray<readonly [string, string]> = [
      ['exact-rive-load', 'onLoad'],
      ['exact-rive-error', 'onError'],
      ['exact-rive-statechange', 'onStateChange'],
      ['exact-rive-datachange', 'onDataChange'],
      ['exact-rive-riveevent', 'onRiveEvent'],
    ];
    for (const [domEvent, handlerName] of riveEvents) {
      element.addEventListener(domEvent, (event) => {
        const liveNode = target[DIRECT_EVENT_NODE] ?? node;
        currentHandler(liveNode, handlerName)?.((event as CustomEvent).detail ?? {});
      });
    }
  }
}

function applyDescription(element: HTMLElement, description: DomElementDescription): void {
  const attributes = materializeDomElementAttributes(description);
  const desiredAttrs = new Set(attributes.map(([name]) => name.toLowerCase()));
  // `element.attributes` materializes one retained browser `Attr` wrapper per
  // attribute. The direct host only needs names for stale-attribute removal.
  for (const name of element.getAttributeNames()) {
    if (name === 'data-exact-contract-host-root') continue;
    if (!desiredAttrs.has(name.toLowerCase())) element.removeAttribute(name);
  }
  for (const [name, value] of attributes) {
    if (value === true) element.setAttribute(name, '');
    else element.setAttribute(name, value);
  }

  let cssText = '';
  for (const [name, value] of Object.entries(description.styles)) {
    const cssName = name.startsWith('-')
      ? name
      : name.replace(/[A-Z]/g, (character) => `-${character.toLowerCase()}`);
    cssText += `${cssText ? ';' : ''}${cssName}:${value}`;
  }
  if (cssText) element.setAttribute('style', cssText);
  else element.removeAttribute('style');

  if ('disabled' in element && description.properties.disabled !== undefined) {
    (element as HTMLButtonElement).disabled = description.properties.disabled;
  }
  if (element instanceof HTMLInputElement) {
    if (description.properties.checked !== undefined) element.checked = description.properties.checked;
    if (description.properties.readOnly !== undefined) element.readOnly = description.properties.readOnly;
  }
  if ((element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement) &&
      description.properties.value !== undefined &&
      (element as DirectEventElement)[DIRECT_COMPOSITION_ACTIVE] !== true &&
      element.value !== description.properties.value) {
    element.value = description.properties.value;
  }
}

type HydrationCommitRow = [
  element: HTMLElement,
  left: number,
  top: number,
  value?: string,
  checked?: boolean,
];

type HydrationCommitFocus = [
  element: HTMLElement,
  selectionStart: number | null,
  selectionEnd: number | null,
  selectionDirection: 'forward' | 'backward' | 'none' | null,
];

type HydrationCommitSnapshot = [
  rows: HydrationCommitRow[],
  focus: HydrationCommitFocus | null,
  viewport: [view: Window, x: number, y: number] | null,
];

function captureHydrationCommitSnapshot(
  container: HTMLElement,
): HydrationCommitSnapshot {
  const document = container.ownerDocument;
  const marked = [
    container,
    ...container.querySelectorAll<HTMLElement>('[data-exact-hydration-id]'),
  ];
  const rows = marked.map((element): HydrationCommitRow => {
    const row: HydrationCommitRow = [
      element,
      element.scrollLeft,
      element.scrollTop,
    ];
    if (
      element.localName === 'input' ||
      element.localName === 'textarea' ||
      element.localName === 'select'
    ) {
      row[3] = (
        element as HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
      ).value;
      if (element.localName === 'input') {
        row[4] = (element as HTMLInputElement).checked;
      }
    }
    return row;
  });
  const activeElement = document.activeElement;
  let focus: HydrationCommitFocus | null = null;
  if (activeElement instanceof HTMLElement && container.contains(activeElement)) {
    let selectionStart: number | null = null;
    let selectionEnd: number | null = null;
    let selectionDirection: 'forward' | 'backward' | 'none' | null = null;
    if (
      activeElement.localName === 'input' ||
      activeElement.localName === 'textarea'
    ) {
      const control = activeElement as HTMLInputElement | HTMLTextAreaElement;
      try {
        selectionStart = control.selectionStart;
        selectionEnd = control.selectionEnd;
        selectionDirection = control.selectionDirection;
      } catch {
        // Some input types do not expose text selection.
      }
    }
    focus = [activeElement, selectionStart, selectionEnd, selectionDirection];
  }
  const view = document.defaultView;
  return [
    rows,
    focus,
    view
      ? [view, view.scrollX, view.scrollY]
      : null,
  ];
}

function reapplyHydrationCommitSnapshot(
  container: HTMLElement,
  snapshot: HydrationCommitSnapshot,
): void {
  const [rows, focus, viewport] = snapshot;
  const survives = (element: HTMLElement): boolean =>
    element.isConnected && container.contains(element);
  for (const [element, , , value, checked] of rows) {
    if (!survives(element) || value === undefined) continue;
    (
      element as HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
    ).value = value;
    if (checked !== undefined) {
      (element as HTMLInputElement).checked = checked;
    }
  }
  if (focus && survives(focus[0])) {
    const [element, selectionStart, selectionEnd, selectionDirection] = focus;
    element.focus({ preventScroll: true });
    if (
      selectionStart !== null &&
      selectionEnd !== null &&
      (
        element.localName === 'input' ||
        element.localName === 'textarea'
      )
    ) {
      try {
        (element as HTMLInputElement | HTMLTextAreaElement).setSelectionRange(
          selectionStart,
          selectionEnd,
          selectionDirection ?? undefined,
        );
      } catch {
        // The target survived, but this input type does not admit selection.
      }
    }
  }
  for (const [element, left, top] of rows) {
    if (!survives(element)) continue;
    element.scrollLeft = left;
    element.scrollTop = top;
  }
  if (
    viewport &&
    (
      viewport[0].scrollX !== viewport[1] ||
      viewport[0].scrollY !== viewport[2]
    )
  ) {
    try {
      viewport[0].scrollTo(viewport[1], viewport[2]);
    } catch {
      // Some embedded documents expose scroll coordinates without scrolling.
    }
  }
}

export function installDirectContractWebHost(
  options: DirectContractWebHostOptions = {},
): DirectContractWebHostHandle {
  if (globalThis.__exactContractWebHost) {
    throw new Error('[ExactRenderer] a Contract web host is already installed');
  }
  const base = options.container ?? document.getElementById('exact-root') ?? document.body;
  let hydration = options.hydrate;
  const domByHost = new WeakMap<HostChild, Node>();
  const hydrationCandidates = new WeakMap<HostChild, Node>();
  const adoptedHosts = new WeakSet<HostChild>();
  const appliedElements = new WeakMap<ElementNode, {
    props: unknown;
    parent: unknown;
    imageColorScheme: ReturnType<typeof getRuntimeImageColorScheme>;
  }>();
  const rootContainers = new Map<number, HTMLElement>();
  const focusScopes = new Map<HTMLElement, {
    previous: HTMLElement | null;
    restore: boolean;
  }>();
  let disposed = false;
  let hydrationPending = hydration !== undefined;
  let hydrationReported = false;
  let hydrationReplayNeeded = false;
  let adoptedNodes = 0;
  let recreatedNodes = 0;
  const mismatches: string[] = [];

  const rootContainerFor = (rootId: number): HTMLElement => {
    const known = rootContainers.get(rootId);
    if (known) return known;
    const existing = hydration?.rootId === rootId
      ? base.querySelector<HTMLElement>(`[data-exact-contract-host-root="${rootId}"]`)
      : null;
    const root = existing ?? document.createElement('div');
    if (!existing) {
      root.setAttribute('data-exact-contract-host-root', String(rootId));
      Object.assign(root.style, {
        display: 'flex', flexDirection: 'column', alignItems: 'stretch',
        width: '100%', height: '100%', minHeight: '0',
      });
      base.appendChild(root);
    }
    rootContainers.set(rootId, root);
    return root;
  };

  const expectedTag = (node: ElementNode): string => describeDomElement(node, {
    imageColorScheme: getRuntimeImageColorScheme(),
  }).tag;

  const hydrationIdFor = (host: HostChild): string | undefined => {
    if (host.kind === NodeKind.Text) {
      return (host as TextNode & { __exactHydrationId?: string }).__exactHydrationId;
    }
    const value = host.originalProps?.['data-exact-hydration-id'];
    return typeof value === 'string' && value.length > 0 ? value : undefined;
  };

  const preflightHydration = (
    root: RootNode,
    container: HTMLElement,
  ): string[] => {
    // @ref LLP 0210 §4.9 — decide total candidate ↔ manifest ↔ DOM
    // correspondence before installing one handler or mutating one server
    // node. A red transcript sends the complete root through CSR below.
    const anchors = hydration?.manifest.nodes ?? [];
    const anchorByPath = new Map<string, (typeof anchors)[number]>();
    const anchorIds = new Set<string>();
    const handlersByNode = new Map<
      string,
      Map<string, { readonly event: string; readonly actionId: string }>
    >();
    const errors: string[] = [];
    for (const anchor of anchors) {
      const id = anchor.nodeId;
      const path = anchor.domPath?.join('.');
      if (
        !id ||
        path === undefined ||
        anchorIds.has(id) ||
        anchorByPath.has(path)
      ) {
        errors.push(`${id ?? 'manifest'}: invalid or duplicate anchor`);
        continue;
      }
      anchorIds.add(id);
      anchorByPath.set(path, anchor);
    }
    for (const handler of hydration?.manifest.handlers ?? []) {
      const nodeId = handler.nodeId;
      const event = handler.event;
      const actionId = handler.actionId;
      if (
        !nodeId ||
        !event ||
        !actionId ||
        !anchorIds.has(nodeId)
      ) {
        errors.push(`${nodeId ?? 'manifest'}: invalid hydration handler`);
        continue;
      }
      let byIdentity = handlersByNode.get(nodeId);
      if (!byIdentity) {
        byIdentity = new Map();
        handlersByNode.set(nodeId, byIdentity);
      }
      if (byIdentity.has(event)) {
        errors.push(`${nodeId}: duplicate hydration handler`);
      } else {
        byIdentity.set(event, { event, actionId });
      }
    }
    let candidateCount = 0;
    const visit = (
      hostChildren: readonly HostChild[],
      domParent: ParentNode,
      parentPath: string,
    ): void => {
      if (domParent.childNodes.length !== hostChildren.length) {
        errors.push(`${parentPath || 'root'}: child count mismatch`);
      }
      hostChildren.forEach((host, index) => {
        candidateCount += 1;
        const pathLabel = parentPath ? `${parentPath}.${index}` : String(index);
        const hydrationId = hydrationIdFor(host);
        if (!hydrationId) {
          errors.push(`${pathLabel}: missing candidate identity`);
          return;
        }
        const anchor = anchorByPath.get(pathLabel);
        if (!anchor) {
          errors.push(`${hydrationId}: missing anchor`);
          return;
        }
        if (anchor.nodeId !== hydrationId) {
          errors.push(`${hydrationId}: identity mismatch`);
          return;
        }
        const candidate = domParent.childNodes.item(index);
        if (!candidate) {
          errors.push(`${hydrationId}: missing DOM node`);
          return;
        }
        if (host.kind === NodeKind.Text) {
          if ((handlersByNode.get(hydrationId)?.size ?? 0) > 0) {
            errors.push(`${hydrationId}: text node owns hydration handlers`);
            return;
          }
          if (candidate.nodeType !== 3) {
            errors.push(`${hydrationId}: expected text node`);
          } else if (
            anchor.textGuard !== undefined &&
            host.text !== anchor.textGuard
          ) {
            errors.push(`${hydrationId}: candidate textGuard mismatch`);
          } else if (
            anchor.textGuard !== undefined &&
            candidate.nodeValue !== anchor.textGuard
          ) {
            errors.push(`${hydrationId}: textGuard mismatch`);
          } else {
            hydrationCandidates.set(host, candidate);
          }
          return;
        }
        if (!(candidate instanceof HTMLElement)) {
          errors.push(`${hydrationId}: expected element node`);
          return;
        }
        const tag = expectedTag(host);
        if (candidate.localName !== tag) {
          errors.push(`${hydrationId}: tag mismatch`);
          return;
        }
        if (anchor.tag && anchor.tag !== tag) {
          errors.push(`${hydrationId}: manifest tag mismatch`);
          return;
        }
        if (candidate.getAttribute('data-exact-hydration-id') !== hydrationId) {
          errors.push(`${hydrationId}: marker mismatch`);
          return;
        }
        const expectedHandlers = handlersByNode.get(hydrationId) ?? new Map();
        const actualHandlers = new Map<string, {
          readonly event: string;
          readonly actionId: string;
        }>();
        for (
          const handler of (
            host as DirectHydrationHandlerOwner
          ).__exactHydrationHandlers ?? []
        ) {
          if (actualHandlers.has(handler.event)) {
            errors.push(`${hydrationId}: duplicate candidate hydration handler`);
          } else {
            actualHandlers.set(handler.event, handler);
          }
        }
        if (
          actualHandlers.size !== expectedHandlers.size ||
          [...actualHandlers].some(
            ([event, handler]) =>
              expectedHandlers.get(event)?.actionId !== handler.actionId,
          )
        ) {
          errors.push(`${hydrationId}: handler correspondence mismatch`);
          return;
        }
        hydrationCandidates.set(host, candidate);
        visit(host.children, candidate, pathLabel);
      });
    };
    visit(root.children, container, '');
    if (candidateCount !== anchors.length) {
      errors.push('candidate/manifest node count mismatch');
    }
    return errors;
  };

  const adoptPreflightCandidate = (host: HostChild): Node | undefined => {
    if (!hydrationPending) return undefined;
    const candidate = hydrationCandidates.get(host);
    if (!candidate) return undefined;
    domByHost.set(host, candidate);
    adoptedHosts.add(host);
    if (host.kind === NodeKind.Element) installEvents(candidate as HTMLElement, host);
    adoptedNodes += 1;
    return candidate;
  };

  const domFor = (host: HostChild): Node => {
    const known = domByHost.get(host);
    if (known) return known;
    const adopted = adoptPreflightCandidate(host);
    if (adopted) return adopted;
    recreatedNodes += 1;
    const created = host.kind === NodeKind.Text
      ? document.createTextNode(host.text)
      : document.createElement(expectedTag(host));
    domByHost.set(host, created);
    if (host.kind === NodeKind.Element) installEvents(created as HTMLElement, host);
    return created;
  };

  // RFC 0101 SG2: an element culled by reconciliation may carry (or contain)
  // an attached canvas2d backend whose scene subscription, ResizeObserver,
  // and DPR matchMedia listener otherwise persist until a post-removal
  // commit reaches the paint path — a commit that never comes for an empty
  // scene, or for a scene disposed in the same owner teardown before its
  // scheduled commit runs. Disposal is deferred to the end of the sync pass
  // because a cross-parent move removes the element from its old parent
  // before reinserting it; only elements still disconnected after the full
  // pass are true removals.
  const pendingGraphicsRemovals: Node[] = [];

  // LLP 0364: the color-matrix `<defs>` container is document-scoped, so its
  // reference sweep only runs on commits that actually changed the filtered
  // element set.
  let colorMatrixDefsDirty = false;

  const sweepColorMatrixDefsIfDirty = (): void => {
    if (!colorMatrixDefsDirty) return;
    colorMatrixDefsDirty = false;
    sweepImageColorMatrixFilterDefs(document);
  };

  const disposeGraphicsBackendsWithin = (removed: Node): void => {
    if (removed.nodeType !== 1) return;
    const el = removed as HTMLElement;
    if (el.getAttribute('data-exact-graphics-backend') === 'canvas2d') {
      disposeGraphicsCanvas2dBackend(el);
    }
    if (el.hasAttribute('data-exact-video-player-id')) {
      disposeVideoWebView(el);
    }
    if (el.firstElementChild) {
      for (const surfaceHost of el.querySelectorAll<HTMLElement>(
        '[data-exact-graphics-backend="canvas2d"]',
      )) {
        disposeGraphicsCanvas2dBackend(surfaceHost);
      }
      for (const videoHost of el.querySelectorAll<HTMLElement>(
        '[data-exact-video-player-id]',
      )) {
        disposeVideoWebView(videoHost);
      }
    }
    // LLP 0394: lottie backends ride the same deferred-removal drain.
    disposeLottieBackendsWithin(el);
    disposeRiveBackendsWithin(el);
  };

  const drainPendingGraphicsRemovals = (): void => {
    for (const removed of pendingGraphicsRemovals.splice(0)) {
      // Still connected means the node merely moved this pass; dispose only
      // true removals (disposeGraphicsCanvas2dBackend is an idempotent no-op
      // for elements without a backend).
      if (!removed.isConnected) disposeGraphicsBackendsWithin(removed);
    }
  };

  const reconcileChildren = (
    hostChildren: readonly HostChild[],
    parent: HTMLElement,
    imageColorScheme: ReturnType<typeof getRuntimeImageColorScheme>,
  ): void => {
    const desired = hostChildren.map((host) => {
      const dom = domFor(host);
      if (host.kind === NodeKind.Text) {
        if (!(hydrationPending && adoptedHosts.has(host)) && dom.nodeValue !== host.text) {
          dom.nodeValue = host.text;
        }
      } else {
        const applied = appliedElements.get(host);
        const presentationChanged = !applied ||
          applied.props !== host.originalProps ||
          applied.parent !== host.parent ||
          applied.imageColorScheme !== imageColorScheme;
        // LLP 0210 fine-grained adoption: server bytes stay authoritative for
        // the adoption turn. Identity and event handlers attach now; ordinary
        // reactive commits may update this node after the host reports the
        // completed first paint.
        if (!(hydrationPending && adoptedHosts.has(host)) && presentationChanged) {
          const description = describeDomElement(host, { imageColorScheme });
          // LLP 0364: read before applyDescription drops stale attributes — a
          // filter cleared with the element still alive (matrix -> undefined)
          // must schedule the def sweep too, or the orphan def persists.
          const hadColorMatrixFilter =
            (dom as HTMLElement).hasAttribute(IMAGE_COLOR_MATRIX_ATTR);
          applyDescription(dom as HTMLElement, description);
          // LLP 0364: the `filter: url(#…)` this just wrote needs its
          // `<feColorMatrix>` in the document to resolve.
          if (description.colorMatrixFilter) {
            ensureImageColorMatrixFilterDef(document, description.colorMatrixFilter);
            colorMatrixDefsDirty = true;
          } else if (hadColorMatrixFilter) {
            colorMatrixDefsDirty = true;
          }
          appliedElements.set(host, {
            props: host.originalProps,
            parent: host.parent,
            imageColorScheme,
          });
          // RFC 0101 SG2: graphics surface hosts adopt the canvas2d backend.
          if ((dom as HTMLElement).getAttribute('data-exact-graphics-backend') === 'canvas2d') {
            ensureGraphicsCanvas2dBackend(dom as HTMLElement);
          }
          // LLP 0394: lottie hosts adopt the dotlottie-web backend.
          if ((dom as HTMLElement).getAttribute('data-exact-lottie-backend') === 'dotlottie') {
            ensureLottieDomBackend(dom as HTMLElement);
          }
          if ((dom as HTMLElement).getAttribute('data-exact-rive-backend') === 'webgl2') {
            ensureRiveDomBackend(dom as HTMLElement);
          }
          // LLP 0393: Contract video hosts adopt the engine-owned element.
          if ((dom as HTMLElement).hasAttribute('data-exact-video-player-id')) {
            ensureVideoWebView(dom as HTMLElement);
          }
        }
        reconcileChildren(host.children, dom as HTMLElement, imageColorScheme);
        // First-commit restoration must observe the mounted child extent
        // before its monotonic command watermark is consumed.
        applyDomScrollCommandIfNeeded(
          dom as HTMLElement,
          host.originalProps?.scrollCommand,
        );
      }
      return dom;
    });
    const desiredSet = new Set(desired);
    for (const existing of Array.from(parent.childNodes)) {
      if (desiredSet.has(existing)) continue;
      // RFC 0101 SG2: the backend-owned canvas is not a host child — the
      // scene lane owns it, so host child reconciliation must not cull it.
      if (
        (existing as HTMLElement).getAttribute?.('data-exact-graphics-canvas') === 'true'
      ) {
        continue;
      }
      // LLP 0394: same cull exception for the lottie backend's canvas child.
      if (
        (existing as HTMLElement).getAttribute?.('data-exact-lottie-canvas') === 'true'
      ) {
        continue;
      }
      if (
        (existing as HTMLElement).getAttribute?.('data-exact-rive-canvas') === 'true'
      ) {
        continue;
      }
      parent.removeChild(existing);
      if (existing.nodeType === 1) {
        pendingGraphicsRemovals.push(existing);
        colorMatrixDefsDirty = true;
      }
    }
    desired.forEach((node, index) => {
      const current = parent.childNodes[index] ?? null;
      if (current !== node) parent.insertBefore(node, current);
    });
  };

  const restoreFocusScope = (
    scope: HTMLElement,
    state: { previous: HTMLElement | null; restore: boolean },
  ): void => {
    focusScopes.delete(scope);
    if (state.restore && state.previous?.isConnected) state.previous.focus();
  };

  const syncFocusScopes = (container: HTMLElement): void => {
    const next = new Set(
      container.querySelectorAll<HTMLElement>('[data-exact-focus-scope="trapped"]'),
    );
    for (const [scope, state] of focusScopes) {
      if (!scope.isConnected || !next.has(scope)) restoreFocusScope(scope, state);
    }
    for (const scope of next) {
      if (focusScopes.has(scope)) continue;
      const previous = directActiveElement(scope);
      focusScopes.set(scope, {
        previous: previous && !scope.contains(previous) ? previous : null,
        restore: scope.getAttribute('data-exact-focus-restore') === 'true',
      });
      directFocusTarget(scope).focus();
    }
  };

  const removeFocusScopesWithin = (container: HTMLElement): void => {
    for (const [scope, state] of focusScopes) {
      if (container === scope || container.contains(scope)) restoreFocusScope(scope, state);
    }
  };

  const registry: ContractWebHostRegistry = {
    sync(root: RootNode): void {
      if (disposed) return;
      // @ref LLP 0210#4 — the adoption callback may release buffered live
      // work in a microtask while the first-paint fence is still raised.
      // Remember that post-report commit so the current host model is replayed
      // once server-byte custody ends.
      if (hydrationPending && hydrationReported && hydration?.rootId === root.rootId) {
        hydrationReplayNeeded = true;
      }
      const container = rootContainerFor(root.rootId);
      let liveInteraction: HydrationCommitSnapshot | null = null;
      if (!hydrationReported && hydrationPending && hydration?.rootId === root.rootId) {
        const preflightErrors = preflightHydration(root, container);
        if (preflightErrors.length > 0) {
          mismatches.push(...preflightErrors);
          hydrationPending = false;
          hydrationReported = true;
          const onResult = hydration.onResult;
          hydration = undefined;
          // The preflight has not installed handlers or mutated server bytes.
          // Clear the complete root once, then perform an ordinary CSR commit
          // from the already-prepared host tree.
          container.replaceChildren();
          reconcileChildren(root.children, container, getRuntimeImageColorScheme());
          syncFocusScopes(container);
          onResult?.({
            rootId: root.rootId,
            adoptedNodes: 0,
            recreatedNodes,
            mismatches,
          });
          return;
        }
        // @ref LLP 0386 §3.8.1 — preserve input, focus/selection, and scroll
        // that arrived on the live server DOM after precheck and before the
        // successful candidate owns it. Reapply only to surviving nodes.
        liveInteraction = captureHydrationCommitSnapshot(container);
      }
      reconcileChildren(root.children, container, getRuntimeImageColorScheme());
      drainPendingGraphicsRemovals();
      sweepColorMatrixDefsIfDirty();
      syncFocusScopes(container);
      if (liveInteraction) {
        reapplyHydrationCommitSnapshot(container, liveInteraction);
      }
      if (!hydrationReported && hydrationPending && hydration?.rootId === root.rootId) {
        hydrationReported = true;
        const onResult = hydration.onResult;
        onResult?.({ rootId: root.rootId, adoptedNodes, recreatedNodes, mismatches });
        // Promise continuations released by onResult observe the untouched
        // server first paint. Later reactive work resumes ordinary DOM writes.
        setTimeout(() => {
          hydrationPending = false;
          // @ref LLP 0210#4 — the manifest governs one adoption turn. Once
          // that turn is reported, keeping its node/path ledger alive in the
          // ordinary client host adds no verification power.
          hydration = undefined;
          if (hydrationReplayNeeded) {
            hydrationReplayNeeded = false;
            registry.sync(root);
          }
          // RFC 0101 SG2: adopted graphics hosts skipped applyDescription for
          // the whole custody turn, and scene-lane commits never trigger a
          // host sync — attach the backend deterministically now instead of
          // waiting for a presentation change that may never come.
          for (const surfaceHost of container.querySelectorAll<HTMLElement>(
            '[data-exact-graphics-backend="canvas2d"]',
          )) {
            ensureGraphicsCanvas2dBackend(surfaceHost);
          }
          // LLP 0394: same deterministic post-hydration attach for lottie.
          for (const lottieHost of container.querySelectorAll<HTMLElement>(
            '[data-exact-lottie-backend="dotlottie"]',
          )) {
            ensureLottieDomBackend(lottieHost);
          }
          for (const riveHost of container.querySelectorAll<HTMLElement>(
            '[data-exact-rive-backend="webgl2"]',
          )) {
            ensureRiveDomBackend(riveHost);
          }
          for (const videoHost of container.querySelectorAll<HTMLElement>(
            '[data-exact-video-player-id]',
          )) {
            ensureVideoWebView(videoHost);
          }
          // LLP 0364: prerendered HTML deliberately omits the filter style, and
          // adopted hosts skipped applyDescription for the custody turn — apply
          // the deferred filters here rather than waiting on a commit that may
          // never come.
          attachDeferredImageColorMatrixFilters(container);
        }, 0);
      }
    },
    remove(rootId: number): void {
      const root = rootContainers.get(rootId);
      if (root) {
        removeFocusScopesWithin(root);
        root.remove();
        disposeGraphicsBackendsWithin(root);
      }
      rootContainers.delete(rootId);
      colorMatrixDefsDirty = true;
      sweepColorMatrixDefsIfDirty();
    },
    applyStyle(node: ElementNode, property: string, value: unknown): boolean {
      const dom = domByHost.get(node);
      if (!(dom instanceof HTMLElement)) return false;
      if (
        property === 'glassEffect' ||
        property === 'backdropBlur' ||
        property === 'backdropMaterial'
      ) {
        const nodeStyle = node.style as Record<string, unknown>;
        const glass = lowerLiquidGlassWebStyle(nodeStyle);
        if (glass) {
          // Liquid Glass wins over backdropMaterial/backdropBlur (LLP 0412
          // §1) and replaces the authored fill, matching the native hosts,
          // which clear the node's background so glass samples the backdrop.
          dom.style.backdropFilter = glass.backdropFilter;
          dom.style.setProperty('-webkit-backdrop-filter', glass.WebkitBackdropFilter);
          dom.style.backgroundColor = glass.backgroundColor;
          return true;
        }
        const backdrop = lowerBackdropMaterialWebStyle(nodeStyle);
        dom.style.backdropFilter = backdrop?.backdropFilter ?? '';
        dom.style.setProperty('-webkit-backdrop-filter', backdrop?.WebkitBackdropFilter ?? '');
        if (nodeStyle.backgroundColor === undefined) {
          dom.style.backgroundColor = backdrop?.backgroundColor ?? '';
        } else if (property === 'glassEffect') {
          // Glass just turned off: restore the authored fill it replaced.
          dom.style.backgroundColor = String(nodeStyle.backgroundColor);
        }
        return true;
      }
      // Route the per-frame channel value through the same lowering the
      // static description path uses (LLP 0417 §4): RN-style names become
      // real CSS ("shadowOpacity" is not a CSS property), numeric lengths
      // get their px unit, and transforms lower structurally.
      //
      // On web a shadow is ONE composed `box-shadow` declaration, so a write
      // of `shadowOpacity`/`shadowRadius` alone would drop the node's color
      // and offset. Re-lower the whole authored shadow group with the
      // animated component substituted — `applyHostChannelStyle` already
      // merged the channel value into `node.originalProps.style`, mirroring
      // the dom-mirror tier's composed shadow channel.
      const isShadowChannel = property === 'shadowOpacity' || property === 'shadowRadius';
      const authored = (node.originalProps?.style as Record<string, unknown> | undefined) ?? {};
      const css = lowerDomStyle(
        isShadowChannel
          ? {
              shadowColor: authored.shadowColor,
              shadowOffset: authored.shadowOffset,
              shadowRadius: authored.shadowRadius,
              shadowOpacity: authored.shadowOpacity,
              [property]: value,
            }
          : { [property]: value },
      );
      if (isShadowChannel && css.boxShadow === undefined) {
        // Radius drove to 0 (or no color/blur remains): the composed shadow
        // is gone, so clear the declaration instead of leaving a stale one.
        css.boxShadow = '';
      }
      const style = dom.style as unknown as Record<string, string>;
      for (const [name, cssValue] of Object.entries(css)) {
        if (name.startsWith('-')) dom.style.setProperty(name, cssValue);
        else style[name] = cssValue;
      }
      return true;
    },
  };

  globalThis.__exactContractWebHost = registry;
  const measureProvider = createDomMotionMeasureProvider(
    base,
    (rootId) => rootContainers.get(rootId) ?? null,
  );
  setMotionMeasureProvider(measureProvider);
  return {
    dispose(): void {
      disposed = true;
      if (getMotionMeasureProvider() === measureProvider) {
        setMotionMeasureProvider(null);
      }
      if (globalThis.__exactContractWebHost === registry) globalThis.__exactContractWebHost = undefined;
      for (const root of rootContainers.values()) {
        removeFocusScopesWithin(root);
        root.remove();
        disposeGraphicsBackendsWithin(root);
      }
      rootContainers.clear();
      // LLP 0364: the defs container is document-global and shared with every
      // other tier (dom-mirror hosts, React-tier hook retains). This host's
      // own references left the document with its root containers above, so a
      // sweep releases exactly them: defs another tier still references — and
      // the container — survive; the container is removed only once empty.
      sweepImageColorMatrixFilterDefs(document);
      colorMatrixDefsDirty = false;
    },
  };
}
