// @system @ref LLP 0292 / LLP 0336 §2, §4.2 / LLP 0373 phase 3c —
// lightweight always-mounted input inventory. Native keyboard transport and
// its protocol inventory remain in host-capabilities.ts and are reachable
// only when a compiled module declares key interaction behavior.

import { defineCapability } from './capabilities.js';
import { allowStateWrites } from './instance.js';
import { batch, signal } from './signals.js';

export type ContractPointerPrecision = 'coarse' | 'fine' | 'none';
export type ContractKeyboardPresence = 'present' | 'absent' | 'unknown';

export interface ContractInputInventory {
  readonly pointer: ContractPointerPrecision;
  readonly anyPointerCoarse: boolean;
  readonly anyPointerFine: boolean;
  readonly hover: boolean;
  readonly anyHover: boolean;
  readonly keyboard: ContractKeyboardPresence;
}

export interface ContractPreferences {
  readonly characterShortcutsEnabled: boolean;
  setCharacterShortcutsEnabled(enabled: boolean): void;
}

const inputPointer = signal<ContractPointerPrecision>('none');
const inputAnyPointerCoarse = signal(false);
const inputAnyPointerFine = signal(false);
const inputHover = signal(false);
const inputAnyHover = signal(false);
const inputKeyboard = signal<ContractKeyboardPresence>('unknown');
let inputObserverInstalled = false;
let inputObserverCleanup: (() => void) | null = null;

const CHARACTER_SHORTCUTS_STORAGE_KEY =
  'exact.preferences.characterShortcutsEnabled';
const characterShortcutsEnabled = signal(true);
let characterShortcutsHydrated = false;

const EDITABLE_TAGS = new Set(['INPUT', 'TEXTAREA', 'SELECT']);

function editableKeyboardTarget(target: EventTarget | null): boolean {
  const element = target as HTMLElement | null;
  return Boolean(
    element &&
    (EDITABLE_TAGS.has(element.tagName) || element.isContentEditable),
  );
}

function qualifiesAsHardwareKeyboardObservation(event: KeyboardEvent): boolean {
  return (
    !event.isComposing &&
    event.key !== 'Unidentified' &&
    event.key.length > 0 &&
    !editableKeyboardTarget(event.target)
  );
}

function readMedia(query: string): boolean {
  return typeof window !== 'undefined' &&
    typeof window.matchMedia === 'function'
    ? window.matchMedia(query).matches
    : false;
}

function refreshInputMedia(): void {
  batch(() =>
    allowStateWrites(() => {
      const fine = readMedia('(pointer: fine)');
      const coarse = readMedia('(pointer: coarse)');
      inputPointer.set(fine ? 'fine' : coarse ? 'coarse' : 'none');
      inputAnyPointerCoarse.set(readMedia('(any-pointer: coarse)'));
      inputAnyPointerFine.set(readMedia('(any-pointer: fine)'));
      inputHover.set(readMedia('(hover: hover)'));
      inputAnyHover.set(readMedia('(any-hover: hover)'));
    }),
  );
}

/** Installs independently of key binding registration; the same key event
 * flips unknown→present before later document listeners dispatch it. */
export function ensureInputInventoryObserver(): void {
  if (inputObserverInstalled || typeof document === 'undefined') return;
  inputObserverInstalled = true;
  refreshInputMedia();
  const medias = [
    '(pointer: fine)',
    '(pointer: coarse)',
    '(any-pointer: coarse)',
    '(any-pointer: fine)',
    '(hover: hover)',
    '(any-hover: hover)',
  ]
    .map((query) =>
      typeof window.matchMedia === 'function' ? window.matchMedia(query) : null,
    )
    .filter((value): value is MediaQueryList => value !== null);
  medias.forEach((media) =>
    media.addEventListener?.('change', refreshInputMedia),
  );
  const onKeyDown = (event: KeyboardEvent): void => {
    if (
      inputKeyboard.peek() === 'unknown' &&
      qualifiesAsHardwareKeyboardObservation(event)
    ) {
      batch(() => allowStateWrites(() => inputKeyboard.set('present')));
    }
  };
  // Close over the installed document: test hosts may remove the global
  // binding before teardown (ENG-25012).
  const installedDocument = document;
  installedDocument.addEventListener('keydown', onKeyDown);
  inputObserverCleanup = () => {
    medias.forEach((media) =>
      media.removeEventListener?.('change', refreshInputMedia),
    );
    installedDocument.removeEventListener('keydown', onKeyDown);
  };
}

export function readInputKeyboardPresence(): ContractKeyboardPresence {
  return inputKeyboard.get();
}

function readStoredCharacterShortcuts(): void {
  if (characterShortcutsHydrated) return;
  characterShortcutsHydrated = true;
  if (typeof localStorage === 'undefined') return;
  try {
    const stored = localStorage.getItem(CHARACTER_SHORTCUTS_STORAGE_KEY);
    if (stored === 'false') characterShortcutsEnabled.set(false);
    if (stored === 'true') characterShortcutsEnabled.set(true);
  } catch {
    // Storage denial leaves the safe default enabled for this session.
  }
}

export function setCharacterShortcutsEnabled(enabled: boolean): void {
  characterShortcutsHydrated = true;
  batch(() =>
    allowStateWrites(() => characterShortcutsEnabled.set(Boolean(enabled))),
  );
  if (typeof localStorage !== 'undefined') {
    try {
      localStorage.setItem(
        CHARACTER_SHORTCUTS_STORAGE_KEY,
        String(Boolean(enabled)),
      );
    } catch {
      // The in-memory preference remains writable when persistence is denied.
    }
  }
}

export function getCharacterShortcutsEnabled(): boolean {
  readStoredCharacterShortcuts();
  return characterShortcutsEnabled.get();
}

export const input = /* @__PURE__ */ defineCapability<ContractInputInventory>({
  id: 'contract.input',
  effects: ['host:input'],
  instantiate() {
    ensureInputInventoryObserver();
    return {
      get pointer() {
        return inputPointer.get();
      },
      get anyPointerCoarse() {
        return inputAnyPointerCoarse.get();
      },
      get anyPointerFine() {
        return inputAnyPointerFine.get();
      },
      get hover() {
        return inputHover.get();
      },
      get anyHover() {
        return inputAnyHover.get();
      },
      get keyboard() {
        return inputKeyboard.get();
      },
    };
  },
});

export const preferences = /* @__PURE__ */ defineCapability<ContractPreferences>({
  id: 'contract.preferences',
  effects: ['host:preferences'],
  instantiate() {
    readStoredCharacterShortcuts();
    return {
      get characterShortcutsEnabled() {
        return characterShortcutsEnabled.get();
      },
      setCharacterShortcutsEnabled,
    };
  },
});

export function _resetInputInventoryForTests(): void {
  inputObserverCleanup?.();
  inputObserverCleanup = null;
  inputObserverInstalled = false;
  inputPointer.set('none');
  inputAnyPointerCoarse.set(false);
  inputAnyPointerFine.set(false);
  inputHover.set(false);
  inputAnyHover.set(false);
  inputKeyboard.set('unknown');
  characterShortcutsEnabled.set(true);
  characterShortcutsHydrated = false;
}
