// @system @ref LLP 0166 §4.7 — versioned structural identity (static side).
//
// `structuralId` is the deterministic path through one component's view
// tree within ONE source version: stable across literal edits and reloads,
// NOT stable across insertions, branch reshapes, or extraction. It pairs
// with `sourceVersion` (the LLP 0158 staleness content hash) everywhere —
// edit targeting and hot-patch diffing never use an id without the version
// it came from. Path grammar (shared with the slot catalog): root is `v`;
// child i appends `i`; `when` branches mark `t{i}`/`e{i}`; `each` bodies
// mark `b{i}`; `match size` cases mark `m:<value>{i}` and else marks
// `me{i}`; resource/async slots mark `s:<kind>{i}`; boundary fallback/body mark
// `f{i}`/`bd{i}`; snippet bodies root at `snippet:<name>/r{i}`; segments
// after the root join with `.`.

import type { ComponentIR, ContractFileIR, Expr, ViewNodeIR } from './ir.js';
import { sha256Hex, utf8ByteLength } from './hash.js';

export const MAX_CONTRACT_STATE_INSTANCE_ANCESTORS = 128;
export const MAX_CONTRACT_STATE_INSTANCE_PREIMAGE_BYTES = 16 * 1024;

export type ContractEachIdentityKey =
  | { type: 'null'; value: null }
  | { type: 'boolean'; value: boolean }
  | { type: 'number'; value: number }
  | { type: 'string'; value: string };

export type ContractStateInstanceAncestor =
  | { type: 'callsite'; value: string }
  | { type: 'each'; value: ContractEachIdentityKey };

function assertIdentityString(value: string, field: string): void {
  if (value.length === 0) throw new Error(`${field} must not be empty`);
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code >= 0xd800 && code <= 0xdbff) {
      const low = value.charCodeAt(index + 1);
      if (!Number.isInteger(low) || low < 0xdc00 || low > 0xdfff) {
        throw new Error(`${field} contains a lone surrogate`);
      }
      index += 1;
    } else if (code >= 0xdc00 && code <= 0xdfff) {
      throw new Error(`${field} contains a lone surrogate`);
    }
  }
}

/**
 * Canonical type tag for one Contract `each` key used in stable state
 * identity. Objects, arrays, undefined, functions, and non-finite numbers
 * fail closed: their JS identity/display coercions are not a cross-runtime
 * reload identity. Finite numbers use RFC 8785's ECMAScript number
 * serialization, including large integers such as `1e21`.
 */
export function contractEachIdentityKey(value: unknown): ContractEachIdentityKey {
  if (value === null) return { type: 'null', value: null };
  if (typeof value === 'boolean') return { type: 'boolean', value };
  if (typeof value === 'string') {
    assertIdentityString(value, 'Contract each key');
    return { type: 'string', value };
  }
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new Error('Contract each key must be a finite number');
    return { type: 'number', value: Object.is(value, -0) ? 0 : value };
  }
  throw new Error('Contract stateful each key must be null, boolean, number, or string');
}

/**
 * RFC 8785 preimage for an Exact Native Contract child state instance.
 * Every object is constructed in UTF-16 property order, so JSON.stringify
 * emits the JCS bytes for this closed I-JSON shape.
 */
export function contractStateInstanceKeyPreimage(
  rootId: string,
  ancestors: readonly ContractStateInstanceAncestor[],
): string {
  assertIdentityString(rootId, 'Contract root id');
  if (ancestors.length === 0 || ancestors.at(-1)?.type !== 'callsite') {
    throw new Error('Contract child state identity must end at a component callsite');
  }
  if (ancestors.length > MAX_CONTRACT_STATE_INSTANCE_ANCESTORS) {
    throw new Error('Contract state instance ancestry exceeds its bound');
  }
  const canonicalAncestors = ancestors.map((ancestor): ContractStateInstanceAncestor => {
    if (ancestor.type === 'callsite') {
      assertIdentityString(ancestor.value, 'Contract component callsite structural id');
      return { type: 'callsite', value: ancestor.value };
    }
    const key = contractEachIdentityKey(ancestor.value.value);
    if (key.type !== ancestor.value.type) {
      throw new Error('Contract each key type tag does not match its value');
    }
    return { type: 'each', value: key };
  });
  const preimage = JSON.stringify({
    ancestors: canonicalAncestors,
    rootId,
    type: 'exact-contract-state-instance-v1',
  });
  if (utf8ByteLength(preimage) > MAX_CONTRACT_STATE_INSTANCE_PREIMAGE_BYTES) {
    throw new Error('Contract state instance preimage exceeds its bound');
  }
  return preimage;
}

/** LLP 0333 §5.1 child `instanceKey`: SHA-256(JCS(typed ancestor chain)). */
export function contractStateInstanceKey(
  rootId: string,
  ancestors: readonly ContractStateInstanceAncestor[],
): string {
  return sha256Hex(contractStateInstanceKeyPreimage(rootId, ancestors));
}

export function childPath(parent: string, segment: string): string {
  return parent === 'v' ? `v${segment}` : `${parent}.${segment}`;
}

/** Depth-first walk pairing every view node with its structural path. */
export function walkStructuralPaths(
  component: ComponentIR,
  visit: (node: ViewNodeIR, path: string) => void,
): void {
  const walk = (node: ViewNodeIR, path: string): void => {
    visit(node, path);
    switch (node.kind) {
      case 'element':
      case 'component':
        node.children.forEach((child, index) => {
          walk(child, childPath(path, String(index)));
        });
        return;
      case 'when':
        node.then.forEach((child, index) => {
          walk(child, childPath(path, `t${index}`));
        });
        (node.else ?? []).forEach((child, index) => {
          walk(child, childPath(path, `e${index}`));
        });
        return;
      case 'match':
        node.cases.forEach((arm, armIndex) => {
          arm.body.forEach((child, index) => {
            walk(child, childPath(path, `c${armIndex}b${index}`));
          });
        });
        (node.else ?? []).forEach((child, index) => {
          walk(child, childPath(path, `ce${index}`));
        });
        return;
      case 'match-size':
        node.cases.forEach((arm) => {
          arm.body.forEach((child, index) => {
            walk(child, childPath(path, `m:${arm.value}${index}`));
          });
        });
        (node.else ?? []).forEach((child, index) => {
          walk(child, childPath(path, `me${index}`));
        });
        return;
      case 'nothing':
      case 'hole':
        return;
      case 'each':
        node.body.forEach((child, index) => {
          walk(child, childPath(path, `b${index}`));
        });
        return;
      case 'resource':
      case 'async':
        node.slots.forEach((slot) => {
          slot.body.forEach((child, index) => {
            walk(child, childPath(path, `s:${slot.kind}${index}`));
          });
        });
        return;
      case 'boundary':
        node.fallback.body.forEach((child, index) => {
          walk(child, childPath(path, `f${index}`));
        });
        node.body.forEach((child, index) => {
          walk(child, childPath(path, `bd${index}`));
        });
        return;
      case 'text':
      case 'children':
      case 'snippet-call':
      // publish (LLP 0281 §3.1) is a childless effect line; it gets a
      // structural id (the visit above) like every other view node.
      case 'publish':
        return;
      // LLP 0386 H3a: exhaustiveness lands before pager's hydration-visible
      // identity repair. Visit the pager itself, but deliberately do not walk
      // its synthesized cells until H3/H4 switch the versioned wire codec.
      case 'pager':
        return;
      // RFC 0101 SG2: the surface gets a structural id (the visit above);
      // scene-node identity is graphicsId (LLP 0353 §3), a separate axis the
      // scene runtime owns — structural ids never reach inside the scene.
      case 'graphics':
        return;
      default:
        return assertNeverViewNode(node);
    }
  };
  walk(component.view, 'v');
  component.snippets.forEach((snippet) => {
    snippet.body.forEach((node, index) => {
      walk(node, `snippet:${snippet.name}/r${index}`);
    });
  });
}

function assertNeverViewNode(node: never): never {
  throw new Error(`unhandled Contract view node ${(node as { kind?: unknown }).kind ?? '<unknown>'}`);
}

/**
 * Structural ids for every view node in a component, keyed by node object
 * identity — a pure function of the IR (S4's differ and the runtime
 * registry share this exact derivation; S3's runtime registry is not a
 * prerequisite for it).
 */
export function assignStructuralIds(component: ComponentIR): Map<ViewNodeIR, string> {
  const ids = new Map<ViewNodeIR, string>();
  walkStructuralPaths(component, (node, path) => {
    ids.set(node, `${component.name}/${path}`);
  });
  return ids;
}

// ---------------------------------------------------------------------------
// The rebind contract
// ---------------------------------------------------------------------------

export type RebindResult =
  | { kind: 'matched'; structuralId: string }
  | { kind: 'ambiguous'; candidates: string[] }
  | { kind: 'gone' };

interface NodeFingerprint {
  /** Tag for elements, component name for calls, the kind otherwise. */
  shape: string;
  /** Authored identity when present (`testId`, then accessibility label). */
  authorKey?: string;
}

function fingerprintOf(node: ViewNodeIR): NodeFingerprint {
  const shape =
    node.kind === 'element' ? node.tag : node.kind === 'component' ? node.name : node.kind;
  let authorKey: string | undefined;
  if (node.kind === 'element' || node.kind === 'component') {
    const candidates: Array<Expr | undefined> = [
      node.props.testId,
      node.props.accessibilityLabel,
      node.props.label,
      node.props['aria-label'],
    ];
    for (const expr of candidates) {
      if (expr?.kind === 'string') {
        authorKey = expr.value;
        break;
      }
    }
  }
  return { shape, authorKey };
}

function nodesByPath(component: ComponentIR): Map<string, ViewNodeIR> {
  const out = new Map<string, ViewNodeIR>();
  walkStructuralPaths(component, (node, path) => {
    out.set(path, node);
  });
  return out;
}

/**
 * Rebinds a selection `(structuralId, oldFile)` against a new IR. Exactly
 * one of `matched` / `ambiguous` / `gone` — consumers must never guess on
 * `ambiguous` (the actor that MADE a structural edit owns its own
 * remapping; everyone else gets the honest tri-state).
 */
export function rebindStructuralId(
  structuralId: string,
  oldFile: ContractFileIR,
  newFile: ContractFileIR,
): RebindResult {
  const slash = structuralId.indexOf('/');
  if (slash === -1) {
    return { kind: 'gone' };
  }
  const componentName = structuralId.slice(0, slash);
  const path = structuralId.slice(slash + 1);

  const oldComponent = oldFile.components.find((c) => c.name === componentName);
  const newComponent = newFile.components.find((c) => c.name === componentName);
  if (!oldComponent || !newComponent) {
    return { kind: 'gone' };
  }
  const oldNode = nodesByPath(oldComponent).get(path);
  if (!oldNode) {
    return { kind: 'gone' };
  }
  const oldFingerprint = fingerprintOf(oldNode);

  const newPaths = nodesByPath(newComponent);
  const samePath = newPaths.get(path);
  if (samePath) {
    const candidate = fingerprintOf(samePath);
    if (
      candidate.shape === oldFingerprint.shape &&
      (oldFingerprint.authorKey === undefined ||
        candidate.authorKey === oldFingerprint.authorKey)
    ) {
      return { kind: 'matched', structuralId };
    }
  }

  // The path moved or reshaped. Search by the authored key when there is
  // one; without an authorKey a missing path is honestly `gone`.
  if (oldFingerprint.authorKey === undefined) {
    return { kind: 'gone' };
  }
  const candidates: string[] = [];
  newPaths.forEach((node, candidatePath) => {
    const fp = fingerprintOf(node);
    if (
      fp.shape === oldFingerprint.shape &&
      fp.authorKey === oldFingerprint.authorKey
    ) {
      candidates.push(`${componentName}/${candidatePath}`);
    }
  });
  if (candidates.length === 1) {
    return { kind: 'matched', structuralId: candidates[0] };
  }
  if (candidates.length > 1) {
    return { kind: 'ambiguous', candidates };
  }
  return { kind: 'gone' };
}
