// @system @ref LLP 0091 S0-S1 — first-party Contract form field model.

import { batch, signal } from './signals.js';

export type ContractFieldValidator = (
  value: unknown,
  values: Record<string, unknown>,
) => string | null | undefined | false;

export type ContractFormValidators = Record<string, ContractFieldValidator>;

export interface ContractFieldHandle {
  readonly name: string;
  readonly initial: unknown;
  readonly value: unknown;
  readonly touched: boolean;
  readonly dirty: boolean;
  readonly error: string | null;
  readonly valid: boolean;
  change(value: unknown): void;
  touch(): void;
  reset(): void;
}

export interface ContractFormHandle {
  field(name: string): ContractFieldHandle;
  readonly values: Record<string, unknown>;
  readonly errors: Record<string, string>;
  readonly valid: boolean;
  readonly dirty: boolean;
  readonly touched: boolean;
  readonly submitting: boolean;
  readonly error: string | null;
  readonly canSubmit: boolean;
  validate(): boolean;
  reset(): void;
  submit(fn?: (values: Record<string, unknown>) => unknown): unknown;
  setError(name: string, message: string | null): void;
  setFormError(message: string | null): void;
}

interface FieldState {
  name: string;
  initial: unknown;
  value: ReturnType<typeof signal<unknown>>;
  touched: ReturnType<typeof signal<boolean>>;
  serverError: ReturnType<typeof signal<string | null>>;
  handle: ContractFieldHandle;
}

export function createContractForm(
  initialValues: Record<string, unknown>,
  validators: ContractFormValidators = {},
): ContractFormHandle {
  const fields = new Map<string, FieldState>();
  const submitting = signal(false);
  const formError = signal<string | null>(null);

  const values = (): Record<string, unknown> => {
    const out: Record<string, unknown> = {};
    for (const [name, field] of fields) {
      out[name] = field.value.get();
    }
    return out;
  };

  const fieldError = (field: FieldState): string | null => {
    const manual = field.serverError.get();
    if (manual) {
      return manual;
    }
    const validator = validators[field.name];
    if (!validator) {
      return null;
    }
    const result = validator(field.value.get(), values());
    return typeof result === 'string' && result.length > 0 ? result : null;
  };

  const makeField = (name: string, initial: unknown): FieldState => {
    const value = signal(initial);
    const touched = signal(false);
    const serverError = signal<string | null>(null);
    const state: FieldState = {
      name,
      initial,
      value,
      touched,
      serverError,
      handle: undefined as unknown as ContractFieldHandle,
    };
    state.handle = {
      name,
      initial,
      get value() {
        return value.get();
      },
      get touched() {
        return touched.get();
      },
      get dirty() {
        return value.get() !== initial;
      },
      get error() {
        return fieldError(state);
      },
      get valid() {
        return fieldError(state) === null;
      },
      change(next: unknown) {
        batch(() => {
          value.set(next);
          touched.set(true);
          serverError.set(null);
        });
      },
      touch() {
        touched.set(true);
      },
      reset() {
        batch(() => {
          value.set(initial);
          touched.set(false);
          serverError.set(null);
        });
      },
    };
    return state;
  };

  for (const [name, initial] of Object.entries(initialValues)) {
    fields.set(name, makeField(name, initial));
  }

  const handle: ContractFormHandle = {
    field(name: string) {
      const field = fields.get(name);
      if (!field) {
        throw new Error(`[contract] form field "${name}" is not declared`);
      }
      return field.handle;
    },
    get values() {
      return values();
    },
    get errors() {
      const out: Record<string, string> = {};
      for (const [name, field] of fields) {
        const error = fieldError(field);
        if (error) {
          out[name] = error;
        }
      }
      return out;
    },
    get valid() {
      for (const field of fields.values()) {
        if (fieldError(field) !== null) {
          return false;
        }
      }
      return formError.get() === null;
    },
    get dirty() {
      for (const field of fields.values()) {
        if (field.value.get() !== field.initial) {
          return true;
        }
      }
      return false;
    },
    get touched() {
      for (const field of fields.values()) {
        if (field.touched.get()) {
          return true;
        }
      }
      return false;
    },
    get submitting() {
      return submitting.get();
    },
    get error() {
      return formError.get();
    },
    get canSubmit() {
      return handle.valid && !submitting.get();
    },
    validate() {
      return handle.valid;
    },
    reset() {
      batch(() => {
        for (const field of fields.values()) {
          field.handle.reset();
        }
        formError.set(null);
        submitting.set(false);
      });
    },
    submit(fn?: (values: Record<string, unknown>) => unknown) {
      batch(() => {
        for (const field of fields.values()) {
          field.touched.set(true);
        }
        formError.set(null);
      });
      if (!handle.valid || submitting.get()) {
        return false;
      }
      submitting.set(true);
      try {
        const result = fn ? fn(handle.values) : true;
        if (result && typeof (result as Promise<unknown>).then === 'function') {
          return (result as Promise<unknown>).finally(() => {
            submitting.set(false);
          });
        }
        submitting.set(false);
        return result;
      } catch (error) {
        submitting.set(false);
        formError.set(error instanceof Error ? error.message : String(error));
        return false;
      }
    },
    setError(name: string, message: string | null) {
      const field = fields.get(name);
      if (!field) {
        throw new Error(`[contract] form field "${name}" is not declared`);
      }
      field.serverError.set(message);
    },
    setFormError(message: string | null) {
      formError.set(message);
    },
  };

  return handle;
}
