// @system @ref LLP 0195 S0-S1 — Contract responsive size-class runtime.
//
// facet-core owns the size-class tokens and viewport input. Contract consumes
// that store as a reactive source for `match size`; no breakpoint table lives
// in the grammar/runtime layer.

import {
  resolveFacetSizeClass,
  subscribeFacetSizeClass,
  type SizeClass,
} from '@exact/facet-core';

import { runWithOwner, signal, type Signal } from './signals.js';
import type { RuntimeContext } from './instance.js';

let activeSizeClass: Signal<SizeClass> | null = null;
let unsubscribe: (() => void) | null = null;
const hydrationReleaseRegistered = new WeakSet<RuntimeContext>();

function resolveActiveSizeClass(): SizeClass {
  return resolveFacetSizeClass();
}

function ensureActiveSizeClass(): Signal<SizeClass> {
  if (!activeSizeClass) {
    // ENG-23201: module-global signal — create it OWNERLESS. The lazy create
    // runs inside the first consumer's `match size` effect, and an ambient-
    // owned signal registers observers.clear() with that component's owner:
    // its unmount would silently freeze every other component's size-class
    // reactivity while `activeSizeClass` stays non-null forever.
    activeSizeClass = runWithOwner(null, () =>
      signal<SizeClass>(resolveActiveSizeClass()),
    );
  }
  if (!unsubscribe) {
    unsubscribe = subscribeFacetSizeClass(() => {
      activeSizeClass?.set(resolveActiveSizeClass());
    });
  }
  return activeSizeClass;
}

export function readContractSizeClass(context?: RuntimeContext): SizeClass {
  const live = ensureActiveSizeClass();
  const liveValue = live.get();
  if (
    context?.hydrationCapabilitiesReleased === false &&
    !hydrationReleaseRegistered.has(context)
  ) {
    hydrationReleaseRegistered.add(context);
    context.releaseHydrationCapabilities.push(() => live.touch());
  }
  const hydrationWidth = context?.hydrationCapabilitiesReleased === false
    ? context.hydration?.capabilities?.viewport?.width
    : undefined;
  if (typeof hydrationWidth === 'number' && Number.isFinite(hydrationWidth)) {
    // @ref LLP 0210#capability-replay — responsive branch identity is part of
    // the server DOM. Resolve from the request/root-scoped captured viewport
    // until adoption releases instead of consulting the live process store.
    return resolveFacetSizeClass(hydrationWidth);
  }
  return liveValue;
}

export function _resetContractResponsiveForTests(): void {
  unsubscribe?.();
  unsubscribe = null;
  activeSizeClass = null;
}
