  position: 'position', top: 'top', left: 'left', right: 'right', bottom: 'bottom',
  zIndex: 'zIndex', transform: 'transform', transition: 'transition',
  boxShadow: 'boxShadow', shadowColor: 'shadowColor', shadowOffset: 'shadowOffset',
