export const CONTRACT_LOWERED_STYLE_VALUE_TRANSFORMS: Record<
  string,
  (value: unknown) => unknown
> = {
  gridTemplateColumns: (value) =>
    typeof value === 'number' && Number.isFinite(value)
      ? `repeat(${Math.max(1, Math.trunc(value))}, minmax(0, 1fr))`
      : value,
};

export function transformLoweredStyleValue(styleProp: string, value: unknown): unknown {
  const transform = CONTRACT_LOWERED_STYLE_VALUE_TRANSFORMS[styleProp];
  return transform ? transform(value) : value;
}

// LLP 0393 — Contract video vocabulary. It lives here (not in the schema)
// because the runtime mount path consumes it too, and this module is the
// schema-free lowering-facts home. Playback props apply only in self-owned
// mode; `player=` binds an `@exact/contract/video` behavior; view props
// apply in both modes.
