// @system @ref LLP 0381#p3--vertical-slice-aot-expressions-registration-and-the-kill-gate —
// Interpreter-neutral expression helpers for compiler-emitted production
// programs. This module has no value-level dependency on compiler IR or the
// editable expression interpreter.

import type { LayoutRelationOp } from '../compiler/ir.js';
import {
  Scope,
  spreadIntoArray,
  spreadIntoObject,
  type Binding,
  type EvalOptions,
} from './execution-scope.js';
import { createContractRelation } from './layout-intent.js';
import { getContractTokenResolver, readTokenPathFrom, warnUnresolvedToken } from './tokens.js';

const warnedIdents = new Set<string>();

export function resetGeneratedExpressionRuntimeForTests(): void {
  warnedIdents.clear();
}

export function readGeneratedToken(scope: Scope, path: string): unknown {
  const themeBinding = scope.lookup('theme');
  if (themeBinding) {
    const themeValue = readGeneratedBinding(themeBinding);
    if (themeValue !== null && typeof themeValue === 'object') {
      const resolved = readTokenPathFrom(themeValue, path);
      if (resolved !== undefined) return resolved;
    }
  }
  const resolver = getContractTokenResolver();
  if (resolver) {
    const resolved = resolver(path);
    if (resolved !== undefined) return resolved;
  }
  warnUnresolvedToken(path);
  return undefined;
}

export function readGeneratedIdent(
  scope: Scope,
  name: string,
  options: EvalOptions | undefined,
): unknown {
  const binding = scope.lookup(name);
  if (!binding) {
    if (options?.identFallbackToString) {
      if (!warnedIdents.has(name)) {
        warnedIdents.add(name);
        console.warn(
          `[contract] "${name}" is not in scope; treating it as the string "${name}" (quote it to silence this warning)`,
        );
      }
      return name;
    }
    throw new Error(`[contract] "${name}" is not defined`);
  }
  return readGeneratedBinding(binding);
}

export function readGeneratedMember(
  receiver: unknown,
  property: string,
  optional: boolean,
): unknown {
  if (receiver == null) {
    if (optional) return undefined;
    throw new Error(
      `[contract] cannot read "${property}" of ${receiver === null ? 'null' : 'undefined'}`,
    );
  }
  const value = (receiver as Record<string, unknown>)[property];
  if (
    typeof value === 'function' &&
    typeof (
      value as { __exactContractRandomAtSite?: unknown }
    ).__exactContractRandomAtSite === 'function'
  ) {
    return value;
  }
  return typeof value === 'function'
    ? (value as (...args: unknown[]) => unknown).bind(receiver)
    : value;
}

function readGeneratedIndex(receiver: unknown, key: unknown): unknown {
  if (receiver == null) throw new Error('[contract] cannot index into null/undefined');
  return (receiver as Record<string | number, unknown>)[key as string | number];
}

function callGenerated(
  fn: unknown,
  callee: string,
  args: unknown[],
  oracleReadSiteId: string | null,
): unknown {
  if (typeof fn !== 'function') {
    throw new Error(`[contract] attempted to call a non-function (${callee})`);
  }
  const oracleRandom = (
    fn as { __exactContractRandomAtSite?: (siteId: string) => number }
  ).__exactContractRandomAtSite;
  if (oracleReadSiteId && typeof oracleRandom === 'function') {
    if (args.length !== 0) {
      throw new Error('[contract] Math.random() accepts no arguments');
    }
    return oracleRandom(oracleReadSiteId);
  }
  return (fn as (...values: unknown[]) => unknown)(...args);
}

function generatedTemplateValue(value: unknown): string {
  return value == null ? '' : String(value);
}

function buildGeneratedArray(values: unknown[], spreads: boolean[]): unknown[] {
  const out: unknown[] = [];
  values.forEach((value, index) => {
    if (spreads[index]) spreadIntoArray(out, value);
    else out.push(value);
  });
  return out;
}

function buildGeneratedObject(
  keys: Array<string | null>,
  values: unknown[],
): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  keys.forEach((key, index) => {
    if (key === null) spreadIntoObject(out, values[index]);
    else out[key] = values[index];
  });
  return out;
}

function generatedArrowScope(scope: Scope, params: string[], args: unknown[]): Scope {
  const child = scope.child();
  params.forEach((param, index) => child.defineLocal(param, args[index]));
  return child;
}

function createGeneratedRelation(
  op: LayoutRelationOp,
  args: unknown[],
  fallback: unknown,
): unknown {
  return createContractRelation(op, args, fallback);
}

/**
 * Compact generated ABI. The deliberately short member names are part of the
 * emitted-program byte budget; descriptive wrappers stay available from the
 * legacy runtime module.
 */
export const contractGeneratedExpressionRuntime = /* @__PURE__ */ Object.freeze({
  t: readGeneratedToken,
  i: readGeneratedIdent,
  m: readGeneratedMember,
  x: readGeneratedIndex,
  c: callGenerated,
  v: generatedTemplateValue,
  a: buildGeneratedArray,
  o: buildGeneratedObject,
  s: generatedArrowScope,
  r: createGeneratedRelation,
});

export function readGeneratedBinding(binding: Binding): unknown {
  switch (binding.kind) {
    case 'value':
    case 'local':
      return binding.value;
    case 'getter':
    case 'state':
      return binding.get();
  }
}
