// @system @ref LLP 0081 — Contract canonical IR (v0).
//
// The IR is the artifact (LLP 0080 amendment 2026-06-10: source text never
// travels; compiled IR does). Everything here is plain JSON-able data: the
// Vite plugin embeds it in emitted modules, the runtime interprets it, and
// the verifier converts `contract` clauses from it. Expressions are small
// ASTs evaluated by the runtime's interpreter — v0's deliberate execution
// choice (no codegen) so the IR stays the single artifact.

// ---------------------------------------------------------------------------
// Expressions (LLP 0087 pure-expression subset + action statement targets)
// ---------------------------------------------------------------------------

export type LayoutRelationOp =
  | 'fill'
  | 'ratio'
  | 'center'
  | 'pinToSafeArea'
  | 'matchWidth'
  | 'matchHeight'
  | 'alignTo';

export type Expr =
  | { kind: 'string'; value: string; span?: Span }
  // First-class token reference (LLP 0166 §4.4): `$space.md` names a path in
  // the facet-core theme schema — statically recognizable, no scope
  // evaluation. `path` excludes the `$` sigil.
  | { kind: 'token'; path: string; span?: Span }
  // First-class layout-intent relationship (LLP 0199 S0). Pure v0
  // relationships (`fill`, `ratio`, `center`) lower to Taffy/flex inputs; the
  // measured-sibling ops remain stored as intent until LLP 0195 S2 lands.
  | { kind: 'relation'; op: LayoutRelationOp; args: Expr[]; fallback?: Expr; span?: Span }
  | { kind: 'number'; value: number; span?: Span }
  | { kind: 'boolean'; value: boolean; span?: Span }
  | { kind: 'null'; span?: Span }
  | { kind: 'ident'; name: string; span?: Span }
  | { kind: 'member'; object: Expr; property: string; optional?: boolean; span?: Span }
  | { kind: 'index'; object: Expr; index: Expr; span?: Span }
  | {
      kind: 'call';
      callee: Expr;
      args: Expr[];
      span?: Span;
      /** Replay certificate-assigned lexical oracle identity. */
      oracleReadSiteId?: string;
    }
  | { kind: 'unary'; op: '!' | '-'; operand: Expr; span?: Span }
  | {
      kind: 'binary';
      op:
        | '+' | '-' | '*' | '/' | '%'
        | '==' | '!=' | '<' | '<=' | '>' | '>='
        | '&&' | '||' | '??';
      left: Expr;
      right: Expr;
      span?: Span;
    }
  | { kind: 'ternary'; test: Expr; consequent: Expr; alternate: Expr; span?: Span }
  | {
      kind: 'template';
      parts: Array<{ kind: 'text'; text: string } | { kind: 'expr'; expr: Expr }>;
      span?: Span;
    }
  | { kind: 'array'; items: ArrayLiteralItem[]; span?: Span }
  | { kind: 'object'; entries: ObjectLiteralEntry[]; span?: Span }
  | { kind: 'arrow'; params: string[]; body: Expr; span?: Span };

/**
 * Spread element inside array/object literals (LLP 0277 §4.2):
 * `[...items, item]`, `{ ...obj, done: true }`. Deliberately restricted to
 * literal positions — call arguments and function params do not spread.
 * The spread argument is an ordinary read; purity classification of the
 * containing literal is unchanged.
 */
export interface ExprSpread {
  spread: true;
  value: Expr;
  span?: Span;
}

export type ArrayLiteralItem = Expr | ExprSpread;

export type ObjectLiteralEntry = { key: string; value: Expr } | ExprSpread;

/** Narrows an array item or object entry to its spread arm. */
export function isExprSpread(entry: ArrayLiteralItem | ObjectLiteralEntry): entry is ExprSpread {
  return 'spread' in entry && (entry as ExprSpread).spread === true;
}

/**
 * The expression an array literal item reads — the item itself, or the
 * spread argument (an ordinary read for traversal/purity purposes).
 */
export function arrayItemExpr(item: ArrayLiteralItem): Expr {
  return isExprSpread(item) ? item.value : item;
}

// ---------------------------------------------------------------------------
// Statements (action/task bodies; LLP 0087 statement classes)
// ---------------------------------------------------------------------------

export type Stmt =
  | { kind: 'let'; name: string; value: Expr; span: Span }
  | { kind: 'assign'; target: AssignTarget; value: Expr; span: Span }
  | { kind: 'expr'; expr: Expr; await?: boolean; span: Span }
  | { kind: 'if'; test: Expr; then: Stmt[]; else?: Stmt[]; inline?: boolean; span: Span }
  | { kind: 'for'; item: string; iterable: Expr; body: Stmt[]; span: Span }
  | { kind: 'return'; value?: Expr; span: Span }
  | { kind: 'await-assign'; target: AssignTarget | null; isLet: boolean; value: Expr; span: Span };

export type AssignTarget =
  | { kind: 'name'; name: string }
  | { kind: 'member'; object: Expr; property: string }
  | { kind: 'index'; object: Expr; index: Expr };

/**
 * Exact source span (LLP 0166 §4.1). All offsets/lengths are in UTF-16 code
 * units — JS string semantics — computed at lex time. `line` predates the
 * other fields and remains the field line-oriented consumers read.
 */
export interface Span {
  /** 1-based source line in the .contract file. */
  line: number;
  /** 1-based column of the first character, in UTF-16 code units. */
  col: number;
  /** 0-based absolute offset into the source, in UTF-16 code units. */
  offset: number;
  /** Length in UTF-16 code units. */
  len: number;
}

/**
 * Exact source text of literal-valued props, keyed by prop name as written
 * (LLP 0158 D2). Present only for props whose value is a single literal
 * token; the Design Mode commit plane uses `attr=` + this text as the
 * anchored, exactly-once replacement target for instance edits.
 */
export type PropSources = Record<string, string>;

// ---------------------------------------------------------------------------
// Typed props (LLP 0166 §4.5)
// ---------------------------------------------------------------------------

export type TypeIR =
  | { kind: 'primitive'; name: 'string' | 'number' | 'boolean' }
  | { kind: 'literal-union'; values: string[] } // string-only in v0
  | { kind: 'array'; element: TypeIR }
  | { kind: 'function' } // signature stays in raw
  // Action-typed prop (LLP 0280 §2.3): `action(id: string)`. Bindable to
  // event attrs or threadable to other action-typed props; never callable
  // in pure contexts. Params without a type annotation are arity-only.
  | { kind: 'action'; params: ActionTypeParamIR[] }
  | { kind: 'value-kind'; name: 'dimension' | 'color' | 'duration' }
  | { kind: 'named'; name: string; variant?: string }
  | { kind: 'opaque' }; // raw carries the text

/** One declared parameter of an action-typed prop (LLP 0280 §2.3). */
export interface ActionTypeParamIR {
  name: string;
  /** Declared param type when written; absent means arity-only checking. */
  type?: TypeIR;
  /** Verbatim source of the param's type annotation (diagnostics/display). */
  typeRaw?: string;
}

/**
 * A parsed type annotation that PRESERVES the raw source text — unparseable
 * types degrade to `opaque` with the raw intact (graceful degradation,
 * never a gate).
 */
export interface ParsedType {
  /** Verbatim source text — never discarded, even when parsed. */
  raw: string;
  ir: TypeIR;
  span: Span;
  diagnostics: Diagnostic[];
}

// ---------------------------------------------------------------------------
// Component blocks
// ---------------------------------------------------------------------------

export interface PropIR {
  name: string;
  /** Space-joined token text (pre-LLP 0166 shape; kept for compatibility). */
  type?: string;
  /** Structured type view (LLP 0166 §4.5). */
  parsedType?: ParsedType;
  defaultValue?: Expr;
  span: Span;
}

export interface StateIR {
  name: string;
  type?: string;
  /** Structured type view for `state x: T = ...` (LLP 0234 typed state). */
  parsedType?: ParsedType;
  initial: Expr;
  span: Span;
}

// ---------------------------------------------------------------------------
// Reactive host bindings (LLP 0292, ENG-24199)
// ---------------------------------------------------------------------------

/**
 * A component-scoped, read-only projection of host-owned state. The parser
 * lowers the deliberately closed authoring forms into this discriminated IR
 * so runtimes never have to execute an arbitrary initializer to discover a
 * capability. `hosts` stays optional on ComponentIR: modules with no host
 * declarations retain their pre-ENG-24199 serialized shape and startup graph.
 */
export type HostBindingIR =
  | {
      name: string;
      capability: 'colorScheme';
      span: Span;
    }
  | {
      name: string;
      capability: 'safeAreaInsets';
      span: Span;
    }
  | {
      name: string;
      capability: 'geolocation';
      mode: 'whenAvailable';
      span: Span;
    }
  | {
      name: string;
      capability: 'appGlue';
      /** Static provider channel name. Dynamic event-bus names are forbidden. */
      key: string;
      /** Static JSON-like default; also defines the publication value shape. */
      defaultValue: Expr;
      span: Span;
    };

/**
 * `params` section entry (LLP 0163 §5.3): a reified facet recipe parameter
 * declared in component source — the semantic declaration recipes read
 * through the resolver and the `RECIPE_PARAMETERS` generator consumes.
 */
export interface ParamIR {
  name: string;
  defaultValue: Expr;
  /** Value kind feeding control inference + commit-plane validation. */
  kind?: 'dimension' | 'color' | 'duration';
  span: Span;
}

// ---------------------------------------------------------------------------
// Design controls (LLP 0163 §5.3): the `design` block. Controls are LENSES
// over existing rungs of the scope ladder (prop / facet param / theme
// token), never value homes — declaration lives in `props`/`params`; a
// `control` line contributes presentation only.
// ---------------------------------------------------------------------------

export type DesignControlKind =
  | 'slider'
  | 'number'
  | 'text'
  | 'select'
  | 'radio'
  | 'toggle'
  | 'color';

/** Explicit binding kinds so a typo can never silently retarget a control. */
export type DesignControlBindingIR =
  | { kind: 'prop'; name: string }
  | { kind: 'facet'; param: string }
  | { kind: 'token'; name: string; path: string };

export interface DesignControlConstraintsIR {
  min?: number;
  max?: number;
  step?: number;
  options?: string[];
}

export interface DesignControlIR {
  binding: DesignControlBindingIR;
  /** `as <kind>`; inferred from the binding's type/kind when absent. */
  controlKind?: DesignControlKind;
  constraints: DesignControlConstraintsIR;
  label?: string;
  group?: string;
  span: Span;
}

export interface DeriveIR {
  name: string;
  type?: string;
  expr: Expr;
  /**
   * Opt-in result stabilization. Omitted derives retain the signal core's
   * ordinary Object.is identity semantics.
   */
  memo?: DeriveMemoIR;
  span: Span;
}

export type DeriveMemoIR =
  /** Scalar, plain-object, or scalar-array shallow equality. */
  | { kind: 'shallow' }
  /** User-supplied `(previous, next) => boolean` equality predicate. */
  | { kind: 'comparator'; comparator: Expr }
  /** Bottom-up structural sharing for plain data with keyed object arrays. */
  | { kind: 'rows'; key: string };

export interface ResourceIR {
  name: string;
  /** LLP 0342 declaration identity (module/component scope joins at runtime). */
  effectId?: string;
  /** The async initializer; re-evaluated when its reactive reads change. */
  expr: Expr;
  span: Span;
}

export interface QueryIR {
  name: string;
  /** Typed query-handle initializer behind the LLP 0183 `query` boundary. */
  expr: Expr;
  /**
   * LLP 0284 §2.3 — `query x = f() once`: one snapshot-with-subscribe read,
   * then no ongoing subscription (the binding settles at its first value and
   * its connection axis is absent). Omitted (never `false`) when unmodified.
   */
  once?: boolean;
  span: Span;
}

/**
 * LLP 0284 §2.5 — `ephemeral <name> = <descriptor>(args)`: a typed reactive
 * map over provider-owned presence state. Excluded from `mutates` effect
 * checking and from undo/replay by construction (§2.5); the keyword spelling
 * is provisional pending the B-4 freeze (LLP 0284 OQ1).
 */
export interface EphemeralIR {
  name: string;
  /** Ephemeral-map handle initializer behind the LLP 0183 boundary. */
  expr: Expr;
  span: Span;
}

export interface MutationIR {
  name: string;
  /** LLP 0342 declaration identity (preserved across opaque→descriptor migration). */
  effectId?: string;
  /** Manifest-backed mutation descriptor/callable behind the LLP 0183 boundary. */
  expr: Expr;
  span: Span;
}

export interface ActionIR {
  name: string;
  effectId?: string;
  /** Lexically ordered possible effect call sites in this declaration body. */
  effectSites?: EffectOperationSiteIR[];
  params: string[];
  /** A3 effect signature: declared state writes (`action save writes draft`). */
  writes?: string[];
  /** LLP 0263 effect signature: declared provider mutations called by this action. */
  mutates?: string[];
  body: Stmt[];
  span: Span;
}

export type TaskTrigger =
  | { kind: 'mount' }
  | { kind: 'manual' }
  | { kind: 'when'; deps: string[] };

export interface TaskIR {
  name: string;
  effectId?: string;
  /** Lexically ordered possible effect call sites in this declaration body. */
  effectSites?: EffectOperationSiteIR[];
  trigger: TaskTrigger;
  /** LLP 0263 effect signature: declared provider mutations called by this task. */
  mutates?: string[];
  body: Stmt[];
  span: Span;
}

export interface EffectOperationSiteIR {
  id: string;
  /** Stable only within the declaration body absent earlier same-body insertions. */
  ordinal: number;
  context: 'call' | 'await' | 'return';
  span: Span;
}

export interface SnippetIR {
  name: string;
  params: string[];
  body: ViewNodeIR[];
  span: Span;
}

/** `use Name from "spec"` (module-level) */
export interface UseImportIR {
  name: string;
  spec: string;
  span: Span;
}

// ---------------------------------------------------------------------------
// Import boundary descriptors and witness (LLP 0183 descriptors-only core)
// ---------------------------------------------------------------------------

export type ContractImportKind =
  | 'component'
  | 'pure'
  | 'shape'
  | 'styleRecipe'
  | 'store'
  | 'capability'
  | 'query'
  | 'mutation'
  // LLP 0284 §2.5: generated `*.ephemeral.ts` read descriptors (Snapback
  // LLP 0034 §4 emits them); provisional spelling pending B-4 (OQ1).
  | 'ephemeral'
  // LLP 0281 §3.1 (ENG-22525): generated `*.publish.ts` ephemeral publish
  // descriptors — the write side of the LLP 0284 source seam. Carries the
  // provider budget facts the rated `publish` line compiles against.
  | 'publish'
  | 'opaque';

export type ContractImportConfidence =
  | 'static'
  | 'declared'
  | 'inferred'
  | 'runtime'
  | 'opaque';

export type ContractImportProvenanceSource =
  | 'contract-ir'
  | 'module-export'
  | 'sidecar'
  | 'package-manifest'
  | 'inference'
  | 'runtime-observation'
  | 'opaque';

export interface ContractImportProvenance {
  source: ContractImportProvenanceSource;
  file?: string;
  span?: Span;
}

export interface ContractImportDescriptorBase {
  kind: ContractImportKind;
  confidence: ContractImportConfidence;
  provenance: ContractImportProvenance;
  params?: string[] | Record<string, unknown>;
  effects?: string[];
  reads?: string[];
  invalidates?: string[];
}

export interface PureImportDescriptor extends ContractImportDescriptorBase {
  kind: 'pure';
  depends: 'args' | string[];
  result?: string;
}

export type ShapeFieldDescriptor =
  | string
  | {
      type: string;
      optional?: boolean;
    };

export interface ShapeVariantDescriptor {
  fields: Record<string, ShapeFieldDescriptor>;
}

export interface ShapeImportDescriptor extends ContractImportDescriptorBase {
  kind: 'shape';
  fields?: Record<string, ShapeFieldDescriptor>;
  discriminant?: string;
  variants?: Record<string, ShapeVariantDescriptor>;
}

/**
 * LLP 0398 P3/D5 — an operand reference inside a style-recipe helper call.
 * String references resolve through the descriptor reference grammar
 * (`'theme'` = the whole resolved theme, `'theme.<path>'` = a token leaf,
 * `'<Component>.<param>'` = a reified recipe param, `'const.<name>'` = a
 * registered module constant); `{ literal }` is an explicit literal (the
 * unambiguous spelling for values that would otherwise parse as references).
 */
export type StyleRecipeOperandRef = string | { literal: unknown };

/**
 * LLP 0398 P3/D5 — a named helper derivation for one output leaf. The
 * helper's operands are declared by name so drift gates can execute the
 * real helper against the resolved operands and compare (D5's "compare
 * helper operands"); `pick` selects one key of an object-returning helper
 * (e.g. `applyShadow(...)` → `boxShadow`). A `via` derivation is honest
 * `computed` confidence — never `exact` (LLP 0398 D5).
 */
export interface StyleRecipeHelperRef {
  helper: string;
  operands?: Record<string, StyleRecipeOperandRef>;
  pick?: string;
}

/**
 * One output leaf of a style recipe. `by` names the normalized selector
 * dimensions (declared in the descriptor's `domains`); `cases` nests by the
 * `by` dimensions in order, `'*'` is a per-level wildcard, and a case leaf
 * is a literal, a reference string, the reserved strings `'undefined'`
 * (key present with value undefined) / `'absent'` (key not produced), or a
 * `StyleRecipeHelperRef`-shaped object (`via`). The legacy coarse form
 * (`value: 'Style'`, flat cases, string `via`) remains valid — coarse
 * descriptors yield honestly-truncated graphs, never wrong ones.
 */
export interface StyleRecipeOutputDescriptor {
  by?: string[];
  value?: unknown;
  cases?: Record<string, unknown>;
  via?: string | StyleRecipeHelperRef;
}

export interface StyleRecipeImportDescriptor extends ContractImportDescriptorBase {
  kind: 'styleRecipe';
  component?: string;
  reads: string[];
  outputs: Record<string, StyleRecipeOutputDescriptor>;
  /** LLP 0398 P3/D5 — versioned rule identity for the recipe step (the D1
   * `rule: {id, version}` shape; a behavior change bumps `ruleVersion`). */
  ruleId?: string;
  ruleVersion?: number;
  /**
   * Completeness claim (LLP 0398 D5). `'leaf'` asserts that `outputs`
   * enumerates every key the recipe actually produces, at leaf granularity
   * — a claim the runtime drift gates validate by executing every
   * enumerated case, and FAIL CLOSED on (`descriptor-drift`) so a lying
   * descriptor can never produce a confident wrong attribution. Absent or
   * `'coarse'`: no completeness claim; explanations truncate honestly.
   */
  granularity?: 'leaf' | 'coarse';
  /** Normalized selector-dimension domains for `'leaf'` case enumeration
   * (the variant/interaction/disabled/size tuple axes). */
  domains?: Record<string, string[]>;
}

export interface StoreImportDescriptor extends ContractImportDescriptorBase {
  kind: 'store';
  snapshotReadable?: boolean;
}

/**
 * LLP 0284 §2.4 liveness facts on an import descriptor (ENG-22526): the
 * subset of the manifest-v2 fields a generated `.contract-meta.ts` sidecar
 * carries so the COMPILER can reason about serving mode — field names match
 * §2.4 exactly (the Snapback codegen emits them under these names). All
 * optional: absence of facts is silence, never a diagnostic.
 */
export interface ImportLivenessFacts {
  /** How the binding is kept current (§2.4). */
  mode?: 'snapshot' | 'live' | 'poll' | 'reconcile-on-mutate';
  /** Whether the provider can push deltas for this descriptor. */
  livePush?: boolean;
  /** Whether the subscription primes with an authoritative snapshot (§2.1 rule 1). */
  initialSnapshot?: boolean;
  /** Poll cadence floor, provider-owned. */
  pollCadenceMs?: number;
  /** Declared delta transport (§2.1 rule 3's static twin). */
  transport?: 'push' | 'poll' | 'reconcile-on-mutate';
  /** §2.4's ephemeral-collection fact; on imports the `ephemeral` KIND is the primary spelling. */
  ephemeral?: boolean;
  /**
   * @ref LLP 0392 B3 — RESERVED per-descriptor first-hydration boot-policy
   * carrier, threaded from `DeclarationQueryLiveness.bootPolicy` by the
   * declaration generator. Semantics are ratified by the Snapback
   * local-first design; nothing consumes it yet.
   */
  bootPolicy?: 'render-local' | 'hold-until-hydrated';
}

export interface QueryImportDescriptor extends ContractImportDescriptorBase, ImportLivenessFacts {
  kind: 'query';
  readMode?: 'sync' | 'async';
  cacheKey?: string;
  result?: string;
}

/**
 * LLP 0284 §2.5 — an ephemeral-collection read descriptor. `reads` names the
 * ephemeral collection(s) it observes; ephemeral reads never close durable
 * data loops (§2.5: excluded from mutates effect checking and undo/replay).
 */
export interface EphemeralImportDescriptor extends ContractImportDescriptorBase, ImportLivenessFacts {
  kind: 'ephemeral';
  /** Entry value type, when the generator declares one. */
  result?: string;
}

/**
 * LLP 0281 stage 0 — publish budget facts a provider generator declares on
 * an ephemeral publish descriptor (Snapback LLP 0034 §4 emits them). The
 * analyzer checks a `publish` line's declared `rate` against `sustainedHz`;
 * all fields optional — absence degrades the check, never fails it.
 */
export interface PublishBudgetDescriptor {
  sustainedHz?: number;
  burst?: number;
  maxValueBytes?: number;
}

/**
 * LLP 0281 §3.1 (ENG-22525) — a generated `*.publish.ts` ephemeral publish
 * descriptor: the target of the rated `publish <channel> -> <descriptor>
 * rate=N` view line. Publishes are ephemeral-durability by definition
 * (Snapback LLP 0013): they invalidate nothing durable and stay out of
 * undo/replay; `budget` carries the provider facts the declared rate is
 * checked against at compile time. Mutation-shaped descriptors carrying
 * `publishBudget` remain accepted transitionally until provider generators
 * emit this kind.
 */
export interface PublishImportDescriptor extends ContractImportDescriptorBase {
  kind: 'publish';
  effects: string[];
  budget?: PublishBudgetDescriptor;
  params?: Record<string, unknown>;
}

export type ContractImportDescriptor =
  | { kind: 'component'; confidence: ContractImportConfidence; provenance: ContractImportProvenance }
  | PureImportDescriptor
  | ShapeImportDescriptor
  | StyleRecipeImportDescriptor
  | StoreImportDescriptor
  // LLP 0281 stage 0: `channel` marks a capability whose component-level
  // instantiation (`use cursors = pointerChannel(...)`) yields a host-owned
  // value-channel set (the LLP 0280 §2.2 root-capability shape; value is the
  // channel class, e.g. 'pointer').
  | { kind: 'capability'; confidence: ContractImportConfidence; provenance: ContractImportProvenance; params?: Record<string, unknown>; effects: string[]; channel?: string }
  | QueryImportDescriptor
  | EphemeralImportDescriptor
  | { kind: 'mutation'; confidence: ContractImportConfidence; provenance: ContractImportProvenance; params?: Record<string, unknown>; effects: string[]; invalidates?: string[]; publishBudget?: PublishBudgetDescriptor }
  | PublishImportDescriptor
  | { kind: 'opaque'; confidence: 'opaque'; provenance: ContractImportProvenance };

export interface ResolvedContractImportIR {
  name: string;
  spec: string;
  descriptor: ContractImportDescriptor;
  span: Span;
}

/**
 * Minimal authored locus retained for an opaque import in production runtime
 * IR. Full `uses`/`imports` inventories remain build-time-only; hydration
 * needs this subset to diagnose prepare-time work that may be reissued.
 */
export interface HydrationOpaqueImportIR {
  spec: string;
  span: Span;
}

export interface ContractWitnessEdge {
  name: string;
  kind: ContractImportKind;
  confidence: ContractImportConfidence;
  provenance: ContractImportProvenance;
  effects?: string[];
  reads?: string[];
  depends?: 'args' | string[];
}

export interface ContractWitnessDiagnostic {
  code: string;
  severity: Diagnostic['severity'];
  message: string;
  line: number;
}

export interface ImportWitness extends ContractWitnessEdge {
  spec: string;
}

export interface DeriveWitness {
  name: string;
  calls: ContractWitnessEdge[];
}

export interface ActionWitness {
  name: string;
  calls: ContractWitnessEdge[];
  effects: string[];
  opaqueBoundaries: ContractWitnessEdge[];
}

export interface EventWitness {
  event: string;
  handler: string;
  calls: ContractWitnessEdge[];
}

export interface ViewBindingWitness {
  componentId: string;
  binding: string;
  calls: ContractWitnessEdge[];
}

export interface StyleRecipeWitness {
  name: string;
  component?: string;
  reads: string[];
  outputs: Record<string, StyleRecipeOutputDescriptor>;
  confidence: ContractImportConfidence;
  provenance: ContractImportProvenance;
}

export interface OpaqueBoundaryWitness {
  name: string;
  context: 'pure' | 'resource' | 'query' | 'ephemeral' | 'mutation' | 'handler' | 'action' | 'task';
  line: number;
  confidence: 'opaque';
  provenance: ContractImportProvenance;
}

/**
 * One `use x = ...` slot in the component's interface projection
 * (LLP 0280 §2.1): which analyzability the slot bought, made explicit.
 */
export interface BehaviorUseWitness {
  name: string;
  /** `template` = same-file behavior template, graph inlined; `opaque` = JS factory. */
  resolution: 'template' | 'opaque';
  /** Template name when resolution is `template`. */
  behavior?: string;
  /** The template's declared (exposed) interface when resolved. */
  exposes?: string[];
}

/** A rated `publish` line's compile-time facts (LLP 0281 §3.1/§3.5). */
export interface ChannelPublishWitness {
  /** Publish descriptor import name. */
  descriptor: string;
  /** Declared rate in Hz — the IR fact an agent reads ("publishes at 20Hz"). */
  rateHz?: number;
  /** Declared idle keepalive in Hz (ENG-22539), when authored. */
  heartbeatHz?: number;
  /** Provider budget facts from the resolved import descriptor. */
  budget?: PublishBudgetDescriptor;
  /** Whether the line carries a payload mapping over sample/element. */
  hasPayload: boolean;
  line: number;
}

/**
 * A programmatic `publish(<channel>)` emitter (LLP 0281 §3.1, ENG-22539):
 * which action/task bodies request paced emissions through the channel's
 * declared publish line — the §3.5 topology fact an agent reads ("action
 * pickColor publishes cursors on demand").
 */
export interface ChannelEmitterWitness {
  kind: 'action' | 'task';
  name: string;
  line: number;
}

/**
 * LLP 0281 §3.5 (ENG-22525) — one value-channel binding's compile-time
 * topology: the pointer events that write it, the presentation-sink
 * classes (presentation-sinks.ts authority) that read it, and the rated
 * publishes that sample it. Live values ride the dataflow snapshot's
 * `channels` section, never this witness (live-observable, not
 * replay-asserted).
 */
export interface ChannelWitness {
  binding: string;
  /** Channel class ('pointer') or 'prop' for pass-through channel props. */
  channelClass: string;
  /** Capability import name, for component-local instances. */
  capability?: string;
  /** `via: 'sample'` marks edge events writing through `sample(<channel>)`. */
  events: Array<{ event: string; line: number; via?: 'sample' }>;
  sinks: Array<{ sinkClass: string; attr: string; line: number }>;
  publishes: ChannelPublishWitness[];
  /**
   * Programmatic `publish(<channel>)` emitters (ENG-22539). Optional so
   * witnesses from earlier builds stay loadable; consumers read
   * `channel.emitters ?? []`.
   */
  emitters?: ChannelEmitterWitness[];
}

export interface ComponentWitness {
  componentId: string;
  derives: Record<string, DeriveWitness>;
  actions: Record<string, ActionWitness>;
  events: EventWitness[];
  viewBindings: ViewBindingWitness[];
  styleRecipes: StyleRecipeWitness[];
  opaqueBoundaries: OpaqueBoundaryWitness[];
  /**
   * Behavior instantiations (LLP 0280 §2.1). Optional so witnesses from
   * builds predating the construct stay loadable; consumers read
   * `witness.behaviors ?? {}`.
   */
  behaviors?: Record<string, BehaviorUseWitness>;
  /**
   * Value-channel topology (LLP 0281 §3.5, ENG-22525): bindings, pointer
   * events, sink classes, and rated publishes with declared rates.
   * Optional (same loadability rule); consumers read
   * `witness.channels ?? {}`.
   */
  channels?: Record<string, ChannelWitness>;
}

export interface ContractWitness {
  schemaVersion: 1;
  producer: {
    package: '@exact/contract';
    version?: string;
  };
  file?: string;
  sourceHash?: string;
  imports: Record<string, ImportWitness>;
  components: Record<string, ComponentWitness>;
  diagnostics: ContractWitnessDiagnostic[];
}

/** `use hover = interaction()` (component-level behavior instantiation) */
export interface UseBehaviorIR {
  name: string;
  expr: Expr;
  span: Span;
  /**
   * LLP 0280 §2.1 resolution rule: set when `expr` is a direct call of a
   * same-file `behavior` template — the template inlines (its slots, writes
   * sets, and dependency edges join the component's graph, fully analyzable).
   * Absent for opaque JS behavior instances (today's `interaction()`), which
   * stay analyzed at the LLP 0087 opaque boundary. The compiler sets this
   * (resolveBehaviorTemplates); it never travels from hand-authored source.
   */
  template?: string;
}

// ---------------------------------------------------------------------------
// Behavior templates (LLP 0280 §2.1)
// ---------------------------------------------------------------------------

/**
 * LLP 0280 §2.1 — a Contract behavior template: an author-defined, named
 * bundle of `state`/`derive`/`action`/`task` with a required `expose`
 * interface and an optional carried `contract` block. Same-file v1 (LLP 0280
 * OQ5 lean): components in the same `.contract` file instantiate it through
 * the existing `use x = name(args)` spelling; parameters are reactive.
 * Behaviors may not render (no `view`) and may not attach host handler
 * props — `interaction()` explicitly does not migrate (LLP 0280 §2.1 scope).
 * `behavior`/`expose` are new grammar ahead of the B-4 notation freeze
 * review (LLP 0280 OQ4 spelling); they land plainly, like `invariant`.
 */
export interface BehaviorTemplateIR {
  /** camelCase template name (PascalCase is reserved for components). */
  name: string;
  /** Declared parameters; reactive at every instantiation site. */
  params: string[];
  states: StateIR[];
  derives: DeriveIR[];
  actions: ActionIR[];
  tasks: TaskIR[];
  /**
   * Behavior-carried contract clauses (LLP 0278 §6 hand-off): at
   * instantiation these join the instantiating component's clause set,
   * qualified by instance name and tagged with provenance.
   */
  contracts: ContractClauseIR[];
  /** Declared interface: exposed state/derive/action names (required). */
  expose: string[];
  /** Span of the `expose` line (formatter ordering + diagnostics). */
  exposeSpan?: Span;
  span: Span;
}

/**
 * Provenance for a contract clause a behavior template carried into a
 * component's clause set (LLP 0280 §2.1 / LLP 0278 §6): live verification
 * treats the clause as the component's own; provenance names where it came
 * from. Inheritance semantics beyond this minimal join (selector scoping,
 * override rules) are owned by LLP 0278 §6.
 */
export interface ContractClauseProvenanceIR {
  /** Behavior template that declared the clause. */
  behavior: string;
  /** Instantiation binding name (`use <instance> = <behavior>(...)`). */
  instance: string;
}

