export interface ContractSelectorIR {
  /** 'text' | 'button' | 'input' | 'toggle' | 'section' | 'node' */
  kind: string;
  /** Literal label/text argument when present. */
  value?: string;
  testId?: string;
  label?: string;
  role?: string;
}

export type ContractAssertionClauseIR =
  | { kind: 'has'; selector: ContractSelectorIR; span: Span }
  | { kind: 'missing'; selector: ContractSelectorIR; span: Span }
  | { kind: 'count'; selector: ContractSelectorIR; expected: Expr; span: Span }
  | {
      kind: 'state';
      selector: ContractSelectorIR;
      state: 'enabled' | 'disabled' | 'checked' | 'unchecked' | 'visible' | 'hidden';
      span: Span;
    };

export type ContractClauseIR = ContractClauseVariantIR & {
  /**
   * Present only on clauses a behavior template carried into the component
   * (LLP 0280 §2.1); absent on component-authored clauses. Emission passes
   * it through so verification results name their source.
   */
  provenance?: ContractClauseProvenanceIR;
};

export type ContractClauseVariantIR =
  | ContractAssertionClauseIR
  | {
      kind: 'press';
      selector: ContractSelectorIR;
      action?: string;
      navigate?: Expr;
      expectedRedirects?: Expr[];
      alternates?: Expr[];
      expects?: ContractAssertionClauseIR[];
      span: Span;
    }
  | {
      kind: 'navigate';
      target: Expr;
      expectedRedirects?: Expr[];
      alternates?: Expr[];
      span: Span;
    }
  | { kind: 'exits'; targets: Expr[]; only: boolean; span: Span }
  | {
      kind: 'change';
      selector: ContractSelectorIR;
      action: string;
      expects?: ContractAssertionClauseIR[];
      span: Span;
    }
  | { kind: 'when'; test: Expr; clause: ContractClauseIR; span: Span }
  | { kind: 'action-writes'; action: string; writes: string[]; span: Span }
  | { kind: 'derive-depends'; derive: string; deps: string[]; span: Span }
  /**
   * LLP 0278 §4 mode 1 — a passive invariant: an assertion clause
   * (optionally `when`-guarded) quantified over every settled flush. The
   * runtime checks it in dev after each flush; the verifier checks it once
   * per run. `invariant` is new grammar ahead of the B-4 notation freeze
   * review; the spelling (`invariant` vs `always`/`never`) is LLP 0278 OQ1.
   */
  | { kind: 'invariant'; clause: ContractClauseIR; span: Span };

