// @system @ref LLP 0082 — Contract v0 reactive core.
//
// Fine-grained signals with the 0082 scheduling contract: state writes mark
// bindings dirty, dirty bindings coalesce, a single microtask flush updates
// derived values and view subscribers, and one commit closes the batch
// (multiple synchronous writes -> one render/commit wave).

import { reportContractRuntimeError } from './error-locus-runtime.js';
import {
  CONTRACT_DEVELOPMENT,
  CONTRACT_PRODUCTION,
} from './build-mode.js';
import {
  beginSignalsEffectCause,
  currentSignalsCausalContext,
  endSignalsEffectCause,
  propagateSignalsInvalidation,
  recordSignalsComputed,
  recordSignalsComputedInvalidation,
  recordSignalsEffectSkipped,
  recordSignalsWrite,
  registerSignalsCore,
  registerSignalsEffect,
  resetAllSignalsIntrospectionForTests,
  resetSignalsIntrospectionForTests,
  setSignalsIntrospectionEnabled,
  signalsIntrospectionEnabled,
  signalsReactiveChurn,
  snapshotSignalsReactiveGraph,
  unregisterSignalsCore,
  unregisterSignalsEffect,
  whyDidSignalsNodeUpdate,
} from './signals-introspection-runtime.js';

// @system @ref LLP 0192#non-goals — production builds retain no reactive
// introspection graph. Vite replaces the shared production authority before
// tree-shaking; a non-Vite host consumes the fail-closed fallback below.
declare const __EXACT_CONTRACT_PRODUCTION__: boolean;

// Keep the shared authority visible at this hot module's call sites. Rollup
// cannot always propagate an imported boolean far enough to erase the
// allocation-free introspection bridge; the plugin replaces this identifier
// with a literal before tree-shaking.
const CONTRACT_SIGNALS_PRODUCTION =
  typeof __EXACT_CONTRACT_PRODUCTION__ !== 'undefined'
    ? __EXACT_CONTRACT_PRODUCTION__
    : CONTRACT_PRODUCTION;
// The diagnostics gate must reference the define DIRECTLY: the Hermes
// pipeline's Babel pass lowers const to var before the bundler's optimizer
// runs, so a boolean routed through another binding
// (`!CONTRACT_SIGNALS_PRODUCTION && …`) survives as a runtime expression
// and Hermes -O cannot fold cross-slot loads — the update-economy seams
// then leak into production bytecode (contract-update-economy check). With
// the define inline, the whole expression collapses to a literal before
// Babel ever sees it.
const CONTRACT_SIGNALS_DIAGNOSTICS =
  (typeof __EXACT_CONTRACT_PRODUCTION__ !== 'undefined'
    ? !__EXACT_CONTRACT_PRODUCTION__
    : !CONTRACT_PRODUCTION) && CONTRACT_DEVELOPMENT;

export interface ReadonlySignal<T> {
  get(): T;
}

export interface Signal<T> extends ReadonlySignal<T> {
  set(value: T): void;
  peek(): T;
  dispose(): void;
  observerCount(): number;
  /**
   * Notify observers after an in-place mutation of the held value. `set()`
   * equality-skips same-reference writes (Object.is), so state whose object
   * identity is unchanged needs an explicit version bump + notify.
   */
  touch(): void;
}

/** @internal Structural seam consumed by the dev-only introspection module. */
export interface Computation {
  execute(force?: boolean): void;
  invalidate(): void;
  deps: Set<SignalCore<unknown>>;
  seenVersions: Map<SignalCore<unknown>, number>;
  readHeight: number;
  disposed: boolean;
  debugCore?(): SignalCore<unknown>;
  debugState?(): ComputationState;
}

/** @internal Structural seam consumed by the dev-only introspection module. */
export interface SignalCore<T> {
  value: T;
  version: number;
  height: number;
  producer?: Computation & {
    settle(): void;
    debugCore(): SignalCore<unknown>;
    debugState(): ComputationState;
  };
  observers: Set<Computation>;
  onNoObservers?: () => void;
}

let currentComputation: Computation | null = null;
let batchDepth = 0;
let nextVersion = 1;
let nextCreationOrder = 1;

export type ComputationState = 'clean' | 'check' | 'dirty';

export interface ReactiveChurnSnapshot {
  wave: number;
  effectRuns: number;
  skippedEffects: number;
  computedRecomputes: number;
  cascadePasses: number;
  nodes?: ReactiveNodeChurnSnapshot[];
}

/**
 * Dev-only churn joined to renderer commits made by one settled reactive wave.
 *
 * The counters describe the whole wave, not an arbitrary slice between roots.
 * A wave can commit more than one mounted root, so consumers must deduplicate
 * totals by `wave` rather than summing this record once per renderer commit.
 */
export interface ReactiveCommitChurnSnapshot {
  version: 1;
  scope: 'reactive-wave';
  wave: number;
  effectRuns: number;
  skippedEffects: number;
  computedRecomputes: number;
  freshEqualComputedResults: number;
  cascadePasses: number;
}

export interface ReactiveNodeChurnSnapshot {
  nodeId: string;
  kind: ReactiveNodeKind;
  recomputes: number;
  effectRuns: number;
  skippedEffects: number;
  writes: number;
}

export type ReactiveNodeKind = 'signal' | 'computed' | 'effect';

export type ReactiveNodeState = 'clean' | 'check' | 'dirty' | 'disposed';

/** Compiler-authored provenance for a reactive node (LLP 0192 / ENG-24207). */
export interface ReactiveNodeSource {
  sourcePath?: string;
  component?: string;
  region?: string;
  expression?: string;
  span?: {
    line: number;
    col: number;
    offset?: number;
    len?: number;
  };
}

/** Optional stable identity attached by Contract lowering. */
export interface ReactiveNodeOptions {
  label?: string;
  source?: ReactiveNodeSource;
}

export interface ReactiveNodeSnapshot {
  id: string;
  kind: ReactiveNodeKind;
  label: string;
  source?: ReactiveNodeSource;
  value?: unknown;
  version?: number;
  state?: ReactiveNodeState;
  height?: number;
  readHeight?: number;
  observerCount: number;
  depCount: number;
  disposed: boolean;
  churn: ReactiveNodeChurnSnapshot;
}

export interface ReactiveEdgeSnapshot {
  from: string;
  to: string;
}

export interface ReactiveGraphSnapshot {
  schemaVersion: 0;
  wave: number;
  nodes: ReactiveNodeSnapshot[];
  edges: ReactiveEdgeSnapshot[];
}

export type ReactiveCauseKind = 'write' | 'invalidate' | 'recompute' | 'effect';

export interface ReactiveCauseHop {
  kind: ReactiveCauseKind;
  wave: number;
  nodeId: string;
  from?: string;
  value?: unknown;
  previous?: unknown;
  /** Recompute output advanced under Object.is (absent on non-recompute hops). */
  changed?: boolean;
  /** A fresh result was bounded-value-equal or retained by authored memo policy. */
  freshEqual?: boolean;
}

export interface ReactiveCauseTrace {
  nodeId: string;
  wave: number;
  /** Deterministic primary path, retained for the LLP 0192 v0 API. */
  hops: ReactiveCauseHop[];
  /** Every distinct same-wave path under fan-in, sorted by source creation. */
  traces: ReactiveCauseHop[][];
  /** First changed nodes for the paths, deduplicated and deterministically sorted. */
  topSources: ReactiveCauseSource[];
  truncated: boolean;
}

export interface ReactiveCauseSource {
  nodeId: string;
  kind: ReactiveNodeKind;
  label: string;
  source?: ReactiveNodeSource;
  /** The source allocated bounded-value-equal data or hit an authored memo policy. */
  freshEqual?: boolean;
}

/** Generic dev carrier structurally consumed by host renderers. */
export interface ReactiveCausalContext {
  version: 1;
  wave: number;
  nodeId: string;
  label: string;
  source?: ReactiveNodeSource;
  topSources: ReactiveCauseSource[];
  truncated: boolean;
}

const reactiveChurnState: ReactiveChurnSnapshot = {
  wave: 0,
  effectRuns: 0,
  skippedEffects: 0,
  computedRecomputes: 0,
  cascadePasses: 0,
};

// Read and written only inside production-foldable update-economy branches.
// Keeping it separate from public reactiveChurnState prevents the dev metric
// from adding a field or increment to ordinary production introspection.
let updateEconomyFreshEqualComputedResults = 0;
let updateEconomyMemoHitComputations = new WeakSet<Computation>();

/** @internal Called only by the opt-in derive memo runtime. */
export function _recordUpdateEconomyMemoHit(): void {
  if (!CONTRACT_SIGNALS_DIAGNOSTICS) {
    return;
  }
  if (
    typeof (globalThis as typeof globalThis & {
      __exactUpdateEconomy?: { getReport?: unknown };
    }).__exactUpdateEconomy?.getReport !== 'function' ||
    !signalsIntrospectionEnabled() ||
    !(currentComputation instanceof ComputedImpl) ||
    updateEconomyMemoHitComputations.has(currentComputation)
  ) {
    return;
  }
  updateEconomyMemoHitComputations.add(currentComputation);
  updateEconomyFreshEqualComputedResults += 1;
}

/** Cheap mount-time gate for compiler-authored diagnostic metadata. */
export function isReactiveIntrospectionEnabled(): boolean {
  return !CONTRACT_SIGNALS_PRODUCTION && signalsIntrospectionEnabled();
}

/**
 * Force reactive introspection recording on/off (LLP 0192). `null` restores the
 * dev-mode default. Disabling clears accumulated cause/churn state so a
 * production or perf-sensitive surface pays neither the per-write recording cost
 * nor retains the reactive graph in memory.
 */
export function setReactiveIntrospectionEnabled(enabled: boolean | null): void {
  if (!CONTRACT_SIGNALS_PRODUCTION) setSignalsIntrospectionEnabled(enabled);
}

function currentReactiveWave(): number {
  return reactiveChurnState.wave + (queueState(currentReactiveQueueOwner).flushing ? 0 : 1);
}

/**
 * LLP 0284 §2.6 — the wave identity currently-batching writes will settle in
 * (during a flush, the flushing wave itself). `MutationReceipt.
 * optimisticWaveId` derives from this at `mutate()` entry: provider mutate
 * calls run synchronously inside the action body, so this is the flush that
 * applies the action's optimistic writes.
 */
export function reactiveSettlingWave(): number {
  return currentReactiveWave();
}

/**
 * ENG-23197 — cheap accessor for the committed wave counter. Hot paths that
 * only need the wave number (every Contract action invocation logs one) must
 * use this instead of `reactiveChurn()`, which snapshots the ENTIRE reactive
 * graph (O(N log N) walk + one allocation per signal/computed/effect in the
 * whole mounted app) just to carry this same field.
 */
export function reactiveCurrentWave(): number {
  return reactiveChurnState.wave;
}

const MAX_UPDATE_ECONOMY_EQUALITY_VISITS = 2_048;

/**
 * Conservative dev-only detector for the RFC 0052 allocation-churn shape:
 * Object.is changed, but bounded plain array/record data did not. It never
 * invokes authored accessors and treats cycles, custom prototypes, symbols,
 * sparse arrays, and budget exhaustion as unequal.
 */
function updateEconomyFreshValuesEqual(left: unknown, right: unknown): boolean {
  const budget = { remaining: MAX_UPDATE_ECONOMY_EQUALITY_VISITS };
  const activeLeft = new WeakSet<object>();
  const activeRight = new WeakSet<object>();
  const visit = (before: unknown, after: unknown): boolean => {
    if (budget.remaining <= 0) return false;
    budget.remaining -= 1;
    if (
      typeof before !== 'object' || before === null ||
      typeof after !== 'object' || after === null
    ) {
      return (
        Object.is(before, after) &&
        (before == null ||
          typeof before === 'string' ||
          typeof before === 'number' ||
          typeof before === 'boolean')
      );
    }
    if (activeLeft.has(before) || activeRight.has(after)) return false;
    activeLeft.add(before);
    activeRight.add(after);
    try {
      const beforeArray = Array.isArray(before);
      if (beforeArray !== Array.isArray(after)) return false;
      if (beforeArray) {
        if (
          Object.getPrototypeOf(before) !== Array.prototype ||
          Object.getPrototypeOf(after) !== Array.prototype ||
          Object.getOwnPropertySymbols(before).length > 0 ||
          Object.getOwnPropertySymbols(after).length > 0
        ) {
          return false;
        }
        const beforeValues = before as readonly unknown[];
        const afterValues = after as readonly unknown[];
        if (
          beforeValues.length !== afterValues.length ||
          beforeValues.length > budget.remaining
        ) {
          return false;
        }
        const beforeNames = Object.getOwnPropertyNames(beforeValues);
        const afterNames = Object.getOwnPropertyNames(afterValues);
        if (
          beforeNames.length !== beforeValues.length + 1 ||
          afterNames.length !== afterValues.length + 1
        ) {
          return false;
        }
        for (let index = 0; index < beforeValues.length; index += 1) {
          const key = String(index);
          const beforeDescriptor = Object.getOwnPropertyDescriptor(beforeValues, key);
          const afterDescriptor = Object.getOwnPropertyDescriptor(afterValues, key);
          if (
            !beforeDescriptor || !afterDescriptor ||
            !('value' in beforeDescriptor) || !('value' in afterDescriptor) ||
            beforeDescriptor.enumerable !== afterDescriptor.enumerable ||
            beforeDescriptor.configurable !== afterDescriptor.configurable ||
            beforeDescriptor.writable !== afterDescriptor.writable ||
            !visit(beforeDescriptor.value, afterDescriptor.value)
          ) {
            return false;
          }
        }
        const beforeLength = Object.getOwnPropertyDescriptor(beforeValues, 'length');
        const afterLength = Object.getOwnPropertyDescriptor(afterValues, 'length');
        if (
          !beforeLength || !afterLength ||
          !('value' in beforeLength) || !('value' in afterLength) ||
          beforeLength.enumerable !== afterLength.enumerable ||
          beforeLength.configurable !== afterLength.configurable ||
          beforeLength.writable !== afterLength.writable
        ) {
          return false;
        }
        return true;
      }

      const beforePrototype = Object.getPrototypeOf(before);
      if (
        beforePrototype !== Object.getPrototypeOf(after) ||
        (beforePrototype !== Object.prototype && beforePrototype !== null) ||
        Object.getOwnPropertySymbols(before).length > 0 ||
        Object.getOwnPropertySymbols(after).length > 0
      ) {
        return false;
      }
      const beforeRecord = before as Readonly<Record<string, unknown>>;
      const afterRecord = after as Readonly<Record<string, unknown>>;
      const beforeKeys = Object.getOwnPropertyNames(beforeRecord);
      const afterKeys = Object.getOwnPropertyNames(afterRecord);
      if (
        beforeKeys.length !== afterKeys.length ||
        beforeKeys.length > budget.remaining
      ) {
        return false;
      }
      for (const key of beforeKeys) {
        if (!Object.prototype.hasOwnProperty.call(afterRecord, key)) return false;
        const beforeDescriptor = Object.getOwnPropertyDescriptor(beforeRecord, key);
        const afterDescriptor = Object.getOwnPropertyDescriptor(afterRecord, key);
        if (
          !beforeDescriptor || !afterDescriptor ||
          !('value' in beforeDescriptor) || !('value' in afterDescriptor) ||
          beforeDescriptor.enumerable !== afterDescriptor.enumerable ||
          beforeDescriptor.configurable !== afterDescriptor.configurable ||
          beforeDescriptor.writable !== afterDescriptor.writable ||
          !visit(beforeDescriptor.value, afterDescriptor.value)
        ) {
          return false;
        }
      }
      return true;
    } finally {
      activeLeft.delete(before);
      activeRight.delete(after);
    }
  };
  try {
    return visit(left, right);
  } catch {
    // Revoked/hostile proxies can throw from reflection. Profiling must never
    // turn an otherwise-valid app update into an exception; uncertain means
    // unequal and therefore no allocation-churn claim.
    return false;
  }
}

/** Current authored reactive cause, if an effect is evaluating in dev mode. */
export function currentReactiveCausalContext(): ReactiveCausalContext | null {
  return CONTRACT_SIGNALS_PRODUCTION ? null : currentSignalsCausalContext();
}

/** Opaque owner for one app runtime's fixed-point reactive queue. */
export type ContractReactiveQueueOwner = object;

const DEFAULT_REACTIVE_QUEUE_OWNER: ContractReactiveQueueOwner = Object.freeze({
  kind: 'default-contract-reactive-queue',
});

interface ReactiveQueueState {
  pendingEffects: Set<EffectImpl>;
  flushScheduled: boolean;
  flushing: boolean;
  wave: number;
}

let currentReactiveQueueOwner: ContractReactiveQueueOwner = DEFAULT_REACTIVE_QUEUE_OWNER;
const reactiveQueues = new Map<ContractReactiveQueueOwner, ReactiveQueueState>();
const batchPendingOwners = new Set<ContractReactiveQueueOwner>();
const afterFlushCallbacks = new Set<{
  callback: () => void;
  owner?: ContractReactiveQueueOwner;
}>();

function queueState(owner: ContractReactiveQueueOwner): ReactiveQueueState {
  let state = reactiveQueues.get(owner);
  if (!state) {
    state = { pendingEffects: new Set(), flushScheduled: false, flushing: false, wave: 0 };
    reactiveQueues.set(owner, state);
  }
  return state;
}

export function runWithContractReactiveQueueOwner<T>(
  owner: ContractReactiveQueueOwner,
  fn: () => T,
): T {
  const previous = currentReactiveQueueOwner;
  currentReactiveQueueOwner = owner;
  try {
    return fn();
  } finally {
    currentReactiveQueueOwner = previous;
  }
}

function scheduleFlush(owner: ContractReactiveQueueOwner): void {
  const state = queueState(owner);
  if (batchDepth > 0 || state.flushScheduled) {
    return;
  }
  state.flushScheduled = true;
  queueMicrotask(() => {
    state.flushScheduled = false;
    runPendingEffects(owner);
  });
}

export interface ContractReactiveQueueSnapshot {
  pendingEffects: number;
  flushScheduled: boolean;
  flushing: boolean;
  wave: number;
}

/** Runtime-owned quiescence seam (LLP 0341 §3 / LLP 0342 §2). */
export function contractReactiveQueueSnapshot(
  owner?: ContractReactiveQueueOwner,
): ContractReactiveQueueSnapshot {
  if (!owner) {
    const states = [...reactiveQueues.values()];
    return {
      pendingEffects: states.reduce((sum, state) => sum + state.pendingEffects.size, 0),
      flushScheduled: states.some((state) => state.flushScheduled),
      flushing: states.some((state) => state.flushing),
      wave: reactiveChurnState.wave,
    };
  }
  const state = queueState(owner);
  return {
    pendingEffects: state.pendingEffects.size,
    flushScheduled: state.flushScheduled,
    flushing: state.flushing,
    wave: state.wave,
  };
}

/** Synchronously drain currently actionable reactive work. */
export function drainContractReactiveQueue(owner?: ContractReactiveQueueOwner): number {
  if (!owner) {
    let drained = 0;
    for (const queueOwner of [...reactiveQueues.keys()]) drained += drainContractReactiveQueue(queueOwner);
    return drained;
  }
  const state = queueState(owner);
  const before = state.pendingEffects.size;
  if (batchDepth === 0 && !state.flushing && before > 0) runPendingEffects(owner);
  return before;
}

function runPendingEffects(owner: ContractReactiveQueueOwner): void {
  const state = queueState(owner);
  // Re-entrant calls (a batch() inside an executing effect, e.g. resource
  // settlement) defer to the outer drain loop, which picks up their newly
  // enqueued effects — preserving one commit per wave.
  if (state.flushing) {
    return;
  }
  // A stray microtask after a synchronous batch drain has nothing to do; in
  // particular it must not re-fire the afterFlush (commit) callbacks.
  if (state.pendingEffects.size === 0) {
    return;
  }
  // The update-economy reporter is installed only on explicit development
  // profiling runs. Keep its global lookup and the otherwise-redundant
  // introspectionEnabled() call behind the production-foldable Vite dev gate
  // (plus Bun's test mode); ordinary dev runs without a reporter avoid the
  // snapshots too.
  let recordCommitChurn = false;
  if (CONTRACT_SIGNALS_DIAGNOSTICS) {
    recordCommitChurn =
      typeof (globalThis as typeof globalThis & {
        __exactUpdateEconomy?: { getReport?: unknown };
      }).__exactUpdateEconomy?.getReport === 'function' &&
      signalsIntrospectionEnabled();
  }
  const churnAtWaveStart = recordCommitChurn
    ? {
        effectRuns: reactiveChurnState.effectRuns,
        skippedEffects: reactiveChurnState.skippedEffects,
        computedRecomputes: reactiveChurnState.computedRecomputes,
        freshEqualComputedResults: updateEconomyFreshEqualComputedResults,
        cascadePasses: reactiveChurnState.cascadePasses,
      }
    : null;
  state.flushing = true;
  const errors: unknown[] = [];
  try {
    // Effects can enqueue more effects (e.g. region remounts); drain fully,
    // then notify commit listeners exactly once.
    let guard = 0;
    reactiveChurnState.wave += 1;
    state.wave += 1;
    while (state.pendingEffects.size > 0) {
      if (guard++ > 10_000) {
        throw new Error('[contract] reactive flush did not settle (possible infinite update loop)');
      }
      reactiveChurnState.cascadePasses += 1;
      const batch = [...state.pendingEffects].sort((a, b) => {
        const height = a.readHeight - b.readHeight;
        return height !== 0 ? height : a.creationOrder - b.creationOrder;
      });
      state.pendingEffects.clear();
      for (const effect of batch) {
        if (!effect.disposed) {
          try {
            runWithContractReactiveQueueOwner(owner, () => effect.execute());
          } catch (error) {
            errors.push(error);
          }
        }
      }
    }
  } finally {
    state.flushing = false;
  }
  // @system @ref LLP 0330 §4 — renderer
  // commits observe one settled, glitch-free wave. The commit carrier is
  // dev-only and separate from the causal-context carrier so production
  // builds can erase the whole update-economy seam. It lets reporting join
  // reactive work to the commit without a Contract -> renderer dependency or
  // duplicated whole-wave counts in multi-root aggregate totals.
  const commitChurnRuntime = recordCommitChurn && signalsIntrospectionEnabled()
    ? globalThis as typeof globalThis & {
        __exactReactiveWaveChurn?: ReactiveCommitChurnSnapshot;
      }
    : null;
  const previousCommitChurn = commitChurnRuntime?.__exactReactiveWaveChurn;
  if (commitChurnRuntime && churnAtWaveStart) {
    commitChurnRuntime.__exactReactiveWaveChurn = {
      version: 1,
      scope: 'reactive-wave',
      wave: reactiveChurnState.wave,
      effectRuns: reactiveChurnState.effectRuns - churnAtWaveStart.effectRuns,
      skippedEffects:
        reactiveChurnState.skippedEffects - churnAtWaveStart.skippedEffects,
      computedRecomputes:
        reactiveChurnState.computedRecomputes - churnAtWaveStart.computedRecomputes,
      freshEqualComputedResults:
        updateEconomyFreshEqualComputedResults -
        churnAtWaveStart.freshEqualComputedResults,
      cascadePasses:
        reactiveChurnState.cascadePasses - churnAtWaveStart.cascadePasses,
    };
  }
  try {
    for (const entry of [...afterFlushCallbacks]) {
      if (!entry.owner || entry.owner === owner) entry.callback();
    }
  } finally {
    if (commitChurnRuntime) {
      if (previousCommitChurn === undefined) {
        delete commitChurnRuntime.__exactReactiveWaveChurn;
      } else {
        commitChurnRuntime.__exactReactiveWaveChurn = previousCommitChurn;
      }
    }
  }
  if (errors.length > 0) {
    // ENG-22443: effect errors are isolated per effect (the flush completed
    // and committed — surviving UI keeps its last-good state); report each
    // with its authored Contract locus (dev-only, deduped per Error) before
    // rethrowing the first so failures stay loud.
    for (const error of errors) {
      reportContractRuntimeError(error);
    }
    const first = errors[0];
    if (first instanceof Error) {
      throw first;
    }
    throw new Error(String(first));
  }
}

/** Registers a callback that runs once after each effect flush (commit point). */
export function onFlush(
  callback: () => void,
  owner?: ContractReactiveQueueOwner,
): () => void {
  const entry = { callback, ...(owner ? { owner } : {}) };
  afterFlushCallbacks.add(entry);
  return () => {
    afterFlushCallbacks.delete(entry);
  };
}

export function batch<T>(fn: () => T): T {
  batchDepth += 1;
  try {
    return fn();
  } finally {
    if (batchDepth === 1) {
      (globalThis as { __exactContractOuterBatchExit?: () => void })
        .__exactContractOuterBatchExit?.();
    }
    batchDepth -= 1;
    if (batchDepth === 0) {
      // Drain only queues dirtied by this batch. This preserves synchronous
      // event→commit latency without sweeping unrelated runtimes that already
      // had pending work.
      const owners = [...batchPendingOwners];
      batchPendingOwners.clear();
      for (const owner of owners) {
        if (queueState(owner).pendingEffects.size > 0) runPendingEffects(owner);
      }
    }
  }
}

/** Tiny conditional-extension seam; substantial staging stays off this graph. */
export function contractBatchActive(): boolean { return batchDepth > 0; }

export function untrack<T>(fn: () => T): T {
  const previous = currentComputation;
  currentComputation = null;
  try {
    return fn();
  } finally {
    currentComputation = previous;
  }
}

function track(core: SignalCore<unknown>): void {
  if (currentComputation) {
    core.observers.add(currentComputation);
    currentComputation.deps.add(core);
    currentComputation.seenVersions.set(core, core.version);
    currentComputation.readHeight = Math.max(currentComputation.readHeight, core.height + 1);
  }
}

function notify(core: SignalCore<unknown>): void {
  for (const observer of [...core.observers]) {
    if (!CONTRACT_SIGNALS_PRODUCTION) {
      propagateSignalsInvalidation(core, observer, currentReactiveWave());
    }
    observer.invalidate();
  }
  for (const [owner, state] of reactiveQueues) {
    if (state.pendingEffects.size > 0) scheduleFlush(owner);
  }
}

export function signal<T>(initial: T, options?: ReactiveNodeOptions & {
  onNoObservers?: () => void;
}): Signal<T> {
  const core: SignalCore<T> = { value: initial, version: nextVersion++, height: 0,
    observers: new Set(), onNoObservers: options?.onNoObservers };
  if (!CONTRACT_SIGNALS_PRODUCTION) registerSignalsCore(core, 'signal', options);
  let disposed = false;
  const dispose = (): void => {
    if (disposed) return;
    disposed = true;
    core.observers.clear();
    if (!CONTRACT_SIGNALS_PRODUCTION) {
      unregisterSignalsCore(core as SignalCore<unknown>);
    }
  };
  currentOwner?.register(dispose);
  return {
    get(): T {
      track(core as SignalCore<unknown>);
      return core.value;
    },
    peek(): T {
      return core.value;
    },
    dispose,
    observerCount: () => core.observers.size,
    set(value: T): void {
      if (Object.is(core.value, value)) {
        return;
      }
      const previous = core.value;
      core.value = value;
      core.version = nextVersion++;
      // Introspection recording (incl. the value deep-clone) is dev-only and
      // skipped wholesale in production — see setReactiveIntrospectionEnabled.
      if (!CONTRACT_SIGNALS_PRODUCTION && signalsIntrospectionEnabled()) {
        recordSignalsWrite(
          core as SignalCore<unknown>,
          previous,
          value,
          currentReactiveWave(),
        );
      }
      notify(core as SignalCore<unknown>);
    },
    touch(): void {
      core.version = nextVersion++;
      if (!CONTRACT_SIGNALS_PRODUCTION && signalsIntrospectionEnabled()) {
        recordSignalsWrite(
          core as SignalCore<unknown>,
          core.value,
          core.value,
          currentReactiveWave(),
        );
      }
      notify(core as SignalCore<unknown>);
    },
  };
}

class ComputedImpl<T> implements Computation {
  deps = new Set<SignalCore<unknown>>();
  seenVersions = new Map<SignalCore<unknown>, number>();
  readHeight = 0;
  disposed = false;
  private state: ComputationState = 'dirty';
  private core: SignalCore<T>;

  constructor(private readonly fn: () => T, options?: ReactiveNodeOptions) {
    this.core = {
      value: undefined as T,
      version: nextVersion++,
      height: 1,
      producer: this,
      observers: new Set(),
    };
    if (!CONTRACT_SIGNALS_PRODUCTION) {
      registerSignalsCore(this.core, 'computed', options);
    }
  }

  debugCore(): SignalCore<unknown> {
    return this.core as SignalCore<unknown>;
  }

  debugState(): ComputationState {
    return this.disposed ? 'dirty' : this.state;
  }

  get(): T {
    if (this.state !== 'clean' && !this.disposed) {
      this.settle();
    }
    track(this.core as SignalCore<unknown>);
    return this.core.value;
  }

  settle(): void {
    if (this.disposed || this.state === 'clean') {
      return;
    }
    if (this.state === 'dirty' || this.depsChanged()) {
      this.recompute();
    } else {
      this.state = 'clean';
    }
  }

  private depsChanged(): boolean {
    for (const dep of this.deps) {
      settleCore(dep);
      if (dep.version !== this.seenVersions.get(dep)) {
        return true;
      }
    }
    return false;
  }

  private recompute(): void {
    const recordingCause =
      !CONTRACT_SIGNALS_PRODUCTION && signalsIntrospectionEnabled();
    const wave = currentReactiveWave();
    this.cleanupDeps();
    const previous = currentComputation;
    currentComputation = this;
    this.readHeight = 0;
    reactiveChurnState.computedRecomputes += 1;
    let changed = false;
    let freshEqual = false;
    try {
      const next = this.fn();
      this.state = 'clean';
      changed = !Object.is(next, this.core.value);
      if (CONTRACT_SIGNALS_DIAGNOSTICS) {
        const memoFreshEqual = updateEconomyMemoHitComputations.delete(this);
        const ordinaryFreshEqual =
          changed &&
          typeof (globalThis as typeof globalThis & {
            __exactUpdateEconomy?: { getReport?: unknown };
          }).__exactUpdateEconomy?.getReport === 'function' &&
          signalsIntrospectionEnabled() &&
          updateEconomyFreshValuesEqual(this.core.value, next);
        freshEqual = memoFreshEqual || ordinaryFreshEqual;
        if (ordinaryFreshEqual) {
          updateEconomyFreshEqualComputedResults += 1;
        }
      }
      if (changed) {
        this.core.value = next;
        this.core.version = nextVersion++;
      }
      this.core.height = this.readHeight;
    } finally {
      // A comparator or later evaluator step can throw after reporting a hit;
      // never let that mark leak into the next recompute.
      if (CONTRACT_SIGNALS_DIAGNOSTICS) {
        const memoFreshEqual = updateEconomyMemoHitComputations.delete(this);
        freshEqual ||= memoFreshEqual;
      }
      if (recordingCause) {
        recordSignalsComputed(
          this,
          this.core as SignalCore<unknown>,
          changed,
          freshEqual,
          wave,
        );
      }
      currentComputation = previous;
    }
  }

  execute(): void {
    // Computeds are pull-based; nothing runs at flush time.
  }

  invalidate(): void {
    if (this.state === 'dirty') {
      return;
    }
    this.state = 'dirty';
    if (!CONTRACT_SIGNALS_PRODUCTION && signalsIntrospectionEnabled()) {
      recordSignalsComputedInvalidation(
        this,
        this.core as SignalCore<unknown>,
      );
    }
    // Direct dependency changed; downstream observers need only check whether
    // this computed's value version changes after it settles.
    for (const observer of [...this.core.observers]) {
      if (!CONTRACT_SIGNALS_PRODUCTION) {
        propagateSignalsInvalidation(
          this.core as SignalCore<unknown>,
          observer,
          currentReactiveWave(),
        );
      }
      markCheck(observer);
    }
  }

  markCheck(): void {
    if (this.state !== 'clean') {
      return;
    }
    this.state = 'check';
    for (const observer of [...this.core.observers]) {
      if (!CONTRACT_SIGNALS_PRODUCTION) {
        propagateSignalsInvalidation(
          this.core as SignalCore<unknown>,
          observer,
          currentReactiveWave(),
        );
      }
      markCheck(observer);
    }
  }

  dispose(): void {
    this.disposed = true;
    this.cleanupDeps();
    this.core.observers.clear();
    if (!CONTRACT_SIGNALS_PRODUCTION) {
      unregisterSignalsCore(this.core as SignalCore<unknown>);
    }
  }

  private cleanupDeps(): void {
    for (const dep of this.deps) {
      dep.observers.delete(this);
      if (dep.observers.size === 0) dep.onNoObservers?.();
    }
    this.deps.clear();
    this.seenVersions.clear();
  }
}

export interface Computed<T> extends ReadonlySignal<T> {
  dispose(): void;
}

export function computed<T>(fn: () => T, options?: ReactiveNodeOptions): Computed<T> {
  const impl = new ComputedImpl(fn, options);
  return {
    get: () => impl.get(),
    dispose: () => impl.dispose(),
  };
}

class EffectImpl implements Computation {
  deps = new Set<SignalCore<unknown>>();
  seenVersions = new Map<SignalCore<unknown>, number>();
  readHeight = 0;
  disposed = false;
  readonly creationOrder = nextCreationOrder++;
  readonly queueOwner = currentReactiveQueueOwner;

  constructor(private readonly fn: () => void, options?: ReactiveNodeOptions) {
    if (!CONTRACT_SIGNALS_PRODUCTION) registerSignalsEffect(this, options);
  }

  execute(force = false): void {
    if (this.disposed) {
      return;
    }
    if (!force && !this.depsChanged()) {
      reactiveChurnState.skippedEffects += 1;
      if (!CONTRACT_SIGNALS_PRODUCTION && signalsIntrospectionEnabled()) {
        recordSignalsEffectSkipped(this, currentReactiveWave());
      }
      return;
    }
    const wave = currentReactiveWave();
    const recordingCause =
      !CONTRACT_SIGNALS_PRODUCTION && signalsIntrospectionEnabled();
    const causeToken = recordingCause
      ? beginSignalsEffectCause(this, force, wave)
      : null;
    this.cleanupDeps();
    const previous = currentComputation;
    currentComputation = this;
    this.readHeight = 0;
    reactiveChurnState.effectRuns += 1;
    try {
      this.fn();
    } finally {
      if (recordingCause) endSignalsEffectCause(causeToken);
      currentComputation = previous;
    }
  }

  invalidate(): void {
    if (!this.disposed) {
      queueState(this.queueOwner).pendingEffects.add(this);
      if (batchDepth > 0) batchPendingOwners.add(this.queueOwner);
      scheduleFlush(this.queueOwner);
    }
  }

  dispose(): void {
    this.disposed = true;
    this.cleanupDeps();
    queueState(this.queueOwner).pendingEffects.delete(this);
    if (!CONTRACT_SIGNALS_PRODUCTION) unregisterSignalsEffect(this);
  }

  private cleanupDeps(): void {
    for (const dep of this.deps) {
      dep.observers.delete(this);
      if (dep.observers.size === 0) dep.onNoObservers?.();
    }
    this.deps.clear();
    this.seenVersions.clear();
  }

  private depsChanged(): boolean {
    for (const dep of this.deps) {
      settleCore(dep);
      if (dep.version !== this.seenVersions.get(dep)) {
        return true;
      }
    }
    return false;
  }
}

export interface EffectHandle {
  dispose(): void;
}

function handleForEffect(impl: EffectImpl): EffectHandle {
  return {
    dispose: () => impl.dispose(),
  };
}

/** Runs immediately, re-runs on dependency change (coalesced per flush). */
export function effect(fn: () => void, options?: ReactiveNodeOptions): EffectHandle {
  const impl = new EffectImpl(fn, options);
  const handle = handleForEffect(impl);
  try {
    impl.execute(true);
  } catch (error) {
    handle.dispose();
    throw error;
  }
  return handle;
}

function markCheck(computation: Computation): void {
  if (computation.disposed) {
    return;
  }
  if (computation instanceof ComputedImpl) {
    computation.markCheck();
    return;
  }
  computation.invalidate();
}

function settleCore(core: SignalCore<unknown>): void {
  core.producer?.settle();
}

export function snapshotReactiveGraph(): ReactiveGraphSnapshot {
  return snapshotSignalsReactiveGraph(reactiveChurnState.wave);
}

export function whyDidNodeUpdate(nodeId: string): ReactiveCauseTrace | null {
  return whyDidSignalsNodeUpdate(nodeId);
}

export function reactiveChurn(options: { sinceWave?: number } = {}): ReactiveChurnSnapshot {
  return signalsReactiveChurn(reactiveChurnState, options.sinceWave);
}

export function _resetReactiveChurnForTests(): void {
  reactiveChurnState.wave = 0;
  reactiveChurnState.effectRuns = 0;
  reactiveChurnState.skippedEffects = 0;
  reactiveChurnState.computedRecomputes = 0;
  updateEconomyFreshEqualComputedResults = 0;
  updateEconomyMemoHitComputations = new WeakSet<Computation>();
  reactiveChurnState.cascadePasses = 0;
  for (const state of reactiveQueues.values()) state.wave = 0;
  const runtime = globalThis as typeof globalThis & {
    __exactReactiveWaveChurn?: ReactiveCommitChurnSnapshot;
  };
  delete runtime.__exactReactiveWaveChurn;
  resetSignalsIntrospectionForTests();
}

export function _resetReactiveIntrospectionForTests(): void {
  _resetReactiveChurnForTests();
  resetAllSignalsIntrospectionForTests();
  reactiveQueues.clear();
  currentReactiveQueueOwner = DEFAULT_REACTIVE_QUEUE_OWNER;
}

// ---------------------------------------------------------------------------
// Owners (disposal scopes; LLP 0155 A4's affine-disposal substrate)
// ---------------------------------------------------------------------------

export interface Owner {
  register(dispose: () => void): void;
  dispose(): void;
}

let currentOwner: Owner | null = null;

export function createOwner(): Owner {
  const disposables: Array<() => void> = [];
  let disposed = false;
  return {
    register(dispose: () => void): void {
      if (disposed) {
        dispose();
        return;
      }
      disposables.push(dispose);
    },
    dispose(): void {
      if (disposed) {
        return;
      }
      disposed = true;
      const errors: unknown[] = [];
      // Dispose in reverse creation order.
      for (let i = disposables.length - 1; i >= 0; i -= 1) {
        try {
          disposables[i]();
        } catch (error) {
          errors.push(error);
        }
      }
      disposables.length = 0;
      if (errors.length === 1) {
        throw errors[0];
      }
      if (errors.length > 1) {
        throw new AggregateError(errors, 'multiple Contract owner disposers failed');
      }
    },
  };
}

export function getOwner(): Owner | null {
  return currentOwner;
}

export function runWithOwner<T>(owner: Owner | null, fn: () => T): T {
  const previous = currentOwner;
  currentOwner = owner;
  try {
    return fn();
  } finally {
    currentOwner = previous;
  }
}

/** effect() that registers its disposal with the current owner. */
export function ownedEffect(fn: () => void, options?: ReactiveNodeOptions): EffectHandle {
  const owner = currentOwner;
  const impl = new EffectImpl(fn, options);
  const handle = handleForEffect(impl);
  try {
    impl.execute(true);
  } catch (error) {
    if (owner) {
      owner.register(() => handle.dispose());
    } else {
      handle.dispose();
    }
    throw error;
  }
  owner?.register(() => handle.dispose());
  return handle;
}

export function ownedComputed<T>(fn: () => T, options?: ReactiveNodeOptions): Computed<T> {
  const handle = computed(fn, options);
  currentOwner?.register(() => handle.dispose());
  return handle;
}
