// @system @ref LLP 0393 — Contract video: the always-loaded seam.
//
// This module is imported unconditionally by the Contract runtime, so it must
// stay tiny and engine-free (the motion-scope budget discipline): the
// ~2k-line `@exact/video` engine loads only through
// `runtime/video-production.ts`, which the Vite plugin injects when a module
// actually authors a `video` tag or imports `@exact/contract/video`.

/** Marker value carried by `@exact/contract/video` player behaviors. */
export const CONTRACT_VIDEO_BEHAVIOR_KIND = 'video-player-behavior';

export interface ContractVideoPlayerBehavior {
  readonly __exactContractVideoKind: typeof CONTRACT_VIDEO_BEHAVIOR_KIND;
  /** The engine player handle owned by the behavior (opaque to the runtime). */
  readonly __player: unknown;
}

export function isVideoPlayerBehavior(
  value: unknown,
): value is ContractVideoPlayerBehavior {
  return (
    typeof value === 'object' &&
    value !== null &&
    (value as { __exactContractVideoKind?: unknown }).__exactContractVideoKind ===
      CONTRACT_VIDEO_BEHAVIOR_KIND
  );
}

/** Creation-time config for a self-owned tag player (LLP 0393 D2/D3). */
export interface ContractVideoCreateConfig {
  source: unknown;
  autoplay?: boolean;
  paused?: boolean;
  muted?: boolean;
  loop?: boolean;
  volume?: number;
  rate?: number;
}

/** The tag-owned view concerns (both modes). */
export interface ContractVideoViewConfig {
  poster?: string;
  objectFit?: string;
  controls?: boolean;
}

/**
 * Event handlers the mount path wires through the engine's subscribe seam.
 * Names match the authored Contract event attrs, not the engine spellings.
 */
export interface ContractVideoEventHandlers {
  ready?: (payload: unknown) => void;
  firstFrame?: () => void;
  play?: () => void;
  pause?: () => void;
  ended?: () => void;
  progress?: (payload: { currentTime: number; duration: number | null }) => void;
  seeked?: (payload: { currentTime: number }) => void;
  error?: (payload: unknown) => void;
  autoplayBlocked?: () => void;
}

/**
 * The engine seam. `runtime/video-production.ts` registers the real
 * `@exact/video`-backed implementation; player handles are opaque here.
 */
export interface ContractVideoEngine {
  createPlayer(config: ContractVideoCreateConfig): unknown;
  destroyPlayer(player: unknown): void;
  playerId(player: unknown): string;
  replaceSource(player: unknown, source: unknown): void;
  setMuted(player: unknown, value: boolean): void;
  setVolume(player: unknown, value: number): void;
  setRate(player: unknown, value: number): void;
  setLoop(player: unknown, value: boolean): void;
  setPaused(player: unknown, value: boolean): void;
  seekTo(player: unknown, seconds: number): void;
  updateViewConfig(player: unknown, config: ContractVideoViewConfig): void;
  serializeViewConfig(config: ContractVideoViewConfig): string;
  subscribe(player: unknown, handlers: ContractVideoEventHandlers): () => void;
  setBoundNativeView(player: unknown, nodeId: number, bound: boolean): void;
}

let registeredEngine: ContractVideoEngine | null = null;

export function registerContractVideoEngine(engine: ContractVideoEngine): void {
  registeredEngine = engine;
}

export function getContractVideoEngine(): ContractVideoEngine | null {
  return registeredEngine;
}
