// @system @ref LLP 0185 S2 — straight-line value-match region construction.

import type { Span, ViewNodeIR } from '../compiler/ir.js';
import {
  runWithContractErrorLocus,
  type ContractErrorLocus,
} from './error-locus-runtime.js';
import {
  isReactiveIntrospectionEnabled,
  ownedEffect,
  untrack,
  type ReactiveNodeOptions,
} from './signals.js';
import type { Scope } from './interpreter.js';
import { mountContractAotViewNodes } from './aot-view-runtime.js';
import {
  createContractBranchRegion,
  type ContractMountViewNodes,
} from './aot-view-region.js';
import type { AnchorFn, HostParent, Mounted, MountEnv } from './view.js';

const VIEW_EVAL = { identFallbackToString: true } as const;
type ContractMatchEvaluator = (scope: Scope, options: typeof VIEW_EVAL) => unknown;

export type ContractAotMatchPlan = readonly [
  subject: ContractMatchEvaluator,
  cases: readonly ContractMatchEvaluator[],
  line: number,
  col: number,
  len: number,
  offset: number,
];

interface ContractMatchCaseBody {
  body: readonly ViewNodeIR[];
}

export function mountContractMatch(
  plan: ContractAotMatchPlan,
  node: ViewNodeIR,
  cases: readonly ContractMatchCaseBody[],
  elseNodes: readonly ViewNodeIR[] | undefined,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  mountNodes: ContractMountViewNodes = mountContractAotViewNodes,
): Mounted {
  const [subject, caseEvaluators, line, col, len, offset] = plan;
  const structuralId = env.ids.get(node) ?? null;
  const span: Span = { line, col, len, offset };
  if (caseEvaluators.length !== cases.length) {
    throw new Error(
      `[contract] compiled match has ${caseEvaluators.length} predicates for ${cases.length} arms`,
    );
  }
  const region = createContractBranchRegion(parent, anchor, env, mountNodes);
  const locus: ContractErrorLocus = {
    component: env.component.name,
    sourcePath: env.component.file.sourcePath,
    region: 'match',
    span,
  };
  ownedEffect(
    () => runWithContractErrorLocus(locus, () => {
      const value = subject(env.scope, VIEW_EVAL);
      const armIndex = caseEvaluators.findIndex((evaluate) =>
        contractMatchEquals(value, evaluate(env.scope, VIEW_EVAL))
      );
      const arm = armIndex >= 0 ? cases[armIndex] : undefined;
      untrack(() => region.swap(
        arm ? `case:${armIndex}` : 'else',
        arm?.body ?? elseNodes ?? [],
      ));
    }),
    matchReactiveOptions(env, structuralId, span),
  );
  return region;
}

function contractMatchEquals(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;
  if (
    (typeof a === 'string' || typeof a === 'number' || typeof a === 'boolean') &&
    (typeof b === 'string' || typeof b === 'number' || typeof b === 'boolean')
  ) {
    return String(a) === String(b);
  }
  return false;
}

function matchReactiveOptions(
  env: MountEnv,
  structuralId: string | null,
  span: Span,
): ReactiveNodeOptions | undefined {
  if (!isReactiveIntrospectionEnabled()) return undefined;
  const id = structuralId ?? `match:${span.line}:${span.col}`;
  return {
    label: `${env.component.name}.view.${id}.match`,
    source: {
      component: env.component.name,
      sourcePath: env.component.file.sourcePath,
      region: 'match',
      span,
    },
  };
}
