// @system @ref LLP 0185 S2 — straight-line snippet-call construction.

import type { ViewNodeIR } from '../compiler/ir.js';
import type { Scope } from './interpreter.js';
import { mountContractAotViewNodes } from './aot-view-runtime.js';
import type { ContractMountViewNodes } from './aot-view-region.js';
import type { AnchorFn, HostParent, Mounted, MountEnv } from './view.js';

const VIEW_EVAL = { identFallbackToString: true } as const;
type ContractSnippetArgEvaluator = (
  scope: Scope,
  options: typeof VIEW_EVAL,
) => unknown;

export type ContractAotSnippetPlan = readonly [
  name: string,
  params: readonly string[],
  args: readonly ContractSnippetArgEvaluator[],
];

export function mountContractSnippet(
  plan: ContractAotSnippetPlan,
  body: readonly ViewNodeIR[] | undefined,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  mountNodes: ContractMountViewNodes = mountContractAotViewNodes,
): Mounted {
  const [name, params, args] = plan;
  if (!body) throw new Error(`[contract] unknown snippet "${name}"`);
  const snippetScope = env.scope.child();
  params.forEach((param, index) => {
    const evaluate = args[index];
    snippetScope.define(param, {
      kind: 'getter',
      get: () => evaluate ? evaluate(env.scope, VIEW_EVAL) : undefined,
    });
  });
  return mountNodes(body, parent, anchor, { ...env, scope: snippetScope });
}
