// @system @ref LLP 0185 S2 — straight-line responsive match region construction.

import type { Span, ViewNodeIR } from '../compiler/ir.js';
import {
  isReactiveIntrospectionEnabled,
  ownedEffect,
  untrack,
  type ReactiveNodeOptions,
} from './signals.js';
import { readContractSizeClass } from './responsive.js';
import { mountContractAotViewNodes } from './aot-view-runtime.js';
import {
  createContractBranchRegion,
  type ContractMountViewNodes,
} from './aot-view-region.js';
import type { AnchorFn, HostParent, Mounted, MountEnv } from './view.js';

export type ContractAotMatchSizePlan = readonly [
  values: readonly string[],
  line: number,
  col: number,
  len: number,
  offset: number,
];

interface ContractMatchSizeCaseBody {
  body: readonly ViewNodeIR[];
}

export function mountContractMatchSize(
  plan: ContractAotMatchSizePlan,
  node: ViewNodeIR,
  cases: readonly ContractMatchSizeCaseBody[],
  elseNodes: readonly ViewNodeIR[] | undefined,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  mountNodes: ContractMountViewNodes = mountContractAotViewNodes,
): Mounted {
  const [values, line, col, len, offset] = plan;
  const structuralId = env.ids.get(node) ?? null;
  const span: Span = { line, col, len, offset };
  if (values.length !== cases.length) {
    throw new Error(
      `[contract] compiled match-size has ${values.length} values for ${cases.length} arms`,
    );
  }
  const region = createContractBranchRegion(parent, anchor, env, mountNodes);
  ownedEffect(
    () => {
      const sizeClass = readContractSizeClass(env.ctx);
      const armIndex = values.indexOf(sizeClass);
      const arm = armIndex >= 0 ? cases[armIndex] : undefined;
      untrack(() => region.swap(
        arm ? sizeClass : 'else',
        arm?.body ?? elseNodes ?? [],
      ));
    },
    matchSizeReactiveOptions(env, structuralId, span),
  );
  return region;
}

function matchSizeReactiveOptions(
  env: MountEnv,
  structuralId: string | null,
  span: Span,
): ReactiveNodeOptions | undefined {
  if (!isReactiveIntrospectionEnabled()) return undefined;
  const id = structuralId ?? `match-size:${span.line}:${span.col}`;
  return {
    label: `${env.component.name}.view.${id}.match-size`,
    source: {
      component: env.component.name,
      sourcePath: env.component.file.sourcePath,
      region: 'match-size',
      span,
    },
  };
}
