// @system @ref LLP 0284 §2.5 / LLP 0373 P1 — optional ephemeral-map
// instantiation. Ordinary components do not retain this provider capability.

import {
  isContractEphemeralHandle,
  type ContractEphemeralHandle,
  type DataConnection,
  type DataSubscription,
} from './data-provider.js';
import {
  decorateContractError,
  type ContractErrorLocus,
} from './error-locus-runtime.js';
import { evalRuntimeExpr } from './execution.js';
import {
  allowStateWrites,
  registerHydrationActivation,
  type ComponentInstance,
} from './instance.js';
import {
  batch,
  ownedEffect,
  runWithOwner,
  signal,
} from './signals.js';
import type { ContractEphemeralsRuntime } from './ephemerals-runtime.js';

export const contractEphemeralsRuntime: ContractEphemeralsRuntime = {
  setup(instance) {
    const { def, scope, owner, ctx } = instance;
    for (const ephemeral of def.ir.ephemerals ?? []) {
      const status = signal<'pending' | 'ready' | 'error'>('pending');
      const entries = signal<readonly unknown[]>([]);
      const connection = signal<DataConnection | undefined>(undefined);
      let subscription: DataSubscription | null = null;
      let generation = 0;
      const locus: ContractErrorLocus = {
        component: def.ir.name,
        sourcePath: def.file.sourcePath,
        region: `ephemeral "${ephemeral.name}"`,
        span: ephemeral.span,
      };

      const subscribe = (): void => {
        const gen = ++generation;
        subscription?.dispose();
        subscription = null;
        batch(() =>
          allowStateWrites(() => {
            status.set('pending');
            entries.set([]);
            connection.set(undefined);
          }),
        );
        let handle: ContractEphemeralHandle | null = null;
        try {
          const candidate = evalRuntimeExpr(ephemeral.expr, scope);
          if (!isContractEphemeralHandle(candidate)) {
            throw new Error(
              `[contract] ephemeral "${ephemeral.name}" initializer did not return a Contract ephemeral handle`,
            );
          }
          handle = candidate;
        } catch (thrown) {
          decorateContractError(thrown, locus);
          console.warn(
            `[contract] ephemeral "${ephemeral.name}" failed to bind`,
            thrown,
          );
          batch(() => allowStateWrites(() => status.set('error')));
          return;
        }
        try {
          const established = handle.subscribe((cell) => {
            if (gen !== generation) return;
            batch(() =>
              allowStateWrites(() => {
                status.set(cell.status);
                entries.set([...cell.entries]);
                connection.set(cell.connection);
              }),
            );
          });
          if (gen !== generation) established.dispose();
          else subscription = established;
        } catch (thrown) {
          decorateContractError(thrown, locus);
          console.warn(
            `[contract] ephemeral "${ephemeral.name}" subscription failed`,
            thrown,
          );
          batch(() => allowStateWrites(() => status.set('error')));
        }
      };

      registerHydrationActivation(
        ctx,
        () => runWithOwner(owner, () => ownedEffect(subscribe)),
        instance.effectScope,
      );
      owner.register(() => subscription?.dispose());
      scope.defineValue(ephemeral.name, {
        get status() {
          return status.get();
        },
        get entries() {
          return entries.get();
        },
        get connection() {
          return connection.get();
        },
      });
    }
  },
};
