import type { ImageDynamicRange } from '../types.js';

const warnings = new Set<string>();

function warn(key: string, message: string): void {
  if (warnings.has(key)) return;
  warnings.add(key);
  console.warn(`[exact-renderer] ${message}`);
}

function isImageDynamicRange(value: unknown): value is ImageDynamicRange {
  return value === 'standard' || value === 'constrained' || value === 'no-limit';
}

/** Canonical public image policy shared by native/full and direct-DOM hosts. */
export function normalizeImageDynamicRange(
  dynamicRange: unknown,
  hdr: unknown,
): ImageDynamicRange | undefined {
  const hasDynamicRange = dynamicRange !== undefined;
  const hasHdr = typeof hdr === 'boolean';

  if (hasHdr) warn('deprecated-hdr', 'image hdr is deprecated; use dynamicRange.');
  if (hasDynamicRange && hasHdr) {
    warn(
      'dynamic-range-conflict',
      'image dynamicRange and hdr were both supplied; a valid dynamicRange wins.',
    );
  }
  if (isImageDynamicRange(dynamicRange)) return dynamicRange;
  if (hasDynamicRange) {
    warn(
      'invalid-dynamic-range',
      `invalid image dynamicRange ${String(dynamicRange)}; expected standard, constrained, or no-limit.`,
    );
  }
  if (hasHdr) return hdr ? 'no-limit' : 'standard';
  return hasDynamicRange ? 'standard' : undefined;
}

export function resetImageDynamicRangeWarningsForTests(): void {
  warnings.clear();
}
