// @system @ref LLP 0328 D1, LLP 0330 §5 (ENG-23894) — the scripted clock +
// seeded rng seam.
//
// Time and randomness enter Contract through explicit builtins (LLP 0087:
// `now()`, `every()`, `after()`, and `Math.random` on the exposed Math
// object). Conformance fixtures pin them by installing a determinism host:
// when installed, every runtime that implements this seam (the TS runtime
// here; `contract-native` per LLP 0328 D1) resolves those builtins against
// the host instead of the ambient engine, so golden traces are reproducible
// across runs, engines, and languages.
//
// Production behavior is unchanged: with no host installed the builtins keep
// their ambient definitions (Date.now, setInterval/setTimeout, Math.random).

export interface ContractDeterminismHost {
  /** Headless replay provenance for the pinned RNG stream, when available. */
  readonly replayRng?: { algorithm: 'mulberry32'; seed: number };
  /** Current virtual time in ms (backs the `now()` builtin). */
  now(): number;
  /** Schedules a repeating timer on the virtual clock (backs `every()`). */
  setInterval(fn: () => void, ms: number): unknown;
  clearInterval(handle: unknown): void;
  /** Schedules a one-shot timer on the virtual clock (backs `after()`). */
  setTimeout(fn: () => void, ms: number): unknown;
  clearTimeout(handle: unknown): void;
  /** Seeded rng in [0, 1) (backs `Math.random` on the Contract Math object). */
  random(context?: ContractRandomReadContext): number;
  /** Optional quiescence seam: count timers deliverable at the current time. */
  dueTimerCount?(): number;
  /** Optional quiescence seam: deliver all timers due at the current time. */
  drainDueTimers?(): number;
}

/** LLP 0330 §5 pinned cross-runtime RNG. */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export interface ContractRandomReadContext {
  siteId: string;
  logicalInstancePath: readonly string[];
}

/**
 * Per-app-runtime determinism authority (LLP 0342 §5). The legacy module
 * functions below proxy one default authority so existing harnesses remain
 * source-compatible, while explicit ContractRuntime instances get isolated
 * host pointers, listeners, clocks, rng streams, and timer registries.
 */
export class ContractDeterminismAuthority {
  private installedHost: ContractDeterminismHost | null = null;
  private readonly listeners = new Set<() => void>();

  install(host: ContractDeterminismHost): () => void {
    const previous = this.installedHost;
    this.installedHost = host;
    this.notify();
    let restored = false;
    return () => {
      if (restored) return;
      restored = true;
      this.installedHost = previous;
      this.notify();
    };
  }

  get(): ContractDeterminismHost | null {
    return this.installedHost;
  }

  subscribe(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  now(): number {
    return this.installedHost?.now() ?? Date.now();
  }

  random(context?: ContractRandomReadContext): number {
    return this.installedHost?.random(context) ?? Math.random();
  }

  dueTimerCount(): number {
    return this.installedHost?.dueTimerCount?.() ?? 0;
  }

  drainDueTimers(): number {
    return this.installedHost?.drainDueTimers?.() ?? 0;
  }

  private notify(): void {
    for (const listener of [...this.listeners]) listener();
  }
}

const defaultAuthority = new ContractDeterminismAuthority();

export function getDefaultContractDeterminismAuthority(): ContractDeterminismAuthority {
  return defaultAuthority;
}

/**
 * Installs a determinism host for the duration of a fixture run. Returns a
 * restore function; keep installs strictly nested (harness-scoped).
 */
export function installContractDeterminismHost(
  host: ContractDeterminismHost,
): () => void {
  return defaultAuthority.install(host);
}

/** The installed determinism host, or null outside conformance runs. */
export function getContractDeterminismHost(): ContractDeterminismHost | null {
  return defaultAuthority.get();
}

export function onContractDeterminismHostChange(listener: () => void): () => void {
  return defaultAuthority.subscribe(listener);
}
