// @system @ref LLP 0099#M8 — component-lifetime semantic command identities.
// @system @ref LLP 0336#command-instance-identity — this extends the existing
// action-symbol + binding-generation family; it is not a parallel intent
// registry.

import { registerWebMotionArtifact } from './web-motion-diagnostics.js';
import {
  hasMotionCommandRefBrand,
  MOTION_COMMAND_REF_KIND,
} from './motion-command-ref.js';

export { MOTION_COMMAND_REF_KIND } from './motion-command-ref.js';

export interface MotionCommandIdentity {
  readonly commandInstanceId: string;
  readonly action: string;
  readonly ownerInstance: string;
  readonly bindingGeneration: number;
}

export type MotionCommandWitnessState =
  | 'visible'
  | 'disabled'
  | 'conditionally-hidden';

export interface MotionCommandWitness {
  readonly id: string;
  readonly identity: MotionCommandIdentity;
  readonly state: MotionCommandWitnessState;
}

export type MotionCommandDispatchFailure =
  | 'stale-command'
  | 'witness-missing'
  | 'witness-disabled'
  | 'witness-conditionally-hidden'
  | 'witness-ambiguous'
  | 'action-threw';

export interface MotionCommandDispatchReceipt {
  readonly sequence: number;
  readonly dispatchId: string;
  readonly command: MotionCommandIdentity;
  readonly source: 'visible-control' | 'motion-gesture' | 'dismissable-layer';
  readonly status: 'dispatched' | 'blocked' | 'failed';
  readonly reason: MotionCommandDispatchFailure | null;
  readonly witness: MotionCommandWitness | null;
  readonly gestureId?: string;
  /** Decimal u64 on native; web callers may retain their numeric stream id. */
  readonly streamId?: number | string;
  readonly timestampMs: number;
  readonly deduplicated: boolean;
}

export interface MotionCommandDispatchContext {
  readonly source: MotionCommandDispatchReceipt['source'];
  /** Stable semantic-event identity. Replays return the first receipt. */
  readonly dispatchId?: string;
  readonly gestureId?: string;
  readonly streamId?: number | string;
  /**
   * Admission hook: runs once, after the dispatch has passed dedup,
   * registration, and witness checks, immediately before the action is
   * invoked. The native dispatch path adopts terminal SharedValue samples
   * here so a replayed or blocked command can never mutate the JS store.
   * A throw is treated like the action throwing (fail-closed receipt).
   */
  readonly onAdmitted?: () => void;
}

// ---------------------------------------------------------------------------
// Typed terminal command payload (ENG-25123).
//
// A gesture that resolves `commit` delivers ONE bounded, framework-captured
// record to the bound action, on the same acknowledged/deduplicated dispatch
// path as every other command. This is a terminal-only semantic result — it
// is NOT a per-frame transport, and authors cannot extend it from worklets
// (the compiler rejects extra verdict-record fields).
//
// Geometry basis: `presented` — pointer positions in window coordinates at
// the terminal edge, the same basis `motion.measure` rectangles use, so drop
// placement can compare payload coordinates against measured lane rects
// without a basis conversion. Web captures `clientX/clientY`; native captures
// the gesture output's absolute window coordinates. Both sides agree on the
// sample field schema by construction.
//
// Origin identity is first-class: two affordances converging on one command
// (a visible witness press and a pan terminal) are distinguished by the
// presence of this payload and its `origin` field — never by author-managed
// shared flags, which command convergence makes timing-sensitive.
//
// `prospective` is a reserved extension point (ENG-25124): a drop target and
// insertion index resolved on the presentation/worklet path may be attached
// there without an ABI break. A gesture `prospective:` binding populates the
// insertion index and an optional `prospectiveTarget:` binding populates the
// stable decimal target identity from the same presentation-path sample.
// ---------------------------------------------------------------------------

export const MOTION_COMMAND_TERMINAL_PAYLOAD_KIND = 'motion-command-terminal';
export const MOTION_COMMAND_TERMINAL_PAYLOAD_VERSION = 1;

export interface MotionCommandTerminalProspective {
  /** Stable presentation-resolved drop-target identity, when computed. */
  readonly targetId: string | null;
  /** Resolved insertion index within the drop target, when computed. */
  readonly insertionIndex: number | null;
}

export interface MotionCommandTerminalPayload {
  readonly kind: typeof MOTION_COMMAND_TERMINAL_PAYLOAD_KIND;
  readonly version: typeof MOTION_COMMAND_TERMINAL_PAYLOAD_VERSION;
  /** Which affordance produced this dispatch. Terminal gestures only in v1. */
  readonly origin: 'gesture-terminal';
  /** Geometry basis for the coordinate fields (LLP 0313 vocabulary). */
  readonly basis: 'presented';
  readonly gestureId: string;
  readonly gestureKind: string;
  /** Web uses a number; native preserves the full u64 as a decimal string. */
  readonly streamId: number | string;
  readonly commandInstanceId: string;
  readonly bindingGeneration: number;
  /** Pointer position relative to the claimed node at the terminal edge. */
  readonly x: number;
  readonly y: number;
  /** Pointer position in window coordinates (presented basis). */
  readonly absoluteX: number;
  readonly absoluteY: number;
  readonly translationX: number;
  readonly translationY: number;
  readonly velocityX: number;
  readonly velocityY: number;
  readonly timestampMs: number;
  readonly prospective: MotionCommandTerminalProspective | null;
}

const TERMINAL_GEOMETRY_FIELDS = [
  'x',
  'y',
  'absoluteX',
  'absoluteY',
  'translationX',
  'translationY',
  'velocityX',
  'velocityY',
  'timestampMs',
] as const;

export type MotionCommandTerminalGeometry = {
  readonly [Field in (typeof TERMINAL_GEOMETRY_FIELDS)[number]]: number;
};

/** Optional bounded geometry attached to a native terminal dispatch. */
export interface NativeMotionCommandTerminalGeometry extends MotionCommandTerminalGeometry {
  readonly gestureKind?: string;
  readonly prospectiveInsertionIndex?: number;
  readonly prospectiveTargetId?: string;
}

export function isMotionCommandTerminalPayload(
  value: unknown,
): value is MotionCommandTerminalPayload {
  if (!value || typeof value !== 'object') return false;
  const candidate = value as Partial<MotionCommandTerminalPayload>;
  const prospective = candidate.prospective;
  const validProspective = prospective === null || (
    !!prospective && typeof prospective === 'object' &&
    (prospective.targetId === null || typeof prospective.targetId === 'string') &&
    (prospective.insertionIndex === null || (
      typeof prospective.insertionIndex === 'number' &&
      Number.isSafeInteger(prospective.insertionIndex) && prospective.insertionIndex >= 0
    ))
  );
  return candidate.kind === MOTION_COMMAND_TERMINAL_PAYLOAD_KIND &&
    candidate.version === MOTION_COMMAND_TERMINAL_PAYLOAD_VERSION &&
    candidate.origin === 'gesture-terminal' &&
    candidate.basis === 'presented' &&
    typeof candidate.gestureId === 'string' &&
    TERMINAL_GEOMETRY_FIELDS.every((field) => Number.isFinite(candidate[field])) &&
    validProspective;
}

export function createMotionCommandTerminalPayload(options: {
  identity: MotionCommandIdentity;
  gestureId: string;
  gestureKind: string;
  streamId: number | string;
  geometry: MotionCommandTerminalGeometry;
  prospective?: MotionCommandTerminalProspective | null;
}): MotionCommandTerminalPayload {
  for (const field of TERMINAL_GEOMETRY_FIELDS) {
    if (!Number.isFinite(options.geometry[field])) {
      throw new TypeError(`[motion] terminal command geometry field "${field}" must be a finite number`);
    }
  }
  if (
    options.prospective !== undefined && options.prospective !== null &&
    ((options.prospective.targetId !== null &&
      typeof options.prospective.targetId !== 'string') ||
      (options.prospective.insertionIndex !== null &&
        (!Number.isSafeInteger(options.prospective.insertionIndex) || options.prospective.insertionIndex < 0)))
  ) {
    throw new TypeError('[motion] terminal command prospective must contain a bounded integer insertion index');
  }
  return Object.freeze({
    kind: MOTION_COMMAND_TERMINAL_PAYLOAD_KIND,
    version: MOTION_COMMAND_TERMINAL_PAYLOAD_VERSION,
    origin: 'gesture-terminal',
    basis: 'presented',
    gestureId: options.gestureId,
    gestureKind: options.gestureKind,
    streamId: options.streamId,
    commandInstanceId: options.identity.commandInstanceId,
    bindingGeneration: options.identity.bindingGeneration,
    x: options.geometry.x,
    y: options.geometry.y,
    absoluteX: options.geometry.absoluteX,
    absoluteY: options.geometry.absoluteY,
    translationX: options.geometry.translationX,
    translationY: options.geometry.translationY,
    velocityX: options.geometry.velocityX,
    velocityY: options.geometry.velocityY,
    timestampMs: options.geometry.timestampMs,
    prospective: options.prospective === undefined ? null : options.prospective,
  });
}

/**
 * Validate the bounded terminal geometry attached to a native dispatch.
 * Fail-closed: unknown keys, non-finite numbers, or a wrong shape reject the
 * whole record so a malformed host crossing can never smuggle an unbounded
 * payload into an action invocation.
 */
export function normalizeNativeMotionCommandTerminalGeometry(
  value: unknown,
): NativeMotionCommandTerminalGeometry {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError('[motion] native terminal geometry must be a bounded record');
  }
  const record = value as Record<string, unknown>;
  const known = new Set<string>([
    ...TERMINAL_GEOMETRY_FIELDS,
    'gestureKind',
    'prospectiveInsertionIndex',
    'prospectiveTargetId',
  ]);
  for (const key of Object.keys(record)) {
    if (!known.has(key)) {
      throw new TypeError(`[motion] native terminal geometry field "${key}" is outside the bounded terminal payload schema`);
    }
  }
  const geometry: Record<string, number> = {};
  for (const field of TERMINAL_GEOMETRY_FIELDS) {
    const candidate = record[field];
    if (typeof candidate !== 'number' || !Number.isFinite(candidate)) {
      throw new TypeError(`[motion] native terminal geometry field "${field}" must be a finite number`);
    }
    geometry[field] = candidate;
  }
  if (record.gestureKind !== undefined && typeof record.gestureKind !== 'string') {
    throw new TypeError('[motion] native terminal geometry gestureKind must be a string');
  }
  if (record.prospectiveTargetId !== undefined && (
    typeof record.prospectiveTargetId !== 'string' || record.prospectiveTargetId.length === 0
  )) {
    throw new TypeError('[motion] native terminal geometry prospectiveTargetId must be a non-empty string');
  }
  if (
    record.prospectiveInsertionIndex !== undefined &&
    (typeof record.prospectiveInsertionIndex !== 'number' ||
      !Number.isFinite(record.prospectiveInsertionIndex) ||
      !Number.isSafeInteger(Math.round(record.prospectiveInsertionIndex)))
  ) {
    throw new TypeError('[motion] native terminal geometry prospectiveInsertionIndex must round to a finite safe integer');
  }
  return Object.freeze({
    ...(geometry as MotionCommandTerminalGeometry),
    ...(record.gestureKind === undefined ? {} : { gestureKind: record.gestureKind as string }),
    ...(record.prospectiveInsertionIndex === undefined
      ? {}
      : { prospectiveInsertionIndex: record.prospectiveInsertionIndex as number }),
    ...(record.prospectiveTargetId === undefined
      ? {}
      : { prospectiveTargetId: record.prospectiveTargetId as string }),
  });
}

export interface MotionCommandDigestIdentity {
  readonly commandInstanceHash: bigint;
  readonly actionHash: bigint;
  readonly ownerHash: bigint;
  readonly bindingGeneration: number;
}

/**
 * One terminal SharedValue sample from the native UI slab. The slab is the
 * write authority during a gesture (worklet writes never reach the JS store),
 * so the dispatch carries the gesture's captured SharedValues at the terminal
 * edge and the store adopts them before the command action runs — otherwise
 * an action reading `sharedValue.value` observes pre-gesture state and
 * commits a revert.
 */
export interface NativeMotionCommandSharedValueSample {
  readonly descriptorId: string;
  readonly generation: number;
  readonly value: number;
}

const NATIVE_SHARED_VALUE_SAMPLE_LIMIT = 64;

/**
 * Validate the bounded SharedValue sample list attached to a native dispatch.
 * Fail-closed like the terminal geometry: unknown keys, non-canonical u64
 * ids, or non-finite values reject the whole dispatch.
 */
export function normalizeNativeMotionCommandSharedValueSamples(
  value: unknown,
): readonly NativeMotionCommandSharedValueSample[] {
  if (!Array.isArray(value)) {
    throw new TypeError('[motion] native sharedValues must be an array');
  }
  if (value.length > NATIVE_SHARED_VALUE_SAMPLE_LIMIT) {
    throw new TypeError(
      `[motion] native sharedValues exceeds the bounded sample limit (${NATIVE_SHARED_VALUE_SAMPLE_LIMIT})`,
    );
  }
  const samples = value.map((entry) => {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
      throw new TypeError('[motion] native sharedValue sample must be a bounded record');
    }
    const record = entry as Record<string, unknown>;
    for (const key of Object.keys(record)) {
      if (key !== 'descriptorId' && key !== 'generation' && key !== 'value') {
        throw new TypeError(`[motion] native sharedValue sample field "${key}" is outside the bounded schema`);
      }
    }
    if (typeof record.descriptorId !== 'string') {
      throw new TypeError('[motion] native sharedValue sample descriptorId must be a string');
    }
    // Throws on non-canonical u64 text, matching the identity fields.
    parseDecimalU64(record.descriptorId, 'sharedValue sample descriptorId');
    if (
      typeof record.generation !== 'number' ||
      !Number.isInteger(record.generation) ||
      record.generation <= 0 ||
      record.generation > 0xffff_ffff
    ) {
      throw new TypeError('[motion] native sharedValue sample generation must be a positive u32');
    }
    if (typeof record.value !== 'number' || !Number.isFinite(record.value)) {
      throw new TypeError('[motion] native sharedValue sample value must be a finite number');
    }
    return Object.freeze({
      descriptorId: record.descriptorId,
      generation: record.generation,
      value: record.value,
    });
  });
  return Object.freeze(samples);
}

/**
 * Store-side applier for terminal SharedValue write-back, registered by the
 * host-ops layer (motion-command must not import host-ops — cycle). No
 * applier registered means samples are ignored, which is the correct web
 * behavior: there the JS store already IS the write authority.
 */
let nativeSharedValueWriteBack:
  | ((samples: readonly NativeMotionCommandSharedValueSample[]) => void)
  | null = null;

export function setNativeMotionSharedValueWriteBack(
  applier: ((samples: readonly NativeMotionCommandSharedValueSample[]) => void) | null,
): void {
  nativeSharedValueWriteBack = applier;
}

export interface NativeMotionCommandDispatchRequest {
  readonly commandInstanceHash: string;
  readonly actionHash: string;
  readonly ownerHash: string;
  readonly bindingGeneration: number;
  readonly dispatchId: string;
  readonly gestureId: string;
  readonly streamId: string;
  /**
   * Bounded presented-basis geometry captured at the terminal edge
   * (ENG-25123). Optional: hosts predating the typed terminal payload omit
   * it and the command action receives no payload argument.
   */
  readonly terminal?: NativeMotionCommandTerminalGeometry;
  /**
   * Bounded terminal SharedValue samples for JS-store write-back (FX2-d).
   * Optional: hosts predating the field omit it.
   */
  readonly sharedValues?: readonly NativeMotionCommandSharedValueSample[];
}

export interface NativeMotionCommandDispatchResult {
  readonly status: MotionCommandDispatchReceipt['status'];
  readonly reason: MotionCommandDispatchFailure | null;
  readonly sequence: number;
  readonly deduplicated: boolean;
}

type NativeMotionCommandDigestRequest = Pick<
  NativeMotionCommandDispatchRequest,
  'commandInstanceHash' | 'actionHash' | 'ownerHash' | 'bindingGeneration'
>;

export interface MotionCommandRef<Args extends readonly unknown[] = readonly unknown[]> {
  (...args: Args): MotionCommandDispatchReceipt;
  readonly __exactMotionCommandKind: typeof MOTION_COMMAND_REF_KIND;
  readonly identity: MotionCommandIdentity;
}

interface RegisteredCommand {
  readonly ref: MotionCommandRef;
  readonly invoke: (...args: readonly unknown[]) => unknown;
  rootLabel: string | null;
  retireDiagnostics: () => void;
  registrations: number;
}

interface RegisteredWitness {
  readonly id: string;
  readonly identity: MotionCommandIdentity;
  readonly readState: () => MotionCommandWitnessState;
  retireDiagnostics: () => void;
}

interface MotionCommandRegistryState {
  commands: Map<string, RegisteredCommand>;
  commandsByDigest: Map<string, RegisteredCommand>;
  digestIdentityHistory: Map<string, MotionCommandIdentity>;
  digestIdentityOrder: string[];
  latestGeneration: Map<string, number>;
  witnesses: Map<string, RegisteredWitness>;
  receipts: MotionCommandDispatchReceipt[];
  diagnostics: Array<{
    sequence: number;
    commandInstanceId: string;
    code: MotionCommandDispatchFailure;
    message: string;
    timestampMs: number;
  }>; 
  dedup: Map<string, MotionCommandDispatchReceipt>;
  dedupOrder: string[];
  nextCommand: number;
  nextDispatch: number;
  nextReceipt: number;
  nextDiagnostic: number;
}

const RECEIPT_CAPACITY = 100;
const DIAGNOSTIC_CAPACITY = 100;
const DEDUP_CAPACITY = 100;
const DIGEST_IDENTITY_CAPACITY = 1024;
const U64_MAX = 0xffff_ffff_ffff_ffffn;

function fnv1a64(value: string): bigint {
  let digest = 0xcbf29ce484222325n;
  for (const byte of new TextEncoder().encode(value)) {
    digest = BigInt.asUintN(64, (digest ^ BigInt(byte)) * 0x100000001b3n);
  }
  return digest === 0n ? 1n : digest;
}

export function motionCommandIdentityDigests(
  identity: Pick<MotionCommandIdentity, 'commandInstanceId' | 'action' | 'ownerInstance' | 'bindingGeneration'>,
): MotionCommandDigestIdentity {
  if (!Number.isInteger(identity.bindingGeneration) || identity.bindingGeneration < 1 ||
      identity.bindingGeneration > 0xffff_ffff) {
    throw new RangeError('[motion] command digest requires a positive u32 binding generation');
  }
  return Object.freeze({
    commandInstanceHash: fnv1a64(`motion-command-instance:${identity.commandInstanceId}`),
    actionHash: fnv1a64(`motion-command-action:${identity.action}`),
    ownerHash: fnv1a64(`motion-command-owner:${identity.ownerInstance}`),
    bindingGeneration: identity.bindingGeneration,
  });
}

function digestKey(digests: MotionCommandDigestIdentity): string {
  return `${digests.commandInstanceHash}:${digests.actionHash}:${digests.ownerHash}:${digests.bindingGeneration}`;
}

function parseDecimalU64(value: unknown, label: string): bigint {
  if (typeof value !== 'string' || !/^(?:0|[1-9][0-9]*)$/.test(value)) {
    throw new TypeError(`[motion] ${label} must be a canonical decimal u64`);
  }
  const parsed = BigInt(value);
  if (parsed === 0n || parsed > U64_MAX) {
    throw new RangeError(`[motion] ${label} must be a nonzero u64`);
  }
  return parsed;
}

/**
 * Resolve a native digest through the same bounded, collision-checked history
 * used by dispatch. Delayed acknowledged outcomes may outlive the descriptor
 * that authored them, so callers must not substitute the current descriptor's
 * CommandRef identity.
 */
export function resolveNativeMotionCommandIdentity(
  request: NativeMotionCommandDigestRequest,
): MotionCommandIdentity | undefined {
  if (!request || typeof request !== 'object') return undefined;
  const bindingGeneration = request.bindingGeneration;
  if (!Number.isInteger(bindingGeneration) || bindingGeneration < 1 ||
      bindingGeneration > 0xffff_ffff) {
    return undefined;
  }
  try {
    return registry().digestIdentityHistory.get(digestKey({
      commandInstanceHash: parseDecimalU64(
        request.commandInstanceHash,
        'command instance hash',
      ),
      actionHash: parseDecimalU64(request.actionHash, 'command action hash'),
      ownerHash: parseDecimalU64(request.ownerHash, 'command owner hash'),
      bindingGeneration,
    }));
  } catch {
    return undefined;
  }
}

function registry(): MotionCommandRegistryState {
  const scope = globalThis as typeof globalThis & {
    __exactMotionCommandRegistry?: MotionCommandRegistryState;
  };
  const state: MotionCommandRegistryState = scope.__exactMotionCommandRegistry ??= {
    commands: new Map(),
    commandsByDigest: new Map(),
    digestIdentityHistory: new Map(),
    digestIdentityOrder: [],
    latestGeneration: new Map(),
    witnesses: new Map(),
    receipts: [],
    diagnostics: [],
    dedup: new Map(),
    dedupOrder: [],
    nextCommand: 1,
    nextDispatch: 1,
    nextReceipt: 1,
    nextDiagnostic: 1,
  };
  // HMR can preserve a registry created by an older bundle. Hydrate new
  // derived indexes instead of requiring a process restart.
  const rebuildDigestIndex = state.commandsByDigest === undefined ||
    state.digestIdentityHistory === undefined || state.digestIdentityOrder === undefined;
  state.commandsByDigest ??= new Map();
  state.digestIdentityHistory ??= new Map();
  state.digestIdentityOrder ??= [];
  // HMR may preserve registrations minted by ENG-25123/25125 bundles that
  // predate per-root artifact accounting. Hydrate them once in place so a
  // later disposer/reset cannot call a missing retirement handle.
  for (const registration of state.commands.values()) {
    registration.rootLabel ??= null;
    registration.registrations = Number.isSafeInteger(registration.registrations) &&
      registration.registrations > 0 ? registration.registrations : 1;
    registration.retireDiagnostics ??= registerWebMotionArtifact(
      'commands',
      registration.rootLabel,
    );
  }
  for (const witness of state.witnesses.values()) {
    const rootLabel = state.commands.get(commandKey(witness.identity))?.rootLabel;
    witness.retireDiagnostics ??= registerWebMotionArtifact('witnesses', rootLabel);
  }
  if (rebuildDigestIndex) {
    for (const registration of state.commands.values()) {
      const identity = registration.ref.identity;
      const key = digestKey(motionCommandIdentityDigests(identity));
      const prior = state.digestIdentityHistory.get(key);
      if (prior && !sameIdentity(prior, identity)) continue;
      state.commandsByDigest.set(key, registration);
      state.digestIdentityHistory.set(key, identity);
      state.digestIdentityOrder.push(key);
    }
  }
  return state;
}

function pruneDigestHistory(state: MotionCommandRegistryState): void {
  let inactive = state.digestIdentityOrder.length - state.commandsByDigest.size;
  if (inactive <= DIGEST_IDENTITY_CAPACITY) return;
  state.digestIdentityOrder = state.digestIdentityOrder.filter((key) => {
    if (inactive <= DIGEST_IDENTITY_CAPACITY || state.commandsByDigest.has(key)) return true;
    inactive -= 1;
    state.digestIdentityHistory.delete(key);
    return false;
  });
}

function rememberDispatch(
  dispatchId: string,
  receipt: MotionCommandDispatchReceipt,
): void {
  const state = registry();
  if (!state.dedup.has(dispatchId)) state.dedupOrder.push(dispatchId);
  state.dedup.set(dispatchId, receipt);
  while (state.dedupOrder.length > DEDUP_CAPACITY) {
    const expired = state.dedupOrder.shift();
    if (expired !== undefined) state.dedup.delete(expired);
  }
}

function sameIdentity(left: MotionCommandIdentity, right: MotionCommandIdentity): boolean {
  return left.commandInstanceId === right.commandInstanceId &&
    left.bindingGeneration === right.bindingGeneration &&
    left.action === right.action &&
    left.ownerInstance === right.ownerInstance;
}

function commandKey(identity: MotionCommandIdentity): string {
  return `${identity.commandInstanceId}\0${identity.bindingGeneration}`;
}

function noteDiagnostic(
  identity: MotionCommandIdentity,
  code: MotionCommandDispatchFailure,
  message: string,
): void {
  const state = registry();
  state.diagnostics.push({
    sequence: state.nextDiagnostic++,
    commandInstanceId: identity.commandInstanceId,
    code,
    message,
    timestampMs: Date.now(),
  });
  while (state.diagnostics.length > DIAGNOSTIC_CAPACITY) state.diagnostics.shift();
}

function freezeReceipt(
  identity: MotionCommandIdentity,
  context: MotionCommandDispatchContext,
  dispatchId: string,
  status: MotionCommandDispatchReceipt['status'],
  reason: MotionCommandDispatchFailure | null,
  witness: MotionCommandWitness | null,
  deduplicated = false,
): MotionCommandDispatchReceipt {
  const state = registry();
  const receipt: MotionCommandDispatchReceipt = Object.freeze({
    sequence: state.nextReceipt++,
    dispatchId,
    command: identity,
    source: context.source,
    status,
    reason,
    witness,
    ...(context.gestureId === undefined ? {} : { gestureId: context.gestureId }),
    ...(context.streamId === undefined ? {} : { streamId: context.streamId }),
    timestampMs: Date.now(),
    deduplicated,
  });
  state.receipts.push(receipt);
  while (state.receipts.length > RECEIPT_CAPACITY) state.receipts.shift();
  return receipt;
}

function witnessVerdict(identity: MotionCommandIdentity): {
  witness: MotionCommandWitness | null;
  reason: MotionCommandDispatchFailure | null;
} {
  const entries = [...registry().witnesses.values()]
    .filter((entry) => sameIdentity(entry.identity, identity))
    .map((entry): MotionCommandWitness => Object.freeze({
      id: entry.id,
      identity: entry.identity,
      state: entry.readState(),
    }));
  const visible = entries.filter((entry) => entry.state === 'visible');
  if (visible.length === 1) return { witness: visible[0]!, reason: null };
  if (visible.length > 1) return { witness: null, reason: 'witness-ambiguous' };
  if (entries.some((entry) => entry.state === 'disabled')) {
    return { witness: entries.find((entry) => entry.state === 'disabled')!, reason: 'witness-disabled' };
  }
  if (entries.some((entry) => entry.state === 'conditionally-hidden')) {
    return {
      witness: entries.find((entry) => entry.state === 'conditionally-hidden')!,
      reason: 'witness-conditionally-hidden',
    };
  }
  return { witness: null, reason: 'witness-missing' };
}

export function isMotionCommandRef(value: unknown): value is MotionCommandRef {
  return hasMotionCommandRefBrand(value);
}

export function isMotionCommandIdentity(value: unknown): value is MotionCommandIdentity {
  if (!value || typeof value !== 'object') return false;
  const candidate = value as Partial<MotionCommandIdentity>;
  return typeof candidate.commandInstanceId === 'string' && candidate.commandInstanceId.length > 0 &&
    typeof candidate.action === 'string' && candidate.action.length > 0 &&
    typeof candidate.ownerInstance === 'string' && candidate.ownerInstance.length > 0 &&
    Number.isInteger(candidate.bindingGeneration) && (candidate.bindingGeneration ?? 0) > 0;
}

export function createMotionCommandRef<Args extends readonly unknown[]>(
  invoke: (...args: Args) => unknown,
  options: {
    action?: string;
    ownerInstance?: string;
    commandInstanceId?: string;
    bindingGeneration?: number;
  } = {},
): MotionCommandRef<Args> {
  if (typeof invoke !== 'function') throw new TypeError('[motion] command requires an action function');
  const annotated = invoke as typeof invoke & {
    __exactCommandAction?: string;
    __exactCommandOwner?: string;
  };
  const state = registry();
  const action = options.action ?? annotated.__exactCommandAction ?? invoke.name ?? 'anonymous';
  const ownerInstance = options.ownerInstance ?? annotated.__exactCommandOwner ?? 'external';
  const commandInstanceId = options.commandInstanceId ?? `${ownerInstance}/command_${state.nextCommand++}`;
  const bindingGeneration = options.bindingGeneration ?? 1;
  if (!action || !ownerInstance || !commandInstanceId || !Number.isInteger(bindingGeneration) || bindingGeneration < 1) {
    throw new TypeError('[motion] command identity must have action, owner, instance, and positive generation');
  }
  const identity: MotionCommandIdentity = Object.freeze({
    commandInstanceId,
    action,
    ownerInstance,
    bindingGeneration,
  });
  const ref = ((...args: Args) => dispatchMotionCommand(identity, args, {
    source: 'visible-control',
  })) as MotionCommandRef<Args>;
  Object.defineProperties(ref, {
    __exactMotionCommandKind: { value: MOTION_COMMAND_REF_KIND, enumerable: false },
    identity: { value: identity, enumerable: true },
  });
  Object.defineProperty(ref, '__exactMotionCommandInvoke', { value: invoke, enumerable: false });
  return ref;
}

export function registerMotionCommand(
  ref: MotionCommandRef,
  options: { rootLabel?: string | null } = {},
): () => void {
  if (!isMotionCommandRef(ref)) throw new TypeError('[motion] registerCommand requires a CommandRef');
  const state = registry();
  const identity = ref.identity;
  const key = commandKey(identity);
  const invoke = (ref as MotionCommandRef & {
    __exactMotionCommandInvoke?: (...args: readonly unknown[]) => unknown;
  }).__exactMotionCommandInvoke;
  if (typeof invoke !== 'function') throw new TypeError('[motion] CommandRef has no registered action');
  const existing = state.commands.get(key);
  if (existing && existing.ref !== ref) {
    throw new Error(`[motion] command identity "${identity.commandInstanceId}" generation ${identity.bindingGeneration} is already mounted`);
  }
  const digests = motionCommandIdentityDigests(identity);
  const hashedKey = digestKey(digests);
  const digestCollision = state.digestIdentityHistory.get(hashedKey);
  if (digestCollision && !sameIdentity(digestCollision, identity)) {
    throw new Error('[motion] CommandRef digest collision; native acceleration refused');
  }
  const registration = existing ?? {
    ref,
    invoke,
    rootLabel: options.rootLabel ?? null,
    retireDiagnostics: registerWebMotionArtifact('commands', options.rootLabel),
    registrations: 0,
  };
  registration.registrations += 1;
  state.commands.set(key, registration);
  state.commandsByDigest.set(hashedKey, registration);
  if (!state.digestIdentityHistory.has(hashedKey)) {
    state.digestIdentityOrder.push(hashedKey);
  }
  state.digestIdentityHistory.set(hashedKey, identity);
  pruneDigestHistory(state);
  state.latestGeneration.set(identity.commandInstanceId, Math.max(
    identity.bindingGeneration,
    state.latestGeneration.get(identity.commandInstanceId) ?? 0,
  ));
  let active = true;
  return () => {
    if (!active) return;
    active = false;
    registration.registrations = Math.max(0, registration.registrations - 1);
    if (registration.registrations > 0) return;
    if (state.commands.get(key) === registration) {
      state.commands.delete(key);
      registration.retireDiagnostics();
    }
    if (state.commandsByDigest.get(hashedKey)?.ref === ref) {
      state.commandsByDigest.delete(hashedKey);
    }
    pruneDigestHistory(state);
  };
}

/**
 * Runtime-side half of the native CommandRef crossing. Native supplies only
 * irreversible, generation-fenced digests; this registry resolves them back
 * to the one mounted CommandRef and applies the same witness/receipt policy as
 * a visible control. Unknown or stale identities fail closed.
 */
export function dispatchNativeMotionCommand(
  request: NativeMotionCommandDispatchRequest,
): NativeMotionCommandDispatchResult {
  if (!request || typeof request !== 'object') {
    throw new TypeError('[motion] native command dispatch requires a request');
  }
  const bindingGeneration = request.bindingGeneration;
  if (!Number.isInteger(bindingGeneration) || bindingGeneration < 1 || bindingGeneration > 0xffff_ffff) {
    throw new RangeError('[motion] native command binding generation must be a positive u32');
  }
  if (typeof request.dispatchId !== 'string' || request.dispatchId.length === 0 ||
      typeof request.gestureId !== 'string' || request.gestureId.length === 0) {
    throw new TypeError('[motion] native command dispatch requires stable dispatch and gesture ids');
  }
  parseDecimalU64(request.streamId, 'native stream id');
  // Preserve the public dispatch surface's strict validation. The resolver
  // below deliberately returns undefined (rather than throwing) because it
  // is also used to fail closed while normalizing delayed terminal events.
  parseDecimalU64(request.commandInstanceHash, 'command instance hash');
  parseDecimalU64(request.actionHash, 'command action hash');
  parseDecimalU64(request.ownerHash, 'command owner hash');
  // Validate the bounded terminal geometry BEFORE identity resolution so a
  // malformed payload fails closed even when the command is otherwise live.
  const terminalGeometry = request.terminal === undefined
    ? null
    : normalizeNativeMotionCommandTerminalGeometry(request.terminal);
  const sharedValueSamples = request.sharedValues === undefined
    ? null
    : normalizeNativeMotionCommandSharedValueSamples(request.sharedValues);
  const identity = resolveNativeMotionCommandIdentity(request);
  if (!identity) {
    return Object.freeze({
      status: 'blocked',
      reason: 'stale-command',
      sequence: 0,
      deduplicated: false,
    });
  }
  const args = terminalGeometry === null ? [] : [createMotionCommandTerminalPayload({
    identity,
    gestureId: request.gestureId,
    gestureKind: terminalGeometry.gestureKind ?? 'pan',
    streamId: request.streamId,
    geometry: terminalGeometry,
    prospective: terminalGeometry.prospectiveInsertionIndex === undefined &&
        terminalGeometry.prospectiveTargetId === undefined
      ? null
      : {
          targetId: terminalGeometry.prospectiveTargetId ?? null,
          insertionIndex: terminalGeometry.prospectiveInsertionIndex === undefined ||
              terminalGeometry.prospectiveInsertionIndex < 0
            ? null
            : Math.round(terminalGeometry.prospectiveInsertionIndex),
        },
  })];
  const receipt = dispatchMotionCommand(identity, args, {
    source: 'motion-gesture',
    dispatchId: request.dispatchId,
    gestureId: request.gestureId,
    streamId: request.streamId,
    // Adopt the terminal slab state into the JS store BEFORE the action runs
    // — its `sharedValue.value` reads must observe what the gesture actually
    // wrote (FX2-d) — but only AFTER the dispatch is admitted: a replayed
    // dispatchId or a witness-blocked command must leave the store untouched.
    // Hosts without a registered applier (web: the store already is the write
    // authority) skip harmlessly.
    ...(sharedValueSamples !== null && sharedValueSamples.length > 0
      ? {
          onAdmitted: () => {
            nativeSharedValueWriteBack?.(sharedValueSamples);
          },
        }
      : {}),
  });
  return Object.freeze({
    status: receipt.status,
    reason: receipt.reason,
    sequence: receipt.sequence,
    deduplicated: receipt.deduplicated,
  });
}

type NativeMotionCommandGlobal = typeof globalThis & {
  __exactDispatchMotionCommand?: (
    request: NativeMotionCommandDispatchRequest,
  ) => NativeMotionCommandDispatchResult;
};

// The app runtime is the only CommandRef registry. The native host invokes
// this entry asynchronously on the runtime executor; no main-thread resolver
// or duplicate command table is created.
(globalThis as NativeMotionCommandGlobal).__exactDispatchMotionCommand =
  dispatchNativeMotionCommand;

export function registerMotionCommandWitness(
  refOrIdentity: MotionCommandRef | MotionCommandIdentity,
  witness: { id: string; readState: () => MotionCommandWitnessState },
): () => void {
  const identity = isMotionCommandRef(refOrIdentity) ? refOrIdentity.identity : refOrIdentity;
  if (!isMotionCommandIdentity(identity)) throw new TypeError('[motion] witness requires a CommandRef identity');
  if (!witness.id || typeof witness.readState !== 'function') {
    throw new TypeError('[motion] witness requires a stable id and state reader');
  }
  const state = registry();
  const key = `${commandKey(identity)}\0${witness.id}`;
  const rootLabel = state.commands.get(commandKey(identity))?.rootLabel;
  const entry: RegisteredWitness = {
    id: witness.id,
    identity,
    readState: witness.readState,
    retireDiagnostics: registerWebMotionArtifact('witnesses', rootLabel),
  };
  state.witnesses.get(key)?.retireDiagnostics();
  state.witnesses.set(key, entry);
  let active = true;
  return () => {
    if (!active) return;
    active = false;
    if (state.witnesses.get(key) === entry) {
      state.witnesses.delete(key);
      entry.retireDiagnostics();
    }
  };
}

export function dispatchMotionCommand(
  identity: MotionCommandIdentity,
  args: readonly unknown[],
  context: MotionCommandDispatchContext,
): MotionCommandDispatchReceipt {
  if (!isMotionCommandIdentity(identity)) throw new TypeError('[motion] dispatch requires a CommandRef identity');
  const state = registry();
  const dispatchId = context.dispatchId ?? `command_dispatch_${state.nextDispatch++}`;
  const replay = state.dedup.get(dispatchId);
  if (replay) {
    return Object.freeze({ ...replay, deduplicated: true });
  }
  const registration = state.commands.get(commandKey(identity));
  if (!registration) {
    const receipt = freezeReceipt(identity, context, dispatchId, 'blocked', 'stale-command', null);
    rememberDispatch(dispatchId, receipt);
    noteDiagnostic(identity, 'stale-command',
      `command ${identity.commandInstanceId}@${identity.bindingGeneration} is no longer mounted`);
    return receipt;
  }
  const verdict = witnessVerdict(identity);
  if (verdict.reason) {
    const receipt = freezeReceipt(identity, context, dispatchId, 'blocked', verdict.reason, verdict.witness);
    rememberDispatch(dispatchId, receipt);
    noteDiagnostic(identity, verdict.reason,
      `command ${identity.commandInstanceId}@${identity.bindingGeneration} blocked: ${verdict.reason}`);
    return receipt;
  }
  try {
    // Admission is complete (dedup, registration, witness). Side effects the
    // dispatch carries — e.g. native terminal SharedValue write-back — may
    // apply now and only now.
    context.onAdmitted?.();
    registration.invoke(...args);
  } catch (error) {
    const receipt = freezeReceipt(identity, context, dispatchId, 'failed', 'action-threw', verdict.witness);
    rememberDispatch(dispatchId, receipt);
    noteDiagnostic(identity, 'action-threw',
      `command ${identity.commandInstanceId}@${identity.bindingGeneration} threw: ${String(error)}`);
    return receipt;
  }
  const receipt = freezeReceipt(identity, context, dispatchId, 'dispatched', null, verdict.witness);
  rememberDispatch(dispatchId, receipt);
  return receipt;
}

export function getMotionCommandSnapshot(): {
  receipts: readonly MotionCommandDispatchReceipt[];
  diagnostics: readonly MotionCommandRegistryState['diagnostics'][number][];
} {
  const state = registry();
  return {
    receipts: [...state.receipts],
    diagnostics: [...state.diagnostics],
  };
}

export function resetMotionCommandRegistryForTests(): void {
  const state = (globalThis as typeof globalThis & {
    __exactMotionCommandRegistry?: MotionCommandRegistryState;
  }).__exactMotionCommandRegistry;
  if (state) {
    for (const registration of state.commands.values()) registration.retireDiagnostics();
    for (const witness of state.witnesses.values()) witness.retireDiagnostics();
  }
  delete (globalThis as typeof globalThis & {
    __exactMotionCommandRegistry?: MotionCommandRegistryState;
  }).__exactMotionCommandRegistry;
}
