// @system @ref LLP 0393 M3–M4 / LLP 0373 P1 — the web host keeps only this
// inert adoption seam. The Contract compiler installs the real video adopter
// together with the video engine for authored video modules.

export interface VideoWebAdopter {
  ensure(el: HTMLElement): void;
  dispose(el: HTMLElement): void;
}

let registeredAdopter: VideoWebAdopter | null = null;

export function registerVideoWebAdopter(adopter: VideoWebAdopter): void {
  registeredAdopter = adopter;
}

export function ensureVideoWebView(el: HTMLElement): void {
  registeredAdopter?.ensure(el);
}

export function disposeVideoWebView(el: HTMLElement): void {
  registeredAdopter?.dispose(el);
}
