// @system @ref LLP 0336#4-2-key-accelerator-lines —
// Interpreter-free native keyboard registration used by compiled pagers.

import { OpCode } from '@exact/core/protocol/opcodes';

export interface NativeContractKeyEvent {
  readonly key: string;
  readonly rootId: number | null;
  readonly focusScopeViewId: number | null;
}

interface NativeRuntimeBridge {
  getModuleMetadata?: (
    name: string,
  ) => { moduleId?: number } | null | undefined;
  dispatchModule?: (bytes: Uint8Array) => void;
}

type ModuleEventHandler = (event: string, payload: unknown) => void;

interface ModuleEventGlobals {
  exact?: NativeRuntimeBridge;
  __exactModuleEvent?: (
    module: string,
    event: string,
    ...rest: unknown[]
  ) => void;
  __exactModuleEventHandlers?: Map<string, ModuleEventHandler>;
}

interface NativeBinding {
  readonly rootId: number;
  readonly key: string;
  readonly action: (event: NativeContractKeyEvent) => void;
}

const MODULE = 'com.exact.host.keyboard';
const ACTION_SET_KEYS = 0;
const bindings = new Set<NativeBinding>();
let handlerInstalled = false;
let dispatcherInstalled = false;
let correlationId = 1;
let syncedKeys: string | null = null;

function globals(): ModuleEventGlobals {
  return globalThis as ModuleEventGlobals;
}

function encode(keys: readonly string[]): Uint8Array | null {
  const bridge = globals().exact;
  if (
    !bridge?.dispatchModule ||
    typeof bridge.getModuleMetadata !== 'function'
  ) {
    return null;
  }
  const moduleId = bridge.getModuleMetadata(MODULE)?.moduleId;
  if (!moduleId) return null;
  const payload = new TextEncoder().encode(JSON.stringify({ keys }));
  const bytes = new Uint8Array(13 + payload.length);
  const view = new DataView(bytes.buffer);
  view.setUint8(0, OpCode.ModuleAction);
  view.setUint16(1, moduleId, true);
  view.setUint16(3, ACTION_SET_KEYS, true);
  view.setUint32(5, correlationId++, true);
  view.setUint32(9, payload.length, true);
  bytes.set(payload, 13);
  return bytes;
}

function sync(): void {
  const bridge = globals().exact;
  if (!bridge?.dispatchModule) return;
  const keys = [...new Set(
    [...bindings]
      .map((binding) => binding.key)
      .filter((key) => !key.includes('+')),
  )].sort();
  const serialized = JSON.stringify(keys);
  if (serialized === syncedKeys) return;
  const bytes = encode(keys);
  if (!bytes) return;
  bridge.dispatchModule(bytes);
  syncedKeys = serialized;
}

function decode(payload: unknown): NativeContractKeyEvent | null {
  let candidate: unknown = payload;
  if (payload instanceof Uint8Array) {
    candidate = new TextDecoder().decode(payload);
  } else if (payload instanceof ArrayBuffer) {
    candidate = new TextDecoder().decode(new Uint8Array(payload));
  }
  if (typeof candidate === 'string') {
    try {
      candidate = JSON.parse(candidate);
    } catch {
      return null;
    }
  }
  if (!candidate || typeof candidate !== 'object') return null;
  const event = candidate as {
    key?: unknown;
    rootId?: unknown;
    focusScopeViewId?: unknown;
  };
  if (typeof event.key !== 'string') return null;
  return {
    key: event.key,
    rootId: typeof event.rootId === 'number' ? event.rootId : null,
    focusScopeViewId:
      typeof event.focusScopeViewId === 'number'
        ? event.focusScopeViewId
        : null,
  };
}

function ensureHandler(): void {
  if (handlerInstalled) return;
  const target = globals();
  target.__exactModuleEventHandlers ??= new Map();
  if (!dispatcherInstalled) {
    const previous = target.__exactModuleEvent;
    target.__exactModuleEvent = (
      module: string,
      event: string,
      ...rest: unknown[]
    ) => {
      const payload = rest.length > 1 ? rest[rest.length - 1] : rest[0];
      const handler = target.__exactModuleEventHandlers?.get(module);
      if (handler) {
        handler(event, payload);
        return;
      }
      previous?.(module, event, ...rest);
    };
    dispatcherInstalled = true;
  }
  const previousHandler = target.__exactModuleEventHandlers.get(MODULE);
  target.__exactModuleEventHandlers.set(MODULE, (event, payload) => {
    previousHandler?.(event, payload);
    if (event !== 'keydown') return;
    const decoded = decode(payload);
    if (!decoded) return;
    const eligible = decoded.rootId === null
      ? [...bindings]
      : [...bindings].filter((binding) => binding.rootId === decoded.rootId);
    if (
      decoded.rootId === null &&
      new Set(eligible.map((binding) => binding.rootId)).size !== 1
    ) {
      return;
    }
    for (const binding of eligible) {
      if (
        binding.key === decoded.key ||
        (decoded.key === ' ' && binding.key === 'Space')
      ) {
        binding.action(decoded);
      }
    }
  });
  handlerInstalled = true;
}

export function registerNativeContractKeyBinding(
  rootId: number,
  key: string,
  action: (event: NativeContractKeyEvent) => void,
): () => void {
  if (typeof document !== 'undefined') return () => {};
  if (!key || typeof action !== 'function') {
    throw new Error('[contract] native keyboard binding requires key + action');
  }
  ensureHandler();
  const binding = { rootId, key, action };
  bindings.add(binding);
  sync();
  let disposed = false;
  return () => {
    if (disposed) return;
    disposed = true;
    bindings.delete(binding);
    sync();
  };
}
