// @system @ref LLP 0007 §8.2.3 — canonical key/focus payloads.

function finiteTimestamp(value: number): number {
  if (!Number.isFinite(value)) {
    return Date.now();
  }
  // DOMHighResTimeStamp is normally relative to Performance.timeOrigin while
  // Apple/native payloads use Unix epoch milliseconds. Normalize the browser
  // value so the canonical cross-platform field has one time domain.
  if (value < 1_000_000_000_000) {
    const performanceValue = globalThis.performance;
    const timeOrigin = performanceValue && Number.isFinite(performanceValue.timeOrigin)
      ? performanceValue.timeOrigin
      : Date.now() - (performanceValue?.now() ?? 0);
    return timeOrigin + value;
  }
  return value;
}

export function domViewId(target: EventTarget | null): number | null {
  const registered = (
    globalThis as typeof globalThis & {
      __exactDomIdentity?: { viewIdForTarget(target: EventTarget | null): number | null };
    }
  ).__exactDomIdentity?.viewIdForTarget(target);
  if (typeof registered === 'number') {
    return registered;
  }
  if (
    target == null ||
    typeof target !== 'object' ||
    !('closest' in target) ||
    typeof (target as { closest?: unknown }).closest !== 'function'
  ) {
    return null;
  }
  const raw = (target as Element)
    .closest('[data-exact-view-id]')
    ?.getAttribute('data-exact-view-id');
  if (raw == null || raw.trim() === '') {
    return null;
  }
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : null;
}

export function createDomKeyEventPayload(event: KeyboardEvent) {
  return {
    nativeEvent: {
      key: event.key,
      code: event.code || null,
      altKey: event.altKey,
      ctrlKey: event.ctrlKey,
      metaKey: event.metaKey,
      shiftKey: event.shiftKey,
      repeat: event.repeat,
      timestamp: finiteTimestamp(event.timeStamp),
    },
    preventDefault: () => event.preventDefault(),
    get defaultPrevented() { return event.defaultPrevented; },
  };
}

export function createDomFocusEventPayload(
  event: FocusEvent,
  targetViewId?: number | null,
  relatedTargetViewId?: number | null,
) {
  return {
    nativeEvent: {
      timestamp: finiteTimestamp(event.timeStamp),
      target: targetViewId === undefined ? domViewId(event.target) : targetViewId,
      relatedTarget:
        relatedTargetViewId === undefined
          ? domViewId(event.relatedTarget)
          : relatedTargetViewId,
    },
  };
}
