// @system @ref LLP 0185 S2/S8, LLP 0373 phase 3c — straight-line
// production element construction. Generated plans carry evaluated values,
// event call shape, and authored loci; ordinary elements therefore do not
// retain expression AST or pull the editable/advanced view interpreter into
// a production bundle.

import {
  appendChild,
  createInstance,
  insertBefore,
  removeChild,
  updateInstanceProps,
  type ElementNode,
} from '@exact/renderer/host-ops';
import {
  registerDismissLayer,
  reserveDismissLayerMountSequence,
  type DismissLayerHandle,
} from '@exact/renderer/dismiss-layer-stack';

import type { Span, ViewNodeIR } from '../compiler/ir.js';
import {
  CONTRACT_OVERLAY_PROP_MAP,
  CONTRACT_PROP_RENAMES,
  CONTRACT_STYLE_PROP_MAP,
  CONTRACT_TAG_LOWERING,
  CONTRACT_TEXT_BEARING_TAG_SET,
  CONTRACT_TEXT_STYLE_PROP_MAP,
  transformLoweredStyleValue,
  type ContractTagLowering,
} from '../compiler/builtin-lowering.js';
import type { ContractRoutePayloadTag } from '../compiler/route-payload.js';
import type { CompiledExpr } from './compiled-expr.js';
import {
  decorateContractError,
  reportContractRuntimeError,
  runWithContractErrorLocus,
  type ContractErrorLocus,
} from './error-locus-runtime.js';
import { contractHydrationNodeId, type ContractHydrationEvent } from './hydration.js';
import { applyStyleObject, applyStyleValue } from './layout-intent.js';
import {
  getOwner,
  isReactiveIntrospectionEnabled,
  ownedEffect,
  untrack,
  type ReactiveNodeOptions,
} from './signals.js';
import {
  readContractRoutePayloadExpression,
  registerContractRoutePayloadElementCapture,
} from './route-payload-capture-runtime.js';
import type { Scope } from './interpreter.js';
import { registerHydrationActivation } from './instance.js';
import type { AnchorFn, HostParent, Mounted, MountEnv } from './view.js';
import type { ContractMountViewNodes } from './aot-view-region.js';

const VIEW_EVAL = { identFallbackToString: true } as const;

/**
 * Alternating `[name, value, ...]` entries. A token-valued entry stores
 * `[evaluate, tokenPath]` in its value slot. Keeping the ordinary path flat
 * avoids one retained array per authored prop after a lazy view factory
 * materializes.
 *
 * @ref LLP 0381 §4.1 — production has one compact executable program, not a
 * tuple object for every leaf in that program.
 */
export type ContractAotElementPropPlan = readonly unknown[];

/** Repeating `[name, evaluate, mode, action, ...]` entries. */
export type ContractAotElementEventPlan = readonly unknown[];

export type ContractAotElementDismissPlan = readonly [
  name: string,
  evaluate: CompiledExpr,
  mode: 0 | 1 | 2,
  action: string | null,
];

export type ContractAotElementPlan = readonly [
  props: ContractAotElementPropPlan,
  events: ContractAotElementEventPlan,
  dismiss: ContractAotElementDismissPlan | null,
  tag: string,
  line: number,
  col: number,
  len: number,
  offset: number,
];

function propNameAt(plan: ContractAotElementPropPlan, index: number): string {
  return plan[index] as string;
}

function encodedPropValueAt(
  plan: ContractAotElementPropPlan,
  index: number,
): unknown {
  return plan[index + 1];
}

function propValueAt(plan: ContractAotElementPropPlan, index: number): unknown {
  const encoded = encodedPropValueAt(plan, index);
  return Array.isArray(encoded) ? encoded[0] : encoded;
}

function propTokenPathAt(
  plan: ContractAotElementPropPlan,
  index: number,
): string | undefined {
  const encoded = encodedPropValueAt(plan, index);
  return Array.isArray(encoded) ? encoded[1] as string : undefined;
}

function readPlanValue(
  plan: ContractAotElementPropPlan,
  index: number,
  scope: Scope,
): unknown {
  const value = propValueAt(plan, index);
  return typeof value === 'function'
    ? (value as CompiledExpr)(scope, VIEW_EVAL)
    : value;
}

function lowerOverlayProp(name: string): {
  hostProp: string;
  map?: (value: unknown) => unknown;
} | undefined {
  const hostProp = (CONTRACT_OVERLAY_PROP_MAP as Record<string, string>)[name];
  if (!hostProp) return undefined;
  return {
    hostProp,
    map: name === 'focusTrap'
      ? (value: unknown) => value === true ? 'trapped' : undefined
      : undefined,
  };
}

function mapHeadingLevelValue(value: unknown): unknown {
  return typeof value === 'number' && Number.isInteger(value) && value >= 1 && value <= 6
    ? value
    : undefined;
}

function lowerImageLoading(
  value: unknown,
  inRepetitionScope: boolean,
  repetitionIndex: number | null,
): 'eager' | 'lazy' | undefined {
  if (value === 'lazy' || value === 'eager') return value;
  if (value !== undefined && value !== 'auto') return undefined;
  if (!inRepetitionScope) return undefined;
  return repetitionIndex !== null && repetitionIndex < 12 ? undefined : 'lazy';
}

function lowerEventName(event: string, tag: string): string | null {
  switch (event) {
    case 'press': return 'onPress';
    case 'longpress': return 'onLongPress';
    case 'keydown': return 'onKeyDown';
    case 'change': return tag === 'input'
      ? 'onChangeText'
      : tag === 'toggle' ? 'onValueChange' : 'onChange';
    case 'focus': return 'onFocus';
    case 'blur': return 'onBlur';
    case 'load': return tag === 'image' || tag === 'lottie' || tag === 'rive' ? 'onLoad' : null;
    case 'error': return tag === 'image' || tag === 'lottie' || tag === 'rive' ? 'onError' : null;
    // LLP 0394 Lottie lifecycle (parity with runtime/view.ts lowerEventName).
    case 'complete': return tag === 'lottie' ? 'onComplete' : null;
    case 'looped': return tag === 'lottie' ? 'onLooped' : null;
    case 'statechange': return tag === 'rive' ? 'onStateChange' : null;
    case 'datachange': return tag === 'rive' ? 'onDataChange' : null;
    case 'riveevent': return tag === 'rive' ? 'onRiveEvent' : null;
    case 'submit': return 'onKeyDown';
    case 'scrollend': return 'onScrollEnd';
    case 'refresh': return 'onRefresh';
    default: return null;
  }
}

function chainEventHandler(existing: unknown, next: (payload: unknown) => void) {
  if (typeof existing !== 'function') return next;
  return (payload: unknown) => {
    (existing as (value: unknown) => void)(payload);
    next(payload);
  };
}

export function contractAotKeyFromPayload(payload: unknown): string | undefined {
  if (!payload || typeof payload !== 'object') return undefined;
  const value = payload as { key?: unknown; nativeEvent?: { key?: unknown } };
  return typeof value.key === 'string'
    ? value.key
    : typeof value.nativeEvent?.key === 'string' ? value.nativeEvent.key : undefined;
}

export function invokeContractAotEventPlan(
  evaluate: CompiledExpr,
  mode: 0 | 1 | 2,
  scope: Scope,
  locus: ContractErrorLocus,
): (...args: unknown[]) => void {
  return (...args: unknown[]): void => {
    try {
      if (mode === 1) {
        untrack(() => evaluate(scope, VIEW_EVAL));
        return;
      }
      const handler = untrack(() => evaluate(scope, VIEW_EVAL));
      if (typeof handler === 'function') handler(...args);
    } catch (error) {
      decorateContractError(error, locus);
      reportContractRuntimeError(error);
      throw error;
    }
  };
}

function insertNode(parent: HostParent, node: ElementNode, anchor: ElementNode | null): void {
  if (anchor) insertBefore(parent, node, anchor);
  else appendChild(parent, node);
}

function hydrationNodeIdFor(env: MountEnv, structuralId: string): string {
  return contractHydrationNodeId({
    prefix: env.hydrationPrefix,
    structuralId,
    keyChain: env.hydrationKeyChain,
  });
}

function reactiveOptions(
  env: MountEnv,
  structuralId: string | null,
  span: Span,
): ReactiveNodeOptions | undefined {
  if (!isReactiveIntrospectionEnabled()) return undefined;
  const id = structuralId ?? `element:${span.line}:${span.col}`;
  return {
    label: `${env.component.name}.view.${id}.element props`,
    source: {
      component: env.component.name,
      sourcePath: env.component.file.sourcePath,
      region: 'element props',
      span,
    },
  };
}

function visualOrder(props: Record<string, unknown>): number {
  return typeof props.zIndex === 'number' && Number.isFinite(props.zIndex)
    ? props.zIndex
    : 0;
}

function portalOrder(props: Record<string, unknown>): number {
  return typeof props.__exactPortalLevel === 'number' && Number.isFinite(props.__exactPortalLevel)
    ? props.__exactPortalLevel
    : 0;
}

/** Mount the ordinary generated production element subset. Advanced Motion,
 * channel, interaction-behavior, pointer, and collection shapes are rejected
 * by the compiler's eligibility predicate and retain their exhaustive path. */
export function mountContractElementPlan(
  plan: ContractAotElementPlan,
  node: ViewNodeIR,
  children: readonly ViewNodeIR[],
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  mountNodes: ContractMountViewNodes,
): Mounted {
  const [propPlans, eventPlans, dismissPlan, tag, line, col, len, offset] = plan;
  const structuralId = env.ids.get(node) ?? null;
  const lowering = CONTRACT_TAG_LOWERING[
    tag as keyof typeof CONTRACT_TAG_LOWERING
  ] as ContractTagLowering | undefined;
  if (!lowering) throw new Error(`[contract] no host lowering for "${tag}"`);
  const span: Span = { line, col, len, offset };
  const locus = (region: string): ContractErrorLocus => ({
    component: env.component.name,
    sourcePath: env.component.file.sourcePath,
    region,
    span,
  });
  const staticProps: Record<string, unknown> = { ...(lowering.staticProps ?? {}) };
  if (lowering.semanticTag) {
    staticProps.__exactSemanticTag = lowering.semanticTag;
  }
  const staticStyle: Record<string, unknown> = { ...(lowering.staticStyle ?? {}) };
  const staticAttrStyle: Record<string, unknown> = {};
  const dynamicProps: Array<{
    index: number;
    hostProp: string;
    map?: (value: unknown) => unknown;
  }> = [];
  const dynamicStyle: Array<{ index: number; styleProp: string }> = [];
  let stylePlanIndex: number | null = null;
  const propNames = new Set<string>();
  for (let index = 0; index < propPlans.length; index += 2) {
    propNames.add(propNameAt(propPlans, index));
  }

  if (env.isRootView && tag === 'scroll') {
    if (!propNames.has('width')) staticStyle.width = '100%';
    if (!propNames.has('minHeight')) staticStyle.minHeight = 0;
    if (![...propNames].some((name) =>
      ['height', 'minHeight', 'maxHeight', 'flex', 'grow', 'basis'].includes(name))) {
      staticStyle.flex = 1;
    }
  }

  for (let index = 0; index < propPlans.length; index += 2) {
    const name = propNameAt(propPlans, index);
    const valueOrEvaluate = propValueAt(propPlans, index);
    const dynamic = typeof valueOrEvaluate === 'function';
    if (name === 'style') {
      if (!dynamic) applyStyleObject(staticStyle, readPlanValue(propPlans, index, env.scope));
      else stylePlanIndex = index;
      continue;
    }
    const styleProp = (CONTRACT_STYLE_PROP_MAP as Record<string, string>)[name]
      ?? (CONTRACT_TEXT_BEARING_TAG_SET.has(tag)
        ? (CONTRACT_TEXT_STYLE_PROP_MAP as Record<string, string>)[name]
        : undefined);
    if (styleProp) {
      if (!dynamic) {
        applyStyleValue(
          staticAttrStyle,
          styleProp,
          transformLoweredStyleValue(
            styleProp,
            readPlanValue(propPlans, index, env.scope),
          ),
        );
      } else {
        dynamicStyle.push({ index, styleProp });
      }
      continue;
    }
    const overlay = lowerOverlayProp(name);
    const hostProp = overlay?.hostProp
      ?? (CONTRACT_PROP_RENAMES as Record<string, string>)[name]
      ?? name;
    const map = overlay?.map
      ?? (tag === 'image' && name === 'loading'
        ? (value: unknown) => lowerImageLoading(
            value,
            env.inRepetitionScope,
            env.repetitionIndex,
          )
        : name === 'headingLevel' ? mapHeadingLevelValue : undefined);
    if (!dynamic) {
      const value = readPlanValue(propPlans, index, env.scope);
      staticProps[hostProp] = map ? map(value) : value;
    } else {
      dynamicProps.push({ index, hostProp, map });
    }
  }

  if (tag === 'image' && !propNames.has('loading') && env.inRepetitionScope) {
    staticProps.loading = lowerImageLoading(undefined, true, env.repetitionIndex);
  }
  if (tag === 'text' && propNames.has('headingLevel') &&
      !propNames.has('role') && !propNames.has('accessibilityRole')) {
    staticProps.accessibilityRole = 'heading';
  }

  const eventProps: Record<string, unknown> = {};
  const hydrationHandlers: Array<{
    readonly event: string;
    readonly actionId: string;
  }> = [];
  for (let index = 0; index < eventPlans.length; index += 4) {
    const event = eventPlans[index] as string;
    const evaluate = eventPlans[index + 1] as CompiledExpr;
    const mode = eventPlans[index + 2] as 0 | 1 | 2;
    const action = eventPlans[index + 3] as string | null;
    const hostEvent = lowerEventName(event, tag);
    if (!hostEvent) continue;
    const invoke = invokeContractAotEventPlan(
      evaluate,
      mode,
      env.scope,
      locus(`event "${event}"`),
    );
    if (event === 'submit') {
      staticProps.__exactSubmitHandler = true;
      eventProps[hostEvent] = chainEventHandler(eventProps[hostEvent], (payload) => {
        if (!payload || contractAotKeyFromPayload(payload) === 'Enter') {
          invoke(payload);
        }
      });
    } else if (event === 'keydown') {
      staticProps.__exactKeydownObserver = true;
      eventProps[hostEvent] = chainEventHandler(eventProps[hostEvent], (payload) =>
        invoke(contractAotKeyFromPayload(payload) ?? payload));
    } else {
      eventProps[hostEvent] = invoke;
    }
    if (env.ctx.hydration?.capture && structuralId && action) {
      env.ctx.hydration.capture.recordHandler({
        nodeId: hydrationNodeIdFor(env, structuralId),
        structuralId,
        event: event as ContractHydrationEvent,
        actionId: action,
      });
    }
    if (action) hydrationHandlers.push({ event, actionId: action });
  }

  let dismissHandle: DismissLayerHandle | null = null;
  const dismissId = dismissPlan
    ? `contract-dismiss:${env.instance.runtimeInstanceId ?? env.component.name}:${structuralId ?? offset}`
    : null;
  const dismissSequence = dismissPlan ? reserveDismissLayerMountSequence() : null;
  if (dismissPlan) {
    staticProps.__exactDismissableLayer = true;
    staticProps.__exactDismissAction = dismissPlan[3] ?? undefined;
    staticProps.__exactKeydownObserver = true;
    const dismiss = invokeContractAotEventPlan(
      dismissPlan[1],
      dismissPlan[2],
      env.scope,
      locus('event "dismiss"'),
    );
    eventProps.onKeyDown = chainEventHandler(eventProps.onKeyDown, (payload) => {
      if (
        (!payload || contractAotKeyFromPayload(payload) === 'Escape') &&
        dismissHandle?.isTopmost()
      ) {
        dismiss(payload);
      }
    });
  }

  const hasDynamic = dynamicProps.length > 0 ||
    dynamicStyle.length > 0 ||
    stylePlanIndex !== null;
  const nodeId = structuralId && env.ctx.hydration?.capture
    ? hydrationNodeIdFor(env, structuralId)
    : undefined;
  if (nodeId && structuralId) {
    staticProps['data-exact-hydration-id'] = nodeId;
    staticProps['data-exact-structural-id'] = structuralId;
    if (env.component.file.sourceVersion) {
      staticProps['data-exact-source-version'] = env.component.file.sourceVersion;
    }
  }
  const decorateDismiss = (props: Record<string, unknown>): Record<string, unknown> => {
    if (!dismissId || dismissSequence === null) return props;
    const modal = props.accessibilityModal === true;
    const nextPortalOrder = portalOrder(props);
    const nextVisualOrder = visualOrder(props);
    dismissHandle?.update({
      modal,
      portalOrder: nextPortalOrder,
      visualOrder: nextVisualOrder,
      triggers: ['escape'],
    });
    return {
      ...props,
      __exactMotionDismissLayerClaim: Object.freeze({
        schemaVersion: 1,
        layerId: dismissId,
        rootId: String(env.ctx.rootId),
        parentId: env.dismissLayerParentId ?? null,
        modal,
        portalOrder: nextPortalOrder,
        visualOrder: nextVisualOrder,
        mountSequence: dismissSequence,
      }),
    };
  };
  let initialProps: Record<string, unknown> = { ...staticProps, ...eventProps };
  if (!hasDynamic && (Object.keys(staticStyle).length || Object.keys(staticAttrStyle).length)) {
    initialProps.style = { ...staticStyle, ...staticAttrStyle };
  }
  initialProps = decorateDismiss(initialProps);
  const element = createInstance(lowering.tag, initialProps);
  if (nodeId && hydrationHandlers.length > 0) {
    (
      element as ElementNode & {
        __exactHydrationHandlers?: readonly {
          readonly event: string;
          readonly actionId: string;
        }[];
      }
    ).__exactHydrationHandlers = Object.freeze(
      hydrationHandlers.map((handler) => Object.freeze({ ...handler })),
    );
  }
  let lastProps = initialProps;

  if (env.ctx.hydration?.capture && structuralId && nodeId) {
    env.ctx.hydration.capture.recordNode({
      host: element,
      nodeId,
      structuralId,
      sourcePath: env.component.file.sourcePath,
      sourceVersion: env.component.file.sourceVersion,
      componentName: env.component.name,
      kind: 'element',
    });
  }
  if (env.ctx.routePayloadCapture && structuralId) {
    registerContractRoutePayloadElementCapture(env.ctx.routePayloadCapture, element, {
      kind: 'element',
      id: hydrationNodeIdFor(env, structuralId),
      ...(env.keyChain.length > 0 ? { key: env.keyChain.slice(1) } : {}),
      tag: tag as ContractRoutePayloadTag,
      provenance: Object.freeze({
        component: env.component.name,
        ...(env.component.file.sourcePath ? { source: env.component.file.sourcePath } : {}),
        span: Object.freeze({ ...span }),
      }),
      readProps: () => {
        const props: Record<string, ReturnType<typeof readContractRoutePayloadExpression>> =
          Object.create(null);
        for (let index = 0; index < propPlans.length; index += 2) {
          const name = propNameAt(propPlans, index);
          const tokenPath = propTokenPathAt(propPlans, index);
          const value = tokenPath === undefined
            ? readPlanValue(propPlans, index, env.scope)
            : Object.freeze({ $token: tokenPath });
          const payloadValue = readContractRoutePayloadExpression(
            { kind: 'string', value: '' },
            () => value,
            env.ctx.routePayloadCapture!,
          );
          if (tag === 'image' && name === 'loading') {
            const lowered = lowerImageLoading(
              payloadValue,
              env.inRepetitionScope,
              env.repetitionIndex,
            );
            if (lowered !== undefined) props[name] = lowered;
          } else {
            props[name] = payloadValue;
          }
        }
        if (tag === 'image' && !propNames.has('loading') && env.inRepetitionScope) {
          const lowered = lowerImageLoading(undefined, true, env.repetitionIndex);
          if (lowered !== undefined) props.loading = lowered;
        }
        return props;
      },
    });
  }

  insertNode(parent, element, anchor() as ElementNode | null);
  if (dismissId && dismissSequence !== null) {
    registerHydrationActivation(env.ctx, () => {
      dismissHandle = registerDismissLayer({
        id: dismissId,
        rootId: String(env.ctx.rootId),
        viewId: element.id,
        ...(env.dismissLayerParentId ? { parentId: env.dismissLayerParentId } : {}),
        modal: lastProps.accessibilityModal === true,
        portalOrder: portalOrder(lastProps),
        visualOrder: visualOrder(lastProps),
        mountSequence: dismissSequence,
        triggers: ['escape'],
      });
    });
  }

  let disposed = false;
  let childMount: Mounted | null = null;
  const dispose = (): void => {
    if (disposed) return;
    disposed = true;
    childMount?.dispose();
    dismissHandle?.dispose();
    removeChild(parent, element);
  };
  getOwner()?.register(dispose);

  if (hasDynamic) {
    ownedEffect(() => runWithContractErrorLocus(locus('element props'), () => {
      const style: Record<string, unknown> = { ...staticStyle };
      if (stylePlanIndex !== null) {
        applyStyleObject(
          style,
          readPlanValue(propPlans, stylePlanIndex, env.scope),
        );
      }
      Object.assign(style, staticAttrStyle);
      for (const entry of dynamicStyle) {
        applyStyleValue(
          style,
          entry.styleProp,
          transformLoweredStyleValue(
            entry.styleProp,
            readPlanValue(propPlans, entry.index, env.scope),
          ),
        );
      }
      const next: Record<string, unknown> = { ...staticProps, ...eventProps, style };
      for (const entry of dynamicProps) {
        const value = readPlanValue(propPlans, entry.index, env.scope);
        next[entry.hostProp] = entry.map ? entry.map(value) : value;
      }
      const decorated = decorateDismiss(next);
      updateInstanceProps(element, lastProps, decorated);
      lastProps = decorated;
    }), reactiveOptions(env, structuralId, span));
  }

  const crossesPortal = propNames.has('portalTarget') || propNames.has('portalLevel') ||
    propNames.has('portalPresentation');
  childMount = mountNodes(
    children,
    element,
    null,
    contractElementChildMountEnv(env, crossesPortal, dismissId),
  );
  return { hostNodes: () => disposed ? [] : [element], dispose };
}

/**
 * Ordinary descendants already have the exact immutable environment they
 * need. Only the component-root transition, portal reset, or dismiss-layer
 * boundary warrants another projection.
 *
 * @ref LLP 0185 §2 — production mounts retain compiled context, not a fresh
 * copy of unchanged context for every nested host container.
 */
export function contractElementChildMountEnv(
  env: MountEnv,
  crossesPortal: boolean,
  dismissId: string | null,
): MountEnv {
  if (!env.isRootView && !crossesPortal && dismissId === null) return env;
  return {
    ...env,
    isRootView: false,
    inRepetitionScope: crossesPortal ? false : env.inRepetitionScope,
    repetitionIndex: crossesPortal ? null : env.repetitionIndex,
    dismissLayerParentId: dismissId ?? env.dismissLayerParentId,
  };
}
