import type { ContractClockAuthority } from './clock-authority.js';
import type { ContractDeterminismAuthority } from './determinism-host.js';

export type ContractClockAuthorityFactory = (
  determinism: ContractDeterminismAuthority,
  useDefault: boolean,
) => ContractClockAuthority;

let factory: ContractClockAuthorityFactory = () => {
  throw new Error(
    '[contract] temporal clock authority requires the temporal runtime extension',
  );
};

export function installContractClockAuthorityFactory(
  next: ContractClockAuthorityFactory,
): void {
  factory = next;
}

export function createContractClockAuthority(
  determinism: ContractDeterminismAuthority,
  useDefault: boolean,
): ContractClockAuthority {
  return factory(determinism, useDefault);
}
