// @system @ref LLP 0185 S2/S8, LLP 0373 phase 3c — narrow generated
// virtual-list construction. The compiler admits only the closed ordinary
// collection shape here; reach/refresh/restoration/sortable/pointer variants
// stay on the exhaustive runtime.

import {
  appendChild,
  collectionAgentSemantics,
  createInstance,
  insertBefore,
  removeChild,
  updateInstanceProps,
  type ElementNode,
  type TextNode,
} from '@exact/renderer/host-ops';
import {
  computeVirtualItemsFromPrepared,
  prepareVirtualList,
  type PreparedListState,
  type VirtualListItem,
} from '@exact/list-core';

import type { Span, ViewNodeIR } from '../compiler/ir.js';
import type { CompiledExpr } from './compiled-expr.js';
import {
  runWithContractErrorLocus,
  type ContractErrorLocus,
} from './error-locus-runtime.js';
import {
  contractHydrationNodeId,
  contractHydrationSyntheticStructuralId,
  type ContractHydrationEvent,
} from './hydration.js';
import {
  createOwner,
  getOwner,
  ownedEffect,
  runWithOwner,
  signal,
  untrack,
  type Owner,
} from './signals.js';
import type { Scope } from './interpreter.js';
import { logicalKeySegment } from './view-key-identity.js';
import type { AnchorFn, HostParent, Mounted, MountEnv } from './view.js';
import type { ContractMountViewNodes } from './aot-view-region.js';
import {
  contractAotKeyFromPayload,
  invokeContractAotEventPlan,
  type ContractAotElementEventPlan,
  type ContractAotElementPropPlan,
} from './aot-view-element.js';

const VIEW_EVAL = { identFallbackToString: true } as const;

export type ContractAotCollectionPlan = readonly [
  props: ContractAotElementPropPlan,
  events: ContractAotElementEventPlan,
  line: number,
  col: number,
  len: number,
  offset: number,
];

interface MountedRow {
  key: unknown;
  wrapper: ElementNode;
  owner: Owner;
  setItem(value: unknown): void;
  setIndex(value: number): void;
  updateFrame(frame: VirtualListItem, itemCount: number): void;
}

function read(
  plan: ContractAotElementPropPlan,
  index: number | undefined,
  scope: Scope,
): unknown {
  if (index === undefined) return undefined;
  const encoded = plan[index + 1];
  const value = Array.isArray(encoded) ? encoded[0] : encoded;
  return typeof value === 'function'
    ? (value as CompiledExpr)(scope, VIEW_EVAL)
    : value;
}

function finite(value: unknown, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
}

function geometryFromPayload(
  payload: unknown,
  fallback: { offset: number; viewport: number },
): { offset: number; viewport: number } {
  const envelope = payload && typeof payload === 'object'
    ? payload as Record<string, unknown>
    : {};
  const native = envelope.nativeEvent && typeof envelope.nativeEvent === 'object'
    ? envelope.nativeEvent as Record<string, unknown>
    : envelope;
  const contentOffset = native.contentOffset && typeof native.contentOffset === 'object'
    ? native.contentOffset as Record<string, unknown>
    : {};
  const layout = native.layoutMeasurement && typeof native.layoutMeasurement === 'object'
    ? native.layoutMeasurement as Record<string, unknown>
    : {};
  return {
    offset: finite(native.offset ?? contentOffset.y, fallback.offset),
    viewport: finite(native.viewport ?? layout.height, fallback.viewport),
  };
}

function insert(parent: HostParent, node: ElementNode, anchor: ElementNode | TextNode | null): void {
  if (anchor) insertBefore(parent, node, anchor);
  else appendChild(parent, node);
}

function rowProps(
  key: unknown,
  index: number,
  frame: VirtualListItem,
  itemCount: number,
  accessibilityRole: 'listitem' | 'presentation',
): Record<string, unknown> {
  return {
    rowKey: String(key),
    rowIndex: index,
    accessibilityRole,
    accessibilityPosInSet: index + 1,
    accessibilitySetSize: itemCount,
    style: {
      position: 'absolute',
      top: frame.start,
      left: 0,
      right: 0,
      height: frame.size,
    },
  };
}

export function mountContractCollectionPlan(
  plan: ContractAotCollectionPlan,
  node: ViewNodeIR,
  children: readonly ViewNodeIR[],
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  mountNodes: ContractMountViewNodes,
): Mounted {
  const [plans, eventPlans, line, col, len, offset] = plan;
  const structuralId = env.ids.get(node) ?? null;
  const span: Span = { line, col, len, offset };
  const byName = new Map<string, number>();
  for (let index = 0; index < plans.length; index += 2) {
    byName.set(plans[index] as string, index);
  }
  const itemsPlan = byName.get('items');
  const keyPlan = byName.get('key');
  if (itemsPlan === undefined || keyPlan === undefined) {
    throw new Error('[contract] generated virtualList plan omitted items or key');
  }
  const itemNameValue = read(plans, byName.get('as'), env.scope);
  const indexNameValue = read(plans, byName.get('index'), env.scope);
  const itemName = typeof itemNameValue === 'string' && itemNameValue ? itemNameValue : 'item';
  const indexName = typeof indexNameValue === 'string' && indexNameValue ? indexNameValue : null;
  const estimate = () => finite(
    read(
      plans,
      byName.get('estimateSize') ?? byName.get('estimatedItemSize'),
      env.scope,
    ),
    64,
  );
  const viewport = () =>
    finite(read(plans, byName.get('viewportSize'), env.scope), estimate() * 8);
  const overscan = () => finite(
    read(
      plans,
      byName.get('overscan') ?? byName.get('drawDistance'),
      env.scope,
    ),
    estimate() * 2,
  );
  const listIdValue = read(
    plans,
    byName.get('testId') ?? byName.get('testID'),
    env.scope,
  );
  const listId = typeof listIdValue === 'string' && listIdValue
    ? listIdValue
    : `contract-list:${structuralId ?? 'unknown'}`;
  const roleValue = read(plans, byName.get('role'), env.scope);
  const accessibilityRole = typeof roleValue === 'string' && roleValue
    ? roleValue
    : 'list';
  const labelValue = read(plans, byName.get('label'), env.scope);
  const rowWrapperRole = accessibilityRole === 'listbox'
    ? 'presentation'
    : 'listitem';
  const geometry = signal({ offset: 0, viewport: viewport() });
  const nodeId = structuralId && env.ctx.hydration?.capture
    ? contractHydrationNodeId({
        prefix: env.hydrationPrefix,
        structuralId,
        keyChain: env.hydrationKeyChain,
      })
    : undefined;

  const initialProps: Record<string, unknown> = {
    virtualized: true,
    accessibilityRole,
    ...(labelValue !== undefined ? { accessibilityLabel: labelValue } : {}),
    __exactSemanticTag: 'list',
    scrollEventThrottle: 50,
    ...(byName.has('testId') ? { testId: listIdValue } : {}),
    ...(byName.has('testID') ? { testID: listIdValue } : {}),
  };
  initialProps.onScroll = (payload: unknown) => {
    geometry.set(geometryFromPayload(payload, geometry.get()));
  };
  const hydrationHandlers: Array<{
    readonly event: string;
    readonly actionId: string;
  }> = [];
  for (let index = 0; index < eventPlans.length; index += 4) {
    const event = eventPlans[index] as string;
    const evaluate = eventPlans[index + 1] as CompiledExpr;
    const mode = eventPlans[index + 2] as 0 | 1 | 2;
    const action = eventPlans[index + 3] as string | null;
    if (event !== 'keydown') continue;
    initialProps.__exactKeydownObserver = true;
    const invoke = invokeContractAotEventPlan(
      evaluate,
      mode,
      env.scope,
      {
        component: env.component.name,
        sourcePath: env.component.file.sourcePath,
        region: `event "${event}"`,
        span,
      },
    );
    initialProps.onKeyDown = (payload: unknown) =>
      invoke(contractAotKeyFromPayload(payload) ?? payload);
    if (env.ctx.hydration?.capture && structuralId && nodeId && action) {
      env.ctx.hydration.capture.recordHandler({
        nodeId,
        structuralId,
        event: event as ContractHydrationEvent,
        actionId: action,
      });
    }
    if (action) hydrationHandlers.push({ event, actionId: action });
  }
  if (nodeId && structuralId) {
    initialProps['data-exact-hydration-id'] = nodeId;
    initialProps['data-exact-structural-id'] = structuralId;
    if (env.component.file.sourceVersion) {
      initialProps['data-exact-source-version'] = env.component.file.sourceVersion;
    }
  }
  const element = createInstance('List', initialProps);
  if (nodeId && hydrationHandlers.length > 0) {
    (
      element as ElementNode & {
        __exactHydrationHandlers?: readonly {
          readonly event: string;
          readonly actionId: string;
        }[];
      }
    ).__exactHydrationHandlers = Object.freeze(
      hydrationHandlers.map((handler) => Object.freeze({ ...handler })),
    );
  }
  let lastElementProps = initialProps;
  insert(parent, element, anchor());
  if (nodeId && structuralId && env.ctx.hydration?.capture) {
    env.ctx.hydration.capture.recordNode({
      host: element,
      nodeId,
      structuralId,
      sourcePath: env.component.file.sourcePath,
      sourceVersion: env.component.file.sourceVersion,
      componentName: env.component.name,
      kind: 'element',
    });
  }
  const contentStructuralId = structuralId
    ? contractHydrationSyntheticStructuralId(structuralId, 'virtual-content')
    : null;
  const contentNodeId = contentStructuralId && env.ctx.hydration?.capture
    ? contractHydrationNodeId({
        prefix: env.hydrationPrefix,
        structuralId: contentStructuralId,
        keyChain: env.hydrationKeyChain,
      })
    : undefined;
  const contentHydrationProps: Record<string, unknown> = contentNodeId && contentStructuralId
    ? {
        'data-exact-hydration-id': contentNodeId,
        'data-exact-structural-id': contentStructuralId,
        ...(env.component.file.sourceVersion
          ? { 'data-exact-source-version': env.component.file.sourceVersion }
          : {}),
      }
    : {};
  let contentProps: Record<string, unknown> = {
    ...contentHydrationProps,
    // @ref LLP 0088#host-mapping — generated geometry must remain
    // accessibility-transparent between the collection and its rows.
    accessibilityRole: 'presentation',
    style: { position: 'relative', height: 0 },
  };
  const content = createInstance('View', contentProps);
  appendChild(element, content);
  if (contentNodeId && contentStructuralId && env.ctx.hydration?.capture) {
    env.ctx.hydration.capture.recordNode({
      host: content,
      nodeId: contentNodeId,
      structuralId: contentStructuralId,
      sourcePath: env.component.file.sourcePath,
      sourceVersion: env.component.file.sourceVersion,
      componentName: env.component.name,
      kind: 'element',
    });
  }

  let rows: MountedRow[] = [];
  let prepared: { items: readonly unknown[]; estimate: number; value: PreparedListState } | null = null;
  let disposed = false;
  let warnedDuplicateKeys = false;
  const locus: ContractErrorLocus = {
    component: env.component.name,
    sourcePath: env.component.file.sourcePath,
    region: 'virtualList items',
    span,
  };

  const keyFor = (item: unknown, index: number): unknown => {
    const scope = env.scope.child();
    scope.defineValue(itemName, item);
    if (indexName) scope.defineValue(indexName, index);
    const encoded = plans[keyPlan + 1];
    const evaluate = (Array.isArray(encoded) ? encoded[0] : encoded) as CompiledExpr;
    return evaluate(scope, VIEW_EVAL);
  };
  const createRow = (
    item: unknown,
    index: number,
    key: unknown,
    frame: VirtualListItem,
    itemCount: number,
  ): MountedRow => {
    const owner = createOwner();
    const rowStructuralId = structuralId
      ? contractHydrationSyntheticStructuralId(structuralId, 'collection-row')
      : null;
    const rowHydrationKeyChain = `${env.hydrationKeyChain}#${String(key)}`;
    const rowNodeId = rowStructuralId && env.ctx.hydration?.capture
      ? contractHydrationNodeId({
          prefix: env.hydrationPrefix,
          structuralId: rowStructuralId,
          keyChain: rowHydrationKeyChain,
        })
      : undefined;
    const rowHydrationProps: Record<string, unknown> = rowNodeId && rowStructuralId
      ? {
          'data-exact-hydration-id': rowNodeId,
          'data-exact-structural-id': rowStructuralId,
          ...(env.component.file.sourceVersion
            ? { 'data-exact-source-version': env.component.file.sourceVersion }
            : {}),
        }
      : {};
    const initial = {
      ...rowProps(key, index, frame, itemCount, rowWrapperRole),
      ...rowHydrationProps,
    };
    const wrapper = createInstance('View', initial);
    let last = initial;
    insert(content, wrapper, null);
    if (rowNodeId && rowStructuralId && env.ctx.hydration?.capture) {
      env.ctx.hydration.capture.recordNode({
        host: wrapper,
        nodeId: rowNodeId,
        structuralId: rowStructuralId,
        sourcePath: env.component.file.sourcePath,
        sourceVersion: env.component.file.sourceVersion,
        componentName: env.component.name,
        kind: 'element',
      });
    }
    owner.register(() => removeChild(content, wrapper));
    try {
      return runWithOwner(owner, () => {
        const itemSignal = signal(item);
        const indexSignal = signal(index);
        const scope = env.scope.child();
        scope.define(itemName, { kind: 'getter', get: () => itemSignal.get() });
        if (indexName) {
          scope.define(indexName, { kind: 'getter', get: () => indexSignal.get() });
        }
        const mounted = mountNodes(children, wrapper, null, {
          ...env,
          scope,
          isRootView: false,
          inRepetitionScope: true,
          repetitionIndex: index,
          keyChain: `${env.keyChain}#${String(key)}`,
          logicalKeyPath: [...env.logicalKeyPath, logicalKeySegment(key)],
          hydrationKeyChain: `${env.hydrationKeyChain}#${String(key)}`,
        });
        owner.register(mounted.dispose);
        return {
          key,
          wrapper,
          owner,
          setItem: (value: unknown) => itemSignal.set(value),
          setIndex: (value: number) => indexSignal.set(value),
          updateFrame(nextFrame: VirtualListItem, nextCount: number) {
            const next = {
              ...rowProps(key, indexSignal.get(), nextFrame, nextCount, rowWrapperRole),
              ...rowHydrationProps,
            };
            updateInstanceProps(wrapper, last, next);
            last = next;
          },
        };
      });
    } catch (error) {
      owner.dispose();
      throw error;
    }
  };

  ownedEffect(() => runWithContractErrorLocus(locus, () => {
    const raw = read(plans, itemsPlan, env.scope);
    const allItems = Array.isArray(raw) ? raw : [];
    const itemEstimate = estimate();
    if (!prepared || prepared.items !== allItems || prepared.estimate !== itemEstimate) {
      const keys = allItems.map((item, index) => String(keyFor(item, index)));
      prepared = {
        items: allItems,
        estimate: itemEstimate,
        value: prepareVirtualList({
          count: allItems.length,
          estimatedItemSize: itemEstimate,
          getKey: (index) => keys[index] ?? String(index),
        }),
      };
    }
    const geometryValue = geometry.get();
    const output = computeVirtualItemsFromPrepared(prepared.value, {
      scrollOffset: geometryValue.offset,
      viewportSize: geometryValue.viewport > 0 ? geometryValue.viewport : viewport(),
      drawDistance: overscan(),
    });
    untrack(() => {
      if (disposed) return;
      const nextContent = {
        ...contentHydrationProps,
        style: { position: 'relative', height: output.totalSize },
      };
      updateInstanceProps(content, contentProps, nextContent);
      contentProps = nextContent;
      const nextElement = {
        ...lastElementProps,
        itemCount: output.diagnostics.itemCount,
        mountedItemCount: output.diagnostics.mountedItemCount,
        visibleStartIndex: output.diagnostics.visibleStartIndex,
        visibleEndIndex: output.diagnostics.visibleEndIndex,
        overscanStartIndex: output.diagnostics.overscanStartIndex,
        overscanEndIndex: output.diagnostics.overscanEndIndex,
        totalSize: output.totalSize,
        agentSemantics: collectionAgentSemantics({
          logicalItemCount: output.diagnostics.itemCount,
          mountedItemCount: output.diagnostics.mountedItemCount,
          virtualized: true,
          nativeHost: false,
        }),
      };
      updateInstanceProps(element, lastElementProps, nextElement);
      lastElementProps = nextElement;

      const oldByKey = new Map<unknown, MountedRow[]>();
      rows.forEach((row) => {
        const queue = oldByKey.get(row.key);
        if (queue) queue.push(row);
        else oldByKey.set(row.key, [row]);
      });
      const nextRows: MountedRow[] = [];
      const created: MountedRow[] = [];
      const seen = new Set<unknown>();
      let orderChanged = output.items.length !== rows.length;
      try {
        output.items.forEach((frame) => {
          const item = allItems[frame.index];
          const key = frame.key;
          if (seen.has(key) && !warnedDuplicateKeys) {
            warnedDuplicateKeys = true;
            console.warn(`[contract] duplicate virtualList key ${String(key)}; rows need unique keys`);
          }
          seen.add(key);
          const queue = oldByKey.get(key);
          const existing = queue?.shift();
          if (existing) {
            if (queue!.length === 0) oldByKey.delete(key);
            existing.setItem(item);
            existing.setIndex(frame.index);
            existing.updateFrame(frame, output.diagnostics.itemCount);
            orderChanged ||= existing !== rows[nextRows.length];
            nextRows.push(existing);
          } else {
            const row = createRow(item, frame.index, key, frame, output.diagnostics.itemCount);
            created.push(row);
            nextRows.push(row);
            orderChanged = true;
          }
        });
      } catch (error) {
        created.forEach((row) => row.owner.dispose());
        throw error;
      }
      oldByKey.forEach((queue) => queue.forEach((row) => row.owner.dispose()));
      rows = nextRows;
      if (orderChanged) {
        let nextAnchor: ElementNode | null = null;
        for (let index = rows.length - 1; index >= 0; index -= 1) {
          const row = rows[index]!;
          if (nextAnchor) insertBefore(content, row.wrapper, nextAnchor);
          else appendChild(content, row.wrapper);
          nextAnchor = row.wrapper;
        }
      }
    });
  }));

  const dispose = (): void => {
    if (disposed) return;
    disposed = true;
    rows.forEach((row) => row.owner.dispose());
    rows = [];
    removeChild(element, content);
    removeChild(parent, element);
  };
  getOwner()?.register(dispose);
  return { hostNodes: () => disposed ? [] : [element], dispose };
}
