// @system @ref LLP 0342 §§2-5 / LLP 0341 §3 — explicit app-runtime ownership
// for effects, determinism, roots, tracked microtasks, and quiescence.

import {
  EffectSupervisor,
  type EffectJournalRecord,
  type EffectJournalSink,
  type EffectPressureSnapshot,
  type EffectSupervisorOptions,
} from './effect-supervisor.js';
import {
  createContractEffectEvidenceBinding,
  type ContractEffectEvidenceBroker,
} from './effect-evidence-runtime.js';
import {
  ContractDeterminismAuthority,
  getDefaultContractDeterminismAuthority,
} from './determinism-host.js';
import {
  contractQuiescenceSnapshot,
  quiesceContractRuntime,
  type ContractQuiescenceRuntimeInput,
  type ContractRuntimeQuiescenceParticipant,
  type QuiescenceResultV1,
  type QuiescenceSnapshotV1,
} from './quiescence-runtime.js';
import {
  createContractClockAuthority,
} from './clock-authority-runtime.js';
import type { ContractClockAuthority } from './clock-authority.js';
import {
  acquireContractReplayCaptureLease,
  assertContractReplayCaptureLease,
  captureContractReplayValue,
  disposeContractReplayRuntime,
  notifyContractReplayCaptureProcessDeath,
  recordContractReplayEvent,
  registerContractReplayModule,
  releaseContractReplayCaptureLease,
  renewContractReplayCaptureLease,
  setContractReplayObserver,
  type ContractRuntimeReplayEvent,
  type ContractRuntimeReplayObserver,
  type ReplayCaptureRevocationReason,
} from './contract-replay-runtime.js';

export type {
  ContractRuntimeReplayEvent,
  ContractRuntimeReplayObserver,
  ReplayCaptureRevocationReason,
} from './contract-replay-runtime.js';
export type {
  ContractRuntimeQuiescenceParticipant,
  NonQuiescentFailureV1,
  QuiescenceResultV1,
  QuiescenceSnapshotV1,
} from './quiescence-runtime.js';

export interface ContractRuntimeOptions {
  id?: string;
  determinism?: ContractDeterminismAuthority;
  clockAuthority?: ContractClockAuthority;
  /** The default runtime shares the legacy authority; explicit runtimes isolate. */
  useDefaultDeterminismAuthority?: boolean;
  monotonicNow?: () => number;
  supervisor?: Omit<EffectSupervisorOptions, 'runtimeId' | 'scheduleMicrotask'>;
}

export interface ContractRuntimeRootRegistration {
  id: string;
  rootId: number;
  scope: import('./effect-supervisor.js').EffectScope;
  /** Publish a prepared root to runtime-wide capture/quiescence observers. */
  publish(): void;
  setCaptureReset(reset: () => void): void;
  resetForCapture(): void;
  close(): void;
}

let nextRuntimeId = 1;
let nextRootRegistrationId = 1;
let effectsLifecycleGeneration = 0;

const runtimeRegistry = new Set<ContractRuntime>();

function advanceEffectsLifecycleGeneration(): void {
  effectsLifecycleGeneration = Math.min(
    Number.MAX_SAFE_INTEGER,
    effectsLifecycleGeneration + 1,
  );
}

class RuntimeJournalFanout implements EffectJournalSink {
  readonly listeners = new Set<(record: EffectJournalRecord) => void>();

  record(entry: EffectJournalRecord): void {
    for (const listener of [...this.listeners]) {
      try {
        listener(entry);
      } catch {
        // Journal observers are diagnostics/capture consumers, never part of
        // arbitration. A broken observer may poison its own recording but
        // cannot prevent a supervisor input or terminal completion.
      }
    }
  }
}

export class ContractRuntime {
  readonly id: string;
  readonly determinism: ContractDeterminismAuthority;
  readonly effectSupervisor: EffectSupervisor;
  readonly effectEvidence: ContractEffectEvidenceBroker;
  private readonly journal = new RuntimeJournalFanout();
  private readonly roots = new Map<string, ContractRuntimeRootRegistration>();
  private readonly participants = new Map<string, ContractRuntimeQuiescenceParticipant>();
  private ownedMicrotasks = 0;
  private nextReplayTimer = 1;
  private disposed = false;
  private readonly detachEffectEvidence: () => void;
  private clockAuthorityValue: ContractClockAuthority | null;
  private readonly ownsClockAuthority: boolean;
  private readonly useDefaultClockAuthority: boolean;

  get clockAuthority(): ContractClockAuthority {
    if (!this.clockAuthorityValue) {
      if (this.disposed) {
        throw new Error(`[contract] runtime ${this.id} is disposed`);
      }
      this.clockAuthorityValue = createContractClockAuthority(
        this.determinism,
        this.useDefaultClockAuthority,
      );
    }
    return this.clockAuthorityValue;
  }

  private quiescenceInput(): ContractQuiescenceRuntimeInput {
    return {
      runtimeId: this.id,
      reactiveQueueOwner: this,
      supervisor: this.effectSupervisor,
      determinism: this.determinism,
      ownedMicrotasks: () => this.ownedMicrotasks,
      participants: this.participants,
    };
  }

  constructor(options: ContractRuntimeOptions = {}) {
    if (options.id !== undefined) {
      if (typeof options.id !== 'string' || options.id.trim().length === 0) {
        throw new Error('[contract] runtime id must be a non-empty string');
      }
      if ([...runtimeRegistry].some((runtime) => runtime.id === options.id)) {
        throw new Error(`[contract] duplicate active runtime id ${options.id}`);
      }
      this.id = options.id;
    } else {
      let generatedId: string;
      do {
        generatedId = `contract-runtime-${nextRuntimeId++}`;
      } while ([...runtimeRegistry].some((runtime) => runtime.id === generatedId));
      this.id = generatedId;
    }
    this.determinism = options.determinism ?? (
      options.useDefaultDeterminismAuthority
        ? getDefaultContractDeterminismAuthority()
        : new ContractDeterminismAuthority()
    );
    const usesDefaultClock =
      !options.clockAuthority &&
      options.useDefaultDeterminismAuthority === true &&
      options.determinism === undefined;
    this.useDefaultClockAuthority = usesDefaultClock;
    this.ownsClockAuthority = !options.clockAuthority && !usesDefaultClock;
    this.clockAuthorityValue = options.clockAuthority ?? null;
    if (this.clockAuthorityValue?.determinism !== undefined &&
        this.clockAuthorityValue.determinism !== this.determinism) {
      throw new Error(`[contract] runtime ${this.id} clock/determinism authorities do not match`);
    }
    this.effectSupervisor = new EffectSupervisor({
      runtimeId: this.id,
      ...options.supervisor,
      monotonicNow: options.monotonicNow ?? options.supervisor?.monotonicNow,
      scheduleMicrotask: (work) => this.scheduleMicrotask(work),
      journal: this.journal,
    });
    const effectEvidence = createContractEffectEvidenceBinding({
      supervisor: this.effectSupervisor,
      journal: this.journal,
      runtimeId: this.id,
    });
    this.effectEvidence = effectEvidence.broker;
    this.detachEffectEvidence = effectEvidence.dispose;
    runtimeRegistry.add(this);
    advanceEffectsLifecycleGeneration();
  }

  get isDisposed(): boolean {
    return this.disposed;
  }

  scheduleMicrotask(work: () => void): void {
    if (this.disposed) return;
    this.ownedMicrotasks += 1;
    queueMicrotask(() => {
      try {
        if (!this.disposed) work();
      } finally {
        this.ownedMicrotasks = Math.max(0, this.ownedMicrotasks - 1);
      }
    });
  }

  subscribeEffectJournal(listener: (record: EffectJournalRecord) => void): () => void {
    this.journal.listeners.add(listener);
    return () => this.journal.listeners.delete(listener);
  }

  setReplayObserver(observer: ContractRuntimeReplayObserver | null): () => void {
    return setContractReplayObserver(this, observer);
  }

  acquireReplayCaptureLease(input: {
    owner: object;
    leaseId: string;
    token: string;
    expiresAtMs: number;
    revoke(reason: Exclude<ReplayCaptureRevocationReason, 'released'>): void;
  }): void {
    acquireContractReplayCaptureLease(this, input);
  }

  renewReplayCaptureLease(owner: object, token: string, expiresAtMs: number): void {
    renewContractReplayCaptureLease(this, owner, token, expiresAtMs);
  }

  assertReplayCaptureLease(owner: object, token: string): void {
    assertContractReplayCaptureLease(this, owner, token);
  }

  releaseReplayCaptureLease(owner: object, token: string): void {
    releaseContractReplayCaptureLease(this, owner, token);
  }

  notifyReplayCaptureProcessDeath(): void {
    notifyContractReplayCaptureProcessDeath(this);
  }

  recordReplayEvent(event: ContractRuntimeReplayEvent): void {
    recordContractReplayEvent(this, event);
  }

  registerReplayModule(module: { moduleId: string; sourceVersion: string; irVersion: number }): void {
    registerContractReplayModule(this, module);
  }

  captureReplayValue(value: unknown): unknown {
    return captureContractReplayValue(this, value);
  }

  allocateReplayTimerId(): string {
    return `${this.id}:timer:${this.nextReplayTimer++}`;
  }

  now(): number {
    const value = this.determinism.now();
    this.recordReplayEvent({ kind: 'clock-read', value });
    return value;
  }

  random(siteId = '<uncertified-rng>', logicalInstancePath: readonly string[] = []): number {
    const context = { siteId, logicalInstancePath };
    const value = this.determinism.random(context);
    this.recordReplayEvent({ kind: 'oracle-rng', ...context, value });
    return value;
  }

  registerRoot(
    rootId: number,
    options: { deferPublication?: boolean } = {},
  ): ContractRuntimeRootRegistration {
    if (this.disposed) throw new Error(`[contract] runtime ${this.id} is disposed`);
    const id = `${this.id}:root:${rootId}:${nextRootRegistrationId++}`;
    const rootScope = this.effectSupervisor.createScope({
      id,
      kind: 'root',
      parentId: this.effectSupervisor.runtimeScope.id,
    });
    let captureReset: (() => void) | null = null;
    // @ref LLP 0386 §3.8.1 — a prepared hydration root stays private until
    // the DOM adoption transaction owns the document and commits activation.
    let published = options.deferPublication !== true;
    let closed = false;
    const registration: ContractRuntimeRootRegistration = {
      id,
      rootId,
      scope: rootScope,
      publish: () => {
        if (closed || published) return;
        published = true;
        this.roots.set(id, registration);
      },
      setCaptureReset: (reset) => {
        captureReset = reset;
      },
      resetForCapture: () => {
        if (captureReset) captureReset();
        else registration.close();
      },
      close: () => {
        if (closed) return;
        closed = true;
        if (published) this.roots.delete(id);
        rootScope.close();
      },
    };
    if (published) this.roots.set(id, registration);
    return registration;
  }

  /** @internal Destructive ownership hook used only by replay capture. */
  resetRootsForReplayCapture(): void {
    for (const root of [...this.roots.values()]) root.resetForCapture();
    if (this.roots.size !== 0) {
      throw new Error(`[contract-replay] runtime ${this.id} failed to reset every mounted root`);
    }
  }

  registerQuiescenceParticipant(participant: ContractRuntimeQuiescenceParticipant): () => void {
    if (this.participants.has(participant.id)) {
      throw new Error(`[contract] duplicate quiescence participant ${participant.id}`);
    }
    this.participants.set(participant.id, participant);
    return () => this.participants.delete(participant.id);
  }

  quiescenceSnapshot(iteration = 0, work = 0): QuiescenceSnapshotV1 {
    return contractQuiescenceSnapshot(this.quiescenceInput(), iteration, work);
  }

  /**
   * Runtime-owned fixed-point barrier. Future timers and open effects do not
   * block; only work deliverable at current virtual time participates.
   */
  async quiesce(options: { maxIterations?: number; maxWork?: number } = {}): Promise<QuiescenceResultV1> {
    return quiesceContractRuntime(this.quiescenceInput(), options);
  }

  dispose(): void {
    if (this.disposed) return;
    disposeContractReplayRuntime(this);
    for (const root of [...this.roots.values()]) root.close();
    this.detachEffectEvidence();
    this.effectSupervisor.shutdown();
    if (this.ownsClockAuthority) this.clockAuthorityValue?.dispose();
    this.participants.clear();
    this.journal.listeners.clear();
    this.disposed = true;
    if (runtimeRegistry.delete(this)) advanceEffectsLifecycleGeneration();
  }
}

let defaultRuntime: ContractRuntime | null = null;

export function getDefaultContractRuntime(): ContractRuntime {
  if (!defaultRuntime || defaultRuntime.isDisposed) {
    defaultRuntime = new ContractRuntime({
      id: 'contract-runtime-default',
      useDefaultDeterminismAuthority: true,
    });
  }
  return defaultRuntime;
}

export function createContractRuntime(options: ContractRuntimeOptions = {}): ContractRuntime {
  return new ContractRuntime(options);
}

export interface ContractEffectPressureState {
  /**
   * Monotonic within this producer epoch. Every active-runtime membership
   * discontinuity advances it, so dispose + same-id reuse cannot look like one
   * continuous session row.
   */
  resetGeneration: number;
  snapshots: readonly EffectPressureSnapshot[];
}

export function getContractEffectPressureState(): ContractEffectPressureState {
  return {
    resetGeneration: effectsLifecycleGeneration,
    snapshots: [...runtimeRegistry]
      .filter((runtime) => !runtime.isDisposed)
      .map((runtime) => runtime.effectSupervisor.snapshotPressure())
      .sort((left, right) => left.runtimeId.localeCompare(right.runtimeId)),
  };
}

/**
 * Read-only producer seam consumed by ENG-24438. One snapshot per active
 * app runtime; no diagnostics schema knowledge lives in Contract.
 */
export function getContractEffectPressureSnapshots(): readonly EffectPressureSnapshot[] {
  return getContractEffectPressureState().snapshots;
}

/** Test-only, instance-safe reset: production code should dispose explicitly. */
export function _resetContractRuntimesForTests(): void {
  for (const runtime of [...runtimeRegistry]) runtime.dispose();
  defaultRuntime = null;
  nextRuntimeId = 1;
  nextRootRegistrationId = 1;
}
