// @system @ref LLP 0190, LLP 0373 phase 3c — production error-locus core.
//
// Production keeps authored-coordinate decoration so errors retain their
// innermost Contract locus. Source registries, code-frame formatting, repeat
// deduplication, and browser overlays belong to the full/editable runtime and
// install through the reporter seam below.

import type { Span } from '../compiler/ir.js';

export interface ContractErrorLocus {
  /** Authored file path (ContractFileIR.sourcePath — the Vite module id). */
  sourcePath?: string;
  /** Component the failing code belongs to. */
  component?: string;
  /** Human region description: `derive "stations"`, `action "toggle"`, ... */
  region?: string;
  /** Innermost known authored span. */
  span?: Span;
}

const LOCUS_PROP = '__exactContractLocus';

/**
 * Attach locus fields to a thrown error, filling only missing fields so the
 * innermost (most precise) decoration wins while the error unwinds.
 */
export function decorateContractError(error: unknown, locus: ContractErrorLocus): void {
  if (!(error instanceof Error)) {
    return;
  }
  let existing = (error as Error & { [LOCUS_PROP]?: ContractErrorLocus })[LOCUS_PROP];
  if (!existing) {
    existing = {};
    Object.defineProperty(error, LOCUS_PROP, {
      value: existing,
      enumerable: false,
      writable: true,
      configurable: true,
    });
  }
  if (existing.span === undefined && locus.span !== undefined) existing.span = locus.span;
  if (existing.region === undefined && locus.region !== undefined) existing.region = locus.region;
  if (existing.component === undefined && locus.component !== undefined) existing.component = locus.component;
  if (existing.sourcePath === undefined && locus.sourcePath !== undefined) existing.sourcePath = locus.sourcePath;
}

export function getContractErrorLocus(error: unknown): ContractErrorLocus | null {
  if (!(error instanceof Error)) {
    return null;
  }
  return (error as Error & { [LOCUS_PROP]?: ContractErrorLocus })[LOCUS_PROP] ?? null;
}

export function runWithContractErrorLocus<T>(locus: ContractErrorLocus, fn: () => T): T {
  try {
    return fn();
  } catch (error) {
    decorateContractError(error, locus);
    throw error;
  }
}

export type ContractErrorReporter = (
  error: unknown,
  fallback?: ContractErrorLocus,
) => void;

let reporter: ContractErrorReporter = () => {};

export function installContractErrorReporter(next: ContractErrorReporter): void {
  reporter = next;
}

export function reportContractRuntimeError(
  error: unknown,
  fallback?: ContractErrorLocus,
): void {
  reporter(error, fallback);
}
