// @system @ref LLP 0185 S2 — straight-line synchronous error boundaries.

import type { ViewNodeIR } from '../compiler/ir.js';
import { createOwner, getOwner, runWithOwner } from './signals.js';
import { mountContractAotViewNodes } from './aot-view-runtime.js';
import type { ContractMountViewNodes } from './aot-view-region.js';
import type { AnchorFn, HostParent, Mounted, MountEnv } from './view.js';

export type ContractAotBoundaryPlan = readonly [
  fallbackBinding: string | null,
  line: number,
  col: number,
  len: number,
  offset: number,
];

export function mountContractBoundary(
  plan: ContractAotBoundaryPlan,
  body: readonly ViewNodeIR[],
  fallbackBody: readonly ViewNodeIR[],
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  mountNodes: ContractMountViewNodes = mountContractAotViewNodes,
): Mounted {
  const [fallbackBinding] = plan;
  let current: {
    mounted: Mounted;
    owner: ReturnType<typeof createOwner>;
  } | null = null;
  let disposed = false;

  const mountFallback = (thrown: unknown): void => {
    if (disposed) return;
    console.warn(
      '[contract] boundary caught render error; rendering fallback',
      thrown,
    );
    const owner = createOwner();
    const fallbackScope = env.scope.child();
    if (fallbackBinding) fallbackScope.defineLocal(fallbackBinding, thrown);
    let mounted: Mounted;
    try {
      mounted = runWithOwner(owner, () => mountNodes(
        fallbackBody,
        parent,
        anchor,
        { ...env, scope: fallbackScope },
      ));
    } catch (error) {
      owner.dispose();
      throw error;
    }
    current = { mounted, owner };
  };

  const owner = createOwner();
  try {
    const mounted = runWithOwner(owner, () =>
      mountNodes(body, parent, anchor, env));
    current = { mounted, owner };
  } catch (thrown) {
    owner.dispose();
    mountFallback(thrown);
  }

  const dispose = (): void => {
    if (disposed) return;
    disposed = true;
    current?.owner.dispose();
    current = null;
  };
  getOwner()?.register(dispose);
  return {
    hostNodes: () => current ? current.mounted.hostNodes() : [],
    dispose,
  };
}
