// @system @ref LLP 0381#23-what-the-investigation-rules-out--and-one-confound-it-does-not
// One fail-closed build/runtime authority for Contract development machinery.
// Production must dominate every mutable runtime hint; an unbundled browser
// with no Vite constants is neither implicitly development nor production.

declare const __EXACT_CONTRACT_PRODUCTION__: boolean;

const importMetaEnv = (
  typeof import.meta.env === 'undefined'
    ? undefined
    : import.meta.env
) as { readonly PROD?: boolean; readonly DEV?: boolean } | undefined;
const IMPORT_META_PRODUCTION =
  importMetaEnv?.PROD === true;
const IMPORT_META_DEVELOPMENT =
  importMetaEnv?.DEV === true;

/** Vite's immutable production-build fact, shared by every runtime gate. */
export const CONTRACT_PRODUCTION =
  typeof __EXACT_CONTRACT_PRODUCTION__ !== 'undefined'
    ? __EXACT_CONTRACT_PRODUCTION__
    : IMPORT_META_PRODUCTION;

const runtimeProcess = globalThis as typeof globalThis & {
  process?: { env?: { NODE_ENV?: string } };
};
// Read the test fallback from the target host at module initialization. A
// general-purpose bundler must not bake the build process's NODE_ENV=test into
// an otherwise production Node/SSR artifact. More importantly, an immutable
// production build never touches the host's lazy `process` builtin: on armed
// native runtimes first access may materialize the compatibility module even
// though the test fallback cannot affect the production result.
const NODE_TEST =
  !CONTRACT_PRODUCTION &&
  runtimeProcess.process?.env?.NODE_ENV === 'test';

/** Immutable build/test admission for development-only runtime machinery. */
export const CONTRACT_DEVELOPMENT =
  !CONTRACT_PRODUCTION && (IMPORT_META_DEVELOPMENT || NODE_TEST);

/**
 * Runtime development override used by direct tests and non-Vite development
 * hosts. A production build can never be re-enabled through `__DEV__`.
 */
export function contractDevelopmentFeaturesEnabled(): boolean {
  if (CONTRACT_PRODUCTION) return false;
  const runtime = globalThis as typeof globalThis & { __DEV__?: boolean };
  return typeof runtime.__DEV__ === 'boolean'
    ? runtime.__DEV__
    : CONTRACT_DEVELOPMENT;
}
