// @system @ref LLP 0395 §4 / LLP 0373 P1 — Rive is a compiler-selected
// production capability. Web hosts import only this inert seam; generated
// modules that author Rive import rive-production, which registers the full
// WebGL2 backend and prop normalizers.

export interface RiveDomProps {
  source?: string;
  config?: string;
  bindings?: string;
  controllerId?: string;
}

export interface RiveDomBackend {
  ensure(el: HTMLElement): void;
  disposeWithin(root: Element): void;
  describeProps(props: Record<string, unknown>): RiveDomProps;
}

let registeredBackend: RiveDomBackend | null = null;

export function registerRiveDomBackend(backend: RiveDomBackend): void {
  registeredBackend = backend;
}

export function ensureRiveDomBackend(el: HTMLElement): void {
  registeredBackend?.ensure(el);
}

export function disposeRiveBackendsWithin(root: Element): void {
  registeredBackend?.disposeWithin(root);
}

export function describeRiveDomProps(
  props: Record<string, unknown>,
): RiveDomProps | undefined {
  return registeredBackend?.describeProps(props);
}
