import {
  normalizeBackdropMaterial,
  type BackdropMaterial,
} from '@exact/core/style/backdrop-material';

interface BackdropMaterialWebSpec {
  readonly blur: number;
  readonly saturation: number;
  readonly tintPercent: number;
}
const BACKDROP_MATERIAL_WEB_SPECS: Readonly<Record<BackdropMaterial, BackdropMaterialWebSpec>> = {
  thin: { blur: 12, saturation: 140, tintPercent: 10 },
  regular: { blur: 20, saturation: 160, tintPercent: 14 },
  thick: { blur: 32, saturation: 180, tintPercent: 20 },
  chrome: { blur: 28, saturation: 190, tintPercent: 24 },
  bar: { blur: 18, saturation: 170, tintPercent: 18 },
  sidebar: { blur: 24, saturation: 150, tintPercent: 16 },
};

export interface BackdropMaterialWebStyle {
  readonly backdropFilter: string;
  readonly WebkitBackdropFilter: string;
  readonly backgroundColor?: string;
}

/**
 * Resolve Exact's semantic backdrop knobs to browser CSS.
 *
 * `Canvas` is a scheme-aware CSS system color, so the tint follows the
 * document's resolved `color-scheme` without a JS media-query fork. An
 * authored backdropBlur remains the emulated radius input; a material used
 * alone receives its token default.
 *
 * LLP 0412 §1 precedence: Liquid Glass wins outright (no second backdrop
 * effect), and an authored background — solid OR gradient-valued — wins
 * over the token's emulated tint (blur/saturation still apply).
 */
export function lowerBackdropMaterialWebStyle(
  style: Readonly<Record<string, unknown>>,
): BackdropMaterialWebStyle | undefined {
  if (style.glassEffect) return undefined;
  const material = normalizeBackdropMaterial(style.backdropMaterial);
  const authoredBlur = typeof style.backdropBlur === 'number' && Number.isFinite(style.backdropBlur)
    ? Math.max(0, style.backdropBlur)
    : undefined;

  if (material === undefined) {
    if (authoredBlur === undefined) return undefined;
    const filter = `blur(${authoredBlur}px)`;
    return { backdropFilter: filter, WebkitBackdropFilter: filter };
  }

  const spec = BACKDROP_MATERIAL_WEB_SPECS[material];
  const radius = authoredBlur !== undefined && authoredBlur > 0 ? authoredBlur : spec.blur;
  const filter = `blur(${radius}px) saturate(${spec.saturation}%)`;
  if (style.backgroundColor !== undefined && style.backgroundColor !== null) {
    return { backdropFilter: filter, WebkitBackdropFilter: filter };
  }
  return {
    backdropFilter: filter,
    WebkitBackdropFilter: filter,
    backgroundColor: `color-mix(in srgb, Canvas ${spec.tintPercent}%, transparent)`,
  };
}
