// @system @ref LLP 0185 S2 — straight-line rated channel publication.

import type { Scope } from './interpreter.js';
import {
  isValueChannelSet,
  type ChannelElementBox,
  type ChannelPublishBudget,
  type PointerSample,
} from './capabilities.js';
import { getOwner, untrack } from './signals.js';
import type { Mounted, MountEnv } from './view.js';

const VIEW_EVAL = { identFallbackToString: true } as const;
type ContractPublishEvaluator = (
  scope: Scope,
  options?: typeof VIEW_EVAL,
) => unknown;

export type ContractAotPublishPlan = readonly [
  channelRoot: ContractPublishEvaluator,
  descriptor: string,
  rate: number | null,
  heartbeat: number | null,
  budget: ChannelPublishBudget | null,
  payload: ContractPublishEvaluator | null,
  payloadSource: string | null,
];

const emptyMounted = (): Mounted => ({ hostNodes: () => [], dispose: () => {} });

export function mountContractPublish(
  plan: ContractAotPublishPlan,
  env: MountEnv,
): Mounted {
  return mountContractPublishInScope(plan, env.scope);
}

/**
 * IR-free production-program entry. Publish semantics need only the compiled
 * evaluator plan and the owning execution scope; keeping this seam separate
 * avoids manufacturing a legacy MountEnv/ComponentInstance in P4.
 */
export function mountContractPublishInScope(
  plan: ContractAotPublishPlan,
  scope: Scope,
): Mounted {
  const [channelRoot, descriptor, rate, heartbeat, budget, payload, payloadSource] = plan;
  const warn = (reason: string): Mounted => {
    console.warn(
      `[contract] publish -> ${descriptor}: ${reason} (LLP 0281 §3.1)`,
    );
    return emptyMounted();
  };

  const handle = untrack(() => channelRoot(scope, VIEW_EVAL));
  const set = isValueChannelSet(handle) ? handle : null;
  if (!set) return warn('the publish target is not a value channel');
  if (typeof set.__attachPublisher !== 'function') {
    return warn('this channel implementation does not support rated publish');
  }

  const descriptorBinding = scope.lookup(descriptor);
  const descriptorValue = descriptorBinding
    ? descriptorBinding.kind === 'value' || descriptorBinding.kind === 'local'
      ? descriptorBinding.value
      : untrack(() => descriptorBinding.get())
    : undefined;
  if (typeof descriptorValue !== 'function') {
    return warn('the publish descriptor did not resolve to a callable');
  }
  if (rate === null || !(rate > 0)) {
    return warn('publish requires a positive literal rate');
  }

  const payloadEvaluator = payload
    ? (bindings: {
        sample: Readonly<PointerSample>;
        element: ChannelElementBox;
      }): unknown => {
        const lane = scope.child();
        lane.defineValue('sample', bindings.sample);
        lane.defineValue('element', bindings.element);
        return untrack(() => payload(lane));
      }
    : undefined;
  const heartbeatHz = heartbeat !== null && heartbeat > 0
    ? heartbeat
    : undefined;
  const disposePublisher = set.__attachPublisher({
    publish: descriptorValue as (args: unknown) => unknown,
    rateHz: rate,
    heartbeatHz,
    descriptor,
    budget: budget ?? undefined,
    payloadEvaluator,
    payloadSource: payloadSource ?? undefined,
  });
  getOwner()?.register(disposePublisher);
  return emptyMounted();
}
