// @system @ref LLP 0185 S2 — straight-line async-resource region construction.

import type {
  ResourceSlotKind,
  Span,
  ViewNodeIR,
} from '../compiler/ir.js';
import type { DataConnection } from './data-provider.js';
import {
  runWithContractErrorLocus,
  type ContractErrorLocus,
} from './error-locus-runtime.js';
import {
  createOwner,
  getOwner,
  isReactiveIntrospectionEnabled,
  ownedEffect,
  runWithOwner,
  signal,
  untrack,
  type ReactiveNodeOptions,
} from './signals.js';
import { mountContractAotViewNodes } from './aot-view-runtime.js';
import type { ContractMountViewNodes } from './aot-view-region.js';
import type { AnchorFn, HostParent, Mounted, MountEnv } from './view.js';

interface ResourceHandle {
  status: 'pending' | 'ready' | 'error' | 'refreshing';
  pending?: boolean;
  loading?: boolean;
  ready?: boolean;
  error: unknown;
  value: unknown;
  connection?: DataConnection;
  refresh?: () => void;
}

interface ContractResourceSlotBody {
  body: readonly ViewNodeIR[];
}

type ContractResourceSlotPlan = readonly [
  kind: ResourceSlotKind,
  binding: string | null,
];

export type ContractAotResourcePlan = readonly [
  regionKind: 'resource' | 'async',
  name: string,
  slots: readonly ContractResourceSlotPlan[],
  line: number,
  col: number,
  len: number,
  offset: number,
];

function isResourceHandle(value: unknown): value is ResourceHandle {
  return typeof value === 'object' && value !== null &&
    'status' in value && 'value' in value && 'error' in value;
}

function isEmptyResourceValue(value: unknown): boolean {
  if (value == null) return true;
  if (typeof value === 'object' || typeof value === 'string') {
    const length = (value as { length?: unknown }).length;
    return typeof length === 'number' && length === 0;
  }
  return false;
}

export function mountContractResource(
  plan: ContractAotResourcePlan,
  node: ViewNodeIR,
  slotBodies: readonly ContractResourceSlotBody[],
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  mountNodes: ContractMountViewNodes = mountContractAotViewNodes,
): Mounted {
  const [regionKind, name, slotPlans, line, col, len, offset] = plan;
  const structuralId = env.ids.get(node) ?? null;
  const span: Span = { line, col, len, offset };
  if (slotPlans.length !== slotBodies.length) {
    throw new Error(
      `[contract] compiled ${regionKind} region has ${slotPlans.length} slot plans for ${slotBodies.length} bodies`,
    );
  }

  let current: {
    mounted: Mounted;
    owner: ReturnType<typeof createOwner>;
    key: string;
    setPayload?: (value: unknown) => void;
  } | null = null;
  let disposed = false;

  const findSlot = (kind: ResourceSlotKind): number =>
    slotPlans.findIndex((slot) => slot[0] === kind);
  const slotFor = (handle: ResourceHandle): number => {
    if (handle.status === 'pending') return findSlot('loading');
    if (handle.status === 'error') return findSlot('error');
    if (handle.status === 'ready' || handle.status === 'refreshing') {
      // LLP 0284 §2.2: connection state dominates data shape.
      if (handle.connection === 'stale' || handle.connection === 'disconnected') {
        const stale = findSlot('stale');
        if (stale >= 0) return stale;
      }
      if (isEmptyResourceValue(handle.value)) {
        const empty = findSlot('empty');
        return empty >= 0 ? empty : findSlot('ready');
      }
      return findSlot('ready');
    }
    return -1;
  };

  const swap = (handle: ResourceHandle): void => {
    if (disposed) return;
    const index = slotFor(handle);
    const slot = index >= 0 ? slotPlans[index] : undefined;
    const body = index >= 0 ? slotBodies[index] : undefined;
    const key = slot ? `${slot[0]}:${slot[1] ?? ''}` : 'none';
    const payload = slot?.[0] === 'error' ? handle.error : handle.value;
    if (current?.key === key) {
      current.setPayload?.(payload);
      return;
    }
    if (!slot || !body) {
      current?.owner.dispose();
      current = null;
      return;
    }

    // Keep-last-good: a replacement must mount successfully before the old
    // branch and its owner are disposed.
    const owner = createOwner();
    const slotScope = env.scope.child();
    let setPayload: ((value: unknown) => void) | undefined;
    if (slot[1]) {
      const payloadSignal = signal<unknown>(payload);
      setPayload = (value: unknown) => payloadSignal.set(value);
      slotScope.define(slot[1], { kind: 'getter', get: () => payloadSignal.get() });
    }
    let mounted: Mounted;
    try {
      mounted = runWithOwner(owner, () => mountNodes(body.body, parent, anchor, {
        ...env,
        scope: slotScope,
      }));
    } catch (error) {
      owner.dispose();
      throw error;
    }
    current?.owner.dispose();
    current = { mounted, owner, key, setPayload };
  };

  const locus: ContractErrorLocus = {
    component: env.component.name,
    sourcePath: env.component.file.sourcePath,
    region: `${regionKind} region "${name}"`,
    span,
  };
  ownedEffect(
    () => runWithContractErrorLocus(locus, () => {
      const binding = env.scope.lookup(name);
      const value = binding
        ? binding.kind === 'value' || binding.kind === 'local'
          ? binding.value
          : binding.get()
        : undefined;
      if (!isResourceHandle(value)) {
        throw new Error(
          `[contract] ${regionKind} region "${name}" did not resolve to an async resource/query handle`,
        );
      }
      void value.status;
      void value.error;
      void value.value;
      void value.connection;
      untrack(() => swap(value));
    }),
    resourceReactiveOptions(env, regionKind, name, structuralId, span),
  );

  const dispose = (): void => {
    if (disposed) return;
    disposed = true;
    current?.owner.dispose();
    current = null;
  };
  getOwner()?.register(dispose);
  return {
    hostNodes: () => current ? current.mounted.hostNodes() : [],
    dispose,
  };
}

function resourceReactiveOptions(
  env: MountEnv,
  regionKind: 'resource' | 'async',
  name: string,
  structuralId: string | null,
  span: Span,
): ReactiveNodeOptions | undefined {
  if (!isReactiveIntrospectionEnabled()) return undefined;
  const id = structuralId ?? `${regionKind}:${span.line}:${span.col}`;
  const region = `${regionKind} region "${name}"`;
  return {
    label: `${env.component.name}.view.${id}.${region}`,
    source: {
      component: env.component.name,
      sourcePath: env.component.file.sourcePath,
      region,
      span,
    },
  };
}
