// @system @ref LLP 0359 M1 — shared web image output-range lowering.

import type { ImageDynamicRange } from './types.js';

export type CssSupports = (property: string, value: string) => boolean;

export interface ImageDynamicRangeCss {
  property: 'dynamic-range-limit';
  value: string;
  vocabulary: 'current' | 'legacy';
}

const CURRENT_VALUES: Readonly<Record<ImageDynamicRange, string>> = {
  standard: 'standard',
  constrained: 'constrained',
  'no-limit': 'no-limit',
};

const LEGACY_VALUES: Readonly<Record<ImageDynamicRange, string>> = {
  standard: 'standard',
  constrained: 'constrained-high',
  'no-limit': 'high',
};

/** Prefer the CSS Color HDR Editor's Draft vocabulary, then the legacy tokens. */
export function lowerImageDynamicRangeCss(
  policy: ImageDynamicRange | undefined,
  supports?: CssSupports,
): ImageDynamicRangeCss | undefined {
  if (policy === undefined) return undefined;
  const current = CURRENT_VALUES[policy];
  if (supports === undefined || supports('dynamic-range-limit', current)) {
    return { property: 'dynamic-range-limit', value: current, vocabulary: 'current' };
  }
  const legacy = LEGACY_VALUES[policy];
  if (supports('dynamic-range-limit', legacy)) {
    return { property: 'dynamic-range-limit', value: legacy, vocabulary: 'legacy' };
  }
  return undefined;
}

export function browserCssSupports(property: string, value: string): boolean {
  return typeof CSS !== 'undefined' && typeof CSS.supports === 'function'
    ? CSS.supports(property, value)
    : false;
}
