// @system @ref LLP 0394 §9 / LLP 0373 P1 — Lottie is a compiler-selected
// production capability. The web hosts import this tiny seam unconditionally;
// generated modules that actually author Lottie import lottie-production,
// which registers the dotlottie backend. This keeps both the backend and its
// lazy dotlottie-web chunk out of non-Lottie bundles.

export interface LottieDomBackend {
  ensure(el: HTMLElement): void;
  disposeWithin(root: Element): void;
  describeProps(props: Record<string, unknown>): {
    source?: string;
    config?: string;
    playerId?: string;
  };
}

let registeredBackend: LottieDomBackend | null = null;

export function registerLottieDomBackend(backend: LottieDomBackend): void {
  registeredBackend = backend;
}

export function ensureLottieDomBackend(el: HTMLElement): void {
  registeredBackend?.ensure(el);
}

export function disposeLottieBackendsWithin(root: Element): void {
  registeredBackend?.disposeWithin(root);
}

export function describeLottieDomProps(
  props: Record<string, unknown>,
): { source?: string; config?: string; playerId?: string } | undefined {
  return registeredBackend?.describeProps(props);
}
